window.APP_DATA.phonics = [
  // 2026-08-02 全面重寫：一律以教育部《國語一字多音審訂表》為準
  // ---- 國小 1-4（p001-p100 前段）----
  {id:"p001",grade:1,word:"行走",target:"行",zhuyin:"ㄒㄧㄥˊ",pinyin:"xíng",wz:"ㄒㄧㄥˊ ㄗㄡˇ",wrong:[{z:"ㄏㄤˊ",p:"háng"},{z:"ㄒㄧㄥˋ",p:"xìng"}],note:"「行走」的「行」讀ㄒㄧㄥˊ；「銀行」「行列」讀ㄏㄤˊ。",deep:"1. 注音比較\n行：ㄒㄧㄥˊ（二聲）＝行走、行為；ㄏㄤˊ（二聲）＝行列、銀行；ㄒㄧㄥˋ（四聲）＝品行、德行\n2. 國字拆解與造字原因\n行：象形字，甲骨文像四通八達的十字路口，本義是道路。人在路上走→「行走」（ㄒㄧㄥˊ）；道路上店鋪成排→「行列、銀行」（ㄏㄤˊ）；一個人走過的路如同他的作為→「品行」（ㄒㄧㄥˋ）。"},
  {id:"p002",grade:1,word:"長大",target:"長",zhuyin:"ㄓㄤˇ",pinyin:"zhǎng",wz:"ㄓㄤˇ ㄉㄚˋ",wrong:[{z:"ㄔㄤˊ",p:"cháng"},{z:"ㄓㄤˋ",p:"zhàng"}],note:"「長大」「長輩」讀ㄓㄤˇ；「長短」讀ㄔㄤˊ。",deep:"1. 注音比較\n長：ㄓㄤˇ（三聲）＝長大、長輩；ㄔㄤˊ（二聲）＝長短、長久；ㄓㄤˋ＝無此音（易與「漲」「帳」混淆）\n2. 國字拆解與造字原因\n長：象形字，像長髮老人拄杖之形。頭髮要時間才留得長→「生長、年長」（ㄓㄤˇ）；長髮下垂形容距離、時間的長度→「長短、長久」（ㄔㄤˊ）。"},
  {id:"p003",grade:1,word:"為什麼",target:"為",zhuyin:"ㄨㄟˋ",pinyin:"wèi",wz:"ㄨㄟˋ ㄕㄣˊ ˙ㄇㄜ",wrong:[{z:"ㄨㄟˊ",p:"wéi"},{z:"ㄨㄟˇ",p:"wěi"}],note:"「為什麼」「因為」讀ㄨㄟˋ；「作為」「成為」讀ㄨㄟˊ。",deep:"1. 注音比較\n為：ㄨㄟˋ（四聲）＝為什麼、因為、為了；ㄨㄟˊ（二聲）＝成為、行為、大有可為；ㄨㄟˇ＝無此音\n2. 國字拆解與造字原因\n為：會意字，甲骨文像一隻手牽著大象幫人做事，本義是做、作為→「行為、成為」（ㄨㄟˊ）；替誰做事、為了什麼目的→「因為、為了」（ㄨㄟˋ）。記法：表「目的、原因」讀四聲，表「做、當」讀二聲。"},
  {id:"p004",grade:1,word:"著急",target:"著",zhuyin:"ㄓㄠ",pinyin:"zhāo",wz:"ㄓㄠ ㄐㄧˊ",wrong:[{z:"ㄓㄠˊ",p:"zháo"},{z:"ㄓㄜ",p:"zhē"}],note:"教育部審訂音「著急」的「著」讀ㄓㄠ（一聲）；「睡著」「找著」才讀ㄓㄠˊ。",deep:"1. 注音比較\n著：ㄓㄠ＝著急、著慌、著涼、著風；ㄓㄠˊ＝睡著、找著；ㄓㄨˋ＝著作、名著、顯著；ㄓㄨㄛˊ＝穿著、著陸、著色、不著邊際；˙ㄓㄜ＝慢著、隨著。★「著急」教育部審訂音讀ㄓㄠ，坊間常念成ㄓㄠˊ，那不是審訂音\n2. 國字拆解與造字原因\n著：從艸、者聲。本義是顯明、寫定→「著作、顯著」（ㄓㄨˋ）；引申為接觸、附上→「著手、著陸」（ㄓㄨㄛˊ）；感受到、達成→「睡著、找著」（ㄓㄠˊ）；心裡慌起來→「著急、著慌」（ㄓㄠ）；虛化成表持續的助詞→「隨著」（輕聲）。一字五音，要靠詞來分。"},
  {id:"p005",grade:1,word:"和氣",target:"和",zhuyin:"ㄏㄜˊ",pinyin:"hé",wz:"ㄏㄜˊ ㄑㄧˋ",wrong:[{z:"ㄏㄨㄛˋ",p:"huò"},{z:"ㄏㄢˋ",p:"hàn"}],note:"「和氣」「和平」讀ㄏㄜˊ；「攪和」讀ㄏㄨㄛˋ。",deep:"1. 注音比較\n和：ㄏㄜˊ（二聲）＝和氣、和平；ㄏㄨㄛˋ（四聲）＝攪和、和藥；ㄏㄢˋ（四聲）＝「我和你」（表「與」的口語音）\n2. 國字拆解與造字原因\n和：形聲字，「口」＋「禾」（聲）。本義是聲音互相應和、和諧，引申為溫和、和平（ㄏㄜˊ）；把東西摻在一起攪拌→「攪和」（ㄏㄨㄛˋ）；當連接詞「與」用時口語讀ㄏㄢˋ。"},
  {id:"p006",grade:1,word:"音樂",target:"樂",zhuyin:"ㄩㄝˋ",pinyin:"yuè",wz:"ㄧㄣ ㄩㄝˋ",wrong:[{z:"ㄌㄜˋ",p:"lè"},{z:"ㄧㄠˋ",p:"yào"}],note:"「音樂」「樂器」讀ㄩㄝˋ；「快樂」讀ㄌㄜˋ。",deep:"1. 注音比較\n樂：ㄩㄝˋ（四聲）＝音樂、樂器；ㄌㄜˋ（四聲）＝快樂、樂觀；ㄧㄠˋ（四聲）＝仁者樂山（喜好，文言）\n2. 國字拆解與造字原因\n樂：象形字，像木架上張著絲弦的樂器，本義是樂器、音樂（ㄩㄝˋ）；音樂使人愉快→「快樂」（ㄌㄜˋ）；心中喜愛→「仁者樂山、智者樂水」（ㄧㄠˋ）。三個讀音是「樂器→快樂→喜好」的意義引申。"},
  {id:"p007",grade:1,word:"好人",target:"好",zhuyin:"ㄏㄠˇ",pinyin:"hǎo",wz:"ㄏㄠˇ ㄖㄣˊ",wrong:[{z:"ㄏㄠˋ",p:"hào"},{z:"ㄏㄡˇ",p:"hǒu"}],note:"「好人」讀ㄏㄠˇ；「好奇」「愛好」讀ㄏㄠˋ。",deep:"1. 注音比較\n好：ㄏㄠˇ（三聲）＝好人、美好；ㄏㄠˋ（四聲）＝好奇、愛好、好學；ㄏㄡˇ＝無此音（是「吼」的讀音）\n2. 國字拆解與造字原因\n好：會意字，「女」＋「子」，母親抱著孩子，是最美善的畫面，本義美好（ㄏㄠˇ）；對美好事物心生喜愛→「愛好、好奇」（ㄏㄠˋ）。記法：當形容詞讀三聲，當動詞「喜愛」讀四聲。"},
  {id:"p008",grade:1,word:"睡覺",target:"覺",zhuyin:"ㄐㄧㄠˋ",pinyin:"jiào",wz:"ㄕㄨㄟˋ ㄐㄧㄠˋ",wrong:[{z:"ㄐㄩㄝˊ",p:"jué"},{z:"ㄐㄧㄠˇ",p:"jiǎo"}],note:"「睡覺」讀ㄐㄧㄠˋ；「感覺」「發覺」讀ㄐㄩㄝˊ。",deep:"1. 注音比較\n覺：ㄐㄧㄠˋ（四聲）＝睡覺、午覺；ㄐㄩㄝˊ（二聲）＝感覺、發覺、覺悟；ㄐㄧㄠˇ＝無此音\n2. 國字拆解與造字原因\n覺：形聲字，「學（省略）」＋「見」，本義是睡醒、醒悟——醒來才「看見」明白→「發覺、覺悟、感覺」（ㄐㄩㄝˊ）；一睡一醒算一次，量詞化→「睡一覺、午覺」（ㄐㄧㄠˋ）。"},
  {id:"p009",grade:1,word:"背書包",target:"背",zhuyin:"ㄅㄟ",pinyin:"bēi",wz:"ㄅㄟ ㄕㄨ ㄅㄠ",wrong:[{z:"ㄅㄟˋ",p:"bèi"},{z:"ㄆㄟ",p:"pēi"}],note:"「背書包」（負載）讀ㄅㄟ；「背書」「背後」讀ㄅㄟˋ。",deep:"1. 注音比較\n背：ㄅㄟ（一聲）＝背書包、背負；ㄅㄟˋ（四聲）＝背後、背書、違背；ㄆㄟ＝無此音（是「胚」的讀音）\n2. 國字拆解與造字原因\n背：形聲字，「月（肉）」＋「北」（聲，甲骨文「北」像兩人背對背）。本義是背部（ㄅㄟˋ）；用背部扛東西的動作→「背書包」（ㄅㄟ）。記法：當名詞或「背誦、違背」讀四聲，當「用背扛」的動作讀一聲。"},
  {id:"p010",grade:1,word:"教書",target:"教",zhuyin:"ㄐㄧㄠ",pinyin:"jiāo",wz:"ㄐㄧㄠ ㄕㄨ",wrong:[{z:"ㄐㄧㄠˋ",p:"jiào"},{z:"ㄑㄧㄠ",p:"qiāo"}],note:"「教書」「教你」讀ㄐㄧㄠ；「教育」「教室」讀ㄐㄧㄠˋ。",deep:"1. 注音比較\n教：ㄐㄧㄠ（一聲）＝教書、教我寫字；ㄐㄧㄠˋ（四聲）＝教育、教室、宗教；ㄑㄧㄠ＝無此音（是「敲」的讀音）\n2. 國字拆解與造字原因\n教：會意字，右邊「攵」是手持教鞭，左邊是孩子在學習，長輩持鞭督導孩子。當動作「傳授」讀ㄐㄧㄠ（教你）；當名詞或制度（教育、宗教、教室）讀ㄐㄧㄠˋ。"},
  {id:"p011",grade:1,word:"數星星",target:"數",zhuyin:"ㄕㄨˇ",pinyin:"shǔ",wz:"ㄕㄨˇ ㄒㄧㄥ ㄒㄧㄥ",wrong:[{z:"ㄕㄨˋ",p:"shù"},{z:"ㄕㄨㄛˋ",p:"shuò"}],note:"「數星星」（計算）讀ㄕㄨˇ；「數字」讀ㄕㄨˋ。",deep:"1. 注音比較\n數：ㄕㄨˇ（三聲）＝數星星、數不清；ㄕㄨˋ（四聲）＝數字、數學；ㄕㄨㄛˋ（四聲）＝數見不鮮（屢次，文言）\n2. 國字拆解與造字原因\n數：形聲字，「攵」＋「婁」（聲）。本義是一個一個計算→「數星星」（ㄕㄨˇ）；計算出來的結果是數目→「數字、數學」（ㄕㄨˋ）；一次又一次、頻繁→「數見不鮮」（ㄕㄨㄛˋ）。"},
  {id:"p012",grade:2,word:"種子",target:"種",zhuyin:"ㄓㄨㄥˇ",pinyin:"zhǒng",wz:"ㄓㄨㄥˇ ㄗˇ",wrong:[{z:"ㄓㄨㄥˋ",p:"zhòng"},{z:"ㄔㄨㄥˊ",p:"chóng"}],note:"「種子」「種類」讀ㄓㄨㄥˇ；「種樹」「種植」讀ㄓㄨㄥˋ。",deep:"1. 注音比較\n種：ㄓㄨㄥˇ（三聲）＝種子、種類；ㄓㄨㄥˋ（四聲）＝種樹、種植；ㄔㄨㄥˊ＝無此音（是「蟲」的讀音）\n2. 國字拆解與造字原因\n種：形聲字，「禾」＋「重」（聲）。本義是穀物的種子（名詞，ㄓㄨㄥˇ），引申為類別；把種子埋進土裡的動作（動詞）讀ㄓㄨㄥˋ。記法：名詞三聲、動詞四聲。"},
  {id:"p013",grade:2,word:"勉強",target:"強",zhuyin:"ㄑㄧㄤˇ",pinyin:"qiǎng",wz:"ㄇㄧㄢˇ ㄑㄧㄤˇ",wrong:[{z:"ㄑㄧㄤˊ",p:"qiáng"},{z:"ㄐㄧㄤˋ",p:"jiàng"}],note:"「勉強」「強迫」讀ㄑㄧㄤˇ；「強壯」讀ㄑㄧㄤˊ；「倔強」讀ㄐㄧㄤˋ。",deep:"1. 注音比較\n強：ㄑㄧㄤˇ（三聲）＝勉強、強迫；ㄑㄧㄤˊ（二聲）＝強壯、堅強；ㄐㄧㄤˋ（四聲）＝倔強\n2. 國字拆解與造字原因\n強：形聲字，從「虫」、「弘」聲，本是一種米蟲的名字，後借來表「有力」→「強壯」（ㄑㄧㄤˊ）；用力迫使別人→「勉強、強迫」（ㄑㄧㄤˇ）；個性硬不聽勸→「倔強」（ㄐㄧㄤˋ）。"},
  {id:"p014",grade:2,word:"處理",target:"處",zhuyin:"ㄔㄨˇ",pinyin:"chǔ",wz:"ㄔㄨˇ ㄌㄧˇ",wrong:[{z:"ㄔㄨˋ",p:"chù"},{z:"ㄔㄨˊ",p:"chú"}],note:"「處理」「相處」讀ㄔㄨˇ；「到處」「處所」讀ㄔㄨˋ。",deep:"1. 注音比較\n處：ㄔㄨˇ（三聲）＝處理、相處；ㄔㄨˋ（四聲）＝到處、處所；ㄔㄨˊ＝無此音（是「除」的讀音）\n2. 國字拆解與造字原因\n處：從「虍」（虎）從「処」（人靠几而止），本義是停留、安頓。當動詞「安頓、對待」→「處理、相處」（ㄔㄨˇ）；停留的地方（名詞）→「處所、到處」（ㄔㄨˋ）。記法：動詞三聲、名詞四聲。"},
  {id:"p015",grade:2,word:"便利",target:"便",zhuyin:"ㄅㄧㄢˋ",pinyin:"biàn",wz:"ㄅㄧㄢˋ ㄌㄧˋ",wrong:[{z:"ㄆㄧㄢˊ",p:"pián"},{z:"ㄅㄧㄢˇ",p:"biǎn"}],note:"「便利」「方便」讀ㄅㄧㄢˋ；「便宜」讀ㄆㄧㄢˊ。",deep:"1. 注音比較\n便：ㄅㄧㄢˋ（四聲）＝便利、方便、便當；ㄆㄧㄢˊ（二聲）＝便宜；ㄅㄧㄢˇ＝無此音（是「貶」的讀音）\n2. 國字拆解與造字原因\n便：會意字，「亻」＋「更」（改變），人調整姿勢使自己安適，本義是安適、順利→「方便、便利」（ㄅㄧㄢˋ）；價錢讓人輕鬆負擔→「便宜」（ㄆㄧㄢˊ）。"},
  {id:"p016",grade:2,word:"便宜",target:"便",zhuyin:"ㄆㄧㄢˊ",pinyin:"pián",wz:"ㄆㄧㄢˊ ㄧˊ",wrong:[{z:"ㄅㄧㄢˋ",p:"biàn"},{z:"ㄅㄧㄢ",p:"biān"}],note:"「便宜」讀ㄆㄧㄢˊ；「便當」「順便」讀ㄅㄧㄢˋ。",deep:"1. 注音比較\n便：ㄆㄧㄢˊ（二聲）＝便宜；ㄅㄧㄢˋ（四聲）＝便當、順便、隨便；ㄅㄧㄢ＝無此音（是「邊」的讀音）\n2. 國字拆解與造字原因\n便：「亻」＋「更」，人改變姿勢求安適。表「安適、順利」讀ㄅㄧㄢˋ；只有「便宜」（價格低）一詞讀ㄆㄧㄢˊ，要特別記住。"},
  {id:"p017",grade:2,word:"血液",target:"血",zhuyin:"ㄒㄧㄝˇ",pinyin:"xiě",wz:"ㄒㄧㄝˇ ㄧㄝˋ",wrong:[{z:"ㄒㄩㄝˋ",p:"xuè"},{z:"ㄒㄧㄝˋ",p:"xiè"}],note:"審訂音「血」語音讀ㄒㄧㄝˇ，如「血液」「流血」。",deep:"1. 注音比較\n血：ㄒㄧㄝˇ（三聲）＝血液、流血、血泊（教育部審訂音只收這一個音）；ㄒㄩㄝˋ＝舊讀音，審訂表已統讀ㄒㄧㄝˇ；ㄒㄧㄝˋ＝無此音（是「謝」的讀音）。另外「液」審訂音讀ㄧㄝˋ，所以「血液」讀ㄒㄧㄝˇ ㄧㄝˋ\n2. 國字拆解與造字原因\n血：指事字，「皿」（器皿）上加一點，表示祭祀時滴在器皿中的牲血。教育部審訂音把「血」統一讀ㄒㄧㄝˇ，不再分文白讀音。"},
  {id:"p018",grade:2,word:"塞住",target:"塞",zhuyin:"ㄙㄞ",pinyin:"sāi",wz:"ㄙㄞ ㄓㄨˋ",wrong:[{z:"ㄙㄞˋ",p:"sài"},{z:"ㄙㄜˋ",p:"sè"}],note:"「塞住」「塞車」讀ㄙㄞ；「邊塞」讀ㄙㄞˋ；「閉塞」「阻塞」讀ㄙㄜˋ。",deep:"1. 注音比較\n塞：ㄙㄞ（一聲）＝塞住、塞車；ㄙㄞˋ（四聲）＝邊塞、要塞；ㄙㄜˋ（四聲）＝閉塞、阻塞（文言用法）\n2. 國字拆解與造字原因\n塞：會意兼形聲，「宀」（屋）內用「工」形土塊填堵，下加「土」。本義是填堵→「塞住」（ㄙㄞ）；堵住敵人的邊防要地→「邊塞」（ㄙㄞˋ）；文言的「堵塞不通」→「閉塞、阻塞」（ㄙㄜˋ）。"},
  {id:"p019",grade:2,word:"折斷",target:"折",zhuyin:"ㄓㄜˊ",pinyin:"zhé",wz:"ㄓㄜˊ ㄉㄨㄢˋ",wrong:[{z:"ㄕㄜˊ",p:"shé"},{z:"ㄓㄜ",p:"zhē"}],note:"「折斷」「打折」讀ㄓㄜˊ；「繩子折了」（斷）讀ㄕㄜˊ；「折騰」讀ㄓㄜ。",deep:"1. 注音比較\n折：ㄓㄜˊ（二聲）＝折斷、打折、折紙；ㄕㄜˊ（二聲）＝繩子折了（斷掉）、折本；ㄓㄜ（一聲）＝折騰\n2. 國字拆解與造字原因\n折：會意字，「扌（手）」＋「斤」（斧頭），用手拿斧砍斷東西，本義是弄斷→「折斷」（ㄓㄜˊ）；東西自己斷掉、虧損讀ㄕㄜˊ（繩子折了、折本）；翻來覆去讀ㄓㄜ（折騰）。"},
  {id:"p020",grade:2,word:"降低",target:"降",zhuyin:"ㄐㄧㄤˋ",pinyin:"jiàng",wz:"ㄐㄧㄤˋ ㄉㄧ",wrong:[{z:"ㄒㄧㄤˊ",p:"xiáng"},{z:"ㄍㄤˋ",p:"gàng"}],note:"「降低」「降雨」讀ㄐㄧㄤˋ；「投降」「降服」讀ㄒㄧㄤˊ。",deep:"1. 注音比較\n降：ㄐㄧㄤˋ（四聲）＝降低、降雨、下降；ㄒㄧㄤˊ（二聲）＝投降、降服；ㄍㄤˋ＝無此音\n2. 國字拆解與造字原因\n降：會意字，「阝（阜，土山）」＋「夅」（兩腳向下走），從山上往下走，本義是下來→「下降、降雨」（ㄐㄧㄤˋ）；向敵人低頭屈服→「投降」（ㄒㄧㄤˊ）。"},
  {id:"p021",grade:2,word:"還書",target:"還",zhuyin:"ㄏㄨㄢˊ",pinyin:"huán",wz:"ㄏㄨㄢˊ ㄕㄨ",wrong:[{z:"ㄏㄞˊ",p:"hái"},{z:"ㄒㄩㄢˊ",p:"xuán"}],note:"「還書」「歸還」讀ㄏㄨㄢˊ；「還有」「還沒」讀ㄏㄞˊ。",deep:"1. 注音比較\n還：ㄏㄨㄢˊ（二聲）＝還書、歸還、還原；ㄏㄞˊ（二聲）＝還有、還沒；ㄒㄩㄢˊ＝無此音（是「旋」的讀音）\n2. 國字拆解與造字原因\n還：形聲字，「辶（走）」＋「瞏」（聲），本義是返回→「歸還、還原」（ㄏㄨㄢˊ）；由「返回」虛化成副詞「仍然、尚且」→「還有、還沒」（ㄏㄞˊ）。"},
  {id:"p022",grade:2,word:"倒水",target:"倒",zhuyin:"ㄉㄠˋ",pinyin:"dào",wz:"ㄉㄠˋ ㄕㄨㄟˇ",wrong:[{z:"ㄉㄠˇ",p:"dǎo"},{z:"ㄊㄠˊ",p:"táo"}],note:"「倒水」「倒車」讀ㄉㄠˋ；「跌倒」「倒下」讀ㄉㄠˇ。",deep:"1. 注音比較\n倒：ㄉㄠˋ（四聲）＝倒水、倒車、倒退；ㄉㄠˇ（三聲）＝跌倒、倒下、倒閉；ㄊㄠˊ＝無此音（是「逃」的讀音）\n2. 國字拆解與造字原因\n倒：形聲字，「亻」＋「到」（聲）。人向下傾倒、垮下讀ㄉㄠˇ（跌倒）；上下顛倒、反方向的動作讀ㄉㄠˋ（倒水、倒車）。記法：自己倒下三聲，把東西反過來四聲。"},
  {id:"p023",grade:2,word:"假日",target:"假",zhuyin:"ㄐㄧㄚˋ",pinyin:"jià",wz:"ㄐㄧㄚˋ ㄖˋ",wrong:[{z:"ㄐㄧㄚˇ",p:"jiǎ"},{z:"ㄒㄧㄚˊ",p:"xiá"}],note:"「假日」「放假」讀ㄐㄧㄚˋ；「真假」「假裝」讀ㄐㄧㄚˇ。",deep:"1. 注音比較\n假：ㄐㄧㄚˋ（四聲）＝假日、放假、請假；ㄐㄧㄚˇ（三聲）＝真假、假裝、假如；ㄒㄧㄚˊ＝無此音（是「霞」的讀音）\n2. 國字拆解與造字原因\n假：形聲字，「亻」＋「叚」（聲，借），本義是借→不是真的（借來的）讀ㄐㄧㄚˇ（假裝）；向公家「借」來的休息時間讀ㄐㄧㄚˋ（放假）。"},
  {id:"p024",grade:2,word:"中獎",target:"中",zhuyin:"ㄓㄨㄥˋ",pinyin:"zhòng",wz:"ㄓㄨㄥˋ ㄐㄧㄤˇ",wrong:[{z:"ㄓㄨㄥ",p:"zhōng"},{z:"ㄔㄨㄥ",p:"chōng"}],note:"「中獎」「猜中」讀ㄓㄨㄥˋ；「中間」「中央」讀ㄓㄨㄥ。",deep:"1. 注音比較\n中：ㄓㄨㄥˋ（四聲）＝中獎、猜中、命中；ㄓㄨㄥ（一聲）＝中間、中央；ㄔㄨㄥ＝無此音（是「充」的讀音）\n2. 國字拆解與造字原因\n中：象形字，像旗杆立在範圍的正中央，本義是中央→「中間」（ㄓㄨㄥ）；射箭正好射到中心→「命中、中獎」（ㄓㄨㄥˋ）。記法：位置一聲，打中目標四聲。"},
  {id:"p025",grade:2,word:"重新",target:"重",zhuyin:"ㄔㄨㄥˊ",pinyin:"chóng",wz:"ㄔㄨㄥˊ ㄒㄧㄣ",wrong:[{z:"ㄓㄨㄥˋ",p:"zhòng"},{z:"ㄔㄨㄥ",p:"chōng"}],note:"「重新」「重複」讀ㄔㄨㄥˊ；「重量」「重要」讀ㄓㄨㄥˋ。",deep:"1. 注音比較\n重：ㄔㄨㄥˊ（二聲）＝重新、重複、重疊；ㄓㄨㄥˋ（四聲）＝重量、重要；ㄔㄨㄥ＝無此音（是「充」的讀音）\n2. 國字拆解與造字原因\n重：會意字，像人背著沉重的行囊，本義是分量大→「重量、重要」（ㄓㄨㄥˋ）；一層又一層、再來一次→「重複、重新」（ㄔㄨㄥˊ）。"},
  {id:"p026",grade:3,word:"樂器",target:"樂",zhuyin:"ㄩㄝˋ",pinyin:"yuè",wz:"ㄩㄝˋ ㄑㄧˋ",wrong:[{z:"ㄌㄜˋ",p:"lè"},{z:"ㄌㄠˋ",p:"lào"}],note:"「樂器」「樂團」讀ㄩㄝˋ；「歡樂」讀ㄌㄜˋ。",deep:"1. 注音比較\n樂：ㄩㄝˋ（四聲）＝樂器、樂團、音樂；ㄌㄜˋ（四聲）＝歡樂、快樂；ㄌㄠˋ＝地名用音（如河北樂亭）\n2. 國字拆解與造字原因\n樂：象形字，像木架上張著絲弦的樂器，本義是樂器、音樂（ㄩㄝˋ）；音樂使人愉悅→「快樂」（ㄌㄜˋ）。與樂器音樂有關讀ㄩㄝˋ。"},
  {id:"p027",grade:3,word:"傳達",target:"傳",zhuyin:"ㄔㄨㄢˊ",pinyin:"chuán",wz:"ㄔㄨㄢˊ ㄉㄚˊ",wrong:[{z:"ㄓㄨㄢˋ",p:"zhuàn"},{z:"ㄔㄨㄢˇ",p:"chuǎn"}],note:"「傳達」「流傳」讀ㄔㄨㄢˊ；「傳記」「自傳」讀ㄓㄨㄢˋ。",deep:"1. 注音比較\n傳：ㄔㄨㄢˊ（二聲）＝傳達、流傳、傳球；ㄓㄨㄢˋ（四聲）＝傳記、自傳、水滸傳；ㄔㄨㄢˇ＝無此音（是「喘」的讀音）\n2. 國字拆解與造字原因\n傳：形聲字，「亻」＋「專」（聲），本義是驛站接力遞送文書→輾轉遞送（ㄔㄨㄢˊ，傳達、流傳）；記錄人生平的文字→「傳記」（ㄓㄨㄢˋ）。記法：動詞二聲、書名人物記事四聲。"},
  {id:"p028",grade:3,word:"說服",target:"說",zhuyin:"ㄕㄨㄟˋ",pinyin:"shuì",wz:"ㄕㄨㄟˋ ㄈㄨˊ",wrong:[{z:"ㄕㄨㄛ",p:"shuō"},{z:"ㄩㄝˋ",p:"yuè"}],note:"「說服」「遊說」讀ㄕㄨㄟˋ；「說話」讀ㄕㄨㄛ。",deep:"1. 注音比較\n說：ㄕㄨㄟˋ（四聲）＝說服、遊說；ㄕㄨㄛ（一聲）＝說話、說明；ㄩㄝˋ＝通「悅」（文言，不亦說乎）\n2. 國字拆解與造字原因\n說：形聲字，「言」＋「兌」（聲），本義是解釋、講述（ㄕㄨㄛ）；用言語打動別人聽從自己→「說服、遊說」（ㄕㄨㄟˋ）；古通「悅」（ㄩㄝˋ）。"},
  {id:"p029",grade:3,word:"翹起",target:"翹",zhuyin:"ㄑㄧㄠˋ",pinyin:"qiào",wz:"ㄑㄧㄠˋ ㄑㄧˇ",wrong:[{z:"ㄑㄧㄠˊ",p:"qiáo"},{z:"ㄑㄧㄠˇ",p:"qiǎo"}],note:"「翹起」「翹尾巴」讀ㄑㄧㄠˋ；「翹首」「翹楚」讀ㄑㄧㄠˊ。",deep:"1. 注音比較\n翹：ㄑㄧㄠˋ（四聲）＝翹起、翹尾巴、翹課；ㄑㄧㄠˊ（二聲）＝翹首、翹楚；ㄑㄧㄠˇ＝無此音\n2. 國字拆解與造字原因\n翹：形聲字，「羽」＋「堯」（聲，高），本義是鳥尾上的長羽，鳥尾上揚→「翹起」（ㄑㄧㄠˋ）；抬頭盼望、出眾之才讀ㄑㄧㄠˊ（翹首、翹楚）。"},
  {id:"p030",grade:3,word:"暴露",target:"露",zhuyin:"ㄌㄨˋ",pinyin:"lù",wz:"ㄆㄨˋ ㄌㄨˋ",wrong:[{z:"ㄌㄡˋ",p:"lòu"},{z:"ㄌㄨˊ",p:"lú"}],note:"「暴露」「揭露」讀ㄌㄨˋ；「露臉」「露一手」讀ㄌㄡˋ。",deep:"1. 注音比較\n露：ㄌㄨˋ（四聲）＝暴露、揭露、露水；ㄌㄡˋ（四聲）＝露臉、露一手、露餡（口語）；ㄌㄨˊ＝無此音（是「盧」的讀音）\n2. 國字拆解與造字原因\n露：形聲字，「雨」＋「路」（聲），本義是露水——水氣在外凝結，引申為顯現在外（暴露）。書面語讀ㄌㄨˋ，口語顯現義讀ㄌㄡˋ（露臉、露馬腳）。"},
  {id:"p031",grade:3,word:"骨骼",target:"骼",zhuyin:"ㄍㄜˊ",pinyin:"gé",wz:"ㄍㄨˇ ㄍㄜˊ",wrong:[{z:"ㄍㄜˋ",p:"gè"},{z:"ㄌㄨㄛˋ",p:"luò"}],note:"「骨骼」的「骼」讀ㄍㄜˊ。",deep:"1. 注音比較\n骼：ㄍㄜˊ（二聲）＝骨骼；ㄍㄜˋ＝無此音（是「個」的讀音）；ㄌㄨㄛˋ＝無此音（是「洛」的讀音）\n2. 國字拆解與造字原因\n骼：形聲字，「骨」＋「各」（聲），本義是骨頭，「骨骼」指支撐身體的骨架。從「各」得聲的字有的讀ㄍㄜˊ（骼、格），別受「各」（ㄍㄜˋ）影響誤讀。"},
  {id:"p032",grade:3,word:"地殼",target:"殼",zhuyin:"ㄎㄜˊ",pinyin:"ké",wz:"ㄉㄧˋ ㄎㄜˊ",wrong:[{z:"ㄑㄧㄠˋ",p:"qiào"},{z:"ㄎㄜˇ",p:"kě"}],note:"教育部審訂音「殼」只有一個讀音ㄎㄜˊ：地殼、蛋殼、瓜子殼都讀ㄎㄜˊ。",deep:"1. 注音比較\n殼：ㄎㄜˊ＝地殼、蛋殼、瓜子殼、貝殼、甲殼。★教育部《國語辭典簡編本》「殼」只收ㄎㄜˊ一音，舊書上「地殼」讀ㄑㄧㄠˋ已非現行審訂音\n2. 國字拆解與造字原因\n殼：從「殳」（手持器具敲擊），本義是敲得響的堅硬外皮。地球最外層像蛋殼一樣包住地球，所以叫「地殼」，跟蛋殼、貝殼同一個音。"},
  {id:"p033",grade:3,word:"興趣",target:"興",zhuyin:"ㄒㄧㄥˋ",pinyin:"xìng",wz:"ㄒㄧㄥˋ ㄑㄩˋ",wrong:[{z:"ㄒㄧㄥ",p:"xīng"},{z:"ㄒㄧㄥˇ",p:"xǐng"}],note:"「興趣」「高興」讀ㄒㄧㄥˋ；「興起」「興建」讀ㄒㄧㄥ。",deep:"1. 注音比較\n興：ㄒㄧㄥˋ（四聲）＝興趣、高興、興致；ㄒㄧㄥ（一聲）＝興起、興建、復興；ㄒㄧㄥˇ＝無此音（是「醒」的讀音）\n2. 國字拆解與造字原因\n興：會意字，甲骨文像眾人四手共抬一物，本義是抬起、發動→「興建、興起」（ㄒㄧㄥ）；心情被「抬起來」的愉悅感→「高興、興趣」（ㄒㄧㄥˋ）。記法：動詞一聲、情緒四聲。"},
  {id:"p034",grade:3,word:"答應",target:"應",zhuyin:"ㄧㄥˋ",pinyin:"yìng",wz:"ㄉㄚ ㄧㄥˋ",wrong:[{z:"ㄧㄥ",p:"yīng"},{z:"ㄧㄥˇ",p:"yǐng"}],note:"「答應」「反應」讀ㄧㄥˋ；「應該」「應當」讀ㄧㄥ。",deep:"1. 注音比較\n應：ㄧㄥˋ（四聲）＝答應、反應、應付；ㄧㄥ（一聲）＝應該、應當；ㄧㄥˇ＝無此音（是「影」的讀音）\n2. 國字拆解與造字原因\n應：形聲字，從「心」、「䧹」（聲），本義是心裡回應→「答應、回應」（ㄧㄥˋ）；由「理當回應」引申為「應該」（ㄧㄥ）。記法：回應動作四聲、應該一聲。"},
  {id:"p035",grade:3,word:"乾淨",target:"乾",zhuyin:"ㄍㄢ",pinyin:"gān",wz:"ㄍㄢ ㄐㄧㄥˋ",wrong:[{z:"ㄑㄧㄢˊ",p:"qián"},{z:"ㄍㄢˋ",p:"gàn"}],note:"「乾淨」「乾燥」讀ㄍㄢ；「乾坤」讀ㄑㄧㄢˊ。",deep:"1. 注音比較\n乾：ㄍㄢ（一聲）＝乾淨、乾燥、餅乾；ㄑㄧㄢˊ（二聲）＝乾坤、乾隆；ㄍㄢˋ＝無此音（是「幹」的讀音）\n2. 國字拆解與造字原因\n乾：形聲字，本義是上出的日光，引申為沒有水分→「乾燥」（ㄍㄢ）；《易經》以乾為天→「乾坤」（ㄑㄧㄢˊ）。記法：沒水分讀ㄍㄢ，天地讀ㄑㄧㄢˊ。"},
  {id:"p036",grade:3,word:"差別",target:"差",zhuyin:"ㄔㄚ",pinyin:"chā",wz:"ㄔㄚ ㄅㄧㄝˊ",wrong:[{z:"ㄔㄚˋ",p:"chà"},{z:"ㄔㄞ",p:"chāi"}],note:"「差別」「差異」讀ㄔㄚ；「差勁」讀ㄔㄚˋ；「出差」讀ㄔㄞ。",deep:"1. 注音比較\n差：ㄔㄚ（一聲）＝差別、差異、差距；ㄔㄚˋ（四聲）＝差勁、差不多；ㄔㄞ（一聲）＝出差、差遣；（另有ㄘ，參差）\n2. 國字拆解與造字原因\n差：本義是失當、不相合→兩者不同「差別」（ㄔㄚ）；品質不好「差勁」（ㄔㄚˋ）；被派去辦事「出差」（ㄔㄞ）。一字多音都由「不齊、分派」的本義引申。"},
  {id:"p037",grade:3,word:"倒楣",target:"楣",zhuyin:"ㄇㄟˊ",pinyin:"méi",wz:"ㄉㄠˇ ㄇㄟˊ",wrong:[{z:"ㄇㄟˇ",p:"měi"},{z:"ㄇㄟˋ",p:"mèi"}],note:"「倒楣」的「楣」讀ㄇㄟˊ，本指門框上的橫木。",deep:"1. 注音比較\n楣：ㄇㄟˊ（二聲）＝倒楣、門楣；ㄇㄟˇ＝無此音（是「美」的讀音）；ㄇㄟˋ＝無此音（是「妹」的讀音）\n2. 國字拆解與造字原因\n楣：形聲字，「木」＋「眉」（聲），本義是門框上的橫木（像門的眉毛）。科舉時代家有喜事在門楣掛旗，失利則「倒楣」——放倒旗杆，引申為運氣不好。"},
  {id:"p038",grade:3,word:"蝸牛",target:"蝸",zhuyin:"ㄍㄨㄚ",pinyin:"guā",wz:"ㄍㄨㄚ ㄋㄧㄡˊ",wrong:[{z:"ㄨㄛ",p:"wō"},{z:"ㄍㄨㄛ",p:"guō"}],note:"審訂音「蝸牛」的「蝸」讀ㄍㄨㄚ。",deep:"1. 注音比較\n蝸：ㄍㄨㄚ（一聲）＝蝸牛、蝸居（審訂音）；ㄨㄛ＝舊讀，審訂表不採；ㄍㄨㄛ＝無此音（是「鍋」的讀音）\n2. 國字拆解與造字原因\n蝸：形聲字，「虫」＋「咼」（聲），背著螺旋殼的軟體動物。教育部審訂音定讀ㄍㄨㄚ，注意別跟「窩」（ㄨㄛ）混淆。"},
  {id:"p039",grade:3,word:"挑戰",target:"挑",zhuyin:"ㄊㄧㄠˇ",pinyin:"tiǎo",wz:"ㄊㄧㄠˇ ㄓㄢˋ",wrong:[{z:"ㄊㄧㄠ",p:"tiāo"},{z:"ㄊㄧㄠˋ",p:"tiào"}],note:"「挑戰」「挑釁」讀ㄊㄧㄠˇ；「挑選」「挑水」讀ㄊㄧㄠ。",deep:"1. 注音比較\n挑：ㄊㄧㄠˇ（三聲）＝挑戰、挑釁、挑燈；ㄊㄧㄠ（一聲）＝挑選、挑水；ㄊㄧㄠˋ＝無此音（是「跳」的讀音）\n2. 國字拆解與造字原因\n挑：形聲字，「扌」＋「兆」（聲）。用肩擔、用眼選讀ㄊㄧㄠ（挑水、挑選）；用竿撥動、引動對方讀ㄊㄧㄠˇ（挑燈、挑戰、挑撥）。"},
  {id:"p040",grade:3,word:"漂亮",target:"漂",zhuyin:"ㄆㄧㄠˋ",pinyin:"piào",wz:"ㄆㄧㄠˋ ㄌㄧㄤˋ",wrong:[{z:"ㄆㄧㄠ",p:"piāo"},{z:"ㄆㄧㄠˇ",p:"piǎo"}],note:"「漂亮」讀ㄆㄧㄠˋ；「漂流」讀ㄆㄧㄠ；「漂白」讀ㄆㄧㄠˇ。",deep:"1. 注音比較\n漂：ㄆㄧㄠˋ（四聲）＝漂亮；ㄆㄧㄠ（一聲）＝漂流、漂浮；ㄆㄧㄠˇ（三聲）＝漂白\n2. 國字拆解與造字原因\n漂：形聲字，「氵」＋「票」（聲），本義是浮在水上（ㄆㄧㄠ）；用水沖洗使潔白讀ㄆㄧㄠˇ（漂白）；洗得潔白好看→「漂亮」（ㄆㄧㄠˋ）。三個音是「浮→洗→美」的引申。"},
  {id:"p041",grade:3,word:"曾經",target:"曾",zhuyin:"ㄘㄥˊ",pinyin:"céng",wz:"ㄘㄥˊ ㄐㄧㄥ",wrong:[{z:"ㄗㄥ",p:"zēng"},{z:"ㄘㄥ",p:"cēng"}],note:"「曾經」讀ㄘㄥˊ；「曾祖父」「姓曾」讀ㄗㄥ。",deep:"1. 注音比較\n曾：ㄘㄥˊ（二聲）＝曾經、未曾；ㄗㄥ（一聲）＝曾祖父、姓曾；ㄘㄥ＝無此音\n2. 國字拆解與造字原因\n曾：象形字，像蒸食的炊具（甑的本字）。假借為副詞「曾經」（ㄘㄥˊ）；隔兩代的親屬「曾祖」與姓氏讀ㄗㄥ。"},
  {id:"p042",grade:3,word:"泡沫",target:"沫",zhuyin:"ㄇㄛˋ",pinyin:"mò",wz:"ㄆㄠˋ ㄇㄛˋ",wrong:[{z:"ㄇㄟˋ",p:"mèi"},{z:"ㄇㄚˇ",p:"mǎ"}],note:"「泡沫」的「沫」讀ㄇㄛˋ。",deep:"1. 注音比較\n沫：ㄇㄛˋ（四聲）＝泡沫、口沫；ㄇㄟˋ＝無此音（是「妹」的讀音）；ㄇㄚˇ＝無此音（是「馬」的讀音）\n2. 國字拆解與造字原因\n沫：形聲字，「氵」＋「末」（聲），水的細碎泡泡（末＝細小）。從「末」（ㄇㄛˋ）得聲，別受「妹」影響誤讀。"},
  {id:"p043",grade:4,word:"垃圾",target:"垃",zhuyin:"ㄌㄜˋ",pinyin:"lè",wz:"ㄌㄜˋ ㄙㄜˋ",wrong:[{z:"ㄌㄚ",p:"lā"},{z:"ㄌㄞˋ",p:"lài"}],note:"台灣審訂音「垃圾」讀ㄌㄜˋ ㄙㄜˋ。",deep:"1. 注音比較\n垃：ㄌㄜˋ（四聲）＝垃圾（審訂音ㄌㄜˋ ㄙㄜˋ）；ㄌㄚ＝大陸讀法（lājī），台灣審訂表不採；ㄌㄞˋ＝無此音\n2. 國字拆解與造字原因\n垃：形聲字，「土」＋「立」（聲），髒土穢物堆積。台灣審訂音「垃圾」讀ㄌㄜˋ ㄙㄜˋ，與大陸讀音不同，考試以審訂音為準。"},
  {id:"p044",grade:4,word:"液體",target:"液",zhuyin:"ㄧㄝˋ",pinyin:"yè",wz:"ㄧㄝˋ ㄊㄧˇ",wrong:[{z:"ㄧˋ",p:"yì"},{z:"ㄧㄝˇ",p:"yě"}],note:"教育部審訂音「液」只有一個讀音ㄧㄝˋ：液體、血液、唾液都讀ㄧㄝˋ。",deep:"1. 注音比較\n液：ㄧㄝˋ＝液體、血液、唾液、汁液、溶液。★教育部《國語辭典簡編本》「液」只收ㄧㄝˋ一音，讀成ㄧˋ不是審訂音\n2. 國字拆解與造字原因\n液：形聲字，「氵（水）」＋「夜」（聲），指能流動的水狀物質。從水部，因為凡是會流動的東西都跟水有關。"},
  {id:"p045",grade:4,word:"攜帶",target:"攜",zhuyin:"ㄒㄧ",pinyin:"xī",wz:"ㄒㄧ ㄉㄞˋ",wrong:[{z:"ㄒㄧㄝˊ",p:"xié"},{z:"ㄏㄨㄟˊ",p:"huí"}],note:"審訂音「攜」讀ㄒㄧ，如「攜帶」「攜手」。",deep:"1. 注音比較\n攜：ㄒㄧ（一聲）＝攜帶、攜手（審訂音）；ㄒㄧㄝˊ＝俗讀，審訂表不採；ㄏㄨㄟˊ＝無此音\n2. 國字拆解與造字原因\n攜：形聲字，「扌」＋「巂」（聲），用手提著、帶著→攜帶、提攜。審訂音讀ㄒㄧ，常被誤讀成ㄒㄧㄝˊ。"},
  {id:"p046",grade:4,word:"跌倒",target:"跌",zhuyin:"ㄉㄧㄝˊ",pinyin:"dié",wz:"ㄉㄧㄝˊ ㄉㄠˇ",wrong:[{z:"ㄉㄧㄝ",p:"diē"},{z:"ㄊㄧㄝ",p:"tiē"}],note:"審訂音「跌」讀ㄉㄧㄝˊ，如「跌倒」「下跌」。",deep:"1. 注音比較\n跌：ㄉㄧㄝˊ（二聲）＝跌倒、下跌（審訂音）；ㄉㄧㄝ＝俗讀一聲，審訂表不採；ㄊㄧㄝ＝無此音（是「貼」的讀音）\n2. 國字拆解與造字原因\n跌：形聲字，「足」＋「失」（聲），腳失去平衡而摔倒——「失足」二字合成一個「跌」字，很好記。審訂音讀二聲ㄉㄧㄝˊ。"},
  {id:"p047",grade:4,word:"攻擊",target:"擊",zhuyin:"ㄐㄧˊ",pinyin:"jí",wz:"ㄍㄨㄥ ㄐㄧˊ",wrong:[{z:"ㄐㄧ",p:"jī"},{z:"ㄑㄧˋ",p:"qì"}],note:"審訂音「擊」讀ㄐㄧˊ，如「攻擊」「打擊」。",deep:"1. 注音比較\n擊：ㄐㄧˊ（二聲）＝攻擊、打擊、射擊（審訂音）；ㄐㄧ＝俗讀一聲，審訂表不採；ㄑㄧˋ＝無此音\n2. 國字拆解與造字原因\n擊：從「手」，上為「毄」（車軸相撞），用手敲打、攻打。審訂音讀二聲ㄐㄧˊ，口語常誤讀成一聲。"},
  {id:"p048",grade:4,word:"研究",target:"究",zhuyin:"ㄐㄧㄡˋ",pinyin:"jiù",wz:"ㄧㄢˊ ㄐㄧㄡˋ",wrong:[{z:"ㄐㄧㄡ",p:"jiū"},{z:"ㄐㄧㄡˇ",p:"jiǔ"}],note:"審訂音「究」讀ㄐㄧㄡˋ，如「研究」「終究」。",deep:"1. 注音比較\n究：ㄐㄧㄡˋ（四聲）＝研究、終究、追究（審訂音）；ㄐㄧㄡ＝俗讀一聲，審訂表不採；ㄐㄧㄡˇ＝無此音（是「九」的讀音）\n2. 國字拆解與造字原因\n究：形聲字，「穴」＋「九」（聲），本義是洞穴的盡頭→追查到底（研究、追究）。審訂音讀四聲ㄐㄧㄡˋ。"},
  {id:"p049",grade:4,word:"曝曬",target:"曝",zhuyin:"ㄆㄨˋ",pinyin:"pù",wz:"ㄆㄨˋ ㄕㄞˋ",wrong:[{z:"ㄅㄠˋ",p:"bào"},{z:"ㄆㄠˋ",p:"pào"}],note:"「曝曬」「一曝十寒」讀ㄆㄨˋ；「曝光」亦讀ㄆㄨˋ。",deep:"1. 注音比較\n曝：ㄆㄨˋ（四聲）＝曝曬、曝光、一曝十寒；ㄅㄠˋ＝俗讀，審訂表不採；ㄆㄠˋ＝無此音\n2. 國字拆解與造字原因\n曝：形聲字，「日」＋「暴」（聲），在太陽下曬。「暴」本身就是曬的象形（日下捧米曝曬），加「日」更明確。讀ㄆㄨˋ，「曝光」勿讀成ㄅㄠˋ光。"},
  {id:"p050",grade:4,word:"麻痺",target:"痺",zhuyin:"ㄅㄧˋ",pinyin:"bì",wz:"ㄇㄚˊ ㄅㄧˋ",wrong:[{z:"ㄆㄧˊ",p:"pí"},{z:"ㄅㄟˋ",p:"bèi"}],note:"「麻痺」的「痺」讀ㄅㄧˋ。",deep:"1. 注音比較\n痺：ㄅㄧˋ（四聲）＝麻痺；ㄆㄧˊ＝無此音（是「皮」的讀音）；ㄅㄟˋ＝無此音（是「備」的讀音）\n2. 國字拆解與造字原因\n痺：形聲字，「疒」（疾病）＋「卑」（聲），肢體失去知覺的病症→麻痺。疒字旁表示與疾病有關。"},
  {id:"p051",grade:4,word:"骰子",target:"骰",zhuyin:"ㄊㄡˊ",pinyin:"tóu",wz:"ㄊㄡˊ ˙ㄗ",wrong:[{z:"ㄕㄞˇ",p:"shǎi"},{z:"ㄉㄡˇ",p:"dǒu"}],note:"「骰子」的「骰」讀ㄊㄡˊ，俗讀ㄕㄞˇ非審訂音。",deep:"1. 注音比較\n骰：ㄊㄡˊ（二聲）＝骰子（審訂音）；ㄕㄞˇ＝俗讀（色子），審訂表不採；ㄉㄡˇ＝無此音（是「斗」的讀音）\n2. 國字拆解與造字原因\n骰：形聲字，「骨」＋「投」（省聲），骨頭做的、用來「投」擲的賭具。審訂音讀ㄊㄡˊ，與「投」同音好記。"},
  {id:"p052",grade:4,word:"蛤蜊",target:"蛤",zhuyin:"ㄍㄜˊ",pinyin:"gé",wz:"ㄍㄜˊ ㄌㄧˊ",wrong:[{z:"ㄏㄚˊ",p:"há"},{z:"ㄎㄜˊ",p:"ké"}],note:"「蛤蜊」讀ㄍㄜˊ ㄌㄧˊ；「蛤蟆」讀ㄏㄚˊ。",deep:"1. 注音比較\n蛤：ㄍㄜˊ（二聲）＝蛤蜊；ㄏㄚˊ（二聲）＝蛤蟆；ㄎㄜˊ＝無此音（是「殼」的語讀）\n2. 國字拆解與造字原因\n蛤：形聲字，「虫」＋「合」（聲），雙殼「合」起來的貝類→蛤蜊（ㄍㄜˊ）；「蛤蟆」（青蛙、蟾蜍）讀ㄏㄚˊ。同字兩音指不同動物。"},
  {id:"p053",grade:4,word:"混合",target:"混",zhuyin:"ㄏㄨㄣˋ",pinyin:"hùn",wz:"ㄏㄨㄣˋ ㄏㄜˊ",wrong:[{z:"ㄏㄨㄣˊ",p:"hún"},{z:"ㄎㄨㄣˋ",p:"kùn"}],note:"「混合」「混亂」讀ㄏㄨㄣˋ；「混水摸魚」的「混」亦讀ㄏㄨㄣˋ。",deep:"1. 注音比較\n混：ㄏㄨㄣˋ（四聲）＝混合、混亂、混水摸魚；ㄏㄨㄣˊ（二聲）＝混蛋（口語罵語）；ㄎㄨㄣˋ＝無此音（是「困」的讀音）\n2. 國字拆解與造字原因\n混：形聲字，「氵」＋「昆」（聲），本義是水勢盛大，水流交雜→摻雜（混合）、雜亂（混亂）。標準音讀ㄏㄨㄣˋ。"},
  {id:"p054",grade:4,word:"寧可",target:"寧",zhuyin:"ㄋㄧㄥˊ",pinyin:"níng",wz:"ㄋㄧㄥˊ ㄎㄜˇ",wrong:[{z:"ㄋㄧㄥˋ",p:"nìng"},{z:"ㄋㄧㄥˇ",p:"nǐng"}],note:"審訂音「寧可」「寧願」讀ㄋㄧㄥˊ；「寧死不屈」亦讀ㄋㄧㄥˊ。",deep:"1. 注音比較\n寧：ㄋㄧㄥˊ（二聲）＝寧可、寧願、安寧、寧死不屈（審訂音統讀）；ㄋㄧㄥˋ＝舊讀（寧可），審訂表不採；ㄋㄧㄥˇ＝無此音\n2. 國字拆解與造字原因\n寧：會意字，屋（宀）內有食器（皿），豐衣足食心安定，本義是安定→安寧；「寧可」是「情願求安」的引申。審訂音一律讀ㄋㄧㄥˊ。"},
  {id:"p055",grade:4,word:"率領",target:"率",zhuyin:"ㄕㄨㄞˋ",pinyin:"shuài",wz:"ㄕㄨㄞˋ ㄌㄧㄥˇ",wrong:[{z:"ㄌㄩˋ",p:"lǜ"},{z:"ㄕㄨㄛˋ",p:"shuò"}],note:"「率領」「率先」讀ㄕㄨㄞˋ；「效率」「機率」讀ㄌㄩˋ。",deep:"1. 注音比較\n率：ㄕㄨㄞˋ（四聲）＝率領、率先、坦率；ㄌㄩˋ（四聲）＝效率、機率、比率；ㄕㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n率：象形字，像捕鳥的網，本義是循著、帶領→「率領」（ㄕㄨㄞˋ）；數學上兩數相比的值讀ㄌㄩˋ（比率、效率）。記法：帶頭讀ㄕㄨㄞˋ，數值讀ㄌㄩˋ。"},
  {id:"p056",grade:4,word:"參差",target:"參",zhuyin:"ㄘㄣ",pinyin:"cēn",wz:"ㄘㄣ ㄘ",wrong:[{z:"ㄘㄢ",p:"cān"},{z:"ㄕㄣ",p:"shēn"}],note:"「參差不齊」讀ㄘㄣ ㄘ；「參加」讀ㄘㄢ；「人參」讀ㄕㄣ。",deep:"1. 注音比較\n參：ㄘㄣ（一聲）＝參差不齊；ㄘㄢ（一聲）＝參加、參觀；ㄕㄣ（一聲）＝人參、海參\n2. 國字拆解與造字原因\n參：象形字，像參星（三顆星）在人頭上，本義是星宿名（ㄕㄣ）；三者並列引申為加入其中→「參加」（ㄘㄢ）；長短不齊→「參差」（ㄘㄣ）。一字三音各司其職。"},
  {id:"p057",grade:4,word:"當鋪",target:"當",zhuyin:"ㄉㄤˋ",pinyin:"dàng",wz:"ㄉㄤˋ ㄆㄨˋ",wrong:[{z:"ㄉㄤ",p:"dāng"},{z:"ㄊㄤˊ",p:"táng"}],note:"「當鋪」「典當」「上當」讀ㄉㄤˋ；「當然」「當時」讀ㄉㄤ。",deep:"1. 注音比較\n當：ㄉㄤˋ（四聲）＝當鋪、典當、上當、當作；ㄉㄤ（一聲）＝當然、當時、擔當；ㄊㄤˊ＝無此音（是「堂」的讀音）\n2. 國字拆解與造字原因\n當：形聲字，「田」＋「尚」（聲），本義是兩塊田相抵、相等→面對、承擔讀ㄉㄤ（當面、擔當）；用物品抵押換錢讀ㄉㄤˋ（典當、當鋪）。"},
  {id:"p058",grade:4,word:"分量",target:"量",zhuyin:"ㄌㄧㄤˋ",pinyin:"liàng",wz:"ㄈㄣˋ ㄌㄧㄤˋ",wrong:[{z:"ㄌㄧㄤˊ",p:"liáng"},{z:"ㄌㄧㄤˇ",p:"liǎng"}],note:"「分量」「重量」讀ㄌㄧㄤˋ；「測量」「量身」讀ㄌㄧㄤˊ。",deep:"1. 注音比較\n量：ㄌㄧㄤˋ（四聲）＝分量、重量、力量；ㄌㄧㄤˊ（二聲）＝測量、量身、量體溫；ㄌㄧㄤˇ＝無此音（是「兩」的讀音）\n2. 國字拆解與造字原因\n量：從「重（省）」，上像量器開口，本義是用器具計測（動詞，ㄌㄧㄤˊ）；計測的結果、多寡（名詞）讀ㄌㄧㄤˋ。記法：動詞二聲、名詞四聲。"},
  {id:"p059",grade:4,word:"迷藏",target:"藏",zhuyin:"ㄘㄤˊ",pinyin:"cáng",wz:"ㄇㄧˊ ㄘㄤˊ",wrong:[{z:"ㄗㄤˋ",p:"zàng"},{z:"ㄔㄤˊ",p:"cháng"}],note:"「捉迷藏」「收藏」讀ㄘㄤˊ；「寶藏」「西藏」讀ㄗㄤˋ。",deep:"1. 注音比較\n藏：ㄘㄤˊ（二聲）＝捉迷藏、收藏、躲藏；ㄗㄤˋ（四聲）＝寶藏、西藏、藏族；ㄔㄤˊ＝無此音（是「常」的讀音）\n2. 國字拆解與造字原因\n藏：形聲字，「艹」＋「臧」（聲），草木遮蔽而隱匿→躲藏（ㄘㄤˊ）；收存起來的珍寶、儲藏之所讀ㄗㄤˋ（寶藏）。記法：動作二聲、名詞四聲。"},
  {id:"p060",grade:4,word:"稱職",target:"稱",zhuyin:"ㄔㄥˋ",pinyin:"chèng",wz:"ㄔㄥˋ ㄓˊ",wrong:[{z:"ㄔㄣˋ",p:"chèn"},{z:"ㄔㄥ",p:"chēng"}],note:"教育部審訂音「稱職」的「稱」讀ㄔㄥˋ（相合、合適）；「稱呼」「稱讚」才讀ㄔㄥ。",deep:"1. 注音比較\n稱：ㄔㄥ＝稱呼、名稱、稱讚、稱兄道弟；ㄔㄥˋ＝稱職、稱意、稱願、市稱。★「稱職」教育部審訂音讀ㄔㄥˋ，讀成ㄔㄣˋ不是審訂音\n2. 國字拆解與造字原因\n稱：從禾、爯（舉起）聲，舉起穀物衡量輕重。由「衡量」引申出兩路：叫出名號、讚美→「稱呼、稱讚」（ㄔㄥ）；輕重恰好相合、合乎心意→「稱職、稱心」（ㄔㄥˋ）。"},
  {id:"p061",grade:4,word:"要求",target:"要",zhuyin:"ㄧㄠ",pinyin:"yāo",wz:"ㄧㄠ ㄑㄧㄡˊ",wrong:[{z:"ㄧㄠˋ",p:"yào"},{z:"ㄧㄠˇ",p:"yǎo"}],note:"「要求」「要脅」讀ㄧㄠ；「重要」「需要」讀ㄧㄠˋ。",deep:"1. 注音比較\n要：ㄧㄠ（一聲）＝要求、要脅；ㄧㄠˋ（四聲）＝重要、需要、要不要；ㄧㄠˇ＝無此音（是「咬」的讀音）\n2. 國字拆解與造字原因\n要：象形字，像人雙手叉腰，本義是腰（「腰」的本字）。腰是身體中樞→重要（ㄧㄠˋ）；攔腰截求、強求讀ㄧㄠ（要求、要脅）。"},
  {id:"p062",grade:4,word:"呼喊",target:"喊",zhuyin:"ㄏㄢˇ",pinyin:"hǎn",wz:"ㄏㄨ ㄏㄢˇ",wrong:[{z:"ㄏㄢˋ",p:"hàn"},{z:"ㄎㄢˇ",p:"kǎn"}],note:"「呼喊」的「喊」讀ㄏㄢˇ。",deep:"1. 注音比較\n喊：ㄏㄢˇ（三聲）＝呼喊、喊叫；ㄏㄢˋ＝無此音（是「漢」的讀音）；ㄎㄢˇ＝無此音（是「砍」的讀音）\n2. 國字拆解與造字原因\n喊：形聲字，「口」＋「咸」（聲），大聲呼叫。從「咸」得聲的字有喊（ㄏㄢˇ）、鹹（ㄒㄧㄢˊ）、減（ㄐㄧㄢˇ），聲隨字轉，別誤讀。"},
  {id:"p063",grade:4,word:"膝蓋",target:"膝",zhuyin:"ㄒㄧ",pinyin:"xī",wz:"ㄒㄧ ㄍㄞˋ",wrong:[{z:"ㄑㄧ",p:"qī"},{z:"ㄒㄧˊ",p:"xí"}],note:"「膝蓋」的「膝」讀ㄒㄧ，常被誤讀成ㄑㄧ。",deep:"1. 注音比較\n膝：ㄒㄧ（一聲）＝膝蓋、護膝、促膝長談；ㄑㄧ＝誤讀（受「漆」影響）；ㄒㄧˊ＝無此音（是「習」的讀音）\n2. 國字拆解與造字原因\n膝：形聲字，「月（肉）」＋「桼」（聲），大腿小腿相接的關節。「桼」是「漆」的本字，但「膝」讀ㄒㄧ不讀ㄑㄧ，是常見誤讀字。"},
  {id:"p064",grade:4,word:"符合",target:"符",zhuyin:"ㄈㄨˊ",pinyin:"fú",wz:"ㄈㄨˊ ㄏㄜˊ",wrong:[{z:"ㄈㄨˇ",p:"fǔ"},{z:"ㄈㄨˋ",p:"fù"}],note:"「符合」「符號」讀ㄈㄨˊ。",deep:"1. 注音比較\n符：ㄈㄨˊ（二聲）＝符合、符號、護身符；ㄈㄨˇ＝無此音（是「府」的讀音）；ㄈㄨˋ＝無此音（是「付」的讀音）\n2. 國字拆解與造字原因\n符：形聲字，「竹」＋「付」（聲），古代用竹片做的信物，剖成兩半，相合為證→「符合」（兩半相合）、「符號」（表意的記號）。"},
  {id:"p065",grade:4,word:"氛圍",target:"氛",zhuyin:"ㄈㄣ",pinyin:"fēn",wz:"ㄈㄣ ㄨㄟˊ",wrong:[{z:"ㄈㄣˋ",p:"fèn"},{z:"ㄈㄣˊ",p:"fén"}],note:"「氣氛」「氛圍」的「氛」讀ㄈㄣ，常被誤讀成ㄈㄣˋ。",deep:"1. 注音比較\n氛：ㄈㄣ（一聲）＝氣氛、氛圍（審訂音）；ㄈㄣˋ＝誤讀；ㄈㄣˊ＝無此音（是「墳」的讀音）\n2. 國字拆解與造字原因\n氛：形聲字，「气」＋「分」（聲），瀰漫的雲氣，引申為環境中的情調感覺→氣氛。讀一聲ㄈㄣ，「氣氛」勿讀成「氣ㄈㄣˋ」。"},
  {id:"p066",grade:5,word:"倔強",target:"倔",zhuyin:"ㄐㄩㄝˊ",pinyin:"jué",wz:"ㄐㄩㄝˊ ㄐㄧㄤˋ",wrong:[{z:"ㄐㄩㄝˋ",p:"juè"},{z:"ㄑㄩ",p:"qū"}],note:"「倔強」讀ㄐㄩㄝˊ ㄐㄧㄤˋ。",deep:"1. 注音比較\n倔：ㄐㄩㄝˊ（二聲）＝倔強；ㄐㄩㄝˋ＝誤讀；ㄑㄩ＝無此音（是「屈」的讀音）\n2. 國字拆解與造字原因\n倔：形聲字，「亻」＋「屈」（聲），性情剛硬不肯屈服→「倔強」（ㄐㄩㄝˊ ㄐㄧㄤˋ）。注意「強」在此讀ㄐㄧㄤˋ。"},
  {id:"p067",grade:5,word:"栽贓",target:"贓",zhuyin:"ㄗㄤ",pinyin:"zāng",wz:"ㄗㄞ ㄗㄤ",wrong:[{z:"ㄗㄤˋ",p:"zàng"},{z:"ㄘㄤˊ",p:"cáng"}],note:"「栽贓」「贓物」的「贓」讀ㄗㄤ。",deep:"1. 注音比較\n贓：ㄗㄤ（一聲）＝栽贓、贓物、貪贓枉法；ㄗㄤˋ＝誤讀；ㄘㄤˊ＝無此音（是「藏」的讀音）\n2. 國字拆解與造字原因\n贓：形聲字，「貝」（錢財）＋「臧」（聲），用不正當手段得來的財物→贓款、贓物。讀一聲ㄗㄤ。"},
  {id:"p068",grade:5,word:"松柏",target:"柏",zhuyin:"ㄅㄛˊ",pinyin:"bó",wz:"ㄙㄨㄥ ㄅㄛˊ",wrong:[{z:"ㄅㄞˇ",p:"bǎi"},{z:"ㄆㄛˋ",p:"pò"}],note:"審訂音「松柏」「柏樹」讀ㄅㄛˊ；「柏油」讀ㄅㄞˇ。",deep:"1. 注音比較\n柏：ㄅㄛˊ（二聲）＝松柏、柏樹、柏林（審訂音）；ㄅㄞˇ（三聲）＝柏油；ㄆㄛˋ＝無此音（是「魄」的讀音）\n2. 國字拆解與造字原因\n柏：形聲字，「木」＋「白」（聲），常綠喬木。樹木義審訂音讀ㄅㄛˊ（松柏長青）；外來語音譯「柏油」讀ㄅㄞˇ。"},
  {id:"p069",grade:5,word:"剖析",target:"剖",zhuyin:"ㄆㄡˇ",pinyin:"pǒu",wz:"ㄆㄡˇ ㄒㄧ",wrong:[{z:"ㄆㄛ",p:"pō"},{z:"ㄈㄡˇ",p:"fǒu"}],note:"「剖析」「解剖」的「剖」讀ㄆㄡˇ。",deep:"1. 注音比較\n剖：ㄆㄡˇ（三聲）＝剖析、解剖、剖開；ㄆㄛ＝無此音；ㄈㄡˇ＝無此音（是「否」的讀音）\n2. 國字拆解與造字原因\n剖：形聲字，「刂」（刀）＋「咅」（聲），用刀切開→解剖；把道理切開細看→剖析。讀ㄆㄡˇ。"},
  {id:"p070",grade:5,word:"畸形",target:"畸",zhuyin:"ㄐㄧ",pinyin:"jī",wz:"ㄐㄧ ㄒㄧㄥˊ",wrong:[{z:"ㄑㄧˊ",p:"qí"},{z:"ㄧˋ",p:"yì"}],note:"「畸形」的「畸」讀ㄐㄧ，常被誤讀成ㄑㄧˊ。",deep:"1. 注音比較\n畸：ㄐㄧ（一聲）＝畸形、畸零地；ㄑㄧˊ＝誤讀（受「奇」影響）；ㄧˋ＝無此音\n2. 國字拆解與造字原因\n畸：形聲字，「田」＋「奇」（聲），本義是劃分田地後剩下的不方正零地→不正常、不整齊（畸形）。從「奇」得聲卻讀ㄐㄧ，常考誤讀字。"},
  {id:"p071",grade:5,word:"堤防",target:"堤",zhuyin:"ㄊㄧˊ",pinyin:"tí",wz:"ㄊㄧˊ ㄈㄤˊ",wrong:[{z:"ㄉㄧ",p:"dī"},{z:"ㄕˋ",p:"shì"}],note:"審訂音「堤」讀ㄊㄧˊ，如「堤防」「河堤」。",deep:"1. 注音比較\n堤：ㄊㄧˊ（二聲）＝堤防、河堤、堤岸（審訂音）；ㄉㄧ＝大陸及俗讀，審訂表不採；ㄕˋ＝無此音\n2. 國字拆解與造字原因\n堤：形聲字，「土」＋「是」（聲），沿水邊築起擋水的土壩。台灣審訂音讀ㄊㄧˊ，與「提」同音好記。"},
  {id:"p072",grade:5,word:"包紮",target:"紮",zhuyin:"ㄓㄚˊ",pinyin:"zhá",wz:"ㄅㄠ ㄓㄚˊ",wrong:[{z:"ㄗㄚ",p:"zā"},{z:"ㄓㄚˇ",p:"zhǎ"}],note:"審訂音「包紮」「駐紮」的「紮」讀ㄓㄚˊ。",deep:"1. 注音比較\n紮：ㄓㄚˊ（二聲）＝包紮、駐紮（審訂音）；ㄗㄚ＝俗讀，審訂表不採；ㄓㄚˇ＝無此音\n2. 國字拆解與造字原因\n紮：形聲字，「糸」（繩）＋「札」（聲），用繩捆綁→包紮；軍隊「捆好行囊安營」→駐紮。審訂音讀ㄓㄚˊ。"},
  {id:"p073",grade:5,word:"匕首",target:"匕",zhuyin:"ㄅㄧˇ",pinyin:"bǐ",wz:"ㄅㄧˇ ㄕㄡˇ",wrong:[{z:"ㄅㄧˋ",p:"bì"},{z:"ㄆㄧˇ",p:"pǐ"}],note:"「匕首」的「匕」讀ㄅㄧˇ。",deep:"1. 注音比較\n匕：ㄅㄧˇ（三聲）＝匕首；ㄅㄧˋ＝誤讀；ㄆㄧˇ＝無此音（是「匹」的讀音）\n2. 國字拆解與造字原因\n匕：象形字，像古代取食的匙勺，也像短劍之形→匕首（短劍，柄頭如匙）。讀三聲ㄅㄧˇ。"},
  {id:"p074",grade:5,word:"庇護",target:"庇",zhuyin:"ㄅㄧˋ",pinyin:"bì",wz:"ㄅㄧˋ ㄏㄨˋ",wrong:[{z:"ㄆㄧˋ",p:"pì"},{z:"ㄅㄧˇ",p:"bǐ"}],note:"「庇護」「庇蔭」的「庇」讀ㄅㄧˋ。",deep:"1. 注音比較\n庇：ㄅㄧˋ（四聲）＝庇護、庇蔭、包庇；ㄆㄧˋ＝誤讀；ㄅㄧˇ＝無此音（是「比」的讀音）\n2. 國字拆解與造字原因\n庇：形聲字，「广」（屋）＋「比」（聲），在屋簷下遮蔽→保護（庇護）。讀ㄅㄧˋ。"},
  {id:"p075",grade:5,word:"呵護",target:"呵",zhuyin:"ㄏㄜ",pinyin:"hē",wz:"ㄏㄜ ㄏㄨˋ",wrong:[{z:"ㄎㄜ",p:"kē"},{z:"ㄚ",p:"ā"}],note:"「呵護」「呵斥」的「呵」讀ㄏㄜ。",deep:"1. 注音比較\n呵：ㄏㄜ（一聲）＝呵護、呵斥、呵氣；ㄎㄜ＝無此音；ㄚ＝語氣詞用法（同「啊」）\n2. 國字拆解與造字原因\n呵：形聲字，「口」＋「可」（聲），本義是大聲責喝（呵斥），呵氣取暖引申為照顧保護（呵護）。讀ㄏㄜ。"},
  {id:"p076",grade:5,word:"綻放",target:"綻",zhuyin:"ㄓㄢˋ",pinyin:"zhàn",wz:"ㄓㄢˋ ㄈㄤˋ",wrong:[{z:"ㄉㄧㄥˋ",p:"dìng"},{z:"ㄔㄢˊ",p:"chán"}],note:"「綻放」「破綻」的「綻」讀ㄓㄢˋ。",deep:"1. 注音比較\n綻：ㄓㄢˋ（四聲）＝綻放、破綻、皮開肉綻；ㄉㄧㄥˋ＝無此音（是「定」的讀音）；ㄔㄢˊ＝無此音\n2. 國字拆解與造字原因\n綻：形聲字，「糸」＋「定」（聲），本義是衣縫裂開（破綻）→花苞裂開盛開（綻放）。從「定」得聲卻讀ㄓㄢˋ，常考。"},
  {id:"p077",grade:5,word:"憧憬",target:"憧",zhuyin:"ㄔㄨㄥ",pinyin:"chōng",wz:"ㄔㄨㄥ ㄐㄧㄥˇ",wrong:[{z:"ㄊㄨㄥˊ",p:"tóng"},{z:"ㄓㄨㄤˋ",p:"zhuàng"}],note:"「憧憬」讀ㄔㄨㄥ ㄐㄧㄥˇ。",deep:"1. 注音比較\n憧：ㄔㄨㄥ（一聲）＝憧憬；ㄊㄨㄥˊ＝誤讀（受「童」影響）；ㄓㄨㄤˋ＝無此音（是「撞」的讀音）\n2. 國字拆解與造字原因\n憧：形聲字，「忄」＋「童」（聲），心神往來不定，引申為對未來的嚮往→「憧憬」（ㄔㄨㄥ ㄐㄧㄥˇ）。"},
  {id:"p078",grade:5,word:"瀰漫",target:"瀰",zhuyin:"ㄇㄧˊ",pinyin:"mí",wz:"ㄇㄧˊ ㄇㄢˋ",wrong:[{z:"ㄋㄧˊ",p:"ní"},{z:"ㄇㄧˇ",p:"mǐ"}],note:"「瀰漫」的「瀰」讀ㄇㄧˊ。",deep:"1. 注音比較\n瀰：ㄇㄧˊ（二聲）＝瀰漫；ㄋㄧˊ＝無此音（是「泥」的讀音）；ㄇㄧˇ＝無此音（是「米」的讀音）\n2. 國字拆解與造字原因\n瀰：形聲字，「氵」＋「彌」（聲），水滿布的樣子→煙霧、氣氛滿布（瀰漫）。與「彌」同音ㄇㄧˊ。"},
  {id:"p079",grade:5,word:"贗品",target:"贗",zhuyin:"ㄧㄢˋ",pinyin:"yàn",wz:"ㄧㄢˋ ㄆㄧㄣˇ",wrong:[{z:"ㄧㄥ",p:"yīng"},{z:"ㄧㄢˊ",p:"yán"}],note:"「贗品」的「贗」讀ㄧㄢˋ，偽造的意思。",deep:"1. 注音比較\n贗：ㄧㄢˋ（四聲）＝贗品；ㄧㄥ＝無此音（是「鷹」的讀音）；ㄧㄢˊ＝無此音（是「言」的讀音）\n2. 國字拆解與造字原因\n贗：形聲字，「貝」（財貨）＋「雁」（聲），偽造的財貨→贗品（假貨）。與「雁」形近，但讀ㄧㄢˋ。"},
  {id:"p080",grade:5,word:"魁梧",target:"梧",zhuyin:"ㄨˊ",pinyin:"wú",wz:"ㄎㄨㄟˊ ㄨˊ",wrong:[{z:"ㄨˇ",p:"wǔ"},{z:"ㄨˋ",p:"wù"}],note:"「魁梧」讀ㄎㄨㄟˊ ㄨˊ。",deep:"1. 注音比較\n梧：ㄨˊ（二聲）＝魁梧、梧桐；ㄨˇ＝誤讀；ㄨˋ＝無此音（是「悟」的讀音）\n2. 國字拆解與造字原因\n梧：形聲字，「木」＋「吾」（聲），梧桐樹高大挺直→形容人高大壯碩（魁梧，ㄎㄨㄟˊ ㄨˊ）。"},
  {id:"p081",grade:5,word:"淬鍊",target:"淬",zhuyin:"ㄘㄨㄟˋ",pinyin:"cuì",wz:"ㄘㄨㄟˋ ㄌㄧㄢˋ",wrong:[{z:"ㄗㄨˊ",p:"zú"},{z:"ㄙㄨㄟˋ",p:"suì"}],note:"「淬鍊」「淬火」的「淬」讀ㄘㄨㄟˋ。",deep:"1. 注音比較\n淬：ㄘㄨㄟˋ（四聲）＝淬鍊、淬火；ㄗㄨˊ＝無此音（是「卒」的讀音）；ㄙㄨㄟˋ＝無此音（是「碎」的讀音）\n2. 國字拆解與造字原因\n淬：形聲字，「氵」＋「卒」（聲），鑄劍時把燒紅的金屬浸入水中使堅硬→淬火；引申為磨練（淬鍊）。讀ㄘㄨㄟˋ。"},
  {id:"p082",grade:5,word:"粗糙",target:"糙",zhuyin:"ㄘㄠ",pinyin:"cāo",wz:"ㄘㄨ ㄘㄠ",wrong:[{z:"ㄗㄠˋ",p:"zào"},{z:"ㄘㄠˋ",p:"cào"}],note:"「粗糙」的「糙」讀ㄘㄠ。",deep:"1. 注音比較\n糙：ㄘㄠ（一聲）＝粗糙、糙米；ㄗㄠˋ＝無此音（是「造」的讀音）；ㄘㄠˋ＝誤讀\n2. 國字拆解與造字原因\n糙：形聲字，「米」＋「造」（聲），米沒舂精，表面粗礪→糙米；引申為不細緻（粗糙）。讀一聲ㄘㄠ。"},
  {id:"p083",grade:5,word:"執拗",target:"拗",zhuyin:"ㄋㄧㄡˋ",pinyin:"niù",wz:"ㄓˊ ㄋㄧㄡˋ",wrong:[{z:"ㄠˇ",p:"ǎo"},{z:"ㄠˋ",p:"ào"}],note:"「執拗」（固執）讀ㄋㄧㄡˋ；「拗斷」讀ㄠˇ。",deep:"1. 注音比較\n拗：ㄋㄧㄡˋ（四聲）＝執拗（固執）；ㄠˇ（三聲）＝拗斷、拗折；ㄠˋ（四聲）＝拗口\n2. 國字拆解與造字原因\n拗：形聲字，「扌」＋「幼」（聲），本義是用手折彎（ㄠˇ，拗斷）；性子彆扭不順讀ㄋㄧㄡˋ（執拗）；文句念起來不順讀ㄠˋ（拗口）。一字三音依語義區分。"},
  {id:"p084",grade:5,word:"友誼",target:"誼",zhuyin:"ㄧˋ",pinyin:"yì",wz:"ㄧㄡˇ ㄧˋ",wrong:[{z:"ㄧˊ",p:"yí"},{z:"ㄧˇ",p:"yǐ"}],note:"「友誼」「情誼」的「誼」讀ㄧˋ。",deep:"1. 注音比較\n誼：ㄧˋ（四聲）＝友誼、情誼、聯誼；ㄧˊ＝誤讀（受「宜」影響）；ㄧˇ＝無此音\n2. 國字拆解與造字原因\n誼：形聲字，「言」＋「宜」（聲），本義是合宜的道理，引申為人與人合宜的交情→友誼。從「宜」得聲卻讀ㄧˋ，常考誤讀字。"},
  {id:"p085",grade:5,word:"氣魄",target:"魄",zhuyin:"ㄆㄛˋ",pinyin:"pò",wz:"ㄑㄧˋ ㄆㄛˋ",wrong:[{z:"ㄅㄛˊ",p:"bó"},{z:"ㄊㄨㄛˋ",p:"tuò"}],note:"「氣魄」「魄力」讀ㄆㄛˋ；「落魄」亦讀ㄆㄛˋ。",deep:"1. 注音比較\n魄：ㄆㄛˋ（四聲）＝氣魄、魄力、落魄；ㄅㄛˊ＝「落魄」舊讀，審訂表統讀ㄆㄛˋ；ㄊㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n魄：形聲字，「鬼」＋「白」（聲），古人認為依附形體的精神為「魄」（魂魄）→精神力量（氣魄、魄力）。審訂音統讀ㄆㄛˋ。"},
  {id:"p086",grade:6,word:"沮喪",target:"沮",zhuyin:"ㄐㄩˇ",pinyin:"jǔ",wz:"ㄐㄩˇ ㄙㄤˋ",wrong:[{z:"ㄑㄧㄝˇ",p:"qiě"},{z:"ㄗㄨˇ",p:"zǔ"}],note:"「沮喪」的「沮」讀ㄐㄩˇ。",deep:"1. 注音比較\n沮：ㄐㄩˇ（三聲）＝沮喪；ㄑㄧㄝˇ＝無此音（是「且」的讀音）；ㄗㄨˇ＝無此音（是「阻」的讀音）\n2. 國字拆解與造字原因\n沮：形聲字，「氵」＋「且」（聲），本義是水名，假借表頹敗、氣餒→沮喪。讀ㄐㄩˇ，別受「阻」影響誤讀。"},
  {id:"p087",grade:6,word:"賦予",target:"賦",zhuyin:"ㄈㄨˋ",pinyin:"fù",wz:"ㄈㄨˋ ㄩˇ",wrong:[{z:"ㄈㄨˇ",p:"fǔ"},{z:"ㄨˇ",p:"wǔ"}],note:"「賦予」「天賦」的「賦」讀ㄈㄨˋ。",deep:"1. 注音比較\n賦：ㄈㄨˋ（四聲）＝賦予、天賦、詩詞歌賦；ㄈㄨˇ＝無此音（是「腐」的讀音）；ㄨˇ＝無此音\n2. 國字拆解與造字原因\n賦：形聲字，「貝」（財）＋「武」（聲），本義是徵收田稅→朝廷「給與」人民負擔，引申為授與（賦予）、天生具備（天賦），也是文體名（漢賦）。"},
  {id:"p088",grade:6,word:"毋庸置疑",target:"毋",zhuyin:"ㄨˊ",pinyin:"wú",wz:"ㄨˊ ㄩㄥ ㄓˋ ㄧˊ",wrong:[{z:"ㄨˋ",p:"wù"},{z:"ㄇㄨˇ",p:"mǔ"}],note:"「毋」讀ㄨˊ，不要、不可的意思。",deep:"1. 注音比較\n毋：ㄨˊ（二聲）＝毋庸置疑、寧缺毋濫；ㄨˋ＝無此音（是「勿」的讀音）；ㄇㄨˇ＝無此音（是「母」的讀音）\n2. 國字拆解與造字原因\n毋：指事字，「母」字加一筆貫穿，表示禁止之意——不要、不可。與「母」形近，注意分辨：毋（ㄨˊ）中間是一橫貫穿，母（ㄇㄨˇ）是兩點。"},
  {id:"p089",grade:6,word:"阻撓",target:"撓",zhuyin:"ㄋㄠˊ",pinyin:"náo",wz:"ㄗㄨˇ ㄋㄠˊ",wrong:[{z:"ㄖㄠˊ",p:"ráo"},{z:"ㄋㄠˇ",p:"nǎo"}],note:"「阻撓」「不屈不撓」的「撓」讀ㄋㄠˊ。",deep:"1. 注音比較\n撓：ㄋㄠˊ（二聲）＝阻撓、不屈不撓；ㄖㄠˊ＝無此音（是「饒」的讀音）；ㄋㄠˇ＝無此音（是「惱」的讀音）\n2. 國字拆解與造字原因\n撓：形聲字，「扌」＋「堯」（聲），本義是攪動、使彎曲→阻撓（從中攪擾）、不屈不撓（不彎曲）。讀ㄋㄠˊ。"},
  {id:"p090",grade:6,word:"闢謠",target:"闢",zhuyin:"ㄆㄧˋ",pinyin:"pì",wz:"ㄆㄧˋ ㄧㄠˊ",wrong:[{z:"ㄅㄧˋ",p:"bì"},{z:"ㄆㄧ",p:"pī"}],note:"「闢謠」「開闢」的「闢」讀ㄆㄧˋ。",deep:"1. 注音比較\n闢：ㄆㄧˋ（四聲）＝闢謠、開闢、精闢；ㄅㄧˋ＝古通「避」「辟」的讀音；ㄆㄧ＝無此音（是「批」的讀音）\n2. 國字拆解與造字原因\n闢：形聲字，「門」＋「辟」（聲），本義是打開門→開拓（開闢）、駁斥使真相打開（闢謠）。讀ㄆㄧˋ。"},
  {id:"p091",grade:6,word:"塑膠",target:"塑",zhuyin:"ㄙㄨˋ",pinyin:"sù",wz:"ㄙㄨˋ ㄐㄧㄠ",wrong:[{z:"ㄕㄨㄛˋ",p:"shuò"},{z:"ㄙㄨㄛˋ",p:"suò"}],note:"「塑膠」「雕塑」的「塑」讀ㄙㄨˋ。",deep:"1. 注音比較\n塑：ㄙㄨˋ（四聲）＝塑膠、雕塑、塑造；ㄕㄨㄛˋ＝無此音（是「朔」的讀音）；ㄙㄨㄛˋ＝誤讀\n2. 國字拆解與造字原因\n塑：形聲字，「土」＋「朔」（聲），用泥土捏造形象→雕塑、塑造。從「朔」（ㄕㄨㄛˋ）得聲卻讀ㄙㄨˋ，常考誤讀字。"},
  {id:"p092",grade:6,word:"琺瑯",target:"琺",zhuyin:"ㄈㄚˋ",pinyin:"fà",wz:"ㄈㄚˋ ㄌㄤˊ",wrong:[{z:"ㄈㄚ",p:"fā"},{z:"ㄈㄚˇ",p:"fǎ"}],note:"「琺瑯」讀ㄈㄚˋ ㄌㄤˊ。",deep:"1. 注音比較\n琺：ㄈㄚˋ（四聲）＝琺瑯；ㄈㄚ＝無此音（是「發」的讀音）；ㄈㄚˇ＝無此音（是「法」的讀音）\n2. 國字拆解與造字原因\n琺：形聲字，「𤣩（玉）」＋「法」（聲），外來語音譯字，「琺瑯」（ㄈㄚˋ ㄌㄤˊ）是覆在金屬表面的玻璃質釉料。"},
  {id:"p093",grade:6,word:"卓越",target:"卓",zhuyin:"ㄓㄨㄛˊ",pinyin:"zhuó",wz:"ㄓㄨㄛˊ ㄩㄝˋ",wrong:[{z:"ㄓㄠ",p:"zhāo"},{z:"ㄉㄧㄠˋ",p:"diào"}],note:"「卓越」「卓見」的「卓」讀ㄓㄨㄛˊ。",deep:"1. 注音比較\n卓：ㄓㄨㄛˊ（二聲）＝卓越、卓見、卓然；ㄓㄠ＝無此音；ㄉㄧㄠˋ＝無此音（是「吊」的讀音）\n2. 國字拆解與造字原因\n卓：會意字，像人高立之形，本義是高超、直立→卓越、卓然出眾。讀ㄓㄨㄛˊ。"},
  {id:"p094",grade:6,word:"稽查",target:"稽",zhuyin:"ㄐㄧ",pinyin:"jī",wz:"ㄐㄧ ㄔㄚˊ",wrong:[{z:"ㄑㄧˇ",p:"qǐ"},{z:"ㄐㄧˋ",p:"jì"}],note:"「稽查」「稽核」讀ㄐㄧ；「稽首」讀ㄑㄧˇ。",deep:"1. 注音比較\n稽：ㄐㄧ（一聲）＝稽查、稽核、無稽之談；ㄑㄧˇ（三聲）＝稽首（叩頭禮）；ㄐㄧˋ＝無此音（是「計」的讀音）\n2. 國字拆解與造字原因\n稽：形聲字，「禾」＋「尤」「旨」，本義是停留查考→稽查、稽核（ㄐㄧ）；古代叩頭至地停留的大禮讀ㄑㄧˇ（稽首）。"},
  {id:"p095",grade:6,word:"綜合",target:"綜",zhuyin:"ㄗㄨㄥˋ",pinyin:"zòng",wz:"ㄗㄨㄥˋ ㄏㄜˊ",wrong:[{z:"ㄗㄨㄥ",p:"zōng"},{z:"ㄘㄨㄥˊ",p:"cóng"}],note:"審訂音「綜合」的「綜」讀ㄗㄨㄥˋ。",deep:"1. 注音比較\n綜：ㄗㄨㄥˋ（四聲）＝綜合、綜覽、錯綜複雜（審訂音）；ㄗㄨㄥ＝俗讀，審訂表不採；ㄘㄨㄥˊ＝無此音\n2. 國字拆解與造字原因\n綜：形聲字，「糸」＋「宗」（聲），本義是織布機上總持經線的部件→總聚各方（綜合）。審訂音讀四聲ㄗㄨㄥˋ。"},
  {id:"p096",grade:6,word:"矜持",target:"矜",zhuyin:"ㄐㄧㄣ",pinyin:"jīn",wz:"ㄐㄧㄣ ㄔˊ",wrong:[{z:"ㄑㄧㄣˊ",p:"qín"},{z:"ㄍㄨㄢ",p:"guān"}],note:"「矜持」「自矜」的「矜」讀ㄐㄧㄣ。",deep:"1. 注音比較\n矜：ㄐㄧㄣ（一聲）＝矜持、自矜、矜憫；ㄑㄧㄣˊ＝古音（矛柄義）；ㄍㄨㄢ＝古通「鰥」\n2. 國字拆解與造字原因\n矜：形聲字，「矛」＋「今」（聲），本義是矛柄，假借表自重、莊重→矜持；自誇→自矜。今讀ㄐㄧㄣ。"},
  {id:"p097",grade:6,word:"僥倖",target:"僥",zhuyin:"ㄐㄧㄠˇ",pinyin:"jiǎo",wz:"ㄐㄧㄠˇ ㄒㄧㄥˋ",wrong:[{z:"ㄧㄠˊ",p:"yáo"},{z:"ㄒㄧㄠˇ",p:"xiǎo"}],note:"「僥倖」讀ㄐㄧㄠˇ ㄒㄧㄥˋ。",deep:"1. 注音比較\n僥：ㄐㄧㄠˇ（三聲）＝僥倖；ㄧㄠˊ＝古音（僬僥，傳說矮人國）；ㄒㄧㄠˇ＝無此音\n2. 國字拆解與造字原因\n僥：形聲字，「亻」＋「堯」（聲），「僥倖」（ㄐㄧㄠˇ ㄒㄧㄥˋ）指意外獲得成功或免於災禍——貪求非分的好運。"},
  {id:"p098",grade:6,word:"骨髓",target:"髓",zhuyin:"ㄙㄨㄟˇ",pinyin:"suǐ",wz:"ㄍㄨˇ ㄙㄨㄟˇ",wrong:[{z:"ㄙㄨㄟˊ",p:"suí"},{z:"ㄙㄨㄟˋ",p:"suì"}],note:"「骨髓」「精髓」的「髓」讀ㄙㄨㄟˇ。",deep:"1. 注音比較\n髓：ㄙㄨㄟˇ（三聲）＝骨髓、精髓、腦髓；ㄙㄨㄟˊ＝誤讀（受「隨」影響）；ㄙㄨㄟˋ＝無此音（是「歲」的讀音）\n2. 國字拆解與造字原因\n髓：形聲字，「骨」＋「隨（省）」（聲），骨頭中的膏狀組織→骨髓；事物的精華→精髓。讀三聲ㄙㄨㄟˇ。"},
  {id:"p099",grade:6,word:"露臉",target:"露",zhuyin:"ㄌㄡˋ",pinyin:"lòu",wz:"ㄌㄡˋ ㄌㄧㄢˇ",wrong:[{z:"ㄌㄨˋ",p:"lù"},{z:"ㄌㄡˊ",p:"lóu"}],note:"口語「露臉」「露餡」讀ㄌㄡˋ；書面「露水」「揭露」讀ㄌㄨˋ。",deep:"1. 注音比較\n露：ㄌㄡˋ（四聲）＝露臉、露餡、露一手（口語）；ㄌㄨˋ（四聲）＝露水、揭露、暴露（書面）；ㄌㄡˊ＝無此音（是「樓」的讀音）\n2. 國字拆解與造字原因\n露：「雨」＋「路」（聲），本義是露水。書面語讀ㄌㄨˋ；口語「顯現出來」讀ㄌㄡˋ（露臉、露馬腳）。記法：口語顯現ㄌㄡˋ、書面ㄌㄨˋ。"},
  {id:"p100",grade:6,word:"薄弱",target:"薄",zhuyin:"ㄅㄛˊ",pinyin:"bó",wz:"ㄅㄛˊ ㄖㄨㄛˋ",wrong:[{z:"ㄅㄠˊ",p:"báo"},{z:"ㄅㄛˋ",p:"bò"}],note:"「薄弱」「刻薄」讀ㄅㄛˊ；口語「很薄」讀ㄅㄠˊ；「薄荷」讀ㄅㄛˋ。",deep:"1. 注音比較\n薄：ㄅㄛˊ（二聲）＝薄弱、刻薄、單薄（書面）；ㄅㄠˊ（二聲）＝很薄、薄片（口語）；ㄅㄛˋ（四聲）＝薄荷\n2. 國字拆解與造字原因\n薄：形聲字，「艹」＋「溥」（聲），本義是草木叢生處，假借表厚度小。書面詞讀ㄅㄛˊ（薄弱、淡薄）；口語讀ㄅㄠˊ（紙很薄）；「薄荷」專讀ㄅㄛˋ。"},
  // ---- 國中 7-9（p101-p200）----
  {id:"p101",grade:7,word:"莘莘學子",target:"莘",zhuyin:"ㄕㄣ",pinyin:"shēn",wz:"ㄕㄣ ㄕㄣ ㄒㄩㄝˊ ㄗˇ",wrong:[{z:"ㄒㄧㄣ",p:"xīn"},{z:"ㄒㄧㄥ",p:"xīng"}],note:"教育部審訂音「莘莘學子」的「莘」讀ㄕㄣ，形容眾多的樣子。",deep:"1. 注音比較\n莘：ㄕㄣ＝莘莘學子（眾多的樣子）；ㄒㄧㄣ＝地名、姓氏用。★「莘莘學子」教育部審訂音讀ㄕㄣ ㄕㄣ，讀成ㄒㄧㄣ不是審訂音\n2. 國字拆解與造字原因\n莘：形聲字，「艹」＋「辛」（聲）。本是一種草，疊用作「莘莘」表示數量很多，「莘莘學子」就是眾多的學生。"},
  {id:"p102",grade:7,word:"肄業",target:"肄",zhuyin:"ㄧˋ",pinyin:"yì",wz:"ㄧˋ ㄧㄝˋ",wrong:[{z:"ㄙˋ",p:"sì"},{z:"ㄌㄧˋ",p:"lì"}],note:"「肄業」的「肄」讀ㄧˋ，修習之意，勿與「肆」混淆。",deep:"1. 注音比較\n肄：ㄧˋ（四聲）＝肄業；ㄙˋ＝無此音（是「肆」的讀音）；ㄌㄧˋ＝無此音\n2. 國字拆解與造字原因\n肄：從「聿」（筆），本義是學習、修習→肄業（在學修習尚未畢業）。與「肆」（ㄙˋ，放肆）形近，注意左半不同。"},
  {id:"p103",grade:7,word:"造詣",target:"詣",zhuyin:"ㄧˋ",pinyin:"yì",wz:"ㄗㄠˋ ㄧˋ",wrong:[{z:"ㄓˇ",p:"zhǐ"},{z:"ㄑㄧˇ",p:"qǐ"}],note:"「造詣」的「詣」讀ㄧˋ，學問技藝所達到的境界。",deep:"1. 注音比較\n詣：ㄧˋ（四聲）＝造詣；ㄓˇ＝無此音（是「旨」的讀音）；ㄑㄧˇ＝無此音\n2. 國字拆解與造字原因\n詣：形聲字，「言」＋「旨」（聲），本義是前往拜訪，引申為學問技藝「到達」的境界→造詣。從「旨」得聲卻讀ㄧˋ。"},
  {id:"p104",grade:7,word:"贍養",target:"贍",zhuyin:"ㄕㄢˋ",pinyin:"shàn",wz:"ㄕㄢˋ ㄧㄤˇ",wrong:[{z:"ㄓㄢ",p:"zhān"},{z:"ㄉㄢ",p:"dān"}],note:"「贍養」的「贍」讀ㄕㄢˋ，供給之意。",deep:"1. 注音比較\n贍：ㄕㄢˋ（四聲）＝贍養；ㄓㄢ＝無此音（是「瞻」的讀音）；ㄉㄢ＝無此音\n2. 國字拆解與造字原因\n贍：形聲字，「貝」（財）＋「詹」（聲），供給財物→贍養（供養長輩）。與「瞻」（ㄓㄢ，瞻仰）同聲符不同音。"},
  {id:"p105",grade:7,word:"未遂",target:"遂",zhuyin:"ㄙㄨㄟˋ",pinyin:"suì",wz:"ㄨㄟˋ ㄙㄨㄟˋ",wrong:[{z:"ㄙㄨㄟˊ",p:"suí"},{z:"ㄓㄨㄟˋ",p:"zhuì"}],note:"「未遂」「遂心」的「遂」讀ㄙㄨㄟˋ；「半身不遂」讀ㄙㄨㄟˊ。",deep:"1. 注音比較\n遂：ㄙㄨㄟˋ（四聲）＝未遂、遂心、遂願；ㄙㄨㄟˊ（二聲）＝半身不遂；ㄓㄨㄟˋ＝無此音（是「贅」的讀音）\n2. 國字拆解與造字原因\n遂：形聲字，「辶」＋「㒸」（聲），本義是前進達成→順遂、未遂（沒達成）；肢體「行不通」的「半身不遂」讀ㄙㄨㄟˊ。"},
  {id:"p106",grade:7,word:"倉皇",target:"皇",zhuyin:"ㄏㄨㄤˊ",pinyin:"huáng",wz:"ㄘㄤ ㄏㄨㄤˊ",wrong:[{z:"ㄨㄤˊ",p:"wáng"},{z:"ㄏㄨㄤˇ",p:"huǎng"}],note:"「倉皇」讀ㄘㄤ ㄏㄨㄤˊ，匆忙慌張的樣子。",deep:"1. 注音比較\n皇：ㄏㄨㄤˊ（二聲）＝倉皇、皇帝、堂皇；ㄨㄤˊ＝無此音（是「王」的讀音）；ㄏㄨㄤˇ＝無此音（是「謊」的讀音）\n2. 國字拆解與造字原因\n皇：從「白」從「王」，本義是大、輝煌→皇帝。「倉皇」（匆忙慌張）借「皇」表音，讀ㄏㄨㄤˊ。"},
  {id:"p107",grade:7,word:"馴服",target:"馴",zhuyin:"ㄒㄩㄣˊ",pinyin:"xún",wz:"ㄒㄩㄣˊ ㄈㄨˊ",wrong:[{z:"ㄒㄩㄣˋ",p:"xùn"},{z:"ㄕㄨㄣˋ",p:"shùn"}],note:"「馴服」「溫馴」的「馴」讀ㄒㄩㄣˊ。",deep:"1. 注音比較\n馴：ㄒㄩㄣˊ（二聲）＝馴服、溫馴、馴養；ㄒㄩㄣˋ＝誤讀（受「訓」影響）；ㄕㄨㄣˋ＝無此音（是「順」的讀音）\n2. 國字拆解與造字原因\n馴：形聲字，「馬」＋「川」（聲），馬順從如川水順流→馴服、溫馴。讀二聲ㄒㄩㄣˊ。"},
  {id:"p108",grade:7,word:"胸脯",target:"脯",zhuyin:"ㄆㄨˊ",pinyin:"pú",wz:"ㄒㄩㄥ ㄆㄨˊ",wrong:[{z:"ㄈㄨˇ",p:"fǔ"},{z:"ㄅㄨˇ",p:"bǔ"}],note:"「胸脯」讀ㄆㄨˊ；「果脯」「肉脯」讀ㄈㄨˇ。",deep:"1. 注音比較\n脯：ㄆㄨˊ（二聲）＝胸脯；ㄈㄨˇ（三聲）＝果脯、肉脯（乾製食品）；ㄅㄨˇ＝無此音\n2. 國字拆解與造字原因\n脯：形聲字，「月（肉）」＋「甫」（聲）。指胸膛讀ㄆㄨˊ（胸脯）；指晒乾的肉果讀ㄈㄨˇ（肉脯、果脯）。一字兩音指不同東西。"},
  {id:"p109",grade:7,word:"憎恨",target:"憎",zhuyin:"ㄗㄥ",pinyin:"zēng",wz:"ㄗㄥ ㄏㄣˋ",wrong:[{z:"ㄗㄥˋ",p:"zèng"},{z:"ㄘㄥˊ",p:"céng"}],note:"「憎恨」「愛憎」的「憎」讀ㄗㄥ，常被誤讀成ㄗㄥˋ。",deep:"1. 注音比較\n憎：ㄗㄥ（一聲）＝憎恨、愛憎、面目可憎；ㄗㄥˋ＝誤讀（受「贈」影響）；ㄘㄥˊ＝無此音（是「曾」的讀音）\n2. 國字拆解與造字原因\n憎：形聲字，「忄」＋「曾」（聲），心生厭惡→憎恨。讀一聲ㄗㄥ，別受「贈」（ㄗㄥˋ）影響。"},
  {id:"p110",grade:7,word:"陶冶",target:"冶",zhuyin:"ㄧㄝˇ",pinyin:"yě",wz:"ㄊㄠˊ ㄧㄝˇ",wrong:[{z:"ㄓˋ",p:"zhì"},{z:"ㄊㄞˊ",p:"tái"}],note:"「陶冶」「冶金」的「冶」讀ㄧㄝˇ，勿與「治」混淆。",deep:"1. 注音比較\n冶：ㄧㄝˇ（三聲）＝陶冶、冶金、冶煉；ㄓˋ＝無此音（是「治」的讀音）；ㄊㄞˊ＝無此音\n2. 國字拆解與造字原因\n冶：從「冫」（冰），本義是銷熔金屬（冰融與金屬熔化意象相通）→冶金；鎔鑄性情→陶冶。與「治」（氵旁）形近音異，注意分辨。"},
  {id:"p111",grade:7,word:"氣餒",target:"餒",zhuyin:"ㄋㄟˇ",pinyin:"něi",wz:"ㄑㄧˋ ㄋㄟˇ",wrong:[{z:"ㄊㄨㄛˇ",p:"tuǒ"},{z:"ㄋㄨㄛˋ",p:"nuò"}],note:"「氣餒」的「餒」讀ㄋㄟˇ，喪失勇氣。",deep:"1. 注音比較\n餒：ㄋㄟˇ（三聲）＝氣餒、勝不驕敗不餒；ㄊㄨㄛˇ＝無此音；ㄋㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n餒：形聲字，「食」＋「妥」（聲），本義是飢餓——餓了就沒力氣，引申為喪失勇氣→氣餒。讀ㄋㄟˇ。"},
  {id:"p112",grade:7,word:"堆砌",target:"砌",zhuyin:"ㄑㄧˋ",pinyin:"qì",wz:"ㄉㄨㄟ ㄑㄧˋ",wrong:[{z:"ㄑㄧㄝˋ",p:"qiè"},{z:"ㄒㄧˋ",p:"xì"}],note:"「堆砌」「砌牆」的「砌」讀ㄑㄧˋ。",deep:"1. 注音比較\n砌：ㄑㄧˋ（四聲）＝堆砌、砌牆、雕欄玉砌；ㄑㄧㄝˋ＝俗讀（如堆砌ㄑㄧㄝˋ），審訂表不採；ㄒㄧˋ＝無此音\n2. 國字拆解與造字原因\n砌：形聲字，「石」＋「切」（聲），用石塊層層疊築→砌牆；文章堆疊詞藻→堆砌。讀ㄑㄧˋ。"},
  {id:"p113",grade:7,word:"莞爾",target:"莞",zhuyin:"ㄨㄢˇ",pinyin:"wǎn",wz:"ㄨㄢˇ ㄦˇ",wrong:[{z:"ㄍㄨㄢˇ",p:"guǎn"},{z:"ㄨㄢˊ",p:"wán"}],note:"「莞爾一笑」的「莞」讀ㄨㄢˇ。",deep:"1. 注音比較\n莞：ㄨㄢˇ（三聲）＝莞爾一笑；ㄍㄨㄢˇ（三聲）＝東莞（地名）；ㄨㄢˊ＝無此音\n2. 國字拆解與造字原因\n莞：形聲字，「艹」＋「完」（聲），本義是水草蓆草。「莞爾」是微笑的樣子（《論語》「夫子莞爾而笑」），讀ㄨㄢˇ；地名「東莞」讀ㄍㄨㄢˇ。"},
  {id:"p114",grade:7,word:"憔悴",target:"悴",zhuyin:"ㄘㄨㄟˋ",pinyin:"cuì",wz:"ㄑㄧㄠˊ ㄘㄨㄟˋ",wrong:[{z:"ㄗㄨˋ",p:"zù"},{z:"ㄙㄨㄟˋ",p:"suì"}],note:"「憔悴」讀ㄑㄧㄠˊ ㄘㄨㄟˋ。",deep:"1. 注音比較\n悴：ㄘㄨㄟˋ（四聲）＝憔悴；ㄗㄨˋ＝無此音；ㄙㄨㄟˋ＝無此音（是「碎」的讀音）\n2. 國字拆解與造字原因\n悴：形聲字，「忄」＋「卒」（聲），心力交瘁而面容枯槁→「憔悴」（ㄑㄧㄠˊ ㄘㄨㄟˋ）。"},
  {id:"p115",grade:7,word:"戛然而止",target:"戛",zhuyin:"ㄐㄧㄚˊ",pinyin:"jiá",wz:"ㄐㄧㄚˊ ㄖㄢˊ ㄦˊ ㄓˇ",wrong:[{z:"ㄍㄚ",p:"gā"},{z:"ㄓㄚˊ",p:"zhá"}],note:"「戛然而止」的「戛」讀ㄐㄧㄚˊ，聲音突然停止。",deep:"1. 注音比較\n戛：ㄐㄧㄚˊ（二聲）＝戛然而止；ㄍㄚ＝誤讀；ㄓㄚˊ＝無此音\n2. 國字拆解與造字原因\n戛：從「戈」，本義是長矛，敲擊聲「戛然」借其音——「戛然而止」形容聲音突然停止。讀ㄐㄧㄚˊ。"},
  {id:"p116",grade:7,word:"綺麗",target:"綺",zhuyin:"ㄑㄧˇ",pinyin:"qǐ",wz:"ㄑㄧˇ ㄌㄧˋ",wrong:[{z:"ㄧˇ",p:"yǐ"},{z:"ㄑㄧˊ",p:"qí"}],note:"「綺麗」「羅綺」的「綺」讀ㄑㄧˇ。",deep:"1. 注音比較\n綺：ㄑㄧˇ（三聲）＝綺麗、羅綺、綺想；ㄧˇ＝無此音；ㄑㄧˊ＝誤讀（受「奇」影響）\n2. 國字拆解與造字原因\n綺：形聲字，「糸」＋「奇」（聲），有花紋的絲織品→華美（綺麗）。從「奇」得聲卻讀ㄑㄧˇ。"},
  {id:"p117",grade:7,word:"手帕",target:"帕",zhuyin:"ㄆㄚˋ",pinyin:"pà",wz:"ㄕㄡˇ ㄆㄚˋ",wrong:[{z:"ㄆㄛˋ",p:"pò"},{z:"ㄅㄚˋ",p:"bà"}],note:"「手帕」的「帕」讀ㄆㄚˋ。",deep:"1. 注音比較\n帕：ㄆㄚˋ（四聲）＝手帕；ㄆㄛˋ＝無此音（是「魄」的讀音）；ㄅㄚˋ＝無此音（是「爸」的讀音）\n2. 國字拆解與造字原因\n帕：形聲字，「巾」＋「白」（聲），擦拭用的小方巾→手帕。讀ㄆㄚˋ。"},
  {id:"p118",grade:7,word:"要脅",target:"脅",zhuyin:"ㄒㄧㄝˊ",pinyin:"xié",wz:"ㄧㄠ ㄒㄧㄝˊ",wrong:[{z:"ㄒㄧㄝˋ",p:"xiè"},{z:"ㄐㄧㄝˊ",p:"jié"}],note:"「要脅」「脅迫」的「脅」讀ㄒㄧㄝˊ。",deep:"1. 注音比較\n脅：ㄒㄧㄝˊ（二聲）＝要脅、脅迫、威脅；ㄒㄧㄝˋ＝誤讀；ㄐㄧㄝˊ＝無此音\n2. 國字拆解與造字原因\n脅：從「月（肉）」、「劦」（聲），本義是腋下肋骨部位——從兩肋挾制人→威脅、脅迫。讀ㄒㄧㄝˊ。"},
  {id:"p119",grade:7,word:"猙獰",target:"獰",zhuyin:"ㄋㄧㄥˊ",pinyin:"níng",wz:"ㄓㄥ ㄋㄧㄥˊ",wrong:[{z:"ㄋㄧㄥˇ",p:"nǐng"},{z:"ㄋㄧㄥˋ",p:"nìng"}],note:"「猙獰」讀ㄓㄥ ㄋㄧㄥˊ。",deep:"1. 注音比較\n獰：ㄋㄧㄥˊ（二聲）＝猙獰、獰笑；ㄋㄧㄥˇ＝無此音；ㄋㄧㄥˋ＝無此音（是「濘」的讀音）\n2. 國字拆解與造字原因\n獰：形聲字，「犭」＋「寧」（聲），面目凶惡如猛獸→「猙獰」（ㄓㄥ ㄋㄧㄥˊ）。"},
  {id:"p120",grade:7,word:"手腕",target:"腕",zhuyin:"ㄨㄢˋ",pinyin:"wàn",wz:"ㄕㄡˇ ㄨㄢˋ",wrong:[{z:"ㄨㄢˇ",p:"wǎn"},{z:"ㄨㄢ",p:"wān"}],note:"「手腕」「腕力」的「腕」讀ㄨㄢˋ。",deep:"1. 注音比較\n腕：ㄨㄢˋ（四聲）＝手腕、腕力、鐵腕；ㄨㄢˇ＝誤讀；ㄨㄢ＝無此音（是「彎」的讀音）\n2. 國字拆解與造字原因\n腕：形聲字，「月（肉）」＋「宛」（聲），手掌與前臂相接的部位→手腕；引申為手段（鐵腕）。讀ㄨㄢˋ。"},
  {id:"p121",grade:8,word:"膾炙人口",target:"膾",zhuyin:"ㄎㄨㄞˋ",pinyin:"kuài",wz:"ㄎㄨㄞˋ ㄓˋ ㄖㄣˊ ㄎㄡˇ",wrong:[{z:"ㄏㄨㄟˋ",p:"huì"},{z:"ㄎㄨㄛˋ",p:"kuò"}],note:"「膾」讀ㄎㄨㄞˋ，細切的肉。",deep:"1. 注音比較\n膾：ㄎㄨㄞˋ（四聲）＝膾炙人口；ㄏㄨㄟˋ＝誤讀（受「會」影響）；ㄎㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n膾：形聲字，「月（肉）」＋「會」（聲），細切的魚、肉片——古人視為美味。「膾炙人口」的「膾」讀ㄎㄨㄞˋ，與「快」同音。"},
  {id:"p122",grade:8,word:"矯揉造作",target:"矯",zhuyin:"ㄐㄧㄠˇ",pinyin:"jiǎo",wz:"ㄐㄧㄠˇ ㄖㄡˊ ㄗㄠˋ ㄗㄨㄛˋ",wrong:[{z:"ㄑㄧㄠˊ",p:"qiáo"},{z:"ㄐㄧㄠ",p:"jiāo"}],note:"「矯揉造作」「矯正」的「矯」讀ㄐㄧㄠˇ。",deep:"1. 注音比較\n矯：ㄐㄧㄠˇ（三聲）＝矯正、矯揉造作、矯健；ㄑㄧㄠˊ＝無此音（是「僑」的讀音）；ㄐㄧㄠ＝無此音（是「驕」的讀音）\n2. 國字拆解與造字原因\n矯：形聲字，「矢」（箭）＋「喬」（聲），本義是把箭桿弄直→矯正；故意做作→矯揉造作。讀ㄐㄧㄠˇ。"},
  {id:"p123",grade:8,word:"瞠目結舌",target:"瞠",zhuyin:"ㄔㄥ",pinyin:"chēng",wz:"ㄔㄥ ㄇㄨˋ ㄐㄧㄝˊ ㄕㄜˊ",wrong:[{z:"ㄊㄤˊ",p:"táng"},{z:"ㄓㄥ",p:"zhēng"}],note:"「瞠目結舌」的「瞠」讀ㄔㄥ，瞪眼直視。",deep:"1. 注音比較\n瞠：ㄔㄥ（一聲）＝瞠目結舌、瞠乎其後；ㄊㄤˊ＝誤讀（受「堂」影響）；ㄓㄥ＝無此音\n2. 國字拆解與造字原因\n瞠：形聲字，「目」＋「堂」（聲），瞪大眼睛直視→瞠目結舌。從「堂」得聲卻讀ㄔㄥ，常考誤讀字。"},
  {id:"p124",grade:8,word:"傀儡",target:"儡",zhuyin:"ㄌㄟˇ",pinyin:"lěi",wz:"ㄎㄨㄟˇ ㄌㄟˇ",wrong:[{z:"ㄌㄟˊ",p:"léi"},{z:"ㄌㄟˋ",p:"lèi"}],note:"「傀儡」讀ㄎㄨㄟˇ ㄌㄟˇ。",deep:"1. 注音比較\n儡：ㄌㄟˇ（三聲）＝傀儡；ㄌㄟˊ＝無此音（是「雷」的讀音）；ㄌㄟˋ＝無此音（是「淚」的讀音）\n2. 國字拆解與造字原因\n儡：形聲字，「亻」＋「畾」（聲），「傀儡」（ㄎㄨㄟˇ ㄌㄟˇ）是提線木偶，引申為受人操縱的人。"},
  {id:"p125",grade:8,word:"骷髏",target:"髏",zhuyin:"ㄌㄡˊ",pinyin:"lóu",wz:"ㄎㄨ ㄌㄡˊ",wrong:[{z:"ㄌㄡˇ",p:"lǒu"},{z:"ㄌㄨˊ",p:"lú"}],note:"「骷髏」讀ㄎㄨ ㄌㄡˊ。",deep:"1. 注音比較\n髏：ㄌㄡˊ（二聲）＝骷髏；ㄌㄡˇ＝無此音；ㄌㄨˊ＝無此音（是「顱」的讀音）\n2. 國字拆解與造字原因\n髏：形聲字，「骨」＋「婁」（聲），「骷髏」（ㄎㄨ ㄌㄡˊ）是乾枯的死人頭骨或全副骨骸。"},
  {id:"p126",grade:8,word:"贖罪",target:"贖",zhuyin:"ㄕㄨˊ",pinyin:"shú",wz:"ㄕㄨˊ ㄗㄨㄟˋ",wrong:[{z:"ㄉㄨˊ",p:"dú"},{z:"ㄕㄨˇ",p:"shǔ"}],note:"「贖罪」「贖回」的「贖」讀ㄕㄨˊ。",deep:"1. 注音比較\n贖：ㄕㄨˊ（二聲）＝贖罪、贖回、贖金；ㄉㄨˊ＝無此音（是「讀」的讀音）；ㄕㄨˇ＝無此音（是「屬」的舊讀）\n2. 國字拆解與造字原因\n贖：形聲字，「貝」（財）＋「賣」（聲），用財物換回人或物→贖回、贖罪（用行動抵過）。讀ㄕㄨˊ。"},
  {id:"p127",grade:8,word:"箴言",target:"箴",zhuyin:"ㄓㄣ",pinyin:"zhēn",wz:"ㄓㄣ ㄧㄢˊ",wrong:[{z:"ㄒㄧㄢˊ",p:"xián"},{z:"ㄐㄧㄢ",p:"jiān"}],note:"「箴言」的「箴」讀ㄓㄣ，規勸告誡的話。",deep:"1. 注音比較\n箴：ㄓㄣ（一聲）＝箴言、箴規；ㄒㄧㄢˊ＝無此音（是「鹹」的讀音）；ㄐㄧㄢ＝無此音\n2. 國字拆解與造字原因\n箴：形聲字，「竹」＋「咸」（聲），本義是竹製的針——針刺引申為規勸告誡→箴言。與「針」同源，讀ㄓㄣ。"},
  {id:"p128",grade:8,word:"對峙",target:"峙",zhuyin:"ㄓˋ",pinyin:"zhì",wz:"ㄉㄨㄟˋ ㄓˋ",wrong:[{z:"ㄕˋ",p:"shì"},{z:"ㄙˋ",p:"sì"}],note:"「對峙」的「峙」讀ㄓˋ，相對而立。",deep:"1. 注音比較\n峙：ㄓˋ（四聲）＝對峙、聳峙；ㄕˋ＝無此音（是「侍」的讀音）；ㄙˋ＝無此音（是「寺」的讀音）\n2. 國字拆解與造字原因\n峙：形聲字，「山」＋「寺」（聲），山高聳立→聳峙；兩方像山一樣相對而立→對峙。從「寺」得聲卻讀ㄓˋ。"},
  {id:"p129",grade:8,word:"粗獷",target:"獷",zhuyin:"ㄍㄨㄤˇ",pinyin:"guǎng",wz:"ㄘㄨ ㄍㄨㄤˇ",wrong:[{z:"ㄎㄨㄤˋ",p:"kuàng"},{z:"ㄍㄨㄤ",p:"guāng"}],note:"「粗獷」的「獷」讀ㄍㄨㄤˇ，常被誤讀成ㄎㄨㄤˋ。",deep:"1. 注音比較\n獷：ㄍㄨㄤˇ（三聲）＝粗獷；ㄎㄨㄤˋ＝誤讀（受「礦」影響）；ㄍㄨㄤ＝無此音（是「光」的讀音）\n2. 國字拆解與造字原因\n獷：形聲字，「犭」＋「廣」（聲），本義是兇悍的犬，引申為粗野豪放→粗獷。讀ㄍㄨㄤˇ，常被誤讀成ㄎㄨㄤˋ。"},
  {id:"p130",grade:8,word:"糟蹋",target:"蹋",zhuyin:"ㄊㄚˋ",pinyin:"tà",wz:"ㄗㄠ ㄊㄚˋ",wrong:[{z:"ㄊㄚ",p:"tā"},{z:"ㄉㄚˋ",p:"dà"}],note:"「糟蹋」的「蹋」讀ㄊㄚˋ。",deep:"1. 注音比較\n蹋：ㄊㄚˋ（四聲）＝糟蹋；ㄊㄚ＝無此音（是「塌」的讀音）；ㄉㄚˋ＝無此音\n2. 國字拆解與造字原因\n蹋：形聲字，「足」＋「}（聲），用腳踩→「糟蹋」本指踐踏，引申為浪費、不愛惜。讀ㄊㄚˋ。"},
  {id:"p131",grade:8,word:"埋怨",target:"埋",zhuyin:"ㄇㄢˊ",pinyin:"mán",wz:"ㄇㄢˊ ㄩㄢˋ",wrong:[{z:"ㄇㄞˊ",p:"mái"},{z:"ㄇㄞˋ",p:"mài"}],note:"「埋怨」讀ㄇㄢˊ；「埋葬」「掩埋」讀ㄇㄞˊ。",deep:"1. 注音比較\n埋：ㄇㄢˊ（二聲）＝埋怨；ㄇㄞˊ（二聲）＝埋葬、掩埋、埋伏；ㄇㄞˋ＝無此音（是「賣」的讀音）\n2. 國字拆解與造字原因\n埋：「土」＋「里」（聲），把東西藏進土裡（ㄇㄞˊ）；心中怨氣悶著又發出來→「埋怨」（ㄇㄢˊ）。記法：只有「埋怨」讀ㄇㄢˊ。"},
  {id:"p132",grade:8,word:"造船廠",target:"廠",zhuyin:"ㄔㄤˇ",pinyin:"chǎng",wz:"ㄗㄠˋ ㄔㄨㄢˊ ㄔㄤˇ",wrong:[{z:"ㄔㄤˊ",p:"cháng"},{z:"ㄕㄤˇ",p:"shǎng"}],note:"「工廠」「廠房」的「廠」讀ㄔㄤˇ。",deep:"1. 注音比較\n廠：ㄔㄤˇ（三聲）＝工廠、廠房、造船廠；ㄔㄤˊ＝誤讀（受「場」影響）；ㄕㄤˇ＝無此音（是「賞」的讀音）\n2. 國字拆解與造字原因\n廠：從「广」（依山崖建的房），無牆或寬敞的作業屋舍→工廠。讀三聲ㄔㄤˇ。"},
  {id:"p133",grade:8,word:"堡壘",target:"壘",zhuyin:"ㄌㄟˇ",pinyin:"lěi",wz:"ㄅㄠˇ ㄌㄟˇ",wrong:[{z:"ㄌㄟˋ",p:"lèi"},{z:"ㄌㄩˇ",p:"lǚ"}],note:"「堡壘」「壁壘」的「壘」讀ㄌㄟˇ。",deep:"1. 注音比較\n壘：ㄌㄟˇ（三聲）＝堡壘、壁壘、兩軍對壘；ㄌㄟˋ＝誤讀（受「累」影響）；ㄌㄩˇ＝無此音（是「旅」的讀音）\n2. 國字拆解與造字原因\n壘：形聲字，「畾」（聲）＋「土」，堆土築成的軍事工事→堡壘、棒球的壘包。讀ㄌㄟˇ。"},
  {id:"p134",grade:8,word:"諂媚",target:"諂",zhuyin:"ㄔㄢˇ",pinyin:"chǎn",wz:"ㄔㄢˇ ㄇㄟˋ",wrong:[{z:"ㄒㄧㄢˋ",p:"xiàn"},{z:"ㄧㄢˋ",p:"yàn"}],note:"「諂媚」的「諂」讀ㄔㄢˇ，奉承巴結。",deep:"1. 注音比較\n諂：ㄔㄢˇ（三聲）＝諂媚、諂笑；ㄒㄧㄢˋ＝誤讀（受「陷」影響）；ㄧㄢˋ＝無此音\n2. 國字拆解與造字原因\n諂：形聲字，「言」＋「臽」（聲），用甜言蜜語奉承巴結→諂媚。讀ㄔㄢˇ，與「產」同音。"},
  {id:"p135",grade:8,word:"贊助",target:"贊",zhuyin:"ㄗㄢˋ",pinyin:"zàn",wz:"ㄗㄢˋ ㄓㄨˋ",wrong:[{z:"ㄗㄢ",p:"zān"},{z:"ㄘㄢˊ",p:"cán"}],note:"「贊助」「贊成」的「贊」讀ㄗㄢˋ。",deep:"1. 注音比較\n贊：ㄗㄢˋ（四聲）＝贊助、贊成、贊同；ㄗㄢ＝無此音（是「簪」的讀音）；ㄘㄢˊ＝無此音（是「殘」的讀音）\n2. 國字拆解與造字原因\n贊：從「貝」（財物），本義是進見時獻上財禮→輔助（贊助）、同意（贊成）。讀ㄗㄢˋ。"},
  {id:"p136",grade:8,word:"陷阱",target:"阱",zhuyin:"ㄐㄧㄥˇ",pinyin:"jǐng",wz:"ㄒㄧㄢˋ ㄐㄧㄥˇ",wrong:[{z:"ㄐㄧㄥˋ",p:"jìng"},{z:"ㄒㄧㄥˊ",p:"xíng"}],note:"「陷阱」的「阱」讀ㄐㄧㄥˇ。",deep:"1. 注音比較\n阱：ㄐㄧㄥˇ（三聲）＝陷阱；ㄐㄧㄥˋ＝誤讀；ㄒㄧㄥˊ＝無此音（是「刑」的讀音）\n2. 國字拆解與造字原因\n阱：形聲字，「阝（阜）」＋「井」（聲），捕獸的坑洞——像口井一樣的坑→陷阱。與「井」同讀三聲ㄐㄧㄥˇ。"},
  {id:"p137",grade:8,word:"竣工",target:"竣",zhuyin:"ㄐㄩㄣˋ",pinyin:"jùn",wz:"ㄐㄩㄣˋ ㄍㄨㄥ",wrong:[{z:"ㄙㄨㄣ",p:"sūn"},{z:"ㄑㄩㄣ",p:"qūn"}],note:"「竣工」的「竣」讀ㄐㄩㄣˋ，完成之意。",deep:"1. 注音比較\n竣：ㄐㄩㄣˋ（四聲）＝竣工、完竣；ㄙㄨㄣ＝無此音；ㄑㄩㄣ＝無此音\n2. 國字拆解與造字原因\n竣：形聲字，「立」＋「夋」（聲），事情做完、停立→竣工（工程完成）。與「峻」同音ㄐㄩㄣˋ。"},
  {id:"p138",grade:8,word:"魯莽",target:"莽",zhuyin:"ㄇㄤˇ",pinyin:"mǎng",wz:"ㄌㄨˇ ㄇㄤˇ",wrong:[{z:"ㄇㄤˊ",p:"máng"},{z:"ㄨㄤˇ",p:"wǎng"}],note:"「魯莽」「草莽」的「莽」讀ㄇㄤˇ。",deep:"1. 注音比較\n莽：ㄇㄤˇ（三聲）＝魯莽、草莽、莽撞；ㄇㄤˊ＝誤讀（受「忙」影響）；ㄨㄤˇ＝無此音\n2. 國字拆解與造字原因\n莽：會意字，「犬」在草叢（茻）中，本義是草深廣的樣子→草莽；行事像闖進草叢般冒失→魯莽。讀ㄇㄤˇ。"},
  {id:"p139",grade:8,word:"畏葸",target:"葸",zhuyin:"ㄒㄧˇ",pinyin:"xǐ",wz:"ㄨㄟˋ ㄒㄧˇ",wrong:[{z:"ㄙ",p:"sī"},{z:"ㄕㄞ",p:"shāi"}],note:"「畏葸不前」的「葸」讀ㄒㄧˇ，畏懼的樣子。",deep:"1. 注音比較\n葸：ㄒㄧˇ（三聲）＝畏葸不前；ㄙ＝無此音（是「思」的讀音）；ㄕㄞ＝無此音\n2. 國字拆解與造字原因\n葸：形聲字，「艹」＋「思」（聲），畏懼膽怯的樣子→畏葸不前（害怕而不敢前進）。讀ㄒㄧˇ。"},
  {id:"p140",grade:8,word:"星宿",target:"宿",zhuyin:"ㄒㄧㄡˋ",pinyin:"xiù",wz:"ㄒㄧㄥ ㄒㄧㄡˋ",wrong:[{z:"ㄙㄨˋ",p:"sù"},{z:"ㄒㄧㄡˇ",p:"xiǔ"}],note:"「星宿」讀ㄒㄧㄡˋ；「住宿」讀ㄙㄨˋ；「一宿」讀ㄒㄧㄡˇ。",deep:"1. 注音比較\n宿：ㄒㄧㄡˋ（四聲）＝星宿；ㄙㄨˋ（四聲）＝住宿、宿舍、宿願；ㄒㄧㄡˇ（三聲）＝一宿、整宿\n2. 國字拆解與造字原因\n宿：會意字，人在屋內蓆上過夜，本義是過夜（ㄙㄨˋ）；星辰的「住所」——星座讀ㄒㄧㄡˋ（星宿）；計算夜數讀ㄒㄧㄡˇ（住了一宿）。一字三音常考。"},
  {id:"p141",grade:9,word:"呱呱墜地",target:"呱",zhuyin:"ㄍㄨ",pinyin:"gū",wz:"ㄍㄨ ㄍㄨ ㄓㄨㄟˋ ㄉㄧˋ",wrong:[{z:"ㄍㄨㄚ",p:"guā"},{z:"ㄨㄚ",p:"wā"}],note:"「呱呱墜地」的「呱」讀ㄍㄨ，嬰兒哭聲。",deep:"1. 注音比較\n呱：ㄍㄨ（一聲）＝呱呱墜地；ㄍㄨㄚ（一聲）＝呱呱叫（鴨鳴、稱讚）；ㄨㄚ＝無此音（是「蛙」的讀音）\n2. 國字拆解與造字原因\n呱：形聲字，「口」＋「瓜」（聲），擬聲字。嬰兒的哭聲讀ㄍㄨ（呱呱墜地）；鴨叫或「頂呱呱」讀ㄍㄨㄚ。"},
  {id:"p142",grade:9,word:"暴虎馮河",target:"馮",zhuyin:"ㄆㄧㄥˊ",pinyin:"píng",wz:"ㄅㄠˋ ㄏㄨˇ ㄆㄧㄥˊ ㄏㄜˊ",wrong:[{z:"ㄈㄥˊ",p:"féng"},{z:"ㄆㄥˊ",p:"péng"}],note:"「暴虎馮河」的「馮」讀ㄆㄧㄥˊ，徒步渡河；姓氏讀ㄈㄥˊ。",deep:"1. 注音比較\n馮：ㄆㄧㄥˊ（二聲）＝暴虎馮河（徒步渡河）；ㄈㄥˊ（二聲）＝姓馮；ㄆㄥˊ＝無此音\n2. 國字拆解與造字原因\n馮：從「馬」、「冫」（聲），本義是馬行疾速。「暴虎馮河」（空手打虎、徒步渡河）的「馮」通「憑」，讀ㄆㄧㄥˊ；姓氏讀ㄈㄥˊ。"},
  {id:"p143",grade:9,word:"色厲內荏",target:"荏",zhuyin:"ㄖㄣˇ",pinyin:"rěn",wz:"ㄙㄜˋ ㄌㄧˋ ㄋㄟˋ ㄖㄣˇ",wrong:[{z:"ㄖㄣˋ",p:"rèn"},{z:"ㄋㄧㄢˇ",p:"niǎn"}],note:"「色厲內荏」的「荏」讀ㄖㄣˇ，軟弱之意。",deep:"1. 注音比較\n荏：ㄖㄣˇ（三聲）＝色厲內荏、光陰荏苒；ㄖㄣˋ＝誤讀（受「任」影響）；ㄋㄧㄢˇ＝無此音\n2. 國字拆解與造字原因\n荏：形聲字，「艹」＋「任」（聲），本義是白蘇（草本植物），莖葉柔弱→軟弱（色厲內荏＝外表強硬內心軟弱）。讀ㄖㄣˇ。"},
  {id:"p144",grade:9,word:"心廣體胖",target:"胖",zhuyin:"ㄆㄢˊ",pinyin:"pán",wz:"ㄒㄧㄣ ㄍㄨㄤˇ ㄊㄧˇ ㄆㄢˊ",wrong:[{z:"ㄆㄤˋ",p:"pàng"},{z:"ㄅㄢˋ",p:"bàn"}],note:"「心廣體胖」的「胖」讀ㄆㄢˊ，安舒之意。",deep:"1. 注音比較\n胖：ㄆㄢˊ（二聲）＝心廣體胖（安舒舒坦）；ㄆㄤˋ（四聲）＝肥胖、胖子；ㄅㄢˋ＝無此音\n2. 國字拆解與造字原因\n胖：形聲字，「月（肉）」＋「半」（聲），本義是祭祀用的半體牲肉。「心廣體胖」出自《大學》，指心胸寬廣則身體安舒，讀ㄆㄢˊ；肥胖義讀ㄆㄤˋ。"},
  {id:"p145",grade:9,word:"否極泰來",target:"否",zhuyin:"ㄆㄧˇ",pinyin:"pǐ",wz:"ㄆㄧˇ ㄐㄧˊ ㄊㄞˋ ㄌㄞˊ",wrong:[{z:"ㄈㄡˇ",p:"fǒu"},{z:"ㄆㄧˋ",p:"pì"}],note:"「否極泰來」「臧否」的「否」讀ㄆㄧˇ；「是否」讀ㄈㄡˇ。",deep:"1. 注音比較\n否：ㄆㄧˇ（三聲）＝否極泰來、臧否人物；ㄈㄡˇ（三聲）＝是否、否認、否決；ㄆㄧˋ＝無此音（是「僻」的讀音）\n2. 國字拆解與造字原因\n否：從「口」從「不」，本義是不然（ㄈㄡˇ）。《易經》的否卦（閉塞不通的壞運）讀ㄆㄧˇ——「否極泰來」＝壞運到頭好運來；評論好壞「臧否」也讀ㄆㄧˇ。"},
  {id:"p146",grade:9,word:"一曝十寒",target:"曝",zhuyin:"ㄆㄨˋ",pinyin:"pù",wz:"ㄧ ㄆㄨˋ ㄕˊ ㄏㄢˊ",wrong:[{z:"ㄅㄠˋ",p:"bào"},{z:"ㄆㄨ",p:"pū"}],note:"「一曝十寒」「曝曬」的「曝」讀ㄆㄨˋ。",deep:"1. 注音比較\n曝：ㄆㄨˋ（四聲）＝一曝十寒、曝曬、曝光；ㄅㄠˋ＝俗讀，審訂表不採；ㄆㄨ＝無此音\n2. 國字拆解與造字原因\n曝：「日」＋「暴」（聲），太陽下晒。「一曝十寒」出自《孟子》，晒一天凍十天，讀ㄆㄨˋ。"},
  {id:"p147",grade:9,word:"針砭",target:"砭",zhuyin:"ㄅㄧㄢ",pinyin:"biān",wz:"ㄓㄣ ㄅㄧㄢ",wrong:[{z:"ㄈㄚˊ",p:"fá"},{z:"ㄅㄧㄢˇ",p:"biǎn"}],note:"「針砭時弊」的「砭」讀ㄅㄧㄢ，古代石針。",deep:"1. 注音比較\n砭：ㄅㄧㄢ（一聲）＝針砭時弊、砭骨；ㄈㄚˊ＝無此音（是「乏」的讀音）；ㄅㄧㄢˇ＝誤讀（受「貶」影響）\n2. 國字拆解與造字原因\n砭：形聲字，「石」＋「乏」（聲），古代治病的石針→用言論刺醒世人（針砭時弊）。讀一聲ㄅㄧㄢ。"},
  {id:"p148",grade:9,word:"倥傯",target:"傯",zhuyin:"ㄗㄨㄥˇ",pinyin:"zǒng",wz:"ㄎㄨㄥˇ ㄗㄨㄥˇ",wrong:[{z:"ㄘㄨㄥ",p:"cōng"},{z:"ㄓㄨㄥˇ",p:"zhǒng"}],note:"「戎馬倥傯」讀ㄎㄨㄥˇ ㄗㄨㄥˇ，匆忙迫促。",deep:"1. 注音比較\n傯：ㄗㄨㄥˇ（三聲）＝戎馬倥傯；ㄘㄨㄥ＝無此音（是「匆」的讀音）；ㄓㄨㄥˇ＝無此音\n2. 國字拆解與造字原因\n傯：形聲字，「亻」＋「總」（聲），「倥傯」（ㄎㄨㄥˇ ㄗㄨㄥˇ）是連綿詞：事務匆迫繁忙——「戎馬倥傯」形容軍務繁忙。"},
  {id:"p149",grade:9,word:"鞭笞",target:"笞",zhuyin:"ㄔ",pinyin:"chī",wz:"ㄅㄧㄢ ㄔ",wrong:[{z:"ㄊㄞˊ",p:"tái"},{z:"ㄓˋ",p:"zhì"}],note:"「鞭笞」的「笞」讀ㄔ，用竹板抽打。",deep:"1. 注音比較\n笞：ㄔ（一聲）＝鞭笞、笞刑；ㄊㄞˊ＝無此音（是「臺」的讀音）；ㄓˋ＝無此音\n2. 國字拆解與造字原因\n笞：形聲字，「竹」＋「台」（聲），用竹板抽打→鞭笞、笞刑（古代五刑之一）。讀ㄔ。"},
  {id:"p150",grade:9,word:"晌午",target:"晌",zhuyin:"ㄕㄤˇ",pinyin:"shǎng",wz:"ㄕㄤˇ ˙ㄏㄨㄛ",wrong:[{z:"ㄒㄧㄤˇ",p:"xiǎng"},{z:"ㄕㄤˋ",p:"shàng"}],note:"「晌午」的「晌」讀ㄕㄤˇ，正午時分。",deep:"1. 注音比較\n晌：ㄕㄤˇ（三聲）＝晌午、半晌；ㄒㄧㄤˇ＝無此音（是「響」的讀音）；ㄕㄤˋ＝無此音（是「上」的讀音）\n2. 國字拆解與造字原因\n晌：形聲字，「日」＋「向」（聲），白天的一段時間→晌午（正午）、半晌（好一會兒）。「晌」讀ㄕㄤˇ；教育部審訂「晌午」整詞讀ㄕㄤˇ ˙ㄏㄨㄛ，後一字讀輕聲ㄏㄨㄛ，不讀ㄨˇ。"},
  {id:"p151",grade:9,word:"憤懣",target:"懣",zhuyin:"ㄇㄣˋ",pinyin:"mèn",wz:"ㄈㄣˋ ㄇㄣˋ",wrong:[{z:"ㄇㄢˇ",p:"mǎn"},{z:"ㄇㄢˊ",p:"mán"}],note:"「憤懣」的「懣」讀ㄇㄣˋ，煩悶怨怒。",deep:"1. 注音比較\n懣：ㄇㄣˋ（四聲）＝憤懣；ㄇㄢˇ＝誤讀（受「滿」影響）；ㄇㄢˊ＝無此音（是「瞞」的讀音）\n2. 國字拆解與造字原因\n懣：形聲字，「心」＋「滿」（聲），心中脹滿煩怨→憤懣（憤怒鬱悶）。讀ㄇㄣˋ，與「悶」同音。"},
  {id:"p152",grade:9,word:"惺忪",target:"忪",zhuyin:"ㄙㄨㄥ",pinyin:"sōng",wz:"ㄒㄧㄥ ㄙㄨㄥ",wrong:[{z:"ㄓㄨㄥ",p:"zhōng"},{z:"ㄍㄨㄥ",p:"gōng"}],note:"教育部審訂音「惺忪」的「忪」讀ㄙㄨㄥ；「怔忪」（驚懼）才讀ㄓㄨㄥ。",deep:"1. 注音比較\n忪：ㄙㄨㄥ＝惺忪（睡眼惺忪）；ㄓㄨㄥ＝怔忪（驚懼不安）。★「惺忪」教育部審訂音讀ㄒㄧㄥ ㄙㄨㄥ，整詞讀ㄓㄨㄥ不是審訂音\n2. 國字拆解與造字原因\n忪：形聲字，「忄（心）」＋「公」（聲），與心理狀態有關所以從心部。「睡眼惺忪」形容剛睡醒眼神迷糊。"},
  {id:"p153",grade:9,word:"蹣跚",target:"蹣",zhuyin:"ㄇㄢˊ",pinyin:"mán",wz:"ㄇㄢˊ ㄕㄢ",wrong:[{z:"ㄆㄢˊ",p:"pán"},{z:"ㄅㄢˋ",p:"bàn"}],note:"教育部審訂音「蹣跚」的「蹣」讀ㄇㄢˊ，是走路搖晃不穩的樣子。",deep:"1. 注音比較\n蹣：ㄇㄢˊ＝蹣跚（步履蹣跚）。★教育部《國語辭典簡編本》「蹣」只收ㄇㄢˊ一音，讀成ㄆㄢˊ不是審訂音\n2. 國字拆解與造字原因\n蹣：形聲字，「足」＋「㒼」（聲），與走路有關所以從足部。「蹣跚」是連綿詞，兩字不能拆開解釋，形容腿腳不便、走起來搖搖晃晃。"},
  {id:"p154",grade:9,word:"躊躇",target:"躇",zhuyin:"ㄔㄨˊ",pinyin:"chú",wz:"ㄔㄡˊ ㄔㄨˊ",wrong:[{z:"ㄓㄨˊ",p:"zhú"},{z:"ㄔㄨˋ",p:"chù"}],note:"「躊躇」讀ㄔㄡˊ ㄔㄨˊ，猶豫不決。",deep:"1. 注音比較\n躇：ㄔㄨˊ（二聲）＝躊躇；ㄓㄨˊ＝無此音（是「竹」的讀音）；ㄔㄨˋ＝無此音（「躊躇滿志」亦讀ㄔㄨˊ）\n2. 國字拆解與造字原因\n躇：形聲字，「足」＋「著」（聲），「躊躇」（ㄔㄡˊ ㄔㄨˊ）是連綿詞：腳步徘徊、猶豫不前。"},
  {id:"p155",grade:9,word:"饕餮",target:"餮",zhuyin:"ㄊㄧㄝˋ",pinyin:"tiè",wz:"ㄊㄠ ㄊㄧㄝˋ",wrong:[{z:"ㄊㄧㄢ",p:"tiān"},{z:"ㄉㄧㄝˊ",p:"dié"}],note:"「饕餮」讀ㄊㄠ ㄊㄧㄝˋ，傳說中貪食的惡獸。",deep:"1. 注音比較\n餮：ㄊㄧㄝˋ（四聲）＝饕餮；ㄊㄧㄢ＝無此音（是「天」的讀音）；ㄉㄧㄝˊ＝無此音\n2. 國字拆解與造字原因\n餮：從「食」，「饕餮」（ㄊㄠ ㄊㄧㄝˋ）是傳說中貪吃的凶獸，商周鼎彝常鑄其紋→比喻貪吃或貪婪的人（饕客的「饕」由此來）。"},
  {id:"p156",grade:9,word:"贛江",target:"贛",zhuyin:"ㄍㄢˋ",pinyin:"gàn",wz:"ㄍㄢˋ ㄐㄧㄤ",wrong:[{z:"ㄓㄤˋ",p:"zhàng"},{z:"ㄍㄨㄥˋ",p:"gòng"}],note:"「贛」讀ㄍㄢˋ，江西省的簡稱。",deep:"1. 注音比較\n贛：ㄍㄢˋ（四聲）＝贛江、贛（江西簡稱）；ㄓㄤˋ＝無此音；ㄍㄨㄥˋ＝無此音（是「貢」的讀音）\n2. 國字拆解與造字原因\n贛：從「貝」，本義是賜給。江西的贛江、江西省簡稱「贛」讀ㄍㄢˋ。"},
  {id:"p157",grade:9,word:"皈依",target:"皈",zhuyin:"ㄍㄨㄟ",pinyin:"guī",wz:"ㄍㄨㄟ ㄧ",wrong:[{z:"ㄈㄢˇ",p:"fǎn"},{z:"ㄅㄢ",p:"bān"}],note:"「皈依」的「皈」讀ㄍㄨㄟ，歸信宗教。",deep:"1. 注音比較\n皈：ㄍㄨㄟ（一聲）＝皈依；ㄈㄢˇ＝無此音（是「反」的讀音）；ㄅㄢ＝無此音\n2. 國字拆解與造字原因\n皈：從「白」從「反」，是「歸」的俗字分化——「皈依」即歸投依靠（信仰宗教）。與「歸」同音ㄍㄨㄟ。"},
  {id:"p158",grade:9,word:"整飭",target:"飭",zhuyin:"ㄔˋ",pinyin:"chì",wz:"ㄓㄥˇ ㄔˋ",wrong:[{z:"ㄕˋ",p:"shì"},{z:"ㄙˋ",p:"sì"}],note:"「整飭」的「飭」讀ㄔˋ，整頓之意，勿與「飾」混淆。",deep:"1. 注音比較\n飭：ㄔˋ（四聲）＝整飭、飭令；ㄕˋ＝無此音（是「飾」的讀音）；ㄙˋ＝無此音\n2. 國字拆解與造字原因\n飭：從「人」「力」與「食（省）」，本義是整治、使謹嚴→整飭（整頓）、申飭（告誡）。與「飾」（ㄕˋ，裝飾）形近音異，常考。"},
  {id:"p159",grade:9,word:"熨貼",target:"熨",zhuyin:"ㄩˋ",pinyin:"yù",wz:"ㄩˋ ㄊㄧㄝ",wrong:[{z:"ㄩㄣˋ",p:"yùn"},{z:"ㄨㄟˋ",p:"wèi"}],note:"「熨貼」（妥適）讀ㄩˋ；「熨斗」讀ㄩㄣˋ。",deep:"1. 注音比較\n熨：ㄩˋ（四聲）＝熨貼（妥適舒坦）；ㄩㄣˋ（四聲）＝熨斗、熨衣服；ㄨㄟˋ＝無此音\n2. 國字拆解與造字原因\n熨：從「火」，用加熱的金屬器把衣物壓平。燙衣讀ㄩㄣˋ（熨斗）；「熨貼」（心裡舒坦、用字妥當）讀ㄩˋ。"},
  {id:"p160",grade:9,word:"氤氳",target:"氳",zhuyin:"ㄩㄣ",pinyin:"yūn",wz:"ㄧㄣ ㄩㄣ",wrong:[{z:"ㄨㄣ",p:"wēn"},{z:"ㄩㄣˊ",p:"yún"}],note:"「氤氳」讀ㄧㄣ ㄩㄣ，煙氣瀰漫的樣子。",deep:"1. 注音比較\n氳：ㄩㄣ（一聲）＝氤氳；ㄨㄣ＝無此音（是「溫」的讀音）；ㄩㄣˊ＝誤讀（受「雲」影響）\n2. 國字拆解與造字原因\n氳：形聲字，「气」＋「昷」（聲），「氤氳」（ㄧㄣ ㄩㄣ）是連綿詞：煙雲瀰漫的樣子。"},
  {id:"p161",grade:9,word:"拈花惹草",target:"拈",zhuyin:"ㄋㄧㄢˊ",pinyin:"nián",wz:"ㄋㄧㄢˊ ㄏㄨㄚ ㄖㄜˇ ㄘㄠˇ",wrong:[{z:"ㄓㄢ",p:"zhān"},{z:"ㄋㄧㄢˇ",p:"niǎn"}],note:"「拈」讀ㄋㄧㄢˊ，用指尖夾取。",deep:"1. 注音比較\n拈：ㄋㄧㄢˊ（二聲）＝拈花惹草、信手拈來；ㄓㄢ＝無此音（是「沾」的讀音）；ㄋㄧㄢˇ＝誤讀（受「捻」影響）\n2. 國字拆解與造字原因\n拈：形聲字，「扌」＋「占」（聲），用手指輕輕夾取→信手拈來。讀ㄋㄧㄢˊ，與「捻」（ㄋㄧㄢˇ，搓）不同。"},
  {id:"p162",grade:9,word:"根深柢固",target:"柢",zhuyin:"ㄉㄧˇ",pinyin:"dǐ",wz:"ㄍㄣ ㄕㄣ ㄉㄧˇ ㄍㄨˋ",wrong:[{z:"ㄓˇ",p:"zhǐ"},{z:"ㄉㄧˋ",p:"dì"}],note:"「根深柢固」的「柢」讀ㄉㄧˇ，樹根。",deep:"1. 注音比較\n柢：ㄉㄧˇ（三聲）＝根深柢固；ㄓˇ＝無此音；ㄉㄧˋ＝誤讀（受「帝」影響）\n2. 國字拆解與造字原因\n柢：形聲字，「木」＋「氐」（聲），樹木的主根→根深柢固（根基深固）。讀ㄉㄧˇ，與「底」同音。"},
  {id:"p163",grade:9,word:"傴僂",target:"僂",zhuyin:"ㄌㄡˊ",pinyin:"lóu",wz:"ㄩˇ ㄌㄡˊ",wrong:[{z:"ㄌㄩˇ",p:"lǚ"},{z:"ㄌㄡˋ",p:"lòu"}],note:"「傴僂」讀ㄩˇ ㄌㄡˊ，駝背彎腰。",deep:"1. 注音比較\n僂：ㄌㄡˊ（二聲）＝傴僂（ㄩˇ ㄌㄡˊ）；ㄌㄩˇ＝「佝僂病」另讀；ㄌㄡˋ＝無此音（是「陋」的讀音）\n2. 國字拆解與造字原因\n僂：形聲字，「亻」＋「婁」（聲），背脊彎曲→傴僂（駝背）。讀ㄌㄡˊ。"},
  {id:"p164",grade:9,word:"骨鯁在喉",target:"鯁",zhuyin:"ㄍㄥˇ",pinyin:"gěng",wz:"ㄍㄨˇ ㄍㄥˇ ㄗㄞˋ ㄏㄡˊ",wrong:[{z:"ㄍㄥ",p:"gēng"},{z:"ㄏㄡˊ",p:"hóu"}],note:"「骨鯁在喉」的「鯁」讀ㄍㄥˇ，魚刺卡喉。",deep:"1. 注音比較\n鯁：ㄍㄥˇ（三聲）＝骨鯁在喉、骨鯁之臣；ㄍㄥ＝誤讀；ㄏㄡˊ＝無此音（是「喉」的讀音）\n2. 國字拆解與造字原因\n鯁：形聲字，「魚」＋「更」（聲），魚骨、魚刺→骨鯁在喉（有話不吐不快）；魚骨正直不彎→正直敢言（骨鯁之臣）。讀ㄍㄥˇ。"},
  {id:"p165",grade:9,word:"僭越",target:"僭",zhuyin:"ㄐㄧㄢˋ",pinyin:"jiàn",wz:"ㄐㄧㄢˋ ㄩㄝˋ",wrong:[{z:"ㄑㄧㄢˊ",p:"qián"},{z:"ㄗㄢˋ",p:"zàn"}],note:"「僭越」的「僭」讀ㄐㄧㄢˋ，超越本分。",deep:"1. 注音比較\n僭：ㄐㄧㄢˋ（四聲）＝僭越、僭稱；ㄑㄧㄢˊ＝無此音（是「潛」的讀音）；ㄗㄢˋ＝無此音（是「贊」的讀音）\n2. 國字拆解與造字原因\n僭：形聲字，「亻」＋「朁」（聲），超越自己的身分冒用上位者的名義職權→僭越。讀ㄐㄧㄢˋ。"},
  {id:"p166",grade:10,word:"呶呶不休",target:"呶",zhuyin:"ㄋㄠˊ",pinyin:"náo",wz:"ㄋㄠˊ ㄋㄠˊ ㄅㄨˋ ㄒㄧㄡ",wrong:[{z:"ㄋㄨˊ",p:"nú"},{z:"ㄉㄨ",p:"dū"}],note:"「呶呶不休」的「呶」讀ㄋㄠˊ，喋喋不休。",deep:"1. 注音比較\n呶：ㄋㄠˊ（二聲）＝呶呶不休；ㄋㄨˊ＝無此音（是「奴」的讀音）；ㄉㄨ＝無此音\n2. 國字拆解與造字原因\n呶：形聲字，「口」＋「奴」（聲），喧鬧多言→呶呶不休（說個不停）。讀ㄋㄠˊ。"},
  {id:"p167",grade:10,word:"齟齬",target:"齬",zhuyin:"ㄩˇ",pinyin:"yǔ",wz:"ㄐㄩˇ ㄩˇ",wrong:[{z:"ㄨˇ",p:"wǔ"},{z:"ㄩˊ",p:"yú"}],note:"「齟齬」讀ㄐㄩˇ ㄩˇ，意見不合。",deep:"1. 注音比較\n齬：ㄩˇ（三聲）＝齟齬；ㄨˇ＝無此音（是「五」的讀音）；ㄩˊ＝誤讀（受「吾」影響）\n2. 國字拆解與造字原因\n齬：形聲字，「齒」＋「吾」（聲），「齟齬」（ㄐㄩˇ ㄩˇ）本指上下牙齒對不齊→意見不合、不融洽。"},
  {id:"p168",grade:10,word:"抵牾",target:"牾",zhuyin:"ㄨˇ",pinyin:"wǔ",wz:"ㄉㄧˇ ㄨˇ",wrong:[{z:"ㄨˊ",p:"wú"},{z:"ㄧㄡˇ",p:"yǒu"}],note:"「抵牾」的「牾」讀ㄨˇ，牴觸矛盾。",deep:"1. 注音比較\n牾：ㄨˇ（三聲）＝抵牾；ㄨˊ＝誤讀（受「吾」影響）；ㄧㄡˇ＝無此音\n2. 國字拆解與造字原因\n牾：形聲字，「牛」＋「吾」（聲），本義是逆、相牴觸→抵牾（互相矛盾）。讀ㄨˇ。"},
  {id:"p169",grade:10,word:"倨傲",target:"倨",zhuyin:"ㄐㄩˋ",pinyin:"jù",wz:"ㄐㄩˋ ㄠˋ",wrong:[{z:"ㄐㄩ",p:"jū"},{z:"ㄍㄨˋ",p:"gù"}],note:"「前倨後恭」的「倨」讀ㄐㄩˋ，傲慢。",deep:"1. 注音比較\n倨：ㄐㄩˋ（四聲）＝前倨後恭、倨傲；ㄐㄩ＝誤讀（受「居」影響）；ㄍㄨˋ＝無此音\n2. 國字拆解與造字原因\n倨：形聲字，「亻」＋「居」（聲），態度傲慢→倨傲；「前倨後恭」指先傲慢後恭敬。讀ㄐㄩˋ。"},
  {id:"p170",grade:10,word:"睥睨",target:"睨",zhuyin:"ㄋㄧˋ",pinyin:"nì",wz:"ㄅㄧˋ ㄋㄧˋ",wrong:[{z:"ㄧˊ",p:"yí"},{z:"ㄋㄧˊ",p:"ní"}],note:"「睥睨」讀ㄅㄧˋ ㄋㄧˋ，斜眼傲視。",deep:"1. 注音比較\n睨：ㄋㄧˋ（四聲）＝睥睨、睨視；ㄧˊ＝無此音；ㄋㄧˊ＝誤讀（受「泥」影響）\n2. 國字拆解與造字原因\n睨：形聲字，「目」＋「兒」（聲），斜著眼看→睥睨（ㄅㄧˋ ㄋㄧˋ，斜眼傲視一切）。讀ㄋㄧˋ。"},
  {id:"p171",grade:10,word:"訾議",target:"訾",zhuyin:"ㄗˇ",pinyin:"zǐ",wz:"ㄗˇ ㄧˋ",wrong:[{z:"ㄘˊ",p:"cí"},{z:"ㄗ",p:"zī"}],note:"「無可訾議」的「訾」讀ㄗˇ，詆毀批評。",deep:"1. 注音比較\n訾：ㄗˇ（三聲）＝訾議、無可訾議；ㄘˊ＝無此音（是「詞」的讀音）；ㄗ＝姓氏讀音\n2. 國字拆解與造字原因\n訾：形聲字，「言」＋「此」（聲），用言語詆毀批評→訾議（非議）。讀ㄗˇ。"},
  {id:"p172",grade:10,word:"謾罵",target:"謾",zhuyin:"ㄇㄢˋ",pinyin:"màn",wz:"ㄇㄢˋ ㄇㄚˋ",wrong:[{z:"ㄇㄢˊ",p:"mán"},{z:"ㄨㄢˋ",p:"wàn"}],note:"「謾罵」的「謾」讀ㄇㄢˋ；「欺謾」讀ㄇㄢˊ。",deep:"1. 注音比較\n謾：ㄇㄢˋ（四聲）＝謾罵；ㄇㄢˊ（二聲）＝欺謾（欺騙）；ㄨㄢˋ＝無此音\n2. 國字拆解與造字原因\n謾：形聲字，「言」＋「曼」（聲）。輕慢無禮地罵讀ㄇㄢˋ（謾罵）；欺瞞義讀ㄇㄢˊ。記法：罵人ㄇㄢˋ、欺騙ㄇㄢˊ。"},
  {id:"p173",grade:10,word:"羞赧",target:"赧",zhuyin:"ㄋㄢˇ",pinyin:"nǎn",wz:"ㄒㄧㄡ ㄋㄢˇ",wrong:[{z:"ㄋㄢˊ",p:"nán"},{z:"ㄏㄢˇ",p:"hǎn"}],note:"「羞赧」的「赧」讀ㄋㄢˇ，因害羞而臉紅。",deep:"1. 注音比較\n赧：ㄋㄢˇ（三聲）＝羞赧、赧然；ㄋㄢˊ＝誤讀（受「難」影響）；ㄏㄢˇ＝無此音\n2. 國字拆解與造字原因\n赧：從「赤」（紅）從「𠬝」，因羞愧而臉紅→羞赧。從「赤」表意，讀ㄋㄢˇ。"},
  {id:"p174",grade:10,word:"造次",target:"造",zhuyin:"ㄗㄠˋ",pinyin:"zào",wz:"ㄗㄠˋ ㄘˋ",wrong:[{z:"ㄘㄠˋ",p:"cào"},{z:"ㄗㄠˇ",p:"zǎo"}],note:"「造次」讀ㄗㄠˋ ㄘˋ，魯莽輕率。",deep:"1. 注音比較\n造：ㄗㄠˋ（四聲）＝造次（魯莽）、建造；ㄘㄠˋ＝無此音；ㄗㄠˇ＝無此音（是「早」的讀音）\n2. 國字拆解與造字原因\n造：形聲字，「辶」＋「告」（聲），本義是到達→建造。「造次」（倉促、魯莽）出自《論語》「造次必於是」，讀ㄗㄠˋ ㄘˋ。"},
  {id:"p175",grade:10,word:"倏忽",target:"倏",zhuyin:"ㄕㄨˋ",pinyin:"shù",wz:"ㄕㄨˋ ㄏㄨ",wrong:[{z:"ㄊㄧㄠˊ",p:"tiáo"},{z:"ㄕㄨ",p:"shū"}],note:"「倏忽」的「倏」讀ㄕㄨˋ，極快地。",deep:"1. 注音比較\n倏：ㄕㄨˋ（四聲）＝倏忽、倏地；ㄊㄧㄠˊ＝無此音（是「條」的讀音）；ㄕㄨ＝誤讀\n2. 國字拆解與造字原因\n倏：從「犬」，本義是狗快速奔跑→迅速（倏忽＝一眨眼）。讀ㄕㄨˋ，與「條」形近，注意分辨。"},
  {id:"p176",grade:10,word:"間不容髮",target:"間",zhuyin:"ㄐㄧㄢˋ",pinyin:"jiàn",wz:"ㄐㄧㄢˋ ㄅㄨˋ ㄖㄨㄥˊ ㄈㄚˇ",wrong:[{z:"ㄐㄧㄢ",p:"jiān"},{z:"ㄒㄧㄢˊ",p:"xián"}],note:"「間不容髮」的「間」讀ㄐㄧㄢˋ，空隙之意。",deep:"1. 注音比較\n間：ㄐㄧㄢˋ（四聲）＝間不容髮、間隔、離間；ㄐㄧㄢ（一聲）＝中間、時間；ㄒㄧㄢˊ＝無此音（「閒」的讀音）\n2. 國字拆解與造字原因\n間：門縫中見月光，本義是縫隙。「間不容髮」＝縫隙容不下一根頭髮（危急），「間」取縫隙義讀ㄐㄧㄢˋ。"},
  {id:"p177",grade:10,word:"愀然",target:"愀",zhuyin:"ㄑㄧㄠˇ",pinyin:"qiǎo",wz:"ㄑㄧㄠˇ ㄖㄢˊ",wrong:[{z:"ㄐㄧㄡ",p:"jiū"},{z:"ㄑㄧㄡ",p:"qiū"}],note:"「愀然變色」的「愀」讀ㄑㄧㄠˇ，神色驟變。",deep:"1. 注音比較\n愀：ㄑㄧㄠˇ（三聲）＝愀然變色；ㄐㄧㄡ＝無此音；ㄑㄧㄡ＝無此音（是「秋」的讀音）\n2. 國字拆解與造字原因\n愀：形聲字，「忄」＋「秋」（聲），神色驟然轉為嚴肅憂戚→愀然。讀ㄑㄧㄠˇ。"},
  {id:"p178",grade:10,word:"稗官野史",target:"稗",zhuyin:"ㄅㄞˋ",pinyin:"bài",wz:"ㄅㄞˋ ㄍㄨㄢ ㄧㄝˇ ㄕˇ",wrong:[{z:"ㄅㄟ",p:"bēi"},{z:"ㄆㄞˊ",p:"pái"}],note:"「稗官野史」的「稗」讀ㄅㄞˋ。",deep:"1. 注音比較\n稗：ㄅㄞˋ（四聲）＝稗官野史、稗子；ㄅㄟ＝誤讀（受「卑」影響）；ㄆㄞˊ＝無此音\n2. 國字拆解與造字原因\n稗：形聲字，「禾」＋「卑」（聲），田裡像稻的雜草——卑微的禾→瑣碎非正統（稗官野史＝民間瑣聞）。讀ㄅㄞˋ。"},
  {id:"p179",grade:10,word:"畚箕",target:"畚",zhuyin:"ㄅㄣˇ",pinyin:"běn",wz:"ㄅㄣˇ ㄐㄧ",wrong:[{z:"ㄈㄣˋ",p:"fèn"},{z:"ㄅㄣˋ",p:"bèn"}],note:"「畚箕」讀ㄅㄣˇ ㄐㄧ。",deep:"1. 注音比較\n畚：ㄅㄣˇ（三聲）＝畚箕；ㄈㄣˋ＝無此音（是「糞」的讀音）；ㄅㄣˋ＝無此音（是「笨」的讀音）\n2. 國字拆解與造字原因\n畚：從「田」，盛土石垃圾的器具→畚箕（ㄅㄣˇ ㄐㄧ）。讀ㄅㄣˇ，與「本」同音。"},
  {id:"p180",grade:10,word:"蒞臨",target:"蒞",zhuyin:"ㄌㄧˋ",pinyin:"lì",wz:"ㄌㄧˋ ㄌㄧㄣˊ",wrong:[{z:"ㄨㄟˋ",p:"wèi"},{z:"ㄌㄨㄟˋ",p:"luì"}],note:"「蒞臨」的「蒞」讀ㄌㄧˋ，到來之意。",deep:"1. 注音比較\n蒞：ㄌㄧˋ（四聲）＝蒞臨、蒞會；ㄨㄟˋ＝無此音（是「位」的讀音）；ㄌㄨㄟˋ＝無此音\n2. 國字拆解與造字原因\n蒞：形聲字，「艹」＋「涖（省）」，親自到來→蒞臨指導。讀ㄌㄧˋ，與「立」同音。"},
  {id:"p181",grade:10,word:"骨骸",target:"骸",zhuyin:"ㄏㄞˊ",pinyin:"hái",wz:"ㄍㄨˇ ㄏㄞˊ",wrong:[{z:"ㄍㄞ",p:"gāi"},{z:"ㄏㄜˊ",p:"hé"}],note:"「骸骨」「遺骸」的「骸」讀ㄏㄞˊ。",deep:"1. 注音比較\n骸：ㄏㄞˊ（二聲）＝骸骨、遺骸、殘骸；ㄍㄞ＝無此音（是「該」的讀音）；ㄏㄜˊ＝無此音\n2. 國字拆解與造字原因\n骸：形聲字，「骨」＋「亥」（聲），本義是脛骨，泛指骨骸→遺骸、殘骸。讀ㄏㄞˊ，與「孩」同音。"},
  {id:"p182",grade:10,word:"踉蹌",target:"蹌",zhuyin:"ㄑㄧㄤˋ",pinyin:"qiàng",wz:"ㄌㄧㄤˋ ㄑㄧㄤˋ",wrong:[{z:"ㄑㄧㄤ",p:"qiāng"},{z:"ㄘㄤ",p:"cāng"}],note:"「踉蹌」讀ㄌㄧㄤˋ ㄑㄧㄤˋ，走路不穩。",deep:"1. 注音比較\n蹌：ㄑㄧㄤˋ（四聲）＝踉蹌；ㄑㄧㄤ＝誤讀；ㄘㄤ＝無此音（是「倉」的讀音）\n2. 國字拆解與造字原因\n蹌：形聲字，「足」＋「倉」（聲），「踉蹌」（ㄌㄧㄤˋ ㄑㄧㄤˋ）形容腳步歪斜不穩。"},
  {id:"p183",grade:10,word:"糾葛",target:"葛",zhuyin:"ㄍㄜˊ",pinyin:"gé",wz:"ㄐㄧㄡ ㄍㄜˊ",wrong:[{z:"ㄍㄜˇ",p:"gě"},{z:"ㄏㄜˊ",p:"hé"}],note:"「糾葛」「瓜葛」的「葛」讀ㄍㄜˊ；姓氏讀ㄍㄜˇ。",deep:"1. 注音比較\n葛：ㄍㄜˊ（二聲）＝糾葛、瓜葛、葛藤；ㄍㄜˇ（三聲）＝姓氏（諸葛）；ㄏㄜˊ＝無此音\n2. 國字拆解與造字原因\n葛：形聲字，「艹」＋「曷」（聲），藤本植物，莖皮可織布——藤蔓纏繞→糾葛、瓜葛（牽連）。植物與牽連義讀ㄍㄜˊ；姓氏讀ㄍㄜˇ。"},
  {id:"p184",grade:10,word:"蓊鬱",target:"蓊",zhuyin:"ㄨㄥˇ",pinyin:"wěng",wz:"ㄨㄥˇ ㄩˋ",wrong:[{z:"ㄨㄥ",p:"wēng"},{z:"ㄇㄥˊ",p:"méng"}],note:"「蓊鬱」的「蓊」讀ㄨㄥˇ，草木茂盛。",deep:"1. 注音比較\n蓊：ㄨㄥˇ（三聲）＝蓊鬱、蓊蓊鬱鬱；ㄨㄥ＝誤讀；ㄇㄥˊ＝無此音\n2. 國字拆解與造字原因\n蓊：形聲字，「艹」＋「翁」（聲），草木茂盛的樣子→蓊鬱。讀ㄨㄥˇ。"},
  {id:"p185",grade:10,word:"倭寇",target:"倭",zhuyin:"ㄨㄛ",pinyin:"wō",wz:"ㄨㄛ ㄎㄡˋ",wrong:[{z:"ㄨㄟ",p:"wēi"},{z:"ㄨㄛˇ",p:"wǒ"}],note:"「倭寇」的「倭」讀ㄨㄛ。",deep:"1. 注音比較\n倭：ㄨㄛ（一聲）＝倭寇；ㄨㄟ＝古音（倭遲）；ㄨㄛˇ＝誤讀\n2. 國字拆解與造字原因\n倭：形聲字，「亻」＋「委」（聲），古代對日本的稱呼→倭寇（明代侵擾沿海的日本海盜）。讀ㄨㄛ。"},
  {id:"p186",grade:11,word:"莞爾而笑",target:"爾",zhuyin:"ㄦˇ",pinyin:"ěr",wz:"ㄨㄢˇ ㄦˇ ㄦˊ ㄒㄧㄠˋ",wrong:[{z:"ㄦˊ",p:"ér"},{z:"ㄋㄧˇ",p:"nǐ"}],note:"「莞爾」讀ㄨㄢˇ ㄦˇ，微笑的樣子。",deep:"1. 注音比較\n爾：ㄦˇ（三聲）＝莞爾、偶爾、爾後；ㄦˊ＝無此音（是「而」的讀音）；ㄋㄧˇ＝無此音（是「你」的讀音）\n2. 國字拆解與造字原因\n爾：象形字，本義是織布的筘，假借為「你、那、如此」→「莞爾」（ㄨㄢˇ ㄦˇ）是微笑的樣子（《論語》「夫子莞爾而笑」）。"},
  {id:"p187",grade:11,word:"蜷曲",target:"蜷",zhuyin:"ㄑㄩㄢˊ",pinyin:"quán",wz:"ㄑㄩㄢˊ ㄑㄩ",wrong:[{z:"ㄐㄩㄢˇ",p:"juǎn"},{z:"ㄑㄩㄢ",p:"quān"}],note:"「蜷曲」「蜷伏」的「蜷」讀ㄑㄩㄢˊ。",deep:"1. 注音比較\n蜷：ㄑㄩㄢˊ（二聲）＝蜷曲、蜷伏、蜷縮；ㄐㄩㄢˇ＝無此音（是「捲」的讀音）；ㄑㄩㄢ＝誤讀\n2. 國字拆解與造字原因\n蜷：形聲字，「虫」＋「卷」（聲），蟲類身體彎曲成團→蜷曲、蜷縮。讀ㄑㄩㄢˊ，與「拳」同音（縮成一拳）。"},
  {id:"p188",grade:11,word:"殷紅",target:"殷",zhuyin:"ㄧㄢ",pinyin:"yān",wz:"ㄧㄢ ㄏㄨㄥˊ",wrong:[{z:"ㄧㄣ",p:"yīn"},{z:"ㄧㄢˇ",p:"yǎn"}],note:"「殷紅」（深紅色）讀ㄧㄢ；「殷勤」「殷商」讀ㄧㄣ。",deep:"1. 注音比較\n殷：ㄧㄢ（一聲）＝殷紅（深紅帶黑）；ㄧㄣ（一聲）＝殷勤、殷實、殷商；ㄧㄢˇ＝無此音\n2. 國字拆解與造字原因\n殷：本義是盛大（ㄧㄣ）；形容深紅色時讀ㄧㄢ（殷紅的血跡）。記法：顏色讀ㄧㄢ，其餘讀ㄧㄣ。"},
  {id:"p189",grade:11,word:"戲謔",target:"謔",zhuyin:"ㄋㄩㄝˋ",pinyin:"nüè",wz:"ㄒㄧˋ ㄋㄩㄝˋ",wrong:[{z:"ㄒㄩㄝˋ",p:"xuè"},{z:"ㄩㄝˋ",p:"yuè"}],note:"「戲謔」的「謔」讀ㄋㄩㄝˋ，開玩笑。",deep:"1. 注音比較\n謔：ㄋㄩㄝˋ（四聲）＝戲謔、謔而不虐（審訂音）；ㄒㄩㄝˋ＝俗讀，審訂表不採；ㄩㄝˋ＝無此音\n2. 國字拆解與造字原因\n謔：形聲字，「言」＋「虐」（聲），用言語開玩笑→戲謔。審訂音讀ㄋㄩㄝˋ。"},
  {id:"p190",grade:11,word:"炮製",target:"炮",zhuyin:"ㄆㄠˊ",pinyin:"páo",wz:"ㄆㄠˊ ㄓˋ",wrong:[{z:"ㄆㄠˋ",p:"pào"},{z:"ㄅㄠ",p:"bāo"}],note:"「如法炮製」的「炮」讀ㄆㄠˊ；「炮火」讀ㄆㄠˋ。",deep:"1. 注音比較\n炮：ㄆㄠˊ（二聲）＝如法炮製、炮製（中藥加工）；ㄆㄠˋ（四聲）＝炮火、大炮；ㄅㄠ（一聲）＝炮羊肉（快炒）\n2. 國字拆解與造字原因\n炮：形聲字，「火」＋「包」（聲），本義是裹物而燒。中藥的火製加工讀ㄆㄠˊ（炮製）→「如法炮製」＝照同樣方法辦理；武器讀ㄆㄠˋ。"},
  {id:"p191",grade:11,word:"揣度",target:"度",zhuyin:"ㄉㄨㄛˋ",pinyin:"duò",wz:"ㄔㄨㄞˇ ㄉㄨㄛˋ",wrong:[{z:"ㄉㄨˋ",p:"dù"},{z:"ㄊㄨㄛˊ",p:"tuó"}],note:"「揣度」「忖度」（推測）讀ㄉㄨㄛˋ；「程度」讀ㄉㄨˋ。",deep:"1. 注音比較\n度：ㄉㄨㄛˋ（四聲）＝揣度、忖度、審時度勢（推測）；ㄉㄨˋ（四聲）＝程度、制度、度過；ㄊㄨㄛˊ＝無此音\n2. 國字拆解與造字原因\n度：本義是計量長短的標準（ㄉㄨˋ）；用心推算估量（動詞）讀ㄉㄨㄛˋ（揣度、以己度人）。記法：名詞ㄉㄨˋ、猜測ㄉㄨㄛˋ。"},
  {id:"p192",grade:11,word:"創傷",target:"創",zhuyin:"ㄔㄨㄤ",pinyin:"chuāng",wz:"ㄔㄨㄤ ㄕㄤ",wrong:[{z:"ㄔㄨㄤˋ",p:"chuàng"},{z:"ㄘㄤ",p:"cāng"}],note:"「創傷」「創口」讀ㄔㄨㄤ；「創造」「創立」讀ㄔㄨㄤˋ。",deep:"1. 注音比較\n創：ㄔㄨㄤ（一聲）＝創傷、創口、重創；ㄔㄨㄤˋ（四聲）＝創造、創立、開創；ㄘㄤ＝無此音\n2. 國字拆解與造字原因\n創：從「刀」，本義是刀傷→傷口（創傷）讀ㄔㄨㄤ；開始做、首創讀ㄔㄨㄤˋ。記法：傷口一聲、開創四聲。"},
  {id:"p193",grade:11,word:"間諜",target:"諜",zhuyin:"ㄉㄧㄝˊ",pinyin:"dié",wz:"ㄐㄧㄢˋ ㄉㄧㄝˊ",wrong:[{z:"ㄧㄝˋ",p:"yè"},{z:"ㄊㄧㄝˇ",p:"tiě"}],note:"「間諜」的「諜」讀ㄉㄧㄝˊ。",deep:"1. 注音比較\n諜：ㄉㄧㄝˊ（二聲）＝間諜、諜報；ㄧㄝˋ＝無此音；ㄊㄧㄝˇ＝無此音\n2. 國字拆解與造字原因\n諜：形聲字，「言」＋「枼」（聲），刺探消息回報→間諜、諜報。讀ㄉㄧㄝˊ，與「蝶」同音。"},
  {id:"p194",grade:11,word:"魑魅魍魎",target:"魑",zhuyin:"ㄔ",pinyin:"chī",wz:"ㄔ ㄇㄟˋ ㄨㄤˇ ㄌㄧㄤˇ",wrong:[{z:"ㄌㄧˊ",p:"lí"},{z:"ㄨㄤˇ",p:"wǎng"}],note:"「魑魅魍魎」讀ㄔ ㄇㄟˋ ㄨㄤˇ ㄌㄧㄤˇ，泛指鬼怪。",deep:"1. 注音比較\n魑：ㄔ（一聲）＝魑魅魍魎；ㄌㄧˊ＝誤讀（受「離」影響）；ㄨㄤˇ＝無此音（是「魍」的讀音）\n2. 國字拆解與造字原因\n魑：從「鬼」，「魑魅魍魎」（ㄔ ㄇㄟˋ ㄨㄤˇ ㄌㄧㄤˇ）是山林精怪的總稱→泛指各種壞人（如：掃蕩魑魅魍魎）。"},
  {id:"p195",grade:11,word:"耄耋",target:"耋",zhuyin:"ㄉㄧㄝˊ",pinyin:"dié",wz:"ㄇㄠˋ ㄉㄧㄝˊ",wrong:[{z:"ㄓˋ",p:"zhì"},{z:"ㄌㄠˋ",p:"lào"}],note:"「耄耋」讀ㄇㄠˋ ㄉㄧㄝˊ，指八九十歲高齡。",deep:"1. 注音比較\n耋：ㄉㄧㄝˊ（二聲）＝耄耋之年；ㄓˋ＝無此音；ㄌㄠˋ＝無此音\n2. 國字拆解與造字原因\n耋：從「老（省）」、「至」（聲），七八十歲的高齡——「耄耋」（ㄇㄠˋ ㄉㄧㄝˊ）指八九十歲長者。"},
  {id:"p196",grade:11,word:"鱖魚",target:"鱖",zhuyin:"ㄍㄨㄟˋ",pinyin:"guì",wz:"ㄍㄨㄟˋ ㄩˊ",wrong:[{z:"ㄐㄩㄝˊ",p:"jué"},{z:"ㄎㄨㄟˋ",p:"kuì"}],note:"「桃花流水鱖魚肥」的「鱖」讀ㄍㄨㄟˋ。",deep:"1. 注音比較\n鱖：ㄍㄨㄟˋ（四聲）＝鱖魚；ㄐㄩㄝˊ＝誤讀；ㄎㄨㄟˋ＝無此音\n2. 國字拆解與造字原因\n鱖：形聲字，「魚」＋「厥」（聲），淡水食用魚。張志和〈漁歌子〉「桃花流水鱖魚肥」的「鱖」讀ㄍㄨㄟˋ，與「桂」同音。"},
  {id:"p197",grade:11,word:"參乘",target:"乘",zhuyin:"ㄕㄥˋ",pinyin:"shèng",wz:"ㄘㄢ ㄕㄥˋ",wrong:[{z:"ㄔㄥˊ",p:"chéng"},{z:"ㄕㄥ",p:"shēng"}],note:"古文「參乘」「萬乘之國」的「乘」讀ㄕㄥˋ；「乘車」讀ㄔㄥˊ。",deep:"1. 注音比較\n乘：ㄕㄥˋ（四聲）＝參乘、萬乘之國、史乘；ㄔㄥˊ（二聲）＝乘車、乘機；ㄕㄥ＝無此音\n2. 國字拆解與造字原因\n乘：人登木之形。文言的兵車單位（一車四馬為一乘）、陪乘者（參乘）、史書（史乘）讀ㄕㄥˋ；動詞搭乘讀ㄔㄥˊ。"},
  {id:"p198",grade:11,word:"臧否人物",target:"否",zhuyin:"ㄆㄧˇ",pinyin:"pǐ",wz:"ㄗㄤ ㄆㄧˇ ㄖㄣˊ ㄨˋ",wrong:[{z:"ㄈㄡˇ",p:"fǒu"},{z:"ㄅㄧˇ",p:"bǐ"}],note:"「臧否」讀ㄗㄤ ㄆㄧˇ，褒貶評論。",deep:"1. 注音比較\n否：ㄆㄧˇ（三聲）＝臧否人物、否極泰來；ㄈㄡˇ（三聲）＝是否、否定；ㄅㄧˇ＝無此音（是「鄙」的讀音）\n2. 國字拆解與造字原因\n否：從「不」從「口」。「臧否」（ㄗㄤ ㄆㄧˇ）＝褒貶善惡（〈出師表〉「陟罰臧否」），「否」取「惡、壞」義讀ㄆㄧˇ。"},
  {id:"p199",grade:11,word:"暴戾",target:"戾",zhuyin:"ㄌㄧˋ",pinyin:"lì",wz:"ㄅㄠˋ ㄌㄧˋ",wrong:[{z:"ㄏㄨˋ",p:"hù"},{z:"ㄌㄟˋ",p:"lèi"}],note:"「暴戾」的「戾」讀ㄌㄧˋ，凶暴乖張。",deep:"1. 注音比較\n戾：ㄌㄧˋ（四聲）＝暴戾、乖戾、罪戾；ㄏㄨˋ＝無此音（是「戶」的讀音）；ㄌㄟˋ＝無此音（是「淚」的讀音）\n2. 國字拆解與造字原因\n戾：會意字，「戶」＋「犬」，狗從門下擠出，身體彎曲，本義是彎曲→乖張兇暴（暴戾之氣）。讀ㄌㄧˋ。"},
  {id:"p200",grade:11,word:"鞭撻",target:"撻",zhuyin:"ㄊㄚˋ",pinyin:"tà",wz:"ㄅㄧㄢ ㄊㄚˋ",wrong:[{z:"ㄉㄚˊ",p:"dá"},{z:"ㄊㄚ",p:"tā"}],note:"「鞭撻」的「撻」讀ㄊㄚˋ。",deep:"1. 注音比較\n撻：ㄊㄚˋ（四聲）＝鞭撻、撻伐；ㄉㄚˊ＝無此音（是「達」的讀音）；ㄊㄚ＝無此音（是「他」的讀音）\n2. 國字拆解與造字原因\n撻：形聲字，「扌」＋「達」（聲），用鞭棍抽打→鞭撻；出兵征討（大張撻伐）。讀ㄊㄚˋ。"},
  // ---- 高中 10-12 進階（p201-p300 後段）----
  {id:"p201",grade:10,word:"覬覦",target:"覦",zhuyin:"ㄩˊ",pinyin:"yú",wz:"ㄐㄧˋ ㄩˊ",wrong:[{z:"ㄩˋ",p:"yù"},{z:"ㄧˊ",p:"yí"}],note:"「覬覦」讀ㄐㄧˋ ㄩˊ，非分的希望或企圖。",deep:"1. 注音比較\n覦：ㄩˊ（二聲）＝覬覦；ㄩˋ＝誤讀；ㄧˊ＝無此音\n2. 國字拆解與造字原因\n覦：形聲字，「見」＋「俞」（聲），「覬覦」（ㄐㄧˋ ㄩˊ）＝非分的企圖，眼睛盯著不該得的東西。"},
  {id:"p202",grade:10,word:"褪色",target:"褪",zhuyin:"ㄊㄨㄣˋ",pinyin:"tùn",wz:"ㄊㄨㄣˋ ㄙㄜˋ",wrong:[{z:"ㄊㄨㄟˋ",p:"tuì"},{z:"ㄊㄨㄣˊ",p:"tún"}],note:"審訂音「褪色」的「褪」讀ㄊㄨㄣˋ。",deep:"1. 注音比較\n褪：ㄊㄨㄣˋ（四聲）＝褪色、褪去（審訂音）；ㄊㄨㄟˋ＝俗讀，審訂表不採；ㄊㄨㄣˊ＝無此音\n2. 國字拆解與造字原因\n褪：形聲字，「衤」＋「退」（聲），衣物顏色消退、脫下→褪色、褪去。審訂音讀ㄊㄨㄣˋ。"},
  {id:"p203",grade:10,word:"癱瘓",target:"瘓",zhuyin:"ㄏㄨㄢˋ",pinyin:"huàn",wz:"ㄊㄢ ㄏㄨㄢˋ",wrong:[{z:"ㄏㄨㄢ",p:"huān"},{z:"ㄨㄢˋ",p:"wàn"}],note:"「癱瘓」讀ㄊㄢ ㄏㄨㄢˋ。",deep:"1. 注音比較\n瘓：ㄏㄨㄢˋ（四聲）＝癱瘓；ㄏㄨㄢ＝無此音；ㄨㄢˋ＝無此音\n2. 國字拆解與造字原因\n瘓：形聲字，「疒」＋「奐」（聲），「癱瘓」（ㄊㄢ ㄏㄨㄢˋ）＝肢體失去運動能力；引申為機能停擺（交通癱瘓）。"},
  {id:"p204",grade:10,word:"叱吒風雲",target:"吒",zhuyin:"ㄓㄚˋ",pinyin:"zhà",wz:"ㄔˋ ㄓㄚˋ ㄈㄥ ㄩㄣˊ",wrong:[{z:"ㄔㄚˋ",p:"chà"},{z:"ㄊㄨㄛ",p:"tuō"}],note:"「叱吒風雲」讀ㄔˋ ㄓㄚˋ，怒喝聲威震風雲。",deep:"1. 注音比較\n吒：ㄓㄚˋ（四聲）＝叱吒風雲；ㄔㄚˋ＝誤讀；ㄊㄨㄛ＝無此音\n2. 國字拆解與造字原因\n吒：形聲字，「口」＋「乇」（聲），怒喝聲——「叱吒風雲」（ㄔˋ ㄓㄚˋ）形容聲威極大。讀ㄓㄚˋ。"},
  {id:"p205",grade:10,word:"舐犢情深",target:"舐",zhuyin:"ㄕˋ",pinyin:"shì",wz:"ㄕˋ ㄉㄨˊ ㄑㄧㄥˊ ㄕㄣ",wrong:[{z:"ㄉㄧˇ",p:"dǐ"},{z:"ㄊㄧㄢˇ",p:"tiǎn"}],note:"「舐犢情深」的「舐」讀ㄕˋ，舔的意思。",deep:"1. 注音比較\n舐：ㄕˋ（四聲）＝舐犢情深、老牛舐犢；ㄉㄧˇ＝無此音；ㄊㄧㄢˇ＝無此音（是「舔」的讀音）\n2. 國字拆解與造字原因\n舐：從「舌」，用舌頭舔→老牛舐犢（母牛舔小牛），比喻父母疼愛子女。讀ㄕˋ。"},
  {id:"p206",grade:10,word:"復辟",target:"辟",zhuyin:"ㄅㄧˋ",pinyin:"bì",wz:"ㄈㄨˋ ㄅㄧˋ",wrong:[{z:"ㄆㄧˋ",p:"pì"},{z:"ㄅㄟˋ",p:"bèi"}],note:"「復辟」的「辟」讀ㄅㄧˋ，君主之位；「開闢」的「闢」讀ㄆㄧˋ。",deep:"1. 注音比較\n辟：ㄅㄧˋ（四聲）＝復辟、辟邪（君位、驅除）；ㄆㄧˋ（四聲）＝辟謠（通「闢」）、辟穀；ㄅㄟˋ＝無此音\n2. 國字拆解與造字原因\n辟：會意字，從「卩」（人）從「辛」（刑具），本義是法度、君主→復辟（恢復君位）讀ㄅㄧˋ；通「闢」（開）讀ㄆㄧˋ。"},
  {id:"p207",grade:10,word:"駭人聽聞",target:"駭",zhuyin:"ㄏㄞˋ",pinyin:"hài",wz:"ㄏㄞˋ ㄖㄣˊ ㄊㄧㄥ ㄨㄣˊ",wrong:[{z:"ㄍㄞ",p:"gāi"},{z:"ㄏㄞˊ",p:"hái"}],note:"「駭人聽聞」的「駭」讀ㄏㄞˋ，驚嚇。",deep:"1. 注音比較\n駭：ㄏㄞˋ（四聲）＝駭人聽聞、驚駭；ㄍㄞ＝無此音；ㄏㄞˊ＝無此音（是「骸」的讀音）\n2. 國字拆解與造字原因\n駭：形聲字，「馬」＋「亥」（聲），本義是馬受驚→驚嚇（驚駭、駭人聽聞）。讀ㄏㄞˋ。"},
  {id:"p208",grade:10,word:"蒙蔽",target:"蒙",zhuyin:"ㄇㄥˊ",pinyin:"méng",wz:"ㄇㄥˊ ㄅㄧˋ",wrong:[{z:"ㄇㄥˇ",p:"měng"},{z:"ㄇㄥˋ",p:"mèng"}],note:"「蒙蔽」「啟蒙」讀ㄇㄥˊ；「蒙古」讀ㄇㄥˇ。",deep:"1. 注音比較\n蒙：ㄇㄥˊ（二聲）＝蒙蔽、啟蒙、承蒙；ㄇㄥˇ（三聲）＝蒙古；ㄇㄥˋ＝無此音（是「夢」的讀音）\n2. 國字拆解與造字原因\n蒙：形聲字，「艹」＋「冡」（聲），本義是遮覆→蒙蔽（被遮住）、啟蒙（揭開蒙昧）。一般讀ㄇㄥˊ；「蒙古」讀ㄇㄥˇ。"},
  {id:"p209",grade:10,word:"荷槍實彈",target:"荷",zhuyin:"ㄏㄜˋ",pinyin:"hè",wz:"ㄏㄜˋ ㄑㄧㄤ ㄕˊ ㄉㄢˋ",wrong:[{z:"ㄏㄜˊ",p:"hé"},{z:"ㄎㄜ",p:"kē"}],note:"「荷槍」「負荷」的「荷」讀ㄏㄜˋ；「荷花」讀ㄏㄜˊ。",deep:"1. 注音比較\n荷：ㄏㄜˋ（四聲）＝荷槍實彈、負荷、荷重；ㄏㄜˊ（二聲）＝荷花、荷葉；ㄎㄜ＝無此音\n2. 國字拆解與造字原因\n荷：形聲字，「艹」＋「何」（聲），本義是蓮（ㄏㄜˊ）；「何」的本義是人扛物，故「扛、承擔」義讀ㄏㄜˋ（負荷、荷槍）。記法：植物二聲、扛擔四聲。"},
  {id:"p210",grade:10,word:"泥淖",target:"淖",zhuyin:"ㄋㄠˋ",pinyin:"nào",wz:"ㄋㄧˊ ㄋㄠˋ",wrong:[{z:"ㄓㄠˇ",p:"zhǎo"},{z:"ㄔㄨㄛˋ",p:"chuò"}],note:"「泥淖」的「淖」讀ㄋㄠˋ，爛泥。",deep:"1. 注音比較\n淖：ㄋㄠˋ（四聲）＝泥淖；ㄓㄠˇ＝無此音（是「沼」的讀音）；ㄔㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n淖：形聲字，「氵」＋「卓」（聲），爛泥→泥淖（陷入泥淖＝陷入困境）。讀ㄋㄠˋ，與「鬧」同音。"},
  {id:"p211",grade:10,word:"霎時",target:"霎",zhuyin:"ㄕㄚˋ",pinyin:"shà",wz:"ㄕㄚˋ ㄕˊ",wrong:[{z:"ㄕㄚ",p:"shā"},{z:"ㄒㄧㄚˋ",p:"xià"}],note:"「霎時」的「霎」讀ㄕㄚˋ，極短的時間。",deep:"1. 注音比較\n霎：ㄕㄚˋ（四聲）＝霎時、一霎；ㄕㄚ＝誤讀；ㄒㄧㄚˋ＝無此音\n2. 國字拆解與造字原因\n霎：形聲字，「雨」＋「妾」（聲），本義是小雨——雨點一瞬即逝→極短時間（霎時）。讀ㄕㄚˋ。"},
  {id:"p212",grade:10,word:"歃血為盟",target:"歃",zhuyin:"ㄕㄚˋ",pinyin:"shà",wz:"ㄕㄚˋ ㄒㄧㄝˇ ㄨㄟˊ ㄇㄥˊ",wrong:[{z:"ㄔㄚ",p:"chā"},{z:"ㄒㄧㄚˊ",p:"xiá"}],note:"「歃血為盟」的「歃」讀ㄕㄚˋ，以口微吸。",deep:"1. 注音比較\n歃：ㄕㄚˋ（四聲）＝歃血為盟；ㄔㄚ＝無此音（是「插」的讀音）；ㄒㄧㄚˊ＝無此音\n2. 國字拆解與造字原因\n歃：從「欠」（張口），用口微吸→歃血為盟（古代盟誓時口含牲血表誠信）。「歃」讀ㄕㄚˋ；「血」教育部審訂音讀ㄒㄧㄝˇ，所以整句讀ㄕㄚˋ ㄒㄧㄝˇ ㄨㄟˊ ㄇㄥˊ。"},
  {id:"p213",grade:10,word:"鎩羽而歸",target:"鎩",zhuyin:"ㄕㄚ",pinyin:"shā",wz:"ㄕㄚ ㄩˇ ㄦˊ ㄍㄨㄟ",wrong:[{z:"ㄕㄚˋ",p:"shà"},{z:"ㄕㄨㄞ",p:"shuāi"}],note:"「鎩羽而歸」的「鎩」讀ㄕㄚ，羽毛摧落，比喻失敗。",deep:"1. 注音比較\n鎩：ㄕㄚ（一聲）＝鎩羽而歸；ㄕㄚˋ＝誤讀；ㄕㄨㄞ＝無此音（是「摔」的讀音）\n2. 國字拆解與造字原因\n鎩：形聲字，「金」＋「殺」（聲），本義是長矛，引申為摧殘——鳥羽被摧落→鎩羽而歸（失敗而回）。讀ㄕㄚ。"},
  {id:"p214",grade:10,word:"贏得青睞",target:"睞",zhuyin:"ㄌㄞˋ",pinyin:"lài",wz:"ㄧㄥˊ ㄉㄜˊ ㄑㄧㄥ ㄌㄞˋ",wrong:[{z:"ㄌㄞˊ",p:"lái"},{z:"ㄌㄢˊ",p:"lán"}],note:"「青睞」的「睞」讀ㄌㄞˋ，顧盼。",deep:"1. 注音比較\n睞：ㄌㄞˋ（四聲）＝青睞、明眸善睞；ㄌㄞˊ＝誤讀（受「來」影響）；ㄌㄢˊ＝無此音\n2. 國字拆解與造字原因\n睞：形聲字，「目」＋「來」（聲），本義是瞳孔不正，引申為顧盼——「青睞」（青眼相看）＝賞識。讀ㄌㄞˋ。"},
  {id:"p215",grade:10,word:"揠苗助長",target:"揠",zhuyin:"ㄧㄚˋ",pinyin:"yà",wz:"ㄧㄚˋ ㄇㄧㄠˊ ㄓㄨˋ ㄓㄤˇ",wrong:[{z:"ㄧㄢˋ",p:"yàn"},{z:"ㄧㄝˋ",p:"yè"}],note:"「揠苗助長」的「揠」讀ㄧㄚˋ，拔起。",deep:"1. 注音比較\n揠：ㄧㄚˋ（四聲）＝揠苗助長；ㄧㄢˋ＝誤讀；ㄧㄝˋ＝無此音\n2. 國字拆解與造字原因\n揠：形聲字，「扌」＋「匽」（聲），拔起→揠苗助長（把苗拔高）。讀ㄧㄚˋ，與「亞」的俗讀同音。"},
  {id:"p216",grade:11,word:"拾級而上",target:"拾",zhuyin:"ㄕㄜˋ",pinyin:"shè",wz:"ㄕㄜˋ ㄐㄧˊ ㄦˊ ㄕㄤˋ",wrong:[{z:"ㄕˊ",p:"shí"},{z:"ㄕㄜˇ",p:"shě"}],note:"「拾級而上」的「拾」讀ㄕㄜˋ，逐階登上；「拾起」讀ㄕˊ。",deep:"1. 注音比較\n拾：ㄕㄜˋ（四聲）＝拾級而上（逐階登上）；ㄕˊ（二聲）＝拾起、拾金不昧、收拾；ㄕㄜˇ＝無此音\n2. 國字拆解與造字原因\n拾：形聲字，「扌」＋「合」（聲），本義是撿取（ㄕˊ）；「拾級」（一階一階踏上）是特殊文言讀音ㄕㄜˋ。"},
  {id:"p217",grade:11,word:"身陷囹圄",target:"圄",zhuyin:"ㄩˇ",pinyin:"yǔ",wz:"ㄕㄣ ㄒㄧㄢˋ ㄌㄧㄥˊ ㄩˇ",wrong:[{z:"ㄨˊ",p:"wú"},{z:"ㄩˊ",p:"yú"}],note:"「囹圄」讀ㄌㄧㄥˊ ㄩˇ，監獄。",deep:"1. 注音比較\n圄：ㄩˇ（三聲）＝身陷囹圄；ㄨˊ＝無此音（是「吾」的讀音）；ㄩˊ＝誤讀\n2. 國字拆解與造字原因\n圄：「囗」（圍）＋「吾」（聲），「囹圄」（ㄌㄧㄥˊ ㄩˇ）是監獄——「囗」正像四面圍牆。"},
  {id:"p218",grade:11,word:"囫圇吞棗",target:"圇",zhuyin:"ㄌㄨㄣˊ",pinyin:"lún",wz:"ㄏㄨˊ ㄌㄨㄣˊ ㄊㄨㄣ ㄗㄠˇ",wrong:[{z:"ㄌㄨㄣˋ",p:"lùn"},{z:"ㄏㄨㄣˊ",p:"hún"}],note:"「囫圇吞棗」讀ㄏㄨˊ ㄌㄨㄣˊ，不加咀嚼地吞下。",deep:"1. 注音比較\n圇：ㄌㄨㄣˊ（二聲）＝囫圇吞棗；ㄌㄨㄣˋ＝無此音（是「論」的讀音）；ㄏㄨㄣˊ＝無此音\n2. 國字拆解與造字原因\n圇：「囗」＋「侖」（聲），「囫圇」（ㄏㄨˊ ㄌㄨㄣˊ）＝完整未破——囫圇吞棗即整顆吞下不咀嚼，比喻學習不求甚解。"},
  {id:"p219",grade:11,word:"呷茶",target:"呷",zhuyin:"ㄒㄧㄚˊ",pinyin:"xiá",wz:"ㄒㄧㄚˊ ㄔㄚˊ",wrong:[{z:"ㄐㄧㄚ",p:"jiā"},{z:"ㄍㄚ",p:"gā"}],note:"「呷茶」的「呷」讀ㄒㄧㄚˊ，小口喝。",deep:"1. 注音比較\n呷：ㄒㄧㄚˊ（二聲）＝呷茶、呷一口；ㄐㄧㄚ＝無此音；ㄍㄚ＝無此音\n2. 國字拆解與造字原因\n呷：形聲字，「口」＋「甲」（聲），小口喝→呷茶。讀ㄒㄧㄚˊ（閩南語「呷飯」的呷是借字）。"},
  {id:"p220",grade:11,word:"髀肉復生",target:"髀",zhuyin:"ㄅㄧˋ",pinyin:"bì",wz:"ㄅㄧˋ ㄖㄡˋ ㄈㄨˋ ㄕㄥ",wrong:[{z:"ㄆㄧˊ",p:"pí"},{z:"ㄅㄟ",p:"bēi"}],note:"「髀肉復生」的「髀」讀ㄅㄧˋ，大腿。",deep:"1. 注音比較\n髀：ㄅㄧˋ（四聲）＝髀肉復生；ㄆㄧˊ＝無此音（是「皮」的讀音）；ㄅㄟ＝無此音\n2. 國字拆解與造字原因\n髀：形聲字，「骨」＋「卑」（聲），大腿骨、大腿。劉備嘆久不騎馬「髀肉復生」——大腿長回贅肉，功業未建。讀ㄅㄧˋ。"},
  {id:"p221",grade:11,word:"暴殄天物",target:"殄",zhuyin:"ㄊㄧㄢˇ",pinyin:"tiǎn",wz:"ㄅㄠˋ ㄊㄧㄢˇ ㄊㄧㄢ ㄨˋ",wrong:[{z:"ㄓㄣ",p:"zhēn"},{z:"ㄊㄧㄢ",p:"tiān"}],note:"「暴殄天物」的「殄」讀ㄊㄧㄢˇ，滅絕糟蹋。",deep:"1. 注音比較\n殄：ㄊㄧㄢˇ（三聲）＝暴殄天物；ㄓㄣ＝無此音（是「珍」的讀音）；ㄊㄧㄢ＝誤讀\n2. 國字拆解與造字原因\n殄：從「歹」（殘骨），滅絕、糟蹋→暴殄天物（任意糟蹋東西）。讀ㄊㄧㄢˇ，與「舔」同音。"},
  {id:"p222",grade:11,word:"沆瀣一氣",target:"沆",zhuyin:"ㄏㄤˋ",pinyin:"hàng",wz:"ㄏㄤˋ ㄒㄧㄝˋ ㄧ ㄑㄧˋ",wrong:[{z:"ㄎㄤ",p:"kāng"},{z:"ㄏㄤˊ",p:"háng"}],note:"「沆瀣」讀ㄏㄤˋ ㄒㄧㄝˋ，夜間的水氣。",deep:"1. 注音比較\n沆：ㄏㄤˋ（四聲）＝沆瀣一氣；ㄎㄤ＝無此音；ㄏㄤˊ＝誤讀（受「航」影響）\n2. 國字拆解與造字原因\n沆：「氵」＋「亢」（聲），「沆瀣」（ㄏㄤˋ ㄒㄧㄝˋ）是夜間水氣；唐代主考崔沆錄取考生崔瀣，時人譏「座主門生，沆瀣一氣」→氣味相投（今多貶義：勾結一氣）。"},
  {id:"p223",grade:11,word:"魑魅",target:"魅",zhuyin:"ㄇㄟˋ",pinyin:"mèi",wz:"ㄔ ㄇㄟˋ",wrong:[{z:"ㄨㄟˋ",p:"wèi"},{z:"ㄇㄟˊ",p:"méi"}],note:"「魑魅」「魅力」的「魅」讀ㄇㄟˋ。",deep:"1. 注音比較\n魅：ㄇㄟˋ（四聲）＝魑魅、魅力、魅惑；ㄨㄟˋ＝無此音（是「未」的讀音）；ㄇㄟˊ＝無此音（是「眉」的讀音）\n2. 國字拆解與造字原因\n魅：從「鬼」、「未」（聲），山林精怪→魑魅；迷惑人的力量→魅力。讀ㄇㄟˋ。"},
  {id:"p224",grade:11,word:"倥傯戎馬",target:"倥",zhuyin:"ㄎㄨㄥˇ",pinyin:"kǒng",wz:"ㄎㄨㄥˇ ㄗㄨㄥˇ ㄖㄨㄥˊ ㄇㄚˇ",wrong:[{z:"ㄎㄨㄥ",p:"kōng"},{z:"ㄎㄨㄥˋ",p:"kòng"}],note:"「倥傯」讀ㄎㄨㄥˇ ㄗㄨㄥˇ。",deep:"1. 注音比較\n倥：ㄎㄨㄥˇ（三聲）＝倥傯；ㄎㄨㄥ＝誤讀（受「空」影響）；ㄎㄨㄥˋ＝無此音\n2. 國字拆解與造字原因\n倥：形聲字，「亻」＋「空」（聲），「倥傯」（ㄎㄨㄥˇ ㄗㄨㄥˇ）＝事務匆迫——「戎馬倥傯」形容軍務繁忙。"},
  {id:"p225",grade:11,word:"擘畫",target:"擘",zhuyin:"ㄅㄛˋ",pinyin:"bò",wz:"ㄅㄛˋ ㄏㄨㄚˋ",wrong:[{z:"ㄅㄧˋ",p:"bì"},{z:"ㄆㄧˊ",p:"pí"}],note:"「擘畫」「巨擘」的「擘」讀ㄅㄛˋ。",deep:"1. 注音比較\n擘：ㄅㄛˋ（四聲）＝擘畫、巨擘；ㄅㄧˋ＝無此音（是「臂」的讀音）；ㄆㄧˊ＝無此音\n2. 國字拆解與造字原因\n擘：從「手」、「辟」（聲），本義是大拇指→行業中的頂尖人物（巨擘）；用手分開、規劃（擘畫）。讀ㄅㄛˋ。"},
  {id:"p226",grade:11,word:"箇中翹楚",target:"翹",zhuyin:"ㄑㄧㄠˊ",pinyin:"qiáo",wz:"ㄍㄜˋ ㄓㄨㄥ ㄑㄧㄠˊ ㄔㄨˇ",wrong:[{z:"ㄑㄧㄠˋ",p:"qiào"},{z:"ㄐㄧㄠˇ",p:"jiǎo"}],note:"「翹楚」（傑出者）讀ㄑㄧㄠˊ；「翹起」讀ㄑㄧㄠˋ。",deep:"1. 注音比較\n翹：ㄑㄧㄠˊ（二聲）＝翹楚、翹首；ㄑㄧㄠˋ（四聲）＝翹起、翹課；ㄐㄧㄠˇ＝無此音\n2. 國字拆解與造字原因\n翹：「羽」＋「堯」（聲），鳥尾長羽。傑出者（翹楚，本指高出的荊木）、抬頭盼望（翹首）讀ㄑㄧㄠˊ；物體一端上揚讀ㄑㄧㄠˋ。"},
  {id:"p227",grade:11,word:"矯枉過正",target:"枉",zhuyin:"ㄨㄤˇ",pinyin:"wǎng",wz:"ㄐㄧㄠˇ ㄨㄤˇ ㄍㄨㄛˋ ㄓㄥˋ",wrong:[{z:"ㄨㄤˊ",p:"wáng"},{z:"ㄎㄨㄤˊ",p:"kuáng"}],note:"「矯枉過正」的「枉」讀ㄨㄤˇ，彎曲。",deep:"1. 注音比較\n枉：ㄨㄤˇ（三聲）＝矯枉過正、冤枉、枉費；ㄨㄤˊ＝無此音（是「亡」的讀音）；ㄎㄨㄤˊ＝無此音\n2. 國字拆解與造字原因\n枉：形聲字，「木」＋「王」（聲），樹木彎曲→彎曲不直（矯枉過正＝糾正彎曲卻矯過了頭）、冤屈（冤枉）。讀ㄨㄤˇ。"},
  {id:"p228",grade:11,word:"賈禍",target:"賈",zhuyin:"ㄍㄨˇ",pinyin:"gǔ",wz:"ㄍㄨˇ ㄏㄨㄛˋ",wrong:[{z:"ㄐㄧㄚˇ",p:"jiǎ"},{z:"ㄐㄧㄚˋ",p:"jià"}],note:"「賈禍」（招致災禍）讀ㄍㄨˇ；姓氏讀ㄐㄧㄚˇ。",deep:"1. 注音比較\n賈：ㄍㄨˇ（三聲）＝賈禍（招致）、商賈、餘勇可賈；ㄐㄧㄚˇ（三聲）＝姓賈；ㄐㄧㄚˋ＝通「價」（古用法）\n2. 國字拆解與造字原因\n賈：從「貝」，本義是做買賣的商人（商賈，ㄍㄨˇ）；由「買」引申為招來（賈禍＝招災）。姓氏讀ㄐㄧㄚˇ。"},
  {id:"p229",grade:11,word:"僕僕風塵",target:"僕",zhuyin:"ㄆㄨˊ",pinyin:"pú",wz:"ㄆㄨˊ ㄆㄨˊ ㄈㄥ ㄔㄣˊ",wrong:[{z:"ㄆㄨ",p:"pū"},{z:"ㄅㄨˊ",p:"bú"}],note:"「風塵僕僕」的「僕」讀ㄆㄨˊ。",deep:"1. 注音比較\n僕：ㄆㄨˊ（二聲）＝風塵僕僕、僕人、公僕；ㄆㄨ＝無此音（是「撲」的讀音）；ㄅㄨˊ＝無此音\n2. 國字拆解與造字原因\n僕：從「亻」，供役使的人→僕人；「僕僕」是勞頓奔波的樣子→風塵僕僕。讀ㄆㄨˊ。"},
  {id:"p230",grade:11,word:"咋舌",target:"咋",zhuyin:"ㄗㄜˊ",pinyin:"zé",wz:"ㄗㄜˊ ㄕㄜˊ",wrong:[{z:"ㄓㄚˋ",p:"zhà"},{z:"ㄗㄚˇ",p:"zǎ"}],note:"「令人咋舌」的「咋」讀ㄗㄜˊ，咬住。",deep:"1. 注音比較\n咋：ㄗㄜˊ（二聲）＝令人咋舌；ㄓㄚˋ＝無此音（是「炸」的讀音）；ㄗㄚˇ＝北方方言「怎麼」\n2. 國字拆解與造字原因\n咋：形聲字，「口」＋「乍」（聲），咬住→咋舌（驚訝得咬住舌頭說不出話）。讀ㄗㄜˊ。"},
  {id:"p231",grade:12,word:"齷齪",target:"齷",zhuyin:"ㄨㄛˋ",pinyin:"wò",wz:"ㄨㄛˋ ㄔㄨㄛˋ",wrong:[{z:"ㄨㄛ",p:"wō"},{z:"ㄩㄝˋ",p:"yuè"}],note:"「齷齪」讀ㄨㄛˋ ㄔㄨㄛˋ，骯髒卑劣。",deep:"1. 注音比較\n齷：ㄨㄛˋ（四聲）＝齷齪；ㄨㄛ＝誤讀；ㄩㄝˋ＝無此音\n2. 國字拆解與造字原因\n齷：從「齒」，「齷齪」（ㄨㄛˋ ㄔㄨㄛˋ）本指牙齒細密，引申為器量狹小、骯髒卑劣（心思齷齪）。"},
  {id:"p232",grade:12,word:"蹭蹬",target:"蹬",zhuyin:"ㄉㄥˋ",pinyin:"dèng",wz:"ㄘㄥˋ ㄉㄥˋ",wrong:[{z:"ㄉㄥ",p:"dēng"},{z:"ㄔㄥˊ",p:"chéng"}],note:"「蹭蹬」讀ㄘㄥˋ ㄉㄥˋ，失意潦倒。",deep:"1. 注音比較\n蹬：ㄉㄥˋ（四聲）＝蹭蹬；ㄉㄥ（一聲）＝蹬腿、蹬自行車；ㄔㄥˊ＝無此音\n2. 國字拆解與造字原因\n蹬：「足」＋「登」（聲），用腳踏。「蹭蹬」（ㄘㄥˋ ㄉㄥˋ）指路難行→失意潦倒（仕途蹭蹬）。"},
  {id:"p233",grade:12,word:"踟躕不前",target:"踟",zhuyin:"ㄔˊ",pinyin:"chí",wz:"ㄔˊ ㄔㄨˊ ㄅㄨˋ ㄑㄧㄢˊ",wrong:[{z:"ㄓ",p:"zhī"},{z:"ㄉㄧˊ",p:"dí"}],note:"「踟躕」讀ㄔˊ ㄔㄨˊ，徘徊不前。",deep:"1. 注音比較\n踟：ㄔˊ（二聲）＝踟躕；ㄓ＝誤讀；ㄉㄧˊ＝無此音\n2. 國字拆解與造字原因\n踟：「足」＋「知」（聲），「踟躕」（ㄔˊ ㄔㄨˊ）是連綿詞：徘徊不前、猶豫（〈陌上桑〉「使君從南來，五馬立踟躕」）。"},
  {id:"p234",grade:12,word:"躑躅",target:"躅",zhuyin:"ㄓㄨˊ",pinyin:"zhú",wz:"ㄓˊ ㄓㄨˊ",wrong:[{z:"ㄕㄨˇ",p:"shǔ"},{z:"ㄔㄨˊ",p:"chú"}],note:"「躑躅」讀ㄓˊ ㄓㄨˊ，徘徊不進。",deep:"1. 注音比較\n躅：ㄓㄨˊ（二聲）＝躑躅；ㄕㄨˇ＝無此音（是「蜀」的讀音）；ㄔㄨˊ＝無此音\n2. 國字拆解與造字原因\n躅：「足」＋「蜀」（聲），「躑躅」（ㄓˊ ㄓㄨˊ）是連綿詞：徘徊不進。與「踟躕」義近。"},
  {id:"p235",grade:12,word:"矍鑠",target:"矍",zhuyin:"ㄐㄩㄝˊ",pinyin:"jué",wz:"ㄐㄩㄝˊ ㄕㄨㄛˋ",wrong:[{z:"ㄍㄨㄛˋ",p:"guò"},{z:"ㄑㄩˊ",p:"qú"}],note:"「精神矍鑠」讀ㄐㄩㄝˊ ㄕㄨㄛˋ，老而強健。",deep:"1. 注音比較\n矍：ㄐㄩㄝˊ（二聲）＝精神矍鑠；ㄍㄨㄛˋ＝無此音；ㄑㄩˊ＝無此音（是「瞿」的讀音）\n2. 國字拆解與造字原因\n矍：從二「目」從「隹」從「又」，本義是鳥驚視張望——目光炯炯。「矍鑠」（ㄐㄩㄝˊ ㄕㄨㄛˋ）形容老人強健有神。"},
  {id:"p236",grade:12,word:"日晷",target:"晷",zhuyin:"ㄍㄨㄟˇ",pinyin:"guǐ",wz:"ㄖˋ ㄍㄨㄟˇ",wrong:[{z:"ㄐㄧㄡˋ",p:"jiù"},{z:"ㄍㄨㄟ",p:"guī"}],note:"「日晷」「焚膏繼晷」的「晷」讀ㄍㄨㄟˇ，日影。",deep:"1. 注音比較\n晷：ㄍㄨㄟˇ（三聲）＝日晷、焚膏繼晷；ㄐㄧㄡˋ＝無此音（是「咎」的讀音）；ㄍㄨㄟ＝誤讀\n2. 國字拆解與造字原因\n晷：「日」＋「咎」（聲），日影→日晷（以日影計時的儀器）、繼晷（接續日光）。讀ㄍㄨㄟˇ，與「軌」同音。"},
  {id:"p237",grade:12,word:"褫奪公權",target:"褫",zhuyin:"ㄔˇ",pinyin:"chǐ",wz:"ㄔˇ ㄉㄨㄛˊ ㄍㄨㄥ ㄑㄩㄢˊ",wrong:[{z:"ㄉㄧˋ",p:"dì"},{z:"ㄊㄧˇ",p:"tǐ"}],note:"「褫奪」的「褫」讀ㄔˇ，剝奪。",deep:"1. 注音比較\n褫：ㄔˇ（三聲）＝褫奪公權；ㄉㄧˋ＝無此音；ㄊㄧˇ＝無此音\n2. 國字拆解與造字原因\n褫：「衤」＋「虒」（聲），本義是剝去衣服→剝奪（褫奪公權）。讀ㄔˇ，與「恥」同音。"},
  {id:"p238",grade:12,word:"蹙眉",target:"蹙",zhuyin:"ㄘㄨˋ",pinyin:"cù",wz:"ㄘㄨˋ ㄇㄟˊ",wrong:[{z:"ㄗㄨˊ",p:"zú"},{z:"ㄑㄧ",p:"qī"}],note:"「蹙眉」「窮蹙」的「蹙」讀ㄘㄨˋ，皺縮。",deep:"1. 注音比較\n蹙：ㄘㄨˋ（四聲）＝蹙眉、窮蹙；ㄗㄨˊ＝無此音（是「足」的讀音）；ㄑㄧ＝無此音\n2. 國字拆解與造字原因\n蹙：從「足」、「戚」（聲），本義是緊迫→皺縮（蹙眉＝皺眉頭）、困窘（窮蹙）。讀ㄘㄨˋ，與「促」同音。"},
  {id:"p239",grade:12,word:"驪歌",target:"驪",zhuyin:"ㄌㄧˊ",pinyin:"lí",wz:"ㄌㄧˊ ㄍㄜ",wrong:[{z:"ㄌㄧˋ",p:"lì"},{z:"ㄌㄩˊ",p:"lǘ"}],note:"「驪歌」（離別之歌）的「驪」讀ㄌㄧˊ。",deep:"1. 注音比較\n驪：ㄌㄧˊ（二聲）＝驪歌、驪山；ㄌㄧˋ＝誤讀；ㄌㄩˊ＝無此音（是「驢」的讀音）\n2. 國字拆解與造字原因\n驪：「馬」＋「麗」（聲），本義是純黑色的馬。「驪歌」是離別時唱的歌（語出古〈驪駒〉逸詩）。讀ㄌㄧˊ，與「離」同音好記。"},
  {id:"p240",grade:12,word:"蛻變",target:"蛻",zhuyin:"ㄊㄨㄟˋ",pinyin:"tuì",wz:"ㄊㄨㄟˋ ㄅㄧㄢˋ",wrong:[{z:"ㄕㄨㄟˋ",p:"shuì"},{z:"ㄩㄝˋ",p:"yuè"}],note:"教育部審訂音「蛻」只有一個讀音ㄊㄨㄟˋ：蛻皮、蛻變、蟬蛻都讀ㄊㄨㄟˋ。",deep:"1. 注音比較\n蛻：ㄊㄨㄟˋ＝蛻變、蛻皮、蛻殼、蛻化、蟬蛻、蛇蛻。★教育部《國語辭典簡編本》「蛻」只收ㄊㄨㄟˋ一音，讀成ㄕㄨㄟˋ不是審訂音\n2. 國字拆解與造字原因\n蛻：形聲字，「虫」＋「兌」（聲）。本義是蟲蛇脫下的舊皮，脫掉舊皮換上新的→比喻脫胎換骨的改變，就是「蛻變」。"},
  {id:"p241",grade:12,word:"菌蕈",target:"蕈",zhuyin:"ㄒㄩㄣˋ",pinyin:"xùn",wz:"ㄐㄩㄣˋ ㄒㄩㄣˋ",wrong:[{z:"ㄊㄢˊ",p:"tán"},{z:"ㄒㄧㄣ",p:"xīn"}],note:"「蕈類」的「蕈」讀ㄒㄩㄣˋ，菇類。",deep:"1. 注音比較\n蕈：ㄒㄩㄣˋ（四聲）＝蕈類、毒蕈；ㄊㄢˊ＝無此音（是「覃」的讀音）；ㄒㄧㄣ＝無此音\n2. 國字拆解與造字原因\n蕈：「艹」＋「覃」（聲），生於朽木腐土上的菇類→蕈類。讀ㄒㄩㄣˋ，與「訓」同音。"},
  {id:"p242",grade:12,word:"躉售",target:"躉",zhuyin:"ㄉㄨㄣˇ",pinyin:"dǔn",wz:"ㄉㄨㄣˇ ㄕㄡˋ",wrong:[{z:"ㄨㄢˋ",p:"wàn"},{z:"ㄉㄨㄣˋ",p:"dùn"}],note:"「躉售」「躉批」的「躉」讀ㄉㄨㄣˇ，整批買賣。",deep:"1. 注音比較\n躉：ㄉㄨㄣˇ（三聲）＝躉售、躉批、船躉；ㄨㄢˋ＝無此音（是「萬」的讀音）；ㄉㄨㄣˋ＝誤讀\n2. 國字拆解與造字原因\n躉：「萬」＋「足」，整數、整批→躉售（整批出售）、躉批。讀ㄉㄨㄣˇ，與「盹」同音。"},
  {id:"p243",grade:12,word:"藺相如",target:"藺",zhuyin:"ㄌㄧㄣˋ",pinyin:"lìn",wz:"ㄌㄧㄣˋ ㄒㄧㄤ ㄖㄨˊ",wrong:[{z:"ㄌㄧˋ",p:"lì"},{z:"ㄌㄢˊ",p:"lán"}],note:"「藺」讀ㄌㄧㄣˋ；藺草、藺相如皆同。",deep:"1. 注音比較\n藺：ㄌㄧㄣˋ（四聲）＝藺相如、藺草；ㄌㄧˋ＝無此音；ㄌㄢˊ＝無此音（是「蘭」的讀音）\n2. 國字拆解與造字原因\n藺：「艹」＋「閵」（聲），草名（藺草可編蓆），也是姓氏（藺相如）。讀ㄌㄧㄣˋ，與「吝」同音。"},
  {id:"p244",grade:12,word:"臺榭樓閣",target:"榭",zhuyin:"ㄒㄧㄝˋ",pinyin:"xiè",wz:"ㄊㄞˊ ㄒㄧㄝˋ ㄌㄡˊ ㄍㄜˊ",wrong:[{z:"ㄒㄧㄝˊ",p:"xié"},{z:"ㄕㄜˋ",p:"shè"}],note:"「樓榭」的「榭」讀ㄒㄧㄝˋ，建在高臺上的屋子。",deep:"1. 注音比較\n榭：ㄒㄧㄝˋ（四聲）＝樓榭、歌臺舞榭；ㄒㄧㄝˊ＝誤讀（受「斜」影響）；ㄕㄜˋ＝無此音（是「射」的讀音）\n2. 國字拆解與造字原因\n榭：「木」＋「射」（聲），建在高臺上的木造敞屋→水榭、舞榭。讀ㄒㄧㄝˋ，與「謝」同音。"},
  {id:"p245",grade:12,word:"橫槊賦詩",target:"槊",zhuyin:"ㄕㄨㄛˋ",pinyin:"shuò",wz:"ㄏㄥˊ ㄕㄨㄛˋ ㄈㄨˋ ㄕ",wrong:[{z:"ㄙㄨㄛˇ",p:"suǒ"},{z:"ㄕㄨㄛ",p:"shuō"}],note:"「橫槊賦詩」的「槊」讀ㄕㄨㄛˋ，長矛。",deep:"1. 注音比較\n槊：ㄕㄨㄛˋ（四聲）＝橫槊賦詩；ㄙㄨㄛˇ＝無此音（是「索」的讀音）；ㄕㄨㄛ＝誤讀\n2. 國字拆解與造字原因\n槊：「朔」（聲）＋「木」，長柄的矛。蘇軾〈赤壁賦〉寫曹操「橫槊賦詩」——橫持長矛吟詩。讀ㄕㄨㄛˋ。"},
  {id:"p246",grade:12,word:"耆老",target:"耆",zhuyin:"ㄑㄧˊ",pinyin:"qí",wz:"ㄑㄧˊ ㄌㄠˇ",wrong:[{z:"ㄕˋ",p:"shì"},{z:"ㄓˇ",p:"zhǐ"}],note:"「耆老」「耆宿」的「耆」讀ㄑㄧˊ，六十歲以上長者。",deep:"1. 注音比較\n耆：ㄑㄧˊ（二聲）＝耆老、耆宿；ㄕˋ＝無此音（是「嗜」的讀音）；ㄓˇ＝無此音\n2. 國字拆解與造字原因\n耆：從「老（省）」、「旨」（聲），六十歲以上的長者→耆老、耆宿（有名望的老人）。讀ㄑㄧˊ，與「其」同音。"},
  {id:"p247",grade:12,word:"譖言",target:"譖",zhuyin:"ㄗㄣˋ",pinyin:"zèn",wz:"ㄗㄣˋ ㄧㄢˊ",wrong:[{z:"ㄐㄧㄢ",p:"jiān"},{z:"ㄑㄧㄢˊ",p:"qián"}],note:"「譖言」的「譖」讀ㄗㄣˋ，誣陷毀謗的話。",deep:"1. 注音比較\n譖：ㄗㄣˋ（四聲）＝譖言；ㄐㄧㄢ＝無此音；ㄑㄧㄢˊ＝無此音（是「潛」的讀音）\n2. 國字拆解與造字原因\n譖：「言」＋「朁」（聲），進讒毀謗→譖言（誣陷的話）。讀ㄗㄣˋ。"},
  {id:"p248",grade:12,word:"詰問",target:"詰",zhuyin:"ㄐㄧㄝˊ",pinyin:"jié",wz:"ㄐㄧㄝˊ ㄨㄣˋ",wrong:[{z:"ㄐㄧˊ",p:"jí"},{z:"ㄎㄡˋ",p:"kòu"}],note:"「詰問」「反詰」的「詰」讀ㄐㄧㄝˊ，追問責問。",deep:"1. 注音比較\n詰：ㄐㄧㄝˊ（二聲）＝詰問、反詰、盤詰；ㄐㄧˊ＝誤讀；ㄎㄡˋ＝無此音\n2. 國字拆解與造字原因\n詰：「言」＋「吉」（聲），追問責問→詰問、反詰。讀ㄐㄧㄝˊ，與「傑」同音。"},
  {id:"p249",grade:12,word:"罄竹難書",target:"罄",zhuyin:"ㄑㄧㄥˋ",pinyin:"qìng",wz:"ㄑㄧㄥˋ ㄓㄨˊ ㄋㄢˊ ㄕㄨ",wrong:[{z:"ㄑㄧㄥ",p:"qīng"},{z:"ㄒㄧㄣ",p:"xīn"}],note:"「罄竹難書」的「罄」讀ㄑㄧㄥˋ，用盡。",deep:"1. 注音比較\n罄：ㄑㄧㄥˋ（四聲）＝罄竹難書、告罄；ㄑㄧㄥ＝誤讀（受「青」影響）；ㄒㄧㄣ＝無此音（是「馨」的讀音）\n2. 國字拆解與造字原因\n罄：「缶」（瓦器）＋「殸」（聲），器中空了→用盡（存貨告罄、罄竹難書）。讀ㄑㄧㄥˋ，與「慶」同音。"},
  {id:"p250",grade:12,word:"饗宴",target:"饗",zhuyin:"ㄒㄧㄤˇ",pinyin:"xiǎng",wz:"ㄒㄧㄤˇ ㄧㄢˋ",wrong:[{z:"ㄒㄧㄤ",p:"xiāng"},{z:"ㄒㄧㄤˋ",p:"xiàng"}],note:"「饗宴」的「饗」讀ㄒㄧㄤˇ，以酒食款待。",deep:"1. 注音比較\n饗：ㄒㄧㄤˇ（三聲）＝饗宴、以饗讀者；ㄒㄧㄤ＝誤讀；ㄒㄧㄤˋ＝無此音（是「向」的讀音）\n2. 國字拆解與造字原因\n饗：「鄉」（聲）＋「食」，以酒食款待賓客→饗宴；提供給人享用（以饗讀者）。讀ㄒㄧㄤˇ，與「享」同音。"},
  {id:"p251",grade:12,word:"戮力同心",target:"戮",zhuyin:"ㄌㄨˋ",pinyin:"lù",wz:"ㄌㄨˋ ㄌㄧˋ ㄊㄨㄥˊ ㄒㄧㄣ",wrong:[{z:"ㄌㄧㄡˋ",p:"liù"},{z:"ㄌㄨㄛˋ",p:"luò"}],note:"「戮力同心」的「戮」讀ㄌㄨˋ，合力。",deep:"1. 注音比較\n戮：ㄌㄨˋ（四聲）＝戮力同心、殺戮；ㄌㄧㄡˋ＝無此音；ㄌㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n戮：從「戈」，本義是殺（殺戮）；通「勠」表合力→戮力同心（合力一心）。讀ㄌㄨˋ，與「路」同音。"},
  {id:"p252",grade:12,word:"馘首",target:"馘",zhuyin:"ㄍㄨㄛˊ",pinyin:"guó",wz:"ㄍㄨㄛˊ ㄕㄡˇ",wrong:[{z:"ㄒㄩˋ",p:"xù"},{z:"ㄏㄨㄛˋ",p:"huò"}],note:"「馘首」的「馘」讀ㄍㄨㄛˊ，割取首級。",deep:"1. 注音比較\n馘：ㄍㄨㄛˊ（二聲）＝馘首；ㄒㄩˋ＝無此音；ㄏㄨㄛˋ＝無此音（是「獲」的讀音）\n2. 國字拆解與造字原因\n馘：從「首」、「或」（聲），古代戰爭割取敵人首級或左耳計功→馘首。讀ㄍㄨㄛˊ，與「國」同音。"},
  {id:"p253",grade:12,word:"耄耋之年",target:"耄",zhuyin:"ㄇㄠˋ",pinyin:"mào",wz:"ㄇㄠˋ ㄉㄧㄝˊ ㄓ ㄋㄧㄢˊ",wrong:[{z:"ㄇㄠˊ",p:"máo"},{z:"ㄌㄠˇ",p:"lǎo"}],note:"「耄」讀ㄇㄠˋ，八九十歲。",deep:"1. 注音比較\n耄：ㄇㄠˋ（四聲）＝耄耋之年；ㄇㄠˊ＝無此音（是「毛」的讀音）；ㄌㄠˇ＝無此音（是「老」的讀音）\n2. 國字拆解與造字原因\n耄：從「老（省）」、「毛」（聲），八九十歲高齡→耄耋（ㄇㄠˋ ㄉㄧㄝˊ）。讀ㄇㄠˋ，與「冒」同音。"},
  {id:"p254",grade:12,word:"觥籌交錯",target:"觥",zhuyin:"ㄍㄨㄥ",pinyin:"gōng",wz:"ㄍㄨㄥ ㄔㄡˊ ㄐㄧㄠ ㄘㄨㄛˋ",wrong:[{z:"ㄍㄨㄤ",p:"guāng"},{z:"ㄏㄨㄤˊ",p:"huáng"}],note:"「觥」讀ㄍㄨㄥ，古代酒器。",deep:"1. 注音比較\n觥：ㄍㄨㄥ（一聲）＝觥籌交錯；ㄍㄨㄤ＝誤讀（受「光」影響）；ㄏㄨㄤˊ＝無此音\n2. 國字拆解與造字原因\n觥：從「角」，古代獸角形的酒器→觥籌交錯（酒杯與酒籌錯雜，宴飲盡歡）。讀ㄍㄨㄥ，與「公」同音。"},
  {id:"p255",grade:12,word:"泅水",target:"泅",zhuyin:"ㄑㄧㄡˊ",pinyin:"qiú",wz:"ㄑㄧㄡˊ ㄕㄨㄟˇ",wrong:[{z:"ㄒㄧㄡ",p:"xiū"},{z:"ㄧㄡˊ",p:"yóu"}],note:"「泅水」的「泅」讀ㄑㄧㄡˊ，游泳。",deep:"1. 注音比較\n泅：ㄑㄧㄡˊ（二聲）＝泅水、泅泳；ㄒㄧㄡ＝無此音（是「修」的讀音）；ㄧㄡˊ＝無此音（是「游」的讀音）\n2. 國字拆解與造字原因\n泅：「氵」＋「囚」（聲），游水→泅水渡河。讀ㄑㄧㄡˊ，與「求」同音。"},
  {id:"p256",grade:12,word:"胼手胝足",target:"胝",zhuyin:"ㄓ",pinyin:"zhī",wz:"ㄆㄧㄢˊ ㄕㄡˇ ㄓ ㄗㄨˊ",wrong:[{z:"ㄉㄧˇ",p:"dǐ"},{z:"ㄓˇ",p:"zhǐ"}],note:"「胼手胝足」讀ㄆㄧㄢˊ ㄕㄡˇ ㄓ ㄗㄨˊ，手腳長繭，形容辛勞。",deep:"1. 注音比較\n胝：ㄓ（一聲）＝胼手胝足；ㄉㄧˇ＝無此音（是「底」的讀音）；ㄓˇ＝誤讀\n2. 國字拆解與造字原因\n胝：「月（肉）」＋「氐」（聲），手腳因勞動磨出的厚繭。「胼手胝足」（ㄆㄧㄢˊ ㄕㄡˇ ㄓ ㄗㄨˊ）形容極其辛勞。讀一聲ㄓ。"},
  {id:"p257",grade:12,word:"杯盤狼藉",target:"藉",zhuyin:"ㄐㄧˊ",pinyin:"jí",wz:"ㄅㄟ ㄆㄢˊ ㄌㄤˊ ㄐㄧˊ",wrong:[{z:"ㄐㄧㄝˋ",p:"jiè"},{z:"ㄒㄧˊ",p:"xí"}],note:"「狼藉」讀ㄌㄤˊ ㄐㄧˊ；「藉口」「憑藉」讀ㄐㄧㄝˋ。",deep:"1. 注音比較\n藉：ㄐㄧˊ（二聲）＝杯盤狼藉、聲名狼藉；ㄐㄧㄝˋ（四聲）＝藉口、憑藉、慰藉；ㄒㄧˊ＝無此音\n2. 國字拆解與造字原因\n藉：「艹」＋「耤」（聲），本義是草墊。「狼藉」（傳說狼群臥草後一片凌亂）讀ㄐㄧˊ；依靠、假託讀ㄐㄧㄝˋ。記法：狼藉ㄐㄧˊ、藉口ㄐㄧㄝˋ。"},
  {id:"p258",grade:12,word:"掣肘",target:"掣",zhuyin:"ㄔㄜˋ",pinyin:"chè",wz:"ㄔㄜˋ ㄓㄡˇ",wrong:[{z:"ㄓˋ",p:"zhì"},{z:"ㄕˋ",p:"shì"}],note:"「掣肘」的「掣」讀ㄔㄜˋ，牽制阻撓。",deep:"1. 注音比較\n掣：ㄔㄜˋ（四聲）＝掣肘、風馳電掣；ㄓˋ＝誤讀（受「制」影響）；ㄕˋ＝無此音\n2. 國字拆解與造字原因\n掣：「制」（聲）＋「手」，拉扯、牽制→掣肘（拉住手肘，比喻從旁阻撓）；快速拉過→電掣。讀ㄔㄜˋ，與「徹」同音。"},
  {id:"p259",grade:12,word:"僭主",target:"僭",zhuyin:"ㄐㄧㄢˋ",pinyin:"jiàn",wz:"ㄐㄧㄢˋ ㄓㄨˇ",wrong:[{z:"ㄗㄢˋ",p:"zàn"},{z:"ㄑㄧㄢ",p:"qiān"}],note:"「僭」讀ㄐㄧㄢˋ，越分冒用。",deep:"1. 注音比較\n僭：ㄐㄧㄢˋ（四聲）＝僭主、僭越；ㄗㄢˋ＝無此音（是「贊」的讀音）；ㄑㄧㄢ＝無此音\n2. 國字拆解與造字原因\n僭：「亻」＋「朁」（聲），超越本分冒用上位名器→僭越、僭主（非法奪位者）。讀ㄐㄧㄢˋ，與「見」同音。"},
  {id:"p260",grade:12,word:"謳歌",target:"謳",zhuyin:"ㄡ",pinyin:"ōu",wz:"ㄡ ㄍㄜ",wrong:[{z:"ㄑㄩ",p:"qū"},{z:"ㄡˇ",p:"ǒu"}],note:"「謳歌」的「謳」讀ㄡ，歌頌。",deep:"1. 注音比較\n謳：ㄡ（一聲）＝謳歌；ㄑㄩ＝無此音（是「驅」的讀音）；ㄡˇ＝誤讀\n2. 國字拆解與造字原因\n謳：「言」＋「區」（聲），歌唱→謳歌（歌頌讚美）。讀一聲ㄡ，與「歐」同音。"},
  {id:"p261",grade:6,word:"拓印",target:"拓",zhuyin:"ㄊㄚˋ",pinyin:"tà",wz:"ㄊㄚˋ ㄧㄣˋ",wrong:[{z:"ㄊㄨㄛˋ",p:"tuò"},{z:"ㄓㄨㄛˊ",p:"zhuó"}],note:"「拓印」「拓本」讀ㄊㄚˋ；「開拓」讀ㄊㄨㄛˋ。",deep:"1. 注音比較\n拓：ㄊㄚˋ（四聲）＝拓印、拓本、拓碑；ㄊㄨㄛˋ（四聲）＝開拓、拓展；ㄓㄨㄛˊ＝無此音\n2. 國字拆解與造字原因\n拓：形聲字，「扌」＋「石」（聲）。用手開墾擴展讀ㄊㄨㄛˋ（開拓）；把碑刻文字撲印在紙上讀ㄊㄚˋ（拓印、拓本）。記法：印碑ㄊㄚˋ、開展ㄊㄨㄛˋ。"},
  {id:"p262",grade:6,word:"綻開",target:"綻",zhuyin:"ㄓㄢˋ",pinyin:"zhàn",wz:"ㄓㄢˋ ㄎㄞ",wrong:[{z:"ㄉㄧㄥˋ",p:"dìng"},{z:"ㄒㄧㄢˋ",p:"xiàn"}],note:"「綻開」「綻裂」的「綻」讀ㄓㄢˋ。",deep:"1. 注音比較\n綻：ㄓㄢˋ（四聲）＝綻開、綻放、破綻；ㄉㄧㄥˋ＝無此音（是「定」的讀音）；ㄒㄧㄢˋ＝無此音\n2. 國字拆解與造字原因\n綻：形聲字，「糸」＋「定」（聲），衣縫裂開→破綻；花苞裂開→綻放。從「定」得聲卻讀ㄓㄢˋ。"},
  {id:"p263",grade:6,word:"魚鰭",target:"鰭",zhuyin:"ㄑㄧˊ",pinyin:"qí",wz:"ㄩˊ ㄑㄧˊ",wrong:[{z:"ㄑㄧ",p:"qī"},{z:"ㄕˋ",p:"shì"}],note:"「魚鰭」的「鰭」讀ㄑㄧˊ。",deep:"1. 注音比較\n鰭：ㄑㄧˊ（二聲）＝魚鰭、背鰭；ㄑㄧ＝誤讀；ㄕˋ＝無此音\n2. 國字拆解與造字原因\n鰭：形聲字，「魚」＋「耆」（聲），魚類游泳的薄膜器官。與「旗」同音ㄑㄧˊ——魚鰭像魚身上的小旗，好記。"},
  {id:"p264",grade:6,word:"迂迴",target:"迂",zhuyin:"ㄩ",pinyin:"yū",wz:"ㄩ ㄏㄨㄟˊ",wrong:[{z:"ㄩˊ",p:"yú"},{z:"ㄒㄩ",p:"xū"}],note:"「迂迴」「迂腐」的「迂」讀ㄩ。",deep:"1. 注音比較\n迂：ㄩ（一聲）＝迂迴、迂腐；ㄩˊ＝誤讀（受「于」影響）；ㄒㄩ＝無此音（是「需」的讀音）\n2. 國字拆解與造字原因\n迂：形聲字，「辶」＋「于」（聲），繞遠路→迂迴；思想繞遠不切實際→迂腐。讀一聲ㄩ。"},
  {id:"p265",grade:6,word:"眷戀",target:"眷",zhuyin:"ㄐㄩㄢˋ",pinyin:"juàn",wz:"ㄐㄩㄢˋ ㄌㄧㄢˋ",wrong:[{z:"ㄐㄩㄢ",p:"juān"},{z:"ㄑㄩㄢˋ",p:"quàn"}],note:"「眷戀」「眷村」的「眷」讀ㄐㄩㄢˋ。",deep:"1. 注音比較\n眷：ㄐㄩㄢˋ（四聲）＝眷戀、眷屬、眷村；ㄐㄩㄢ＝無此音（是「捐」的讀音）；ㄑㄩㄢˋ＝無此音（是「勸」的讀音）\n2. 國字拆解與造字原因\n眷：從「目」，本義是回頭看→顧念不捨（眷戀）；所顧念的家人→眷屬。讀ㄐㄩㄢˋ。"},
  {id:"p266",grade:6,word:"堤岸",target:"岸",zhuyin:"ㄢˋ",pinyin:"àn",wz:"ㄊㄧˊ ㄢˋ",wrong:[{z:"ㄢˊ",p:"án"},{z:"ㄏㄢˋ",p:"hàn"}],note:"「堤岸」讀ㄊㄧˊ ㄢˋ。",deep:"1. 注音比較\n岸：ㄢˋ（四聲）＝堤岸、河岸、對岸；ㄢˊ＝無此音；ㄏㄢˋ＝無此音（是「漢」的讀音）\n2. 國字拆解與造字原因\n岸：形聲字，「山」＋「厂」「干」（聲），水邊高起的陸地→河岸、海岸。讀ㄢˋ。"},
  {id:"p267",grade:6,word:"卑躬屈膝",target:"屈",zhuyin:"ㄑㄩ",pinyin:"qū",wz:"ㄅㄟ ㄍㄨㄥ ㄑㄩ ㄒㄧ",wrong:[{z:"ㄑㄩˇ",p:"qǔ"},{z:"ㄐㄩˊ",p:"jú"}],note:"「屈膝」「委屈」的「屈」讀ㄑㄩ。",deep:"1. 注音比較\n屈：ㄑㄩ（一聲）＝屈膝、委屈、屈服；ㄑㄩˇ＝無此音（是「取」的讀音）；ㄐㄩˊ＝無此音（是「局」的讀音）\n2. 國字拆解與造字原因\n屈：形聲字，「尸」（人形）＋「出」（聲），身體彎曲→屈膝；受壓不能伸張→委屈、屈服。讀一聲ㄑㄩ。"},
  {id:"p268",grade:6,word:"手足無措",target:"措",zhuyin:"ㄘㄨㄛˋ",pinyin:"cuò",wz:"ㄕㄡˇ ㄗㄨˊ ㄨˊ ㄘㄨㄛˋ",wrong:[{z:"ㄗㄨㄛˋ",p:"zuò"},{z:"ㄘㄨㄛ",p:"cuō"}],note:"「措手不及」「措施」的「措」讀ㄘㄨㄛˋ。",deep:"1. 注音比較\n措：ㄘㄨㄛˋ（四聲）＝措施、措手不及、手足無措；ㄗㄨㄛˋ＝無此音（是「做」的讀音）；ㄘㄨㄛ＝無此音（是「搓」的讀音）\n2. 國字拆解與造字原因\n措：形聲字，「扌」＋「昔」（聲），本義是安放、安排→措施（安排的辦法）、手足無措（手腳不知往哪放）。讀ㄘㄨㄛˋ。"},
  {id:"p269",grade:6,word:"諷刺",target:"諷",zhuyin:"ㄈㄥˋ",pinyin:"fèng",wz:"ㄈㄥˋ ㄘˋ",wrong:[{z:"ㄈㄥ",p:"fēng"},{z:"ㄈㄥˊ",p:"féng"}],note:"「諷刺」「嘲諷」的「諷」讀ㄈㄥˋ。",deep:"1. 注音比較\n諷：ㄈㄥˋ（四聲）＝諷刺、嘲諷、譏諷；ㄈㄥ＝誤讀（受「風」影響）；ㄈㄥˊ＝無此音（是「逢」的讀音）\n2. 國字拆解與造字原因\n諷：形聲字，「言」＋「風」（聲），本義是不看書本背誦，引申為用含蓄的話勸告譏刺→諷刺。讀四聲ㄈㄥˋ。"},
  {id:"p270",grade:6,word:"泥濘",target:"濘",zhuyin:"ㄋㄧㄥˋ",pinyin:"nìng",wz:"ㄋㄧˊ ㄋㄧㄥˋ",wrong:[{z:"ㄋㄧㄥˊ",p:"níng"},{z:"ㄓㄥ",p:"zhēng"}],note:"「泥濘」的「濘」讀ㄋㄧㄥˋ。",deep:"1. 注音比較\n濘：ㄋㄧㄥˋ（四聲）＝泥濘；ㄋㄧㄥˊ＝誤讀（受「寧」影響）；ㄓㄥ＝無此音\n2. 國字拆解與造字原因\n濘：形聲字，「氵」＋「寧」（聲），爛泥積水→泥濘。從「寧」得聲卻讀四聲ㄋㄧㄥˋ。"},
  {id:"p271",grade:7,word:"惋惜",target:"惋",zhuyin:"ㄨㄢˋ",pinyin:"wàn",wz:"ㄨㄢˋ ㄒㄧˊ",wrong:[{z:"ㄨㄢˇ",p:"wǎn"},{z:"ㄩㄢˋ",p:"yuàn"}],note:"教育部審訂音「惋惜」的「惋」讀ㄨㄢˋ（四聲），不是ㄨㄢˇ。",deep:"1. 注音比較\n惋：ㄨㄢˋ＝惋惜、悵惋。★教育部《國語辭典簡編本》「惋」只收ㄨㄢˋ一音，讀成三聲ㄨㄢˇ不是審訂音；同聲符的「宛」讀ㄨㄢˇ、「腕」讀ㄨㄢˋ、「婉」讀ㄨㄢˇ\n2. 國字拆解與造字原因\n惋：形聲字，「忄（心）」＋「宛」（聲），心裡感到可惜、嘆息，所以從心部。"},
  {id:"p272",grade:7,word:"貯藏",target:"貯",zhuyin:"ㄓㄨˇ",pinyin:"zhǔ",wz:"ㄓㄨˇ ㄘㄤˊ",wrong:[{z:"ㄔㄨˊ",p:"chú"},{z:"ㄉㄧㄥˇ",p:"dǐng"}],note:"「貯藏」「貯存」的「貯」讀ㄓㄨˇ。",deep:"1. 注音比較\n貯：ㄓㄨˇ（三聲）＝貯藏、貯存、貯水；ㄔㄨˊ＝無此音（是「儲」的讀音）；ㄉㄧㄥˇ＝無此音\n2. 國字拆解與造字原因\n貯：形聲字，「貝」（財物）＋「宁」（聲），積存財物→貯藏。與同義的「儲」（ㄔㄨˊ）讀音不同，注意分辨。"},
  {id:"p273",grade:7,word:"瑰麗",target:"瑰",zhuyin:"ㄍㄨㄟ",pinyin:"guī",wz:"ㄍㄨㄟ ㄌㄧˋ",wrong:[{z:"ㄍㄨㄟˋ",p:"guì"},{z:"ㄎㄨㄟˊ",p:"kuí"}],note:"「瑰麗」「玫瑰」的「瑰」讀ㄍㄨㄟ。",deep:"1. 注音比較\n瑰：ㄍㄨㄟ（一聲）＝瑰麗、玫瑰、瑰寶；ㄍㄨㄟˋ＝誤讀；ㄎㄨㄟˊ＝無此音（是「魁」的讀音）\n2. 國字拆解與造字原因\n瑰：形聲字，「𤣩（玉）」＋「鬼」（聲），美玉、美石→瑰寶、瑰麗（如美玉般華美）。讀一聲ㄍㄨㄟ。"},
  {id:"p274",grade:7,word:"剎那",target:"剎",zhuyin:"ㄔㄚˋ",pinyin:"chà",wz:"ㄔㄚˋ ㄋㄚˋ",wrong:[{z:"ㄕㄚ",p:"shā"},{z:"ㄙㄚˋ",p:"sà"}],note:"「剎那」讀ㄔㄚˋ；「煞車」的「煞」讀ㄕㄚ。",deep:"1. 注音比較\n剎：ㄔㄚˋ（四聲）＝剎那、古剎；ㄕㄚ（一聲）＝剎車（同「煞車」）；ㄙㄚˋ＝無此音\n2. 國字拆解與造字原因\n剎：梵語音譯字，「剎那」（極短時間）、「古剎」（佛寺）讀ㄔㄚˋ；「剎車」借作「煞車」讀ㄕㄚ。"},
  {id:"p275",grade:7,word:"眼眶",target:"眶",zhuyin:"ㄎㄨㄤ",pinyin:"kuāng",wz:"ㄧㄢˇ ㄎㄨㄤ",wrong:[{z:"ㄎㄨㄤˋ",p:"kuàng"},{z:"ㄍㄨㄤ",p:"guāng"}],note:"「眼眶」的「眶」讀ㄎㄨㄤ，常被誤讀成ㄎㄨㄤˋ。",deep:"1. 注音比較\n眶：ㄎㄨㄤ（一聲）＝眼眶、熱淚盈眶；ㄎㄨㄤˋ＝誤讀（受「況」影響）；ㄍㄨㄤ＝無此音\n2. 國字拆解與造字原因\n眶：形聲字，「目」＋「匡」（聲，方框），眼睛周圍的框→眼眶。讀一聲ㄎㄨㄤ。"},
  {id:"p276",grade:7,word:"歸咎",target:"咎",zhuyin:"ㄐㄧㄡˋ",pinyin:"jiù",wz:"ㄍㄨㄟ ㄐㄧㄡˋ",wrong:[{z:"ㄐㄧㄡ",p:"jiū"},{z:"ㄍㄨˋ",p:"gù"}],note:"「歸咎」「咎由自取」的「咎」讀ㄐㄧㄡˋ，過失。",deep:"1. 注音比較\n咎：ㄐㄧㄡˋ（四聲）＝歸咎、咎由自取、引咎辭職；ㄐㄧㄡ＝誤讀；ㄍㄨˋ＝無此音\n2. 國字拆解與造字原因\n咎：會意字，「人」＋「各」（相違背），人與人相違而生過失→罪過、責備（歸咎）。讀ㄐㄧㄡˋ。"},
  {id:"p277",grade:7,word:"星羅棋布",target:"布",zhuyin:"ㄅㄨˋ",pinyin:"bù",wz:"ㄒㄧㄥ ㄌㄨㄛˊ ㄑㄧˊ ㄅㄨˋ",wrong:[{z:"ㄅㄨˇ",p:"bǔ"},{z:"ㄆㄨ",p:"pū"}],note:"「星羅棋布」的「布」讀ㄅㄨˋ，分布。",deep:"1. 注音比較\n布：ㄅㄨˋ（四聲）＝星羅棋布、分布、宣布；ㄅㄨˇ＝無此音（是「補」的讀音）；ㄆㄨ＝無此音（是「鋪」的讀音）\n2. 國字拆解與造字原因\n布：從「巾」，本義是麻織品，鋪展開來→分布、散布。「星羅棋布」＝像星星羅列、棋子分布，形容多而密。"},
  {id:"p278",grade:7,word:"傾瀉",target:"瀉",zhuyin:"ㄒㄧㄝˋ",pinyin:"xiè",wz:"ㄑㄧㄥ ㄒㄧㄝˋ",wrong:[{z:"ㄒㄧㄝˇ",p:"xiě"},{z:"ㄕㄜˋ",p:"shè"}],note:"「傾瀉」「腹瀉」的「瀉」讀ㄒㄧㄝˋ。",deep:"1. 注音比較\n瀉：ㄒㄧㄝˋ（四聲）＝傾瀉、腹瀉、一瀉千里；ㄒㄧㄝˇ＝誤讀（受「寫」影響）；ㄕㄜˋ＝無此音\n2. 國字拆解與造字原因\n瀉：形聲字，「氵」＋「寫」（聲），水急速往下流→傾瀉、腹瀉。讀ㄒㄧㄝˋ，與「寫」（ㄒㄧㄝˇ）不同調。"},
  {id:"p279",grade:7,word:"游說",target:"游",zhuyin:"ㄧㄡˊ",pinyin:"yóu",wz:"ㄧㄡˊ ㄕㄨㄟˋ",wrong:[{z:"ㄧㄡˋ",p:"yòu"},{z:"ㄌㄧㄡˊ",p:"liú"}],note:"「游說」讀ㄧㄡˊ ㄕㄨㄟˋ。",deep:"1. 注音比較\n游：ㄧㄡˊ（二聲）＝游說（ㄧㄡˊ ㄕㄨㄟˋ）、游泳；ㄧㄡˋ＝無此音（是「右」的讀音）；ㄌㄧㄡˊ＝無此音（是「流」的讀音）\n2. 國字拆解與造字原因\n游：形聲字，「氵」＋「斿」（聲），本義是在水中行進；「游說」是奔走各國勸說（像水般流動奔走），「游」讀ㄧㄡˊ、「說」讀ㄕㄨㄟˋ。"},
  {id:"p280",grade:7,word:"埋伏",target:"埋",zhuyin:"ㄇㄞˊ",pinyin:"mái",wz:"ㄇㄞˊ ㄈㄨˊ",wrong:[{z:"ㄇㄢˊ",p:"mán"},{z:"ㄌㄧˇ",p:"lǐ"}],note:"「埋伏」「掩埋」讀ㄇㄞˊ；「埋怨」讀ㄇㄢˊ。",deep:"1. 注音比較\n埋：ㄇㄞˊ（二聲）＝埋伏、掩埋、埋藏；ㄇㄢˊ（二聲）＝埋怨；ㄌㄧˇ＝無此音（是「里」的讀音）\n2. 國字拆解與造字原因\n埋：形聲字，「土」＋「里」（聲），把東西藏進土裡→掩埋、埋伏（ㄇㄞˊ）；心中藏著不滿說出來→埋怨（ㄇㄢˊ）。"},
  {id:"p281",grade:8,word:"翩翩起舞",target:"翩",zhuyin:"ㄆㄧㄢ",pinyin:"piān",wz:"ㄆㄧㄢ ㄆㄧㄢ ㄑㄧˇ ㄨˇ",wrong:[{z:"ㄅㄧㄢ",p:"biān"},{z:"ㄆㄧㄢˊ",p:"pián"}],note:"「翩翩」的「翩」讀ㄆㄧㄢ。",deep:"1. 注音比較\n翩：ㄆㄧㄢ（一聲）＝翩翩起舞、翩然；ㄅㄧㄢ＝無此音（是「編」的讀音）；ㄆㄧㄢˊ＝無此音\n2. 國字拆解與造字原因\n翩：形聲字，「羽」＋「扁」（聲），鳥輕快飛翔的樣子→翩翩起舞（輕盈飄逸）。讀一聲ㄆㄧㄢ。"},
  {id:"p282",grade:8,word:"信箋",target:"箋",zhuyin:"ㄐㄧㄢ",pinyin:"jiān",wz:"ㄒㄧㄣˋ ㄐㄧㄢ",wrong:[{z:"ㄑㄧㄢ",p:"qiān"},{z:"ㄐㄧㄢˋ",p:"jiàn"}],note:"「信箋」「便箋」的「箋」讀ㄐㄧㄢ。",deep:"1. 注音比較\n箋：ㄐㄧㄢ（一聲）＝信箋、便箋、箋注；ㄑㄧㄢ＝誤讀（受「籤」影響）；ㄐㄧㄢˋ＝無此音\n2. 國字拆解與造字原因\n箋：形聲字，「竹」＋「戔」（聲），本義是注釋經書的小竹片→書信用紙（信箋）。讀ㄐㄧㄢ。"},
  {id:"p283",grade:8,word:"抽搐",target:"搐",zhuyin:"ㄔㄨˋ",pinyin:"chù",wz:"ㄔㄡ ㄔㄨˋ",wrong:[{z:"ㄒㄩˋ",p:"xù"},{z:"ㄉㄨˋ",p:"dù"}],note:"「抽搐」的「搐」讀ㄔㄨˋ。",deep:"1. 注音比較\n搐：ㄔㄨˋ（四聲）＝抽搐；ㄒㄩˋ＝誤讀（受「蓄」影響）；ㄉㄨˋ＝無此音\n2. 國字拆解與造字原因\n搐：形聲字，「扌」＋「畜」（聲），肌肉不自主地牽動抽動→抽搐。讀ㄔㄨˋ。"},
  {id:"p284",grade:8,word:"踱步",target:"踱",zhuyin:"ㄉㄨㄛˋ",pinyin:"duò",wz:"ㄉㄨㄛˋ ㄅㄨˋ",wrong:[{z:"ㄉㄨˋ",p:"dù"},{z:"ㄊㄨㄛˋ",p:"tuò"}],note:"「踱步」的「踱」讀ㄉㄨㄛˋ，慢步行走。",deep:"1. 注音比較\n踱：ㄉㄨㄛˋ（四聲）＝踱步、踱來踱去；ㄉㄨˋ＝誤讀（受「度」影響）；ㄊㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n踱：形聲字，「足」＋「度」（聲），慢步行走→踱步。從「度」得聲卻讀ㄉㄨㄛˋ。"},
  {id:"p285",grade:8,word:"堆疊",target:"疊",zhuyin:"ㄉㄧㄝˊ",pinyin:"dié",wz:"ㄉㄨㄟ ㄉㄧㄝˊ",wrong:[{z:"ㄊㄚˇ",p:"tǎ"},{z:"ㄉㄧㄝˋ",p:"diè"}],note:"「堆疊」「重疊」的「疊」讀ㄉㄧㄝˊ。",deep:"1. 注音比較\n疊：ㄉㄧㄝˊ（二聲）＝堆疊、重疊、疊字；ㄊㄚˇ＝無此音（是「塔」的讀音）；ㄉㄧㄝˋ＝誤讀\n2. 國字拆解與造字原因\n疊：會意字，物品一層層堆起（畾＝堆積）→重疊、摺疊。讀二聲ㄉㄧㄝˊ。"},
  {id:"p286",grade:8,word:"要塞",target:"塞",zhuyin:"ㄙㄞˋ",pinyin:"sài",wz:"ㄧㄠˋ ㄙㄞˋ",wrong:[{z:"ㄙㄞ",p:"sāi"},{z:"ㄙㄜˋ",p:"sè"}],note:"「要塞」「邊塞」讀ㄙㄞˋ；「瓶塞」讀ㄙㄞ；「閉塞」讀ㄙㄜˋ。",deep:"1. 注音比較\n塞：ㄙㄞˋ（四聲）＝要塞、邊塞、塞外；ㄙㄞ（一聲）＝瓶塞、塞住；ㄙㄜˋ（四聲）＝閉塞、阻塞\n2. 國字拆解與造字原因\n塞：屋內填土堵塞之形。堵住讀ㄙㄞ；邊防要地（堵住敵人之處）讀ㄙㄞˋ；文言的堵塞不通讀ㄙㄜˋ。一字三音常考。"},
  {id:"p287",grade:8,word:"胚胎",target:"胚",zhuyin:"ㄆㄟ",pinyin:"pēi",wz:"ㄆㄟ ㄊㄞ",wrong:[{z:"ㄅㄟ",p:"bēi"},{z:"ㄆㄧ",p:"pī"}],note:"「胚胎」的「胚」讀ㄆㄟ。",deep:"1. 注音比較\n胚：ㄆㄟ（一聲）＝胚胎、胚芽；ㄅㄟ＝誤讀（受「杯」影響）；ㄆㄧ＝無此音（是「批」的讀音）\n2. 國字拆解與造字原因\n胚：形聲字，「月（肉）」＋「丕」（聲），生物發育初期的雛體→胚胎、胚芽。讀ㄆㄟ。"},
  {id:"p288",grade:8,word:"眺望",target:"眺",zhuyin:"ㄊㄧㄠˋ",pinyin:"tiào",wz:"ㄊㄧㄠˋ ㄨㄤˋ",wrong:[{z:"ㄓㄠˋ",p:"zhào"},{z:"ㄊㄧㄠ",p:"tiāo"}],note:"「眺望」「遠眺」的「眺」讀ㄊㄧㄠˋ。",deep:"1. 注音比較\n眺：ㄊㄧㄠˋ（四聲）＝眺望、遠眺；ㄓㄠˋ＝無此音（是「兆」的讀音）；ㄊㄧㄠ＝無此音（是「挑」的讀音）\n2. 國字拆解與造字原因\n眺：形聲字，「目」＋「兆」（聲），從高處向遠方看→眺望。讀ㄊㄧㄠˋ，與「跳」同音。"},
  {id:"p289",grade:8,word:"揣測",target:"揣",zhuyin:"ㄔㄨㄞˇ",pinyin:"chuǎi",wz:"ㄔㄨㄞˇ ㄘㄜˋ",wrong:[{z:"ㄔㄨㄢˇ",p:"chuǎn"},{z:"ㄉㄨㄢ",p:"duān"}],note:"「揣測」「揣摩」的「揣」讀ㄔㄨㄞˇ。",deep:"1. 注音比較\n揣：ㄔㄨㄞˇ（三聲）＝揣測、揣摩；ㄔㄨㄢˇ＝無此音（是「喘」的讀音）；ㄉㄨㄢ＝無此音（是「端」的讀音）\n2. 國字拆解與造字原因\n揣：形聲字，「扌」＋「耑」（聲），本義是估量——用手掂量→揣測、揣摩（用心推想）。讀ㄔㄨㄞˇ。"},
  {id:"p290",grade:8,word:"隕石",target:"隕",zhuyin:"ㄩㄣˇ",pinyin:"yǔn",wz:"ㄩㄣˇ ㄕˊ",wrong:[{z:"ㄩㄣˊ",p:"yún"},{z:"ㄩㄢˊ",p:"yuán"}],note:"「隕石」「隕落」的「隕」讀ㄩㄣˇ。",deep:"1. 注音比較\n隕：ㄩㄣˇ（三聲）＝隕石、隕落；ㄩㄣˊ＝誤讀（受「雲」影響）；ㄩㄢˊ＝無此音（是「員」的讀音）\n2. 國字拆解與造字原因\n隕：形聲字，「阝（阜，高處）」＋「員」（聲），從高處墜落→隕落、隕石（天上掉下的石頭）。讀ㄩㄣˇ。"},
  {id:"p291",grade:9,word:"作坊",target:"坊",zhuyin:"ㄈㄤ",pinyin:"fāng",wz:"ㄗㄨㄛˋ ㄈㄤ",wrong:[{z:"ㄈㄤˊ",p:"fáng"},{z:"ㄈㄤˇ",p:"fǎng"}],note:"教育部審訂音「作坊」的「坊」讀ㄈㄤ（一聲）；街坊、磨坊、染坊也都讀ㄈㄤ。",deep:"1. 注音比較\n坊：ㄈㄤ＝作坊、工作坊、街坊、茶坊、書坊、磨坊、染坊。★教育部《國語辭典簡編本》「坊」的詞例都讀一聲ㄈㄤ，讀成ㄈㄤˊ不是審訂音\n2. 國字拆解與造字原因\n坊：形聲字，「土」＋「方」（聲）。本義是城裡劃分整齊的里巷（街坊），後來也指做手工的小工場（作坊、磨坊）。從土部，因為都是土地上劃出來的區塊。"},
  {id:"p292",grade:9,word:"栓塞",target:"塞",zhuyin:"ㄙㄜˋ",pinyin:"sè",wz:"ㄕㄨㄢ ㄙㄜˋ",wrong:[{z:"ㄙㄞ",p:"sāi"},{z:"ㄙㄞˋ",p:"sài"}],note:"醫學「栓塞」「梗塞」的「塞」讀ㄙㄜˋ。",deep:"1. 注音比較\n塞：ㄙㄜˋ（四聲）＝栓塞、梗塞、閉塞（書面文言）；ㄙㄞ（一聲）＝塞車、塞住；ㄙㄞˋ（四聲）＝要塞\n2. 國字拆解與造字原因\n塞：填堵之義。醫學與書面語的「堵塞不通」讀ㄙㄜˋ（心肌梗塞、栓塞）；口語動作讀ㄙㄞ；邊防要地讀ㄙㄞˋ。"},
  {id:"p293",grade:9,word:"挾持",target:"挾",zhuyin:"ㄒㄧㄚˊ",pinyin:"xiá",wz:"ㄒㄧㄚˊ ㄔˊ",wrong:[{z:"ㄒㄧㄝˊ",p:"xié"},{z:"ㄐㄧㄚˊ",p:"jiá"}],note:"教育部審訂音「挾」只有一個讀音ㄒㄧㄚˊ：挾持、要挾、挾怨都讀ㄒㄧㄚˊ。",deep:"1. 注音比較\n挾：ㄒㄧㄚˊ＝挾持、要挾、挾制、挾迫、挾恨、挾怨。★教育部《國語辭典簡編本》「挾」只收ㄒㄧㄚˊ一音，讀成ㄒㄧㄝˊ不是審訂音\n2. 國字拆解與造字原因\n挾：形聲字，「扌（手）」＋「夾」（聲）。本義是用胳膊夾住東西，引申為用強力控制人（挾持）、心裡夾著怨恨（挾怨）。從手部，因為是手臂的動作。"},
  {id:"p294",grade:9,word:"稜角",target:"稜",zhuyin:"ㄌㄥˊ",pinyin:"léng",wz:"ㄌㄥˊ ㄐㄧㄠˇ",wrong:[{z:"ㄌㄧㄥˊ",p:"líng"},{z:"ㄌㄥˋ",p:"lèng"}],note:"「稜角」「三稜鏡」的「稜」讀ㄌㄥˊ。",deep:"1. 注音比較\n稜：ㄌㄥˊ（二聲）＝稜角、三稜鏡、模稜兩可；ㄌㄧㄥˊ＝誤讀（受「陵」影響）；ㄌㄥˋ＝無此音\n2. 國字拆解與造字原因\n稜：形聲字，「禾」＋「夌」（聲），物體的邊角條紋→稜角、稜線。讀ㄌㄥˊ。"},
  {id:"p295",grade:9,word:"粗礪",target:"礪",zhuyin:"ㄌㄧˋ",pinyin:"lì",wz:"ㄘㄨ ㄌㄧˋ",wrong:[{z:"ㄌㄞˋ",p:"lài"},{z:"ㄨㄟˋ",p:"wèi"}],note:"「砥礪」「磨礪」的「礪」讀ㄌㄧˋ，磨刀石。",deep:"1. 注音比較\n礪：ㄌㄧˋ（四聲）＝砥礪、磨礪；ㄌㄞˋ＝無此音（是「賴」的讀音）；ㄨㄟˋ＝無此音\n2. 國字拆解與造字原因\n礪：形聲字，「石」＋「厲」（聲），粗磨刀石→磨練（砥礪品行）。讀ㄌㄧˋ，與「厲」音近意通（「再接再厲」的厲即通礪）。"},
  {id:"p296",grade:9,word:"憎惡",target:"惡",zhuyin:"ㄨˋ",pinyin:"wù",wz:"ㄗㄥ ㄨˋ",wrong:[{z:"ㄜˋ",p:"è"},{z:"ㄨ",p:"wū"}],note:"「憎惡」「厭惡」（討厭）讀ㄨˋ；「罪惡」讀ㄜˋ；「惡心」讀ㄜˇ。",deep:"1. 注音比較\n惡：ㄨˋ（四聲）＝憎惡、厭惡、深惡痛絕（討厭）；ㄜˋ（四聲）＝罪惡、惡人（壞）；ㄜˇ（三聲）＝惡心\n2. 國字拆解與造字原因\n惡：形聲字，「亞」（聲）＋「心」，心所厭棄。當名詞形容詞「壞」讀ㄜˋ；當動詞「討厭」讀ㄨˋ；「惡心」（想吐）讀ㄜˇ。一字三音常考。"},
  {id:"p297",grade:9,word:"擂臺",target:"擂",zhuyin:"ㄌㄟˊ",pinyin:"léi",wz:"ㄌㄟˊ ㄊㄞˊ",wrong:[{z:"ㄌㄟˋ",p:"lèi"},{z:"ㄌㄟˇ",p:"lěi"}],note:"審訂音「擂臺」「打擂」的「擂」讀ㄌㄟˊ。",deep:"1. 注音比較\n擂：ㄌㄟˊ（二聲）＝擂臺、打擂、自吹自擂（審訂音）；ㄌㄟˋ＝俗讀，審訂表不採；ㄌㄟˇ＝無此音\n2. 國字拆解與造字原因\n擂：形聲字，「扌」＋「雷」（聲），敲打（擂鼓）→比武的高臺「擂臺」（敲鼓開賽）。審訂音統讀ㄌㄟˊ。"},
  {id:"p298",grade:9,word:"畜牧",target:"畜",zhuyin:"ㄒㄩˋ",pinyin:"xù",wz:"ㄒㄩˋ ㄇㄨˋ",wrong:[{z:"ㄔㄨˋ",p:"chù"},{z:"ㄒㄩ",p:"xū"}],note:"「畜牧」「畜養」（動詞）讀ㄒㄩˋ；「牲畜」「家畜」（名詞）讀ㄔㄨˋ。",deep:"1. 注音比較\n畜：ㄒㄩˋ（四聲）＝畜牧、畜養（動詞：飼養）；ㄔㄨˋ（四聲）＝牲畜、家畜（名詞：動物）；ㄒㄩ＝無此音\n2. 國字拆解與造字原因\n畜：田中積存草料以養牲口。飼養的動作讀ㄒㄩˋ；被養的動物讀ㄔㄨˋ。記法：動詞ㄒㄩˋ、名詞ㄔㄨˋ。"},
  {id:"p299",grade:9,word:"軋戲",target:"軋",zhuyin:"ㄍㄚˊ",pinyin:"gá",wz:"ㄍㄚˊ ㄒㄧˋ",wrong:[{z:"ㄧㄚˋ",p:"yà"},{z:"ㄓㄚˊ",p:"zhá"}],note:"「軋戲」「軋車」讀ㄍㄚˊ；「傾軋」讀ㄧㄚˋ。",deep:"1. 注音比較\n軋：ㄍㄚˊ（二聲）＝軋戲、軋車、軋朋友（口語：擠、結交）；ㄧㄚˋ（四聲）＝傾軋、軋棉（碾壓、排擠）；ㄓㄚˊ＝軋鋼（軋輥）\n2. 國字拆解與造字原因\n軋：形聲字，「車」＋「乙」（聲），本義是車輪碾壓（ㄧㄚˋ）；口語「擠、趕場」讀ㄍㄚˊ（軋戲）；工業軋鋼讀ㄓㄚˊ。一字三音。"},
  {id:"p300",grade:9,word:"畏縮",target:"縮",zhuyin:"ㄙㄨㄛ",pinyin:"suō",wz:"ㄨㄟˋ ㄙㄨㄛ",wrong:[{z:"ㄙㄨˋ",p:"sù"},{z:"ㄕㄨㄛˋ",p:"shuò"}],note:"「畏縮」「縮小」的「縮」讀ㄙㄨㄛ。",deep:"1. 注音比較\n縮：ㄙㄨㄛ（一聲）＝畏縮、縮小、退縮；ㄙㄨˋ＝無此音（是「宿」的讀音）；ㄕㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n縮：形聲字，「糸」＋「宿」（聲），繩子收緊變短→縮小、退縮。讀ㄙㄨㄛ。"},
  // ---- 2026-08-02 三輪擴充:p301-p450 ----
  {id:"p301",grade:1,word:"三更",target:"更",zhuyin:"ㄍㄥ",pinyin:"gēng",wz:"ㄙㄢ ㄍㄥ",wrong:[{z:"ㄍㄥˋ",p:"gèng"},{z:"ㄍㄥˇ",p:"gěng"}],note:"「三更半夜」「更換」讀ㄍㄥ;「更加」「更好」讀ㄍㄥˋ。",deep:"1. 注音比較\n更：ㄍㄥ（一聲）＝三更半夜、更換、更正；ㄍㄥˋ（四聲）＝更加、更好；ㄍㄥˇ＝無此音（是「梗」的讀音）\n2. 國字拆解與造字原因\n更：形聲字，小篆從「攵」（手持器具）、「丙」（聲），本義是改變、替換→「更換、更正」（ㄍㄥ）；古代夜間輪班報時也是輪「換」，一夜分五更→「三更半夜」（ㄍㄥ）；事情再進一層→「更加」（ㄍㄥˋ）。"},
  {id:"p302",grade:1,word:"首都",target:"都",zhuyin:"ㄉㄨ",pinyin:"dū",wz:"ㄕㄡˇ ㄉㄨ",wrong:[{z:"ㄉㄡ",p:"dōu"},{z:"ㄉㄨˇ",p:"dǔ"}],note:"「首都」「都市」讀ㄉㄨ;「都是」「全都」讀ㄉㄡ。",deep:"1. 注音比較\n都：ㄉㄨ（一聲）＝首都、都市；ㄉㄡ（一聲）＝都是、全都；ㄉㄨˇ＝無此音（是「賭」的讀音）\n2. 國字拆解與造字原因\n都：形聲字，「者」（聲）＋「阝（邑，城市）」，本義是大城市、君王所在的城→「首都、都市」（ㄉㄨ）；大城聚集了所有的人和物，引申為「全部」→「都是、全都」（ㄉㄡ）。"},
  {id:"p303",grade:1,word:"少年",target:"少",zhuyin:"ㄕㄠˋ",pinyin:"shào",wz:"ㄕㄠˋ ㄋㄧㄢˊ",wrong:[{z:"ㄕㄠˇ",p:"shǎo"},{z:"ㄕㄠ",p:"shāo"}],note:"「少年」「少女」讀ㄕㄠˋ;「多少」「減少」讀ㄕㄠˇ。",deep:"1. 注音比較\n少：ㄕㄠˋ（四聲）＝少年、少女；ㄕㄠˇ（三聲）＝多少、減少；ㄕㄠ＝無此音（是「捎」的讀音）\n2. 國字拆解與造字原因\n少：指事字，「小」加一撇，表示比小還細微，本義是數量不多→「多少、減少」（ㄕㄠˇ）；年紀不多、年輕→「少年、少女」（ㄕㄠˋ）。記法：指數量讀三聲，指年紀讀四聲。"},
  {id:"p304",grade:1,word:"相信",target:"相",zhuyin:"ㄒㄧㄤ",pinyin:"xiāng",wz:"ㄒㄧㄤ ㄒㄧㄣˋ",wrong:[{z:"ㄒㄧㄤˋ",p:"xiàng"},{z:"ㄒㄧㄤˇ",p:"xiǎng"}],note:"「相信」「互相」讀ㄒㄧㄤ;「相片」「相貌」讀ㄒㄧㄤˋ。",deep:"1. 注音比較\n相：ㄒㄧㄤ（一聲）＝相信、互相、相親相愛；ㄒㄧㄤˋ（四聲）＝相片、相貌、首相；ㄒㄧㄤˇ＝無此音（是「想」的讀音）\n2. 國字拆解與造字原因\n相：會意字，「木」＋「目」，用眼睛觀察樹木，本義是察看。彼此對看→「互相、相信」（ㄒㄧㄤ）；看到的外貌→「相貌、相片」（ㄒㄧㄤˋ），輔助君王察事的人→「宰相、首相」（ㄒㄧㄤˋ）。"},
  {id:"p305",grade:1,word:"相簿",target:"相",zhuyin:"ㄒㄧㄤˋ",pinyin:"xiàng",wz:"ㄒㄧㄤˋ ㄅㄨˋ",wrong:[{z:"ㄒㄧㄤ",p:"xiāng"},{z:"ㄒㄧㄤˇ",p:"xiǎng"}],note:"「相簿」「照相」讀ㄒㄧㄤˋ;「相親相愛」讀ㄒㄧㄤ。",deep:"1. 注音比較\n相：ㄒㄧㄤˋ（四聲）＝相簿、照相、相貌；ㄒㄧㄤ（一聲）＝相親相愛、互相；ㄒㄧㄤˇ＝無此音（是「想」的讀音）\n2. 國字拆解與造字原因\n相：會意字，「木」＋「目」，用眼睛察看樹木。表「外貌、影像」時讀ㄒㄧㄤˋ→「相簿、照相」；表「彼此、互相」時讀ㄒㄧㄤ→「相親相愛」。記法：看得到的「樣子」讀四聲，兩人之間的「互相」讀一聲。"},
  {id:"p306",grade:2,word:"將來",target:"將",zhuyin:"ㄐㄧㄤ",pinyin:"jiāng",wz:"ㄐㄧㄤ ㄌㄞˊ",wrong:[{z:"ㄐㄧㄤˋ",p:"jiàng"},{z:"ㄑㄧㄤ",p:"qiāng"}],note:"「將來」「將要」讀ㄐㄧㄤ;「將領」「大將」讀ㄐㄧㄤˋ。",deep:"1. 注音比較\n將：ㄐㄧㄤ（一聲）＝將來、將要、將近；ㄐㄧㄤˋ（四聲）＝將領、大將；ㄑㄧㄤ＝罕用音（《詩經》「將進酒」的請求義）\n2. 國字拆解與造字原因\n將：形聲字，從「寸」（手），本義是扶持、帶領。快要發生（副詞）→「將來、將要」（ㄐㄧㄤ）；帶兵的人→「將領」（ㄐㄧㄤˋ）。"},
  {id:"p307",grade:2,word:"大將",target:"將",zhuyin:"ㄐㄧㄤˋ",pinyin:"jiàng",wz:"ㄉㄚˋ ㄐㄧㄤˋ",wrong:[{z:"ㄐㄧㄤ",p:"jiāng"},{z:"ㄑㄧㄤˊ",p:"qiáng"}],note:"「大將」「將軍」讀ㄐㄧㄤˋ;「將近」讀ㄐㄧㄤ。",deep:"1. 注音比較\n將：ㄐㄧㄤˋ（四聲）＝大將、將軍、將士；ㄐㄧㄤ（一聲）＝將近、即將；ㄑㄧㄤˊ＝無此音（是「強」的讀音）\n2. 國字拆解與造字原因\n將：從「寸」（手），本義扶持、帶領。統帥軍隊的人（名詞）讀ㄐㄧㄤˋ；表「快要」的副詞讀ㄐㄧㄤ。記法：官職四聲、副詞一聲。"},
  {id:"p308",grade:2,word:"困難",target:"難",zhuyin:"ㄋㄢˊ",pinyin:"nán",wz:"ㄎㄨㄣˋ ㄋㄢˊ",wrong:[{z:"ㄋㄢˋ",p:"nàn"},{z:"ㄋㄢˇ",p:"nǎn"}],note:"「困難」「難題」讀ㄋㄢˊ;「災難」「避難」讀ㄋㄢˋ。",deep:"1. 注音比較\n難：ㄋㄢˊ（二聲）＝困難、難題、難過；ㄋㄢˋ（四聲）＝災難、避難、難民；ㄋㄢˇ＝無此音\n2. 國字拆解與造字原因\n難：形聲字，「隹」（短尾鳥）＋「堇」（聲），本是一種鳥名，假借表「不容易」→「困難」（ㄋㄢˊ）；不容易度過的禍事→「災難」（ㄋㄢˋ）。記法：形容詞二聲、名詞（禍事）四聲。"},
  {id:"p309",grade:2,word:"災難",target:"難",zhuyin:"ㄋㄢˋ",pinyin:"nàn",wz:"ㄗㄞ ㄋㄢˋ",wrong:[{z:"ㄋㄢˊ",p:"nán"},{z:"ㄋㄚˋ",p:"nà"}],note:"「災難」「難民」讀ㄋㄢˋ;「難過」讀ㄋㄢˊ。",deep:"1. 注音比較\n難：ㄋㄢˋ（四聲）＝災難、難民、遇難；ㄋㄢˊ（二聲）＝難過、困難；ㄋㄚˋ＝無此音（是「納」的讀音）\n2. 國字拆解與造字原因\n難：「隹」＋「堇」（聲），假借表「不容易」。指禍事、劫難（名詞）讀ㄋㄢˋ；指「不容易」（形容詞）讀ㄋㄢˊ。"},
  {id:"p310",grade:2,word:"分開",target:"分",zhuyin:"ㄈㄣ",pinyin:"fēn",wz:"ㄈㄣ ㄎㄞ",wrong:[{z:"ㄈㄣˋ",p:"fèn"},{z:"ㄈㄢ",p:"fān"}],note:"「分開」「分數」讀ㄈㄣ;「本分」「分量」讀ㄈㄣˋ。",deep:"1. 注音比較\n分：ㄈㄣ（一聲）＝分開、分數、十分；ㄈㄣˋ（四聲）＝本分、分量、身分；ㄈㄢ＝無此音（是「翻」的讀音）\n2. 國字拆解與造字原因\n分：會意字，「八」（分開之形）＋「刀」，用刀把東西切開，本義是分開（ㄈㄣ）；分到自己名下的職責、地位→「本分、身分」（ㄈㄣˋ）。記法：動作一聲、名分四聲。"},
  {id:"p311",grade:2,word:"本分",target:"分",zhuyin:"ㄈㄣˋ",pinyin:"fèn",wz:"ㄅㄣˇ ㄈㄣˋ",wrong:[{z:"ㄈㄣ",p:"fēn"},{z:"ㄅㄣˇ",p:"běn"}],note:"「本分」「過分」讀ㄈㄣˋ;「分別」讀ㄈㄣ。",deep:"1. 注音比較\n分：ㄈㄣˋ（四聲）＝本分、過分、安分；ㄈㄣ（一聲）＝分別、分開；ㄅㄣˇ＝無此音（是「本」的讀音）\n2. 國字拆解與造字原因\n分：「八」＋「刀」，以刀分物。切開的動作讀ㄈㄣ；每人「分」得的職責、限度讀ㄈㄣˋ（守本分、不過分）。"},
  {id:"p312",grade:2,word:"天空",target:"空",zhuyin:"ㄎㄨㄥ",pinyin:"kōng",wz:"ㄊㄧㄢ ㄎㄨㄥ",wrong:[{z:"ㄎㄨㄥˋ",p:"kòng"},{z:"ㄎㄨㄥˇ",p:"kǒng"}],note:"「天空」「空氣」讀ㄎㄨㄥ;「空地」「空白」讀ㄎㄨㄥˋ。",deep:"1. 注音比較\n空：ㄎㄨㄥ（一聲）＝天空、空氣、空曠；ㄎㄨㄥˋ（四聲）＝空地、空白、有空；ㄎㄨㄥˇ＝無此音（是「恐」的讀音）\n2. 國字拆解與造字原因\n空：形聲字，「穴」（洞）＋「工」（聲），洞穴裡什麼都沒有，本義是空虛→「天空、空氣」（ㄎㄨㄥ）；騰出來沒被占用的→「空地、有空」（ㄎㄨㄥˋ）。"},
  {id:"p313",grade:2,word:"空地",target:"空",zhuyin:"ㄎㄨㄥˋ",pinyin:"kòng",wz:"ㄎㄨㄥˋ ㄉㄧˋ",wrong:[{z:"ㄎㄨㄥ",p:"kōng"},{z:"ㄎㄨㄥˇ",p:"kǒng"}],note:"「空地」「空檔」「填空」讀ㄎㄨㄥˋ;「空曠」讀ㄎㄨㄥ。",deep:"1. 注音比較\n空：ㄎㄨㄥˋ（四聲）＝空地、空檔、填空；ㄎㄨㄥ（一聲）＝空曠、天空；ㄎㄨㄥˇ＝無此音\n2. 國字拆解與造字原因\n空：「穴」＋「工」（聲）。指「什麼都沒有」的狀態讀ㄎㄨㄥ；指「騰出、留出的位置或時間」讀ㄎㄨㄥˋ（空位、空檔）。"},
  {id:"p314",grade:2,word:"擔心",target:"擔",zhuyin:"ㄉㄢ",pinyin:"dān",wz:"ㄉㄢ ㄒㄧㄣ",wrong:[{z:"ㄉㄢˋ",p:"dàn"},{z:"ㄊㄢˊ",p:"tán"}],note:"「擔心」「承擔」讀ㄉㄢ;「重擔」「扁擔」讀ㄉㄢˋ。",deep:"1. 注音比較\n擔：ㄉㄢ（一聲）＝擔心、承擔、擔任；ㄉㄢˋ（四聲）＝重擔、扁擔、一擔水；ㄊㄢˊ＝無此音（是「談」的讀音）\n2. 國字拆解與造字原因\n擔：形聲字，「扌」＋「詹」（聲），本義是用肩挑東西（動詞，ㄉㄢ）→引申承受（擔心、承擔）；挑的東西或工具（名詞）讀ㄉㄢˋ（重擔、扁擔）。記法：動詞一聲、名詞四聲。"},
  {id:"p315",grade:2,word:"重擔",target:"擔",zhuyin:"ㄉㄢˋ",pinyin:"dàn",wz:"ㄓㄨㄥˋ ㄉㄢˋ",wrong:[{z:"ㄉㄢ",p:"dān"},{z:"ㄓㄨㄥˋ",p:"zhòng"}],note:"「重擔」「一擔水」讀ㄉㄢˋ;「擔任」讀ㄉㄢ。",deep:"1. 注音比較\n擔：ㄉㄢˋ（四聲）＝重擔、一擔水；ㄉㄢ（一聲）＝擔任、擔憂；ㄓㄨㄥˋ＝無此音（是「重」的讀音）\n2. 國字拆解與造字原因\n擔：「扌」＋「詹」（聲），肩挑的動作讀ㄉㄢ；肩上挑的貨物、責任（名詞）讀ㄉㄢˋ，也當量詞（一擔水）。"},
  {id:"p316",grade:2,word:"彈琴",target:"彈",zhuyin:"ㄊㄢˊ",pinyin:"tán",wz:"ㄊㄢˊ ㄑㄧㄣˊ",wrong:[{z:"ㄉㄢˋ",p:"dàn"},{z:"ㄊㄢˇ",p:"tǎn"}],note:"「彈琴」「彈跳」讀ㄊㄢˊ;「子彈」「彈藥」讀ㄉㄢˋ。",deep:"1. 注音比較\n彈：ㄊㄢˊ（二聲）＝彈琴、彈跳、彈性；ㄉㄢˋ（四聲）＝子彈、彈藥、炸彈；ㄊㄢˇ＝無此音（是「坦」的讀音）\n2. 國字拆解與造字原因\n彈：形聲字，「弓」＋「單」（聲），本義是用弓發射的小丸（名詞，ㄉㄢˋ）→子彈；用手指撥動、彈射的動作讀ㄊㄢˊ（彈琴、彈跳）。記法：名詞四聲、動詞二聲。"},
  {id:"p317",grade:2,word:"子彈",target:"彈",zhuyin:"ㄉㄢˋ",pinyin:"dàn",wz:"ㄗˇ ㄉㄢˋ",wrong:[{z:"ㄊㄢˊ",p:"tán"},{z:"ㄉㄢ",p:"dān"}],note:"「子彈」「飛彈」讀ㄉㄢˋ;「彈鋼琴」讀ㄊㄢˊ。",deep:"1. 注音比較\n彈：ㄉㄢˋ（四聲）＝子彈、飛彈、彈殼；ㄊㄢˊ（二聲）＝彈鋼琴、彈簧；ㄉㄢ＝無此音（是「擔」的讀音）\n2. 國字拆解與造字原因\n彈：「弓」＋「單」（聲），弓上發射的彈丸（名詞）讀ㄉㄢˋ；撥動、跳動的動作讀ㄊㄢˊ。"},
  {id:"p318",grade:3,word:"歌曲",target:"曲",zhuyin:"ㄑㄩˇ",pinyin:"qǔ",wz:"ㄍㄜ ㄑㄩˇ",wrong:[{z:"ㄑㄩ",p:"qū"},{z:"ㄑㄩˋ",p:"qù"}],note:"「歌曲」「作曲」讀ㄑㄩˇ;「彎曲」「曲折」讀ㄑㄩ。",deep:"1. 注音比較\n曲：ㄑㄩˇ（三聲）＝歌曲、作曲、戲曲；ㄑㄩ（一聲）＝彎曲、曲折、曲線；ㄑㄩˋ＝無此音（是「去」的讀音）\n2. 國字拆解與造字原因\n曲：象形字，像彎曲的器物，本義是彎（ㄑㄩ）；樂音高低轉折如彎曲的線條→「樂曲」（ㄑㄩˇ）。記法：彎的一聲、歌的三聲。"},
  {id:"p319",grade:3,word:"彎曲",target:"曲",zhuyin:"ㄑㄩ",pinyin:"qū",wz:"ㄨㄢ ㄑㄩ",wrong:[{z:"ㄑㄩˇ",p:"qǔ"},{z:"ㄨㄢ",p:"wān"}],note:"「彎曲」「曲解」讀ㄑㄩ;「戲曲」讀ㄑㄩˇ。",deep:"1. 注音比較\n曲：ㄑㄩ（一聲）＝彎曲、曲解、曲線；ㄑㄩˇ（三聲）＝戲曲、歌曲；ㄨㄢ＝無此音（是「彎」的讀音）\n2. 國字拆解與造字原因\n曲：象形字，像彎曲之物。形容彎、不直（含「歪曲事實」的曲解）讀ㄑㄩ；音樂作品讀ㄑㄩˇ。"},
  {id:"p320",grade:3,word:"磨刀",target:"磨",zhuyin:"ㄇㄛˊ",pinyin:"mó",wz:"ㄇㄛˊ ㄉㄠ",wrong:[{z:"ㄇㄛˋ",p:"mò"},{z:"ㄇㄚˊ",p:"má"}],note:"「磨刀」「磨練」讀ㄇㄛˊ;「石磨」「磨坊」讀ㄇㄛˋ。",deep:"1. 注音比較\n磨：ㄇㄛˊ（二聲）＝磨刀、磨練、折磨；ㄇㄛˋ（四聲）＝石磨、磨坊；ㄇㄚˊ＝無此音（是「麻」的讀音）\n2. 國字拆解與造字原因\n磨：形聲字，「石」＋「麻」（聲），本義是用石頭研磨（動詞，ㄇㄛˊ）；研磨穀物的器具（名詞）讀ㄇㄛˋ（石磨）。記法：動詞二聲、器具四聲。"},
  {id:"p321",grade:3,word:"石磨",target:"磨",zhuyin:"ㄇㄛˋ",pinyin:"mò",wz:"ㄕˊ ㄇㄛˋ",wrong:[{z:"ㄇㄛˊ",p:"mó"},{z:"ㄇㄛ",p:"mō"}],note:"「石磨」「磨豆漿的磨」讀ㄇㄛˋ;「折磨」讀ㄇㄛˊ。",deep:"1. 注音比較\n磨：ㄇㄛˋ（四聲）＝石磨、磨坊、推磨；ㄇㄛˊ（二聲）＝折磨、磨墨；ㄇㄛ＝無此音\n2. 國字拆解與造字原因\n磨：「石」＋「麻」（聲）。磨東西的動作讀ㄇㄛˊ；磨穀物的石製器具讀ㄇㄛˋ。"},
  {id:"p322",grade:3,word:"關卡",target:"卡",zhuyin:"ㄎㄚˇ",pinyin:"kǎ",wz:"ㄍㄨㄢ ㄎㄚˇ",wrong:[{z:"ㄑㄧㄚˇ",p:"qiǎ"},{z:"ㄑㄧㄚˋ",p:"qià"}],note:"教育部審訂音「關卡」的「卡」讀ㄎㄚˇ；「卡子」「鐵卡」（夾東西的器具）才讀ㄑㄧㄚˇ。",deep:"1. 注音比較\n卡：ㄎㄚˇ＝關卡、卡片、賀年卡、聖誕卡、十卡熱量；ㄑㄧㄚˇ＝卡子、鐵卡（夾住東西的小器具）。★「關卡」教育部審訂音讀ㄍㄨㄢ ㄎㄚˇ，讀成ㄑㄧㄚˇ不是審訂音\n2. 國字拆解與造字原因\n卡：由「上」「下」合成，不上不下夾在中間，所以有「卡住」的意思；又借來音譯外來語 card、calorie→「卡片、卡路里」。設在路上檢查的地方叫「關卡」。"},
  {id:"p323",grade:3,word:"撒嬌",target:"撒",zhuyin:"ㄙㄚ",pinyin:"sā",wz:"ㄙㄚ ㄐㄧㄠ",wrong:[{z:"ㄙㄚˇ",p:"sǎ"},{z:"ㄕㄚ",p:"shā"}],note:"「撒嬌」「撒手」讀ㄙㄚ;「撒種」「撒鹽」讀ㄙㄚˇ。",deep:"1. 注音比較\n撒：ㄙㄚ（一聲）＝撒嬌、撒手、撒謊；ㄙㄚˇ（三聲）＝撒種、撒鹽；ㄕㄚ＝無此音（是「沙」的讀音）\n2. 國字拆解與造字原因\n撒：形聲字，「扌」＋「散」（聲）。放開、盡量施展讀ㄙㄚ（撒手、撒嬌）；把顆粒狀東西散布出去讀ㄙㄚˇ（撒種）。記法：放開一聲、散布三聲。"},
  {id:"p324",grade:3,word:"掃帚",target:"掃",zhuyin:"ㄙㄠˋ",pinyin:"sào",wz:"ㄙㄠˋ ㄓㄡˇ",wrong:[{z:"ㄙㄠˇ",p:"sǎo"},{z:"ㄕㄠˋ",p:"shào"}],note:"「掃帚」讀ㄙㄠˋ;「掃地」「打掃」讀ㄙㄠˇ。",deep:"1. 注音比較\n掃：ㄙㄠˋ（四聲）＝掃帚；ㄙㄠˇ（三聲）＝掃地、打掃、掃描；ㄕㄠˋ＝無此音（是「哨」的讀音）\n2. 國字拆解與造字原因\n掃：會意字，「扌」＋「帚」（掃帚），手持帚清除塵土。清掃的動作讀ㄙㄠˇ；只有器具「掃帚」一詞讀ㄙㄠˋ。"},
  {id:"p325",grade:3,word:"悶熱",target:"悶",zhuyin:"ㄇㄣ",pinyin:"mēn",wz:"ㄇㄣ ㄖㄜˋ",wrong:[{z:"ㄇㄣˋ",p:"mèn"},{z:"ㄇㄧㄣˇ",p:"mǐn"}],note:"「悶熱」「悶著頭」讀ㄇㄣ;「煩悶」「苦悶」讀ㄇㄣˋ。",deep:"1. 注音比較\n悶：ㄇㄣ（一聲）＝悶熱、悶著頭、悶不吭聲；ㄇㄣˋ（四聲）＝煩悶、苦悶、解悶；ㄇㄧㄣˇ＝無此音（是「憫」的讀音）\n2. 國字拆解與造字原因\n悶：會意兼形聲，「心」被關在「門」內，心情鬱塞。空氣不流通、不出聲讀ㄇㄣ（悶熱）；心中鬱悶的情緒讀ㄇㄣˋ（苦悶）。記法：外在環境一聲、內心情緒四聲。"},
  {id:"p326",grade:3,word:"調皮",target:"調",zhuyin:"ㄊㄧㄠˊ",pinyin:"tiáo",wz:"ㄊㄧㄠˊ ㄆㄧˊ",wrong:[{z:"ㄉㄧㄠˋ",p:"diào"},{z:"ㄊㄧㄠˋ",p:"tiào"}],note:"「調皮」「調整」讀ㄊㄧㄠˊ;「調查」「聲調」讀ㄉㄧㄠˋ。",deep:"1. 注音比較\n調：ㄊㄧㄠˊ（二聲）＝調皮、調整、調味；ㄉㄧㄠˋ（四聲）＝調查、聲調、調動；ㄊㄧㄠˋ＝無此音（是「跳」的讀音）\n2. 國字拆解與造字原因\n調：形聲字，「言」＋「周」（聲），本義是和諧——使之和諧的動作讀ㄊㄧㄠˊ（調整、調和）；轉換、考核讀ㄉㄧㄠˋ（調動、調查），聲音的高低也叫調（聲調）。"},
  {id:"p327",grade:3,word:"勞累",target:"累",zhuyin:"ㄌㄟˋ",pinyin:"lèi",wz:"ㄌㄠˊ ㄌㄟˋ",wrong:[{z:"ㄌㄟˇ",p:"lěi"},{z:"ㄌㄟˊ",p:"léi"}],note:"「勞累」「疲累」讀ㄌㄟˋ;「累積」讀ㄌㄟˇ;「果實累累」讀ㄌㄟˊ。",deep:"1. 注音比較\n累：ㄌㄟˋ（四聲）＝勞累、疲累；ㄌㄟˇ（三聲）＝累積、連累；ㄌㄟˊ（二聲）＝果實累累\n2. 國字拆解與造字原因\n累：從「糸」（絲繩），本義是繩索捆綁、串連→堆疊串連讀ㄌㄟˇ（累積）；被事情捆住而疲乏讀ㄌㄟˋ（勞累）；果實成串下垂讀ㄌㄟˊ（累累）。"},
  {id:"p328",grade:3,word:"累積",target:"累",zhuyin:"ㄌㄟˇ",pinyin:"lěi",wz:"ㄌㄟˇ ㄐㄧ",wrong:[{z:"ㄌㄟˋ",p:"lèi"},{z:"ㄌㄟˊ",p:"léi"}],note:"「累積」「積累」「日積月累」讀ㄌㄟˇ。",deep:"1. 注音比較\n累：ㄌㄟˇ（三聲）＝累積、積累、日積月累、連累；ㄌㄟˋ（四聲）＝累壞了；ㄌㄟˊ（二聲）＝碩果累累\n2. 國字拆解與造字原因\n累：從「糸」，繩索串連之義。一層層堆疊讀ㄌㄟˇ；疲倦讀ㄌㄟˋ。「日積月累」是堆疊義，讀ㄌㄟˇ。"},
  {id:"p329",grade:3,word:"樹蔭",target:"蔭",zhuyin:"ㄧㄣˋ",pinyin:"yìn",wz:"ㄕㄨˋ ㄧㄣˋ",wrong:[{z:"ㄧㄣ",p:"yīn"},{z:"ㄧㄣˊ",p:"yín"}],note:"審訂音「蔭」一律讀ㄧㄣˋ,如「樹蔭」「庇蔭」,常被誤讀成ㄧㄣ。",deep:"1. 注音比較\n蔭：ㄧㄣˋ（四聲）＝樹蔭、庇蔭、綠樹成蔭（審訂音統讀）；ㄧㄣ＝舊讀，審訂表不採；ㄧㄣˊ＝無此音（是「銀」的讀音）\n2. 國字拆解與造字原因\n蔭：形聲字，「艹」＋「陰」（聲），樹下背光的影子，引申為遮蔽、庇護。教育部審訂音一律讀ㄧㄣˋ，「樹蔭」「林蔭大道」都不再讀一聲。"},
  {id:"p330",grade:3,word:"彷彿",target:"彿",zhuyin:"ㄈㄨˊ",pinyin:"fú",wz:"ㄈㄤˇ ㄈㄨˊ",wrong:[{z:"ㄈㄛˊ",p:"fó"},{z:"ㄈㄨˇ",p:"fǔ"}],note:"「彷彿」讀ㄈㄤˇ ㄈㄨˊ。",deep:"1. 注音比較\n彿：ㄈㄨˊ（二聲）＝彷彿；ㄈㄛˊ＝無此音（是「佛」的讀音）；ㄈㄨˇ＝無此音（是「府」的讀音）\n2. 國字拆解與造字原因\n彿：形聲字，「彳」（行走）＋「弗」（聲），「彷彿」是連綿詞，形容似有若無、好像。注意「彷彿」（ㄈㄤˇ ㄈㄨˊ）與「佛」（ㄈㄛˊ）字形相近、讀音不同。"},
  {id:"p331",grade:4,word:"亞軍",target:"亞",zhuyin:"ㄧㄚˋ",pinyin:"yà",wz:"ㄧㄚˋ ㄐㄩㄣ",wrong:[{z:"ㄧㄚˇ",p:"yǎ"},{z:"ㄧㄚ",p:"yā"}],note:"教育部審訂音「亞」只有一個讀音ㄧㄚˋ：亞軍、亞洲、亞熱帶都讀ㄧㄚˋ。",deep:"1. 注音比較\n亞：ㄧㄚˋ＝亞軍、亞洲、亞熱帶、亞聖、歐亞大陸。★教育部《國語辭典簡編本》「亞」只收ㄧㄚˋ一音，讀成三聲ㄧㄚˇ不是現行審訂音\n2. 國字拆解與造字原因\n亞：象形字，像古代建築的方形基座。本義引申為「次一等」→第二名叫亞軍、次於熱帶叫亞熱帶、地位僅次於孔子的孟子稱亞聖。"},
  {id:"p332",grade:4,word:"檔案",target:"檔",zhuyin:"ㄉㄤˇ",pinyin:"dǎng",wz:"ㄉㄤˇ ㄢˋ",wrong:[{z:"ㄉㄤˋ",p:"dàng"},{z:"ㄉㄤ",p:"dāng"}],note:"審訂音「檔」讀ㄉㄤˇ,如「檔案」「檔次」,常被誤讀成ㄉㄤˋ。",deep:"1. 注音比較\n檔：ㄉㄤˇ（三聲）＝檔案、檔次、空檔（審訂音）；ㄉㄤˋ＝俗讀，審訂表不採；ㄉㄤ＝無此音\n2. 國字拆解與造字原因\n檔：形聲字，「木」＋「當」（聲），本義是木櫃的框格，存放文書之處→檔案。審訂音讀三聲ㄉㄤˇ。"},
  {id:"p333",grade:4,word:"柵欄",target:"柵",zhuyin:"ㄓㄚˋ",pinyin:"zhà",wz:"ㄓㄚˋ ㄌㄢˊ",wrong:[{z:"ㄕㄢ",p:"shān"},{z:"ㄘㄜˋ",p:"cè"}],note:"「柵欄」「木柵」的「柵」讀ㄓㄚˋ。",deep:"1. 注音比較\n柵：ㄓㄚˋ（四聲）＝柵欄、木柵；ㄕㄢ＝無此音（柵極為電子學譯名）；ㄘㄜˋ＝無此音（是「冊」的讀音）\n2. 國字拆解與造字原因\n柵：會意兼形聲，「木」＋「冊」（竹簡編排之形），木條像竹簡一樣排列成的圍欄→柵欄。"},
  {id:"p334",grade:4,word:"嫉妒",target:"嫉",zhuyin:"ㄐㄧˊ",pinyin:"jí",wz:"ㄐㄧˊ ㄉㄨˋ",wrong:[{z:"ㄐㄧˋ",p:"jì"},{z:"ㄑㄧˊ",p:"qí"}],note:"「嫉妒」「嫉惡如仇」的「嫉」讀ㄐㄧˊ,常被誤讀成ㄐㄧˋ。",deep:"1. 注音比較\n嫉：ㄐㄧˊ（二聲）＝嫉妒、嫉惡如仇；ㄐㄧˋ＝誤讀（受「忌」影響）；ㄑㄧˊ＝無此音\n2. 國字拆解與造字原因\n嫉：形聲字，「女」＋「疾」（聲），因別人比自己好而心裡難受。與「疾」同音讀ㄐㄧˊ，別受同義詞「忌妒」影響誤讀成ㄐㄧˋ。"},
  {id:"p335",grade:4,word:"侮辱",target:"侮",zhuyin:"ㄨˇ",pinyin:"wǔ",wz:"ㄨˇ ㄖㄨˋ",wrong:[{z:"ㄨˊ",p:"wú"},{z:"ㄇㄟˇ",p:"měi"}],note:"「侮辱」「欺侮」的「侮」讀ㄨˇ。",deep:"1. 注音比較\n侮：ㄨˇ（三聲）＝侮辱、欺侮；ㄨˊ＝無此音（是「無」的讀音）；ㄇㄟˇ＝無此音（受「每」影響的誤讀）\n2. 國字拆解與造字原因\n侮：形聲字，「亻」＋「每」（聲），輕慢、欺凌他人→侮辱。從「每」得聲但讀ㄨˇ，是形聲字聲符變化的例子。"},
  {id:"p336",grade:4,word:"誣陷",target:"誣",zhuyin:"ㄨ",pinyin:"wū",wz:"ㄨ ㄒㄧㄢˋ",wrong:[{z:"ㄨˊ",p:"wú"},{z:"ㄨˇ",p:"wǔ"}],note:"「誣陷」「誣賴」的「誣」讀ㄨ。",deep:"1. 注音比較\n誣：ㄨ（一聲）＝誣陷、誣賴、誣告；ㄨˊ＝誤讀（受「巫」影響）；ㄨˇ＝無此音（是「侮」的讀音）\n2. 國字拆解與造字原因\n誣：形聲字，「言」＋「巫」（聲），用言語捏造事實冤枉人→誣陷。讀一聲ㄨ。"},
  {id:"p337",grade:4,word:"噩耗",target:"噩",zhuyin:"ㄜˋ",pinyin:"è",wz:"ㄜˋ ㄏㄠˋ",wrong:[{z:"ㄋㄜˋ",p:"nè"},{z:"ㄏㄠˋ",p:"hào"}],note:"「噩耗」「噩夢」的「噩」讀ㄜˋ。",deep:"1. 注音比較\n噩：ㄜˋ（四聲）＝噩耗、噩夢；ㄋㄜˋ＝無此音；ㄏㄠˋ＝無此音（是「耗」的讀音）\n2. 國字拆解與造字原因\n噩：會意字，多個「口」圍著「王」形，象徵驚愕喧嘩，本義是驚人的、不祥的→噩耗（壞消息）、噩夢。與「惡」（ㄜˋ）同音。"},
  {id:"p338",grade:4,word:"酗酒",target:"酗",zhuyin:"ㄒㄩˋ",pinyin:"xù",wz:"ㄒㄩˋ ㄐㄧㄡˇ",wrong:[{z:"ㄒㄩㄥ",p:"xiōng"},{z:"ㄑㄩˋ",p:"qù"}],note:"「酗酒」的「酗」讀ㄒㄩˋ,常被誤讀成ㄒㄩㄥ。",deep:"1. 注音比較\n酗：ㄒㄩˋ（四聲）＝酗酒；ㄒㄩㄥ＝誤讀（受「凶」影響）；ㄑㄩˋ＝無此音\n2. 國字拆解與造字原因\n酗：形聲字，「酉」（酒罈）＋「凶」（聲），喝酒過量而撒野→酗酒。從「凶」得聲卻讀ㄒㄩˋ，是常考的誤讀字。"},
  {id:"p339",grade:4,word:"徘徊",target:"徊",zhuyin:"ㄏㄨㄞˊ",pinyin:"huái",wz:"ㄆㄞˊ ㄏㄨㄞˊ",wrong:[{z:"ㄏㄨㄟˊ",p:"huí"},{z:"ㄏㄨㄞˋ",p:"huài"}],note:"「徘徊」讀ㄆㄞˊ ㄏㄨㄞˊ,「徊」常被誤讀成ㄏㄨㄟˊ。",deep:"1. 注音比較\n徊：ㄏㄨㄞˊ（二聲）＝徘徊；ㄏㄨㄟˊ＝誤讀（受「回」影響）；ㄏㄨㄞˋ＝無此音（是「壞」的讀音）\n2. 國字拆解與造字原因\n徊：形聲字，「彳」（行走）＋「回」（聲），「徘徊」是連綿詞：來回走動、猶豫不前。「徊」讀ㄏㄨㄞˊ不讀ㄏㄨㄟˊ。"},
  {id:"p340",grade:4,word:"蜿蜒",target:"蜿",zhuyin:"ㄨㄢ",pinyin:"wān",wz:"ㄨㄢ ㄧㄢˊ",wrong:[{z:"ㄨㄢˇ",p:"wǎn"},{z:"ㄩㄢ",p:"yuān"}],note:"「蜿蜒」讀ㄨㄢ ㄧㄢˊ,山路曲折延伸的樣子。",deep:"1. 注音比較\n蜿：ㄨㄢ（一聲）＝蜿蜒；ㄨㄢˇ＝誤讀（受「宛」影響）；ㄩㄢ＝無此音（是「冤」的讀音）\n2. 國字拆解與造字原因\n蜿：形聲字，「虫」＋「宛」（聲），「蜿蜒」形容像蛇一樣彎彎曲曲地延伸（山路蜿蜒）。讀一聲ㄨㄢ。"},
  {id:"p341",grade:4,word:"骯髒",target:"骯",zhuyin:"ㄤ",pinyin:"āng",wz:"ㄤ ㄗㄤ",wrong:[{z:"ㄎㄤ",p:"kāng"},{z:"ㄤˊ",p:"áng"}],note:"「骯髒」讀ㄤ ㄗㄤ。",deep:"1. 注音比較\n骯：ㄤ（一聲）＝骯髒；ㄎㄤ＝無此音（是「康」的讀音）；ㄤˊ＝無此音（是「昂」的讀音）\n2. 國字拆解與造字原因\n骯：形聲字，「骨」＋「亢」（聲），「骯髒」（ㄤ ㄗㄤ）是連綿詞，形容汙穢不潔。"},
  {id:"p342",grade:4,word:"花蕾",target:"蕾",zhuyin:"ㄌㄟˇ",pinyin:"lěi",wz:"ㄏㄨㄚ ㄌㄟˇ",wrong:[{z:"ㄌㄟˊ",p:"léi"},{z:"ㄌㄟˋ",p:"lèi"}],note:"「花蕾」「蓓蕾」的「蕾」讀ㄌㄟˇ。",deep:"1. 注音比較\n蕾：ㄌㄟˇ（三聲）＝花蕾、蓓蕾、芭蕾；ㄌㄟˊ＝無此音（是「雷」的讀音）；ㄌㄟˋ＝無此音（是「累」的讀音）\n2. 國字拆解與造字原因\n蕾：形聲字，「艹」＋「雷」（聲），含苞未開的花。從「雷」得聲但讀三聲ㄌㄟˇ。"},
  {id:"p343",grade:5,word:"給予",target:"給",zhuyin:"ㄐㄧˇ",pinyin:"jǐ",wz:"ㄐㄧˇ ㄩˇ",wrong:[{z:"ㄍㄟˇ",p:"gěi"},{z:"ㄐㄧˋ",p:"jì"}],note:"「給予」「補給」「供給」讀ㄐㄧˇ;「給你」讀ㄍㄟˇ。",deep:"1. 注音比較\n給：ㄐㄧˇ（三聲）＝給予、補給、供給、自給自足；ㄍㄟˇ（三聲）＝給你、送給（口語）；ㄐㄧˋ＝無此音（是「寄」的讀音）\n2. 國字拆解與造字原因\n給：形聲字，「糸」＋「合」（聲），本義是豐足、供應→書面語「給予、供給」讀ㄐㄧˇ；口語交付東西讀ㄍㄟˇ。記法：書面ㄐㄧˇ、口語ㄍㄟˇ。"},
  {id:"p344",grade:5,word:"提供",target:"供",zhuyin:"ㄍㄨㄥ",pinyin:"gōng",wz:"ㄊㄧˊ ㄍㄨㄥ",wrong:[{z:"ㄍㄨㄥˋ",p:"gòng"},{z:"ㄍㄨㄥˇ",p:"gǒng"}],note:"「提供」「供應」讀ㄍㄨㄥ;「供品」「口供」讀ㄍㄨㄥˋ。",deep:"1. 注音比較\n供：ㄍㄨㄥ（一聲）＝提供、供應、供不應求；ㄍㄨㄥˋ（四聲）＝供品、口供、供奉；ㄍㄨㄥˇ＝無此音（是「拱」的讀音）\n2. 國字拆解與造字原因\n供：形聲字，「亻」＋「共」（聲），本義是安排、供給（ㄍㄨㄥ）；擺設祭品敬奉、陳述案情讀ㄍㄨㄥˋ（供奉、招供）。"},
  {id:"p345",grade:5,word:"供品",target:"供",zhuyin:"ㄍㄨㄥˋ",pinyin:"gòng",wz:"ㄍㄨㄥˋ ㄆㄧㄣˇ",wrong:[{z:"ㄍㄨㄥ",p:"gōng"},{z:"ㄍㄨㄥˇ",p:"gǒng"}],note:"「供品」「供奉」「招供」讀ㄍㄨㄥˋ;「供給」讀ㄍㄨㄥ。",deep:"1. 注音比較\n供：ㄍㄨㄥˋ（四聲）＝供品、供奉、招供、口供；ㄍㄨㄥ（一聲）＝供給、供應；ㄍㄨㄥˇ＝無此音\n2. 國字拆解與造字原因\n供：「亻」＋「共」（聲）。日常供應讀ㄍㄨㄥ；與祭祀、審訊有關讀ㄍㄨㄥˋ。記法：拜拜與問案四聲。"},
  {id:"p346",grade:5,word:"削鉛筆",target:"削",zhuyin:"ㄒㄧㄠ",pinyin:"xiāo",wz:"ㄒㄧㄠ ㄑㄧㄢ ㄅㄧˇ",wrong:[{z:"ㄒㄩㄝˋ",p:"xuè"},{z:"ㄒㄧㄠˋ",p:"xiào"}],note:"口語「削鉛筆」「削皮」讀ㄒㄧㄠ;書面「剝削」「削減」讀ㄒㄩㄝˋ。",deep:"1. 注音比較\n削：ㄒㄧㄠ（一聲）＝削鉛筆、削皮（口語）；ㄒㄩㄝˋ（四聲）＝剝削、削減、瘦削（書面）；ㄒㄧㄠˋ＝無此音\n2. 國字拆解與造字原因\n削：形聲字，「刂」（刀）＋「肖」（聲），用刀斜著去掉外層。口語具體動作讀ㄒㄧㄠ（削蘋果）；書面抽象義讀ㄒㄩㄝˋ（剝削、削弱）。"},
  {id:"p347",grade:5,word:"剝削",target:"削",zhuyin:"ㄒㄩㄝˋ",pinyin:"xuè",wz:"ㄅㄛ ㄒㄩㄝˋ",wrong:[{z:"ㄒㄧㄠ",p:"xiāo"},{z:"ㄒㄩㄝ",p:"xuē"}],note:"「剝削」「削弱」讀ㄒㄩㄝˋ;「削蘋果」讀ㄒㄧㄠ。",deep:"1. 注音比較\n削：ㄒㄩㄝˋ（四聲）＝剝削、削弱、削價；ㄒㄧㄠ（一聲）＝削果皮；ㄒㄩㄝ＝無此音\n2. 國字拆解與造字原因\n削：「刂」＋「肖」（聲）。抽象的減損、壓榨讀ㄒㄩㄝˋ；動手削東西讀ㄒㄧㄠ。記法：書面文言四聲、口語動作一聲。"},
  {id:"p348",grade:5,word:"月暈",target:"暈",zhuyin:"ㄩㄣˋ",pinyin:"yùn",wz:"ㄩㄝˋ ㄩㄣˋ",wrong:[{z:"ㄩㄣ",p:"yūn"},{z:"ㄏㄨㄣ",p:"hūn"}],note:"「月暈」「暈染」「燈暈」讀ㄩㄣˋ;「頭暈」「暈倒」讀ㄩㄣ。",deep:"1. 注音比較\n暈：ㄩㄣˋ（四聲）＝月暈、暈染、燈暈；ㄩㄣ（一聲）＝頭暈、暈倒、暈車；ㄏㄨㄣ＝無此音（是「昏」的讀音）\n2. 國字拆解與造字原因\n暈：形聲字，「日」＋「軍」（聲），本義是日月周圍的光圈（ㄩㄣˋ，月暈）；頭腦昏眩像被光圈罩住讀ㄩㄣ（頭暈）。記法：光圈名詞四聲、昏眩一聲。"},
  {id:"p349",grade:5,word:"豬圈",target:"圈",zhuyin:"ㄐㄩㄢˋ",pinyin:"juàn",wz:"ㄓㄨ ㄐㄩㄢˋ",wrong:[{z:"ㄑㄩㄢ",p:"quān"},{z:"ㄐㄩㄢ",p:"juān"}],note:"「豬圈」「羊圈」讀ㄐㄩㄢˋ;「圓圈」「圈套」讀ㄑㄩㄢ。",deep:"1. 注音比較\n圈：ㄐㄩㄢˋ（四聲）＝豬圈、羊圈；ㄑㄩㄢ（一聲）＝圓圈、圈套、生活圈；ㄐㄩㄢ＝無此音\n2. 國字拆解與造字原因\n圈：形聲字，「囗」（圍）＋「卷」（聲），圍起來的範圍。畫的環形讀ㄑㄩㄢ；關牲畜的欄舍讀ㄐㄩㄢˋ（豬圈）。"},
  {id:"p350",grade:5,word:"校對",target:"校",zhuyin:"ㄐㄧㄠˋ",pinyin:"jiào",wz:"ㄐㄧㄠˋ ㄉㄨㄟˋ",wrong:[{z:"ㄒㄧㄠˋ",p:"xiào"},{z:"ㄐㄧㄠˇ",p:"jiǎo"}],note:"「校對」「校正」讀ㄐㄧㄠˋ;「學校」「校園」讀ㄒㄧㄠˋ。",deep:"1. 注音比較\n校：ㄐㄧㄠˋ（四聲）＝校對、校正、校稿；ㄒㄧㄠˋ（四聲）＝學校、校園、校長；ㄐㄧㄠˇ＝無此音（是「腳」的讀音）\n2. 國字拆解與造字原因\n校：形聲字，「木」＋「交」（聲），本義是木囚具，引申為核對、比較→校對（ㄐㄧㄠˋ）；教學的場所讀ㄒㄧㄠˋ（學校）。"},
  {id:"p351",grade:5,word:"人質",target:"質",zhuyin:"ㄓˋ",pinyin:"zhì",wz:"ㄖㄣˊ ㄓˋ",wrong:[{z:"ㄓˊ",p:"zhí"},{z:"ㄓˇ",p:"zhǐ"}],note:"「人質」「質押」讀ㄓˋ;「品質」「本質」讀ㄓˊ。",deep:"1. 注音比較\n質：ㄓˋ（四聲）＝人質、質押、質疑；ㄓˊ（二聲）＝品質、本質、性質；ㄓˇ＝無此音（是「紙」的讀音）\n2. 國字拆解與造字原因\n質：形聲字，「貝」（財物）＋「斦」（聲），本義是抵押品→人質、質押讀ㄓˋ；事物的本體、底子讀ㄓˊ（本質、品質）。"},
  {id:"p352",grade:5,word:"論語",target:"論",zhuyin:"ㄌㄨㄣˊ",pinyin:"lún",wz:"ㄌㄨㄣˊ ㄩˇ",wrong:[{z:"ㄌㄨㄣˋ",p:"lùn"},{z:"ㄌㄨㄣˇ",p:"lǔn"}],note:"《論語》的「論」讀ㄌㄨㄣˊ;「討論」「言論」讀ㄌㄨㄣˋ。",deep:"1. 注音比較\n論：ㄌㄨㄣˊ（二聲）＝《論語》；ㄌㄨㄣˋ（四聲）＝討論、言論、理論；ㄌㄨㄣˇ＝無此音\n2. 國字拆解與造字原因\n論：形聲字，「言」＋「侖」（聲，條理），有條理地說→討論（ㄌㄨㄣˋ）。《論語》是「編纂論次孔子之語」，書名讀ㄌㄨㄣˊ，是特殊讀法。"},
  {id:"p353",grade:5,word:"屏息",target:"屏",zhuyin:"ㄅㄧㄥˇ",pinyin:"bǐng",wz:"ㄅㄧㄥˇ ㄒㄧˊ",wrong:[{z:"ㄆㄧㄥˊ",p:"píng"},{z:"ㄅㄧㄥˋ",p:"bìng"}],note:"「屏息」「屏氣」「屏除」讀ㄅㄧㄥˇ;「屏風」「屏東」讀ㄆㄧㄥˊ。",deep:"1. 注音比較\n屏：ㄅㄧㄥˇ（三聲）＝屏息、屏氣、屏除；ㄆㄧㄥˊ（二聲）＝屏風、屏障、屏東；ㄅㄧㄥˋ＝無此音\n2. 國字拆解與造字原因\n屏：從「尸」（遮蔽）＋「并」（聲），本義是遮擋的牆（屏風，ㄆㄧㄥˊ）；把氣「擋住」不呼出→屏息（ㄅㄧㄥˇ）。記法：遮蔽物二聲、憋住排除三聲。"},
  {id:"p354",grade:5,word:"木訥",target:"訥",zhuyin:"ㄋㄜˋ",pinyin:"nè",wz:"ㄇㄨˋ ㄋㄜˋ",wrong:[{z:"ㄋㄚˋ",p:"nà"},{z:"ㄋㄟˋ",p:"nèi"}],note:"教育部審訂音「木訥」的「訥」讀ㄋㄜˋ，指言語遲鈍。",deep:"1. 注音比較\n訥：ㄋㄜˋ＝木訥。★教育部《國語辭典簡編本》「訥」只收ㄋㄜˋ一音，讀成ㄋㄚˋ不是審訂音\n2. 國字拆解與造字原因\n訥：形聲字，「言」＋「內」（聲）。話悶在「內」說不出來→言語遲鈍、不善言辭。《論語》：「君子欲訥於言而敏於行。」從言部，因為講的是說話。"},
  {id:"p355",grade:5,word:"拘泥",target:"泥",zhuyin:"ㄋㄧˋ",pinyin:"nì",wz:"ㄐㄩ ㄋㄧˋ",wrong:[{z:"ㄋㄧˊ",p:"ní"},{z:"ㄋㄧˇ",p:"nǐ"}],note:"「拘泥」(固執)讀ㄋㄧˋ;「泥土」「泥巴」讀ㄋㄧˊ。",deep:"1. 注音比較\n泥：ㄋㄧˋ（四聲）＝拘泥、泥古不化；ㄋㄧˊ（二聲）＝泥土、泥巴；ㄋㄧˇ＝無此音（是「你」的讀音）\n2. 國字拆解與造字原因\n泥：形聲字，「氵」＋「尼」（聲），本義是水和土的泥漿（ㄋㄧˊ）；像陷在泥中不知變通讀ㄋㄧˋ（拘泥）。記法：名詞二聲、固執義四聲。"},
  {id:"p356",grade:5,word:"嗚咽",target:"咽",zhuyin:"ㄧㄝˋ",pinyin:"yè",wz:"ㄨ ㄧㄝˋ",wrong:[{z:"ㄧㄢ",p:"yān"},{z:"ㄧㄢˋ",p:"yàn"}],note:"「嗚咽」「哽咽」讀ㄧㄝˋ;「咽喉」讀ㄧㄢ。",deep:"1. 注音比較\n咽：ㄧㄝˋ（四聲）＝嗚咽、哽咽；ㄧㄢ（一聲）＝咽喉；ㄧㄢˋ＝同「嚥」（吞嚥）\n2. 國字拆解與造字原因\n咽：形聲字，「口」＋「因」（聲），本義是喉嚨（ㄧㄢ，咽喉）；哭聲堵在喉嚨→嗚咽（ㄧㄝˋ）；吞下讀ㄧㄢˋ。一字三音依部位、哭聲、吞嚥區分。"},
  {id:"p357",grade:5,word:"丟三落四",target:"落",zhuyin:"ㄌㄚˋ",pinyin:"là",wz:"ㄉㄧㄡ ㄙㄢ ㄌㄚˋ ㄙˋ",wrong:[{z:"ㄌㄨㄛˋ",p:"luò"},{z:"ㄌㄠˋ",p:"lào"}],note:"「丟三落四」「落了東西」讀ㄌㄚˋ;「落葉」讀ㄌㄨㄛˋ;「落枕」讀ㄌㄠˋ。",deep:"1. 注音比較\n落：ㄌㄚˋ（四聲）＝丟三落四、落了東西（遺漏）；ㄌㄨㄛˋ（四聲）＝落葉、降落；ㄌㄠˋ（四聲）＝落枕\n2. 國字拆解與造字原因\n落：形聲字，「艹」＋「洛」（聲），本義是草木凋落（ㄌㄨㄛˋ）；口語「遺漏、忘記帶」讀ㄌㄚˋ（落東西）；「落枕、落價」等口語讀ㄌㄠˋ。"},
  {id:"p358",grade:5,word:"落枕",target:"落",zhuyin:"ㄌㄠˋ",pinyin:"lào",wz:"ㄌㄠˋ ㄓㄣˇ",wrong:[{z:"ㄌㄨㄛˋ",p:"luò"},{z:"ㄌㄚˋ",p:"là"}],note:"「落枕」讀ㄌㄠˋ;「降落」讀ㄌㄨㄛˋ。",deep:"1. 注音比較\n落：ㄌㄠˋ（四聲）＝落枕；ㄌㄨㄛˋ（四聲）＝降落、落後；ㄌㄚˋ（四聲）＝落下東西（遺漏）\n2. 國字拆解與造字原因\n落：草木凋零為本義。「落枕」（睡姿不當致頸痛）是口語詞，讀ㄌㄠˋ；一般書面義讀ㄌㄨㄛˋ。"},
  {id:"p359",grade:6,word:"拮据",target:"据",zhuyin:"ㄐㄩ",pinyin:"jū",wz:"ㄐㄧㄝˊ ㄐㄩ",wrong:[{z:"ㄐㄩˋ",p:"jù"},{z:"ㄎㄨˋ",p:"kù"}],note:"「拮据」讀ㄐㄧㄝˊ ㄐㄩ,經濟困窘,「据」常被誤讀成ㄐㄩˋ。",deep:"1. 注音比較\n据：ㄐㄩ（一聲）＝拮据；ㄐㄩˋ＝誤讀（受「據」影響）；ㄎㄨˋ＝無此音\n2. 國字拆解與造字原因\n据：形聲字，「扌」＋「居」（聲），「拮据」（ㄐㄧㄝˊ ㄐㄩ）本指鳥銜草築巢辛勞（《詩經》「予手拮据」），引申為經濟困窘。「据」在此讀一聲，不同於「據」。"},
  {id:"p360",grade:6,word:"會計",target:"會",zhuyin:"ㄎㄨㄞˋ",pinyin:"kuài",wz:"ㄎㄨㄞˋ ㄐㄧˋ",wrong:[{z:"ㄏㄨㄟˋ",p:"huì"},{z:"ㄍㄨㄟˋ",p:"guì"}],note:"「會計」的「會」讀ㄎㄨㄞˋ;「開會」「會議」讀ㄏㄨㄟˋ。",deep:"1. 注音比較\n會：ㄎㄨㄞˋ（四聲）＝會計；ㄏㄨㄟˋ（四聲）＝開會、會議、機會；ㄍㄨㄟˋ＝無此音\n2. 國字拆解與造字原因\n會：會意字，像器皿加蓋相合，本義是聚合（開會，ㄏㄨㄟˋ）；總計財物的專業讀ㄎㄨㄞˋ（會計），是古音遺留。"},
  {id:"p361",grade:6,word:"龜裂",target:"龜",zhuyin:"ㄐㄩㄣ",pinyin:"jūn",wz:"ㄐㄩㄣ ㄌㄧㄝˋ",wrong:[{z:"ㄍㄨㄟ",p:"guī"},{z:"ㄑㄧㄡ",p:"qiū"}],note:"「龜裂」讀ㄐㄩㄣ ㄌㄧㄝˋ;「烏龜」讀ㄍㄨㄟ;「龜茲」讀ㄑㄧㄡ。",deep:"1. 注音比較\n龜：ㄐㄩㄣ（一聲）＝龜裂；ㄍㄨㄟ（一聲）＝烏龜、龜甲；ㄑㄧㄡ（一聲）＝龜茲（古西域國名）\n2. 國字拆解與造字原因\n龜：象形字，像烏龜側面之形（ㄍㄨㄟ）。皮膚、土地裂開如龜甲紋路讀ㄐㄩㄣ（龜裂）；古國名「龜茲」讀ㄑㄧㄡ ㄘˊ。一字三音都要記。"},
  {id:"p362",grade:6,word:"木屐",target:"屐",zhuyin:"ㄐㄧ",pinyin:"jī",wz:"ㄇㄨˋ ㄐㄧ",wrong:[{z:"ㄐㄧˊ",p:"jí"},{z:"ㄑㄧ",p:"qī"}],note:"「木屐」的「屐」讀ㄐㄧ。",deep:"1. 注音比較\n屐：ㄐㄧ（一聲）＝木屐、屐痕；ㄐㄧˊ＝誤讀；ㄑㄧ＝無此音\n2. 國字拆解與造字原因\n屐：形聲字，「尸」（人）＋「彳」「支」，木底鞋→木屐。讀一聲ㄐㄧ。"},
  {id:"p363",grade:6,word:"熾熱",target:"熾",zhuyin:"ㄔˋ",pinyin:"chì",wz:"ㄔˋ ㄖㄜˋ",wrong:[{z:"ㄓˋ",p:"zhì"},{z:"ㄕˋ",p:"shì"}],note:"「熾熱」「熾烈」的「熾」讀ㄔˋ,常被誤讀成ㄓˋ。",deep:"1. 注音比較\n熾：ㄔˋ（四聲）＝熾熱、熾烈；ㄓˋ＝誤讀（受「織」「幟」影響）；ㄕˋ＝無此音\n2. 國字拆解與造字原因\n熾：形聲字，「火」＋「戠」（聲），火勢旺盛→熾熱、熾烈。讀ㄔˋ，與「斥」同音，別受「幟」（ㄓˋ）影響。"},
  {id:"p364",grade:6,word:"蟄伏",target:"蟄",zhuyin:"ㄓˊ",pinyin:"zhí",wz:"ㄓˊ ㄈㄨˊ",wrong:[{z:"ㄓㄜˊ",p:"zhé"},{z:"ㄓㄜˋ",p:"zhè"}],note:"審訂音「蟄伏」「驚蟄」的「蟄」讀ㄓˊ。",deep:"1. 注音比較\n蟄：ㄓˊ（二聲）＝蟄伏、驚蟄（審訂音）；ㄓㄜˊ＝俗讀，審訂表不採；ㄓㄜˋ＝無此音\n2. 國字拆解與造字原因\n蟄：形聲字，「執」（聲）＋「虫」，蟲類藏伏土中過冬→蟄伏；節氣「驚蟄」是春雷驚醒冬眠之蟲。審訂音讀ㄓˊ。"},
  {id:"p365",grade:6,word:"匍匐",target:"匐",zhuyin:"ㄈㄨˊ",pinyin:"fú",wz:"ㄆㄨˊ ㄈㄨˊ",wrong:[{z:"ㄈㄨˋ",p:"fù"},{z:"ㄅㄨˊ",p:"bú"}],note:"「匍匐前進」讀ㄆㄨˊ ㄈㄨˊ。",deep:"1. 注音比較\n匐：ㄈㄨˊ（二聲）＝匍匐；ㄈㄨˋ＝誤讀；ㄅㄨˊ＝無此音\n2. 國字拆解與造字原因\n匐：形聲字，「勹」（人彎曲形）＋「畐」（聲），「匍匐」（ㄆㄨˊ ㄈㄨˊ）是連綿詞：身體貼地爬行。"},
  {id:"p366",grade:6,word:"婀娜",target:"婀",zhuyin:"ㄜ",pinyin:"ē",wz:"ㄜ ㄋㄨㄛˊ",wrong:[{z:"ㄚ",p:"ā"},{z:"ㄜˇ",p:"ě"}],note:"「婀娜多姿」讀ㄜ ㄋㄨㄛˇ。",deep:"1. 注音比較\n婀：ㄜ（一聲）＝婀娜多姿；ㄚ＝誤讀；ㄜˇ＝無此音\n2. 國字拆解與造字原因\n婀：形聲字，「女」＋「阿」（聲），「婀娜」（ㄜ ㄋㄨㄛˇ）是連綿詞：女子姿態柔美。"},
  {id:"p367",grade:6,word:"蚌殼",target:"蚌",zhuyin:"ㄅㄤˋ",pinyin:"bàng",wz:"ㄅㄤˋ ㄎㄜˊ",wrong:[{z:"ㄈㄥ",p:"fēng"},{z:"ㄅㄥˋ",p:"bèng"}],note:"「蚌殼」「鷸蚌相爭」的「蚌」讀ㄅㄤˋ。",deep:"1. 注音比較\n蚌：ㄅㄤˋ（四聲）＝蚌殼、鷸蚌相爭；ㄈㄥ＝無此音（是「蜂」的讀音）；ㄅㄥˋ＝無此音（是「蹦」的讀音）\n2. 國字拆解與造字原因\n蚌：形聲字，「虫」＋「丰」（聲），雙殼軟體動物，殼內能生珍珠。讀ㄅㄤˋ，與「棒」同音。"},
  {id:"p368",grade:6,word:"水汞",target:"汞",zhuyin:"ㄍㄨㄥˇ",pinyin:"gǒng",wz:"ㄕㄨㄟˇ ㄍㄨㄥˇ",wrong:[{z:"ㄍㄨㄥ",p:"gōng"},{z:"ㄏㄨㄥˇ",p:"hǒng"}],note:"「汞」讀ㄍㄨㄥˇ,即水銀。",deep:"1. 注音比較\n汞：ㄍㄨㄥˇ（三聲）＝汞（水銀）、汞中毒；ㄍㄨㄥ＝誤讀；ㄏㄨㄥˇ＝無此音（是「哄」的讀音）\n2. 國字拆解與造字原因\n汞：會意兼形聲，「工」（聲）＋「水」，常溫下呈液態的金屬——「像水的金屬」，即水銀。讀三聲ㄍㄨㄥˇ。"},
  {id:"p369",grade:6,word:"陀螺",target:"陀",zhuyin:"ㄊㄨㄛˊ",pinyin:"tuó",wz:"ㄊㄨㄛˊ ㄌㄨㄛˊ",wrong:[{z:"ㄉㄨㄛˋ",p:"duò"},{z:"ㄊㄚ",p:"tā"}],note:"「陀螺」讀ㄊㄨㄛˊ ㄌㄨㄛˊ。",deep:"1. 注音比較\n陀：ㄊㄨㄛˊ（二聲）＝陀螺、佛陀；ㄉㄨㄛˋ＝無此音（是「舵」的讀音）；ㄊㄚ＝無此音（是「它」的讀音）\n2. 國字拆解與造字原因\n陀：形聲字，「阝（阜）」＋「它」（聲），本義是山坡不平，「陀螺」（ㄊㄨㄛˊ ㄌㄨㄛˊ）是旋轉的玩具。"},
  {id:"p370",grade:6,word:"呢絨",target:"呢",zhuyin:"ㄋㄧˊ",pinyin:"ní",wz:"ㄋㄧˊ ㄖㄨㄥˊ",wrong:[{z:"ㄋㄜ",p:"ne"},{z:"ㄋㄧˇ",p:"nǐ"}],note:"「呢絨」「呢帽」讀ㄋㄧˊ;語尾助詞「呢」讀輕聲ㄋㄜ。",deep:"1. 注音比較\n呢：ㄋㄧˊ（二聲）＝呢絨、呢帽、毛呢；˙ㄋㄜ（輕聲）＝好呢、怎麼辦呢（語尾助詞）；ㄋㄧˇ＝無此音（是「你」的讀音）\n2. 國字拆解與造字原因\n呢：形聲字，「口」＋「尼」（聲）。指毛織品讀ㄋㄧˊ（呢絨）；當句尾語氣詞讀輕聲ㄋㄜ。記法：布料二聲、語氣詞輕聲。"},
  {id:"p371",grade:7,word:"字帖",target:"帖",zhuyin:"ㄊㄧㄝˇ",pinyin:"tiě",wz:"ㄗˋ ㄊㄧㄝˇ",wrong:[{z:"ㄊㄧㄝˋ",p:"tiè"},{z:"ㄊㄧㄝ",p:"tiē"}],note:"教育部審訂音「字帖」的「帖」讀ㄊㄧㄝˇ（三聲），和請帖、碑帖同音。",deep:"1. 注音比較\n帖：ㄊㄧㄝˇ＝字帖、請帖、謝帖、換帖、庚帖、碑帖、臨帖、一帖藥；ㄊㄧㄝ＝妥帖、服帖、俯首帖耳。★「字帖」教育部審訂音讀ㄊㄧㄝˇ，讀成四聲ㄊㄧㄝˋ不是審訂音\n2. 國字拆解與造字原因\n帖：形聲字，「巾」＋「占」（聲），本義是寫在布帛上的字。寫成範本供人臨摹的叫「字帖、碑帖」，寫來邀請人的卡片叫「請帖」，都讀ㄊㄧㄝˇ；當「安穩順從」解時讀ㄊㄧㄝ（妥帖）。"},
  {id:"p372",grade:7,word:"請帖",target:"帖",zhuyin:"ㄊㄧㄝˇ",pinyin:"tiě",wz:"ㄑㄧㄥˇ ㄊㄧㄝˇ",wrong:[{z:"ㄊㄧㄝˋ",p:"tiè"},{z:"ㄊㄧㄝ",p:"tiē"}],note:"「請帖」「喜帖」讀ㄊㄧㄝˇ;「字帖」讀ㄊㄧㄝˋ。",deep:"1. 注音比較\n帖：ㄊㄧㄝˇ（三聲）＝請帖、喜帖、名帖；ㄊㄧㄝˋ（四聲）＝字帖、法帖；ㄊㄧㄝ（一聲）＝服帖\n2. 國字拆解與造字原因\n帖：「巾」＋「占」（聲）。邀請、通知的卡片讀ㄊㄧㄝˇ；供臨摹的書法範本讀ㄊㄧㄝˋ；平順服貼讀ㄊㄧㄝ。"},
  {id:"p373",grade:7,word:"妥帖",target:"帖",zhuyin:"ㄊㄧㄝ",pinyin:"tiē",wz:"ㄊㄨㄛˇ ㄊㄧㄝ",wrong:[{z:"ㄊㄧㄝˇ",p:"tiě"},{z:"ㄊㄧㄝˋ",p:"tiè"}],note:"「妥帖」「服帖」讀ㄊㄧㄝ。",deep:"1. 注音比較\n帖：ㄊㄧㄝ（一聲）＝妥帖、服帖、俯首帖耳；ㄊㄧㄝˇ（三聲）＝柬帖；ㄊㄧㄝˋ（四聲）＝碑帖\n2. 國字拆解與造字原因\n帖：「巾」＋「占」（聲）。表「安穩、順從」讀ㄊㄧㄝ（妥帖）；卡片讀ㄊㄧㄝˇ；字帖讀ㄊㄧㄝˋ。"},
  {id:"p374",grade:7,word:"攢動",target:"攢",zhuyin:"ㄘㄨㄢˊ",pinyin:"cuán",wz:"ㄘㄨㄢˊ ㄉㄨㄥˋ",wrong:[{z:"ㄗㄢˇ",p:"zǎn"},{z:"ㄗㄢˋ",p:"zàn"}],note:"「萬頭攢動」(聚集)讀ㄘㄨㄢˊ;「積攢」(儲蓄)讀ㄗㄢˇ。",deep:"1. 注音比較\n攢：ㄘㄨㄢˊ（二聲）＝萬頭攢動、攢聚（聚集）；ㄗㄢˇ（三聲）＝積攢（儲蓄）；ㄗㄢˋ＝無此音（是「贊」的讀音）\n2. 國字拆解與造字原因\n攢：形聲字，「扌」＋「贊」（聲）。聚集在一起讀ㄘㄨㄢˊ（萬頭攢動）；一點一點存錢讀ㄗㄢˇ（積攢）。"},
  {id:"p375",grade:7,word:"佝僂",target:"佝",zhuyin:"ㄎㄡˋ",pinyin:"kòu",wz:"ㄎㄡˋ ㄌㄡˊ",wrong:[{z:"ㄍㄡ",p:"gōu"},{z:"ㄐㄩˋ",p:"jù"}],note:"審訂音「佝僂」讀ㄎㄡˋ ㄌㄡˊ,駝背彎腰。",deep:"1. 注音比較\n佝：ㄎㄡˋ（四聲）＝佝僂（審訂音ㄎㄡˋ ㄌㄡˊ）；ㄍㄡ＝俗讀，審訂表不採；ㄐㄩˋ＝無此音\n2. 國字拆解與造字原因\n佝：形聲字，「亻」＋「句」（聲，彎曲），「佝僂」是背脊彎曲——駝背。審訂音讀ㄎㄡˋ。"},
  {id:"p376",grade:7,word:"綏靖",target:"綏",zhuyin:"ㄙㄨㄟ",pinyin:"suī",wz:"ㄙㄨㄟ ㄐㄧㄥˋ",wrong:[{z:"ㄙㄨㄟˊ",p:"suí"},{z:"ㄊㄨㄛˇ",p:"tuǒ"}],note:"「綏靖」讀ㄙㄨㄟ ㄐㄧㄥˋ,安撫平定。",deep:"1. 注音比較\n綏：ㄙㄨㄟ（一聲）＝綏靖；ㄙㄨㄟˊ＝誤讀（受「隨」影響）；ㄊㄨㄛˇ＝無此音（是「妥」的讀音）\n2. 國字拆解與造字原因\n綏：從「糸」從「妥」，本義是登車時拉的繩子——拉繩使穩，引申為安撫→「綏靖」（安撫平定）。讀一聲ㄙㄨㄟ。"},
  {id:"p377",grade:7,word:"檜木",target:"檜",zhuyin:"ㄎㄨㄞˋ",pinyin:"kuài",wz:"ㄎㄨㄞˋ ㄇㄨˋ",wrong:[{z:"ㄍㄨㄟˋ",p:"guì"},{z:"ㄏㄨㄟˋ",p:"huì"}],note:"教育部審訂音「檜」只有一個讀音ㄎㄨㄞˋ：檜木、秦檜都讀ㄎㄨㄞˋ。",deep:"1. 注音比較\n檜：ㄎㄨㄞˋ＝檜木、紅檜、秦檜（南宋人名）。★教育部《國語辭典簡編本》「檜」只收ㄎㄨㄞˋ一音，讀成ㄍㄨㄟˋ不是審訂音\n2. 國字拆解與造字原因\n檜：形聲字，「木」＋「會」（聲），是一種常綠大喬木，木材有香氣、耐腐，臺灣的紅檜、扁柏都屬之。從木部，因為是樹名。"},
  {id:"p378",grade:7,word:"傍晚",target:"傍",zhuyin:"ㄅㄤ",pinyin:"bāng",wz:"ㄅㄤ ㄨㄢˇ",wrong:[{z:"ㄅㄤˋ",p:"bàng"},{z:"ㄆㄤˊ",p:"páng"}],note:"審訂音「傍晚」的「傍」讀ㄅㄤ;「依傍」讀ㄅㄤˋ。",deep:"1. 注音比較\n傍：ㄅㄤ（一聲）＝傍晚（審訂音）；ㄅㄤˋ（四聲）＝依傍、傍人門戶；ㄆㄤˊ＝無此音（是「旁」的讀音）\n2. 國字拆解與造字原因\n傍：形聲字，「亻」＋「旁」（聲），本義是靠近→依傍（ㄅㄤˋ）；「傍晚」（靠近晚上）審訂音讀ㄅㄤ。"},
  {id:"p379",grade:7,word:"跛腳",target:"跛",zhuyin:"ㄅㄛˇ",pinyin:"bǒ",wz:"ㄅㄛˇ ㄐㄧㄠˇ",wrong:[{z:"ㄆㄛˇ",p:"pǒ"},{z:"ㄅㄞˇ",p:"bǎi"}],note:"「跛腳」「跛行」的「跛」讀ㄅㄛˇ。",deep:"1. 注音比較\n跛：ㄅㄛˇ（三聲）＝跛腳、跛行；ㄆㄛˇ＝誤讀；ㄅㄞˇ＝無此音（是「擺」的讀音）\n2. 國字拆解與造字原因\n跛：形聲字，「足」＋「皮」（聲），腳有毛病走路不穩→跛腳。讀ㄅㄛˇ。"},
  {id:"p380",grade:7,word:"胴體",target:"胴",zhuyin:"ㄉㄨㄥˋ",pinyin:"dòng",wz:"ㄉㄨㄥˋ ㄊㄧˇ",wrong:[{z:"ㄊㄨㄥˊ",p:"tóng"},{z:"ㄉㄨㄥ",p:"dōng"}],note:"「胴體」的「胴」讀ㄉㄨㄥˋ,軀體。",deep:"1. 注音比較\n胴：ㄉㄨㄥˋ（四聲）＝胴體；ㄊㄨㄥˊ＝誤讀（受「同」影響）；ㄉㄨㄥ＝無此音（是「東」的讀音）\n2. 國字拆解與造字原因\n胴：形聲字，「月（肉）」＋「同」（聲），軀幹→胴體。讀四聲ㄉㄨㄥˋ。"},
  {id:"p381",grade:8,word:"可汗",target:"汗",zhuyin:"ㄏㄢˊ",pinyin:"hán",wz:"ㄎㄜˋ ㄏㄢˊ",wrong:[{z:"ㄏㄢˋ",p:"hàn"},{z:"ㄍㄢ",p:"gān"}],note:"「可汗」讀ㄎㄜˋ ㄏㄢˊ,古代北方君長稱號;「流汗」讀ㄏㄢˋ。",deep:"1. 注音比較\n汗：ㄏㄢˊ（二聲）＝可汗（ㄎㄜˋ ㄏㄢˊ）；ㄏㄢˋ（四聲）＝流汗、汗水；ㄍㄢ＝無此音\n2. 國字拆解與造字原因\n汗：「氵」＋「干」（聲），身體排出的水分（ㄏㄢˋ）。「可汗」是古代北方遊牧民族君長稱號的音譯，「汗」讀ㄏㄢˊ。"},
  {id:"p382",grade:8,word:"單于",target:"單",zhuyin:"ㄔㄢˊ",pinyin:"chán",wz:"ㄔㄢˊ ㄩˊ",wrong:[{z:"ㄉㄢ",p:"dān"},{z:"ㄕㄢˋ",p:"shàn"}],note:"「單于」讀ㄔㄢˊ ㄩˊ,匈奴君長;姓氏「單」讀ㄕㄢˋ。",deep:"1. 注音比較\n單：ㄔㄢˊ（二聲）＝單于（ㄔㄢˊ ㄩˊ）；ㄉㄢ（一聲）＝單獨、簡單；ㄕㄢˋ（四聲）＝姓氏（單先生）\n2. 國字拆解與造字原因\n單：象形字，像狩獵的叉形武器。「單于」是匈奴君長稱號的音譯讀ㄔㄢˊ；姓氏讀ㄕㄢˋ；常義讀ㄉㄢ。一字三音常考。"},
  {id:"p383",grade:8,word:"燕京",target:"燕",zhuyin:"ㄧㄢ",pinyin:"yān",wz:"ㄧㄢ ㄐㄧㄥ",wrong:[{z:"ㄧㄢˋ",p:"yàn"},{z:"ㄧㄢˇ",p:"yǎn"}],note:"地名「燕京」「燕山」讀ㄧㄢ;「燕子」讀ㄧㄢˋ。",deep:"1. 注音比較\n燕：ㄧㄢ（一聲）＝燕京、燕山、燕國（地名國名）；ㄧㄢˋ（四聲）＝燕子、燕窩；ㄧㄢˇ＝無此音\n2. 國字拆解與造字原因\n燕：象形字，像燕子展翅之形（ㄧㄢˋ）。古國名、地名（河北一帶）讀ㄧㄢ（燕京＝北京舊稱）。記法：鳥四聲、地名一聲。"},
  {id:"p384",grade:8,word:"鐵騎",target:"騎",zhuyin:"ㄑㄧˊ",pinyin:"qí",wz:"ㄊㄧㄝˇ ㄑㄧˊ",wrong:[{z:"ㄐㄧˋ",p:"jì"},{z:"ㄐㄧˇ",p:"jǐ"}],note:"教育部審訂音「騎」只有一個讀音ㄑㄧˊ：騎馬、坐騎、鐵騎都讀ㄑㄧˊ。",deep:"1. 注音比較\n騎：ㄑㄧˊ＝騎馬、騎車、坐騎、鐵騎、騎縫。★教育部《國語辭典簡編本》「騎」只收ㄑㄧˊ一音，名詞讀ㄐㄧˋ是舊讀，已非現行審訂音\n2. 國字拆解與造字原因\n騎：形聲字，「馬」＋「奇」（聲），本義是跨坐在馬上。後來也用來指騎馬的士兵、馬隊→「鐵騎、輕騎」，現在動詞名詞都讀ㄑㄧˊ。"},
  {id:"p385",grade:8,word:"羽扇綸巾",target:"綸",zhuyin:"ㄍㄨㄢ",pinyin:"guān",wz:"ㄩˇ ㄕㄢˋ ㄍㄨㄢ ㄐㄧㄣ",wrong:[{z:"ㄌㄨㄣˊ",p:"lún"},{z:"ㄍㄨㄢˋ",p:"guàn"}],note:"「綸巾」讀ㄍㄨㄢ ㄐㄧㄣ;「經綸」讀ㄌㄨㄣˊ。",deep:"1. 注音比較\n綸：ㄍㄨㄢ（一聲）＝綸巾（ㄍㄨㄢ ㄐㄧㄣ）；ㄌㄨㄣˊ（二聲）＝經綸、滿腹經綸；ㄍㄨㄢˋ＝無此音\n2. 國字拆解與造字原因\n綸：形聲字，「糸」＋「侖」（聲），本義是青絲帶——青絲頭巾「綸巾」讀ㄍㄨㄢ（羽扇綸巾指諸葛亮）；整理絲線引申為治理才能（經綸）讀ㄌㄨㄣˊ。"},
  {id:"p386",grade:8,word:"道行",target:"行",zhuyin:"ㄒㄧㄥˋ",pinyin:"xìng",wz:"ㄉㄠˋ ㄒㄧㄥˋ",wrong:[{z:"ㄏㄥˊ",p:"héng"},{z:"ㄒㄧㄥˊ",p:"xíng"}],note:"教育部審訂音「道行」的「行」讀ㄒㄧㄥˋ，和品行、德行同音。",deep:"1. 注音比較\n行：ㄒㄧㄥˊ＝行走、旅行、發行、寸步難行；ㄏㄤˊ＝行列、銀行、各行各業；ㄒㄧㄥˋ＝道行、品行、操行、德行。★「道行」（修行的功夫）教育部審訂音讀ㄉㄠˋ ㄒㄧㄥˋ，讀成ㄏㄥˊ不是審訂音\n2. 國字拆解與造字原因\n行：象形字，像十字路口。走路→「行走」（ㄒㄧㄥˊ）；排成一列的東西→「行列、銀行」（ㄏㄤˊ）；一個人做出來的品格表現→「品行、德行、道行」（ㄒㄧㄥˋ）。"},
  {id:"p387",grade:8,word:"傳記",target:"傳",zhuyin:"ㄓㄨㄢˋ",pinyin:"zhuàn",wz:"ㄓㄨㄢˋ ㄐㄧˋ",wrong:[{z:"ㄔㄨㄢˊ",p:"chuán"},{z:"ㄓㄨㄢ",p:"zhuān"}],note:"「傳記」「自傳」「水滸傳」讀ㄓㄨㄢˋ;「傳說」讀ㄔㄨㄢˊ。",deep:"1. 注音比較\n傳：ㄓㄨㄢˋ（四聲）＝傳記、自傳、《水滸傳》；ㄔㄨㄢˊ（二聲）＝傳說、傳遞、流傳；ㄓㄨㄢ＝無此音（是「專」的讀音）\n2. 國字拆解與造字原因\n傳：「亻」＋「專」（聲），驛站遞送（ㄔㄨㄢˊ）；記載生平的著作讀ㄓㄨㄢˋ（列傳、傳記）。記法：動詞ㄔㄨㄢˊ、書與記事ㄓㄨㄢˋ。"},
  {id:"p388",grade:8,word:"標識",target:"識",zhuyin:"ㄓˋ",pinyin:"zhì",wz:"ㄅㄧㄠ ㄓˋ",wrong:[{z:"ㄕˋ",p:"shì"},{z:"ㄓ",p:"zhī"}],note:"「標識」(通「誌」,記號)讀ㄓˋ;「認識」「知識」讀ㄕˋ。",deep:"1. 注音比較\n識：ㄓˋ（四聲）＝標識（通「誌」，記號）、博聞強識；ㄕˋ（四聲）＝認識、知識、見識；ㄓ＝無此音\n2. 國字拆解與造字原因\n識：形聲字，「言」＋「戠」（聲），本義是知道分辨（ㄕˋ）；作「記住、記號」解時通「誌」讀ㄓˋ（標識、強識）。"},
  {id:"p389",grade:8,word:"畜生",target:"畜",zhuyin:"ㄔㄨˋ",pinyin:"chù",wz:"ㄔㄨˋ ㄕㄥ",wrong:[{z:"ㄒㄩˋ",p:"xù"},{z:"ㄒㄩ",p:"xū"}],note:"名詞「畜生」「牲畜」讀ㄔㄨˋ;動詞「畜牧」讀ㄒㄩˋ。",deep:"1. 注音比較\n畜：ㄔㄨˋ（四聲）＝畜生、牲畜、家畜（名詞）；ㄒㄩˋ（四聲）＝畜牧、畜養（動詞）；ㄒㄩ＝無此音\n2. 國字拆解與造字原因\n畜：會意字，田中積存草料，本義是積養。飼養的動作讀ㄒㄩˋ（畜牧）；養的動物（名詞）讀ㄔㄨˋ（牲畜）。記法：動詞ㄒㄩˋ、名詞ㄔㄨˋ。"},
  {id:"p390",grade:8,word:"稱心如意",target:"稱",zhuyin:"ㄔㄥˋ",pinyin:"chèng",wz:"ㄔㄥˋ ㄒㄧㄣ ㄖㄨˊ ㄧˋ",wrong:[{z:"ㄔㄣˋ",p:"chèn"},{z:"ㄔㄥ",p:"chēng"}],note:"教育部審訂音「稱心如意」的「稱」讀ㄔㄥˋ（合乎心意）。",deep:"1. 注音比較\n稱：ㄔㄥˋ＝稱心如意、稱職、稱意、稱願；ㄔㄥ＝稱呼、名稱、稱讚。★「稱心如意」教育部審訂音讀ㄔㄥˋ，讀成ㄔㄣˋ不是審訂音\n2. 國字拆解與造字原因\n稱：從禾、爯（舉起）聲，舉起穀物秤輕重。輕重「恰好相合」→合乎心意的「稱心」、能力配得上職務的「稱職」（ㄔㄥˋ）；叫出名號、讚美→「稱呼、稱讚」（ㄔㄥ）。"},
  {id:"p391",grade:9,word:"簞食壺漿",target:"食",zhuyin:"ㄙˋ",pinyin:"sì",wz:"ㄉㄢ ㄙˋ ㄏㄨˊ ㄐㄧㄤ",wrong:[{z:"ㄕˊ",p:"shí"},{z:"ㄧˋ",p:"yì"}],note:"文言「簞食壺漿」「食馬者」的「食」讀ㄙˋ,給人吃;「食物」讀ㄕˊ。",deep:"1. 注音比較\n食：ㄙˋ（四聲）＝簞食壺漿、食馬者（文言：給人吃、餵養）；ㄕˊ（二聲）＝食物、飲食；ㄧˋ＝人名用音（酈食其）\n2. 國字拆解與造字原因\n食：象形字，像盛食物的器皿。一般「吃、食物」讀ㄕˊ；文言「拿食物給人／餵養」讀ㄙˋ（簞食壺漿以迎王師）。"},
  {id:"p392",grade:9,word:"智者樂水",target:"樂",zhuyin:"ㄧㄠˋ",pinyin:"yào",wz:"ㄓˋ ㄓㄜˇ ㄧㄠˋ ㄕㄨㄟˇ",wrong:[{z:"ㄌㄜˋ",p:"lè"},{z:"ㄩㄝˋ",p:"yuè"}],note:"「智者樂水,仁者樂山」的「樂」讀ㄧㄠˋ,喜好之意。",deep:"1. 注音比較\n樂：ㄧㄠˋ（四聲）＝智者樂水、仁者樂山（喜好）；ㄌㄜˋ（四聲）＝快樂；ㄩㄝˋ（四聲）＝音樂\n2. 國字拆解與造字原因\n樂：樂器象形。《論語》「智者樂水，仁者樂山」的「樂」是「喜好」，文言讀ㄧㄠˋ。三音口訣：音樂ㄩㄝˋ、快樂ㄌㄜˋ、喜好ㄧㄠˋ。"},
  {id:"p393",grade:9,word:"屬文",target:"屬",zhuyin:"ㄓㄨˇ",pinyin:"zhǔ",wz:"ㄓㄨˇ ㄨㄣˊ",wrong:[{z:"ㄕㄨˇ",p:"shǔ"},{z:"ㄕㄨˋ",p:"shù"}],note:"文言「屬文」「屬予作文以記之」的「屬」通「囑」,讀ㄓㄨˇ;「屬於」讀ㄕㄨˇ。",deep:"1. 注音比較\n屬：ㄓㄨˇ（三聲）＝屬文、屬予作文以記之（通「囑」）；ㄕㄨˇ（三聲）＝屬於、金屬、家屬；ㄕㄨˋ＝無此音\n2. 國字拆解與造字原因\n屬：從「尾」，本義是連接。文言「連綴文字（寫作）、囑託」讀ㄓㄨˇ（〈岳陽樓記〉「屬予作文以記之」）；歸屬義讀ㄕㄨˇ。"},
  {id:"p394",grade:9,word:"期年",target:"期",zhuyin:"ㄐㄧ",pinyin:"jī",wz:"ㄐㄧ ㄋㄧㄢˊ",wrong:[{z:"ㄑㄧˊ",p:"qí"},{z:"ㄑㄧ",p:"qī"}],note:"文言「期年」(滿一年)「期月」的「期」讀ㄐㄧ;「期待」讀ㄑㄧˊ。",deep:"1. 注音比較\n期：ㄐㄧ（一聲）＝期年（滿一年）、期月；ㄑㄧˊ（二聲）＝期待、日期、學期；ㄑㄧ＝無此音\n2. 國字拆解與造字原因\n期：形聲字，「月」＋「其」（聲），本義是約定的時日（ㄑㄧˊ）。文言「滿一年／一月」讀ㄐㄧ（期年之後，雖欲言，無可進者）。"},
  {id:"p395",grade:9,word:"遺贈",target:"遺",zhuyin:"ㄨㄟˋ",pinyin:"wèi",wz:"ㄨㄟˋ ㄗㄥˋ",wrong:[{z:"ㄧˊ",p:"yí"},{z:"ㄨㄟˊ",p:"wéi"}],note:"文言「遺之千金」(贈送)讀ㄨㄟˋ;「遺失」「遺產」讀ㄧˊ。",deep:"1. 注音比較\n遺：ㄨㄟˋ（四聲）＝遺之千金、遺書（文言：贈送）；ㄧˊ（二聲）＝遺失、遺產、遺憾；ㄨㄟˊ＝無此音\n2. 國字拆解與造字原因\n遺：形聲字，「辶」＋「貴」（聲），本義是丟失（ㄧˊ）；文言「送給」讀ㄨㄟˋ（父母歲有裘葛之遺）。記法：丟失ㄧˊ、贈送ㄨㄟˋ。"},
  {id:"p396",grade:9,word:"退避三舍",target:"舍",zhuyin:"ㄕㄜˋ",pinyin:"shè",wz:"ㄊㄨㄟˋ ㄅㄧˋ ㄙㄢ ㄕㄜˋ",wrong:[{z:"ㄕㄜˇ",p:"shě"},{z:"ㄕㄚˋ",p:"shà"}],note:"「退避三舍」的「舍」讀ㄕㄜˋ,古代行軍三十里為一舍。",deep:"1. 注音比較\n舍：ㄕㄜˋ（四聲）＝退避三舍、宿舍、寒舍；ㄕㄜˇ（三聲）＝同「捨」（舍棄）；ㄕㄚˋ＝無此音（是「廈」的讀音）\n2. 國字拆解與造字原因\n舍：象形字，像簡易房屋。古代行軍三十里紮營一次為「一舍」——「退避三舍」即退讓九十里，讀ㄕㄜˋ；放棄義同「捨」讀ㄕㄜˇ。"},
  {id:"p397",grade:9,word:"王天下",target:"王",zhuyin:"ㄨㄤˋ",pinyin:"wàng",wz:"ㄨㄤˋ ㄊㄧㄢ ㄒㄧㄚˋ",wrong:[{z:"ㄨㄤˊ",p:"wáng"},{z:"ㄨㄤˇ",p:"wǎng"}],note:"文言動詞「王天下」(稱王)讀ㄨㄤˋ;名詞「國王」讀ㄨㄤˊ。",deep:"1. 注音比較\n王：ㄨㄤˋ（四聲）＝王天下（文言動詞：稱王統治）；ㄨㄤˊ（二聲）＝國王、王子；ㄨㄤˇ＝無此音（是「往」的讀音）\n2. 國字拆解與造字原因\n王：象形字，像大斧（王權象徵）。名詞讀ㄨㄤˊ；文言動詞「稱王」讀ㄨㄤˋ（然而不王者，未之有也）。"},
  {id:"p398",grade:9,word:"雨雪",target:"雨",zhuyin:"ㄩˋ",pinyin:"yù",wz:"ㄩˋ ㄒㄩㄝˇ",wrong:[{z:"ㄩˇ",p:"yǔ"},{z:"ㄩ",p:"yū"}],note:"文言動詞「雨雪霏霏」(降下)讀ㄩˋ;名詞「下雨」讀ㄩˇ。",deep:"1. 注音比較\n雨：ㄩˋ（四聲）＝雨雪霏霏（文言動詞：降下）；ㄩˇ（三聲）＝下雨、雨天；ㄩ＝無此音\n2. 國字拆解與造字原因\n雨：象形字，天上落下水滴之形。名詞讀ㄩˇ；文言當動詞「降下」讀ㄩˋ（天雨雪、雨我公田）。"},
  {id:"p399",grade:9,word:"衣錦還鄉",target:"衣",zhuyin:"ㄧˋ",pinyin:"yì",wz:"ㄧˋ ㄐㄧㄣˇ ㄏㄨㄢˊ ㄒㄧㄤ",wrong:[{z:"ㄧ",p:"yī"},{z:"ㄧˇ",p:"yǐ"}],note:"文言動詞「衣錦還鄉」(穿)讀ㄧˋ;名詞「衣服」讀ㄧ。",deep:"1. 注音比較\n衣：ㄧˋ（四聲）＝衣錦還鄉（文言動詞：穿）；ㄧ（一聲）＝衣服、衣裳；ㄧˇ＝無此音\n2. 國字拆解與造字原因\n衣：象形字，像上衣的領袖衣襟。名詞讀ㄧ；文言當動詞「穿」讀ㄧˋ（衣錦還鄉、解衣衣我）。"},
  {id:"p400",grade:9,word:"語人",target:"語",zhuyin:"ㄩˋ",pinyin:"yù",wz:"ㄩˋ ㄖㄣˊ",wrong:[{z:"ㄩˇ",p:"yǔ"},{z:"ㄩˊ",p:"yú"}],note:"文言動詞「不以語人」(告訴)讀ㄩˋ;名詞「語言」讀ㄩˇ。",deep:"1. 注音比較\n語：ㄩˋ（四聲）＝不以語人（文言動詞：告訴）；ㄩˇ（三聲）＝語言、成語、國語；ㄩˊ＝無此音\n2. 國字拆解與造字原因\n語：形聲字，「言」＋「吾」（聲），本義是談話（ㄩˇ）；文言「告訴某人」讀ㄩˋ（此中人語云：不足為外人道也）。記法：名詞ㄩˇ、告訴ㄩˋ。"},
  {id:"p401",grade:10,word:"咀嚼",target:"嚼",zhuyin:"ㄐㄩㄝˊ",pinyin:"jué",wz:"ㄐㄩˇ ㄐㄩㄝˊ",wrong:[{z:"ㄐㄧㄠˊ",p:"jiáo"},{z:"ㄐㄩㄝˋ",p:"juè"}],note:"書面「咀嚼」讀ㄐㄩˇ ㄐㄩㄝˊ;口語「嚼口香糖」讀ㄐㄧㄠˊ。",deep:"1. 注音比較\n嚼：ㄐㄩㄝˊ（二聲）＝咀嚼（書面）；ㄐㄧㄠˊ（二聲）＝嚼口香糖、細嚼慢嚥（口語）；ㄐㄩㄝˋ＝無此音\n2. 國字拆解與造字原因\n嚼：形聲字，「口」＋「爵」（聲），用牙磨碎食物。書面語「咀嚼」（ㄐㄩˇ ㄐㄩㄝˊ，也指反覆體會）讀ㄐㄩㄝˊ；口語讀ㄐㄧㄠˊ。"},
  {id:"p402",grade:10,word:"間諜活動",target:"間",zhuyin:"ㄐㄧㄢˋ",pinyin:"jiàn",wz:"ㄐㄧㄢˋ ㄉㄧㄝˊ ㄏㄨㄛˊ ㄉㄨㄥˋ",wrong:[{z:"ㄐㄧㄢ",p:"jiān"},{z:"ㄐㄧㄢˇ",p:"jiǎn"}],note:"「間諜」「離間」「間隔」讀ㄐㄧㄢˋ;「中間」讀ㄐㄧㄢ。",deep:"1. 注音比較\n間：ㄐㄧㄢˋ（四聲）＝間諜、離間、間隔、間接；ㄐㄧㄢ（一聲）＝中間、房間、時間；ㄐㄧㄢˇ＝無此音（是「簡」的讀音）\n2. 國字拆解與造字原因\n間：門縫透月光，本義是縫隙。「置身縫隙中打探、拉開距離」的引申義讀ㄐㄧㄢˋ（間諜、離間、間隔）；表方位、單位讀ㄐㄧㄢ。"},
  {id:"p403",grade:10,word:"慰藉",target:"藉",zhuyin:"ㄐㄧㄝˋ",pinyin:"jiè",wz:"ㄨㄟˋ ㄐㄧㄝˋ",wrong:[{z:"ㄐㄧˊ",p:"jí"},{z:"ㄗㄜˋ",p:"zè"}],note:"「慰藉」「藉口」讀ㄐㄧㄝˋ;「狼藉」讀ㄐㄧˊ。",deep:"1. 注音比較\n藉：ㄐㄧㄝˋ（四聲）＝慰藉、藉口、憑藉；ㄐㄧˊ（二聲）＝狼藉；ㄗㄜˋ＝無此音\n2. 國字拆解與造字原因\n藉：「艹」＋「耤」（聲），本義是草墊→依靠（憑藉）、安慰（慰藉）讀ㄐㄧㄝˋ；「狼藉」（雜亂）讀ㄐㄧˊ。"},
  {id:"p404",grade:10,word:"乘客",target:"乘",zhuyin:"ㄔㄥˊ",pinyin:"chéng",wz:"ㄔㄥˊ ㄎㄜˋ",wrong:[{z:"ㄕㄥˋ",p:"shèng"},{z:"ㄔㄥˋ",p:"chèng"}],note:"「乘客」「乘車」讀ㄔㄥˊ;「萬乘之國」「史乘」讀ㄕㄥˋ。",deep:"1. 注音比較\n乘：ㄔㄥˊ（二聲）＝乘客、乘車、乘機；ㄕㄥˋ（四聲）＝萬乘之國、史乘（車輛單位、史書）；ㄔㄥˋ＝無此音\n2. 國字拆解與造字原因\n乘：象形字，人爬在樹上，本義是登上→搭乘（ㄔㄥˊ）；古代四馬一車為一乘，兵車單位與史書讀ㄕㄥˋ（千乘之國）。"},
  {id:"p405",grade:10,word:"泡茶",target:"泡",zhuyin:"ㄆㄠˋ",pinyin:"pào",wz:"ㄆㄠˋ ㄔㄚˊ",wrong:[{z:"ㄆㄠ",p:"pāo"},{z:"ㄅㄠˋ",p:"bào"}],note:"「泡茶」「泡沫」讀ㄆㄠˋ;「眼泡」「豆腐泡兒」讀ㄆㄠ。",deep:"1. 注音比較\n泡：ㄆㄠˋ（四聲）＝泡茶、泡沫、氣泡；ㄆㄠ（一聲）＝眼泡、豆腐泡兒（鬆軟之物）；ㄅㄠˋ＝無此音\n2. 國字拆解與造字原因\n泡：形聲字，「氵」＋「包」（聲），水包著空氣的球→泡沫；浸在水裡→泡茶（ㄆㄠˋ）；鬆軟鼓起之物讀ㄆㄠ（眼泡）。"},
  {id:"p406",grade:10,word:"擂鼓",target:"擂",zhuyin:"ㄌㄟˊ",pinyin:"léi",wz:"ㄌㄟˊ ㄍㄨˇ",wrong:[{z:"ㄌㄟˋ",p:"lèi"},{z:"ㄌㄟˇ",p:"lěi"}],note:"「擂鼓」「自吹自擂」讀ㄌㄟˊ;審訂音「擂臺」亦讀ㄌㄟˊ。",deep:"1. 注音比較\n擂：ㄌㄟˊ（二聲）＝擂鼓、自吹自擂、擂臺；ㄌㄟˋ＝俗讀（擂臺），審訂表不採；ㄌㄟˇ＝無此音\n2. 國字拆解與造字原因\n擂：「扌」＋「雷」（聲），用力敲打（如雷聲）→擂鼓、自吹自擂。審訂音統讀ㄌㄟˊ。"},
  {id:"p407",grade:10,word:"揶揄",target:"揄",zhuyin:"ㄩˊ",pinyin:"yú",wz:"ㄧㄝˊ ㄩˊ",wrong:[{z:"ㄩˋ",p:"yù"},{z:"ㄕㄨ",p:"shū"}],note:"「揶揄」讀ㄧㄝˊ ㄩˊ,嘲笑戲弄。",deep:"1. 注音比較\n揄：ㄩˊ（二聲）＝揶揄；ㄩˋ＝誤讀；ㄕㄨ＝無此音\n2. 國字拆解與造字原因\n揄：形聲字，「扌」＋「俞」（聲），「揶揄」（ㄧㄝˊ ㄩˊ）＝出手戲弄、言語嘲笑。"},
  {id:"p408",grade:10,word:"炮烙",target:"烙",zhuyin:"ㄌㄨㄛˋ",pinyin:"luò",wz:"ㄆㄠˊ ㄌㄨㄛˋ",wrong:[{z:"ㄌㄠˋ",p:"lào"},{z:"ㄍㄜˊ",p:"gé"}],note:"古刑「炮烙」讀ㄆㄠˊ ㄌㄨㄛˋ;「烙印」「烙餅」讀ㄌㄠˋ。",deep:"1. 注音比較\n烙：ㄌㄨㄛˋ（四聲）＝炮烙（ㄆㄠˊ ㄌㄨㄛˋ，古酷刑）；ㄌㄠˋ（四聲）＝烙印、烙餅；ㄍㄜˊ＝無此音\n2. 國字拆解與造字原因\n烙：形聲字，「火」＋「各」（聲），用燒熱的金屬燙→烙印（ㄌㄠˋ）；商紂的酷刑「炮烙」讀ㄌㄨㄛˋ。記法：日常ㄌㄠˋ、古刑ㄌㄨㄛˋ。"},
  {id:"p409",grade:10,word:"馥郁",target:"馥",zhuyin:"ㄈㄨˋ",pinyin:"fù",wz:"ㄈㄨˋ ㄩˋ",wrong:[{z:"ㄈㄨˊ",p:"fú"},{z:"ㄅㄨˋ",p:"bù"}],note:"「馥郁」的「馥」讀ㄈㄨˋ,香氣濃厚。",deep:"1. 注音比較\n馥：ㄈㄨˋ（四聲）＝馥郁；ㄈㄨˊ＝誤讀；ㄅㄨˋ＝無此音\n2. 國字拆解與造字原因\n馥：形聲字，「香」＋「复」（聲），香氣濃厚→馥郁（花香馥郁）。讀ㄈㄨˋ。"},
  {id:"p410",grade:10,word:"陰霾",target:"霾",zhuyin:"ㄇㄞˊ",pinyin:"mái",wz:"ㄧㄣ ㄇㄞˊ",wrong:[{z:"ㄌㄧˊ",p:"lí"},{z:"ㄇㄢˊ",p:"mán"}],note:"「陰霾」「霾害」的「霾」讀ㄇㄞˊ。",deep:"1. 注音比較\n霾：ㄇㄞˊ（二聲）＝陰霾、霾害、霧霾；ㄌㄧˊ＝無此音（是「狸」的讀音）；ㄇㄢˊ＝無此音\n2. 國字拆解與造字原因\n霾：形聲字，「雨」＋「貍」（聲），風夾塵土使天色昏暗→陰霾（也比喻心頭陰影）。讀ㄇㄞˊ，與「埋」同音。"},
  {id:"p411",grade:10,word:"忖度",target:"忖",zhuyin:"ㄘㄨㄣˇ",pinyin:"cǔn",wz:"ㄘㄨㄣˇ ㄉㄨㄛˋ",wrong:[{z:"ㄘㄨㄣˊ",p:"cún"},{z:"ㄈㄨˋ",p:"fù"}],note:"「忖度」「思忖」的「忖」讀ㄘㄨㄣˇ,揣測。",deep:"1. 注音比較\n忖：ㄘㄨㄣˇ（三聲）＝忖度、思忖、自忖；ㄘㄨㄣˊ＝誤讀（受「存」影響）；ㄈㄨˋ＝無此音\n2. 國字拆解與造字原因\n忖：形聲字，「忄」＋「寸」（聲），心中丈量→揣測（忖度）。讀ㄘㄨㄣˇ。"},
  {id:"p412",grade:10,word:"殷實",target:"殷",zhuyin:"ㄧㄣ",pinyin:"yīn",wz:"ㄧㄣ ㄕˊ",wrong:[{z:"ㄧㄢ",p:"yān"},{z:"ㄧㄣˇ",p:"yǐn"}],note:"「殷實」「殷勤」讀ㄧㄣ;「殷紅」讀ㄧㄢ。",deep:"1. 注音比較\n殷：ㄧㄣ（一聲）＝殷實、殷勤、殷商；ㄧㄢ（一聲）＝殷紅（深紅帶黑）；ㄧㄣˇ＝殷殷（雷聲）\n2. 國字拆解與造字原因\n殷：本義是盛大→富足（殷實）、懇切（殷勤）讀ㄧㄣ；深紅色讀ㄧㄢ（殷紅的血）。記法：紅色讀ㄧㄢ，其他多讀ㄧㄣ。"},
  {id:"p413",grade:10,word:"憩息",target:"憩",zhuyin:"ㄑㄧˋ",pinyin:"qì",wz:"ㄑㄧˋ ㄒㄧˊ",wrong:[{z:"ㄒㄧ",p:"xī"},{z:"ㄎㄜˋ",p:"kè"}],note:"「休憩」「小憩」的「憩」讀ㄑㄧˋ。",deep:"1. 注音比較\n憩：ㄑㄧˋ（四聲）＝休憩、小憩、憩息；ㄒㄧ＝無此音（是「息」的讀音）；ㄎㄜˋ＝無此音\n2. 國字拆解與造字原因\n憩：從「舌」「息」，休息→小憩片刻。讀ㄑㄧˋ，與「氣」同音。"},
  {id:"p414",grade:10,word:"僧侶",target:"僧",zhuyin:"ㄙㄥ",pinyin:"sēng",wz:"ㄙㄥ ㄌㄩˇ",wrong:[{z:"ㄗㄥ",p:"zēng"},{z:"ㄘㄥˊ",p:"céng"}],note:"「僧侶」「高僧」的「僧」讀ㄙㄥ。",deep:"1. 注音比較\n僧：ㄙㄥ（一聲）＝僧侶、高僧、僧多粥少；ㄗㄥ＝誤讀（受「曾」影響）；ㄘㄥˊ＝無此音\n2. 國字拆解與造字原因\n僧：形聲字，「亻」＋「曾」（聲），梵語「僧伽」的省稱——出家修行的人→僧侶。讀ㄙㄥ。"},
  {id:"p415",grade:10,word:"蒼穹",target:"穹",zhuyin:"ㄑㄩㄥ",pinyin:"qiōng",wz:"ㄘㄤ ㄑㄩㄥ",wrong:[{z:"ㄑㄩㄥˊ",p:"qióng"},{z:"ㄍㄨㄥ",p:"gōng"}],note:"教育部審訂音「蒼穹」的「穹」讀ㄑㄩㄥ（一聲），不是ㄑㄩㄥˊ。",deep:"1. 注音比較\n穹：ㄑㄩㄥ＝蒼穹、穹廬、穹谷、穹石、清穹。★教育部《國語辭典簡編本》「穹」只收一聲ㄑㄩㄥ，讀成二聲ㄑㄩㄥˊ不是審訂音\n2. 國字拆解與造字原因\n穹：形聲字，「穴」＋「弓」（聲）。像弓一樣中間隆起的洞形→天空看起來就像一個圓頂罩著大地，所以叫「蒼穹」。"},
  {id:"p416",grade:10,word:"泥鰍",target:"鰍",zhuyin:"ㄑㄧㄡ",pinyin:"qiū",wz:"ㄋㄧˊ ㄑㄧㄡ",wrong:[{z:"ㄐㄧㄡ",p:"jiū"},{z:"ㄑㄧㄡˊ",p:"qiú"}],note:"「泥鰍」的「鰍」讀ㄑㄧㄡ。",deep:"1. 注音比較\n鰍：ㄑㄧㄡ（一聲）＝泥鰍；ㄐㄧㄡ＝無此音；ㄑㄧㄡˊ＝誤讀\n2. 國字拆解與造字原因\n鰍：形聲字，「魚」＋「秋」（聲），生活在泥中的細長小魚→泥鰍。與「秋」同音ㄑㄧㄡ。"},
  {id:"p417",grade:10,word:"愜意",target:"愜",zhuyin:"ㄑㄧㄝˋ",pinyin:"qiè",wz:"ㄑㄧㄝˋ ㄧˋ",wrong:[{z:"ㄒㄧㄚˊ",p:"xiá"},{z:"ㄐㄧㄚˊ",p:"jiá"}],note:"「愜意」的「愜」讀ㄑㄧㄝˋ,滿足舒暢。",deep:"1. 注音比較\n愜：ㄑㄧㄝˋ（四聲）＝愜意、愜心；ㄒㄧㄚˊ＝無此音（是「狹」的讀音）；ㄐㄧㄚˊ＝無此音\n2. 國字拆解與造字原因\n愜：形聲字，「忄」＋「匧」（聲），心中滿足舒暢→愜意。讀ㄑㄧㄝˋ，與「怯」同音。"},
  {id:"p418",grade:10,word:"髭鬚",target:"髭",zhuyin:"ㄗ",pinyin:"zī",wz:"ㄗ ㄒㄩ",wrong:[{z:"ㄘˊ",p:"cí"},{z:"ㄗˇ",p:"zǐ"}],note:"「髭鬚」的「髭」讀ㄗ,嘴上邊的鬍子。",deep:"1. 注音比較\n髭：ㄗ（一聲）＝髭鬚；ㄘˊ＝無此音（是「慈」的讀音）；ㄗˇ＝誤讀\n2. 國字拆解與造字原因\n髭：形聲字，「髟」（毛髮）＋「此」（聲），嘴脣上方的鬍子→髭鬚。讀一聲ㄗ。"},
  {id:"p419",grade:10,word:"頷首",target:"頷",zhuyin:"ㄏㄢˋ",pinyin:"hàn",wz:"ㄏㄢˋ ㄕㄡˇ",wrong:[{z:"ㄏㄢˊ",p:"hán"},{z:"ㄧㄢˊ",p:"yán"}],note:"「頷首」的「頷」讀ㄏㄢˋ,點頭。",deep:"1. 注音比較\n頷：ㄏㄢˋ（四聲）＝頷首、下頷；ㄏㄢˊ＝誤讀（受「含」影響）；ㄧㄢˊ＝無此音\n2. 國字拆解與造字原因\n頷：形聲字，「頁」（頭）＋「含」（聲），本義是下巴→頷首（點頭）。讀ㄏㄢˋ。"},
  {id:"p420",grade:10,word:"打鼾",target:"鼾",zhuyin:"ㄏㄢ",pinyin:"hān",wz:"ㄉㄚˇ ㄏㄢ",wrong:[{z:"ㄍㄢ",p:"gān"},{z:"ㄏㄢˊ",p:"hán"}],note:"「打鼾」「鼾聲」的「鼾」讀ㄏㄢ。",deep:"1. 注音比較\n鼾：ㄏㄢ（一聲）＝打鼾、鼾聲如雷；ㄍㄢ＝無此音（是「干」的讀音）；ㄏㄢˊ＝誤讀\n2. 國字拆解與造字原因\n鼾：形聲字，「鼻」＋「干」（聲），睡覺時鼻息作聲→打鼾。讀一聲ㄏㄢ。"},
  {id:"p421",grade:1,word:"快樂",target:"樂",zhuyin:"ㄌㄜˋ",pinyin:"lè",wz:"ㄎㄨㄞˋ ㄌㄜˋ",wrong:[{z:"ㄩㄝˋ",p:"yuè"},{z:"ㄧㄠˋ",p:"yào"}],note:"「快樂」「樂觀」讀ㄌㄜˋ；「音樂」「樂器」讀ㄩㄝˋ。",deep:"1. 注音比較\n樂：ㄌㄜˋ（四聲）＝快樂、樂觀、歡樂；ㄩㄝˋ（四聲）＝音樂、樂器、樂團；ㄧㄠˋ（四聲）＝仁者樂山、智者樂水（喜好，文言）\n2. 國字拆解與造字原因\n樂：象形字，像木架上張著絲弦的樂器。本義是樂器、音樂（ㄩㄝˋ）；音樂使人心情愉悅→「快樂」（ㄌㄜˋ）；心裡喜愛某事物→「樂山樂水」（ㄧㄠˋ）。三個音是「樂器→愉快→喜好」一路引申來的。"},
  {id:"p422",grade:1,word:"學校",target:"校",zhuyin:"ㄒㄧㄠˋ",pinyin:"xiào",wz:"ㄒㄩㄝˊ ㄒㄧㄠˋ",wrong:[{z:"ㄐㄧㄠˋ",p:"jiào"},{z:"ㄒㄧㄠ",p:"xiāo"}],note:"「學校」「校園」讀ㄒㄧㄠˋ；「校對」「校正」讀ㄐㄧㄠˋ。",deep:"1. 注音比較\n校：ㄒㄧㄠˋ（四聲）＝學校、校園、校長；ㄐㄧㄠˋ（四聲）＝校對、校正、校稿；ㄒㄧㄠ＝無此音（易與「消」相混）\n2. 國字拆解與造字原因\n校：形聲字，「木」＋「交」（聲）。本義是木製的刑具，後借指教學的場所→「學校」（ㄒㄧㄠˋ）；又引申為比對、訂正→「校對、校勘」（ㄐㄧㄠˋ）。記法：查核文字讀ㄐㄧㄠˋ，讀書的地方讀ㄒㄧㄠˋ。"},
  {id:"p423",grade:1,word:"還有",target:"還",zhuyin:"ㄏㄞˊ",pinyin:"hái",wz:"ㄏㄞˊ ㄧㄡˇ",wrong:[{z:"ㄏㄨㄢˊ",p:"huán"},{z:"ㄏㄢˊ",p:"hán"}],note:"「還有」「還沒」（尚且、仍舊）讀ㄏㄞˊ；「還書」「歸還」讀ㄏㄨㄢˊ。",deep:"1. 注音比較\n還：ㄏㄞˊ（二聲）＝還有、還沒、還要；ㄏㄨㄢˊ（二聲）＝還書、歸還、還錢；ㄏㄢˊ＝無此音（是「寒」的讀音）\n2. 國字拆解與造字原因\n還：形聲字，「辵（辶，行走）」＋「睘」（聲）。本義是返回→把東西送回去是「歸還」（ㄏㄨㄢˊ）；由「回頭、再次」的意思虛化成副詞「仍然、尚且」→「還有、還在」（ㄏㄞˊ）。當動詞讀ㄏㄨㄢˊ，當副詞讀ㄏㄞˊ。"},
  {id:"p424",grade:1,word:"全都",target:"都",zhuyin:"ㄉㄡ",pinyin:"dōu",wz:"ㄑㄩㄢˊ ㄉㄡ",wrong:[{z:"ㄉㄨ",p:"dū"},{z:"ㄉㄡˋ",p:"dòu"}],note:"「全都」「都來了」（全部）讀ㄉㄡ；「首都」「都市」讀ㄉㄨ。",deep:"1. 注音比較\n都：ㄉㄡ（一聲）＝全都、大家都到了；ㄉㄨ（一聲)＝首都、都市、都會；ㄉㄡˋ＝無此音（是「鬥」的讀音）\n2. 國字拆解與造字原因\n都：形聲字，「邑（阝，城邑）」＋「者」（聲）。本義是大城市、國君所在的城→「首都、都市」（ㄉㄨ）；後來借用作副詞，表「全部、甚至」→「全都、都是」（ㄉㄡ）。當名詞讀ㄉㄨ，當副詞讀ㄉㄡ。"},
  {id:"p425",grade:1,word:"買東西",target:"西",zhuyin:"˙ㄒㄧ",pinyin:"xi",wz:"ㄇㄞˇ ㄉㄨㄥ ˙ㄒㄧ",wrong:[{z:"ㄒㄧ",p:"xī"},{z:"ㄒㄧˇ",p:"xǐ"}],note:"「東西」指物品時，「西」讀輕聲˙ㄒㄧ；指方向（東邊西邊）時讀ㄒㄧ。",deep:"1. 注音比較\n西：˙ㄒㄧ（輕聲）＝買東西、好東西（物品）；ㄒㄧ（一聲）＝東西南北、西邊（方向）；ㄒㄧˇ＝無此音（是「洗」的讀音）\n2. 國字拆解與造字原因\n西：象形字，甲骨文像鳥巢的形狀。太陽西下時鳥兒歸巢，所以借來表示「西方」（ㄒㄧ）；「東西」合起來本指東邊西邊，後來泛指各種物品，這時「西」輕輕帶過讀輕聲（˙ㄒㄧ）。"},
  {id:"p426",grade:1,word:"房間",target:"間",zhuyin:"ㄐㄧㄢ",pinyin:"jiān",wz:"ㄈㄤˊ ㄐㄧㄢ",wrong:[{z:"ㄐㄧㄢˋ",p:"jiàn"},{z:"ㄒㄧㄢˊ",p:"xián"}],note:"「房間」「中間」「時間」讀ㄐㄧㄢ；「間斷」「間諜」「間不容髮」讀ㄐㄧㄢˋ。",deep:"1. 注音比較\n間：ㄐㄧㄢ（一聲）＝房間、中間、時間；ㄐㄧㄢˋ（四聲）＝間斷、間隔、間諜；ㄒㄧㄢˊ＝無此音（是「閒」的讀音，兩字形近易混）\n2. 國字拆解與造字原因\n間：會意字，本作「閒」，門（門）縫裡照進月光（後改為日），表示門有縫隙。指空間、處所→「房間、中間」（ㄐㄧㄢ）；由縫隙引申為「隔開、挑撥」→「間斷、離間」（ㄐㄧㄢˋ）。當名詞讀一聲，當動詞讀四聲。"},
  {id:"p427",grade:1,word:"多少",target:"少",zhuyin:"ㄕㄠˇ",pinyin:"shǎo",wz:"ㄉㄨㄛ ㄕㄠˇ",wrong:[{z:"ㄕㄠˋ",p:"shào"},{z:"ㄒㄧㄠˇ",p:"xiǎo"}],note:"「多少」「很少」（數量少）讀ㄕㄠˇ；「少年」「少女」讀ㄕㄠˋ。",deep:"1. 注音比較\n少：ㄕㄠˇ（三聲）＝多少、減少、缺少；ㄕㄠˋ（四聲）＝少年、少女、少爺；ㄒㄧㄠˇ＝無此音（是「小」的讀音，意思相近更要分清）\n2. 國字拆解與造字原因\n少：指事字，在「小」的字形下加一撇，表示比小更細微，本義是數量不多（ㄕㄠˇ）；年紀不大的人歲數「少」→「少年」（ㄕㄠˋ）。記法：講數量讀三聲，講年紀讀四聲。"},
  {id:"p428",grade:1,word:"回答",target:"答",zhuyin:"ㄉㄚˊ",pinyin:"dá",wz:"ㄏㄨㄟˊ ㄉㄚˊ",wrong:[{z:"ㄉㄚ",p:"dā"},{z:"ㄊㄚˇ",p:"tǎ"}],note:"「回答」「答案」讀ㄉㄚˊ；「答應」的「答」讀ㄉㄚ。",deep:"1. 注音比較\n答：ㄉㄚˊ（二聲）＝回答、答案、報答；ㄉㄚ（一聲）＝答應、答理；ㄊㄚˇ＝無此音（是「塔」的讀音，同聲符）\n2. 國字拆解與造字原因\n答：形聲字，「竹」＋「合」（聲）。古人把回覆的話寫在竹簡上送回，本義是回覆→「回答、答案」（ㄉㄚˊ）；「答應」是口語用法，聲調弱化讀一聲（ㄉㄚ）。"},
  {id:"p429",grade:1,word:"真假",target:"假",zhuyin:"ㄐㄧㄚˇ",pinyin:"jiǎ",wz:"ㄓㄣ ㄐㄧㄚˇ",wrong:[{z:"ㄐㄧㄚˋ",p:"jià"},{z:"ㄒㄧㄚˊ",p:"xiá"}],note:"「真假」「假裝」讀ㄐㄧㄚˇ；「假日」「放假」讀ㄐㄧㄚˋ。",deep:"1. 注音比較\n假：ㄐㄧㄚˇ（三聲）＝真假、假裝、假如；ㄐㄧㄚˋ（四聲）＝假日、放假、請假；ㄒㄧㄚˊ＝無此音（是「霞」的讀音，同聲符）\n2. 國字拆解與造字原因\n假：形聲字，「亻」＋「叚」（聲，借的意思）。本義是借用，借來的不是真的→「假裝、真假」（ㄐㄧㄚˇ）；向工作「借」幾天休息的時間→「放假、假期」（ㄐㄧㄚˋ）。"},
  {id:"p430",grade:2,word:"好奇",target:"好",zhuyin:"ㄏㄠˋ",pinyin:"hào",wz:"ㄏㄠˋ ㄑㄧˊ",wrong:[{z:"ㄏㄠˇ",p:"hǎo"},{z:"ㄏㄠˊ",p:"háo"}],note:"「好奇」「愛好」「好學」（喜愛）讀ㄏㄠˋ；「好人」「美好」讀ㄏㄠˇ。",deep:"1. 注音比較\n好：ㄏㄠˋ（四聲）＝好奇、愛好、好學不倦；ㄏㄠˇ（三聲）＝好人、美好、好棒；ㄏㄠˊ＝無此音（是「豪」的讀音）\n2. 國字拆解與造字原因\n好：會意字，「女」＋「子」，母親抱著孩子，是最美善的畫面，本義是美好（ㄏㄠˇ）；對美好的事物心生喜愛→「好奇、愛好」（ㄏㄠˋ）。記法：當形容詞讀三聲，當動詞「喜愛」讀四聲。"},
  {id:"p431",grade:2,word:"看門",target:"看",zhuyin:"ㄎㄢ",pinyin:"kān",wz:"ㄎㄢ ㄇㄣˊ",wrong:[{z:"ㄎㄢˋ",p:"kàn"},{z:"ㄎㄢˇ",p:"kǎn"}],note:"「看門」「看守」「看護」（守護）讀ㄎㄢ；「看書」「觀看」讀ㄎㄢˋ。",deep:"1. 注音比較\n看：ㄎㄢ（一聲）＝看門、看守、看護；ㄎㄢˋ（四聲）＝看書、看電視、觀看；ㄎㄢˇ＝無此音（是「砍」的讀音）\n2. 國字拆解與造字原因\n看：會意字，把「手」搭在「目」（眼睛）上遠望，本義是用眼睛注視（ㄎㄢˋ）；一直盯著、守著人或物→「看守、看門」（ㄎㄢ）。記法：一般的看讀四聲，守著不走的看讀一聲。"},
  {id:"p432",grade:2,word:"慢慢地",target:"地",zhuyin:"˙ㄉㄜ",pinyin:"de",wz:"ㄇㄢˋ ㄇㄢˋ ˙ㄉㄜ",wrong:[{z:"ㄉㄧˋ",p:"dì"},{z:"ㄉㄜˊ",p:"dé"}],note:"「慢慢地走」的「地」是副詞語尾，讀輕聲˙ㄉㄜ；「土地」「地方」讀ㄉㄧˋ。",deep:"1. 注音比較\n地：˙ㄉㄜ（輕聲）＝慢慢地、悄悄地、認真地（放在動作前的「～地」）；ㄉㄧˋ（四聲）＝土地、地方、地球；ㄉㄜˊ＝無此音（是「得」的讀音，「跑得快」的「得」也讀輕聲，要分清用法）\n2. 國字拆解與造字原因\n地：形聲字，「土」＋「也」（聲），本義是大地、土地（ㄉㄧˋ）；後來被借去當助詞，接在形容詞後面修飾動作（慢慢地跑），這時只輕輕帶過，讀輕聲（˙ㄉㄜ）。"},
  {id:"p433",grade:2,word:"了解",target:"了",zhuyin:"ㄌㄧㄠˇ",pinyin:"liǎo",wz:"ㄌㄧㄠˇ ㄐㄧㄝˇ",wrong:[{z:"ㄌㄜ",p:"le"},{z:"ㄌㄧㄠˋ",p:"liào"}],note:"「了解」「了不起」「受不了」讀ㄌㄧㄠˇ；「吃了飯」「走了」的「了」讀輕聲˙ㄌㄜ。",deep:"1. 注音比較\n了：ㄌㄧㄠˇ（三聲）＝了解、了不起、一目了然；˙ㄌㄜ（輕聲）＝吃了、走了、下雨了（表動作完成的助詞）；ㄌㄧㄠˋ＝無此音（是「料」的讀音）\n2. 國字拆解與造字原因\n了：象形字，像嬰兒被包起來、手臂收在襁褓中的樣子，本義是完結、結束→「了結、了解（把事情弄明白、弄完）」（ㄌㄧㄠˇ）；表示動作結束的意思虛化後，變成句尾助詞→「吃飽了」（˙ㄌㄜ）。"},
  {id:"p434",grade:2,word:"得到",target:"得",zhuyin:"ㄉㄜˊ",pinyin:"dé",wz:"ㄉㄜˊ ㄉㄠˋ",wrong:[{z:"ㄉㄟˇ",p:"děi"},{z:"ㄉㄜ",p:"de"}],note:"「得到」「獲得」讀ㄉㄜˊ；「我得走了」（必須）讀ㄉㄟˇ；「跑得快」的「得」讀輕聲。",deep:"1. 注音比較\n得：ㄉㄜˊ（二聲）＝得到、獲得、心得；ㄉㄟˇ（三聲）＝我得走了、非得（必須）；˙ㄉㄜ（輕聲）＝跑得快、寫得好（連接補語）\n2. 國字拆解與造字原因\n得：會意字，甲骨文像手拿著貝殼（古代的錢），在路上撿到財貨，本義是獲得（ㄉㄜˊ）；「不得不做」的語氣濃縮成「必須」→讀ㄉㄟˇ；夾在動詞和補語中間時虛化成助詞→「跑得快」（˙ㄉㄜ）。"},
  {id:"p435",grade:2,word:"打掃",target:"掃",zhuyin:"ㄙㄠˇ",pinyin:"sǎo",wz:"ㄉㄚˇ ㄙㄠˇ",wrong:[{z:"ㄙㄠˋ",p:"sào"},{z:"ㄕㄠˇ",p:"shǎo"}],note:"「打掃」「掃地」（動作）讀ㄙㄠˇ；「掃帚」（名詞）讀ㄙㄠˋ。",deep:"1. 注音比較\n掃：ㄙㄠˇ（三聲）＝打掃、掃地、掃墓；ㄙㄠˋ（四聲）＝掃帚；ㄕㄠˇ＝無此音（是「少」的讀音）\n2. 國字拆解與造字原因\n掃：會意字，「扌（手）」＋「帚（掃帚）」，手拿掃帚清潔，是「掃」的動作（ㄙㄠˇ）；只有「掃帚」這個名詞讀ㄙㄠˋ，要特別記住。動作三聲、器具四聲。"},
  {id:"p436",grade:2,word:"數學",target:"數",zhuyin:"ㄕㄨˋ",pinyin:"shù",wz:"ㄕㄨˋ ㄒㄩㄝˊ",wrong:[{z:"ㄕㄨˇ",p:"shǔ"},{z:"ㄕㄨㄛˋ",p:"shuò"}],note:"「數學」「數字」（名詞）讀ㄕㄨˋ；「數一數」「數星星」（計算）讀ㄕㄨˇ。",deep:"1. 注音比較\n數：ㄕㄨˋ（四聲）＝數學、數字、數量；ㄕㄨˇ（三聲）＝數一數、數星星、屈指可數；ㄕㄨㄛˋ（四聲）＝數見不鮮（屢次，文言）\n2. 國字拆解與造字原因\n數：形聲字，「攵」＋「婁」（聲）。本義是一個一個計算（ㄕㄨˇ）；算出來的結果是數目→「數字、數學」（ㄕㄨˋ）；一次又一次→「數見不鮮」（ㄕㄨㄛˋ）。動詞三聲、名詞四聲。"},
  {id:"p437",grade:2,word:"銀行",target:"行",zhuyin:"ㄏㄤˊ",pinyin:"háng",wz:"ㄧㄣˊ ㄏㄤˊ",wrong:[{z:"ㄒㄧㄥˊ",p:"xíng"},{z:"ㄏㄥˊ",p:"héng"}],note:"「銀行」「行列」「各行各業」讀ㄏㄤˊ；「行走」「旅行」讀ㄒㄧㄥˊ。",deep:"1. 注音比較\n行：ㄏㄤˊ（二聲）＝銀行、行列、行業；ㄒㄧㄥˊ（二聲）＝行走、旅行、行動；ㄏㄥˊ（二聲）＝道行（修行的功夫）\n2. 國字拆解與造字原因\n行：象形字，甲骨文像四通八達的十字路口，本義是道路。人在路上走→「行走」（ㄒㄧㄥˊ）；路旁店鋪排成一列一列→「行列」，商家聚集的處所→「銀行、商行」（ㄏㄤˊ）。"},
  {id:"p438",grade:2,word:"長短",target:"長",zhuyin:"ㄔㄤˊ",pinyin:"cháng",wz:"ㄔㄤˊ ㄉㄨㄢˇ",wrong:[{z:"ㄓㄤˇ",p:"zhǎng"},{z:"ㄔㄤˇ",p:"chǎng"}],note:"「長短」「長久」「很長」讀ㄔㄤˊ；「長大」「長輩」「班長」讀ㄓㄤˇ。",deep:"1. 注音比較\n長：ㄔㄤˊ（二聲）＝長短、長久、長頸鹿；ㄓㄤˇ（三聲）＝長大、長輩、校長；ㄔㄤˇ＝無此音（是「場」的讀音）\n2. 國字拆解與造字原因\n長：象形字，像長髮老人拄杖的樣子。頭髮長長要靠時間累積→「生長、年長、首長」（ㄓㄤˇ）；長髮下垂的樣子用來形容距離、時間的長度→「長短、長久」（ㄔㄤˊ）。"},
  {id:"p439",grade:2,word:"背課文",target:"背",zhuyin:"ㄅㄟˋ",pinyin:"bèi",wz:"ㄅㄟˋ ㄎㄜˋ ㄨㄣˊ",wrong:[{z:"ㄅㄟ",p:"bēi"},{z:"ㄆㄟˊ",p:"péi"}],note:"「背課文」「背誦」「背後」讀ㄅㄟˋ；「背書包」（用背扛）讀ㄅㄟ。",deep:"1. 注音比較\n背：ㄅㄟˋ（四聲）＝背課文、背後、違背；ㄅㄟ（一聲）＝背書包、背小孩（負載）；ㄆㄟˊ＝無此音（是「陪」的讀音）\n2. 國字拆解與造字原因\n背：形聲字，「月（肉）」＋「北」（聲，甲骨文「北」像兩人背對背）。本義是背部（ㄅㄟˋ），把課文「放在背後」不看著唸＝背誦；用背部扛東西的動作讀ㄅㄟ。名詞與「背誦、違背」讀四聲，「用背扛」讀一聲。"},
  {id:"p440",grade:2,word:"中間",target:"中",zhuyin:"ㄓㄨㄥ",pinyin:"zhōng",wz:"ㄓㄨㄥ ㄐㄧㄢ",wrong:[{z:"ㄓㄨㄥˋ",p:"zhòng"},{z:"ㄔㄨㄥ",p:"chōng"}],note:"「中間」「中央」「台中」讀ㄓㄨㄥ；「中獎」「猜中」「中暑」讀ㄓㄨㄥˋ。",deep:"1. 注音比較\n中：ㄓㄨㄥ（一聲）＝中間、中央、中午；ㄓㄨㄥˋ（四聲）＝中獎、猜中、中暑；ㄔㄨㄥ＝無此音（是「充」的讀音）\n2. 國字拆解與造字原因\n中：指事字，像一面旗子插在範圍的正中央，本義是中央、裡面（ㄓㄨㄥ）；箭射到正中央＝命中，引申為「正好對上、遭受」→「中獎、中毒」（ㄓㄨㄥˋ）。位置讀一聲，擊中讀四聲。"},
  {id:"p441",grade:2,word:"種樹",target:"種",zhuyin:"ㄓㄨㄥˋ",pinyin:"zhòng",wz:"ㄓㄨㄥˋ ㄕㄨˋ",wrong:[{z:"ㄓㄨㄥˇ",p:"zhǒng"},{z:"ㄔㄨㄥˊ",p:"chóng"}],note:"「種樹」「種花」「種植」（動作）讀ㄓㄨㄥˋ；「種子」「種類」讀ㄓㄨㄥˇ。",deep:"1. 注音比較\n種：ㄓㄨㄥˋ（四聲）＝種樹、種花、耕種；ㄓㄨㄥˇ（三聲）＝種子、種類、品種；ㄔㄨㄥˊ＝無此音（是「蟲」的讀音）\n2. 國字拆解與造字原因\n種：形聲字，「禾」＋「重」（聲）。穀物的種子是名詞（ㄓㄨㄥˇ）；把種子埋進土裡的動作是動詞（ㄓㄨㄥˋ）。記法：名詞三聲、動詞四聲，「種（ㄓㄨㄥˋ）下種（ㄓㄨㄥˇ）子」。"},
  {id:"p442",grade:2,word:"到處",target:"處",zhuyin:"ㄔㄨˋ",pinyin:"chù",wz:"ㄉㄠˋ ㄔㄨˋ",wrong:[{z:"ㄔㄨˇ",p:"chǔ"},{z:"ㄕㄨˋ",p:"shù"}],note:"「到處」「處所」「辦事處」（地方）讀ㄔㄨˋ；「處理」「相處」讀ㄔㄨˇ。",deep:"1. 注音比較\n處：ㄔㄨˋ（四聲）＝到處、住處、益處；ㄔㄨˇ（三聲）＝處理、相處、處罰；ㄕㄨˋ＝無此音（是「樹」的讀音）\n2. 國字拆解與造字原因\n處：從「虍」（虎）從「処」（人靠几而止息），本義是停留、安頓。當動詞「安頓、對待」→「處理、相處」（ㄔㄨˇ）；停留的地方（名詞）→「處所、到處」（ㄔㄨˋ）。動詞三聲、名詞四聲。"},
  {id:"p443",grade:2,word:"當然",target:"當",zhuyin:"ㄉㄤ",pinyin:"dāng",wz:"ㄉㄤ ㄖㄢˊ",wrong:[{z:"ㄉㄤˋ",p:"dàng"},{z:"ㄊㄤ",p:"tāng"}],note:"「當然」「當時」「應當」讀ㄉㄤ；「當作」「上當」「當鋪」讀ㄉㄤˋ。",deep:"1. 注音比較\n當：ㄉㄤ（一聲）＝當然、當時、擔當；ㄉㄤˋ（四聲）＝當作、上當、妥當；ㄊㄤ＝無此音（是「湯」的讀音）\n2. 國字拆解與造字原因\n當：形聲字，「田」＋「尚」（聲）。本義是兩塊田地價值相抵，引申為「承擔、面對、正值」→「擔當、當時」（ㄉㄤ）；「抵押、算作」→「典當、當作」（ㄉㄤˋ）。"},
  {id:"p444",grade:2,word:"應該",target:"應",zhuyin:"ㄧㄥ",pinyin:"yīng",wz:"ㄧㄥ ㄍㄞ",wrong:[{z:"ㄧㄥˋ",p:"yìng"},{z:"ㄧㄣ",p:"yīn"}],note:"「應該」「應當」讀ㄧㄥ；「答應」「反應」「應付」讀ㄧㄥˋ。",deep:"1. 注音比較\n應：ㄧㄥ（一聲）＝應該、應當、應有盡有；ㄧㄥˋ（四聲）＝答應、反應、應付；ㄧㄣ＝無此音（是「音」的讀音）\n2. 國字拆解與造字原因\n應：形聲字，「心」＋「䧹」（聲）。本義是心裡的回應→「答應、回應、反應」（ㄧㄥˋ）；表示道理上「該當如此」時讀一聲→「應該、應當」。回應讀四聲，該當讀一聲。"},
  {id:"p445",grade:3,word:"親切",target:"切",zhuyin:"ㄑㄧㄝˋ",pinyin:"qiè",wz:"ㄑㄧㄣ ㄑㄧㄝˋ",wrong:[{z:"ㄑㄧㄝ",p:"qiē"},{z:"ㄑㄧㄚˇ",p:"qiǎ"}],note:"「親切」「一切」「切記」讀ㄑㄧㄝˋ；「切菜」「切開」讀ㄑㄧㄝ。",deep:"1. 注音比較\n切：ㄑㄧㄝˋ（四聲）＝親切、一切、迫切；ㄑㄧㄝ（一聲）＝切菜、切開、切割；ㄑㄧㄚˇ＝無此音（是「卡」的讀音）\n2. 國字拆解與造字原因\n切：形聲字，「刀」＋「七」（聲）。本義是用刀分割→「切菜」（ㄑㄧㄝ）；刀貼著東西切，引申為「貼近、密合」→「親切、密切、切身」（ㄑㄧㄝˋ）。動刀讀一聲，貼近讀四聲。"},
  {id:"p446",grade:3,word:"嘔吐",target:"吐",zhuyin:"ㄊㄨˋ",pinyin:"tù",wz:"ㄡˇ ㄊㄨˋ",wrong:[{z:"ㄊㄨˇ",p:"tǔ"},{z:"ㄉㄨˋ",p:"dù"}],note:"「嘔吐」「吐奶」（不由自主湧出）讀ㄊㄨˋ；「吐氣」「談吐」（主動吐出）讀ㄊㄨˇ。",deep:"1. 注音比較\n吐：ㄊㄨˋ（四聲）＝嘔吐、吐血、上吐下瀉；ㄊㄨˇ（三聲）＝吐氣、吐露、談吐；ㄉㄨˋ＝無此音（是「肚」的讀音）\n2. 國字拆解與造字原因\n吐：形聲字，「口」＋「土」（聲）。從嘴裡出來的都叫吐：自己主動吐出（吐口水、吐露心事）讀ㄊㄨˇ；生病忍不住嘔出來讀ㄊㄨˋ。記法：能控制的讀三聲，控制不了的讀四聲。"},
  {id:"p447",grade:3,word:"沒收",target:"沒",zhuyin:"ㄇㄛˋ",pinyin:"mò",wz:"ㄇㄛˋ ㄕㄡ",wrong:[{z:"ㄇㄟˊ",p:"méi"},{z:"ㄇㄛ",p:"mō"}],note:"「沒收」「沉沒」「淹沒」讀ㄇㄛˋ；「沒有」「沒關係」讀ㄇㄟˊ。",deep:"1. 注音比較\n沒：ㄇㄛˋ（四聲）＝沒收、沉沒、埋沒；ㄇㄟˊ（二聲）＝沒有、沒空、沒關係；ㄇㄛ＝無此音（是「摸」的讀音）\n2. 國字拆解與造字原因\n沒：會意字，「氵（水）」＋「殳」，人沉入水中，本義是沉入水裡→「沉沒、淹沒」，東西被收走不見了→「沒收」（ㄇㄛˋ）；「沉下去＝不存在了」引申成表示「無」的副詞→「沒有」（ㄇㄟˊ）。"},
  {id:"p448",grade:3,word:"興旺",target:"興",zhuyin:"ㄒㄧㄥ",pinyin:"xīng",wz:"ㄒㄧㄥ ㄨㄤˋ",wrong:[{z:"ㄒㄧㄥˋ",p:"xìng"},{z:"ㄒㄧㄥˇ",p:"xǐng"}],note:"「興旺」「興盛」「興建」讀ㄒㄧㄥ；「興趣」「高興」「興致」讀ㄒㄧㄥˋ。",deep:"1. 注音比較\n興：ㄒㄧㄥ（一聲）＝興旺、興盛、興風作浪；ㄒㄧㄥˋ（四聲）＝興趣、高興、興高采烈；ㄒㄧㄥˇ＝無此音（是「醒」的讀音）\n2. 國字拆解與造字原因\n興：會意字，甲骨文像四隻手合力抬起一個器物，本義是抬起、發動→「興建、興起、興旺」（ㄒㄧㄥ）；事情辦起來心情高昂→「高興、興致」（ㄒㄧㄥˋ）。做起來讀一聲，樂起來讀四聲。"},
  {id:"p449",grade:3,word:"大夫",target:"大",zhuyin:"ㄉㄞˋ",pinyin:"dài",wz:"ㄉㄞˋ ㄈㄨ",wrong:[{z:"ㄉㄚˋ",p:"dà"},{z:"ㄊㄞˋ",p:"tài"}],note:"「大夫」指醫生時，「大」讀ㄉㄞˋ；一般的「大小」「大人」讀ㄉㄚˋ。",deep:"1. 注音比較\n大：ㄉㄞˋ（四聲）＝大夫（醫生）；ㄉㄚˋ（四聲）＝大小、大人、大家；ㄊㄞˋ＝無此音（是「太」的讀音）\n2. 國字拆解與造字原因\n大：象形字，像人張開雙手雙腳站立的樣子，本義是大（ㄉㄚˋ）。「大夫」本是古代官名（讀ㄉㄚˋㄈㄨ），宋代太醫官階有「大夫」，民間便把醫生稱作「大夫」，口語轉讀ㄉㄞˋ˙ㄈㄨ——同一個詞，當官名讀ㄉㄚˋ，當醫生讀ㄉㄞˋ。"},
  {id:"p450",grade:3,word:"奇數",target:"奇",zhuyin:"ㄐㄧ",pinyin:"jī",wz:"ㄐㄧ ㄕㄨˋ",wrong:[{z:"ㄑㄧˊ",p:"qí"},{z:"ㄐㄧˇ",p:"jǐ"}],note:"「奇數」「奇偶」（單數）讀ㄐㄧ；「奇怪」「好奇」「神奇」讀ㄑㄧˊ。",deep:"1. 注音比較\n奇：ㄐㄧ（一聲）＝奇數、奇偶（單數，和「偶」相對）；ㄑㄧˊ（二聲）＝奇怪、奇妙、驚奇；ㄐㄧˇ＝無此音（是「幾」的讀音）\n2. 國字拆解與造字原因\n奇：從「大」從「可」。本義是特殊、罕見→「奇怪、奇特」（ㄑㄧˊ）；「特殊」的數＝不成雙的單數→「奇數」（ㄐㄧ）。記法：數學的單數讀ㄐㄧ，奇怪的事讀ㄑㄧˊ。"},
  {id:"p451",grade:3,word:"鋪路",target:"鋪",zhuyin:"ㄆㄨ",pinyin:"pū",wz:"ㄆㄨ ㄌㄨˋ",wrong:[{z:"ㄆㄨˋ",p:"pù"},{z:"ㄈㄨ",p:"fū"}],note:"「鋪路」「鋪床」（動作）讀ㄆㄨ；「店鋪」「床鋪」（名詞）讀ㄆㄨˋ。",deep:"1. 注音比較\n鋪：ㄆㄨ（一聲）＝鋪路、鋪床、鋪陳；ㄆㄨˋ（四聲）＝店鋪、床鋪、當鋪；ㄈㄨ＝無此音（是「敷」的讀音，意思相近更易混）\n2. 國字拆解與造字原因\n鋪：形聲字，「金」＋「甫」（聲）。本義是門上銜門環的金屬底座，引申為把東西平展開來→「鋪路、鋪桌巾」（ㄆㄨ）；平面展開擺放貨物的地方→「店鋪」（ㄆㄨˋ）。動詞一聲、名詞四聲。"},
  {id:"p452",grade:3,word:"投降",target:"降",zhuyin:"ㄒㄧㄤˊ",pinyin:"xiáng",wz:"ㄊㄡˊ ㄒㄧㄤˊ",wrong:[{z:"ㄐㄧㄤˋ",p:"jiàng"},{z:"ㄒㄧㄤˋ",p:"xiàng"}],note:"「投降」「降服」讀ㄒㄧㄤˊ；「降落」「下降」「降低」讀ㄐㄧㄤˋ。",deep:"1. 注音比較\n降：ㄒㄧㄤˊ（二聲）＝投降、降服、降龍伏虎；ㄐㄧㄤˋ（四聲）＝降落、下降、降價；ㄒㄧㄤˋ＝無此音（是「向」的讀音）\n2. 國字拆解與造字原因\n降：會意字，「阜（阝，土山）」＋兩腳向下的形，本義是從山上走下來→「下降、降落」（ㄐㄧㄤˋ）；打敗仗「放下」武器屈服→「投降」（ㄒㄧㄤˊ）。往下讀ㄐㄧㄤˋ，屈服讀ㄒㄧㄤˊ。"},
  {id:"p453",grade:3,word:"貝殼",target:"殼",zhuyin:"ㄎㄜˊ",pinyin:"ké",wz:"ㄅㄟˋ ㄎㄜˊ",wrong:[{z:"ㄑㄧㄠˋ",p:"qiào"},{z:"ㄎㄜˋ",p:"kè"}],note:"「貝殼」「蛋殼」（口語）讀ㄎㄜˊ；「地殼」「甲殼」（書面）讀ㄑㄧㄠˋ。",deep:"1. 注音比較\n殼：ㄎㄜˊ（二聲）＝貝殼、蛋殼、果殼（語音）；ㄑㄧㄠˋ（四聲）＝地殼、甲殼、軀殼（讀音）；ㄎㄜˋ＝無此音（是「課」的讀音）\n2. 國字拆解與造字原因\n殼：從「殳」（手持器具敲擊），本義是堅硬的外皮，要敲才會破。日常口語的殼讀ㄎㄜˊ（雞蛋殼）；科學、書面語詞讀ㄑㄧㄠˋ（地殼、金蟬脫殼）。"},
  {id:"p454",grade:3,word:"漲價",target:"漲",zhuyin:"ㄓㄤˇ",pinyin:"zhǎng",wz:"ㄓㄤˇ ㄐㄧㄚˋ",wrong:[{z:"ㄓㄤˋ",p:"zhàng"},{z:"ㄔㄤˊ",p:"cháng"}],note:"「漲價」「水漲船高」讀ㄓㄤˇ；「漲紅了臉」「豆子泡漲」讀ㄓㄤˋ。",deep:"1. 注音比較\n漲：ㄓㄤˇ（三聲）＝漲價、漲潮、水漲船高；ㄓㄤˋ（四聲）＝漲紅了臉、泡漲（體積變大）；ㄔㄤˊ＝無此音（是「長」的讀音之一）\n2. 國字拆解與造字原因\n漲：形聲字，「氵（水）」＋「張」（聲）。本義是水位升高→「漲潮、漲價（價格像水位一樣升高）」（ㄓㄤˇ）；吸了水體積膨脹、血往臉上充→「泡漲、漲紅」（ㄓㄤˋ）。升高讀三聲，膨脹讀四聲。"},
  {id:"p455",grade:3,word:"朝陽",target:"朝",zhuyin:"ㄓㄠ",pinyin:"zhāo",wz:"ㄓㄠ ㄧㄤˊ",wrong:[{z:"ㄔㄠˊ",p:"cháo"},{z:"ㄓㄠˋ",p:"zhào"}],note:"「朝陽」「朝氣」「朝夕」（早晨）讀ㄓㄠ；「朝代」「上朝」「朝向」讀ㄔㄠˊ。",deep:"1. 注音比較\n朝：ㄓㄠ（一聲）＝朝陽、朝氣、朝令夕改（早晨）；ㄔㄠˊ（二聲）＝朝代、朝廷、朝向；ㄓㄠˋ＝無此音（是「照」的讀音）\n2. 國字拆解與造字原因\n朝：會意字，甲骨文像太陽從草叢間升起、月亮還沒落下，本義是早晨（ㄓㄠ）；臣子一大早去見君王→「上朝、朝拜」，君王處理政事的地方→「朝廷、朝代」（ㄔㄠˊ）。"},
  {id:"p456",grade:3,word:"圓圈",target:"圈",zhuyin:"ㄑㄩㄢ",pinyin:"quān",wz:"ㄩㄢˊ ㄑㄩㄢ",wrong:[{z:"ㄐㄩㄢˋ",p:"juàn"},{z:"ㄑㄩㄢˊ",p:"quán"}],note:"「圓圈」「畫圈」讀ㄑㄩㄢ；「豬圈」「羊圈」（獸欄）讀ㄐㄩㄢˋ。",deep:"1. 注音比較\n圈：ㄑㄩㄢ（一聲）＝圓圈、圈選、圈套；ㄐㄩㄢˋ（四聲）＝豬圈、羊圈（關牲畜的地方）；ㄑㄩㄢˊ＝無此音（是「全」的讀音）\n2. 國字拆解與造字原因\n圈：形聲字，「囗（圍起來）」＋「卷」（聲）。本義是環形、圍起來的形狀→「圓圈」（ㄑㄩㄢ）；圍起來關牲畜的欄舍→「豬圈」（ㄐㄩㄢˋ）。畫的圈讀ㄑㄩㄢ，關動物的圈讀ㄐㄩㄢˋ。"},
  {id:"p457",grade:3,word:"咽喉",target:"咽",zhuyin:"ㄧㄢ",pinyin:"yān",wz:"ㄧㄢ ㄏㄡˊ",wrong:[{z:"ㄧㄝˋ",p:"yè"},{z:"ㄧㄢˋ",p:"yàn"}],note:"「咽喉」（喉嚨）讀ㄧㄢ；「嗚咽」（低聲哭）讀ㄧㄝˋ；「狼吞虎嚥」用「嚥」。",deep:"1. 注音比較\n咽：ㄧㄢ（一聲）＝咽喉、咽炎；ㄧㄝˋ（四聲）＝嗚咽、哽咽（悲傷得說不出話）；ㄧㄢˋ（四聲）＝同「嚥」，吞嚥（吞下去）\n2. 國字拆解與造字原因\n咽：形聲字，「口」＋「因」（聲）。本義是喉嚨這個部位→「咽喉」（ㄧㄢ）；喉嚨哽住、哭聲堵在喉頭→「嗚咽、哽咽」（ㄧㄝˋ）；食物通過喉嚨吞下（後多寫作「嚥」）讀ㄧㄢˋ。部位、哭聲、吞嚥三個音要分清。"},
  {id:"p458",grade:3,word:"調查",target:"調",zhuyin:"ㄉㄧㄠˋ",pinyin:"diào",wz:"ㄉㄧㄠˋ ㄔㄚˊ",wrong:[{z:"ㄊㄧㄠˊ",p:"tiáo"},{z:"ㄓㄠˋ",p:"zhào"}],note:"「調查」「調動」「聲調」讀ㄉㄧㄠˋ；「調皮」「調整」「調味」讀ㄊㄧㄠˊ。",deep:"1. 注音比較\n調：ㄉㄧㄠˋ（四聲）＝調查、調動、曲調；ㄊㄧㄠˊ（二聲）＝調皮、調整、風調雨順；ㄓㄠˋ＝無此音（是「照」的讀音）\n2. 國字拆解與造字原因\n調：形聲字，「言」＋「周」（聲）。本義是言語和諧、使均勻協調→「調整、調味、調解」（ㄊㄧㄠˊ）；另一路意思是徵集、更動、查考→「調動、調查」，音樂的高低配置→「曲調、聲調」（ㄉㄧㄠˋ）。"},
  {id:"p459",grade:3,word:"挑水",target:"挑",zhuyin:"ㄊㄧㄠ",pinyin:"tiāo",wz:"ㄊㄧㄠ ㄕㄨㄟˇ",wrong:[{z:"ㄊㄧㄠˇ",p:"tiǎo"},{z:"ㄊㄧㄠˋ",p:"tiào"}],note:"「挑水」「挑選」「挑食」讀ㄊㄧㄠ；「挑戰」「挑撥」「挑燈」讀ㄊㄧㄠˇ。",deep:"1. 注音比較\n挑：ㄊㄧㄠ（一聲）＝挑水、挑選、挑食；ㄊㄧㄠˇ（三聲）＝挑戰、挑撥、挑燈夜戰；ㄊㄧㄠˋ＝無此音（是「跳」的讀音）\n2. 國字拆解與造字原因\n挑：形聲字，「扌（手）」＋「兆」（聲）。用肩擔物、用手揀選→「挑水、挑選」（ㄊㄧㄠ）；用長物往上撥、引動→「挑燈（把燈芯撥高）、挑起爭端、挑戰」（ㄊㄧㄠˇ）。擔與選讀一聲，撥與惹讀三聲。"},
  {id:"p460",grade:3,word:"暈倒",target:"暈",zhuyin:"ㄩㄣ",pinyin:"yūn",wz:"ㄩㄣ ㄉㄠˇ",wrong:[{z:"ㄩㄣˋ",p:"yùn"},{z:"ㄏㄨㄣ",p:"hūn"}],note:"「暈倒」「頭暈」讀ㄩㄣ；「暈車」「暈船」「月暈」讀ㄩㄣˋ。",deep:"1. 注音比較\n暈：ㄩㄣ（一聲）＝暈倒、頭暈、暈頭轉向；ㄩㄣˋ（四聲）＝暈車、暈船、月暈、燈暈；ㄏㄨㄣ＝無此音（是「昏」的讀音，意思相近特別容易寫錯讀錯）\n2. 國字拆解與造字原因\n暈：從「日」，本義是太陽、月亮周圍的光圈→「日暈、月暈」（ㄩㄣˋ），坐車坐船引起的不適感也讀ㄩㄣˋ；頭腦昏沉、失去知覺→「頭暈、暈倒」（ㄩㄣ）。光圈與暈車讀四聲，昏沉讀一聲。"},
  {id:"p461",grade:4,word:"喝采",target:"喝",zhuyin:"ㄏㄜˋ",pinyin:"hè",wz:"ㄏㄜˋ ㄘㄞˇ",wrong:[{z:"ㄏㄜ",p:"hē"},{z:"ㄏㄚ",p:"hā"}],note:"「喝采」「吆喝」（大聲喊）讀ㄏㄜˋ；「喝水」「喝茶」讀ㄏㄜ。",deep:"1. 注音比較\n喝：ㄏㄜˋ（四聲）＝喝采、吆喝、大喝一聲；ㄏㄜ（一聲）＝喝水、喝茶、喝湯；ㄏㄚ＝無此音（是「哈」的讀音）\n2. 國字拆解與造字原因\n喝：形聲字，「口」＋「曷」（聲）。用口的動作有兩路：把液體吞進口中→「喝水」（ㄏㄜ）；放大聲量呼喊→「喝采、喝令、當頭棒喝」（ㄏㄜˋ）。飲用讀一聲，喊叫讀四聲。"},
  {id:"p462",grade:4,word:"結巴",target:"結",zhuyin:"ㄐㄧㄝ",pinyin:"jiē",wz:"ㄐㄧㄝ ㄅㄚ",wrong:[{z:"ㄐㄧㄝˊ",p:"jié"},{z:"ㄐㄧㄚˊ",p:"jiá"}],note:"「結巴」「結實（堅固）」讀ㄐㄧㄝ；「結束」「打結」「結果」讀ㄐㄧㄝˊ。",deep:"1. 注音比較\n結：ㄐㄧㄝ（一聲）＝結巴、結實（堅固牢靠）；ㄐㄧㄝˊ（二聲）＝結束、打結、團結；ㄐㄧㄚˊ＝無此音（是「夾」的讀音）\n2. 國字拆解與造字原因\n結：形聲字，「糸（絲線）」＋「吉」（聲）。本義是把繩線打成結→「打結、結繩」（ㄐㄧㄝˊ），引申為聚合、收尾（團結、結束）；口語形容說話卡住不順（結巴）、東西紮實牢靠（結實）時讀ㄐㄧㄝ。"},
  {id:"p463",grade:4,word:"縫隙",target:"縫",zhuyin:"ㄈㄥˋ",pinyin:"fèng",wz:"ㄈㄥˋ ㄒㄧˋ",wrong:[{z:"ㄈㄥˊ",p:"féng"},{z:"ㄈㄥ",p:"fēng"}],note:"「縫隙」「門縫」（裂縫，名詞）讀ㄈㄥˋ；「縫衣服」「縫補」（動作）讀ㄈㄥˊ。",deep:"1. 注音比較\n縫：ㄈㄥˋ（四聲）＝縫隙、門縫、裂縫；ㄈㄥˊ（二聲）＝縫衣服、縫補、縫紉；ㄈㄥ＝無此音（是「風」的讀音）\n2. 國字拆解與造字原因\n縫：形聲字，「糸（絲線）」＋「逢」（聲）。用針線把布連起來的動作→「縫補」（ㄈㄥˊ）；兩塊布相接的地方會留下一道細線＝接合處的細長空隙→「縫隙」（ㄈㄥˋ）。動詞二聲、名詞四聲。"},
  {id:"p464",grade:4,word:"納悶",target:"悶",zhuyin:"ㄇㄣˋ",pinyin:"mèn",wz:"ㄋㄚˋ ㄇㄣˋ",wrong:[{z:"ㄇㄣ",p:"mēn"},{z:"ㄇㄟˋ",p:"mèi"}],note:"「納悶」「苦悶」「悶悶不樂」讀ㄇㄣˋ；「悶熱」「悶不吭聲」讀ㄇㄣ。",deep:"1. 注音比較\n悶：ㄇㄣˋ（四聲）＝納悶、苦悶、悶悶不樂（心情鬱結）；ㄇㄣ（一聲）＝悶熱、悶著頭、悶不吭聲（不透氣）；ㄇㄟˋ＝無此音（是「妹」的讀音）\n2. 國字拆解與造字原因\n悶：會意兼形聲，「心」被關在「門」裡。空氣被關住不流通→「悶熱、悶壞了」（ㄇㄣ）；心被關住透不出來→「苦悶、納悶（心裡疑惑解不開）」（ㄇㄣˋ）。環境不透氣讀一聲，心裡不痛快讀四聲。"},
  {id:"p465",grade:4,word:"鞭炮",target:"炮",zhuyin:"ㄆㄠˋ",pinyin:"pào",wz:"ㄅㄧㄢ ㄆㄠˋ",wrong:[{z:"ㄆㄠˊ",p:"páo"},{z:"ㄅㄠˋ",p:"bào"}],note:"「鞭炮」「大炮」讀ㄆㄠˋ；「炮製」「炮烙」（古代火烤）讀ㄆㄠˊ。",deep:"1. 注音比較\n炮：ㄆㄠˋ（四聲）＝鞭炮、大炮、炮火；ㄆㄠˊ（二聲）＝炮製、炮烙、如法炮製；ㄅㄠˋ＝無此音（「爆」才讀ㄅㄠˋ，爆竹＝鞭炮，兩字易混）\n2. 國字拆解與造字原因\n炮：形聲字，「火」＋「包」（聲）。本義是把食物包起來放在火上烤→「炮製藥材、炮烙」（ㄆㄠˊ）；後來借指火器、爆裂物→「大炮、鞭炮」（ㄆㄠˋ）。古法烤製讀二聲，火器讀四聲。"},
  {id:"p466",grade:4,word:"漂流",target:"漂",zhuyin:"ㄆㄧㄠ",pinyin:"piāo",wz:"ㄆㄧㄠ ㄌㄧㄡˊ",wrong:[{z:"ㄆㄧㄠˋ",p:"piào"},{z:"ㄆㄧㄠˇ",p:"piǎo"}],note:"「漂流」「漂浮」讀ㄆㄧㄠ；「漂亮」讀ㄆㄧㄠˋ；「漂白」讀ㄆㄧㄠˇ。",deep:"1. 注音比較\n漂：ㄆㄧㄠ（一聲）＝漂流、漂浮、漂泊；ㄆㄧㄠˇ（三聲）＝漂白、漂洗；ㄆㄧㄠˋ（四聲）＝漂亮\n2. 國字拆解與造字原因\n漂：形聲字，「氵（水）」＋「票」（聲）。本義是浮在水面隨水移動→「漂流」（ㄆㄧㄠ）；把衣物放在水裡沖洗、使變白→「漂白、漂洗」（ㄆㄧㄠˇ）；洗得乾乾淨淨、好看→「漂亮」（ㄆㄧㄠˋ）。三個音是「浮水→水洗→潔美」的引申。"},
  {id:"p467",grade:4,word:"湖泊",target:"泊",zhuyin:"ㄅㄛˊ",pinyin:"bó",wz:"ㄏㄨˊ ㄅㄛˊ",wrong:[{z:"ㄆㄛˋ",p:"pò"},{z:"ㄅㄞˊ",p:"bái"}],note:"教育部審訂音「泊」一律讀ㄅㄛˊ：湖泊、停泊、漂泊、淡泊、梁山泊都讀ㄅㄛˊ。",deep:"1. 注音比較\n泊：ㄅㄛˊ（二聲）＝湖泊、停泊、漂泊、淡泊名利、梁山泊，教育部辭典所有詞例都讀這個音；ㄆㄛˋ＝ㄅㄛˊ的又音，一般不用；ㄅㄞˊ＝是聲符「白」自己的讀音，「泊」不讀這個音\n2. 國字拆解與造字原因\n泊：形聲字，「氵（水）」＋「白」（聲）。船靠岸停住→「泊舟、停泊」，漂流不定→「漂泊」，一大片積水的湖沼→「湖泊」，恬靜不貪求→「淡泊」。四個意思都讀ㄅㄛˊ，不必分讀音。"},
  {id:"p468",grade:4,word:"投奔",target:"奔",zhuyin:"ㄅㄣ",pinyin:"bēn",wz:"ㄊㄡˊ ㄅㄣ",wrong:[{z:"ㄅㄣˋ",p:"bèn"},{z:"ㄆㄣˊ",p:"pén"}],note:"教育部審訂音「奔」只有一個讀音ㄅㄣ：奔跑、投奔、私奔都讀ㄅㄣ。",deep:"1. 注音比較\n奔：ㄅㄣ＝奔跑、狂奔、奔馳、出奔、私奔、投奔。★教育部《國語辭典簡編本》「奔」只收一聲ㄅㄣ，讀成四聲ㄅㄣˋ不是現行審訂音\n2. 國字拆解與造字原因\n奔：會意字，上面是甩開手臂的人（大），下面原是三個「止」（腳），很多腳步就是快跑。往某個地方投靠也是跑過去，所以「投奔」同樣讀ㄅㄣ。"},
  {id:"p469",grade:4,word:"占卜",target:"占",zhuyin:"ㄓㄢ",pinyin:"zhān",wz:"ㄓㄢ ㄅㄨˇ",wrong:[{z:"ㄓㄢˋ",p:"zhàn"},{z:"ㄉㄧㄢˋ",p:"diàn"}],note:"「占卜」「占卦」讀ㄓㄢ；「占領」「占用」「攻占」讀ㄓㄢˋ。",deep:"1. 注音比較\n占：ㄓㄢ（一聲）＝占卜、占卦、占星；ㄓㄢˋ（四聲）＝占領、占用、獨占；ㄉㄧㄢˋ＝無此音（是「店」的讀音，同聲符）\n2. 國字拆解與造字原因\n占：會意字，「卜」＋「口」，看著龜甲上的裂紋（卜）用口說出吉凶，本義是占卜（ㄓㄢ）；後來借用表「據為己有」→「占領、霸占」（ㄓㄢˋ）。問卜讀一聲，奪取讀四聲。"},
  {id:"p470",grade:4,word:"團團轉",target:"轉",zhuyin:"ㄓㄨㄢˋ",pinyin:"zhuàn",wz:"ㄊㄨㄢˊ ㄊㄨㄢˊ ㄓㄨㄢˋ",wrong:[{z:"ㄓㄨㄢˇ",p:"zhuǎn"},{z:"ㄔㄨㄢˊ",p:"chuán"}],note:"「團團轉」「轉圈」（繞圈）讀ㄓㄨㄢˋ；「轉彎」「轉學」「旋轉」讀ㄓㄨㄢˇ。",deep:"1. 注音比較\n轉：ㄓㄨㄢˋ（四聲）＝團團轉、轉圈子、地球自轉一圈（繞著圈子轉動）；ㄓㄨㄢˇ（三聲）＝轉彎、轉身、轉學（改變方向）；ㄔㄨㄢˊ＝無此音（是「傳」的讀音）\n2. 國字拆解與造字原因\n轉：形聲字，「車」＋「專」（聲）。本義是車輪迴旋。改變方向、中途變換→「轉彎、轉變、轉告」（ㄓㄨㄢˇ）；繞著圈子旋動→「轉圈、團團轉」（ㄓㄨㄢˋ）。變向讀三聲，繞圈讀四聲。"},
  {id:"p471",grade:4,word:"噴香",target:"噴",zhuyin:"ㄆㄣˋ",pinyin:"pèn",wz:"ㄆㄣˋ ㄒㄧㄤ",wrong:[{z:"ㄆㄣ",p:"pēn"},{z:"ㄈㄣ",p:"fēn"}],note:"「噴香」「噴鼻」（香氣濃）讀ㄆㄣˋ；「噴水」「噴嚏」讀ㄆㄣ。",deep:"1. 注音比較\n噴：ㄆㄣˋ（四聲）＝噴香、香氣噴鼻；ㄆㄣ（一聲）＝噴水、噴泉、打噴嚏；ㄈㄣ＝無此音（是「芬」的讀音，「芬芳」與「噴香」意近更易混）\n2. 國字拆解與造字原因\n噴：形聲字，「口」＋「賁」（聲）。本義是液體、氣體用力射出→「噴水、噴出」（ㄆㄣ）；香味濃得像用力撲向鼻子→「噴香」（ㄆㄣˋ）。動作讀一聲，形容香氣撲鼻讀四聲。"},
  {id:"p472",grade:4,word:"刨冰",target:"刨",zhuyin:"ㄅㄠˋ",pinyin:"bào",wz:"ㄅㄠˋ ㄅㄧㄥ",wrong:[{z:"ㄆㄠˊ",p:"páo"},{z:"ㄅㄠ",p:"bāo"}],note:"「刨冰」「刨刀」（削刮）讀ㄅㄠˋ；「刨土」「刨根問底」（挖掘）讀ㄆㄠˊ。",deep:"1. 注音比較\n刨：ㄅㄠˋ（四聲）＝刨冰、刨刀、刨木頭（用刀具削刮）；ㄆㄠˊ（二聲）＝刨土、刨坑、刨根問底（挖掘）；ㄅㄠ＝無此音（是「包」的讀音）\n2. 國字拆解與造字原因\n刨：形聲字，「刀」＋「包」（聲）。用刀具把表面一層層削下來→「刨木、刨冰（把冰削成細片）」（ㄅㄠˋ）；用手或工具往下挖→「刨土、刨根」（ㄆㄠˊ）。削刮讀四聲，挖掘讀二聲。"},
  {id:"p473",grade:4,word:"蛤蟆",target:"蛤",zhuyin:"ㄏㄚˊ",pinyin:"há",wz:"ㄏㄚˊ ˙ㄇㄚ",wrong:[{z:"ㄍㄜˊ",p:"gé"},{z:"ㄏㄚˇ",p:"hǎ"}],note:"「蛤蟆」（蛙類）讀ㄏㄚˊ；「蛤蜊」「文蛤」（貝類）讀ㄍㄜˊ。",deep:"1. 注音比較\n蛤：ㄏㄚˊ（二聲）＝蛤蟆（青蛙、蟾蜍一類）；ㄍㄜˊ（二聲）＝蛤蜊、文蛤、蛤仔（貝類）；ㄏㄚˇ＝無此音（「哈巴狗」的「哈」才讀ㄏㄚˇ）\n2. 國字拆解與造字原因\n蛤：形聲字，「虫」＋「合」（聲）。貝殼兩片「合」起來的水中生物→「蛤蜊」（ㄍㄜˊ）；「蛤蟆」是連綿詞，專指蛙類，讀ㄏㄚˊ。看到「蟆」就讀ㄏㄚˊ，看到「蜊」就讀ㄍㄜˊ。"},
  {id:"p474",grade:4,word:"寶藏",target:"藏",zhuyin:"ㄗㄤˋ",pinyin:"zàng",wz:"ㄅㄠˇ ㄗㄤˋ",wrong:[{z:"ㄘㄤˊ",p:"cáng"},{z:"ㄗㄤ",p:"zāng"}],note:"「寶藏」「藏經」「西藏」讀ㄗㄤˋ；「躲藏」「收藏」讀ㄘㄤˊ。",deep:"1. 注音比較\n藏：ㄗㄤˋ（四聲）＝寶藏、藏經樓、西藏；ㄘㄤˊ（二聲）＝躲藏、收藏、捉迷藏；ㄗㄤ＝無此音（是「贓」的讀音）\n2. 國字拆解與造字原因\n藏：形聲字，「艹」＋「臧」（聲）。把東西收起來不讓人看見→「躲藏、收藏」（ㄘㄤˊ）；收起來的珍貴東西、儲存的地方→「寶藏、藏書樓」（ㄗㄤˋ）。動詞讀ㄘㄤˊ，名詞讀ㄗㄤˋ。"},
  {id:"p475",grade:4,word:"扇風",target:"扇",zhuyin:"ㄕㄢ",pinyin:"shān",wz:"ㄕㄢ ㄈㄥ",wrong:[{z:"ㄕㄢˋ",p:"shàn"},{z:"ㄕㄢˇ",p:"shǎn"}],note:"「扇風」「扇動翅膀」（動作）讀ㄕㄢ；「扇子」「電扇」（名詞）讀ㄕㄢˋ。",deep:"1. 注音比較\n扇：ㄕㄢ（一聲）＝扇風、扇動翅膀、扇爐火；ㄕㄢˋ（四聲）＝扇子、電扇、一扇門；ㄕㄢˇ＝無此音（是「閃」的讀音）\n2. 國字拆解與造字原因\n扇：會意字，「戶」（門）＋「羽」（翅膀），門像鳥翅一樣開合，本義是門扇，引申為搧風用具→「扇子、門扇」（ㄕㄢˋ）；拿扇子搧動生風的動作→「扇風、扇動」（ㄕㄢ）。名詞四聲、動詞一聲。"},
  {id:"p476",grade:5,word:"雪茄",target:"茄",zhuyin:"ㄐㄧㄚ",pinyin:"jiā",wz:"ㄒㄩㄝˇ ㄐㄧㄚ",wrong:[{z:"ㄑㄧㄝˊ",p:"qié"},{z:"ㄐㄧㄚˊ",p:"jiá"}],note:"「雪茄」讀ㄐㄧㄚ；「茄子」「番茄」讀ㄑㄧㄝˊ。",deep:"1. 注音比較\n茄：ㄐㄧㄚ（一聲）＝雪茄（外來語音譯）；ㄑㄧㄝˊ（二聲）＝茄子、番茄、茄苳；ㄐㄧㄚˊ＝無此音（是「夾」的讀音）\n2. 國字拆解與造字原因\n茄：形聲字，「艹」＋「加」（聲）。本義是植物，指茄子（ㄑㄧㄝˊ）；「雪茄」是英語 cigar 的音譯詞，借「茄」字取其近似音，讀本來的聲符音ㄐㄧㄚ。植物讀ㄑㄧㄝˊ，音譯詞讀ㄐㄧㄚ。"},
  {id:"p477",grade:5,word:"哄堂大笑",target:"哄",zhuyin:"ㄏㄨㄥ",pinyin:"hōng",wz:"ㄏㄨㄥ ㄊㄤˊ ㄉㄚˋ ㄒㄧㄠˋ",wrong:[{z:"ㄏㄨㄥˇ",p:"hǒng"},{z:"ㄏㄨㄥˋ",p:"hòng"}],note:"「哄堂大笑」「哄動」讀ㄏㄨㄥ；「哄騙」「哄小孩」讀ㄏㄨㄥˇ；「起鬨」的「鬨」讀ㄏㄨㄥˋ。",deep:"1. 注音比較\n哄：ㄏㄨㄥ（一聲）＝哄堂大笑、哄動一時（許多人同時出聲）；ㄏㄨㄥˇ（三聲）＝哄騙、哄小孩（用話語逗、騙）；ㄏㄨㄥˋ（四聲）＝一哄而散（吵鬧，同「鬨」）\n2. 國字拆解與造字原因\n哄：形聲字，「口」＋「共」（聲）。「共」有大家一起的意思：眾人一起發出聲音→「哄堂大笑」（ㄏㄨㄥ）；用好聽的話哄逗一個人→「哄小孩」（ㄏㄨㄥˇ）；眾人吵鬧起鬨→「一哄而散」（ㄏㄨㄥˋ）。"},
  {id:"p478",grade:5,word:"綠林好漢",target:"綠",zhuyin:"ㄌㄩˋ",pinyin:"lǜ",wz:"ㄌㄩˋ ㄌㄧㄣˊ ㄏㄠˇ ㄏㄢˋ",wrong:[{z:"ㄌㄨˋ",p:"lù"},{z:"ㄌㄨˊ",p:"lú"}],note:"教育部審訂音「綠」只有一個讀音ㄌㄩˋ，「綠林好漢」也讀ㄌㄩˋ。",deep:"1. 注音比較\n綠：ㄌㄩˋ＝綠林好漢、綠色、墨綠、紅花綠葉、綠意盎然。★教育部《國語辭典簡編本》「綠」只收ㄌㄩˋ一音，「綠林」讀ㄌㄨˋ是舊讀，已非現行審訂音\n2. 國字拆解與造字原因\n綠：形聲字，「糸（絲）」＋「彔」（聲），本義是青黃色的絲帛，後泛指綠色。「綠林」原是西漢的綠林山（在今湖北），飢民聚集山中起事，後世就用「綠林好漢」稱聚眾山林、劫富濟貧的人。"},
  {id:"p479",grade:5,word:"效率",target:"率",zhuyin:"ㄌㄩˋ",pinyin:"lǜ",wz:"ㄒㄧㄠˋ ㄌㄩˋ",wrong:[{z:"ㄕㄨㄞˋ",p:"shuài"},{z:"ㄌㄩˇ",p:"lǚ"}],note:"「效率」「機率」「利率」（比值）讀ㄌㄩˋ；「率領」「坦率」讀ㄕㄨㄞˋ。",deep:"1. 注音比較\n率：ㄌㄩˋ（四聲）＝效率、機率、比率（數學比值）；ㄕㄨㄞˋ（四聲）＝率領、坦率、輕率；ㄌㄩˇ＝無此音（是「旅」的讀音）\n2. 國字拆解與造字原因\n率：象形字，像捕鳥的網，本義是網羅、帶領→「率領」，帶頭的人性情直接→「直率、坦率」（ㄕㄨㄞˋ）；數學借它表示兩數相比的值→「效率、機率」（ㄌㄩˋ）。帶領讀ㄕㄨㄞˋ，比值讀ㄌㄩˋ。"},
  {id:"p480",grade:5,word:"曾祖父",target:"曾",zhuyin:"ㄗㄥ",pinyin:"zēng",wz:"ㄗㄥ ㄗㄨˇ ㄈㄨˋ",wrong:[{z:"ㄘㄥˊ",p:"céng"},{z:"ㄗㄥˋ",p:"zèng"}],note:"「曾祖父」「曾孫」（隔兩代的親屬）讀ㄗㄥ；「曾經」「未曾」讀ㄘㄥˊ。",deep:"1. 注音比較\n曾：ㄗㄥ（一聲）＝曾祖父、曾孫（隔兩代的親屬）、姓氏（曾子）；ㄘㄥˊ（二聲）＝曾經、未曾、何曾；ㄗㄥˋ＝無此音（是「贈」的讀音，同聲符）\n2. 國字拆解與造字原因\n曾：象形字，像蒸食物的炊具（甑的本字），蒸氣層層上冒。層層相隔→隔兩代的親屬「曾祖、曾孫」（ㄗㄥ）；「曾經」表示經歷過（時間上隔了一層）讀ㄘㄥˊ。親屬與姓氏讀ㄗㄥ，副詞讀ㄘㄥˊ。"},
  {id:"p481",grade:5,word:"人參",target:"參",zhuyin:"ㄕㄣ",pinyin:"shēn",wz:"ㄖㄣˊ ㄕㄣ",wrong:[{z:"ㄘㄢ",p:"cān"},{z:"ㄘㄣ",p:"cēn"}],note:"「人參」「海參」讀ㄕㄣ；「參加」「參觀」讀ㄘㄢ；「參差不齊」讀ㄘㄣ。",deep:"1. 注音比較\n參：ㄕㄣ（一聲）＝人參、海參、參商（星宿名）；ㄘㄢ（一聲）＝參加、參觀、參考；ㄘㄣ（一聲）＝參差不齊\n2. 國字拆解與造字原因\n參：甲骨文像人頭上有三顆星，本義是參星（星宿名，ㄕㄣ），藥材人參形似人也用此音；「加入其中」→「參加、參與」（ㄘㄢ）；長短不齊的樣子→「參差」（ㄘㄣ）。一字三音：藥材星宿ㄕㄣ、加入ㄘㄢ、不齊ㄘㄣ。"},
  {id:"p482",grade:5,word:"模樣",target:"模",zhuyin:"ㄇㄛˊ",pinyin:"mó",wz:"ㄇㄛˊ ㄧㄤˋ",wrong:[{z:"ㄇㄨˊ",p:"mú"},{z:"ㄇㄨˇ",p:"mǔ"}],note:"教育部審訂音「模」只有一個讀音ㄇㄛˊ：模樣、模範、模仿都讀ㄇㄛˊ。",deep:"1. 注音比較\n模：ㄇㄛˊ＝模樣、模範、楷模、模仿、模擬。★教育部《國語辭典簡編本》「模」只收ㄇㄛˊ一音，「模樣」讀ㄇㄨˊ是口語音，不是審訂音\n2. 國字拆解與造字原因\n模：形聲字，「木」＋「莫」（聲）。本義是鑄造器物用的木製模型，照著它做就會一樣→「模仿、模範」；一個人的外形長相也像照模子做出來的→「模樣」。"},
  {id:"p483",grade:5,word:"抹布",target:"抹",zhuyin:"ㄇㄛˇ",pinyin:"mǒ",wz:"ㄇㄛˇ ㄅㄨˋ",wrong:[{z:"ㄇㄚ",p:"mā"},{z:"ㄇㄛˋ",p:"mò"}],note:"教育部審訂音「抹布」的「抹」讀ㄇㄛˇ；「抹牆」「拐彎抹角」才讀ㄇㄛˋ。",deep:"1. 注音比較\n抹：ㄇㄛˇ＝抹布、抹桌子、塗抹、抹眼淚、抹粉、抹殺；ㄇㄛˋ＝抹牆、抹平、拐彎抹角。★「抹布」教育部審訂音讀ㄇㄛˇ ㄅㄨˋ，讀成ㄇㄚ不是審訂音\n2. 國字拆解與造字原因\n抹：形聲字，「扌（手）」＋「末」（聲）。手在表面來回移動：塗上或擦掉一層→「塗抹、抹布」（ㄇㄛˇ）；用泥塗牆、貼著邊繞→「抹牆、拐彎抹角」（ㄇㄛˋ）。"},
  {id:"p484",grade:5,word:"巷弄",target:"弄",zhuyin:"ㄌㄨㄥˋ",pinyin:"lòng",wz:"ㄒㄧㄤˋ ㄌㄨㄥˋ",wrong:[{z:"ㄋㄨㄥˋ",p:"nòng"},{z:"ㄌㄨㄥˊ",p:"lóng"}],note:"「巷弄」「弄堂」（小巷）讀ㄌㄨㄥˋ；「玩弄」「弄壞」讀ㄋㄨㄥˋ。",deep:"1. 注音比較\n弄：ㄌㄨㄥˋ（四聲）＝巷弄、弄堂、三十五巷八弄（小巷）；ㄋㄨㄥˋ（四聲）＝玩弄、弄壞、捉弄；ㄌㄨㄥˊ＝無此音（是「龍」的讀音）\n2. 國字拆解與造字原因\n弄：會意字，雙手（廾）捧著玉把玩，本義是玩賞→「玩弄、擺弄、弄清楚」（ㄋㄨㄥˋ）；江南方言把小巷稱作「弄」→「巷弄、弄堂」（ㄌㄨㄥˋ）。動作讀ㄋㄨㄥˋ，小巷讀ㄌㄨㄥˋ。"},
  {id:"p485",grade:5,word:"提防",target:"提",zhuyin:"ㄊㄧˊ",pinyin:"tí",wz:"ㄊㄧˊ ㄈㄤˊ",wrong:[{z:"ㄉㄧ",p:"dī"},{z:"ㄉㄧˋ",p:"dì"}],note:"教育部審訂音「提防」的「提」讀ㄊㄧˊ，和提高、提前同音。",deep:"1. 注音比較\n提：ㄊㄧˊ＝提防、提高、提前、提早、提款、提名、提議；ㄕˊ＝提防之外的古語用法（如「朱提」地名）。★「提防」教育部審訂音讀ㄊㄧˊ ㄈㄤˊ，讀成ㄉㄧ是口語音，不是審訂音\n2. 國字拆解與造字原因\n提：形聲字，「扌（手）」＋「是」（聲）。本義是用手懸空拿著→「提水、提袋」，引申為舉出、使升高→「提問、提高」；把心「提」起來留意防備就是「提防」。"},
  {id:"p486",grade:5,word:"散文",target:"散",zhuyin:"ㄙㄢˇ",pinyin:"sǎn",wz:"ㄙㄢˇ ㄨㄣˊ",wrong:[{z:"ㄙㄢˋ",p:"sàn"},{z:"ㄕㄢˇ",p:"shǎn"}],note:"「散文」「散裝」「鬆散」讀ㄙㄢˇ；「解散」「散步」「散播」讀ㄙㄢˋ。",deep:"1. 注音比較\n散：ㄙㄢˇ（三聲）＝散文、散裝、鬆散（零散不集中的狀態）；ㄙㄢˋ（四聲）＝解散、散步、散布（分開的動作）；ㄕㄢˇ＝無此音（是「閃」的讀音）\n2. 國字拆解與造字原因\n散：會意字，手持器具（攵）把麻莖打散。使聚在一起的東西分開（動作）→「解散、驅散、散會」（ㄙㄢˋ）；不受拘束、零零星星的狀態→「散文（不講格律的文章）、散沙」（ㄙㄢˇ）。狀態三聲、動作四聲。"},
  {id:"p487",grade:5,word:"盛飯",target:"盛",zhuyin:"ㄔㄥˊ",pinyin:"chéng",wz:"ㄔㄥˊ ㄈㄢˋ",wrong:[{z:"ㄕㄥˋ",p:"shèng"},{z:"ㄔㄥˋ",p:"chèng"}],note:"「盛飯」「盛湯」（裝取）讀ㄔㄥˊ；「茂盛」「盛大」「盛開」讀ㄕㄥˋ。",deep:"1. 注音比較\n盛：ㄔㄥˊ（二聲）＝盛飯、盛湯（把食物裝進容器）；ㄕㄥˋ（四聲）＝茂盛、盛大、盛況空前；ㄔㄥˋ＝無此音（是「秤」的讀音）\n2. 國字拆解與造字原因\n盛：形聲字，「皿（器皿）」＋「成」（聲）。本義是把穀物裝進祭祀的器皿→「盛飯、盛湯」（ㄔㄥˊ）；祭品裝得滿滿的→引申為豐富、興旺→「盛大、茂盛、強盛」（ㄕㄥˋ）。裝取讀ㄔㄥˊ，興旺讀ㄕㄥˋ。"},
  {id:"p488",grade:5,word:"記載",target:"載",zhuyin:"ㄗㄞˋ",pinyin:"zài",wz:"ㄐㄧˋ ㄗㄞˋ",wrong:[{z:"ㄗㄞˇ",p:"zǎi"},{z:"ㄗㄞ",p:"zāi"}],note:"教育部審訂音「記載」的「載」讀ㄗㄞˋ；「千載難逢」（年）才讀ㄗㄞˇ。",deep:"1. 注音比較\n載：ㄗㄞˋ＝記載、刊載、轉載、載人、載貨、載歌載舞、怨聲載道；ㄗㄞˇ＝一年半載、三年五載、千載難逢（都指「年」）。★「記載」教育部審訂音讀ㄐㄧˋ ㄗㄞˋ，讀成ㄗㄞˇ不是審訂音\n2. 國字拆解與造字原因\n載：形聲字，「車」＋「𢦏」（聲）。本義是用車裝運→「載運、載客」；把事情「裝」進文字保存下來也是載→「記載、刊載」，這些都讀ㄗㄞˋ。只有借指「年」時讀ㄗㄞˇ。"},
  {id:"p489",grade:5,word:"鑽石",target:"鑽",zhuyin:"ㄗㄨㄢˋ",pinyin:"zuàn",wz:"ㄗㄨㄢˋ ㄕˊ",wrong:[{z:"ㄗㄨㄢ",p:"zuān"},{z:"ㄘㄨㄢˋ",p:"cuàn"}],note:"「鑽石」「電鑽」（名詞）讀ㄗㄨㄢˋ；「鑽洞」「鑽研」（動作）讀ㄗㄨㄢ。",deep:"1. 注音比較\n鑽：ㄗㄨㄢˋ（四聲）＝鑽石、電鑽、鑽戒（工具、寶石）；ㄗㄨㄢ（一聲）＝鑽洞、鑽研、鑽牛角尖（穿透）；ㄘㄨㄢˋ＝無此音（是「竄」的讀音）\n2. 國字拆解與造字原因\n鑽：形聲字，「金」＋「贊」（聲）。用金屬工具穿孔的動作→「鑽洞、鑽研（深入研究）」（ㄗㄨㄢ）；穿孔用的工具、硬度最高能鑽穿他物的寶石→「電鑽、鑽石」（ㄗㄨㄢˋ）。動詞一聲、名詞四聲。"},
  {id:"p490",grade:5,word:"似的",target:"似",zhuyin:"ㄙˋ",pinyin:"sì",wz:"ㄙˋ ˙ㄉㄜ",wrong:[{z:"ㄕˋ",p:"shì"},{z:"ㄕˊ",p:"shí"}],note:"教育部審訂音「似」只有一個讀音ㄙˋ：相似、類似、似的都讀ㄙˋ。",deep:"1. 注音比較\n似：ㄙˋ＝似的、相似、類似、光陰似箭、似曾相識。★教育部《國語辭典簡編本》「似」只收ㄙˋ一音，「似的」讀ㄕˋ是口語音，不是審訂音\n2. 國字拆解與造字原因\n似：形聲字，「亻（人）」＋「以」（聲），本義是像、相像。接在名詞後表示比喻（像～一樣）就是「～似的」，例如「他木頭似的站著」。"},
  {id:"p491",grade:6,word:"掙扎",target:"扎",zhuyin:"ㄓㄚˊ",pinyin:"zhá",wz:"ㄓㄥ ㄓㄚˊ",wrong:[{z:"ㄓㄚ",p:"zhā"},{z:"ㄓㄚˋ",p:"zhà"}],note:"「掙扎」讀ㄓㄚˊ；「扎針」「駐扎」的「扎」讀ㄓㄚ。",deep:"1. 注音比較\n扎：ㄓㄚˊ（二聲）＝掙扎；ㄓㄚ（一聲）＝扎針、扎根、駐扎；ㄓㄚˋ＝無此音（是「炸」的讀音）\n2. 國字拆解與造字原因\n扎：形聲字，「扌（手）」＋「乚」。本義是刺入→「扎針、扎根」（ㄓㄚ)；「掙扎」是連綿詞，形容用力支撐擺脫的樣子，「扎」在這裡讀ㄓㄚˊ。單用多讀ㄓㄚ，「掙扎」一詞讀ㄓㄚˊ。"},
  {id:"p492",grade:6,word:"喪事",target:"喪",zhuyin:"ㄙㄤ",pinyin:"sāng",wz:"ㄙㄤ ㄕˋ",wrong:[{z:"ㄙㄤˋ",p:"sàng"},{z:"ㄕㄤ",p:"shāng"}],note:"「喪事」「喪禮」「奔喪」讀ㄙㄤ；「喪失」「沮喪」「喪氣」讀ㄙㄤˋ。",deep:"1. 注音比較\n喪：ㄙㄤ（一聲）＝喪事、喪禮、治喪（與死亡儀式相關）；ㄙㄤˋ（四聲）＝喪失、沮喪、聞風喪膽（失去）；ㄕㄤ＝無此音（是「傷」的讀音）\n2. 國字拆解與造字原因\n喪：甲骨文從「桑」從多個「口」，眾人在桑樹間啼哭，本義是死亡之事→「喪事、喪禮」（ㄙㄤ）；人死＝失去→「喪失、喪志」（ㄙㄤˋ）。儀式讀一聲，失去讀四聲。"},
  {id:"p493",grade:6,word:"熨斗",target:"熨",zhuyin:"ㄩㄣˋ",pinyin:"yùn",wz:"ㄩㄣˋ ㄉㄡˇ",wrong:[{z:"ㄩˋ",p:"yù"},{z:"ㄨㄣˋ",p:"wèn"}],note:"「熨斗」「熨衣服」讀ㄩㄣˋ；「熨貼」（妥適）讀ㄩˋ。",deep:"1. 注音比較\n熨：ㄩㄣˋ（四聲）＝熨斗、熨衣服（燙平）；ㄩˋ（四聲）＝熨貼（心裡妥適舒坦）；ㄨㄣˋ＝無此音（易受「慰」影響誤讀）\n2. 國字拆解與造字原因\n熨：從「火」，「尉」本身就是手持火具燙平布帛的樣子，加「火」更強調用熱燙平→「熨斗、熨燙」（ㄩㄣˋ）；衣服燙平了服服貼貼，引申為心裡舒坦→「熨貼」（ㄩˋ）。燙衣讀ㄩㄣˋ，妥適讀ㄩˋ。"},
  {id:"p494",grade:6,word:"正月",target:"正",zhuyin:"ㄓㄥ",pinyin:"zhēng",wz:"ㄓㄥ ㄩㄝˋ",wrong:[{z:"ㄓㄥˋ",p:"zhèng"},{z:"ㄓㄤ",p:"zhāng"}],note:"「正月」（農曆一月）讀ㄓㄥ；「正確」「正常」讀ㄓㄥˋ。",deep:"1. 注音比較\n正：ㄓㄥ（一聲）＝正月、新正（農曆一月）；ㄓㄥˋ（四聲）＝正確、正常、公正；ㄓㄤ＝無此音（是「張」的讀音）\n2. 國字拆解與造字原因\n正：會意字，「一」（目標）＋「止」（腳），朝著目標直直走去，本義是不偏不斜（ㄓㄥˋ）。一年的第一個月是歲首之「正」，古時避秦始皇「政」（ㄓㄥˋ）名諱改讀平聲，「正月」讀ㄓㄥ沿用至今。"},
  {id:"p495",grade:6,word:"壓軸",target:"軸",zhuyin:"ㄓㄡˊ",pinyin:"zhóu",wz:"ㄧㄚ ㄓㄡˊ",wrong:[{z:"ㄓㄡˋ",p:"zhòu"},{z:"ㄓㄨˊ",p:"zhú"}],note:"教育部審訂音「軸」只有一個讀音ㄓㄡˊ：車軸、畫軸、壓軸都讀ㄓㄡˊ。",deep:"1. 注音比較\n軸：ㄓㄡˊ＝壓軸、車軸、輪軸、轉軸、畫軸、軸心、一軸山水畫。★教育部《國語辭典簡編本》「軸」只收ㄓㄡˊ一音，「壓軸」讀ㄓㄡˋ不是審訂音\n2. 國字拆解與造字原因\n軸：形聲字，「車」＋「由」（聲），本義是貫穿車輪中心的橫桿。戲班把戲碼寫在卷軸上，倒數第二齣壓在軸子上、由最強的角色演出，就叫「壓軸」。"},
  {id:"p496",grade:6,word:"症結",target:"症",zhuyin:"ㄓㄥˋ",pinyin:"zhèng",wz:"ㄓㄥˋ ㄐㄧㄝˊ",wrong:[{z:"ㄓㄥ",p:"zhēng"},{z:"ㄗㄥ",p:"zēng"}],note:"教育部審訂音「症」只有一個讀音ㄓㄥˋ：症狀、急症、症結都讀ㄓㄥˋ。",deep:"1. 注音比較\n症：ㄓㄥˋ＝症結、症狀、病症、急症、絕症、對症下藥。★教育部《國語辭典簡編本》「症」只收ㄓㄥˋ一音，「症結」讀ㄓㄥ是舊讀（本作「癥」），已非現行審訂音\n2. 國字拆解與造字原因\n症：形聲字，「疒（病）」＋「正」（聲），指疾病表現出來的樣子。「症結」本指腹內結塊、難醫的病根，引申為問題最關鍵、最難解的地方。"},
  {id:"p497",grade:6,word:"磅礴",target:"磅",zhuyin:"ㄆㄤ",pinyin:"pāng",wz:"ㄆㄤ ㄅㄛˊ",wrong:[{z:"ㄆㄤˊ",p:"páng"},{z:"ㄅㄤˋ",p:"bàng"}],note:"教育部審訂音「磅礴」的「磅」讀ㄆㄤ（一聲）；秤重的「磅秤」才讀ㄅㄤˋ。",deep:"1. 注音比較\n磅：ㄆㄤ＝磅礴（氣勢磅礴）；ㄅㄤˋ＝磅秤、磅體重、地磅、過磅。★「磅礴」教育部審訂音讀ㄆㄤ ㄅㄛˊ，讀成二聲ㄆㄤˊ不是審訂音\n2. 國字拆解與造字原因\n磅：形聲字，「石」＋「旁」（聲）。「磅礴」是連綿詞，兩字不能拆開解釋，形容像大石一樣廣大雄渾的氣勢；後來又借作英制重量單位 pound 的音譯，讀ㄅㄤˋ。"},
  {id:"p498",grade:6,word:"害臊",target:"臊",zhuyin:"ㄙㄠˋ",pinyin:"sào",wz:"ㄏㄞˋ ㄙㄠˋ",wrong:[{z:"ㄙㄠ",p:"sāo"},{z:"ㄗㄠˋ",p:"zào"}],note:"「害臊」（害羞）讀ㄙㄠˋ；「腥臊」（腥臭味）讀ㄙㄠ。",deep:"1. 注音比較\n臊：ㄙㄠˋ（四聲）＝害臊、臊得臉紅（難為情）；ㄙㄠ（一聲）＝腥臊、臊味（肉的腥味）；ㄗㄠˋ＝無此音（是「燥」的讀音，形近義遠）\n2. 國字拆解與造字原因\n臊：形聲字，「月（肉）」＋「喿」（聲）。本義是生肉的腥氣→「腥臊」（ㄙㄠ）；人難為情時臉上發熱，像被腥氣燻紅了臉→「害臊」（ㄙㄠˋ）。氣味讀一聲，害羞讀四聲。"},
  {id:"p499",grade:6,word:"廈門",target:"廈",zhuyin:"ㄒㄧㄚˋ",pinyin:"xià",wz:"ㄒㄧㄚˋ ㄇㄣˊ",wrong:[{z:"ㄕㄚˋ",p:"shà"},{z:"ㄒㄧㄚ",p:"xiā"}],note:"「廈門」（地名）讀ㄒㄧㄚˋ；「大廈」「高樓大廈」讀ㄕㄚˋ。",deep:"1. 注音比較\n廈：ㄒㄧㄚˋ（四聲）＝廈門（地名專用）；ㄕㄚˋ（四聲）＝大廈、廣廈（高大的房屋）；ㄒㄧㄚ＝無此音（是「蝦」的讀音）\n2. 國字拆解與造字原因\n廈：形聲字，「广（房屋）」＋「夏」（聲），本義是高大的房子→「大廈」（ㄕㄚˋ）；地名「廈門」相傳因位居「大廈之門」而得名，但地名習慣讀ㄒㄧㄚˋ。一般建築讀ㄕㄚˋ，地名讀ㄒㄧㄚˋ。"},
  {id:"p500",grade:6,word:"煞費苦心",target:"煞",zhuyin:"ㄕㄚˋ",pinyin:"shà",wz:"ㄕㄚˋ ㄈㄟˋ ㄎㄨˇ ㄒㄧㄣ",wrong:[{z:"ㄕㄚ",p:"shā"},{z:"ㄕㄜˋ",p:"shè"}],note:"「煞費苦心」「煞有介事」讀ㄕㄚˋ；「煞車」「煞尾」讀ㄕㄚ。",deep:"1. 注音比較\n煞：ㄕㄚˋ（四聲）＝煞費苦心、煞有介事、凶神惡煞（很、極；凶神）；ㄕㄚ（一聲）＝煞車、煞尾（停止、結束）；ㄕㄜˋ＝無此音（是「設」的讀音）\n2. 國字拆解與造字原因\n煞：從「殳」從「火」，是「殺」的變體字。使停止、收束→「煞車、煞尾」（ㄕㄚ）；當程度副詞「極、很」與凶神之義→「煞費苦心、煞星」（ㄕㄚˋ）。停住讀一聲，「很」與凶神讀四聲。"},
  {id:"p501",grade:6,word:"衣裳",target:"裳",zhuyin:"˙ㄕㄤ",pinyin:"shang",wz:"ㄧ ˙ㄕㄤ",wrong:[{z:"ㄕㄤ",p:"shāng"},{z:"ㄔㄤˊ",p:"cháng"}],note:"「衣裳」的「裳」讀輕聲˙ㄕㄤ；「霓裳羽衣」（古代下裙）讀ㄔㄤˊ。",deep:"1. 注音比較\n裳：˙ㄕㄤ（輕聲）＝衣裳；ㄔㄤˊ（二聲）＝霓裳羽衣曲、「制芰荷以為衣兮，集芙蓉以為裳」（古代的下裙）；ㄕㄤ（一聲）＝無此讀法（誤把輕聲讀成一聲）\n2. 國字拆解與造字原因\n裳：形聲字，「衣」＋「尚」（聲）。古人上身穿「衣」、下身圍「裳」（裙），單用指下裙時讀ㄔㄤˊ（霓裳）；後來「衣裳」合成一個詞泛指衣服，「裳」弱化讀輕聲˙ㄕㄤ。"},
  {id:"p502",grade:6,word:"什錦",target:"什",zhuyin:"ㄕˊ",pinyin:"shí",wz:"ㄕˊ ㄐㄧㄣˇ",wrong:[{z:"ㄕㄣˊ",p:"shén"},{z:"ㄕㄜˊ",p:"shé"}],note:"「什錦」「家什」讀ㄕˊ；「什麼」讀ㄕㄣˊ。",deep:"1. 注音比較\n什：ㄕˊ（二聲）＝什錦（多樣混合）、家什（器物）；ㄕㄣˊ（二聲）＝什麼；ㄕㄜˊ＝無此音（易受口語「啥」影響）\n2. 國字拆解與造字原因\n什：會意字，「亻」＋「十」，古代軍隊十人為「什」，本義是十人一組，引申為多樣、雜多→「什錦（十樣錦，多種材料組合）、什物」（ㄕˊ）；「什麼」是後起的疑問詞用法，讀ㄕㄣˊ。"},
  {id:"p503",grade:6,word:"舌苔",target:"苔",zhuyin:"ㄊㄞ",pinyin:"tāi",wz:"ㄕㄜˊ ㄊㄞ",wrong:[{z:"ㄊㄞˊ",p:"tái"},{z:"ㄊㄞˋ",p:"tài"}],note:"「舌苔」讀ㄊㄞ；「青苔」「苔蘚」讀ㄊㄞˊ。",deep:"1. 注音比較\n苔：ㄊㄞ（一聲）＝舌苔（舌面上的垢膜）；ㄊㄞˊ（二聲）＝青苔、苔蘚、苔痕；ㄊㄞˋ＝無此音（是「太」的讀音）\n2. 國字拆解與造字原因\n苔：形聲字，「艹」＋「台」（聲），本義是潮濕處滋生的隱花植物→「青苔、苔蘚」（ㄊㄞˊ）；舌面上滋生的薄垢長得像苔，醫學上稱「舌苔」，口語轉讀一聲ㄊㄞ。植物讀ㄊㄞˊ，舌苔讀ㄊㄞ。"},
  {id:"p504",grade:6,word:"累贅",target:"累",zhuyin:"ㄌㄟˇ",pinyin:"lěi",wz:"ㄌㄟˇ ㄓㄨㄟˋ",wrong:[{z:"ㄌㄟˊ",p:"léi"},{z:"ㄌㄟˋ",p:"lèi"}],note:"教育部審訂音「累贅」的「累」讀ㄌㄟˇ，和累積同音。",deep:"1. 注音比較\n累：ㄌㄟˇ＝累贅、累積、日積月累、經年累月、累次；ㄌㄟˋ＝勞累、疲累、拖累、連累。★教育部《國語辭典簡編本》「累」只收ㄌㄟˇ、ㄌㄟˋ兩音，「累贅」讀ㄌㄟˊ不是審訂音\n2. 國字拆解與造字原因\n累：從「糸（絲線）」，本義是用繩索一串串連綴起來。一層層疊加→「累積」（ㄌㄟˇ）；「累贅」就是身上多綁了一串多餘的東西，麻煩又礙事，同樣讀ㄌㄟˇ；負擔壓身使人疲乏→「勞累」（ㄌㄟˋ）。"},
  {id:"p505",grade:6,word:"屏東",target:"屏",zhuyin:"ㄆㄧㄥˊ",pinyin:"píng",wz:"ㄆㄧㄥˊ ㄉㄨㄥ",wrong:[{z:"ㄅㄧㄥˇ",p:"bǐng"},{z:"ㄆㄧㄥ",p:"pīng"}],note:"「屏東」「屏風」「螢幕屏」讀ㄆㄧㄥˊ；「屏息」「屏除」讀ㄅㄧㄥˇ。",deep:"1. 注音比較\n屏：ㄆㄧㄥˊ（二聲）＝屏東、屏風、屏障；ㄅㄧㄥˇ（三聲）＝屏息、屏氣凝神、屏除（抑止、排除）；ㄆㄧㄥ＝無此音（是「乒」的讀音）\n2. 國字拆解與造字原因\n屏：形聲字，「尸（與屋舍有關）」＋「并」（聲）。本義是遮擋用的屏風→「屏風、屏障、屏東（地名，在半屏山之東說法之一）」（ㄆㄧㄥˊ）；把氣「擋住」不呼出、把東西排除在外→「屏息、屏除」（ㄅㄧㄥˇ）。遮擋物讀ㄆㄧㄥˊ，抑止讀ㄅㄧㄥˇ。"},
  {id:"p506",grade:7,word:"濟濟一堂",target:"濟",zhuyin:"ㄐㄧˇ",pinyin:"jǐ",wz:"ㄐㄧˇ ㄐㄧˇ ㄧ ㄊㄤˊ",wrong:[{z:"ㄐㄧˋ",p:"jì"},{z:"ㄑㄧˊ",p:"qí"}],note:"「濟濟一堂」「人才濟濟」（眾多）讀ㄐㄧˇ；「經濟」「救濟」讀ㄐㄧˋ。",deep:"1. 注音比較\n濟：ㄐㄧˇ（三聲）＝濟濟一堂、人才濟濟（形容眾多）；ㄐㄧˋ（四聲）＝經濟、救濟、同舟共濟；ㄑㄧˊ＝無此音（是「齊」的讀音，「濟濟」常被誤讀成「齊齊」）\n2. 國字拆解與造字原因\n濟：形聲字，「氵（水）」＋「齊」（聲）。本義是濟水（古河名），引申為渡河→幫助人渡過難關→「救濟、接濟」（ㄐㄧˋ）；「濟濟」是疊字形容詞，形容人多而整齊的樣子，讀ㄐㄧˇ。"},
  {id:"p507",grade:7,word:"撒種",target:"撒",zhuyin:"ㄙㄚˇ",pinyin:"sǎ",wz:"ㄙㄚˇ ㄓㄨㄥˇ",wrong:[{z:"ㄙㄚ",p:"sā"},{z:"ㄕㄚˇ",p:"shǎ"}],note:"「撒種」「撒鹽」（散布）讀ㄙㄚˇ；「撒嬌」「撒手」（放開）讀ㄙㄚ。",deep:"1. 注音比較\n撒：ㄙㄚˇ（三聲）＝撒種、撒鹽、撒網（把東西散布出去）；ㄙㄚ（一聲）＝撒嬌、撒手、撒謊（放開、施展）；ㄕㄚˇ＝無此音（是「傻」的讀音）\n2. 國字拆解與造字原因\n撒：形聲字，「扌（手）」＋「散」（聲）。手把細碎的東西散布開來→「撒種、撒胡椒」（ㄙㄚˇ）；把手放開、把性子放出來→「撒手、撒嬌、撒野」（ㄙㄚ）。散布讀三聲，放開讀一聲。"},
  {id:"p508",grade:7,word:"傭金",target:"傭",zhuyin:"ㄩㄥ",pinyin:"yōng",wz:"ㄩㄥ ㄐㄧㄣ",wrong:[{z:"ㄩㄥˋ",p:"yòng"},{z:"ㄩㄥˇ",p:"yǒng"}],note:"教育部審訂音「傭」只有一個讀音ㄩㄥ：傭人、女傭、傭金都讀ㄩㄥ。",deep:"1. 注音比較\n傭：ㄩㄥ＝傭金、傭人、男傭、女傭、家傭、僱傭。★教育部《國語辭典簡編本》「傭」只收一聲ㄩㄥ，「傭金」讀ㄩㄥˋ不是審訂音\n2. 國字拆解與造字原因\n傭：形聲字，「亻（人）」＋「庸」（聲），本義是受僱替人做事的人。受僱做事所得的報酬就是「傭金」，人和錢都讀ㄩㄥ。"},
  {id:"p509",grade:7,word:"胳臂",target:"臂",zhuyin:"ㄅㄧˋ",pinyin:"bì",wz:"ㄍㄜ ㄅㄧˋ",wrong:[{z:"˙ㄅㄟ",p:"bei"},{z:"ㄅㄟˋ",p:"bèi"}],note:"教育部審訂音「胳臂」的「臂」讀ㄅㄧˋ，和手臂、臂膀同音。",deep:"1. 注音比較\n臂：ㄅㄧˋ＝胳臂、手臂、臂膀、臂膊、猿臂、螳臂當車。★教育部《國語辭典簡編本》「臂」只收ㄅㄧˋ一音，「胳臂」讀輕聲˙ㄅㄟ是口語音，不是審訂音\n2. 國字拆解與造字原因\n臂：形聲字，「月（肉）」＋「辟」（聲），指肩膀到手腕的部位。從肉部，因為是身體的一部分。"},
  {id:"p510",grade:7,word:"扁舟",target:"扁",zhuyin:"ㄆㄧㄢ",pinyin:"piān",wz:"ㄆㄧㄢ ㄓㄡ",wrong:[{z:"ㄅㄧㄢˇ",p:"biǎn"},{z:"ㄆㄧㄢˋ",p:"piàn"}],note:"「一葉扁舟」（小船）讀ㄆㄧㄢ；「扁平」「壓扁」讀ㄅㄧㄢˇ。",deep:"1. 注音比較\n扁：ㄆㄧㄢ（一聲）＝一葉扁舟（小的）；ㄅㄧㄢˇ（三聲）＝扁平、壓扁、扁額的「匾」同音；ㄆㄧㄢˋ＝無此音（是「片」的讀音）\n2. 國字拆解與造字原因\n扁：會意字，「戶」＋「冊」，門戶上題字的牌子，本義是匾額，引申為薄而寬的形狀→「扁平」（ㄅㄧㄢˇ）；形容小→「扁舟」（ㄆㄧㄢ），蘇軾〈赤壁賦〉「駕一葉之扁舟」即此音。小義讀ㄆㄧㄢ，平薄讀ㄅㄧㄢˇ。"},
  {id:"p511",grade:7,word:"顛簸",target:"簸",zhuyin:"ㄅㄛˇ",pinyin:"bǒ",wz:"ㄉㄧㄢ ㄅㄛˇ",wrong:[{z:"ㄅㄛˋ",p:"bò"},{z:"ㄆㄛˇ",p:"pǒ"}],note:"「顛簸」「簸動」（搖晃）讀ㄅㄛˇ；「簸箕」讀ㄅㄛˋ。",deep:"1. 注音比較\n簸：ㄅㄛˇ（三聲）＝顛簸、簸動、簸米（上下搖動）；ㄅㄛˋ（四聲）＝簸箕（揚米去糠的器具）；ㄆㄛˇ＝無此音（是「叵」的讀音）\n2. 國字拆解與造字原因\n簸：形聲字，「箕」＋「皮」（聲）。用箕上下搖動、揚去米糠的動作→「簸米、顛簸（像簸米一樣上下晃）」（ㄅㄛˇ）；搖米用的竹器→「簸箕」（ㄅㄛˋ）。動作三聲、器具四聲。"},
  {id:"p512",grade:7,word:"出差",target:"差",zhuyin:"ㄔㄞ",pinyin:"chāi",wz:"ㄔㄨ ㄔㄞ",wrong:[{z:"ㄔㄚˋ",p:"chà"},{z:"ㄘ",p:"cī"}],note:"「出差」「差遣」「郵差」（派遣、公務）讀ㄔㄞ；「差別」讀ㄔㄚ；「差勁」讀ㄔㄚˋ。",deep:"1. 注音比較\n差：ㄔㄞ（一聲）＝出差、差遣、郵差（被派的工作）；ㄔㄚ（一聲）＝差別、差距；ㄔㄚˋ（四聲）＝差勁、成績很差；ㄘ（一聲）＝參差不齊\n2. 國字拆解與造字原因\n差：本義是兩者不相合、有距離→「差別、差距」（ㄔㄚ）；不合標準→「差勁」（ㄔㄚˋ）；被上級「分派」出去辦的事→「出差、差事、欽差」（ㄔㄞ）；長短不齊→「參差」（ㄘ）。一字四音，是常考的多音字。"},
  {id:"p513",grade:7,word:"稱讚",target:"稱",zhuyin:"ㄔㄥ",pinyin:"chēng",wz:"ㄔㄥ ㄗㄢˋ",wrong:[{z:"ㄔㄣˋ",p:"chèn"},{z:"ㄔㄥˋ",p:"chèng"}],note:"「稱讚」「稱呼」「宣稱」讀ㄔㄥ；「稱職」「稱心如意」「對稱」讀ㄔㄣˋ。",deep:"1. 注音比較\n稱：ㄔㄥ（一聲）＝稱讚、稱呼、稱霸；ㄔㄣˋ（四聲）＝稱職、稱心如意、對稱；ㄔㄥˋ（四聲）＝同「秤」（磅秤的舊寫）\n2. 國字拆解與造字原因\n稱：形聲字，「禾」＋「爯」（提起），本義是提起穀物放上秤衡量→秤重（ㄔㄥˋ，後作「秤」）；衡量後說出評價→「稱讚、稱呼」（ㄔㄥ）；分量剛好相合→「稱職、相稱」（ㄔㄣˋ）。說出讀ㄔㄥ，相合讀ㄔㄣˋ。"},
  {id:"p514",grade:7,word:"薄荷",target:"薄",zhuyin:"ㄅㄛˋ",pinyin:"bò",wz:"ㄅㄛˋ ㄏㄜˊ",wrong:[{z:"ㄅㄛˊ",p:"bó"},{z:"ㄅㄠˊ",p:"báo"}],note:"「薄荷」讀ㄅㄛˋ；「薄弱」「刻薄」讀ㄅㄛˊ；口語「很薄」讀ㄅㄠˊ。",deep:"1. 注音比較\n薄：ㄅㄛˋ（四聲）＝薄荷（植物專名）；ㄅㄛˊ（二聲）＝薄弱、刻薄、單薄；ㄅㄠˊ（二聲）＝紙很薄、薄片（口語）\n2. 國字拆解與造字原因\n薄：形聲字，「艹」＋「溥」（聲）。本義是草木叢生，引申為厚度小、不厚道→「薄弱、刻薄」（書面ㄅㄛˊ、口語ㄅㄠˊ）；「薄荷」是植物專名，固定讀ㄅㄛˋ，三個音依詞而定。"},
  {id:"p515",grade:7,word:"藤蔓",target:"蔓",zhuyin:"ㄇㄢˋ",pinyin:"màn",wz:"ㄊㄥˊ ㄇㄢˋ",wrong:[{z:"ㄨㄢˋ",p:"wàn"},{z:"ㄨㄢˊ",p:"wán"}],note:"教育部審訂音「藤蔓」的「蔓」讀ㄇㄢˋ，和蔓延同音。",deep:"1. 注音比較\n蔓：ㄇㄢˋ＝藤蔓、蔓延、蔓生；ㄇㄢˊ＝蔓菁（一種蔬菜）。★教育部《國語辭典簡編本》「藤蔓」讀ㄊㄥˊ ㄇㄢˋ，讀成ㄨㄢˋ是口語音，不是審訂音\n2. 國字拆解與造字原因\n蔓：形聲字，「艹」＋「曼」（聲，有延長的意思）。指植物細長會攀爬的莖，也指莖不斷向外伸展→「蔓延」。從艸部，因為講的是植物。"},
  {id:"p516",grade:7,word:"住了一宿",target:"宿",zhuyin:"ㄒㄧㄡˇ",pinyin:"xiǔ",wz:"ㄓㄨˋ ˙ㄌㄜ ㄧ ㄒㄧㄡˇ",wrong:[{z:"ㄙㄨˋ",p:"sù"},{z:"ㄒㄧㄡˋ",p:"xiù"}],note:"「一宿」「整宿」（一夜）讀ㄒㄧㄡˇ；「住宿」「宿舍」讀ㄙㄨˋ；「星宿」讀ㄒㄧㄡˋ。",deep:"1. 注音比較\n宿：ㄒㄧㄡˇ（三聲）＝一宿、整宿（計算夜晚的量詞）；ㄙㄨˋ（四聲）＝住宿、宿舍、宿願；ㄒㄧㄡˋ（四聲）＝星宿、二十八宿\n2. 國字拆解與造字原因\n宿：會意字，「宀（房屋）」＋人躺在蓆子上，本義是過夜→「住宿、宿營」（ㄙㄨˋ）；過了幾夜就數幾「宿」（量詞，ㄒㄧㄡˇ）；星星是天上的「住所」分區→「星宿」（ㄒㄧㄡˋ）。一字三音：住讀ㄙㄨˋ、數夜讀ㄒㄧㄡˇ、星座讀ㄒㄧㄡˋ。"},
  {id:"p517",grade:7,word:"攪和",target:"和",zhuyin:"ㄏㄨㄛˋ",pinyin:"huò",wz:"ㄐㄧㄠˇ ㄏㄨㄛˋ",wrong:[{z:"ㄏㄜˊ",p:"hé"},{z:"ㄏㄢˋ",p:"hàn"}],note:"「攪和」「和藥」（摻拌）讀ㄏㄨㄛˋ；「和平」讀ㄏㄜˊ；「我和你」口語讀ㄏㄢˋ。",deep:"1. 注音比較\n和：ㄏㄨㄛˋ（四聲）＝攪和、和藥、和稀泥（摻合攪拌）；ㄏㄜˊ（二聲）＝和平、和氣、溫和；ㄏㄢˋ（四聲）＝你和我（連接詞的口語音）；另有ㄏㄜˋ＝唱和、附和\n2. 國字拆解與造字原因\n和：形聲字，「口」＋「禾」（聲）。本義是聲音相應和諧→「和平、溫和」（ㄏㄜˊ）、跟著別人唱→「附和」（ㄏㄜˋ）；把東西摻在一起拌勻→「攪和、和麵」（ㄏㄨㄛˋ）；當「與」用時口語讀ㄏㄢˋ。是國語中音最多的常用字之一。"},
  {id:"p518",grade:7,word:"細嚼慢嚥",target:"嚼",zhuyin:"ㄐㄧㄠˊ",pinyin:"jiáo",wz:"ㄒㄧˋ ㄐㄧㄠˊ ㄇㄢˋ ㄧㄢˋ",wrong:[{z:"ㄐㄩㄝˊ",p:"jué"},{z:"ㄐㄧㄠˋ",p:"jiào"}],note:"「細嚼慢嚥」「嚼舌根」（口語）讀ㄐㄧㄠˊ；「咀嚼」（書面）讀ㄐㄩㄝˊ。",deep:"1. 注音比較\n嚼：ㄐㄧㄠˊ（二聲）＝細嚼慢嚥、嚼口香糖、嚼舌根（口語）；ㄐㄩㄝˊ（二聲）＝咀嚼、過屠門而大嚼（書面）；ㄐㄧㄠˋ＝倒嚼（牛反芻，罕用）\n2. 國字拆解與造字原因\n嚼：形聲字，「口」＋「爵」（聲）。用牙齒磨碎食物：日常口語單用讀ㄐㄧㄠˊ（嚼不爛）；文言與複詞「咀嚼」讀ㄐㄩㄝˊ，引申為反覆體會（咀嚼文意）。口語ㄐㄧㄠˊ、書面ㄐㄩㄝˊ。"},
  {id:"p519",grade:7,word:"口吃",target:"吃",zhuyin:"ㄐㄧˊ",pinyin:"jí",wz:"ㄎㄡˇ ㄐㄧˊ",wrong:[{z:"ㄔ",p:"chī"},{z:"ㄑㄧˋ",p:"qì"}],note:"「口吃」（說話結巴）讀ㄐㄧˊ；「吃飯」「吃苦」讀ㄔ。",deep:"1. 注音比較\n吃：ㄐㄧˊ（二聲）＝口吃（說話不流利）；ㄔ（一聲）＝吃飯、吃虧、吃苦；ㄑㄧˋ＝無此音（是「氣」的讀音）\n2. 國字拆解與造字原因\n吃：形聲字，「口」＋「乞」（聲）。本義是說話結結巴巴、言語艱難→「口吃」（ㄐㄧˊ），《史記》說韓非「為人口吃」即此；後來借作進食的「喫」，簡寫成「吃」→「吃飯」（ㄔ）。進食讀ㄔ，結巴讀ㄐㄧˊ。"},
  {id:"p520",grade:7,word:"一場夢",target:"場",zhuyin:"ㄔㄤˇ",pinyin:"chǎng",wz:"ㄧ ㄔㄤˇ ㄇㄥˋ",wrong:[{z:"ㄔㄤˊ",p:"cháng"},{z:"ㄕㄤˋ",p:"shàng"}],note:"教育部審訂音「場」只有一個讀音ㄔㄤˇ：操場、一場夢、大病一場都讀ㄔㄤˇ。",deep:"1. 注音比較\n場：ㄔㄤˇ＝一場夢、一場電影、大鬧一場、操場、廣場、會場、開場、終場。★教育部《國語辭典簡編本》「場」只收ㄔㄤˇ一音，當量詞讀ㄔㄤˊ是舊讀，已非現行審訂音\n2. 國字拆解與造字原因\n場：形聲字，「土」＋「昜」（聲），本義是平坦的空地→「操場、廣場」。事情從頭到尾發生一遍也像在一塊場地上演完，所以當量詞用→「一場夢、大病一場」，讀音相同。"},
  {id:"p521",grade:8,word:"椎心泣血",target:"椎",zhuyin:"ㄓㄨㄟ",pinyin:"zhuī",wz:"ㄓㄨㄟ ㄒㄧㄣ ㄑㄧˋ ㄒㄧㄝˇ",wrong:[{z:"ㄔㄨㄟˊ",p:"chuí"},{z:"ㄉㄨㄟ",p:"duī"}],note:"教育部審訂音「椎心泣血」的「椎」讀ㄓㄨㄟ，和脊椎同音；「血」讀ㄒㄧㄝˇ。",deep:"1. 注音比較\n椎：ㄓㄨㄟ＝椎心泣血、脊椎、鐵椎。★教育部《國語辭典簡編本》「椎」只收ㄓㄨㄟ一音，讀成ㄔㄨㄟˊ不是審訂音；「血」審訂音讀ㄒㄧㄝˇ\n2. 國字拆解與造字原因\n椎：形聲字，「木」＋「隹」（聲），本義是敲擊用的木槌，當動詞就是捶打。「椎心泣血」是捶著胸口哭到流血，形容極度悲痛。人背上一節節像小槌的骨頭叫「脊椎」，讀音相同。"},
  {id:"p522",grade:8,word:"虛與委蛇",target:"蛇",zhuyin:"ㄧˊ",pinyin:"yí",wz:"ㄒㄩ ㄩˇ ㄨㄟ ㄧˊ",wrong:[{z:"ㄕㄜˊ",p:"shé"},{z:"ㄨㄟ",p:"wēi"}],note:"「虛與委蛇」（敷衍應付）的「蛇」讀ㄧˊ；「蛇類」「毒蛇」讀ㄕㄜˊ。",deep:"1. 注音比較\n蛇：ㄧˊ（二聲）＝虛與委蛇（委蛇＝隨順的樣子）；ㄕㄜˊ（二聲）＝毒蛇、畫蛇添足；ㄨㄟ＝無此音（「委蛇」的「委」才讀ㄨㄟ）\n2. 國字拆解與造字原因\n蛇：形聲字，「虫」＋「它」（聲，「它」本就是蛇的象形）。動物之義讀ㄕㄜˊ；「委蛇」（ㄨㄟ ㄧˊ）是連綿詞，形容從容隨順、曲折延伸的樣子，出自《莊子》「虛與委蛇」——表面順從、敷衍應付，成語中固定讀ㄧˊ。"},
  {id:"p523",grade:8,word:"親家",target:"親",zhuyin:"ㄑㄧㄥˋ",pinyin:"qìng",wz:"ㄑㄧㄥˋ ㄐㄧㄚ",wrong:[{z:"ㄑㄧㄣ",p:"qīn"},{z:"ㄑㄧㄥˊ",p:"qíng"}],note:"「親家」（兒女配偶的父母）讀ㄑㄧㄥˋ；「親人」「親切」讀ㄑㄧㄣ。",deep:"1. 注音比較\n親：ㄑㄧㄥˋ（四聲）＝親家、親家母（兒女婚姻結成的雙方父母）；ㄑㄧㄣ（一聲）＝親人、親切、親自；ㄑㄧㄥˊ＝無此音（是「情」的讀音）\n2. 國字拆解與造字原因\n親：形聲字，「見」＋「亲」（聲），常相見的人最親近，本義是關係最近的人→「親人、雙親」（ㄑㄧㄣ）；兒女結婚使兩家人變成「親」戚，這個專稱口語轉讀ㄑㄧㄥˋ→「親家」。只有「親家」讀ㄑㄧㄥˋ，要特別記。"},
  {id:"p524",grade:8,word:"一石米",target:"石",zhuyin:"ㄉㄢˋ",pinyin:"dàn",wz:"ㄧ ㄉㄢˋ ㄇㄧˇ",wrong:[{z:"ㄕˊ",p:"shí"},{z:"ㄉㄢ",p:"dān"}],note:"「一石米」（容量單位，十斗）讀ㄉㄢˋ；「石頭」「岩石」讀ㄕˊ。",deep:"1. 注音比較\n石：ㄉㄢˋ（四聲）＝一石米、兩石穀（容量單位，十斗為一石）；ㄕˊ（二聲）＝石頭、岩石、鐵石心腸；ㄉㄢ＝無此音（是「擔」的讀音之一，兩字常混）\n2. 國字拆解與造字原因\n石：象形字，像山崖下的石塊，本義是石頭（ㄕˊ）；古代以石為重量基準，借作糧食的容量單位，一石約一人所能挑，與「擔」音近而讀ㄉㄢˋ。物體讀ㄕˊ，單位讀ㄉㄢˋ。"},
  {id:"p525",grade:8,word:"半身不遂",target:"遂",zhuyin:"ㄙㄨㄟˋ",pinyin:"suì",wz:"ㄅㄢˋ ㄕㄣ ㄅㄨˋ ㄙㄨㄟˋ",wrong:[{z:"ㄙㄨㄟˊ",p:"suí"},{z:"ㄓㄨㄟˋ",p:"zhuì"}],note:"教育部審訂音「遂」只有一個讀音ㄙㄨㄟˋ：半身不遂、遂願、未遂都讀ㄙㄨㄟˋ。",deep:"1. 注音比較\n遂：ㄙㄨㄟˋ＝半身不遂、遂心、遂願、諸事不遂、殺人未遂。★教育部《國語辭典簡編本》「遂」只收ㄙㄨㄟˋ一音，「半身不遂」讀ㄙㄨㄟˊ不是審訂音\n2. 國字拆解與造字原因\n遂：形聲字，「辵（辶）」＋「㒸」（聲），本義是往前走、達成。「不遂」就是不能順遂、不聽使喚，「半身不遂」指半邊身體無法照意思活動。"},
  {id:"p526",grade:8,word:"予取予求",target:"予",zhuyin:"ㄩˊ",pinyin:"yú",wz:"ㄩˊ ㄑㄩˇ ㄩˊ ㄑㄧㄡˊ",wrong:[{z:"ㄩˇ",p:"yǔ"},{z:"ㄩˋ",p:"yù"}],note:"「予取予求」（予＝我）讀ㄩˊ；「給予」「賦予」讀ㄩˇ。",deep:"1. 注音比較\n予：ㄩˊ（二聲）＝予取予求、予智予雄（我，文言自稱）；ㄩˇ（三聲）＝給予、賦予、授予；ㄩˋ＝無此音（是「玉」的讀音）\n2. 國字拆解與造字原因\n予：指事字，像織布梭子推送交付的樣子，本義是給→「給予、贈予」（ㄩˇ）；古文借作第一人稱「我」→「予取予求（從我這裡拿、向我要求）」（ㄩˊ）。給讀ㄩˇ，「我」讀ㄩˊ。"},
  {id:"p527",grade:8,word:"體己",target:"體",zhuyin:"ㄊㄧˇ",pinyin:"tǐ",wz:"ㄊㄧˇ ㄐㄧˇ",wrong:[{z:"ㄊㄧ",p:"tī"},{z:"ㄊㄧˋ",p:"tì"}],note:"教育部審訂音「體」只有一個讀音ㄊㄧˇ，「體己」也讀ㄊㄧˇ。",deep:"1. 注音比較\n體：ㄊㄧˇ＝體己、身體、肉體、人體、肢體、五體投地。★教育部《國語辭典簡編本》「體」只收ㄊㄧˇ一音，「體己」讀ㄊㄧ是口語音，不是審訂音\n2. 國字拆解與造字原因\n體：形聲字，「骨」＋「豊」（聲），本義是身體。「體己」指貼著自己身邊、最私密的錢財或話語（如：體己話、體己錢），讀音仍是ㄊㄧˇ。"},
  {id:"p528",grade:8,word:"莎草",target:"莎",zhuyin:"ㄙㄨㄛ",pinyin:"suō",wz:"ㄙㄨㄛ ㄘㄠˇ",wrong:[{z:"ㄕㄚ",p:"shā"},{z:"ㄙㄨㄛˇ",p:"suǒ"}],note:"「莎草」（植物）讀ㄙㄨㄛ；「莎士比亞」「蒙娜麗莎」（譯名）讀ㄕㄚ。",deep:"1. 注音比較\n莎：ㄙㄨㄛ（一聲）＝莎草（多年生草本植物）；ㄕㄚ（一聲）＝莎士比亞、莎莉（外來譯名用字）；ㄙㄨㄛˇ＝無此音（是「所」的讀音）\n2. 國字拆解與造字原因\n莎：形聲字，「艹」＋「沙」（聲）。本義是莎草，塊根即中藥「香附」，植物義讀ㄙㄨㄛ；近代音譯外文人名地名時借用其聲符音讀ㄕㄚ。植物讀ㄙㄨㄛ，譯名讀ㄕㄚ。"},
  {id:"p529",grade:8,word:"寡廉鮮恥",target:"鮮",zhuyin:"ㄒㄧㄢˇ",pinyin:"xiǎn",wz:"ㄍㄨㄚˇ ㄌㄧㄢˊ ㄒㄧㄢˇ ㄔˇ",wrong:[{z:"ㄒㄧㄢ",p:"xiān"},{z:"ㄒㄧㄢˋ",p:"xiàn"}],note:"「寡廉鮮恥」「鮮少」「鮮為人知」（少）讀ㄒㄧㄢˇ；「新鮮」「海鮮」讀ㄒㄧㄢ。",deep:"1. 注音比較\n鮮：ㄒㄧㄢˇ（三聲）＝寡廉鮮恥、鮮少、鮮為人知（少）；ㄒㄧㄢ（一聲）＝新鮮、海鮮、鮮豔；ㄒㄧㄢˋ＝無此音（是「現」的讀音）\n2. 國字拆解與造字原因\n鮮：會意字，「魚」＋「羊」，魚羊都是美味，本義是鮮美的食物→「新鮮、海鮮」（ㄒㄧㄢ）；鮮美的東西難得、稀少→借表「少」→「鮮少、鮮有耳聞」（ㄒㄧㄢˇ）。新鮮讀一聲，稀少讀三聲。"},
  {id:"p530",grade:8,word:"傾軋",target:"軋",zhuyin:"ㄧㄚˋ",pinyin:"yà",wz:"ㄑㄧㄥ ㄧㄚˋ",wrong:[{z:"ㄍㄚˊ",p:"gá"},{z:"ㄓㄚˊ",p:"zhá"}],note:"「傾軋」「軋斷」（排擠、輾壓）讀ㄧㄚˋ；「軋戲」「軋朋友」讀ㄍㄚˊ。",deep:"1. 注音比較\n軋：ㄧㄚˋ（四聲）＝傾軋（互相排擠）、軋斷（輾壓）；ㄍㄚˊ（二聲）＝軋戲、軋一腳（擠入，方言）；ㄓㄚˊ（二聲）＝軋鋼（機械壓延）\n2. 國字拆解與造字原因\n軋：會意字，「車」＋「乙」（曲折壓過的痕跡），本義是車輪輾壓→「軋傷、輾軋」，人與人互相「輾壓」排擠→「傾軋」（ㄧㄚˋ）；方言借音表「擠、湊」→「軋戲」（ㄍㄚˊ）；工業壓延金屬讀ㄓㄚˊ。"},
  {id:"p531",grade:8,word:"開拓",target:"拓",zhuyin:"ㄊㄨㄛˋ",pinyin:"tuò",wz:"ㄎㄞ ㄊㄨㄛˋ",wrong:[{z:"ㄊㄚˋ",p:"tà"},{z:"ㄊㄨㄛ",p:"tuō"}],note:"「開拓」「拓展」「拓荒」讀ㄊㄨㄛˋ；「拓印」「拓本」讀ㄊㄚˋ。",deep:"1. 注音比較\n拓：ㄊㄨㄛˋ（四聲）＝開拓、拓展、拓荒；ㄊㄚˋ（四聲）＝拓印、拓本、碑拓（把碑刻文字印下來）；ㄊㄨㄛ＝無此音（是「托」的讀音）\n2. 國字拆解與造字原因\n拓：形聲字，「扌（手）」＋「石」。本義是用手撿拾、開闢→「開拓、拓寬」（ㄊㄨㄛˋ）；把紙覆在石碑上捶印文字的技術→「拓印、拓本」（ㄊㄚˋ）。開闢讀ㄊㄨㄛˋ，印碑讀ㄊㄚˋ。"},
  {id:"p532",grade:8,word:"蒙古",target:"蒙",zhuyin:"ㄇㄥˊ",pinyin:"méng",wz:"ㄇㄥˊ ㄍㄨˇ",wrong:[{z:"ㄇㄥˇ",p:"měng"},{z:"ㄇㄥ",p:"mēng"}],note:"教育部審訂音「蒙」只有一個讀音ㄇㄥˊ，「蒙古」也讀ㄇㄥˊ。",deep:"1. 注音比較\n蒙：ㄇㄥˊ＝蒙古、蒙族、蒙藏、蒙騙、蒙蔽、承蒙、啟蒙。★教育部《國語辭典簡編本》「蒙」只收ㄇㄥˊ一音，「蒙古」讀ㄇㄥˇ是舊讀，已非現行審訂音\n2. 國字拆解與造字原因\n蒙：形聲字，「艹」＋「冡」（聲，覆蓋），本義是遮蓋→「蒙上眼睛、蒙蔽」；被蓋住就是還沒開化，把蓋子掀開就是「啟蒙」。族名「蒙古」是音譯，讀音同樣是ㄇㄥˊ。"},
  {id:"p533",grade:8,word:"作揖",target:"作",zhuyin:"ㄗㄨㄛˋ",pinyin:"zuò",wz:"ㄗㄨㄛˋ ㄧ",wrong:[{z:"ㄗㄨㄛ",p:"zuō"},{z:"ㄗㄨㄛˇ",p:"zuǒ"}],note:"教育部審訂音「作揖」的「作」讀ㄗㄨㄛˋ，和工作、創作同音。",deep:"1. 注音比較\n作：ㄗㄨㄛˋ＝作揖、工作、創作、寫作、振作、以身作則、裝模作樣；ㄗㄨㄛˊ＝少數古語用法。★教育部《國語辭典簡編本》「作揖」讀ㄗㄨㄛˋ ㄧ，讀成一聲ㄗㄨㄛ不是審訂音\n2. 國字拆解與造字原因\n作：形聲字，「亻（人）」＋「乍」（聲），本義是興起、動手做。「作揖」是兩手抱拳、身子微彎行禮，也是「做」出來的動作，所以讀ㄗㄨㄛˋ。"},
  {id:"p534",grade:8,word:"蠻橫",target:"橫",zhuyin:"ㄏㄥˋ",pinyin:"hèng",wz:"ㄇㄢˊ ㄏㄥˋ",wrong:[{z:"ㄏㄥˊ",p:"héng"},{z:"ㄏㄤˊ",p:"háng"}],note:"「蠻橫」「橫財」「橫禍」（不講理、意外）讀ㄏㄥˋ；「橫線」「縱橫」讀ㄏㄥˊ。",deep:"1. 注音比較\n橫：ㄏㄥˋ（四聲）＝蠻橫、橫財、飛來橫禍（凶暴不講理、意外的）；ㄏㄥˊ（二聲）＝橫線、橫越、縱橫；ㄏㄤˊ＝無此音（是「行」的讀音之一）\n2. 國字拆解與造字原因\n橫：形聲字，「木」＋「黃」（聲），本義是門前橫木，引申為與直相對的方向→「橫線、橫跨」（ㄏㄥˊ）；「橫」著來＝不順著道理來→「蠻橫、強橫」，不循正道而來的財與禍→「橫財、橫禍」（ㄏㄥˋ）。方向讀二聲，凶暴意外讀四聲。"},
  {id:"p535",grade:8,word:"引吭高歌",target:"吭",zhuyin:"ㄏㄤˊ",pinyin:"háng",wz:"ㄧㄣˇ ㄏㄤˊ ㄍㄠ ㄍㄜ",wrong:[{z:"ㄎㄥ",p:"kēng"},{z:"ㄏㄤˋ",p:"hàng"}],note:"「引吭高歌」（放開喉嚨）讀ㄏㄤˊ；「不吭聲」「吭氣」讀ㄎㄥ。",deep:"1. 注音比較\n吭：ㄏㄤˊ（二聲）＝引吭高歌（吭＝喉嚨）；ㄎㄥ（一聲）＝不吭聲、一聲不吭（出聲）；ㄏㄤˋ＝無此音（是「沆」的讀音）\n2. 國字拆解與造字原因\n吭：形聲字，「口」＋「亢」（聲，「亢」本義是人的頸部）。指喉嚨這個部位→「引吭（拉開嗓子）高歌」（ㄏㄤˊ）；從喉嚨發出聲音的動作→「吭聲、吭氣」（ㄎㄥ）。部位讀ㄏㄤˊ，出聲讀ㄎㄥ。"},
  {id:"p536",grade:9,word:"不禁",target:"禁",zhuyin:"ㄐㄧㄣ",pinyin:"jīn",wz:"ㄅㄨˋ ㄐㄧㄣ",wrong:[{z:"ㄐㄧㄣˋ",p:"jìn"},{z:"ㄑㄧㄣ",p:"qīn"}],note:"「不禁」「禁不起」「弱不禁風」（承受）讀ㄐㄧㄣ；「禁止」「禁區」讀ㄐㄧㄣˋ。",deep:"1. 注音比較\n禁：ㄐㄧㄣ（一聲）＝不禁、禁得起、弱不禁風（承受得住）；ㄐㄧㄣˋ（四聲）＝禁止、禁區、監禁；ㄑㄧㄣ＝無此音（是「侵」的讀音）\n2. 國字拆解與造字原因\n禁：會意字，「示」（祭祀）＋「林」，祭祀的林地不許人擅入，本義是避忌、不准→「禁止、禁令」（ㄐㄧㄣˋ）；「承受得住（壓制）」的意思讀ㄐㄧㄣ→「情不自禁、禁不起考驗」。不准讀四聲，承受讀一聲。"},
  {id:"p537",grade:9,word:"勒緊",target:"勒",zhuyin:"ㄌㄟ",pinyin:"lēi",wz:"ㄌㄟ ㄐㄧㄣˇ",wrong:[{z:"ㄌㄜˋ",p:"lè"},{z:"ㄌㄟˋ",p:"lèi"}],note:"「勒緊」「勒住」（拉緊）讀ㄌㄟ；「勒索」「勒令」「懸崖勒馬」讀ㄌㄜˋ。",deep:"1. 注音比較\n勒：ㄌㄟ（一聲）＝勒緊褲帶、勒住繩子（用力拉緊，口語）；ㄌㄜˋ（四聲）＝勒索、勒令、懸崖勒馬（強制、控馭）；ㄌㄟˋ＝無此音（是「累」的讀音之一）\n2. 國字拆解與造字原因\n勒：形聲字，「革」＋「力」（聲），本義是帶嚼口的馬籠頭，拉緊韁繩控馬→「勒馬」，引申為強制→「勒令、勒索」（ㄌㄜˋ）；口語中單純「拉緊、繫緊」的動作讀ㄌㄟ→「勒緊」。書面強制讀ㄌㄜˋ，口語拉緊讀ㄌㄟ。"},
  {id:"p538",grade:9,word:"霓裳",target:"裳",zhuyin:"ㄔㄤˊ",pinyin:"cháng",wz:"ㄋㄧˊ ㄔㄤˊ",wrong:[{z:"ㄕㄤ",p:"shāng"},{z:"ㄕㄤˇ",p:"shǎng"}],note:"「霓裳羽衣」（古代下裙）讀ㄔㄤˊ；「衣裳」的「裳」讀輕聲˙ㄕㄤ。",deep:"1. 注音比較\n裳：ㄔㄤˊ（二聲）＝霓裳羽衣曲、「制芰荷以為衣兮」之「裳」（古代下身的裙）；˙ㄕㄤ（輕聲）＝衣裳；ㄕㄤ（一聲）＝誤讀（把輕聲讀成本調）\n2. 國字拆解與造字原因\n裳：形聲字，「衣」＋「尚」（聲）。上古服制上曰衣、下曰裳，單獨指下裙時讀ㄔㄤˊ，白居易〈琵琶行〉「整頓衣裳起斂容」古音亦然；現代口語「衣裳」合指衣服，「裳」輕讀˙ㄕㄤ。文言讀ㄔㄤˊ，口語輕聲。"},
  {id:"p539",grade:9,word:"恐嚇",target:"嚇",zhuyin:"ㄏㄜˋ",pinyin:"hè",wz:"ㄎㄨㄥˇ ㄏㄜˋ",wrong:[{z:"ㄒㄧㄚˋ",p:"xià"},{z:"ㄏㄞˋ",p:"hài"}],note:"「恐嚇」「威嚇」「恫嚇」讀ㄏㄜˋ；「嚇一跳」「驚嚇」讀ㄒㄧㄚˋ。",deep:"1. 注音比較\n嚇：ㄏㄜˋ（四聲）＝恐嚇、威嚇、恫嚇（用言語威脅）；ㄒㄧㄚˋ（四聲）＝嚇一跳、驚嚇、嚇壞了（受驚）；ㄏㄞˋ＝無此音（是「害」的讀音）\n2. 國字拆解與造字原因\n嚇：形聲字，「口」＋「赫」（聲，盛怒顯赫之貌）。張口作聲使人害怕：主動用聲勢威脅人→「恐嚇、威嚇」（ㄏㄜˋ）；使人受驚、自己受驚→「嚇人、嚇了一跳」（ㄒㄧㄚˋ）。書面威脅讀ㄏㄜˋ，受驚讀ㄒㄧㄚˋ。"},
  {id:"p540",grade:9,word:"積攢",target:"攢",zhuyin:"ㄗㄢˇ",pinyin:"zǎn",wz:"ㄐㄧ ㄗㄢˇ",wrong:[{z:"ㄘㄨㄢˊ",p:"cuán"},{z:"ㄗㄢˋ",p:"zàn"}],note:"「積攢」「攢錢」（積蓄）讀ㄗㄢˇ；「攢動」「攢聚」（聚集）讀ㄘㄨㄢˊ。",deep:"1. 注音比較\n攢：ㄗㄢˇ（三聲）＝積攢、攢錢（一點一點存起來）；ㄘㄨㄢˊ（二聲）＝攢動、攢聚、萬頭攢動（聚攏）；ㄗㄢˋ＝無此音（是「贊」的讀音）\n2. 國字拆解與造字原因\n攢：形聲字，「扌（手）」＋「贊」（聲）。用手把東西聚到一起：許多人或物擠聚在一處→「攢聚、萬頭攢動」（ㄘㄨㄢˊ）；把錢一點一滴聚存起來→「攢錢」（ㄗㄢˇ）。聚攏讀ㄘㄨㄢˊ，存錢讀ㄗㄢˇ。"},
  {id:"p541",grade:9,word:"烙印",target:"烙",zhuyin:"ㄌㄠˋ",pinyin:"lào",wz:"ㄌㄠˋ ㄧㄣˋ",wrong:[{z:"ㄌㄨㄛˋ",p:"luò"},{z:"ㄌㄠˊ",p:"láo"}],note:"「烙印」「烙餅」讀ㄌㄠˋ；「炮烙」（古酷刑）讀ㄌㄨㄛˋ。",deep:"1. 注音比較\n烙：ㄌㄠˋ（四聲）＝烙印、烙餅、烙鐵；ㄌㄨㄛˋ（四聲）＝炮烙（商紂的酷刑）；ㄌㄠˊ＝無此音（是「勞」的讀音）\n2. 國字拆解與造字原因\n烙：形聲字，「火」＋「各」（聲）。用燒熱的金屬燙：燙出印記、用平鍋烤熟麵食→「烙印、烙餅」（ㄌㄠˋ）；古代「炮烙」之刑專讀ㄌㄨㄛˋ。一般讀ㄌㄠˋ，「炮烙」一詞讀ㄌㄨㄛˋ。"},
  {id:"p542",grade:9,word:"果脯",target:"脯",zhuyin:"ㄈㄨˇ",pinyin:"fǔ",wz:"ㄍㄨㄛˇ ㄈㄨˇ",wrong:[{z:"ㄆㄨˊ",p:"pú"},{z:"ㄈㄨˋ",p:"fù"}],note:"「果脯」「肉脯」（乾製食品）讀ㄈㄨˇ；「胸脯」讀ㄆㄨˊ。",deep:"1. 注音比較\n脯：ㄈㄨˇ（三聲）＝果脯、肉脯、杏脯（醃漬曬乾的食品）；ㄆㄨˊ（二聲）＝胸脯、拍胸脯（胸膛）；ㄈㄨˋ＝無此音（是「付」的讀音）\n2. 國字拆解與造字原因\n脯：形聲字，「月（肉）」＋「甫」（聲）。本義是肉乾→「肉脯」，糖漬的果乾也稱脯→「果脯」（ㄈㄨˇ）；口語指胸膛→「胸脯」（ㄆㄨˊ）。食品讀ㄈㄨˇ，胸膛讀ㄆㄨˊ。"},
  {id:"p543",grade:9,word:"稽首",target:"稽",zhuyin:"ㄑㄧˇ",pinyin:"qǐ",wz:"ㄑㄧˇ ㄕㄡˇ",wrong:[{z:"ㄐㄧ",p:"jī"},{z:"ㄑㄧˊ",p:"qí"}],note:"「稽首」（古代叩頭大禮）讀ㄑㄧˇ；「稽查」「稽核」「無稽之談」讀ㄐㄧ。",deep:"1. 注音比較\n稽：ㄑㄧˇ（三聲）＝稽首（叩頭至地的大禮）；ㄐㄧ（一聲）＝稽查、稽核、滑稽、無稽之談；ㄑㄧˊ＝無此音（是「奇」的讀音）\n2. 國字拆解與造字原因\n稽：形聲字，「禾」＋「尤」＋「旨」。本義是停留、考核→「稽查、稽核（留下來細查）」（ㄐㄧ）；古禮跪拜時頭「停留」在地上片刻，是最隆重的叩拜→「稽首」（ㄑㄧˇ）。查核讀ㄐㄧ，叩首讀ㄑㄧˇ。"},
  {id:"p544",grade:9,word:"哪吒",target:"哪",zhuyin:"ㄋㄨㄛˊ",pinyin:"nuó",wz:"ㄋㄨㄛˊ ㄓㄚˋ",wrong:[{z:"ㄋㄜˊ",p:"né"},{z:"ㄋㄚˇ",p:"nǎ"}],note:"教育部審訂音「哪吒」讀ㄋㄨㄛˊ ㄓㄚˋ，是神話人物專名的固定讀法。",deep:"1. 注音比較\n哪：ㄋㄚˇ＝哪裡、哪天、哪知道（疑問）；˙ㄋㄚ＝語尾助詞（好哪）；ㄋㄨㄛˊ＝哪吒（神名）。★教育部《國語辭典簡編本》「哪吒」讀ㄋㄨㄛˊ ㄓㄚˋ，坊間常念成ㄋㄜˊ ㄓㄚ，那不是審訂音\n2. 國字拆解與造字原因\n哪：形聲字，「口」＋「那」（聲），本是疑問代詞。「哪吒」是梵語護法神名的音譯，只是借「哪」「吒」兩字表音，和原本的字義無關，所以讀音也另有規定。"},
  {id:"p545",grade:9,word:"月氏",target:"氏",zhuyin:"ㄓ",pinyin:"zhī",wz:"ㄩㄝˋ ㄓ",wrong:[{z:"ㄕˋ",p:"shì"},{z:"ㄉㄧ",p:"dī"}],note:"「月氏」（古西域國名）的「氏」讀ㄓ；「姓氏」「氏族」讀ㄕˋ。",deep:"1. 注音比較\n氏：ㄓ（一聲）＝月氏、閼氏（古代西域、匈奴專名）；ㄕˋ（四聲）＝姓氏、氏族、攝氏；ㄉㄧ＝無此音（「氐族」的「氐」才讀ㄉㄧ，形近易混）\n2. 國字拆解與造字原因\n氏：象形字，像木本的根柢，宗族由同一根源分出，本義是宗族支系→「姓氏、王氏」（ㄕˋ）；漢代西域國名「月氏」是外語音譯，保留古音讀ㄓ。姓氏讀ㄕˋ，「月氏、閼氏」讀ㄓ。"},
  {id:"p546",grade:10,word:"妄自菲薄",target:"菲",zhuyin:"ㄈㄟˇ",pinyin:"fěi",wz:"ㄨㄤˋ ㄗˋ ㄈㄟˇ ㄅㄛˊ",wrong:[{z:"ㄈㄟ",p:"fēi"},{z:"ㄈㄟˋ",p:"fèi"}],note:"「妄自菲薄」「菲薄」（輕視、微薄）讀ㄈㄟˇ；「芳菲」「菲律賓」讀ㄈㄟ。",deep:"1. 注音比較\n菲：ㄈㄟˇ（三聲）＝妄自菲薄、菲薄（微薄、看輕）、菲儀（謙稱薄禮）；ㄈㄟ（一聲）＝芳菲（花草香美）、菲律賓；ㄈㄟˋ＝無此音（是「費」的讀音）\n2. 國字拆解與造字原因\n菲：形聲字，「艹」＋「非」（聲）。本義是一種蘿蔔類的菜，菜色粗薄→引申為微薄、把自己看得太輕→「妄自菲薄」（ㄈㄟˇ）；花草茂盛芳香→「芳菲」（ㄈㄟ）。微薄讀ㄈㄟˇ，芳香讀ㄈㄟ。"},
  {id:"p547",grade:10,word:"量入為出",target:"量",zhuyin:"ㄌㄧㄤˋ",pinyin:"liàng",wz:"ㄌㄧㄤˋ ㄖㄨˋ ㄨㄟˊ ㄔㄨ",wrong:[{z:"ㄌㄧㄤˊ",p:"liáng"},{z:"ㄌㄧㄤˇ",p:"liǎng"}],note:"教育部審訂音「量入為出」的「量」讀ㄌㄧㄤˋ，指衡量收入的數量。",deep:"1. 注音比較\n量：ㄌㄧㄤˋ＝量入為出、量力而為、數量、容量、降雨量、不自量力；ㄌㄧㄤˊ＝測量、量身高、量血壓、商量。★「量入為出」教育部審訂音讀ㄌㄧㄤˋ，讀成ㄌㄧㄤˊ不是審訂音\n2. 國字拆解與造字原因\n量：本義是用器具測定多少。動手去量的動作讀ㄌㄧㄤˊ（測量、量身高）；量出來的結果、心裡衡量的分寸讀ㄌㄧㄤˋ（容量、量力而為、量入為出＝先看收入有多少，再決定支出）。"},
  {id:"p548",grade:10,word:"風靡一時",target:"靡",zhuyin:"ㄇㄧˇ",pinyin:"mǐ",wz:"ㄈㄥ ㄇㄧˇ ㄧ ㄕˊ",wrong:[{z:"ㄇㄧˊ",p:"mí"},{z:"ㄇㄟˊ",p:"méi"}],note:"「風靡」「靡靡之音」「所向披靡」讀ㄇㄧˇ；「靡費」（浪費）讀ㄇㄧˊ。",deep:"1. 注音比較\n靡：ㄇㄧˇ（三聲）＝風靡一時、所向披靡、靡靡之音（倒下、順從）；ㄇㄧˊ（二聲）＝靡費、奢靡（浪費）；ㄇㄟˊ＝無此音（是「眉」的讀音）\n2. 國字拆解與造字原因\n靡：形聲字，「非」＋「麻」（聲）。本義是倒下、散亂：草木隨風傾倒→「風靡（像風吹草倒般流行）、披靡」（ㄇㄧˇ）；財物散去無度→「靡費、奢靡」（ㄇㄧˊ）。倒下讀ㄇㄧˇ，浪費讀ㄇㄧˊ。"},
  {id:"p549",grade:10,word:"安步當車",target:"當",zhuyin:"ㄉㄤ",pinyin:"dāng",wz:"ㄢ ㄅㄨˋ ㄉㄤ ㄔㄜ",wrong:[{z:"ㄉㄤˋ",p:"dàng"},{z:"ㄊㄤˊ",p:"táng"}],note:"教育部審訂音「安步當車」的「當」讀ㄉㄤ（一聲），意思是「當作」。",deep:"1. 注音比較\n當：ㄉㄤ＝安步當車、當面、當時、當場、應當、門當戶對；ㄉㄤˋ＝典當、上當、勾當；ㄉㄤˇ＝銳不可當、螳臂當車。★「安步當車」教育部審訂音讀ㄢ ㄅㄨˋ ㄉㄤ ㄔㄜ，讀成ㄉㄤˋ不是審訂音\n2. 國字拆解與造字原因\n當：形聲字，「田」＋「尚」（聲），本義是兩塊田價值相抵。「安步當車」是慢慢走路就把它當成坐車，取「相抵、當作」的意思，讀一聲；抵押換錢的「典當」才讀四聲。"},
  {id:"p550",grade:10,word:"叨擾",target:"叨",zhuyin:"ㄊㄠ",pinyin:"tāo",wz:"ㄊㄠ ㄖㄠˇ",wrong:[{z:"ㄉㄠ",p:"dāo"},{z:"ㄊㄠˊ",p:"táo"}],note:"「叨擾」「叨光」（受人好處的謙詞）讀ㄊㄠ；「叨叨」「叨唸」（話多）讀ㄉㄠ。",deep:"1. 注音比較\n叨：ㄊㄠ（一聲）＝叨擾（謝人款待）、叨光、叨陪末座（謙詞）；ㄉㄠ（一聲）＝叨叨、叨唸、絮叨（話多囉嗦）；ㄊㄠˊ＝無此音（是「桃」的讀音）\n2. 國字拆解與造字原因\n叨：形聲字，「口」＋「刀」（聲）。本義是貪，客套話中謙稱自己「貪受」了對方的招待→「叨擾、叨光」（ㄊㄠ）；嘴巴說個不停→「叨唸、絮絮叨叨」（ㄉㄠ）。謙詞讀ㄊㄠ，嘮叨讀ㄉㄠ。"},
  {id:"p551",grade:11,word:"其義自見",target:"見",zhuyin:"ㄒㄧㄢˋ",pinyin:"xiàn",wz:"ㄑㄧˊ ㄧˋ ㄗˋ ㄒㄧㄢˋ",wrong:[{z:"ㄐㄧㄢˋ",p:"jiàn"},{z:"ㄒㄧㄢˇ",p:"xiǎn"}],note:"「讀書百遍，其義自見」的「見」（顯現）讀ㄒㄧㄢˋ；「看見」讀ㄐㄧㄢˋ。",deep:"1. 注音比較\n見：ㄒㄧㄢˋ（四聲）＝其義自見、圖窮匕見（顯露，通「現」）；ㄐㄧㄢˋ（四聲）＝看見、意見、見面；ㄒㄧㄢˇ＝無此音（是「顯」的讀音，意近易混）\n2. 國字拆解與造字原因\n見：會意字，「目」＋「儿（人）」，人睜大眼睛，本義是看到（ㄐㄧㄢˋ）；古代「現」字未造之前，「顯露出來」也寫作「見」，這類文言用法保留古音ㄒㄧㄢˋ→「其義自見、才華畢見」。"},
  {id:"p552",grade:11,word:"亟需",target:"亟",zhuyin:"ㄐㄧˊ",pinyin:"jí",wz:"ㄐㄧˊ ㄒㄩ",wrong:[{z:"ㄑㄧˋ",p:"qì"},{z:"ㄐㄧˋ",p:"jì"}],note:"「亟需」「亟待解決」（急切）讀ㄐㄧˊ；「亟來問訊」（屢次）讀ㄑㄧˋ。",deep:"1. 注音比較\n亟：ㄐㄧˊ（二聲）＝亟需、亟待解決（急迫）；ㄑㄧˋ（四聲）＝亟來問訊、亟稱其善（屢次，文言）；ㄐㄧˋ＝無此音（是「既」的讀音）\n2. 國字拆解與造字原因\n亟：會意字，像人處於天地（二）之間，口與手並用，急迫應對，本義是急切→「亟需」（ㄐㄧˊ）；一次不夠、一再地做→「亟」表屢次時讀ㄑㄧˋ。急迫讀ㄐㄧˊ，屢次讀ㄑㄧˋ。"},
  {id:"p553",grade:11,word:"曲肱而枕",target:"肱",zhuyin:"ㄍㄨㄥ",pinyin:"gōng",wz:"ㄑㄩ ㄍㄨㄥ ㄦˊ ㄓㄣˇ",wrong:[{z:"ㄏㄨㄥˊ",p:"hóng"},{z:"ㄍㄨㄤ",p:"guāng"}],note:"「曲肱而枕」（彎著手臂當枕頭）的「肱」讀ㄍㄨㄥ，指上臂。",deep:"1. 注音比較\n肱：ㄍㄨㄥ（一聲）＝曲肱而枕、股肱之臣（上臂；比喻輔佐的重臣）；ㄏㄨㄥˊ＝誤讀（受「宏、弘」影響）；ㄍㄨㄤ＝無此音（是「光」的讀音）\n2. 國字拆解與造字原因\n肱：形聲字，「月（肉）」＋「厷」（聲，本就是手臂彎曲的象形）。指手肘到肩的上臂，《論語》「曲肱而枕之」寫孔子安貧樂道；「股肱」（大腿與手臂）比喻左右手般的重臣。"},
  {id:"p554",grade:11,word:"讒言",target:"讒",zhuyin:"ㄔㄢˊ",pinyin:"chán",wz:"ㄔㄢˊ ㄧㄢˊ",wrong:[{z:"ㄘㄢˊ",p:"cán"},{z:"ㄓㄢˋ",p:"zhàn"}],note:"「讒言」「進讒」（毀謗的話）讀ㄔㄢˊ，注意不要受「殘」影響誤讀。",deep:"1. 注音比較\n讒：ㄔㄢˊ（二聲）＝讒言、進讒、讒臣；ㄘㄢˊ＝誤讀（受「殘」影響）；ㄓㄢˋ＝無此音（是「站」的讀音）\n2. 國字拆解與造字原因\n讒：形聲字，「言」＋「毚」（聲，狡兔，有狡猾義）。用狡猾的言語中傷別人→「讒言」。與「饞」（貪吃）同聲符：說壞話的是「讒」（言字旁），嘴饞的是「饞」（食字旁）。"},
  {id:"p555",grade:11,word:"儕輩",target:"儕",zhuyin:"ㄔㄞˊ",pinyin:"chái",wz:"ㄔㄞˊ ㄅㄟˋ",wrong:[{z:"ㄐㄧ",p:"jī"},{z:"ㄑㄧˊ",p:"qí"}],note:"「儕輩」「吾儕」（同輩）讀ㄔㄞˊ，不要受「齊」影響誤讀。",deep:"1. 注音比較\n儕：ㄔㄞˊ（二聲）＝儕輩、吾儕、同儕；ㄐㄧ＝無此音（受「齏」影響）；ㄑㄧˊ＝誤讀（受聲符「齊」影響）\n2. 國字拆解與造字原因\n儕：形聲字，「亻」＋「齊」（聲）。「齊」有整齊、相等的意思，地位年紀相等的人＝同輩→「同儕、吾儕（我們這些人）」。聲符「齊」在此轉讀ㄔㄞˊ，是易誤讀的形聲字。"},
  {id:"p556",grade:11,word:"攛掇",target:"攛",zhuyin:"ㄘㄨㄢ",pinyin:"cuān",wz:"ㄘㄨㄢ ㄉㄨㄛ",wrong:[{z:"ㄗㄨㄢ",p:"zuān"},{z:"ㄘㄨㄢˋ",p:"cuàn"}],note:"「攛掇」（慫恿）讀ㄘㄨㄢ ˙ㄉㄨㄛ。",deep:"1. 注音比較\n攛：ㄘㄨㄢ（一聲）＝攛掇（慫恿、鼓動別人做某事）；ㄗㄨㄢ＝無此音（是「鑽」的讀音之一）；ㄘㄨㄢˋ＝無此音（是「竄」的讀音）\n2. 國字拆解與造字原因\n攛：形聲字，「扌（手）」＋「竄」（聲）。用手把人「推」往某個方向＝從旁鼓動、慫恿→「攛掇他去比賽」。「掇」本義是拾取，「攛掇」合成連綿詞，在口語中「掇」讀輕聲。"},
  {id:"p557",grade:11,word:"囁嚅",target:"囁",zhuyin:"ㄋㄧㄝˋ",pinyin:"niè",wz:"ㄋㄧㄝˋ ㄖㄨˊ",wrong:[{z:"ㄖㄨˊ",p:"rú"},{z:"ㄕㄜˋ",p:"shè"}],note:"「囁嚅」（想說又不敢說）讀ㄋㄧㄝˋ ㄖㄨˊ。",deep:"1. 注音比較\n囁：ㄋㄧㄝˋ（四聲）＝囁嚅（吞吞吐吐、欲言又止）；ㄖㄨˊ＝那是「嚅」的讀音；ㄕㄜˋ＝無此音（是「攝」的讀音，同聲符易混）\n2. 國字拆解與造字原因\n囁：形聲字，「口」＋「聶」（聲）。「聶」是附耳小語，嘴巴像在耳邊細語般張張合合、話到嘴邊又縮回去→「囁嚅」。與「躡」（放輕腳步）同聲符：口的是囁、足的是躡，都有「輕、小」的意思。"},
  {id:"p558",grade:11,word:"囤積",target:"囤",zhuyin:"ㄊㄨㄣˊ",pinyin:"tún",wz:"ㄊㄨㄣˊ ㄐㄧ",wrong:[{z:"ㄉㄨㄣˋ",p:"dùn"},{z:"ㄊㄨㄣ",p:"tūn"}],note:"「囤積」「囤貨」（儲存）讀ㄊㄨㄣˊ；當名詞「糧囤」讀ㄉㄨㄣˋ。",deep:"1. 注音比較\n囤：ㄊㄨㄣˊ（二聲）＝囤積、囤貨（動詞，儲存）；ㄉㄨㄣˋ（四聲）＝糧囤（名詞，存糧的器具）；ㄊㄨㄣ＝無此音（是「吞」的讀音）\n2. 國字拆解與造字原因\n囤：形聲字，「囗（圍）」＋「屯」（聲，「屯」本義是聚集）。把糧食圍聚起來存放：儲存的動作讀ㄊㄨㄣˊ（囤積居奇）；用竹篾圍成的存糧器具讀ㄉㄨㄣˋ（大糧囤）。動詞ㄊㄨㄣˊ、名詞ㄉㄨㄣˋ。"},
  {id:"p559",grade:11,word:"齲齒",target:"齲",zhuyin:"ㄑㄩˇ",pinyin:"qǔ",wz:"ㄑㄩˇ ㄔˇ",wrong:[{z:"ㄩˇ",p:"yǔ"},{z:"ㄡˇ",p:"ǒu"}],note:"「齲齒」（蛀牙）讀ㄑㄩˇ。",deep:"1. 注音比較\n齲：ㄑㄩˇ（三聲）＝齲齒（蛀牙的正式名稱）；ㄩˇ＝誤讀（受「禹」影響）；ㄡˇ＝無此音（是「偶」的讀音）\n2. 國字拆解與造字原因\n齲：形聲字，「齒」＋「禹」（聲）。牙齒被蛀出洞來的病＝「齲齒」。從「齒」部可知與牙齒有關；聲符「禹」在此讀ㄑㄩˇ，是醫學常用而易誤讀的字。"},
  {id:"p560",grade:11,word:"麾下",target:"麾",zhuyin:"ㄏㄨㄟ",pinyin:"huī",wz:"ㄏㄨㄟ ㄒㄧㄚˋ",wrong:[{z:"ㄇㄛˊ",p:"mó"},{z:"ㄇㄧˊ",p:"mí"}],note:"「麾下」（部下）「麾軍」讀ㄏㄨㄟ，不要受「摩、魔」影響誤讀。",deep:"1. 注音比較\n麾：ㄏㄨㄟ（一聲）＝麾下、麾軍前進（指揮旗；指揮）；ㄇㄛˊ＝誤讀（受「摩」影響）；ㄇㄧˊ＝無此音（是「彌」的讀音）\n2. 國字拆解與造字原因\n麾：形聲字，「毛」＋「麻（省）」（聲）。本義是主將指揮軍隊用的旗幟，將旗所在＝主帥身邊→「麾下」尊稱將帥，也代稱其部屬；揮動旗子發令→「麾軍」。與「揮」音同義近（都有揮動義）。"},
  {id:"p561",grade:11,word:"淵藪",target:"藪",zhuyin:"ㄙㄡˇ",pinyin:"sǒu",wz:"ㄩㄢ ㄙㄡˇ",wrong:[{z:"ㄕㄨˋ",p:"shù"},{z:"ㄙㄡ",p:"sōu"}],note:"「淵藪」（人或物聚集之處）讀ㄩㄢ ㄙㄡˇ。",deep:"1. 注音比較\n藪：ㄙㄡˇ（三聲）＝淵藪（淵＝魚所聚，藪＝獸所聚，合指聚集地）；ㄕㄨˋ＝無此音（是「樹」的讀音）；ㄙㄡ＝誤讀（受「搜」影響，聲調錯誤）\n2. 國字拆解與造字原因\n藪：形聲字，「艹」＋「數」（聲）。本義是水少草木茂盛的沼澤，野獸聚居其中→引申為人事物匯聚的地方→「罪惡的淵藪」。記法：草多獸聚為「藪」，水深魚聚為「淵」。"},
  {id:"p562",grade:11,word:"剽竊",target:"剽",zhuyin:"ㄆㄧㄠˋ",pinyin:"piào",wz:"ㄆㄧㄠˋ ㄑㄧㄝˋ",wrong:[{z:"ㄆㄧㄠ",p:"piāo"},{z:"ㄅㄧㄠ",p:"biāo"}],note:"「剽竊」「剽悍」讀ㄆㄧㄠˋ（四聲），常被誤讀成一聲。",deep:"1. 注音比較\n剽：ㄆㄧㄠˋ（四聲）＝剽竊（抄襲盜用）、剽悍（敏捷勇猛）；ㄆㄧㄠ＝誤讀（受「漂、飄」影響）；ㄅㄧㄠ＝無此音（是「標」的讀音）\n2. 國字拆解與造字原因\n剽：形聲字，「刂（刀）」＋「票」（聲，「票」有輕捷義）。持刀快速搶劫，本義是搶奪→搶別人的文章成果＝「剽竊」；動作輕疾勇猛＝「剽悍」。從刀部表劫奪，讀四聲ㄆㄧㄠˋ。"},
  {id:"p563",grade:11,word:"縝密",target:"縝",zhuyin:"ㄓㄣˇ",pinyin:"zhěn",wz:"ㄓㄣˇ ㄇㄧˋ",wrong:[{z:"ㄕㄣˋ",p:"shèn"},{z:"ㄓㄣ",p:"zhēn"}],note:"「縝密」（周密細緻）讀ㄓㄣˇ，不要受「慎」影響誤讀。",deep:"1. 注音比較\n縝：ㄓㄣˇ（三聲）＝縝密（思慮周密）；ㄕㄣˋ＝誤讀（受「慎」影響，「慎密」是另一詞）；ㄓㄣ＝誤讀（受「真」影響，聲調錯誤）\n2. 國字拆解與造字原因\n縝：形聲字，「糸（絲）」＋「真」（聲）。絲線織得細密無縫，本義是細緻→「心思縝密」。從糸部表示與絲織有關——織物越細密越好，思考如織布，滴水不漏。"},
  {id:"p564",grade:11,word:"旖旎",target:"旖",zhuyin:"ㄧˇ",pinyin:"yǐ",wz:"ㄧˇ ㄋㄧˇ",wrong:[{z:"ㄑㄧˊ",p:"qí"},{z:"ㄧ",p:"yī"}],note:"「旖旎」（柔美的樣子）讀ㄧˇ ㄋㄧˇ，如「風光旖旎」。",deep:"1. 注音比較\n旖：ㄧˇ（三聲）＝旖旎（柔和美好，多形容風光）；ㄑㄧˊ＝誤讀（受「奇」影響）；ㄧ＝誤讀（聲調錯誤）\n2. 國字拆解與造字原因\n旖：形聲字，「㫃（旗幟）」＋「奇」（聲）。本義是旌旗隨風柔順飄動的樣子，「旖旎」連用形容柔美婉轉→「風光旖旎」。從旗幟的柔垂引申到景色的柔美。"},
  {id:"p565",grade:11,word:"下自成蹊",target:"蹊",zhuyin:"ㄒㄧ",pinyin:"xī",wz:"ㄒㄧㄚˋ ㄗˋ ㄔㄥˊ ㄒㄧ",wrong:[{z:"ㄑㄧ",p:"qī"},{z:"ㄒㄧˊ",p:"xí"}],note:"「桃李不言，下自成蹊」的「蹊」（小路）讀ㄒㄧ。",deep:"1. 注音比較\n蹊：ㄒㄧ（一聲）＝成蹊、蹊徑（小路）、蹊蹺；ㄑㄧ＝誤讀（受「奚」影響）；ㄒㄧˊ＝誤讀（聲調錯誤）\n2. 國字拆解與造字原因\n蹊：形聲字，「足」＋「奚」（聲）。腳走出來的小路→「桃李不言，下自成蹊」：桃樹李樹不會說話，因果實甜美，樹下自然被人踩出小路，比喻德行高的人自然受人景仰。"},
  {id:"p566",grade:11,word:"惴惴不安",target:"惴",zhuyin:"ㄓㄨㄟˋ",pinyin:"zhuì",wz:"ㄓㄨㄟˋ ㄓㄨㄟˋ ㄅㄨˋ ㄢ",wrong:[{z:"ㄔㄨㄞˇ",p:"chuǎi"},{z:"ㄉㄨㄢ",p:"duān"}],note:"「惴惴不安」（憂懼）讀ㄓㄨㄟˋ，不要與「揣」（ㄔㄨㄞˇ）相混。",deep:"1. 注音比較\n惴：ㄓㄨㄟˋ（四聲）＝惴惴不安、惴慄（憂愁恐懼）；ㄔㄨㄞˇ＝那是「揣」的讀音（揣測），形近易混；ㄉㄨㄢ＝無此音（是「端」的讀音，同聲符）\n2. 國字拆解與造字原因\n惴：形聲字，「忄（心）」＋「耑」（聲）。心裡七上八下、憂懼不定→「惴惴不安」。與「揣」（扌，用手估量）、「湍」（氵，急流）同聲符，靠部首分辨：心裡怕是惴、手裡量是揣、水裡急是湍。"},
  {id:"p567",grade:11,word:"罹難",target:"罹",zhuyin:"ㄌㄧˊ",pinyin:"lí",wz:"ㄌㄧˊ ㄋㄢˋ",wrong:[{z:"ㄌㄨㄛˊ",p:"luó"},{z:"ㄌㄧˋ",p:"lì"}],note:"「罹難」「罹患」（遭遇不幸）讀ㄌㄧˊ，不要受「羅」影響誤讀。",deep:"1. 注音比較\n罹：ㄌㄧˊ（二聲）＝罹難、罹患、罹禍（遭受）；ㄌㄨㄛˊ＝誤讀（受「羅」影響，形近）；ㄌㄧˋ＝誤讀（聲調錯誤）\n2. 國字拆解與造字原因\n罹：從「网（罒，網子）」從「惟」。像鳥被網罩住，本義是遭受、陷入（不幸）→「罹難（遭遇災禍死亡）、罹患疾病」。記法：被「網」罩住＝逃不開的不幸。"},
  {id:"p568",grade:11,word:"岑寂",target:"岑",zhuyin:"ㄘㄣˊ",pinyin:"cén",wz:"ㄘㄣˊ ㄐㄧˊ",wrong:[{z:"ㄐㄧㄣ",p:"jīn"},{z:"ㄑㄧㄣˊ",p:"qín"}],note:"「岑寂」（寂靜）讀ㄘㄣˊ ㄐㄧˊ。",deep:"1. 注音比較\n岑：ㄘㄣˊ（二聲）＝岑寂（高而靜；寂靜）、姓氏（岑參）；ㄐㄧㄣ＝無此音（是「今」的讀音，同聲符易混）；ㄑㄧㄣˊ＝無此音（是「琴」的讀音）\n2. 國字拆解與造字原因\n岑：形聲字，「山」＋「今」（聲）。本義是小而高的山。山高人跡罕至，四下無聲→「岑寂」。唐代邊塞詩人「岑參」（ㄘㄣˊ ㄕㄣ）的姓即此字，兩個字都常被誤讀。"},
  {id:"p569",grade:11,word:"疏浚",target:"浚",zhuyin:"ㄐㄩㄣˋ",pinyin:"jùn",wz:"ㄕㄨ ㄐㄩㄣˋ",wrong:[{z:"ㄙㄨㄛˋ",p:"suò"},{z:"ㄑㄩㄢˊ",p:"quán"}],note:"「疏浚」（深挖河道）讀ㄐㄩㄣˋ。",deep:"1. 注音比較\n浚：ㄐㄩㄣˋ（四聲）＝疏浚河道、浚渫（深挖清理水道）；ㄙㄨㄛˋ＝無此音（受「梭」影響）；ㄑㄩㄢˊ＝無此音（是「泉」的讀音）\n2. 國字拆解與造字原因\n浚：形聲字，「氵（水）」＋「夋」（聲）。把水道挖深、淘除淤泥使水流通暢→「疏浚」。與「峻」（山高）、「駿」（馬快）同聲符，都有「高、深、快」的極致義：水深是浚、山高是峻。"},
  {id:"p570",grade:11,word:"踽踽獨行",target:"踽",zhuyin:"ㄐㄩˇ",pinyin:"jǔ",wz:"ㄐㄩˇ ㄐㄩˇ ㄉㄨˊ ㄒㄧㄥˊ",wrong:[{z:"ㄩˇ",p:"yǔ"},{z:"ㄍㄨˇ",p:"gǔ"}],note:"「踽踽獨行」（孤獨行走）讀ㄐㄩˇ。",deep:"1. 注音比較\n踽：ㄐㄩˇ（三聲）＝踽踽獨行（孤零零走路的樣子）；ㄩˇ＝誤讀（受「禹」影響）；ㄍㄨˇ＝無此音（是「古」的讀音）\n2. 國字拆解與造字原因\n踽：形聲字，「足」＋「禹」（聲）。一個人孤單走路、無人相伴的樣子，疊用「踽踽」加強孤獨感→「踽踽獨行」。從足部表示與行走有關。"},
  {id:"p571",grade:11,word:"殫精竭慮",target:"殫",zhuyin:"ㄉㄢ",pinyin:"dān",wz:"ㄉㄢ ㄐㄧㄥ ㄐㄧㄝˊ ㄌㄩˋ",wrong:[{z:"ㄊㄢˊ",p:"tán"},{z:"ㄓㄢˋ",p:"zhàn"}],note:"「殫精竭慮」（用盡心力）的「殫」讀ㄉㄢ，不要受「彈」影響誤讀。",deep:"1. 注音比較\n殫：ㄉㄢ（一聲）＝殫精竭慮、殫思極慮（竭盡）；ㄊㄢˊ＝誤讀（受「彈、譚」影響）；ㄓㄢˋ＝無此音（是「戰」的讀音）\n2. 國字拆解與造字原因\n殫：形聲字，「歹（死亡、盡）」＋「單」（聲）。「歹」部表示到了盡頭，本義是竭盡→「殫精竭慮」＝把精神心思用到一點不剩。與「簞」（竹器）、「憚」（畏懼）同聲符，靠部首分辨。"},
  {id:"p572",grade:11,word:"饜足",target:"饜",zhuyin:"ㄧㄢˋ",pinyin:"yàn",wz:"ㄧㄢˋ ㄗㄨˊ",wrong:[{z:"ㄧㄢ",p:"yān"},{z:"ㄧㄥˋ",p:"yìng"}],note:"「饜足」「貪得無饜」（滿足）讀ㄧㄢˋ，同「厭」的本義。",deep:"1. 注音比較\n饜：ㄧㄢˋ（四聲）＝饜足、貪得無饜（吃飽；滿足）；ㄧㄢ＝誤讀（聲調錯誤）；ㄧㄥˋ＝無此音（是「應」的讀音之一）\n2. 國字拆解與造字原因\n饜：形聲字，「食」＋「厭」（聲）。「厭」的本義就是吃飽（甘＋肉＋犬），後來「厭」轉指討厭，另造從「食」的「饜」保留「飽足」本義→「饜足」；「貪得無饜」也作「貪得無厭」，指貪心永遠餵不飽。"},
  {id:"p573",grade:11,word:"濯足",target:"濯",zhuyin:"ㄓㄨㄛˊ",pinyin:"zhuó",wz:"ㄓㄨㄛˊ ㄗㄨˊ",wrong:[{z:"ㄉㄧˊ",p:"dí"},{z:"ㄧㄠˋ",p:"yào"}],note:"「濯足」「洗濯」（洗滌）讀ㄓㄨㄛˊ，〈漁父〉「可以濯吾足」即此字。",deep:"1. 注音比較\n濯：ㄓㄨㄛˊ（二聲）＝濯足、洗濯、濯清漣而不妖；ㄉㄧˊ＝那是「滌」的讀音（洗滌），意同音異；ㄧㄠˋ＝無此音（受「躍」影響）\n2. 國字拆解與造字原因\n濯：形聲字，「氵（水）」＋「翟」（聲）。用水清洗→「濯足（洗腳）」；〈愛蓮說〉「濯清漣而不妖」、〈漁父〉「滄浪之水清兮，可以濯吾纓」都用此字，是文言常見字。"},
  {id:"p574",grade:11,word:"訃聞",target:"訃",zhuyin:"ㄈㄨˋ",pinyin:"fù",wz:"ㄈㄨˋ ㄨㄣˊ",wrong:[{z:"ㄆㄨ",p:"pū"},{z:"ㄅㄨˇ",p:"bǔ"}],note:"「訃聞」「訃告」（報喪的通知）讀ㄈㄨˋ。",deep:"1. 注音比較\n訃：ㄈㄨˋ（四聲）＝訃聞、訃告（通報喪事的文書）；ㄆㄨ＝誤讀（受「仆」影響）；ㄅㄨˇ＝無此音（是「卜」的讀音，同聲符易混）\n2. 國字拆解與造字原因\n訃：形聲字，「言」＋「卜」（聲）。用言語文字通報死訊→「訃聞」。從言部表示是一種「告知」；聲符「卜」在此讀ㄈㄨˋ。"},
  {id:"p575",grade:11,word:"饋贈",target:"饋",zhuyin:"ㄎㄨㄟˋ",pinyin:"kuì",wz:"ㄎㄨㄟˋ ㄗㄥˋ",wrong:[{z:"ㄍㄨㄟˋ",p:"guì"},{z:"ㄎㄨㄟ",p:"kuī"}],note:"「饋贈」「回饋」讀ㄎㄨㄟˋ，不要受「貴」影響誤讀。",deep:"1. 注音比較\n饋：ㄎㄨㄟˋ（四聲）＝饋贈、回饋、饋線；ㄍㄨㄟˋ＝誤讀（受「貴」影響）；ㄎㄨㄟ＝誤讀（聲調錯誤，是「虧」的讀音）\n2. 國字拆解與造字原因\n饋：形聲字，「食」＋「貴」（聲）。本義是送食物給人→泛指贈送→「饋贈」；受人好處而回報→「回饋」。從食部可知原與送食有關，古人以食物為最常見的餽贈（「餽」為異體）。"},
  {id:"p576",grade:12,word:"芻議",target:"芻",zhuyin:"ㄔㄨˊ",pinyin:"chú",wz:"ㄔㄨˊ ㄧˋ",wrong:[{z:"ㄗㄡ",p:"zōu"},{z:"ㄘㄡˋ",p:"còu"}],note:"「芻議」（謙稱自己的議論）「反芻」讀ㄔㄨˊ。",deep:"1. 注音比較\n芻：ㄔㄨˊ（二聲）＝芻議（謙稱淺見）、反芻、芻豢；ㄗㄡ＝無此音（受「鄒」影響）；ㄘㄡˋ＝無此音（是「湊」的讀音）\n2. 國字拆解與造字原因\n芻：象形字，像手抓斷草的樣子，本義是割草、餵牲口的草→「反芻（牛羊把草吐回口中再嚼）」；割草人的議論＝微不足道的意見→「芻議」，是發表意見時的自謙語。"},
  {id:"p577",grade:12,word:"賡續",target:"賡",zhuyin:"ㄍㄥ",pinyin:"gēng",wz:"ㄍㄥ ㄒㄩˋ",wrong:[{z:"ㄍㄥˋ",p:"gèng"},{z:"ㄩㄥ",p:"yōng"}],note:"「賡續」（繼續）讀ㄍㄥ，公文常用字。",deep:"1. 注音比較\n賡：ㄍㄥ（一聲）＝賡續辦理（接續）、賡和（以詩歌相酬答）；ㄍㄥˋ＝誤讀（受「更」影響，聲調錯誤）；ㄩㄥ＝無此音（是「庸」的讀音）\n2. 國字拆解與造字原因\n賡：會意字，古文「續」的異體，從「庚」從「貝」。本義就是連續、接續→「賡續」；文人以詩互相接續唱和→「賡和」。今多見於公文「賡續辦理」，讀ㄍㄥ不讀ㄍㄥˋ。"},
  {id:"p578",grade:12,word:"菜畦",target:"畦",zhuyin:"ㄑㄧˊ",pinyin:"qí",wz:"ㄘㄞˋ ㄑㄧˊ",wrong:[{z:"ㄒㄧˊ",p:"xí"},{z:"ㄨㄚ",p:"wā"}],note:"教育部審訂音「畦」只有一個讀音ㄑㄧˊ：菜畦、稻畦、瓜畦都讀ㄑㄧˊ。",deep:"1. 注音比較\n畦：ㄑㄧˊ＝菜畦、稻畦、瓜畦、千畦薑韭。★教育部《國語辭典簡編本》「畦」只收ㄑㄧˊ一音，讀成ㄒㄧˊ不是審訂音\n2. 國字拆解與造字原因\n畦：形聲字，「田」＋「圭」（聲）。田地劃分成一格一格的長條小區塊，方便播種和灌溉，種菜的那一畦就叫「菜畦」。從田部，因為講的是田地。"},
  {id:"p579",grade:12,word:"良莠不齊",target:"莠",zhuyin:"ㄧㄡˋ",pinyin:"yòu",wz:"ㄌㄧㄤˊ ㄧㄡˋ ㄅㄨˋ ㄑㄧˊ",wrong:[{z:"ㄧㄡˇ",p:"yǒu"},{z:"ㄒㄧㄡˋ",p:"xiù"}],note:"教育部審訂音「良莠不齊」的「莠」讀ㄧㄡˋ（四聲），指狗尾草。",deep:"1. 注音比較\n莠：ㄧㄡˋ＝良莠不齊、莠民、莠言。★教育部《國語辭典簡編本》「莠」只收四聲ㄧㄡˋ，讀成三聲ㄧㄡˇ不是審訂音\n2. 國字拆解與造字原因\n莠：形聲字，「艹」＋「秀」（聲），本指狗尾草——長得很像禾苗卻不結穀的雜草，混在莊稼裡不容易分辨，所以用來比喻壞人。「良莠不齊」就是好人壞人摻雜在一起。"},
  {id:"p580",grade:12,word:"炙手可熱",target:"炙",zhuyin:"ㄓˋ",pinyin:"zhì",wz:"ㄓˋ ㄕㄡˇ ㄎㄜˇ ㄖㄜˋ",wrong:[{z:"ㄉㄨㄛˋ",p:"duò"},{z:"ㄐㄧㄡˇ",p:"jiǔ"}],note:"「炙手可熱」「膾炙人口」的「炙」（烤）讀ㄓˋ，字形是肉在火上。",deep:"1. 注音比較\n炙：ㄓˋ（四聲）＝炙手可熱、膾炙人口、炙燒（烤）；ㄉㄨㄛˋ＝無此音（是「跺」的讀音）；ㄐㄧㄡˇ＝那是「灸」的讀音（針灸），兩字形近最易混\n2. 國字拆解與造字原因\n炙：會意字，「月（肉）」在「火」上，把肉放在火上烤，本義是烤肉。「炙手可熱」＝手一靠近就燙，比喻權勢氣焰之盛。辨字：上面是「肉」的是炙（烤），上面是「久」的是灸（中醫艾灸）。"},
  {id:"p581",grade:12,word:"掮客",target:"掮",zhuyin:"ㄑㄧㄢˊ",pinyin:"qián",wz:"ㄑㄧㄢˊ ㄎㄜˋ",wrong:[{z:"ㄐㄧㄢ",p:"jiān"},{z:"ㄑㄧㄢˇ",p:"qiǎn"}],note:"「掮客」（居間牟利的中間人）讀ㄑㄧㄢˊ。",deep:"1. 注音比較\n掮：ㄑㄧㄢˊ（二聲）＝掮客（替人介紹買賣、從中取利的人）；ㄐㄧㄢ＝誤讀（受「肩」影響）；ㄑㄧㄢˇ＝誤讀（聲調錯誤）\n2. 國字拆解與造字原因\n掮：形聲字，「扌（手）」＋「肩」（聲）。本義是用肩扛東西（方言），替人「扛著」貨物到處兜售撮合的人→「掮客」，今多帶貶義（政治掮客）。"},
  {id:"p582",grade:12,word:"勖勉",target:"勖",zhuyin:"ㄒㄩˋ",pinyin:"xù",wz:"ㄒㄩˋ ㄇㄧㄢˇ",wrong:[{z:"ㄇㄠˋ",p:"mào"},{z:"ㄒㄩ",p:"xū"}],note:"「勖勉」（勉勵）讀ㄒㄩˋ，常見於長輩對晚輩的期許。",deep:"1. 注音比較\n勖：ㄒㄩˋ（四聲）＝勖勉、勖勵（勉勵）；ㄇㄠˋ＝誤讀（受「冒」影響，形近）；ㄒㄩ＝誤讀（聲調錯誤）\n2. 國字拆解與造字原因\n勖：形聲字，「力」＋「冒」（聲）。用力向前、鼓舞人努力→「勖勉」。從「力」部表示與用力、勉力有關；雖然左邊是「冒」，讀音卻是ㄒㄩˋ，是典型的「有邊讀邊」陷阱字。"},
  {id:"p583",grade:12,word:"暌違",target:"暌",zhuyin:"ㄎㄨㄟˊ",pinyin:"kuí",wz:"ㄎㄨㄟˊ ㄨㄟˊ",wrong:[{z:"ㄍㄨㄟ",p:"guī"},{z:"ㄎㄨㄟˋ",p:"kuì"}],note:"「暌違」（分離、久別）讀ㄎㄨㄟˊ，書信常用「暌違日久」。",deep:"1. 注音比較\n暌：ㄎㄨㄟˊ（二聲）＝暌違（分離不見）；ㄍㄨㄟ＝誤讀（受「規」影響）；ㄎㄨㄟˋ＝誤讀（聲調錯誤，是「愧」的讀音）\n2. 國字拆解與造字原因\n暌：形聲字，「日」＋「癸」（聲）。本義是日落之處與日出相背，引申為分隔兩地、彼此不相見→「暌違已久」＝分別很久了，是書信問候的雅語。"},
  {id:"p584",grade:12,word:"不啻",target:"啻",zhuyin:"ㄔˋ",pinyin:"chì",wz:"ㄅㄨˋ ㄔˋ",wrong:[{z:"ㄉㄧˋ",p:"dì"},{z:"ㄊㄧˊ",p:"tí"}],note:"「不啻」（無異於、不只）讀ㄔˋ，如「不啻天壤之別」。",deep:"1. 注音比較\n啻：ㄔˋ（四聲）＝不啻（不只、無異於）、何啻；ㄉㄧˋ＝誤讀（受「帝」影響）；ㄊㄧˊ＝無此音（是「啼」的讀音，形近易混）\n2. 國字拆解與造字原因\n啻：形聲字，「口」＋「帝」（聲）。本義是「只、僅」，多用於否定句→「不啻」＝不只是、簡直等於（這消息不啻晴天霹靂）。與「啼」形近：口在下是啻、口在左是啼。"},
  {id:"p585",grade:12,word:"橫亙",target:"亙",zhuyin:"ㄍㄣˋ",pinyin:"gèn",wz:"ㄏㄥˊ ㄍㄣˋ",wrong:[{z:"ㄒㄩㄢ",p:"xuān"},{z:"ㄏㄥˊ",p:"héng"}],note:"「橫亙」「亙古」（綿延、貫穿）讀ㄍㄣˋ。",deep:"1. 注音比較\n亙：ㄍㄣˋ（四聲）＝橫亙、亙古不變（綿延不斷）；ㄒㄩㄢ＝那是「宣」的部件「亘」（ㄒㄩㄢ）的讀音，兩形極易相混；ㄏㄥˊ＝無此音（是「橫」的讀音）\n2. 國字拆解與造字原因\n亙：會意字，上下兩橫代表天地兩端，中間貫通，本義是從這頭連到那頭→「山脈橫亙、亙古（貫穿古今）」。辨字：中間是「日」的「亘」讀ㄒㄩㄢ（宣的偏旁），中間封口的「亙」讀ㄍㄣˋ。"},
  {id:"p586",grade:12,word:"龜茲",target:"茲",zhuyin:"ㄘˊ",pinyin:"cí",wz:"ㄑㄧㄡ ㄘˊ",wrong:[{z:"ㄗ",p:"zī"},{z:"ㄐㄧㄡ",p:"jiū"}],note:"「龜茲」（古西域國名）讀ㄑㄧㄡ ㄘˊ；「茲事體大」的「茲」讀ㄗ。",deep:"1. 注音比較\n茲：ㄘˊ（二聲）＝龜茲（古西域國，「龜」在此讀ㄑㄧㄡ）；ㄗ（一聲）＝茲事體大、於茲、來茲；ㄐㄧㄡ＝無此音（受「鳩」影響）\n2. 國字拆解與造字原因\n茲：從「艹（絲）」，本義是草木滋生，借作代詞「此」→「茲事體大」（ㄗ）；「龜茲」是西域古國（今新疆庫車）的音譯名，兩字都用特殊讀音：龜ㄑㄧㄡ、茲ㄘˊ，是史地科目著名的難讀專名。"},
  {id:"p587",grade:12,word:"窮兵黷武",target:"黷",zhuyin:"ㄉㄨˊ",pinyin:"dú",wz:"ㄑㄩㄥˊ ㄅㄧㄥ ㄉㄨˊ ㄨˇ",wrong:[{z:"ㄉㄨˋ",p:"dù"},{z:"ㄕㄨˇ",p:"shǔ"}],note:"「窮兵黷武」（濫用武力）的「黷」讀ㄉㄨˊ。",deep:"1. 注音比較\n黷：ㄉㄨˊ（二聲）＝窮兵黷武（好戰不休）、褻黷；ㄉㄨˋ＝誤讀（聲調錯誤，受「度」影響）；ㄕㄨˇ＝無此音（是「屬」的讀音之一）\n2. 國字拆解與造字原因\n黷：形聲字，「黑」＋「賣」（聲）。本義是污黑、玷污→輕慢濫用→「黷武」＝把用兵當兒戲、濫動干戈。從「黑」部表示弄髒；「窮兵黷武」的「窮」是用盡之意。"},
  {id:"p588",grade:12,word:"罅隙",target:"罅",zhuyin:"ㄒㄧㄚˋ",pinyin:"xià",wz:"ㄒㄧㄚˋ ㄒㄧˋ",wrong:[{z:"ㄏㄨˋ",p:"hù"},{z:"ㄒㄧㄚ",p:"xiā"}],note:"「罅隙」（裂縫）讀ㄒㄧㄚˋ ㄒㄧˋ。",deep:"1. 注音比較\n罅：ㄒㄧㄚˋ（四聲）＝罅隙、石罅（裂縫）；ㄏㄨˋ＝無此音（受「乎」影響）；ㄒㄧㄚ＝誤讀（聲調錯誤，是「蝦」的讀音）\n2. 國字拆解與造字原因\n罅：形聲字，「缶（瓦器）」＋「虖」（聲）。瓦器燒製或碰撞後出現的裂縫，本義是器物的裂痕→泛指縫隙→「罅隙」，也比喻感情或制度的漏洞。從「缶」部可知本與陶器有關。"},
  {id:"p589",grade:12,word:"鐫刻",target:"鐫",zhuyin:"ㄐㄩㄢ",pinyin:"juān",wz:"ㄐㄩㄢ ㄎㄜˋ",wrong:[{z:"ㄒㄧ",p:"xī"},{z:"ㄐㄩㄢˋ",p:"juàn"}],note:"「鐫刻」（雕刻）讀ㄐㄩㄢ，如「鐫刻在心版上」。",deep:"1. 注音比較\n鐫：ㄐㄩㄢ（一聲）＝鐫刻、鐫印（雕鑿）；ㄒㄧ＝無此音（受「巂」形影響）；ㄐㄩㄢˋ＝誤讀（聲調錯誤，是「倦」的讀音）\n2. 國字拆解與造字原因\n鐫：形聲字，「金」＋「雋」（聲）。用金屬工具在硬物上雕鑿文字圖案→「鐫刻」；比喻深深記住→「鐫刻在心」。從金部表示與金屬工具有關，讀一聲ㄐㄩㄢ。"},
  {id:"p590",grade:12,word:"杳無音信",target:"杳",zhuyin:"ㄧㄠˇ",pinyin:"yǎo",wz:"ㄧㄠˇ ㄨˊ ㄧㄣ ㄒㄧㄣˋ",wrong:[{z:"ㄇㄧㄠˇ",p:"miǎo"},{z:"ㄇㄨˋ",p:"mù"}],note:"「杳無音信」「杳然」（毫無蹤影）讀ㄧㄠˇ，字形是日落木下。",deep:"1. 注音比較\n杳：ㄧㄠˇ（三聲）＝杳無音信、杳然無蹤（深遠不見蹤影）；ㄇㄧㄠˇ＝那是「渺」的讀音（渺茫），義近音異易混；ㄇㄨˋ＝無此音（是「木、目」的讀音）\n2. 國字拆解與造字原因\n杳：會意字，「日」沉到「木」（樹）下面，天色昏暗深遠，本義是幽暗深遠→看不見、沒消息→「杳無音信」。對比字：「杲」（ㄍㄠˇ）是日在木上＝明亮；日在木下＝杳（昏暗），一上一下意思相反。"},
  {id:"p591",grade:12,word:"宵衣旰食",target:"旰",zhuyin:"ㄍㄢˋ",pinyin:"gàn",wz:"ㄒㄧㄠ ㄧ ㄍㄢˋ ㄕˊ",wrong:[{z:"ㄏㄢˋ",p:"hàn"},{z:"ㄍㄢ",p:"gān"}],note:"「宵衣旰食」（天未亮就穿衣、天黑才吃飯，形容勤於政事）的「旰」讀ㄍㄢˋ。",deep:"1. 注音比較\n旰：ㄍㄢˋ（四聲）＝宵衣旰食（旰＝天色晚）；ㄏㄢˋ＝誤讀（受「汗、旱」影響）；ㄍㄢ＝誤讀（聲調錯誤，是「乾」的讀音）\n2. 國字拆解與造字原因\n旰：形聲字，「日」＋「干」（聲）。本義是天色已晚→「旰食」＝忙到天黑才吃飯；「宵衣」＝天沒亮就起床穿衣。整個成語形容君王或官員勤勞政事，是高中常見的文化語彙。"},
  {id:"p592",grade:12,word:"弭平",target:"弭",zhuyin:"ㄇㄧˇ",pinyin:"mǐ",wz:"ㄇㄧˇ ㄆㄧㄥˊ",wrong:[{z:"ㄦˇ",p:"ěr"},{z:"ㄇㄧˊ",p:"mí"}],note:"「弭平」「消弭」（平息）讀ㄇㄧˇ，不要受「彌」影響誤讀為二聲。",deep:"1. 注音比較\n弭：ㄇㄧˇ（三聲）＝弭平爭端、消弭（平息、停止）；ㄦˇ＝誤讀（受「耳」影響）；ㄇㄧˊ＝誤讀（受「彌」影響，聲調錯誤）\n2. 國字拆解與造字原因\n弭：從「弓」從「耳」，本義是弓的末端（弓弭），把弓放下＝停止戰事→「弭兵、消弭、弭平」。辨字：「彌」（彌漫、彌補）讀ㄇㄧˊ二聲，「弭」（平息）讀ㄇㄧˇ三聲，形近音異。"},
  {id:"p593",grade:12,word:"痼疾",target:"痼",zhuyin:"ㄍㄨˋ",pinyin:"gù",wz:"ㄍㄨˋ ㄐㄧˊ",wrong:[{z:"ㄍㄨ",p:"gū"},{z:"ㄎㄨˋ",p:"kù"}],note:"「痼疾」（久治不癒的病）讀ㄍㄨˋ，如「積習成痼」。",deep:"1. 注音比較\n痼：ㄍㄨˋ（四聲）＝痼疾、痼習（長久難改）；ㄍㄨ＝誤讀（聲調錯誤，受「孤」影響）；ㄎㄨˋ＝無此音（是「酷」的讀音）\n2. 國字拆解與造字原因\n痼：形聲字，「疒（病）」＋「固」（聲）。「固」有牢固之意——牢牢黏在身上、醫不好的病→「痼疾」；引申指根深柢固的壞習慣→「痼習」。病字旁＋固＝頑固的病。"},
  {id:"p594",grade:12,word:"詬病",target:"詬",zhuyin:"ㄍㄡˋ",pinyin:"gòu",wz:"ㄍㄡˋ ㄅㄧㄥˋ",wrong:[{z:"ㄏㄡˋ",p:"hòu"},{z:"ㄍㄡ",p:"gōu"}],note:"「詬病」「詬罵」（指責、辱罵）讀ㄍㄡˋ，如「為人詬病」。",deep:"1. 注音比較\n詬：ㄍㄡˋ（四聲）＝詬病（指摘批評）、詬罵；ㄏㄡˋ＝誤讀（受「后、後」影響）；ㄍㄡ＝誤讀（聲調錯誤，是「勾」的讀音）\n2. 國字拆解與造字原因\n詬：形聲字，「言」＋「后」（聲）。用言語羞辱、指責→「詬罵」；「詬病」原指把某事當作恥辱來批評→今指被大眾批評指摘（制度為人詬病）。從言部表示與言語攻擊有關。"},
  {id:"p595",grade:12,word:"湮沒",target:"湮",zhuyin:"ㄧㄣ",pinyin:"yīn",wz:"ㄧㄣ ㄇㄛˋ",wrong:[{z:"ㄧㄢ",p:"yān"},{z:"ㄧㄢˋ",p:"yàn"}],note:"教育部審訂音「湮」只有一個讀音ㄧㄣ：湮沒、湮滅都讀ㄧㄣ。",deep:"1. 注音比較\n湮：ㄧㄣ＝湮沒、湮滅（湮沒無聞、證據湮滅）。★教育部《國語辭典簡編本》「湮」只收ㄧㄣ一音，讀成ㄧㄢ不是審訂音；形近的「煙」讀ㄧㄢ、「堙」讀ㄧㄣ\n2. 國字拆解與造字原因\n湮：形聲字，「氵（水）」＋「垔」（聲，堵塞）。本義是被水掩埋、堵塞，引申為被時間掩埋、再也沒有人知道→「湮沒無聞」。從水部：像被大水淹過，痕跡全消。"},
  {id:"p596",grade:12,word:"流氓",target:"氓",zhuyin:"ㄇㄤˊ",pinyin:"máng",wz:"ㄌㄧㄡˊ ㄇㄤˊ",wrong:[{z:"ㄇㄥˊ",p:"méng"},{z:"ㄇㄤˇ",p:"mǎng"}],note:"「流氓」讀ㄇㄤˊ；《詩經》「氓之蚩蚩」（百姓）讀ㄇㄥˊ。",deep:"1. 注音比較\n氓：ㄇㄤˊ（二聲）＝流氓（不務正業、為非作歹的人）；ㄇㄥˊ（二聲）＝氓之蚩蚩、群氓（古指外來的百姓）；ㄇㄤˇ＝無此音（是「莽」的讀音）\n2. 國字拆解與造字原因\n氓：會意字，「亡」（流亡）＋「民」，從外地流亡遷來的人民，本義是移居的百姓→《詩經．氓》即用此義（ㄇㄥˊ）；流動無業的人後來變成貶稱→「流氓」（ㄇㄤˊ）。古義讀ㄇㄥˊ，今貶義讀ㄇㄤˊ。"},
  {id:"p597",grade:12,word:"圭臬",target:"臬",zhuyin:"ㄋㄧㄝˋ",pinyin:"niè",wz:"ㄍㄨㄟ ㄋㄧㄝˋ",wrong:[{z:"ㄗˋ",p:"zì"},{z:"ㄍㄨㄟ",p:"guī"}],note:"「奉為圭臬」（準則）的「臬」讀ㄋㄧㄝˋ。",deep:"1. 注音比較\n臬：ㄋㄧㄝˋ（四聲）＝圭臬（測日影的儀器，引申為法度標準）；ㄗˋ＝無此音（上半是「自」，易被誤導）；ㄍㄨㄟ＝那是「圭」的讀音\n2. 國字拆解與造字原因\n臬：會意字，「自（鼻）」＋「木」，本義是箭靶的中心柱，又指古代測日影定方位的標竿。「圭」「臬」都是天文測量儀器——最精準的標準→「奉為圭臬」＝當作不可違背的準則。"},
  {id:"p598",grade:12,word:"篡位",target:"篡",zhuyin:"ㄘㄨㄢˋ",pinyin:"cuàn",wz:"ㄘㄨㄢˋ ㄨㄟˋ",wrong:[{z:"ㄙㄨㄢˋ",p:"suàn"},{z:"ㄗㄨㄢˇ",p:"zuǎn"}],note:"「篡位」「篡奪」讀ㄘㄨㄢˋ，不要與「纂」（ㄗㄨㄢˇ，編纂）相混。",deep:"1. 注音比較\n篡：ㄘㄨㄢˋ（四聲）＝篡位、篡奪、篡改；ㄙㄨㄢˋ＝誤讀（受「算」影響，形近）；ㄗㄨㄢˇ＝那是「纂」的讀音（編纂），下半部不同要分清\n2. 國字拆解與造字原因\n篡：從「算」省從「厶」（私），用不正當的私心奪取，本義是非法奪取（君位）→「篡位、篡改歷史」。辨字：下面是「厶」的是篡（奪取），下面是「糸」的是纂（編書）。"},
  {id:"p599",grade:12,word:"攫取",target:"攫",zhuyin:"ㄐㄩㄝˊ",pinyin:"jué",wz:"ㄐㄩㄝˊ ㄑㄩˇ",wrong:[{z:"ㄏㄨㄛˋ",p:"huò"},{z:"ㄑㄩㄝˋ",p:"què"}],note:"「攫取」（強奪）讀ㄐㄩㄝˊ，如「攫取暴利」。",deep:"1. 注音比較\n攫：ㄐㄩㄝˊ（二聲）＝攫取、攫奪（像鳥獸用爪抓取）；ㄏㄨㄛˋ＝誤讀（受「獲」影響）；ㄑㄩㄝˋ＝無此音（是「卻」的讀音）\n2. 國字拆解與造字原因\n攫：形聲字，「扌（手）」＋「矍」（聲，鳥受驚左右張望）。本義是猛禽用爪迅速抓取獵物→引申為用不正當手段強奪→「攫取暴利」。與「矍鑠」的「矍」同聲符。"},
  {id:"p600",grade:12,word:"濫觴",target:"觴",zhuyin:"ㄕㄤ",pinyin:"shāng",wz:"ㄌㄢˋ ㄕㄤ",wrong:[{z:"ㄕㄤˋ",p:"shàng"},{z:"ㄧㄤˊ",p:"yáng"}],note:"「濫觴」（事物的起源）的「觴」（酒杯）讀ㄕㄤ。",deep:"1. 注音比較\n觴：ㄕㄤ（一聲）＝濫觴、舉觴、曲水流觴（酒杯）；ㄕㄤˋ＝誤讀（聲調錯誤，受「尚」影響）；ㄧㄤˊ＝無此音（是「揚」的讀音）\n2. 國字拆解與造字原因\n觴：形聲字，「角」＋「昜（省）」。古人用獸角做酒器，本義是酒杯。「濫觴」出自《荀子》：長江大河的源頭，水少得只能浮起一只酒杯（濫＝浮起）→比喻事物的起源、開端，是高中最常考的文化詞之一。"},
  // 2026-08-07 擴充批次一（p601-p630）
  {id:"p601",grade:1,word:"相片",target:"相",zhuyin:"ㄒㄧㄤˋ",pinyin:"xiàng",wz:"ㄒㄧㄤˋ ㄆㄧㄢˋ",wrong:[{z:"ㄒㄧㄤ",p:"xiāng"},{z:"ㄒㄧㄤˇ",p:"xiǎng"}],note:"「相片」「照相」的「相」（容貌影像）讀ㄒㄧㄤˋ；「互相」讀ㄒㄧㄤ。",deep:"1. 注音比較\n相：ㄒㄧㄤˋ（四聲）＝相片、相貌、照相（容貌、影像）；ㄒㄧㄤ（一聲）＝互相、相信（彼此）\n2. 國字拆解與造字原因\n相：會意字，「木」＋「目」，用眼睛察看樹木，本義是仔細看。彼此對看→「互相」（ㄒㄧㄤ）；看到的容貌樣子→「相貌、相片」（ㄒㄧㄤˋ）。"},
  {id:"p602",grade:2,word:"種田",target:"種",zhuyin:"ㄓㄨㄥˋ",pinyin:"zhòng",wz:"ㄓㄨㄥˋ ㄊㄧㄢˊ",wrong:[{z:"ㄓㄨㄥˇ",p:"zhǒng"},{z:"ㄔㄨㄥˊ",p:"chóng"}],note:"動詞「種田」「種樹」讀ㄓㄨㄥˋ；名詞「種子」「品種」讀ㄓㄨㄥˇ。",deep:"1. 注音比較\n種：ㄓㄨㄥˋ（四聲）＝種田、種樹、種花（栽種，動詞）；ㄓㄨㄥˇ（三聲）＝種子、種類、播種（名詞）\n2. 國字拆解與造字原因\n種：形聲字，「禾」＋「重」（聲）。與稻禾有關：穀物的籽實是「種子」（ㄓㄨㄥˇ）；把種子埋進土裡的動作是「種植」（ㄓㄨㄥˋ）。名詞三聲、動詞四聲，是最典型的「破音辨詞性」。"},
  {id:"p603",grade:2,word:"倒車",target:"倒",zhuyin:"ㄉㄠˋ",pinyin:"dào",wz:"ㄉㄠˋ ㄔㄜ",wrong:[{z:"ㄉㄠˇ",p:"dǎo"},{z:"ㄉㄠ",p:"dāo"}],note:"「倒車」（往後退）的「倒」讀ㄉㄠˋ；「跌倒」讀ㄉㄠˇ。",deep:"1. 注音比較\n倒：ㄉㄠˋ（四聲）＝倒車、倒退、倒水（反向、傾出）；ㄉㄠˇ（三聲）＝跌倒、倒塌、打倒（豎立的東西倒下）\n2. 國字拆解與造字原因\n倒：形聲字，「亻」＋「到」（聲）。人從站立變成躺下→「跌倒」（ㄉㄠˇ）；方向顛轉過來→「倒退、倒車、倒帶」（ㄉㄠˋ）。記法：「倒下」三聲、「倒轉」四聲。"},
  {id:"p604",grade:3,word:"擔子",target:"擔",zhuyin:"ㄉㄢˋ",pinyin:"dàn",wz:"ㄉㄢˋ ˙ㄗ",wrong:[{z:"ㄉㄢ",p:"dān"},{z:"ㄉㄢˇ",p:"dǎn"}],note:"名詞「擔子」「重擔」讀ㄉㄢˋ；動詞「擔任」「擔心」讀ㄉㄢ。",deep:"1. 注音比較\n擔：ㄉㄢˋ（四聲）＝擔子、重擔、一擔米（名詞，挑的東西）；ㄉㄢ（一聲）＝擔任、擔心、承擔（動詞，用肩挑、承受）\n2. 國字拆解與造字原因\n擔：形聲字，「扌」＋「詹」（聲）。用手（肩）挑起的動作讀ㄉㄢ；挑在肩上的貨物、責任讀ㄉㄢˋ。動詞一聲、名詞四聲，與「種」相反方向，最易混。"},
  {id:"p605",grade:3,word:"塞車",target:"塞",zhuyin:"ㄙㄞ",pinyin:"sāi",wz:"ㄙㄞ ㄔㄜ",wrong:[{z:"ㄙㄞˋ",p:"sài"},{z:"ㄙㄜˋ",p:"sè"}],note:"「塞車」「瓶塞」讀ㄙㄞ；「邊塞」讀ㄙㄞˋ；「閉塞」「阻塞」讀ㄙㄜˋ。",deep:"1. 注音比較\n塞：ㄙㄞ（一聲）＝塞車、塞住、瓶塞（口語塞入）；ㄙㄞˋ（四聲）＝邊塞、塞外、要塞（邊疆）；ㄙㄜˋ（四聲）＝閉塞、阻塞、茅塞頓開（文言堵塞）\n2. 國字拆解與造字原因\n塞：會意兼形聲，從「土」，像用雙手把東西填進縫隙再覆土，本義是堵住。口語動作讀ㄙㄞ；文言的堵塞讀ㄙㄜˋ；堵住外敵的邊防要地讀ㄙㄞˋ。一字三音全是常考點。"},
  {id:"p606",grade:3,word:"幾乎",target:"幾",zhuyin:"ㄐㄧ",pinyin:"jī",wz:"ㄐㄧ ㄏㄨ",wrong:[{z:"ㄐㄧˇ",p:"jǐ"},{z:"ㄐㄧˋ",p:"jì"}],note:"「幾乎」「幾近」的「幾」（將近）讀ㄐㄧ；「幾個」讀ㄐㄧˇ。",deep:"1. 注音比較\n幾：ㄐㄧ（一聲）＝幾乎、幾近、庶幾（將近、差不多）；ㄐㄧˇ（三聲）＝幾個、幾天、所剩無幾（詢問數量）\n2. 國字拆解與造字原因\n幾：會意字，從「𢆶（絲）」從「戍（守）」，本義是細微的跡象——事情剛露出苗頭。由「細微」引申出「接近、差一點」（ㄐㄧ，幾乎）；又借作疑問數詞「多少」（ㄐㄧˇ，幾個）。"},
  {id:"p607",grade:4,word:"難民",target:"難",zhuyin:"ㄋㄢˋ",pinyin:"nàn",wz:"ㄋㄢˋ ㄇㄧㄣˊ",wrong:[{z:"ㄋㄢˊ",p:"nán"},{z:"ㄋㄢˇ",p:"nǎn"}],note:"「難民」「災難」的「難」（禍患）讀ㄋㄢˋ；「困難」讀ㄋㄢˊ。",deep:"1. 注音比較\n難：ㄋㄢˋ（四聲）＝難民、災難、遇難、發難（禍患）；ㄋㄢˊ（二聲）＝困難、難題、難過（不容易）\n2. 國字拆解與造字原因\n難：形聲字，從「隹」（短尾鳥）。本義是一種鳥，後借表「不容易」（ㄋㄢˊ）；再引申指使人陷入困境的禍事（ㄋㄢˋ）。「多災多難」「排除萬難」前者四聲、後者二聲，看詞義辨音。"},
  {id:"p608",grade:4,word:"供應",target:"供",zhuyin:"ㄍㄨㄥ",pinyin:"gōng",wz:"ㄍㄨㄥ ㄧㄥˋ",wrong:[{z:"ㄍㄨㄥˋ",p:"gòng"},{z:"ㄍㄨㄥˇ",p:"gǒng"}],note:"「供應」「提供」讀ㄍㄨㄥ；「供品」「口供」讀ㄍㄨㄥˋ。",deep:"1. 注音比較\n供：ㄍㄨㄥ（一聲）＝供應、供給、提供（供給所需）；ㄍㄨㄥˋ（四聲）＝供品、供奉、口供、招供（祭祀奉獻、陳述案情）\n2. 國字拆解與造字原因\n供：形聲字，「亻」＋「共」（聲）。人把東西雙手奉上：日常給予所需讀ㄍㄨㄥ；恭敬奉獻給神明祖先、或向官府陳述讀ㄍㄨㄥˋ。"},
  {id:"p609",grade:4,word:"冠軍",target:"冠",zhuyin:"ㄍㄨㄢˋ",pinyin:"guàn",wz:"ㄍㄨㄢˋ ㄐㄩㄣ",wrong:[{z:"ㄍㄨㄢ",p:"guān"},{z:"ㄍㄨㄢˇ",p:"guǎn"}],note:"「冠軍」「奪冠」的「冠」（居首位）讀ㄍㄨㄢˋ；「皇冠」「桂冠」讀ㄍㄨㄢ。",deep:"1. 注音比較\n冠：ㄍㄨㄢˋ（四聲）＝冠軍、奪冠、冠蓋、弱冠（動詞戴帽、位居第一）；ㄍㄨㄢ（一聲）＝皇冠、桂冠、雞冠、衣冠（名詞帽子）\n2. 國字拆解與造字原因\n冠：會意字，「冖（覆蓋）」＋「元（人頭）」＋「寸（手）」——用手把帽子戴到頭上。名詞「帽子」讀ㄍㄨㄢ；戴帽的動作與「第一名」（如冠軍原指功居首位）讀ㄍㄨㄢˋ。「弱冠」（男子二十歲行冠禮）讀ㄍㄨㄢˋ，常考。"},
  {id:"p610",grade:4,word:"骨頭",target:"骨",zhuyin:"ㄍㄨˊ",pinyin:"gú",wz:"ㄍㄨˊ ˙ㄊㄡ",wrong:[{z:"ㄍㄨˇ",p:"gǔ"},{z:"ㄍㄨˋ",p:"gù"}],note:"口語「骨頭」的「骨」讀ㄍㄨˊ；「骨骼」「骨氣」讀ㄍㄨˇ。",deep:"1. 注音比較\n骨：ㄍㄨˊ（二聲）＝骨頭、骨碌（口語）；ㄍㄨˇ（三聲）＝骨骼、骨氣、刻骨銘心（一般用法）\n2. 國字拆解與造字原因\n骨：會意字，上半像剔去肉的骨架（冎），下加「月（肉）」，本義是支撐身體的骨骼。一般讀ㄍㄨˇ；只有口語詞「骨頭、骨碌」按審訂音讀ㄍㄨˊ，是「語音／讀音有別」的例子。"},
  {id:"p611",grade:5,word:"分外",target:"分",zhuyin:"ㄈㄣˋ",pinyin:"fèn",wz:"ㄈㄣˋ ㄨㄞˋ",wrong:[{z:"ㄈㄣ",p:"fēn"},{z:"ㄈㄣˊ",p:"fén"}],note:"「分外」「本分」「安分」的「分」（名分、限度）讀ㄈㄣˋ；「分開」讀ㄈㄣ。",deep:"1. 注音比較\n分：ㄈㄣˋ（四聲）＝分外、本分、安分、身分（名分、界限）；ㄈㄣ（一聲）＝分開、分數、分別（分割）\n2. 國字拆解與造字原因\n分：會意字，「八（分開）」＋「刀」，用刀把東西剖開，本義是分割（ㄈㄣ）。分割後各自應得的部分、地位→「名分、本分、分外（超出本分＝格外）」（ㄈㄣˋ）。"},
  {id:"p612",grade:5,word:"彈性",target:"彈",zhuyin:"ㄊㄢˊ",pinyin:"tán",wz:"ㄊㄢˊ ㄒㄧㄥˋ",wrong:[{z:"ㄉㄢˋ",p:"dàn"},{z:"ㄊㄢˋ",p:"tàn"}],note:"「彈性」「彈跳」「彈琴」讀ㄊㄢˊ；「子彈」「彈藥」讀ㄉㄢˋ。",deep:"1. 注音比較\n彈：ㄊㄢˊ（二聲）＝彈性、彈琴、彈跳、動彈（動詞，撥動反彈）；ㄉㄢˋ（四聲）＝子彈、彈藥、炸彈（名詞，彈丸）\n2. 國字拆解與造字原因\n彈：形聲字，「弓」＋「單」（聲）。本義是用弓發射的小丸（ㄉㄢˋ）；發射時手指撥弦的動作→「彈奏、彈跳」（ㄊㄢˊ）。名詞四聲、動詞二聲。"},
  {id:"p613",grade:5,word:"厭惡",target:"惡",zhuyin:"ㄨˋ",pinyin:"wù",wz:"ㄧㄢˋ ㄨˋ",wrong:[{z:"ㄜˋ",p:"è"},{z:"ㄜˇ",p:"ě"}],note:"「厭惡」「可惡」（討厭）讀ㄨˋ；「惡人」讀ㄜˋ；「惡心」讀ㄜˇ。",deep:"1. 注音比較\n惡：ㄨˋ（四聲）＝厭惡、可惡、深惡痛絕（討厭，動詞）；ㄜˋ（四聲）＝惡人、罪惡、惡劣（壞，形容詞）；ㄜˇ（三聲）＝惡心（想吐）\n2. 國字拆解與造字原因\n惡：形聲字，「心」＋「亞」（聲）。心裡覺得壞→「邪惡」（ㄜˋ）；對壞事心生排斥→「厭惡」（ㄨˋ）；生理上的不舒服想吐→「惡心」（ㄜˇ）。「好（ㄏㄠˋ）惡（ㄨˋ）」並用指喜好與憎惡，常考。"},
  {id:"p614",grade:6,word:"磨坊",target:"磨",zhuyin:"ㄇㄛˋ",pinyin:"mò",wz:"ㄇㄛˋ ㄈㄤ",wrong:[{z:"ㄇㄛˊ",p:"mó"},{z:"ㄇㄛ",p:"mō"}],note:"名詞「磨坊」「石磨」讀ㄇㄛˋ；動詞「磨刀」「折磨」讀ㄇㄛˊ。",deep:"1. 注音比較\n磨：ㄇㄛˋ（四聲）＝磨坊、石磨、推磨（磨碎穀物的器具）；ㄇㄛˊ（二聲）＝磨刀、磨練、折磨（摩擦、消耗）\n2. 國字拆解與造字原因\n磨：形聲字，「石」＋「麻」（聲）。用石頭摩擦的動作讀ㄇㄛˊ；由上下兩片石盤做成、碾碎穀物的器具讀ㄇㄛˋ。動詞二聲、器具四聲。另外「坊」教育部審訂音讀一聲ㄈㄤ，所以整詞讀ㄇㄛˋ ㄈㄤ。"},
  {id:"p615",grade:6,word:"乾坤",target:"乾",zhuyin:"ㄑㄧㄢˊ",pinyin:"qián",wz:"ㄑㄧㄢˊ ㄎㄨㄣ",wrong:[{z:"ㄍㄢ",p:"gān"},{z:"ㄍㄢˋ",p:"gàn"}],note:"「乾坤」「乾卦」的「乾」（天）讀ㄑㄧㄢˊ；「乾淨」「乾燥」讀ㄍㄢ。",deep:"1. 注音比較\n乾：ㄑㄧㄢˊ（二聲）＝乾坤、乾卦、乾隆（《易經》卦名，指天）；ㄍㄢ（一聲）＝乾淨、乾燥、餅乾（沒有水分）\n2. 國字拆解與造字原因\n乾：形聲字，從「乙（草木上出）」、「倝」聲，本義是太陽升起、陽氣上騰——所以《易經》以「乾」為天（ㄑㄧㄢˊ）；日曬使水分蒸發→「乾燥」（ㄍㄢ）。「扭轉乾坤」讀ㄑㄧㄢˊ，常考。"},
  {id:"p616",grade:6,word:"負荷",target:"荷",zhuyin:"ㄏㄜˋ",pinyin:"hè",wz:"ㄈㄨˋ ㄏㄜˋ",wrong:[{z:"ㄏㄜˊ",p:"hé"},{z:"ㄏㄜˇ",p:"hě"}],note:"「負荷」「荷槍」（背負）讀ㄏㄜˋ；「荷花」「荷葉」讀ㄏㄜˊ。",deep:"1. 注音比較\n荷：ㄏㄜˋ（四聲）＝負荷、荷槍實彈、感荷（背負、承受）；ㄏㄜˊ（二聲）＝荷花、荷葉、荷包（蓮）\n2. 國字拆解與造字原因\n荷：形聲字，「艹」＋「何」（聲）。本義是蓮（ㄏㄜˊ）；「何」的古義本是「用肩扛」，「荷」借了這個動詞義讀ㄏㄜˋ→「負荷」（承受的重量）。電學「負荷」、成語「荷槍實彈」都讀ㄏㄜˋ。"},
  {id:"p617",grade:7,word:"遊說",target:"說",zhuyin:"ㄕㄨㄟˋ",pinyin:"shuì",wz:"ㄧㄡˊ ㄕㄨㄟˋ",wrong:[{z:"ㄕㄨㄛ",p:"shuō"},{z:"ㄩㄝˋ",p:"yuè"}],note:"「遊說」（勸人採納主張）的「說」讀ㄕㄨㄟˋ；一般「說話」讀ㄕㄨㄛ。",deep:"1. 注音比較\n說：ㄕㄨㄟˋ（四聲）＝遊說（用言語勸動別人）；ㄕㄨㄛ（一聲）＝說話、說明、小說（講述）；ㄩㄝˋ（四聲）＝通「悅」（不亦說乎），文言用法\n2. 國字拆解與造字原因\n說：形聲字，「言」＋「兌」（聲）。用言語陳述讀ㄕㄨㄛ；帶著目的到處勸人接受主張（戰國縱橫家的專長）讀ㄕㄨㄟˋ；「兌」有喜悅義，通「悅」讀ㄩㄝˋ。依審訂音，「說服」今讀ㄕㄨㄛ ㄈㄨˊ，只有「遊說」保留ㄕㄨㄟˋ。"},
  {id:"p618",grade:7,word:"太監",target:"監",zhuyin:"ㄐㄧㄢˋ",pinyin:"jiàn",wz:"ㄊㄞˋ ㄐㄧㄢˋ",wrong:[{z:"ㄐㄧㄢ",p:"jiān"},{z:"ㄎㄢ",p:"kān"}],note:"「太監」「國子監」（官署）讀ㄐㄧㄢˋ；「監督」「監視」讀ㄐㄧㄢ。",deep:"1. 注音比較\n監：ㄐㄧㄢˋ（四聲）＝太監、國子監（官署、官名）；ㄐㄧㄢ（一聲）＝監督、監視、監獄（察看管束）\n2. 國字拆解與造字原因\n監：會意字，甲骨文像人俯身對著水盆照臉，本義是照視、察看（ㄐㄧㄢ），也是「鑑」的本字。由「察看」引申為執掌監察的官署與宦官職名（ㄐㄧㄢˋ）。動作一聲、官署官名四聲。"},
  {id:"p619",grade:7,word:"燕國",target:"燕",zhuyin:"ㄧㄢ",pinyin:"yān",wz:"ㄧㄢ ㄍㄨㄛˊ",wrong:[{z:"ㄧㄢˋ",p:"yàn"},{z:"ㄧㄢˇ",p:"yǎn"}],note:"國名、地名「燕國」「燕京」讀ㄧㄢ；「燕子」「燕窩」讀ㄧㄢˋ。",deep:"1. 注音比較\n燕：ㄧㄢ（一聲）＝燕國、燕京、燕趙（周代國名、河北一帶古稱）；ㄧㄢˋ（四聲）＝燕子、燕窩、勞燕分飛（鳥名）\n2. 國字拆解與造字原因\n燕：象形字，像燕子張翅剪尾飛翔之形，本義是燕鳥（ㄧㄢˋ）；假借作北方國名、地名（ㄧㄢ）。讀史書遇「燕」先想是鳥還是國，戰國七雄的「燕」一律讀ㄧㄢ。"},
  {id:"p620",grade:8,word:"乳臭未乾",target:"臭",zhuyin:"ㄒㄧㄡˋ",pinyin:"xiù",wz:"ㄖㄨˇ ㄒㄧㄡˋ ㄨㄟˋ ㄍㄢ",wrong:[{z:"ㄔㄡˋ",p:"chòu"},{z:"ㄒㄧㄡ",p:"xiū"}],note:"「乳臭未乾」的「臭」（氣味）讀ㄒㄧㄡˋ；「臭味」「發臭」讀ㄔㄡˋ。",deep:"1. 注音比較\n臭：ㄒㄧㄡˋ（四聲）＝乳臭未乾、無聲無臭（氣味的總稱，同「嗅」的本字）；ㄔㄡˋ（四聲）＝臭味、發臭、臭名（難聞的氣味）\n2. 國字拆解與造字原因\n臭：會意字，「自（鼻子）」＋「犬」——狗用鼻子嗅聞，本義是聞氣味、泛指氣味（ㄒㄧㄡˋ），後加「口」造「嗅」承接此義；「臭」則漸偏指難聞的氣味（ㄔㄡˋ）。「乳臭」＝奶味，譏人年幼稚嫩。"},
  {id:"p621",grade:8,word:"籠罩",target:"籠",zhuyin:"ㄌㄨㄥˊ",pinyin:"lóng",wz:"ㄌㄨㄥˊ ㄓㄠˋ",wrong:[{z:"ㄌㄨㄥˇ",p:"lǒng"},{z:"ㄌㄨㄥˋ",p:"lòng"}],note:"教育部審訂音「籠」只有一個讀音ㄌㄨㄥˊ：燈籠、鳥籠、籠罩都讀ㄌㄨㄥˊ。",deep:"1. 注音比較\n籠：ㄌㄨㄥˊ＝籠罩、燈籠、蒸籠、鳥籠、牢籠、籠統、籠絡。★教育部《國語辭典簡編本》「籠」只收ㄌㄨㄥˊ一音，「籠罩」讀ㄌㄨㄥˇ不是審訂音\n2. 國字拆解與造字原因\n籠：形聲字，「竹」＋「龍」（聲），本義是竹編的罩物器具（鳥籠、蒸籠）。像罩子一樣把東西整個蓋住就是「籠罩」，讀音相同。從竹部，因為古代多用竹子編。"},
  {id:"p622",grade:8,word:"如法炮製",target:"炮",zhuyin:"ㄆㄠˊ",pinyin:"páo",wz:"ㄖㄨˊ ㄈㄚˇ ㄆㄠˊ ㄓˋ",wrong:[{z:"ㄆㄠˋ",p:"pào"},{z:"ㄅㄠ",p:"bāo"}],note:"「如法炮製」「炮製藥材」的「炮」讀ㄆㄠˊ；「大炮」讀ㄆㄠˋ；「炮羊肉」讀ㄅㄠ。",deep:"1. 注音比較\n炮：ㄆㄠˊ（二聲）＝炮製、炮烙（用火加工）；ㄆㄠˋ（四聲）＝大炮、炮火、鞭炮（武器）；ㄅㄠ（一聲）＝炮羊肉（大火快炒）\n2. 國字拆解與造字原因\n炮：形聲字，「火」＋「包」（聲）。本義是把食物裹起來放火裡烤：中藥用火焙製→「炮製」（ㄆㄠˊ）；投石機與火器→「炮」（ㄆㄠˋ）；大火快炒→ㄅㄠ。「如法炮製」比喻照現成方法辦事，讀ㄆㄠˊ，是最常考的破音之一。"},
  {id:"p623",grade:9,word:"女紅",target:"紅",zhuyin:"ㄍㄨㄥ",pinyin:"gōng",wz:"ㄋㄩˇ ㄍㄨㄥ",wrong:[{z:"ㄏㄨㄥˊ",p:"hóng"},{z:"ㄏㄨㄥ",p:"hōng"}],note:"「女紅」（縫紉刺繡等手藝）的「紅」通「工」，讀ㄍㄨㄥ。",deep:"1. 注音比較\n紅：ㄍㄨㄥ（一聲）＝女紅（縫紉、刺繡、織布等工作，通「工」）；ㄏㄨㄥˊ（二聲）＝紅色、紅包、走紅（顏色）\n2. 國字拆解與造字原因\n紅：形聲字，「糸」＋「工」（聲）。本義是淺赤色的絲織品（ㄏㄨㄥˊ）；「女紅」的「紅」是「功／工」的假借字，指婦女的針線織造之事，所以讀ㄍㄨㄥ。「擅長女紅」讀錯率極高，會考常客。"},
  {id:"p624",grade:9,word:"呼天搶地",target:"搶",zhuyin:"ㄑㄧㄤ",pinyin:"qiāng",wz:"ㄏㄨ ㄊㄧㄢ ㄑㄧㄤ ㄉㄧˋ",wrong:[{z:"ㄑㄧㄤˇ",p:"qiǎng"},{z:"ㄑㄧㄤˋ",p:"qiàng"}],note:"「呼天搶地」的「搶」（碰撞）讀ㄑㄧㄤ；「搶奪」讀ㄑㄧㄤˇ。",deep:"1. 注音比較\n搶：ㄑㄧㄤ（一聲）＝呼天搶地、搶地（用頭撞地）；ㄑㄧㄤˇ（三聲）＝搶奪、搶劫、搶先（用力奪取）\n2. 國字拆解與造字原因\n搶：形聲字，「扌」＋「倉」（聲）。奪取義讀ㄑㄧㄤˇ；「碰撞、觸碰」的古義讀ㄑㄧㄤ——「呼天搶地」指大哭大喊、用頭撞地，形容極度悲痛，《戰國策》「以頭搶地爾」同此音。"},
  {id:"p625",grade:10,word:"阿諛",target:"阿",zhuyin:"ㄜ",pinyin:"ē",wz:"ㄜ ㄩˊ",wrong:[{z:"ㄚ",p:"ā"},{z:"ㄜˋ",p:"è"}],note:"「阿諛」「阿附」（曲意逢迎）的「阿」讀ㄜ；稱呼「阿姨」讀ㄚ。",deep:"1. 注音比較\n阿：ㄜ（一聲）＝阿諛、阿附、剛正不阿（迎合偏袒）；ㄚ（一聲）＝阿姨、阿公（稱呼詞頭）\n2. 國字拆解與造字原因\n阿：形聲字，「阝（山）」＋「可」（聲），本義是大山彎曲處。由「彎曲」引申為曲意逢迎、偏袒（ㄜ）→「阿諛奉承」「剛正不阿」；作親暱稱呼的詞頭讀ㄚ。「不阿」讀ㄜ是高中常考音。"},
  {id:"p626",grade:10,word:"可汗",target:"汗",zhuyin:"ㄏㄢˊ",pinyin:"hán",wz:"ㄎㄜˋ ㄏㄢˊ",wrong:[{z:"ㄏㄢˋ",p:"hàn"},{z:"ㄏㄢ",p:"hān"}],note:"「可汗」（古代北方君主）讀ㄎㄜˋ ㄏㄢˊ；「汗水」讀ㄏㄢˋ。",deep:"1. 注音比較\n汗：ㄏㄢˊ（二聲）＝可汗、大汗（北方遊牧民族君主稱號）；ㄏㄢˋ（四聲）＝汗水、流汗、汗顏（身體排出的水分）\n2. 國字拆解與造字原因\n汗：形聲字，「氵」＋「干」（聲），本義是汗水（ㄏㄢˋ）。「可汗」是突厥、蒙古語 khan 的音譯，「可」讀ㄎㄜˋ、「汗」讀ㄏㄢˊ，〈木蘭詩〉「可汗大點兵」即此，音譯詞不能照字面讀。"},
  {id:"p627",grade:11,word:"綸巾",target:"綸",zhuyin:"ㄍㄨㄢ",pinyin:"guān",wz:"ㄍㄨㄢ ㄐㄧㄣ",wrong:[{z:"ㄌㄨㄣˊ",p:"lún"},{z:"ㄌㄨㄣˋ",p:"lùn"}],note:"「綸巾」（青絲頭巾）的「綸」讀ㄍㄨㄢ；「經綸」讀ㄌㄨㄣˊ。",deep:"1. 注音比較\n綸：ㄍㄨㄢ（一聲）＝綸巾（配青絲帶的頭巾）；ㄌㄨㄣˊ（二聲）＝經綸、滿腹經綸（整理過的絲線，喻治國才學）\n2. 國字拆解與造字原因\n綸：形聲字，「糸」＋「侖」（聲），本義是青絲織成的帶子。整理絲線引申為規劃治理→「經綸」（ㄌㄨㄣˊ）；用青絲帶做的頭巾→「綸巾」（ㄍㄨㄢ）。蘇軾〈念奴嬌〉「羽扇綸巾」寫周瑜儒將風度，讀ㄍㄨㄢ，學測常考。"},
  {id:"p628",grade:11,word:"屬意",target:"屬",zhuyin:"ㄓㄨˇ",pinyin:"zhǔ",wz:"ㄓㄨˇ ㄧˋ",wrong:[{z:"ㄕㄨˇ",p:"shǔ"},{z:"ㄓㄨˋ",p:"zhù"}],note:"「屬意」「屬文」（心意歸向、綴文）讀ㄓㄨˇ；「屬於」「金屬」讀ㄕㄨˇ。",deep:"1. 注音比較\n屬：ㄓㄨˇ（三聲）＝屬意、屬文、屬託（連綴、寄託，通「囑」）；ㄕㄨˇ（三聲）＝屬於、金屬、家屬（隸屬、類別）\n2. 國字拆解與造字原因\n屬：形聲字，「尾」＋「蜀」（聲），本義是連接。相連而歸於某類→「隸屬」（ㄕㄨˇ）；把心意、文字連綴寄託→「屬意、屬文」（ㄓㄨˇ），這個意思後來寫作「囑」。〈岳陽樓記〉「屬予作文以記之」讀ㄓㄨˇ，經典考點。"},
  {id:"p629",grade:11,word:"復辟",target:"辟",zhuyin:"ㄅㄧˋ",pinyin:"bì",wz:"ㄈㄨˋ ㄅㄧˋ",wrong:[{z:"ㄆㄧˋ",p:"pì"},{z:"ㄅㄧˇ",p:"bǐ"}],note:"「復辟」（君主復位）的「辟」（君主）讀ㄅㄧˋ；「開闢」義的「辟」讀ㄆㄧˋ。",deep:"1. 注音比較\n辟：ㄅㄧˋ（四聲）＝復辟、辟邪（君主；通「避」「闢」以外的本讀）；ㄆㄧˋ（四聲）＝辟穀？——注意「辟」通「闢」（開闢）、通「僻」（偏僻）時讀ㄆㄧˋ\n2. 國字拆解與造字原因\n辟：會意字，從「卩（人跪）」從「辛（刑刀）」，本義是法度、刑罰，掌刑法者為君→「辟」指君主（ㄅㄧˋ），「復辟」即恢復君位；作「開闢」「偏僻」的通假字時讀ㄆㄧˋ。「復辟」誤讀ㄆㄧˋ是最常見錯音之一。"},
  {id:"p630",grade:12,word:"吐蕃",target:"蕃",zhuyin:"ㄈㄢ",pinyin:"fān",wz:"ㄊㄨˇ ㄈㄢ",wrong:[{z:"ㄅㄛ",p:"bō"},{z:"ㄈㄢˊ",p:"fán"}],note:"教育部審訂音「吐蕃」讀ㄊㄨˇ ㄈㄢ，是古代藏族政權的名稱。",deep:"1. 注音比較\n蕃：ㄈㄢ＝吐蕃（古代藏族政權）、通「番」指外族；ㄈㄢˊ＝蕃茂、蕃育、蕃息、蕃衍（茂盛、繁殖）。★教育部《國語辭典簡編本》「吐蕃」讀ㄊㄨˇ ㄈㄢ，讀成ㄅㄛ不是審訂音\n2. 國字拆解與造字原因\n蕃：形聲字，「艹」＋「番」（聲），本義是草木茂盛（ㄈㄢˊ）；借來通「番」指邊地民族時讀ㄈㄢ，唐代與唐朝往來的藏族政權就寫作「吐蕃」。"},
{"id":"p631","grade":6,"word":"干涸","target":"涸","zhuyin":"ㄏㄜˊ","pinyin":"hé","wz":"ㄍㄢ ㄏㄜˊ","wrong":[{"z":"ㄍㄨˋ","p":"gù"},{"z":"ㄏㄨˊ","p":"hú"}],"note":"「涸」聲旁是「固」，卻不讀ㄍㄨˋ；池塘乾涸、涸轍之鮒都讀ㄏㄜˊ。","deep":"1. 注音比較\n涸：ㄏㄜˊ（二聲）＝乾涸、枯涸、涸轍之鮒；誤讀ㄍㄨˋ＝受聲旁「固」誤導；誤讀ㄏㄨˊ＝與「湖」音混淆\n2. 國字拆解與造字原因\n涸：形聲字，「水（氵）」＋「固」（聲），水乾竭之意——水凝固不流、終至乾涸，故從水。《莊子》「涸轍之鮒」指乾涸車轍中的鯽魚，比喻身陷困境急待救援。記法：水乾了叫涸（ㄏㄜˊ），與「河」同音好記。"},
{"id":"p632","grade":7,"word":"湍急","target":"湍","zhuyin":"ㄊㄨㄢ","pinyin":"tuān","wz":"ㄊㄨㄢ ㄐㄧˊ","wrong":[{"z":"ㄔㄨㄢˇ","p":"chuǎn"},{"z":"ㄉㄨㄢ","p":"duān"}],"note":"「湍」與「喘」「端」同以「耑」為聲旁，讀音卻各不相同；水流湍急讀ㄊㄨㄢ。","deep":"1. 注音比較\n湍：ㄊㄨㄢ（一聲）＝湍急、湍流、急湍；誤讀ㄔㄨㄢˇ＝與「喘」（喘氣）形近；誤讀ㄉㄨㄢ＝與「端」（端正）形近\n2. 國字拆解與造字原因\n湍：形聲字，「水（氵）」＋「耑」（聲），水勢急速奔流。同聲旁三兄弟要分家：從水是湍（ㄊㄨㄢ，急流）、從口是喘（ㄔㄨㄢˇ，急促呼吸）、從立是端（ㄉㄨㄢ，端正）。"},
{"id":"p633","grade":7,"word":"佃農","target":"佃","zhuyin":"ㄉㄧㄢˋ","pinyin":"diàn","wz":"ㄉㄧㄢˋ ㄋㄨㄥˊ","wrong":[{"z":"ㄊㄧㄢˊ","p":"tián"},{"z":"ㄉㄧㄢ","p":"diān"}],"note":"「佃」不可依聲旁「田」讀ㄊㄧㄢˊ；租田耕種的佃農、佃戶都讀ㄉㄧㄢˋ。","deep":"1. 注音比較\n佃：ㄉㄧㄢˋ（四聲）＝佃農、佃戶、佃租；誤讀ㄊㄧㄢˊ＝受聲旁「田」誤導；誤讀ㄉㄧㄢ＝聲調誤標一聲\n2. 國字拆解與造字原因\n佃：形聲兼會意，「人（亻）」＋「田」（聲），本義是耕作田地的人；後專指向地主租地耕種的農民。社會課「三七五減租」保障的就是佃農。記法：人（亻）在田邊做工，是佃（ㄉㄧㄢˋ）農。"},
{"id":"p634","grade":8,"word":"慫恿","target":"慫","zhuyin":"ㄙㄨㄥˇ","pinyin":"sǒng","wz":"ㄙㄨㄥˇ ㄩㄥˇ","wrong":[{"z":"ㄘㄨㄥˊ","p":"cóng"},{"z":"ㄙㄨㄥ","p":"sōng"}],"note":"「慫恿」兩字都讀上聲（ㄙㄨㄥˇ ㄩㄥˇ）；「慫」不可依聲旁「從」讀ㄘㄨㄥˊ。","deep":"1. 注音比較\n慫：ㄙㄨㄥˇ（三聲）＝慫恿；誤讀ㄘㄨㄥˊ＝受聲旁「從」誤導；誤讀ㄙㄨㄥ＝與「鬆」聲調混淆\n2. 國字拆解與造字原因\n慫：形聲字，「從」（聲）＋「心」，從旁鼓動別人的心，使其去做（多指不該做的事）。「恿」（ㄩㄥˇ）從「甬」聲從「心」，同為鼓動之意。記法：慫恿是「攛掇人心」，兩個字都有「心」，兩個字都讀三聲。"},
  {id:"p635",grade:8,word:"靦腆",target:"靦",zhuyin:"ㄇㄧㄢˇ",pinyin:"miǎn",wz:"ㄇㄧㄢˇ ㄊㄧㄢˇ",wrong:[{z:"ㄊㄧㄢˇ",p:"tiǎn"},{z:"ㄉㄧㄢˇ",p:"diǎn"}],note:"教育部審訂音「靦腆」讀ㄇㄧㄢˇ ㄊㄧㄢˇ，形容害羞的樣子。",deep:"1. 注音比較\n靦：ㄇㄧㄢˇ＝靦腆（害羞）；ㄊㄧㄢˇ＝靦顏事仇、靦怍、靦赧（厚著臉皮、慚愧）。★教育部《國語辭典簡編本》「靦腆」讀ㄇㄧㄢˇ ㄊㄧㄢˇ，整詞讀ㄊㄧㄢˇ ㄊㄧㄢˇ不是審訂音\n2. 國字拆解與造字原因\n靦：從「面」＋「見」，臉被人看見——所以字義都繞著「臉面」打轉：害羞得臉紅是「靦腆」（ㄇㄧㄢˇ），厚著臉皮是「靦顏」（ㄊㄧㄢˇ）。同一個字兩張臉，讀音也跟著分。"},
{"id":"p636","grade":9,"word":"相形見絀","target":"絀","zhuyin":"ㄔㄨˋ","pinyin":"chù","wz":"ㄒㄧㄤ ㄒㄧㄥˊ ㄐㄧㄢˋ ㄔㄨˋ","wrong":[{"z":"ㄓㄨㄛˊ","p":"zhuó"},{"z":"ㄔㄨ","p":"chū"}],"note":"「絀」是不足、短缺，讀ㄔㄨˋ；與「笨拙」的「拙」（ㄓㄨㄛˊ）形近易混。","deep":"1. 注音比較\n絀：ㄔㄨˋ（四聲）＝相形見絀、左支右絀（不足）；誤讀ㄓㄨㄛˊ＝與「拙」（笨拙）形近；誤讀ㄔㄨ＝受聲旁「出」誤導漏了聲調\n2. 國字拆解與造字原因\n絀：形聲字，「糸」＋「出」（聲），本指縫紉，借為「短缺、不足」——絲線用罄、捉襟見肘之意。「相形見絀」＝互相比較之下顯得不足；「左支右絀」＝應付了這邊、那邊又不夠。從「糸」是絀（ㄔㄨˋ）、從「手（扌）」是拙（ㄓㄨㄛˊ），部首一換音義全變。"},
{"id":"p637","grade":9,"word":"恪守","target":"恪","zhuyin":"ㄎㄜˋ","pinyin":"kè","wz":"ㄎㄜˋ ㄕㄡˇ","wrong":[{"z":"ㄍㄜˋ","p":"gè"},{"z":"ㄑㄩㄝˋ","p":"què"}],"note":"「恪」是恭敬謹慎，恪守、恪遵都讀ㄎㄜˋ，不可依聲旁「各」讀ㄍㄜˋ。","deep":"1. 注音比較\n恪：ㄎㄜˋ（四聲）＝恪守、恪遵、恪盡職守；誤讀ㄍㄜˋ＝受聲旁「各」誤導；誤讀ㄑㄩㄝˋ＝與「確」音混淆\n2. 國字拆解與造字原因\n恪：形聲字，「心（忄）」＋「各」（聲），存於心中的恭敬謹慎——所以「恪守承諾」是把承諾放在心上、絲毫不敢怠慢。記法：用「心」守規矩，恪（ㄎㄜˋ）盡職守。"},
  {id:"p638",grade:10,word:"內訌",target:"訌",zhuyin:"ㄏㄨㄥˊ",pinyin:"hóng",wz:"ㄋㄟˋ ㄏㄨㄥˊ",wrong:[{z:"ㄏㄨㄥˋ",p:"hòng"},{z:"ㄍㄨㄥ",p:"gōng"}],note:"教育部審訂音「訌」只有一個讀音ㄏㄨㄥˊ：內訌讀ㄋㄟˋ ㄏㄨㄥˊ。",deep:"1. 注音比較\n訌：ㄏㄨㄥˊ＝內訌（內部爭鬥潰亂）。★教育部《國語辭典簡編本》「訌」只收二聲ㄏㄨㄥˊ，讀成四聲ㄏㄨㄥˋ不是審訂音\n2. 國字拆解與造字原因\n訌：形聲字，「言」＋「工」（聲），指因言語相攻而引起的內部潰亂。內訌都是從吵架（言）開始的，所以從言部。"},
{"id":"p639","grade":11,"word":"皴裂","target":"皴","zhuyin":"ㄘㄨㄣ","pinyin":"cūn","wz":"ㄘㄨㄣ ㄌㄧㄝˋ","wrong":[{"z":"ㄐㄩㄣ","p":"jūn"},{"z":"ㄗㄨㄣ","p":"zūn"}],"note":"皮膚受凍起皺裂開叫「皴裂」（ㄘㄨㄣ）；「龜裂」的「龜」才讀ㄐㄩㄣ，兩詞易混。","deep":"1. 注音比較\n皴：ㄘㄨㄣ（一聲）＝皴裂、皴法（國畫技法）；誤讀ㄐㄩㄣ＝與「龜（ㄐㄩㄣ）裂」混淆；誤讀ㄗㄨㄣ＝與「尊」音近相混\n2. 國字拆解與造字原因\n皴：形聲字，「夋」（聲）＋「皮」，皮膚受凍而粗糙起皺、裂開細紋；國畫中畫山石紋理的筆法也叫「皴法」，正是取山石表面如皮膚皺裂之象。「皴裂」（ㄘㄨㄣ）指皮膚凍裂，「龜裂」（ㄐㄩㄣ）多指土地、牆面裂開，主角不同、讀音不同。"},
{"id":"p640","grade":12,"word":"逡巡","target":"逡","zhuyin":"ㄑㄩㄣ","pinyin":"qūn","wz":"ㄑㄩㄣ ㄒㄩㄣˊ","wrong":[{"z":"ㄐㄩㄣˋ","p":"jùn"},{"z":"ㄙㄨㄣ","p":"sūn"}],"note":"「逡巡」是有所顧忌而徘徊不前，「逡」讀ㄑㄩㄣ；與「俊」「峻」形近，不可讀ㄐㄩㄣˋ。","deep":"1. 注音比較\n逡：ㄑㄩㄣ（一聲）＝逡巡不前；誤讀ㄐㄩㄣˋ＝與「俊、峻、駿」形近；誤讀ㄙㄨㄣ＝與「巡」的聲母相混\n2. 國字拆解與造字原因\n逡：形聲字，「辵（辶）」＋「夋」（聲），在原地退卻、徘徊——想前進又縮回來，跟「行走」有關所以從辵部。《岳陽樓記》式的古文常見「逡巡」寫猶豫卻步之態。記法：辶字旁是走走停停的逡（ㄑㄩㄣ）巡；換上人字旁才是英俊（ㄐㄩㄣˋ）的俊。"},
  {id:"p641",grade:7,word:"徇私",target:"徇",zhuyin:"ㄒㄩㄣˋ",pinyin:"xùn",wz:"ㄒㄩㄣˋ ㄙ",wrong:[{z:"ㄒㄩㄣˊ",p:"xún"},{z:"ㄒㄩㄣ",p:"xūn"}],note:"教育部審訂音「徇」只有一個讀音ㄒㄩㄣˋ：徇私、徇國都讀ㄒㄩㄣˋ。",deep:"1. 注音比較\n徇：ㄒㄩㄣˋ＝徇私、徇節、徇名、徇國。★教育部《國語辭典簡編本》「徇」只收四聲ㄒㄩㄣˋ，讀成二聲ㄒㄩㄣˊ不是審訂音；同聲符的「殉」也讀ㄒㄩㄣˋ、「詢」讀ㄒㄩㄣˊ\n2. 國字拆解與造字原因\n徇：形聲字，「彳（行走）」＋「旬」（聲），本義是巡行示眾，引申為曲意順從——順著私人情面辦事就是「徇私」。「殉」從歹部，指為某個目的犧牲性命（殉職），兩字部首不同、意思不同。"},
{"id":"p642","grade":9,"word":"鞭笞","target":"笞","zhuyin":"ㄔ","pinyin":"chī","wz":"ㄅㄧㄢ ㄔ","wrong":[{"z":"ㄊㄞˊ","p":"tái"},{"z":"ㄉㄞˋ","p":"dài"}],"note":"「鞭笞」是用鞭子、竹板抽打，「笞」讀ㄔ；與「苔」形近，不讀ㄊㄞˊ。","deep":"1. 注音比較\n笞：ㄔ（一聲）＝鞭笞、笞刑；誤讀ㄊㄞˊ＝與「苔、抬」同聲符相混；誤讀ㄉㄞˋ＝與「怠」形近相混\n2. 國字拆解與造字原因\n笞：形聲字，「竹」＋「台」（聲），用竹板抽打——古代五刑之一的「笞刑」就是打竹板，所以從竹部。聲符「台」在此讀ㄔ，與「苔（ㄊㄞˊ）、怠（ㄉㄞˋ）」同符不同音，先認部首（竹→刑具）再記音最保險。"},
{"id":"p643","grade":9,"word":"熨帖","target":"熨","zhuyin":"ㄩˋ","pinyin":"yù","wz":"ㄩˋ ㄊㄧㄝ","wrong":[{"z":"ㄩㄣˋ","p":"yùn"},{"z":"ㄨㄟˋ","p":"wèi"}],"note":"「熨帖」是妥帖舒坦，「熨」讀ㄩˋ；燙衣服的「熨斗」才讀ㄩㄣˋ。","deep":"1. 注音比較\n熨：ㄩˋ（四聲）＝熨帖；ㄩㄣˋ（四聲）＝熨斗、熨燙；誤讀ㄨㄟˋ＝與「慰」形近相混\n2. 國字拆解與造字原因\n熨：形聲兼會意，「尉」＋「火」，本義是用加熱的器具燙平衣物。器具、燙衣之義讀ㄩㄣˋ（熨斗、熨衣服）；引申「平整、舒坦」之義讀ㄩˋ（這番話聽來心裡熨帖）。與「慰」（心字底，安慰）形近：用火燙平是熨，用心安撫是慰。"},
{"id":"p644","grade":10,"word":"攻訐","target":"訐","zhuyin":"ㄐㄧㄝˊ","pinyin":"jié","wz":"ㄍㄨㄥ ㄐㄧㄝˊ","wrong":[{"z":"ㄍㄢ","p":"gān"},{"z":"ㄐㄧㄝ","p":"jiē"}],"note":"「攻訐」是揭發攻擊別人的過失隱私，「訐」讀ㄐㄧㄝˊ，不因聲符「干」而讀ㄍㄢ。","deep":"1. 注音比較\n訐：ㄐㄧㄝˊ（二聲）＝攻訐、訐發；誤讀ㄍㄢ＝受聲符「干」影響；誤讀ㄐㄧㄝ＝聲調誤讀（一聲）\n2. 國字拆解與造字原因\n訐：形聲字，「言」＋「干」（聲），用言語揭發、指斥別人的隱私過錯——攻擊靠言語，所以從言部。「干」在此只借形不表音；「攻訐」多用於互揭瘡疤的負面語境（如：選戰淪為人身攻訐）。"},
  {id:"p645",grade:10,word:"佝僂",target:"佝",zhuyin:"ㄎㄡˋ",pinyin:"kòu",wz:"ㄎㄡˋ ㄌㄡˊ",wrong:[{z:"ㄎㄡ",p:"kōu"},{z:"ㄍㄡ",p:"gōu"}],note:"教育部審訂音「佝」只有一個讀音ㄎㄡˋ：佝僂、佝僂病都讀ㄎㄡˋ。",deep:"1. 注音比較\n佝：ㄎㄡˋ＝佝僂（ㄎㄡˋ ㄌㄡˊ）、佝僂病。★教育部《國語辭典簡編本》「佝」只收四聲ㄎㄡˋ，讀成一聲ㄎㄡ不是審訂音\n2. 國字拆解與造字原因\n佝：形聲字，「亻（人）」＋「句」（聲）。「佝僂」連用形容人背脊彎曲、駝背的樣子，講的是人的體態，所以從人部。醫學上的「佝僂病」是缺乏維生素D造成骨骼發育不良。"},
{"id":"p646","grade":10,"word":"骨鯁","target":"鯁","zhuyin":"ㄍㄥˇ","pinyin":"gěng","wz":"ㄍㄨˇ ㄍㄥˇ","wrong":[{"z":"ㄧㄥˋ","p":"yìng"},{"z":"ㄍㄥ","p":"gēng"}],"note":"「骨鯁在喉」的「鯁」是魚刺卡住，讀ㄍㄥˇ；與「硬」形近，不讀ㄧㄥˋ。","deep":"1. 注音比較\n鯁：ㄍㄥˇ（三聲）＝骨鯁在喉、骨鯁之臣；誤讀ㄧㄥˋ＝與「硬」形近相混；誤讀ㄍㄥ＝聲調誤讀（一聲，與「羹」音近）\n2. 國字拆解與造字原因\n鯁：形聲字，「魚」＋「更」（聲），本義是魚骨、魚刺——魚刺卡在喉嚨，不吐不快，故「骨鯁在喉」比喻心裡有話憋不住；敢直言的臣子稱「骨鯁之臣」，取魚刺般剛硬直截之意。從魚部記本義，就不會誤讀成「硬」。"},
{"id":"p647","grade":11,"word":"齟齬","target":"齟","zhuyin":"ㄐㄩˇ","pinyin":"jǔ","wz":"ㄐㄩˇ ㄩˇ","wrong":[{"z":"ㄗㄨˇ","p":"zǔ"},{"z":"ㄑㄧㄝˇ","p":"qiě"}],"note":"「齟齬」是上下牙齒咬合不正，比喻意見不合，「齟」讀ㄐㄩˇ，不因聲符「且」讀ㄗㄨˇ。","deep":"1. 注音比較\n齟：ㄐㄩˇ（三聲）＝齟齬；誤讀ㄗㄨˇ＝與「組、阻」聲符相混；誤讀ㄑㄧㄝˇ＝直讀聲符「且」\n2. 國字拆解與造字原因\n齟：形聲字，「齒」＋「且」（聲），「齟齬」連用指上下牙齒對不齊——牙齒咬合不正，引申為彼此意見不合、相處有摩擦（如：兩人因理念齟齬而拆夥）。從齒部記義；「且」作聲符在「齟」讀ㄐㄩˇ，與「組（ㄗㄨˇ）、狙（ㄐㄩ）」同符異音。"},
{"id":"p648","grade":11,"word":"睥睨","target":"睥","zhuyin":"ㄅㄧˋ","pinyin":"bì","wz":"ㄅㄧˋ ㄋㄧˋ","wrong":[{"z":"ㄆㄧˊ","p":"pí"},{"z":"ㄅㄟ","p":"bēi"}],"note":"「睥睨」是斜著眼看人、傲視一切，「睥」讀ㄅㄧˋ；不因形近「脾」讀ㄆㄧˊ。","deep":"1. 注音比較\n睥：ㄅㄧˋ（四聲）＝睥睨；誤讀ㄆㄧˊ＝與「脾、啤」聲符相混；誤讀ㄅㄟ＝直讀聲符「卑」\n2. 國字拆解與造字原因\n睥：形聲字，「目」＋「卑」（聲），斜著眼睛看人——用眼神表達輕視，所以從目部。「睥睨」二字皆從目，連用指斜視傲物（如：睥睨群雄、睥睨天下）。「卑」作聲符：眼睛斜看是睥（ㄅㄧˋ），肉月臟器是脾（ㄆㄧˊ），石上刻文是碑（ㄅㄟ）。"},
{"id":"p649","grade":11,"word":"耄耋","target":"耋","zhuyin":"ㄉㄧㄝˊ","pinyin":"dié","wz":"ㄇㄠˋ ㄉㄧㄝˊ","wrong":[{"z":"ㄓˋ","p":"zhì"},{"z":"ㄇㄠˋ","p":"mào"}],"note":"「耄耋」指八九十歲的高齡，「耋」讀ㄉㄧㄝˊ；不因聲符「至」讀ㄓˋ。","deep":"1. 注音比較\n耋：ㄉㄧㄝˊ（二聲）＝耄耋之年；誤讀ㄓˋ＝直讀聲符「至」；誤讀ㄇㄠˋ＝與「耄」二字相混\n2. 國字拆解與造字原因\n耋：形聲字，「老（耂）」＋「至」（聲），古稱七八十歲為「耋」——年壽「至」老境，所以從老部。「耄」（ㄇㄠˋ）指八九十歲，「耄耋」連用泛稱高齡長者（如：耄耋老人）。記法：老字頭表年紀，「至」只借音，讀ㄉㄧㄝˊ。"},
{"id":"p650","grade":12,"word":"饕餮","target":"餮","zhuyin":"ㄊㄧㄝˋ","pinyin":"tiè","wz":"ㄊㄠ ㄊㄧㄝˋ","wrong":[{"z":"ㄉㄧㄝˊ","p":"dié"},{"z":"ㄘㄢ","p":"cān"}],"note":"「饕餮」是傳說中貪食的凶獸，「餮」讀ㄊㄧㄝˋ；與「耋」形近，不讀ㄉㄧㄝˊ。","deep":"1. 注音比較\n餮：ㄊㄧㄝˋ（四聲）＝饕餮；誤讀ㄉㄧㄝˊ＝與「耋」形近相混；誤讀ㄘㄢ＝受「餐」聯想誤讀\n2. 國字拆解與造字原因\n餮：形聲字，「食」＋「殄」（省聲），「饕餮」是古代傳說中貪食的凶獸，商周青銅器常鑄其獸面紋——因為貪吃，兩字都從食部。今稱懂吃愛吃的人為「老饕」，豐盛美食稱「饕餮盛宴」。記法：食字底表貪食，讀ㄊㄧㄝˋ；老字頭的耋（ㄉㄧㄝˊ）是高壽，兩字別混。"},
{"id":"p651","grade":7,"word":"憨厚","target":"憨","zhuyin":"ㄏㄢ","pinyin":"hān","wz":"ㄏㄢ ㄏㄡˋ","wrong":[{"z":"ㄍㄢˇ","p":"gǎn"},{"z":"ㄏㄢˋ","p":"hàn"}],"note":"「憨厚」是樸實忠厚，「憨」讀ㄏㄢ（一聲），不因形近「敢」而誤讀。","deep":"1. 注音比較\n憨：ㄏㄢ（一聲）＝憨厚、憨直、憨笑；誤讀ㄍㄢˇ＝受字形上半「敢」影響；誤讀ㄏㄢˋ＝聲調誤讀（與「憾」相混）\n2. 國字拆解與造字原因\n憨：形聲字，「敢」（聲）＋「心」，心思樸實、痴直不巧詐——形容心性，所以從心部。「憨厚」＝樸實忠厚，「憨笑」＝天真傻氣地笑。記法：心字底的憨讀ㄏㄢ，別被上面的「敢」帶走。"},
{"id":"p652","grade":8,"word":"貽誤","target":"貽","zhuyin":"ㄧˊ","pinyin":"yí","wz":"ㄧˊ ㄨˋ","wrong":[{"z":"ㄊㄞˊ","p":"tái"},{"z":"ㄉㄞˋ","p":"dài"}],"note":"「貽誤」是耽誤、留下錯誤，「貽」讀ㄧˊ；與「怠、殆」形近，不讀ㄉㄞˋ。","deep":"1. 注音比較\n貽：ㄧˊ（二聲）＝貽誤、貽笑大方、貽害；誤讀ㄊㄞˊ＝與「抬、苔」聲符相混；誤讀ㄉㄞˋ＝與「怠、殆」形近相混\n2. 國字拆解與造字原因\n貽：形聲字，「貝」＋「台」（聲），本義是贈送財物——所以從貝部；引申為「留給、遺留」（貽誤＝把錯誤留給後面、耽誤事情；貽笑大方＝留下笑柄給內行人）。聲符「台」在此讀ㄧˊ，與「怡（ㄧˊ）」同音可互相聯想：心曠神怡的怡、貽誤的貽，都讀ㄧˊ。"},
{"id":"p653","grade":8,"word":"侃侃而談","target":"侃","zhuyin":"ㄎㄢˇ","pinyin":"kǎn","wz":"ㄎㄢˇ ㄎㄢˇ ㄦˊ ㄊㄢˊ","wrong":[{"z":"ㄎㄢ","p":"kān"},{"z":"ㄧㄢˇ","p":"yǎn"}],"note":"「侃侃而談」是從容不迫地暢談，「侃」讀ㄎㄢˇ（三聲）。","deep":"1. 注音比較\n侃：ㄎㄢˇ（三聲）＝侃侃而談、調侃；誤讀ㄎㄢ＝聲調誤讀（與「刊」相混）；誤讀ㄧㄢˇ＝與「衍」形近相混\n2. 國字拆解與造字原因\n侃：會意字，由「人」「口」「川」組成——人說話如川水般滔滔流暢，本義是剛直、從容。「侃侃而談」語出《論語．鄉黨》「與下大夫言，侃侃如也」，形容說話從容不迫、理直氣壯。記法：侃侃（ㄎㄢˇ）而談要「敢」講，三聲讀來鏗鏘有力。"},
{"id":"p654","grade":9,"word":"徜徉","target":"徜","zhuyin":"ㄔㄤˊ","pinyin":"cháng","wz":"ㄔㄤˊ ㄧㄤˊ","wrong":[{"z":"ㄕㄤˋ","p":"shàng"},{"z":"ㄊㄤˇ","p":"tǎng"}],"note":"「徜徉」是安閒自在地漫步，「徜」讀ㄔㄤˊ，不因聲符「尚」而讀ㄕㄤˋ。","deep":"1. 注音比較\n徜：ㄔㄤˊ（二聲）＝徜徉；誤讀ㄕㄤˋ＝直讀聲符「尚」；誤讀ㄊㄤˇ＝與「倘」形近相混\n2. 國字拆解與造字原因\n徜：形聲字，「彳」＋「尚」（聲），「徜徉」連用指安閒自在地來回漫步——漫步是行走，所以從彳部（雙人旁與行走有關）。（如：徜徉在書海中、徜徉於山水之間）。與「倘（ㄊㄤˇ，倘若）」形近：彳旁漫步是徜（ㄔㄤˊ），人旁假設是倘（ㄊㄤˇ）。"},
{"id":"p655","grade":9,"word":"諄諄教誨","target":"諄","zhuyin":"ㄓㄨㄣ","pinyin":"zhūn","wz":"ㄓㄨㄣ ㄓㄨㄣ ㄐㄧㄠˋ ㄏㄨㄟˋ","wrong":[{"z":"ㄔㄨㄣˊ","p":"chún"},{"z":"ㄉㄨㄣ","p":"dūn"}],"note":"「諄諄」是懇切耐心的樣子，「諄」讀ㄓㄨㄣ（一聲）；與「淳、醇」聲符相同，讀音卻不同。","deep":"1. 注音比較\n諄：ㄓㄨㄣ（一聲）＝諄諄教誨、諄諄告誡；誤讀ㄔㄨㄣˊ＝與「淳、醇」聲符相混；誤讀ㄉㄨㄣ＝與「敦」音近相混\n2. 國字拆解與造字原因\n諄：形聲字，「言」＋「享」（聲），懇切耐心地教導——教誨靠言語，所以從言部。「諄諄教誨」＝不厭其煩、懇切再三的教導。同聲符「享」：言旁懇切是諄（ㄓㄨㄣ）、水旁樸厚是淳（ㄔㄨㄣˊ）、酉旁酒厚是醇（ㄔㄨㄣˊ）。"},
{"id":"p656","grade":10,"word":"未雨綢繆","target":"繆","zhuyin":"ㄇㄡˊ","pinyin":"móu","wz":"ㄨㄟˋ ㄩˇ ㄔㄡˊ ㄇㄡˊ","wrong":[{"z":"ㄇㄧㄡˋ","p":"miù"},{"z":"ㄌㄧㄠˋ","p":"liào"}],"note":"「未雨綢繆」的「繆」讀ㄇㄡˊ；「紕繆」的「繆」才讀ㄇㄧㄡˋ，是多音字。","deep":"1. 注音比較\n繆：ㄇㄡˊ（二聲）＝未雨綢繆；ㄇㄧㄡˋ（四聲）＝紕繆（錯誤）；誤讀ㄌㄧㄠˋ＝與「廖」形近相混\n2. 國字拆解與造字原因\n繆：形聲字，「糸」＋「翏」（聲），本義是纏縛、纏繞——與絲繩有關所以從糸部。「未雨綢繆」語出《詩經．豳風．鴟鴞》：「迨天之未陰雨，徹彼桑土，綢繆牖戶」——趁還沒下雨，先修補好門窗，比喻事先防備。讀音口訣：綢繆（ㄇㄡˊ）防備、紕繆（ㄇㄧㄡˋ）出錯、姓廖不姓繆（作姓氏時讀ㄇㄧㄠˋ）。"},
{"id":"p657","grade":10,"word":"剽悍","target":"剽","zhuyin":"ㄆㄧㄠˋ","pinyin":"piào","wz":"ㄆㄧㄠˋ ㄏㄢˋ","wrong":[{"z":"ㄆㄧㄠ","p":"piāo"},{"z":"ㄅㄧㄠ","p":"biāo"}],"note":"「剽悍」是敏捷勇猛，「剽」讀ㄆㄧㄠˋ（四聲），常被誤讀成一聲。","deep":"1. 注音比較\n剽：ㄆㄧㄠˋ（四聲）＝剽悍、剽竊；誤讀ㄆㄧㄠ＝與「飄、漂」聲調相混；誤讀ㄅㄧㄠ＝與「標」形近相混\n2. 國字拆解與造字原因\n剽：形聲字，「票」（聲）＋「刀（刂）」，本義是搶劫、掠奪——動刀搶奪所以從刀部；引申為輕捷勇猛（剽悍）與抄襲竊取（剽竊）。依教育部審訂音，「剽」統讀ㄆㄧㄠˋ。記法：刀旁的剽讀四聲，不跟「飄」走。"},
  {id:"p658",grade:11,word:"迤邐",target:"迤",zhuyin:"ㄧˊ",pinyin:"yí",wz:"ㄧˊ ㄌㄧˇ",wrong:[{z:"ㄧˇ",p:"yǐ"},{z:"ㄊㄨㄛ",p:"tuō"}],note:"教育部審訂音「迤邐」讀ㄧˊ ㄌㄧˇ，形容曲折連綿的樣子。",deep:"1. 注音比較\n迤：ㄧˊ＝迤邐（山徑迤邐而上）。★教育部《國語辭典簡編本》「迤」只收ㄧˊ一音，讀成三聲ㄧˇ不是審訂音\n2. 國字拆解與造字原因\n迤：形聲字，「辵（辶）」＋「也」（聲），指道路斜著延伸，與行路有關所以從辵部。「迤邐」形容山路、隊伍曲折連綿不斷。"},
{"id":"p659","grade":11,"word":"婆娑","target":"娑","zhuyin":"ㄙㄨㄛ","pinyin":"suō","wz":"ㄆㄛˊ ㄙㄨㄛ","wrong":[{"z":"ㄕㄚ","p":"shā"},{"z":"ㄙㄨㄛˇ","p":"suǒ"}],"note":"「婆娑」是盤旋起舞、枝葉扶疏的樣子，「娑」讀ㄙㄨㄛ（一聲）。","deep":"1. 注音比較\n娑：ㄙㄨㄛ（一聲）＝婆娑起舞、樹影婆娑；誤讀ㄕㄚ＝直讀聲符「沙」；誤讀ㄙㄨㄛˇ＝與「所」音相混\n2. 國字拆解與造字原因\n娑：形聲字，「沙」（聲）＋「女」，本義是舞姿迴旋的樣子——古代舞者多為女子，所以從女部。「婆娑」形容盤旋舞動（婆娑起舞），也形容枝葉隨風搖曳（淚眼婆娑、樹影婆娑）。記法：女字底的娑讀ㄙㄨㄛ，不讀沙。"},
{"id":"p660","grade":12,"word":"睚眥必報","target":"眥","zhuyin":"ㄗˋ","pinyin":"zì","wz":"ㄧㄞˊ ㄗˋ ㄅㄧˋ ㄅㄠˋ","wrong":[{"z":"ㄘˇ","p":"cǐ"},{"z":"ㄗㄞˋ","p":"zài"}],"note":"「睚眥必報」是連瞪一眼的小怨都要報復，「眥」讀ㄗˋ；不因聲符「此」讀ㄘˇ。","deep":"1. 注音比較\n眥：ㄗˋ（四聲）＝睚眥必報、瞋目裂眥；誤讀ㄘˇ＝直讀聲符「此」；誤讀ㄗㄞˋ＝與「睚」的讀音位置相混\n2. 國字拆解與造字原因\n眥：形聲字，「此」（聲）＋「目」，本義是眼眶、眼角——與眼睛有關所以從目部。「睚眥」（ㄧㄚˊ ㄗˋ）＝瞪眼怒視；《史記．范雎蔡澤列傳》稱范雎「一飯之德必償，睚眥之怨必報」——連被人瞪一眼的小怨恨都必定報復，後以「睚眥必報」形容心胸極狹。記法：目旁的眥（ㄗˋ）是眼角，瞪眼之怨睚眥必報。"},
  {"id": "p661", "grade": 1, "word": "大家", "target": "大", "zhuyin": "ㄉㄚˋ", "pinyin": "dà", "wz": "ㄉㄚˋ ㄐㄧㄚ", "wrong": [{"z": "ㄉㄞˋ", "p": "dài"}, {"z": "ㄊㄞˋ", "p": "tài"}], "note": "「大家」讀ㄉㄚˋ；只有「大夫」（醫生）的「大」讀ㄉㄞˋ。", "deep": "1. 注音比較\n大：ㄉㄚˋ（四聲）＝大家、大人、長大；ㄉㄞˋ（四聲）＝大夫（古代的醫生）。誤讀ㄊㄞˋ＝與「太」相混\n2. 國字拆解與造字原因\n大：象形字，甲骨文畫一個人張開手腳站著的樣子，用人把手腳張到最開來表示「大」。因為是整個人的樣子，所以「大」也用來稱地位高的人——「大夫」（ㄉㄞˋ）本來是官名，後來才變成醫生的稱呼。記法：只有「大夫」讀ㄉㄞˋ，其他都讀ㄉㄚˋ。"},
  {"id": "p662", "grade": 1, "word": "覺得", "target": "覺", "zhuyin": "ㄐㄩㄝˊ", "pinyin": "jué", "wz": "ㄐㄩㄝˊ ˙ㄉㄜ", "wrong": [{"z": "ㄐㄧㄠˋ", "p": "jiào"}, {"z": "ㄒㄩㄝˊ", "p": "xué"}], "note": "「覺得」「感覺」讀ㄐㄩㄝˊ；「睡覺」才讀ㄐㄧㄠˋ。", "deep": "1. 注音比較\n覺：ㄐㄩㄝˊ（二聲）＝覺得、感覺、發覺、覺悟；ㄐㄧㄠˋ（四聲）＝睡覺、午覺、一覺到天亮。誤讀ㄒㄩㄝˊ＝把上面的部件看成「學」\n2. 國字拆解與造字原因\n覺：形聲字，上面是「學」省去下半，下面是「見」。人睡醒了才看得見、才明白，所以本義是醒悟——心裡明白叫「覺得、覺悟」（ㄐㄩㄝˊ）；一睡一醒算一次，變成量詞就是「睡一覺」（ㄐㄧㄠˋ）。記法：講心裡的感受讀ㄐㄩㄝˊ，講睡眠讀ㄐㄧㄠˋ。"},
  {"id": "p663", "grade": 1, "word": "教室", "target": "教", "zhuyin": "ㄐㄧㄠˋ", "pinyin": "jiào", "wz": "ㄐㄧㄠˋ ㄕˋ", "wrong": [{"z": "ㄐㄧㄠ", "p": "jiāo"}, {"z": "ㄒㄧㄠˋ", "p": "xiào"}], "note": "「教室」「教師」讀ㄐㄧㄠˋ（四聲）；「教書」「教小孩」當動詞才讀ㄐㄧㄠ（一聲）。", "deep": "1. 注音比較\n教：ㄐㄧㄠˋ（四聲）＝教室、教師、教育、宗教（名詞、指這件事本身）；ㄐㄧㄠ（一聲）＝教書、教我寫字（動詞、指正在教）。誤讀ㄒㄧㄠˋ＝與「校」相混\n2. 國字拆解與造字原因\n教：會意字，左邊像大人拿著算籌示範，右邊「攵」是拿著棍子的手，合起來是大人帶著孩子學。正在做這個動作時讀一聲（教書）；這件事變成一個名稱時讀四聲（教室、教育）。記法：動詞一聲、名詞四聲。"},
  {"id": "p664", "grade": 1, "word": "烏龜", "target": "龜", "zhuyin": "ㄍㄨㄟ", "pinyin": "guī", "wz": "ㄨ ㄍㄨㄟ", "wrong": [{"z": "ㄐㄩㄣ", "p": "jūn"}, {"z": "ㄑㄧㄡ", "p": "qiū"}], "note": "「烏龜」讀ㄍㄨㄟ；「龜裂」（裂開）讀ㄐㄩㄣ。", "deep": "1. 注音比較\n龜：ㄍㄨㄟ（一聲）＝烏龜、龜殼、龜兔賽跑；ㄐㄩㄣ（一聲）＝龜裂（皮膚或土地裂開）；ㄑㄧㄡ（一聲）＝龜茲（古代西域的國名）\n2. 國字拆解與造字原因\n龜：象形字，甲骨文就是一隻烏龜的側面——上面是頭，中間是龜殼上的紋路，下面是腳和尾巴。因為龜殼上的裂紋一格一格的，很像乾掉的土地或凍傷的皮膚裂開的樣子，所以「裂開」這個意思就讀ㄐㄩㄣ，寫作「龜裂」。記法：動物讀ㄍㄨㄟ，裂開讀ㄐㄩㄣ。"},
  {"id": "p665", "grade": 1, "word": "頭髮", "target": "髮", "zhuyin": "ㄈㄚˇ", "pinyin": "fǎ", "wz": "ㄊㄡˊ ㄈㄚˇ", "wrong": [{"z": "ㄈㄚ", "p": "fā"}, {"z": "ㄅㄚˊ", "p": "bá"}], "note": "「頭髮」的「髮」讀ㄈㄚˇ（三聲），不讀「發」的ㄈㄚ（一聲）。", "deep": "1. 注音比較\n髮：ㄈㄚˇ（三聲）＝頭髮、白髮、理髮、千鈞一髮。★「發」（ㄈㄚ，一聲）是發生、出發，跟「髮」是兩個字，不要混在一起\n2. 國字拆解與造字原因\n髮：形聲字，上面的「髟」（ㄅㄧㄠ）是長頭髮垂下來的樣子，凡是跟頭髮、鬍鬚有關的字多半從「髟」（像「鬍」「鬚」）；下面的「犮」是聲符。記法：有「髟」頭的是頭髮的髮，讀三聲。"},
  {"id": "p666", "grade": 1, "word": "企鵝", "target": "企", "zhuyin": "ㄑㄧˋ", "pinyin": "qì", "wz": "ㄑㄧˋ ㄜˊ", "wrong": [{"z": "ㄑㄧˇ", "p": "qǐ"}, {"z": "ㄓˇ", "p": "zhǐ"}], "note": "「企鵝」「企業」的「企」讀ㄑㄧˋ（四聲），不讀三聲。", "deep": "1. 注音比較\n企：ㄑㄧˋ（四聲）＝企鵝、企業、企圖、企盼。★很多人念成ㄑㄧˇ（三聲），那不是審訂音\n2. 國字拆解與造字原因\n企：會意字，上面是「人」，下面是「止」（腳），畫一個人踮起腳尖的樣子，本義是踮腳往遠處看，所以引申出「盼望」的意思（企盼、企求）。企鵝站得直挺挺、像踮著腳的人，因此得名。記法：企＝人＋止，人踮腳。"},
  {"id": "p667", "grade": 1, "word": "玻璃", "target": "璃", "zhuyin": "ㄌㄧˊ", "pinyin": "lí", "wz": "ㄅㄛ ㄌㄧˊ", "wrong": [{"z": "ㄌㄧˇ", "p": "lǐ"}, {"z": "ㄌㄧˋ", "p": "lì"}], "note": "「玻璃」的「璃」讀ㄌㄧˊ（二聲）。", "deep": "1. 注音比較\n璃：ㄌㄧˊ（二聲）＝玻璃、琉璃。誤讀ㄌㄧˇ＝與「李」「裡」相混；誤讀ㄌㄧˋ＝與「利」相混\n2. 國字拆解與造字原因\n璃：形聲字，「玉（王）」＋「离」（聲）。左邊的「王」其實是「玉」，凡是從玉部的字多半跟寶石、美石有關（像「玲」「珠」「琉」）。古人覺得玻璃、琉璃亮晶晶的像玉，所以用玉部造字。記法：王字旁的璃是玉做的，讀二聲。"},
  {"id": "p668", "grade": 1, "word": "螞蟻", "target": "螞", "zhuyin": "ㄇㄚˇ", "pinyin": "mǎ", "wz": "ㄇㄚˇ ㄧˇ", "wrong": [{"z": "ㄇㄚˋ", "p": "mà"}, {"z": "ㄇㄚˊ", "p": "má"}], "note": "「螞蟻」讀ㄇㄚˇ（三聲）；「螞蟥」（吸血的蟲）才讀ㄇㄚˋ。", "deep": "1. 注音比較\n螞：ㄇㄚˇ（三聲）＝螞蟻；ㄇㄚˋ（四聲）＝螞蟥、螞蚱。誤讀ㄇㄚˊ＝與「麻」相混\n2. 國字拆解與造字原因\n螞：形聲字，「虫」＋「馬」（聲）。從虫部表示牠是蟲子；用「馬」當聲符，所以讀音接近「馬」。螞蟻雖小，卻能扛起比自己重好幾倍的東西，古人用「馬」來形容牠力氣大。記法：虫字旁＋馬，讀音跟「馬」一樣是三聲。"},
  {"id": "p669", "grade": 1, "word": "沒有", "target": "沒", "zhuyin": "ㄇㄟˊ", "pinyin": "méi", "wz": "ㄇㄟˊ ㄧㄡˇ", "wrong": [{"z": "ㄇㄛˋ", "p": "mò"}, {"z": "ㄇㄟˋ", "p": "mèi"}], "note": "「沒有」讀ㄇㄟˊ；「沒收」「沉沒」讀ㄇㄛˋ。", "deep": "1. 注音比較\n沒：ㄇㄟˊ（二聲）＝沒有、沒關係（表示「無」）；ㄇㄛˋ（四聲）＝沒收、沉沒、埋沒、出沒（表示「沉下去、被拿走」）。誤讀ㄇㄟˋ＝與「妹」相混\n2. 國字拆解與造字原因\n沒：會意兼形聲，從「水」，本義是沉到水裡去，所以「沉沒、淹沒」讀ㄇㄛˋ；東西沉進水裡就找不到了，等於「沒有」，這個口語的用法讀ㄇㄟˊ。記法：跟水有關、表示沉下去的讀ㄇㄛˋ，表示「無」的讀ㄇㄟˊ。"},
  {"id": "p670", "grade": 1, "word": "便當", "target": "便", "zhuyin": "ㄅㄧㄢˋ", "pinyin": "biàn", "wz": "ㄅㄧㄢˋ ㄉㄤ", "wrong": [{"z": "ㄆㄧㄢˊ", "p": "pián"}, {"z": "ㄅㄧㄢ", "p": "biān"}], "note": "「便當」「方便」讀ㄅㄧㄢˋ；只有「便宜」讀ㄆㄧㄢˊ。", "deep": "1. 注音比較\n便：ㄅㄧㄢˋ（四聲）＝便當、方便、便利、大便；ㄆㄧㄢˊ（二聲）＝便宜（價錢低）。誤讀ㄅㄧㄢ＝少了聲調\n2. 國字拆解與造字原因\n便：會意字，「人」＋「更」（改變）。人把不順手的事情改一改，做起來就順了，本義是方便、順利（ㄅㄧㄢˋ）。「便宜」本來是「合宜、划算」的意思，讀ㄆㄧㄢˊ，後來專指價錢低。記法：只有「便宜」讀ㄆㄧㄢˊ，其餘都讀ㄅㄧㄢˋ。"},
  {"id": "p671", "grade": 1, "word": "白色", "target": "色", "zhuyin": "ㄙㄜˋ", "pinyin": "sè", "wz": "ㄅㄞˊ ㄙㄜˋ", "wrong": [{"z": "ㄕㄞˇ", "p": "shǎi"}, {"z": "ㄙㄞˋ", "p": "sài"}], "note": "「白色」「顏色」讀ㄙㄜˋ；口語「掉色」「色子」才讀ㄕㄞˇ。", "deep": "1. 注音比較\n色：ㄙㄜˋ（四聲）＝白色、顏色、色彩、景色；ㄕㄞˇ（三聲）＝掉色、色子（骰子的口語說法）。誤讀ㄙㄞˋ＝與「賽」相混\n2. 國字拆解與造字原因\n色：會意字，上面是「人」，下面是「卩」（跪坐的人），本義是臉上的神情——心裡的情緒會顯在臉上，所以有「臉色、神色」；臉色有紅有白，再引申成一切顏色（ㄙㄜˋ）。口語裡講顏色掉了、講賭具，才讀ㄕㄞˇ。記法：讀書音ㄙㄜˋ，口語音ㄕㄞˇ。"},
  {"id": "p672", "grade": 1, "word": "幾個", "target": "幾", "zhuyin": "ㄐㄧˇ", "pinyin": "jǐ", "wz": "ㄐㄧˇ ㄍㄜˋ", "wrong": [{"z": "ㄐㄧ", "p": "jī"}, {"z": "ㄑㄧˇ", "p": "qǐ"}], "note": "問數目的「幾個」「幾歲」讀ㄐㄧˇ（三聲）；「幾乎」讀ㄐㄧ（一聲）。", "deep": "1. 注音比較\n幾：ㄐㄧˇ（三聲）＝幾個、幾歲、幾點（問數目）；ㄐㄧ（一聲）＝幾乎、幾希（差一點、接近）。誤讀ㄑㄧˇ＝與「起」相混\n2. 國字拆解與造字原因\n幾：會意字，上面是兩束細絲，下面是「戍」（拿武器的人），表示極細微、快要察覺不到的徵兆，本義是「細微、接近」——「幾乎」就是「接近到差一點」，讀一聲。問數目時要問一個很小的數，所以讀三聲的「幾個」。記法：問數目三聲，「幾乎」一聲。"},
  {"id": "p673", "grade": 1, "word": "說話", "target": "說", "zhuyin": "ㄕㄨㄛ", "pinyin": "shuō", "wz": "ㄕㄨㄛ ㄏㄨㄚˋ", "wrong": [{"z": "ㄕㄨㄟˋ", "p": "shuì"}, {"z": "ㄩㄝˋ", "p": "yuè"}], "note": "「說話」「說明」讀ㄕㄨㄛ；「遊說」（勸別人聽自己的）讀ㄕㄨㄟˋ。", "deep": "1. 注音比較\n說：ㄕㄨㄛ（一聲）＝說話、說明、小說；ㄕㄨㄟˋ（四聲）＝遊說、說服（勸人接受主張）；ㄩㄝˋ（四聲）＝「學而時習之，不亦說乎」，同「悅」，高興\n2. 國字拆解與造字原因\n說：形聲字，「言」＋「兌」（聲）。從言部表示跟講話有關。用嘴巴講出來是「說話」（ㄕㄨㄛ）；靠講話去打動別人、讓對方照自己的意思做，是「遊說」（ㄕㄨㄟˋ）；把心裡的話講開了會高興，古書借它當「悅」（ㄩㄝˋ）。記法：一般講話一聲，勸別人四聲。"},
  {"id": "p674", "grade": 1, "word": "蜻蜓", "target": "蜓", "zhuyin": "ㄊㄧㄥˊ", "pinyin": "tíng", "wz": "ㄑㄧㄥ ㄊㄧㄥˊ", "wrong": [{"z": "ㄊㄧㄥ", "p": "tīng"}, {"z": "ㄉㄧㄥˋ", "p": "dìng"}], "note": "「蜻蜓」的「蜓」讀ㄊㄧㄥˊ（二聲）。", "deep": "1. 注音比較\n蜓：ㄊㄧㄥˊ（二聲）＝蜻蜓、蜻蜓點水。誤讀ㄊㄧㄥ＝少了聲調（跟「聽」相混）；誤讀ㄉㄧㄥˋ＝與「定」相混\n2. 國字拆解與造字原因\n蜓：形聲字，「虫」＋「廷」（聲）。從虫部表示是昆蟲；「廷」是朝廷的廷，在這裡只表示讀音。「蜻蜓點水」是說蜻蜓飛到水面上，尾巴輕輕碰一下水就走（其實是在產卵），後來用來比喻做事只碰一下、不深入。記法：虫字旁＋廷，讀二聲。"},
  {"id": "p675", "grade": 1, "word": "蝴蝶", "target": "蝶", "zhuyin": "ㄉㄧㄝˊ", "pinyin": "dié", "wz": "ㄏㄨˊ ㄉㄧㄝˊ", "wrong": [{"z": "ㄊㄧㄝˇ", "p": "tiě"}, {"z": "ㄧㄝˋ", "p": "yè"}], "note": "「蝴蝶」的「蝶」讀ㄉㄧㄝˊ（二聲）。", "deep": "1. 注音比較\n蝶：ㄉㄧㄝˊ（二聲）＝蝴蝶、彩蝶、蝶泳。誤讀ㄊㄧㄝˇ＝與「鐵」相混；誤讀ㄧㄝˋ＝只讀了右半邊的「枼」\n2. 國字拆解與造字原因\n蝶：形聲字，「虫」＋「枼」（聲）。「枼」是樹葉的葉的本字，指薄薄的葉片。蝴蝶的翅膀又薄又寬，張開來像兩片葉子，所以用「枼」既表音又幫忙表意。記法：虫字旁的蝶，翅膀薄得像葉子。"},
  {"id": "p676", "grade": 1, "word": "麻雀", "target": "雀", "zhuyin": "ㄑㄩㄝˋ", "pinyin": "què", "wz": "ㄇㄚˊ ㄑㄩㄝˋ", "wrong": [{"z": "ㄑㄧㄠˇ", "p": "qiǎo"}, {"z": "ㄘㄨㄟˋ", "p": "cuì"}], "note": "「麻雀」的「雀」讀ㄑㄩㄝˋ；口語「家雀兒」才讀ㄑㄧㄠˇ。", "deep": "1. 注音比較\n雀：ㄑㄩㄝˋ（四聲）＝麻雀、孔雀、雀躍、鴉雀無聲。誤讀ㄘㄨㄟˋ＝與「翠」相混\n2. 國字拆解與造字原因\n雀：會意字，上面是「小」，下面是「隹」（ㄓㄨㄟ，短尾巴的鳥），合起來就是「小小的短尾鳥」，正是麻雀的樣子。「雀躍」是說像小鳥一樣蹦蹦跳跳，用來形容很高興。記法：小＋隹＝小鳥，讀ㄑㄩㄝˋ。"},
  {"id": "p677", "grade": 1, "word": "蟑螂", "target": "螂", "zhuyin": "ㄌㄤˊ", "pinyin": "láng", "wz": "ㄓㄤ ㄌㄤˊ", "wrong": [{"z": "ㄌㄤˇ", "p": "lǎng"}, {"z": "ㄌㄧㄤˊ", "p": "liáng"}], "note": "「蟑螂」的「螂」讀ㄌㄤˊ（二聲）。", "deep": "1. 注音比較\n螂：ㄌㄤˊ（二聲）＝蟑螂、螳螂、蜣螂。誤讀ㄌㄤˇ＝與「朗」相混；誤讀ㄌㄧㄤˊ＝與「良」相混\n2. 國字拆解與造字原因\n螂：形聲字，「虫」＋「郎」（聲）。從虫部表示是昆蟲，「郎」只表示讀音，所以讀得跟「郎」一樣是二聲。國字裡很多蟲名都用這個辦法造：虫＋一個表音的字，像「螳螂」「蜻蜓」「螞蟻」都是。記法：虫字旁＋郎，讀二聲。"},
  {"id": "p678", "grade": 1, "word": "姊姊", "target": "姊", "zhuyin": "ㄐㄧㄝˇ", "pinyin": "jiě", "wz": "ㄐㄧㄝˇ ˙ㄐㄧㄝ", "wrong": [{"z": "ㄗˇ", "p": "zǐ"}, {"z": "ㄐㄧㄝ", "p": "jiē"}], "note": "「姊姊」的「姊」讀ㄐㄧㄝˇ，跟「姐」同音；不要照右半邊念成ㄗˇ。", "deep": "1. 注音比較\n姊：ㄐㄧㄝˇ（三聲）＝姊姊、姊妹、學姊；ㄗˇ＝古音，今天不用。誤讀ㄐㄧㄝ（一聲）＝少了聲調，跟「街」相混\n2. 國字拆解與造字原因\n姊：形聲字，「女」＋「𠂔」（聲）。從女部表示是女性的親屬稱呼。今天教育部字表以「姊」為正體，「姐」是同音的異體寫法，兩個都讀ㄐㄧㄝˇ。疊字稱呼時，第二個字讀輕聲——所以「姊姊」是ㄐㄧㄝˇ ˙ㄐㄧㄝ。記法：女字旁的姊讀ㄐㄧㄝˇ。"},
  {"id": "p679", "grade": 1, "word": "尾巴", "target": "尾", "zhuyin": "ㄨㄟˇ", "pinyin": "wěi", "wz": "ㄨㄟˇ ㄅㄚ", "wrong": [{"z": "ㄧˇ", "p": "yǐ"}, {"z": "ㄨㄟˊ", "p": "wéi"}], "note": "「尾巴」「尾聲」讀ㄨㄟˇ（三聲）。", "deep": "1. 注音比較\n尾：ㄨㄟˇ（三聲）＝尾巴、尾聲、結尾、船尾。誤讀ㄧˇ＝口語「馬尾兒」的變讀，不是審訂音；誤讀ㄨㄟˊ＝與「圍」「為」相混\n2. 國字拆解與造字原因\n尾：會意字，上面是「尸」（側身的人形），下面是「毛」，古人打獵或跳舞時會在腰後掛獸尾裝飾，所以用人身後有毛來表示「尾巴」。引申為東西的最後一段——「結尾」「尾聲」。記法：尸下面有毛就是尾巴，讀三聲。"},
  {"id": "p680", "grade": 1, "word": "顏色", "target": "顏", "zhuyin": "ㄧㄢˊ", "pinyin": "yán", "wz": "ㄧㄢˊ ㄙㄜˋ", "wrong": [{"z": "ㄧㄢˋ", "p": "yàn"}, {"z": "ㄎㄜ", "p": "kē"}], "note": "「顏色」「顏面」的「顏」讀ㄧㄢˊ（二聲）。", "deep": "1. 注音比較\n顏：ㄧㄢˊ（二聲）＝顏色、顏面、笑顏、和顏悅色。誤讀ㄧㄢˋ＝與「豔」「燕」相混；誤讀ㄎㄜ＝把右邊的「頁」看成「科」\n2. 國字拆解與造字原因\n顏：形聲字，「彥」（聲）＋「頁」。「頁」（ㄒㄧㄝˋ）本來就是「頭」的意思，凡是從頁部的字多半跟頭臉有關（像「頭」「臉」「額」「頸」）。「顏」本義是兩眉之間、額頭那一塊，引申為整張臉——「和顏悅色」就是臉色溫和。臉色有各種變化，再引申成一般的色彩。記法：從頁部的顏，本來講的是臉。"},
  {"id": "p681", "grade": 1, "word": "鴿子", "target": "鴿", "zhuyin": "ㄍㄜ", "pinyin": "gē", "wz": "ㄍㄜ ˙ㄗ", "wrong": [{"z": "ㄍㄜˋ", "p": "gè"}, {"z": "ㄏㄜˊ", "p": "hé"}], "note": "「鴿子」「和平鴿」的「鴿」讀ㄍㄜ（一聲）。", "deep": "1. 注音比較\n鴿：ㄍㄜ（一聲）＝鴿子、白鴿、賽鴿。誤讀ㄍㄜˋ＝與「各」相混；誤讀ㄏㄜˊ＝把「合」直接讀出來\n2. 國字拆解與造字原因\n鴿：形聲字，「合」（聲）＋「鳥」。從鳥部表示是一種鳥；用「合」當聲符，但讀音已經變成ㄍㄜ，不讀「合」的ㄏㄜˊ。鴿子認得回家的路，古人用牠送信，叫「飛鴿傳書」。記法：鳥字邊的鴿讀一聲ㄍㄜ，不要跟「合」同音。"},
  {"id": "p682", "grade": 1, "word": "秘密", "target": "秘", "zhuyin": "ㄇㄧˋ", "pinyin": "mì", "wz": "ㄇㄧˋ ㄇㄧˋ", "wrong": [{"z": "ㄅㄧˋ", "p": "bì"}, {"z": "ㄇㄧˇ", "p": "mǐ"}], "note": "「秘密」「神秘」讀ㄇㄧˋ；只有「秘魯」（國名）讀ㄅㄧˋ。", "deep": "1. 注音比較\n秘：ㄇㄧˋ（四聲）＝秘密、神秘、秘書、便秘；ㄅㄧˋ（四聲）＝秘魯（南美洲的國名）。誤讀ㄇㄧˇ＝與「米」相混\n2. 國字拆解與造字原因\n秘：形聲字，「禾」＋「必」（聲）。本來寫作「祕」，從「示」部——「示」跟祭祀、神明有關，所以本義是神明的事情不讓人知道，也就是「神秘、秘密」。後來常寫成禾字旁的「秘」。記法：講不讓人知道的事讀ㄇㄧˋ，只有國名「秘魯」讀ㄅㄧˋ。"},
  {"id": "p683", "grade": 1, "word": "綠色", "target": "綠", "zhuyin": "ㄌㄩˋ", "pinyin": "lǜ", "wz": "ㄌㄩˋ ㄙㄜˋ", "wrong": [{"z": "ㄌㄨˋ", "p": "lù"}, {"z": "ㄌㄧㄡˋ", "p": "liù"}], "note": "「綠色」「綠燈」讀ㄌㄩˋ；只有「綠林好漢」的「綠」讀ㄌㄨˋ。", "deep": "1. 注音比較\n綠：ㄌㄩˋ（四聲）＝綠色、綠燈、綠茶、綠豆；ㄌㄨˋ（四聲）＝綠林好漢（山林中結夥的人）。誤讀ㄌㄧㄡˋ＝與「六」相混\n2. 國字拆解與造字原因\n綠：形聲字，「糸」＋「彔」（聲）。「糸」（ㄇㄧˋ）是絲線，凡是從糸部的字多半跟布、線、顏色有關（像「紅」「紫」「絲」「線」）——因為古人的顏色名稱大多是從染布來的。記法：糸字旁的顏色字，綠讀ㄌㄩˋ。"},
  {"id": "p684", "grade": 1, "word": "只好", "target": "只", "zhuyin": "ㄓˇ", "pinyin": "zhǐ", "wz": "ㄓˇ ㄏㄠˇ", "wrong": [{"z": "ㄓ", "p": "zhī"}, {"z": "ㄓˋ", "p": "zhì"}], "note": "「只好」「只有」讀ㄓˇ（三聲）。", "deep": "1. 注音比較\n只：ㄓˇ（三聲）＝只好、只有、只是（表示「僅僅」）；ㄓ（一聲）＝古書中的語尾助詞（如「樂只君子」），今天很少用。誤讀ㄓˋ＝與「至」「志」相混\n2. 國字拆解與造字原因\n只：指事字，上面是「口」，下面兩點表示氣往下走，本來是句子講完時的語氣詞。後來借去表示「僅僅、不過如此」，就是今天的「只有、只好」（ㄓˇ）。★注意「只」和「隻」（一隻鳥）是兩個字，「隻」讀ㄓ一聲。記法：表示「僅僅」讀三聲。"},
  {"id": "p685", "grade": 1, "word": "中午", "target": "中", "zhuyin": "ㄓㄨㄥ", "pinyin": "zhōng", "wz": "ㄓㄨㄥ ㄨˇ", "wrong": [{"z": "ㄓㄨㄥˋ", "p": "zhòng"}, {"z": "ㄔㄨㄥ", "p": "chōng"}], "note": "「中午」「中間」讀ㄓㄨㄥ（一聲）；「中獎」「射中」讀ㄓㄨㄥˋ（四聲）。", "deep": "1. 注音比較\n中：ㄓㄨㄥ（一聲）＝中午、中間、中心、中國（表示位置在中間）；ㄓㄨㄥˋ（四聲）＝中獎、射中、中毒（表示「正好打到、遭受」）。誤讀ㄔㄨㄥ＝與「衝」相混\n2. 國字拆解與造字原因\n中：指事字，畫一根旗桿正正插在一個範圍的正當中，本義就是「正中間」（ㄓㄨㄥ）。箭射到靶的正中間，就是「射中」——這個「正好打到」的意思讀四聲。記法：位置讀一聲，打到、得到讀四聲。"},
  {"id": "p686", "grade": 1, "word": "番茄", "target": "茄", "zhuyin": "ㄑㄧㄝˊ", "pinyin": "qié", "wz": "ㄈㄢ ㄑㄧㄝˊ", "wrong": [{"z": "ㄐㄧㄚ", "p": "jiā"}, {"z": "ㄑㄧㄝˇ", "p": "qiě"}], "note": "「番茄」「茄子」讀ㄑㄧㄝˊ；只有「雪茄」（一種菸）讀ㄐㄧㄚ。", "deep": "1. 注音比較\n茄：ㄑㄧㄝˊ（二聲）＝番茄、茄子；ㄐㄧㄚ（一聲）＝雪茄（外國話翻過來的詞）。誤讀ㄑㄧㄝˇ＝與「且」相混\n2. 國字拆解與造字原因\n茄：形聲字，「艸（艹）」＋「加」（聲）。從艸部表示是植物；「雪茄」是英文 cigar 翻過來的音，跟蔬菜沒有關係，所以那時候「茄」只借它的聲音，讀ㄐㄧㄚ。記法：吃的茄子讀ㄑㄧㄝˊ，抽的雪茄讀ㄐㄧㄚ。"},
  {"id": "p687", "grade": 1, "word": "鑰匙", "target": "匙", "zhuyin": "˙ㄕ", "pinyin": "shi", "wz": "ㄧㄠˋ ˙ㄕ", "wrong": [{"z": "ㄔˊ", "p": "chí"}, {"z": "ㄕˊ", "p": "shí"}], "note": "「鑰匙」的「匙」讀輕聲˙ㄕ；「湯匙」才讀ㄔˊ。", "deep": "1. 注音比較\n匙：ㄔˊ（二聲）＝湯匙、茶匙；˙ㄕ（輕聲）＝鑰匙\n2. 國字拆解與造字原因\n匙：形聲字，「是」（聲）＋「匕」。「匕」是古代舀東西的小勺子，所以「匙」本義是湯匙（ㄔˊ）。古代的鑰匙形狀像一支小勺子插進鎖裡，就借用了這個字，口語念成輕聲˙ㄕ。記法：舀湯的讀ㄔˊ，開鎖的讀˙ㄕ。"},
  {"id": "p688", "grade": 1, "word": "蘿蔔", "target": "蔔", "zhuyin": "ㄅㄛˊ", "pinyin": "bó", "wz": "ㄌㄨㄛˊ ㄅㄛˊ", "wrong": [{"z": "ㄅㄨˇ", "p": "bǔ"}, {"z": "ㄈㄨˊ", "p": "fú"}], "note": "「蘿蔔」的「蔔」讀ㄅㄛˊ（二聲），不讀「卜」的ㄅㄨˇ。", "deep": "1. 注音比較\n蔔：ㄅㄛˊ（二聲）＝蘿蔔。★「卜」（ㄅㄨˇ）是占卜的卜，跟「蔔」是兩個字，不要混\n2. 國字拆解與造字原因\n蔔：形聲字，「艸（艹）」＋「匐」省聲。從艸部表示是植物。蘿蔔埋在土裡，要整根拔出來才看得到，所以是根莖類的蔬菜。★注意「蘿蔔」兩個字都是艹頭。記法：草字頭的蔔讀ㄅㄛˊ。"},
  {"id": "p689", "grade": 1, "word": "葡萄", "target": "萄", "zhuyin": "ㄊㄠˊ", "pinyin": "táo", "wz": "ㄆㄨˊ ㄊㄠˊ", "wrong": [{"z": "ㄊㄠˇ", "p": "tǎo"}, {"z": "ㄧㄠˊ", "p": "yáo"}], "note": "「葡萄」的「萄」讀ㄊㄠˊ（二聲）。", "deep": "1. 注音比較\n萄：ㄊㄠˊ（二聲）＝葡萄、葡萄糖。誤讀ㄊㄠˇ＝與「討」相混；誤讀ㄧㄠˊ＝把右下看成「舀」\n2. 國字拆解與造字原因\n萄：形聲字，「艸（艹）」＋「匋」（ㄊㄠˊ，聲）。「葡萄」兩個字都是草字頭，而且都只用在這一個詞裡——這種只能兩個字合在一起用、拆開就沒有意思的詞，叫「連綿詞」。葡萄是漢朝從西域傳進中原的，名字也是從外國話翻過來的。記法：草字頭的萄讀二聲ㄊㄠˊ。"},
  {"id": "p690", "grade": 1, "word": "荔枝", "target": "荔", "zhuyin": "ㄌㄧˋ", "pinyin": "lì", "wz": "ㄌㄧˋ ㄓ", "wrong": [{"z": "ㄌㄧˊ", "p": "lí"}, {"z": "ㄌㄧˇ", "p": "lǐ"}], "note": "「荔枝」的「荔」讀ㄌㄧˋ（四聲）。", "deep": "1. 注音比較\n荔：ㄌㄧˋ（四聲）＝荔枝、薜荔。誤讀ㄌㄧˊ＝與「梨」「離」相混；誤讀ㄌㄧˇ＝與「李」相混\n2. 國字拆解與造字原因\n荔：形聲字，「艸（艹）」＋「劦」（ㄒㄧㄝˊ，三個力）。從艸部表示是植物。荔枝在唐朝是進貢的珍果，杜牧〈過華清宮〉「一騎紅塵妃子笑，無人知是荔枝來」寫的就是快馬千里送荔枝給楊貴妃的事。記法：草字頭的荔讀四聲。"},
  {"id": "p691", "grade": 1, "word": "鳳梨", "target": "鳳", "zhuyin": "ㄈㄥˋ", "pinyin": "fèng", "wz": "ㄈㄥˋ ㄌㄧˊ", "wrong": [{"z": "ㄈㄥ", "p": "fēng"}, {"z": "ㄈㄨㄥˋ", "p": "fòng"}], "note": "「鳳梨」「鳳凰」的「鳳」讀ㄈㄥˋ（四聲），不讀「風」的一聲。", "deep": "1. 注音比較\n鳳：ㄈㄥˋ（四聲）＝鳳梨、鳳凰、龍鳳。★「風」（ㄈㄥ，一聲）是颳風的風，跟「鳳」是兩個字\n2. 國字拆解與造字原因\n鳳：形聲字，外面是「凡」（聲），裡面是「鳥」。鳳是傳說中的百鳥之王，古人認為牠一出現天下就太平。鳳梨的果實頂上有一叢像鳳尾的葉子，所以叫鳳梨。記法：裡面有「鳥」的是鳳，讀四聲。"},
  {"id": "p692", "grade": 1, "word": "檸檬", "target": "檸", "zhuyin": "ㄋㄧㄥˊ", "pinyin": "níng", "wz": "ㄋㄧㄥˊ ㄇㄥˊ", "wrong": [{"z": "ㄌㄧㄥˊ", "p": "líng"}, {"z": "ㄋㄧㄥˋ", "p": "nìng"}], "note": "「檸檬」的「檸」讀ㄋㄧㄥˊ（ㄋ開頭），不是ㄌㄧㄥˊ。", "deep": "1. 注音比較\n檸：ㄋㄧㄥˊ（二聲）＝檸檬。誤讀ㄌㄧㄥˊ＝ㄋ、ㄌ不分；誤讀ㄋㄧㄥˋ＝與「寧可」的另一個音相混\n2. 國字拆解與造字原因\n檸：形聲字，「木」＋「寧」（聲）。從木部表示是樹。「檸檬」是英文 lemon 翻過來的音，兩個字都是木字旁，合起來才有意思，拆開來單獨用沒有意義。★ㄋ和ㄌ的分別：ㄋ的氣從鼻子出來（像「牛奶」），ㄌ的氣從舌頭兩邊出來（像「來了」）。記法：木字旁的檸讀ㄋㄧㄥˊ。"},
  {"id": "p693", "grade": 1, "word": "豆腐", "target": "腐", "zhuyin": "ㄈㄨˇ", "pinyin": "fǔ", "wz": "ㄉㄡˋ ㄈㄨˇ", "wrong": [{"z": "ㄈㄨˊ", "p": "fú"}, {"z": "ㄈㄨˋ", "p": "fù"}], "note": "「豆腐」「腐爛」的「腐」讀ㄈㄨˇ（三聲）。", "deep": "1. 注音比較\n腐：ㄈㄨˇ（三聲）＝豆腐、腐爛、腐敗、防腐劑。誤讀ㄈㄨˊ＝與「扶」「符」相混；誤讀ㄈㄨˋ＝與「付」相混\n2. 國字拆解與造字原因\n腐：形聲字，「府」（聲）＋「肉」。從肉部，本義是肉放久了壞掉、爛掉——「腐爛、腐敗」。豆腐是把黃豆磨成漿再凝結成軟軟的一塊，樣子像放軟了的東西，所以借用這個字。記法：下面有「肉」的腐讀三聲。"},
  {"id": "p694", "grade": 1, "word": "饅頭", "target": "饅", "zhuyin": "ㄇㄢˊ", "pinyin": "mán", "wz": "ㄇㄢˊ ˙ㄊㄡ", "wrong": [{"z": "ㄇㄢˋ", "p": "màn"}, {"z": "ㄨㄢˇ", "p": "wǎn"}], "note": "「饅頭」的「饅」讀ㄇㄢˊ（二聲），不讀「慢」的四聲。", "deep": "1. 注音比較\n饅：ㄇㄢˊ（二聲）＝饅頭。誤讀ㄇㄢˋ＝與「慢」相混；誤讀ㄨㄢˇ＝與「碗」相混\n2. 國字拆解與造字原因\n饅：形聲字，「食」＋「曼」（聲）。從食部表示是吃的東西，凡是從食部的字多半跟食物有關（像「飯」「餅」「餃」「飽」）。「饅頭」的「頭」在這裡讀輕聲˙ㄊㄡ，不是說它有頭。記法：食字旁的饅讀二聲。"},
  {"id": "p695", "grade": 1, "word": "粽子", "target": "粽", "zhuyin": "ㄗㄨㄥˋ", "pinyin": "zòng", "wz": "ㄗㄨㄥˋ ˙ㄗ", "wrong": [{"z": "ㄗㄨㄥ", "p": "zōng"}, {"z": "ㄓㄨㄥˋ", "p": "zhòng"}], "note": "「粽子」的「粽」讀ㄗㄨㄥˋ（四聲）。", "deep": "1. 注音比較\n粽：ㄗㄨㄥˋ（四聲）＝粽子、肉粽。誤讀ㄗㄨㄥ＝少了聲調（跟「宗」相混）；誤讀ㄓㄨㄥˋ＝ㄗ、ㄓ不分\n2. 國字拆解與造字原因\n粽：形聲字，「米」＋「宗」（聲）。從米部表示是米做的食物。端午節包粽子，是為了紀念投江的屈原——古人把米食投進江裡，希望魚不要去咬他的身體。★ㄗ是平舌音（舌尖平平抵著門牙後面），ㄓ是翹舌音（舌頭要捲起來）。記法：米字旁的粽讀ㄗㄨㄥˋ。"},
  {"id": "p696", "grade": 1, "word": "廁所", "target": "廁", "zhuyin": "ㄘㄜˋ", "pinyin": "cè", "wz": "ㄘㄜˋ ㄙㄨㄛˇ", "wrong": [{"z": "ㄗㄜˊ", "p": "zé"}, {"z": "ㄔㄜˋ", "p": "chè"}], "note": "「廁所」的「廁」讀ㄘㄜˋ（四聲）。", "deep": "1. 注音比較\n廁：ㄘㄜˋ（四聲）＝廁所、公廁。誤讀ㄗㄜˊ＝把「則」直接讀出來；誤讀ㄔㄜˋ＝ㄘ、ㄔ不分\n2. 國字拆解與造字原因\n廁：形聲字，「广」＋「則」（聲）。「广」（ㄧㄢˇ）是靠著山崖蓋的房子，凡是從广部的字多半跟房屋有關（像「店」「府」「庭」「廚」）。「廁」本來是指房子旁邊的側屋，因為廁所都蓋在旁邊，所以就用來指廁所。記法：广字頭的廁讀ㄘㄜˋ。"},
  {"id": "p697", "grade": 1, "word": "噴嚏", "target": "嚏", "zhuyin": "ㄊㄧˋ", "pinyin": "tì", "wz": "ㄆㄣ ㄊㄧˋ", "wrong": [{"z": "ㄉㄧˋ", "p": "dì"}, {"z": "ㄓˋ", "p": "zhì"}], "note": "「打噴嚏」的「嚏」讀ㄊㄧˋ（四聲）。", "deep": "1. 注音比較\n嚏：ㄊㄧˋ（四聲）＝噴嚏、打噴嚏。誤讀ㄉㄧˋ＝ㄉ、ㄊ不分；誤讀ㄓˋ＝把右下的「疐」看成別的字\n2. 國字拆解與造字原因\n嚏：形聲字，「口」＋「疐」（聲）。從口部表示這個動作是從嘴巴、鼻子發出來的。★ㄉ和ㄊ的分別：ㄊ要送氣（把手放在嘴前會感覺到一股氣），ㄉ不送氣。可以先念「他」再念「打」比較看看。記法：口字旁的嚏讀ㄊㄧˋ，要送氣。"},
  {"id": "p698", "grade": 1, "word": "澆花", "target": "澆", "zhuyin": "ㄐㄧㄠ", "pinyin": "jiāo", "wz": "ㄐㄧㄠ ㄏㄨㄚ", "wrong": [{"z": "ㄧㄠˊ", "p": "yáo"}, {"z": "ㄐㄧㄠˇ", "p": "jiǎo"}], "note": "「澆花」「澆水」的「澆」讀ㄐㄧㄠ（一聲）。", "deep": "1. 注音比較\n澆：ㄐㄧㄠ（一聲）＝澆花、澆水、澆熄。誤讀ㄧㄠˊ＝把右邊的「堯」直接讀出來；誤讀ㄐㄧㄠˇ＝與「攪」「腳」相混\n2. 國字拆解與造字原因\n澆：形聲字，「水（氵）」＋「堯」（聲）。從水部表示跟水有關，本義是把水從上面倒下去。★注意聲符不一定跟整個字同音——「堯」讀ㄧㄠˊ，「澆」卻讀ㄐㄧㄠ，這是因為古今讀音變化了。記法：三點水的澆讀一聲ㄐㄧㄠ。"},
  {"id": "p699", "grade": 1, "word": "摺紙", "target": "摺", "zhuyin": "ㄓㄜˊ", "pinyin": "zhé", "wz": "ㄓㄜˊ ㄓˇ", "wrong": [{"z": "ㄒㄧˊ", "p": "xí"}, {"z": "ㄓㄜˋ", "p": "zhè"}], "note": "「摺紙」「摺衣服」的「摺」讀ㄓㄜˊ（二聲）。", "deep": "1. 注音比較\n摺：ㄓㄜˊ（二聲）＝摺紙、摺衣服、摺疊、存摺。誤讀ㄒㄧˊ＝把右邊的「習」直接讀出來；誤讀ㄓㄜˋ＝與「這」相混\n2. 國字拆解與造字原因\n摺：形聲字，「手（扌）」＋「習」（聲）。從手部表示是用手做的動作——把紙、布對合起來壓出摺痕。「存摺」本來就是一本可以摺起來的簿子。★「摺」和「折」（ㄓㄜˊ，折斷）讀音一樣但意思不同：摺是對合，折是弄斷。記法：手字旁的摺讀二聲。"},
  {"id": "p700", "grade": 1, "word": "弄髒", "target": "髒", "zhuyin": "ㄗㄤ", "pinyin": "zāng", "wz": "ㄋㄨㄥˋ ㄗㄤ", "wrong": [{"z": "ㄗㄤˋ", "p": "zàng"}, {"z": "ㄘㄤ", "p": "cāng"}], "note": "「弄髒」「髒兮兮」的「髒」讀ㄗㄤ（一聲）。", "deep": "1. 注音比較\n髒：ㄗㄤ（一聲）＝弄髒、髒話、髒兮兮。★「臟」（ㄗㄤˋ，四聲）是心臟、內臟，跟「髒」是兩個字。誤讀ㄘㄤ＝ㄗ、ㄘ不分\n2. 國字拆解與造字原因\n髒：形聲字，「骨」＋「葬」（聲）。從骨部。「弄髒」的「弄」在這裡讀ㄋㄨㄥˋ（四聲），是「使它變成…」的意思。★比較：髒（一聲，不乾淨）／臟（四聲，身體裡的器官），一個是骨字旁、一個是肉月旁。記法：講不乾淨的髒讀一聲。"},
  {"id": "p701", "grade": 1, "word": "味道", "target": "味", "zhuyin": "ㄨㄟˋ", "pinyin": "wèi", "wz": "ㄨㄟˋ ㄉㄠˋ", "wrong": [{"z": "ㄨㄟˊ", "p": "wéi"}, {"z": "ㄇㄟˋ", "p": "mèi"}], "note": "「味道」「口味」的「味」讀ㄨㄟˋ（四聲）。", "deep": "1. 注音比較\n味：ㄨㄟˋ（四聲）＝味道、口味、香味、津津有味。誤讀ㄨㄟˊ＝與「圍」「為」相混；誤讀ㄇㄟˋ＝與「妹」相混（「妹」是女字旁）\n2. 國字拆解與造字原因\n味：形聲字，「口」＋「未」（聲）。從口部表示是舌頭嘗出來的感覺。★同樣是「未」當聲符：味（ㄨㄟˋ，口字旁）、妹（ㄇㄟˋ，女字旁）、昧（ㄇㄟˋ，日字旁）——部首不同，意思和讀音都不同，要看清楚部首再念。記法：口字旁的味讀ㄨㄟˋ。"},
  {"id": "p702", "grade": 1, "word": "果汁", "target": "汁", "zhuyin": "ㄓ", "pinyin": "zhī", "wz": "ㄍㄨㄛˇ ㄓ", "wrong": [{"z": "ㄗ", "p": "zī"}, {"z": "ㄓˋ", "p": "zhì"}], "note": "「果汁」「墨汁」的「汁」讀ㄓ（一聲）。", "deep": "1. 注音比較\n汁：ㄓ（一聲）＝果汁、墨汁、汁液。誤讀ㄗ＝ㄗ、ㄓ不分；誤讀ㄓˋ＝多加了聲調（跟「至」相混）\n2. 國字拆解與造字原因\n汁：形聲字，「水（氵）」＋「十」（聲）。從水部表示是液體。★ㄓ是翹舌音，念的時候舌尖要往上翹碰到上顎；ㄗ是平舌音，舌尖平平的抵在下門牙後面。可以連著念「知」「資」比較看看。記法：三點水的汁讀一聲ㄓ，舌頭要翹。"},
  {"id": "p703", "grade": 1, "word": "大約", "target": "約", "zhuyin": "ㄩㄝ", "pinyin": "yuē", "wz": "ㄉㄚˋ ㄩㄝ", "wrong": [{"z": "ㄩㄝˋ", "p": "yuè"}, {"z": "ㄧㄠ", "p": "yāo"}], "note": "「大約」「約會」的「約」讀ㄩㄝ（一聲），不讀四聲。", "deep": "1. 注音比較\n約：ㄩㄝ（一聲）＝大約、約會、約定、節約。★「月」「越」「樂（音樂）」才讀ㄩㄝˋ（四聲）。誤讀ㄧㄠ＝與「邀」相混\n2. 國字拆解與造字原因\n約：形聲字，「糸」＋「勺」（聲）。「糸」是絲線，本義是用繩子把東西綑起來、綁住——兩個人講好了就像用繩子綁住彼此，所以叫「約定、約會」；把用度綁緊一點就是「節約」；把數目說個大概、不綁死，就是「大約」。記法：講約定的約讀一聲。"},
  {"id": "p704", "grade": 1, "word": "香蕉", "target": "蕉", "zhuyin": "ㄐㄧㄠ", "pinyin": "jiāo", "wz": "ㄒㄧㄤ ㄐㄧㄠ", "wrong": [{"z": "ㄑㄧㄠˊ", "p": "qiáo"}, {"z": "ㄐㄧㄠˋ", "p": "jiào"}], "note": "「香蕉」的「蕉」讀ㄐㄧㄠ（一聲）。", "deep": "1. 注音比較\n蕉：ㄐㄧㄠ（一聲）＝香蕉、芭蕉、蕉農。誤讀ㄑㄧㄠˊ＝與「橋」相混；誤讀ㄐㄧㄠˋ＝多加了聲調（跟「叫」相混）\n2. 國字拆解與造字原因\n蕉：形聲字，「艸（艹）」＋「焦」（聲）。從艸部表示是植物。★同樣用「焦」當聲符的字：蕉（艹頭，植物）、礁（石字旁，海裡的岩石）、憔（豎心旁，憔悴）——部首告訴你那個字跟什麼有關。記法：草字頭的蕉讀一聲。"},
  {"id": "p705", "grade": 1, "word": "螢火蟲", "target": "螢", "zhuyin": "ㄧㄥˊ", "pinyin": "yíng", "wz": "ㄧㄥˊ ㄏㄨㄛˇ ㄔㄨㄥˊ", "wrong": [{"z": "ㄩㄥˊ", "p": "yóng"}, {"z": "ㄒㄧㄥˊ", "p": "xíng"}], "note": "「螢火蟲」的「螢」讀ㄧㄥˊ（二聲）。", "deep": "1. 注音比較\n螢：ㄧㄥˊ（二聲）＝螢火蟲、螢光、囊螢映雪。★「營」（ㄧㄥˊ，經營）、「熒」讀音相近但字不同。誤讀ㄩㄥˊ＝與「榮」相混\n2. 國字拆解與造字原因\n螢：形聲字，上面是「熒」省去下半（表示火光），下面是「虫」。合起來就是「會發光的蟲」，字形本身就把螢火蟲畫出來了。★成語「囊螢映雪」是說古人晚上沒錢點燈，就抓螢火蟲裝在袋子裡照著讀書，比喻家窮還努力向學。記法：上面是火光、下面是虫，讀二聲。"},
  {"id": "p706", "grade": 1, "word": "蜜蜂", "target": "蜂", "zhuyin": "ㄈㄥ", "pinyin": "fēng", "wz": "ㄇㄧˋ ㄈㄥ", "wrong": [{"z": "ㄈㄥˊ", "p": "féng"}, {"z": "ㄈㄥˋ", "p": "fèng"}], "note": "「蜜蜂」的「蜂」讀ㄈㄥ（一聲）。", "deep": "1. 注音比較\n蜂：ㄈㄥ（一聲）＝蜜蜂、蜂蜜、蜂窩、蜂擁而上。誤讀ㄈㄥˊ＝與「逢」「縫」相混；誤讀ㄈㄥˋ＝與「鳳」相混\n2. 國字拆解與造字原因\n蜂：形聲字，「虫」＋「夆」（ㄈㄥˊ，聲）。從虫部表示是昆蟲。★「蜜蜂」（動物）和「蜂蜜」（牠做出來的甜東西）兩個詞的字剛好前後對調，意思完全不同，要看清楚順序。記法：虫字旁的蜂讀一聲。"},
  {"id": "p707", "grade": 1, "word": "蚱蜢", "target": "蜢", "zhuyin": "ㄇㄥˇ", "pinyin": "měng", "wz": "ㄓㄚˋ ㄇㄥˇ", "wrong": [{"z": "ㄇㄥˋ", "p": "mèng"}, {"z": "ㄇㄧㄥˇ", "p": "mǐng"}], "note": "「蚱蜢」的「蜢」讀ㄇㄥˇ（三聲）。", "deep": "1. 注音比較\n蜢：ㄇㄥˇ（三聲）＝蚱蜢。誤讀ㄇㄥˋ＝與「夢」相混；誤讀ㄇㄧㄥˇ＝與「皿」相混\n2. 國字拆解與造字原因\n蜢：形聲字，「虫」＋「孟」（聲）。從虫部表示是昆蟲，讀音跟「猛」一樣是三聲。蚱蜢的後腿特別長，一跳可以跳出自己身體好幾倍遠。★「蚱」讀ㄓㄚˋ（四聲），不要念成ㄗㄚˋ。記法：虫字旁的蜢讀三聲。"},
  {"id": "p708", "grade": 1, "word": "鴨子", "target": "鴨", "zhuyin": "ㄧㄚ", "pinyin": "yā", "wz": "ㄧㄚ ˙ㄗ", "wrong": [{"z": "ㄧㄚˋ", "p": "yà"}, {"z": "ㄐㄧㄚˇ", "p": "jiǎ"}], "note": "「鴨子」「烤鴨」的「鴨」讀ㄧㄚ（一聲）。", "deep": "1. 注音比較\n鴨：ㄧㄚ（一聲）＝鴨子、烤鴨、鴨蛋。誤讀ㄧㄚˋ＝與「亞」相混；誤讀ㄐㄧㄚˇ＝把「甲」直接讀出來\n2. 國字拆解與造字原因\n鴨：形聲字，「甲」（聲）＋「鳥」。從鳥部表示是一種鳥。古人說鴨子的叫聲就像「甲甲」，所以用「甲」當聲符，既表音又像牠的叫聲。★這種照聲音造出來的字叫「擬聲」，像「貓」「鴉」也是。記法：鳥字邊的鴨讀一聲。"},
  {"id": "p709", "grade": 1, "word": "青椒", "target": "椒", "zhuyin": "ㄐㄧㄠ", "pinyin": "jiāo", "wz": "ㄑㄧㄥ ㄐㄧㄠ", "wrong": [{"z": "ㄕㄨˊ", "p": "shú"}, {"z": "ㄐㄧㄠˇ", "p": "jiǎo"}], "note": "「青椒」「辣椒」的「椒」讀ㄐㄧㄠ（一聲）。", "deep": "1. 注音比較\n椒：ㄐㄧㄠ（一聲）＝青椒、辣椒、胡椒、花椒。誤讀ㄕㄨˊ＝把右邊的「叔」直接讀出來；誤讀ㄐㄧㄠˇ＝與「腳」相混\n2. 國字拆解與造字原因\n椒：形聲字，「木」＋「叔」（聲）。從木部表示是樹木結的果實。★「叔」讀ㄕㄨˊ，「椒」卻讀ㄐㄧㄠ，這是古今音變的結果——所以看到形聲字不能直接照聲符念，要查過才算數。記法：木字旁的椒讀一聲ㄐㄧㄠ。"},
  {"id": "p710", "grade": 1, "word": "西瓜", "target": "瓜", "zhuyin": "ㄍㄨㄚ", "pinyin": "guā", "wz": "ㄒㄧ ㄍㄨㄚ", "wrong": [{"z": "ㄍㄨㄚˇ", "p": "guǎ"}, {"z": "ㄓㄠˇ", "p": "zhǎo"}], "note": "「西瓜」「瓜子」的「瓜」讀ㄍㄨㄚ（一聲）。", "deep": "1. 注音比較\n瓜：ㄍㄨㄚ（一聲）＝西瓜、南瓜、瓜子、瓜分。誤讀ㄍㄨㄚˇ＝與「寡」相混；誤讀ㄓㄠˇ＝與長得很像的「爪」（ㄓㄠˇ）相混\n2. 國字拆解與造字原因\n瓜：象形字，中間畫一顆果實，兩邊是攀爬的藤蔓，本義就是瓜類的果實。★「瓜」和「爪」（ㄓㄠˇ，爪子）字形很像，差別在中間：瓜的中間是一個圈（果實），爪沒有。「瓜分」是說像切西瓜一樣把東西分掉。記法：中間有果實的是瓜，讀一聲。"},
  {"id": "p711", "grade": 1, "word": "鉛筆", "target": "鉛", "zhuyin": "ㄑㄧㄢ", "pinyin": "qiān", "wz": "ㄑㄧㄢ ㄅㄧˇ", "wrong": [{"z": "ㄩㄢˊ", "p": "yuán"}, {"z": "ㄑㄧㄢˊ", "p": "qián"}], "note": "「鉛筆」「鉛球」的「鉛」讀ㄑㄧㄢ（一聲）。", "deep": "1. 注音比較\n鉛：ㄑㄧㄢ（一聲）＝鉛筆、鉛球、鉛字。誤讀ㄩㄢˊ＝把右邊的「㕣」看成「沿」；誤讀ㄑㄧㄢˊ＝與「錢」「前」相混\n2. 國字拆解與造字原因\n鉛：形聲字，「金」＋「㕣」（聲）。從金部表示是一種金屬。★有趣的是鉛筆裡面根本沒有鉛，是石墨；古代西方人一開始以為那是鉛，名字就這樣沿用下來了。記法：金字旁的鉛讀一聲ㄑㄧㄢ。"},
  {"id": "p712", "grade": 1, "word": "橡皮擦", "target": "橡", "zhuyin": "ㄒㄧㄤˋ", "pinyin": "xiàng", "wz": "ㄒㄧㄤˋ ㄆㄧˊ ㄘㄚ", "wrong": [{"z": "ㄒㄧㄤ", "p": "xiāng"}, {"z": "ㄒㄧㄤˇ", "p": "xiǎng"}], "note": "「橡皮擦」「橡樹」的「橡」讀ㄒㄧㄤˋ（四聲）。", "deep": "1. 注音比較\n橡：ㄒㄧㄤˋ（四聲）＝橡皮擦、橡膠、橡樹。誤讀ㄒㄧㄤ＝與「香」「箱」相混；誤讀ㄒㄧㄤˇ＝與「響」「想」相混\n2. 國字拆解與造字原因\n橡：形聲字，「木」＋「象」（聲）。從木部表示是樹。橡膠是從橡膠樹的樹汁做出來的，可以擦掉鉛筆字，所以叫「橡皮擦」。★「橡」和「像」（人字旁，好像）、「象」（大象）三個字要分清楚：木字旁的是樹。記法：木字旁的橡讀四聲。"},
  {"id": "p713", "grade": 1, "word": "剪刀", "target": "剪", "zhuyin": "ㄐㄧㄢˇ", "pinyin": "jiǎn", "wz": "ㄐㄧㄢˇ ㄉㄠ", "wrong": [{"z": "ㄐㄧㄢˋ", "p": "jiàn"}, {"z": "ㄑㄧㄢˊ", "p": "qián"}], "note": "「剪刀」「剪紙」的「剪」讀ㄐㄧㄢˇ（三聲）。", "deep": "1. 注音比較\n剪：ㄐㄧㄢˇ（三聲）＝剪刀、剪紙、剪頭髮。誤讀ㄐㄧㄢˋ＝與「箭」「劍」相混；誤讀ㄑㄧㄢˊ＝與「錢」「前」相混\n2. 國字拆解與造字原因\n剪：會意兼形聲，上面是「前」（聲），下面是「刀」。從刀部表示要用刀。★「剪」「箭」「前」三個字上半都一樣，靠下半分辨：加刀的是剪（三聲），加竹頭的是箭（四聲）。記法：下面有刀的剪讀三聲。"},
  {"id": "p714", "grade": 1, "word": "膠水", "target": "膠", "zhuyin": "ㄐㄧㄠ", "pinyin": "jiāo", "wz": "ㄐㄧㄠ ㄕㄨㄟˇ", "wrong": [{"z": "ㄌㄧㄠˊ", "p": "liáo"}, {"z": "ㄐㄧㄠˇ", "p": "jiǎo"}], "note": "「膠水」「膠帶」的「膠」讀ㄐㄧㄠ（一聲）。", "deep": "1. 注音比較\n膠：ㄐㄧㄠ（一聲）＝膠水、膠帶、塑膠、如膠似漆。誤讀ㄌㄧㄠˊ＝把右邊的「翏」看成「僚」；誤讀ㄐㄧㄠˇ＝與「攪」相混\n2. 國字拆解與造字原因\n膠：形聲字，「肉（月）」＋「翏」（聲）。從肉部，因為古代的膠是把動物的皮、骨頭熬煮出來的黏稠東西。★成語「如膠似漆」形容感情黏得像膠和漆一樣分不開。記法：肉月旁的膠讀一聲。"},
  {"id": "p715", "grade": 1, "word": "毽子", "target": "毽", "zhuyin": "ㄐㄧㄢˋ", "pinyin": "jiàn", "wz": "ㄐㄧㄢˋ ˙ㄗ", "wrong": [{"z": "ㄐㄧㄢˇ", "p": "jiǎn"}, {"z": "ㄐㄧㄢ", "p": "jiān"}], "note": "「踢毽子」的「毽」讀ㄐㄧㄢˋ（四聲）。", "deep": "1. 注音比較\n毽：ㄐㄧㄢˋ（四聲）＝毽子、踢毽子。誤讀ㄐㄧㄢˇ＝與「剪」相混；誤讀ㄐㄧㄢ＝與「肩」相混\n2. 國字拆解與造字原因\n毽：形聲字，「毛」＋「建」（聲）。從毛部，因為毽子上面那一撮是雞毛或羽毛做的，下面墊銅錢或塑膠片才有重量踢得起來。記法：毛字旁的毽讀四聲，跟「建」同韻。"},
  {"id": "p716", "grade": 1, "word": "鞦韆", "target": "鞦", "zhuyin": "ㄑㄧㄡ", "pinyin": "qiū", "wz": "ㄑㄧㄡ ㄑㄧㄢ", "wrong": [{"z": "ㄑㄧㄡˊ", "p": "qiú"}, {"z": "ㄕㄡ", "p": "shōu"}], "note": "「盪鞦韆」的「鞦」讀ㄑㄧㄡ（一聲）。", "deep": "1. 注音比較\n鞦：ㄑㄧㄡ（一聲）＝鞦韆、盪鞦韆。誤讀ㄑㄧㄡˊ＝與「球」「求」相混；誤讀ㄕㄡ＝把右邊的「秋」看錯\n2. 國字拆解與造字原因\n鞦：形聲字，「革」＋「秋」（聲）。「革」是去了毛的獸皮，凡是從革部的字多半跟皮製品有關（像「鞋」「鞭」「鞍」）——古代的鞦韆是用皮繩吊起來的，所以兩個字都從革部。記法：革字旁的鞦讀一聲，跟「秋」同音。"},
  {"id": "p717", "grade": 1, "word": "洗澡", "target": "澡", "zhuyin": "ㄗㄠˇ", "pinyin": "zǎo", "wz": "ㄒㄧˇ ㄗㄠˇ", "wrong": [{"z": "ㄗㄠˋ", "p": "zào"}, {"z": "ㄘㄠˇ", "p": "cǎo"}], "note": "「洗澡」的「澡」讀ㄗㄠˇ（三聲）。", "deep": "1. 注音比較\n澡：ㄗㄠˇ（三聲）＝洗澡、澡堂。誤讀ㄗㄠˋ＝與「皂」「造」相混；誤讀ㄘㄠˇ＝ㄗ、ㄘ不分\n2. 國字拆解與造字原因\n澡：形聲字，「水（氵）」＋「喿」（ㄗㄠˋ，聲）。從水部表示要用水。★同樣用「喿」當聲符的字很多：澡（三點水，洗澡）、燥（火字旁，乾燥）、躁（足字旁，急躁）、噪（口字旁，噪音）——記部首就分得出來。記法：三點水的澡讀三聲。"},
  {"id": "p718", "grade": 1, "word": "刷牙", "target": "刷", "zhuyin": "ㄕㄨㄚ", "pinyin": "shuā", "wz": "ㄕㄨㄚ ㄧㄚˊ", "wrong": [{"z": "ㄕㄨㄞ", "p": "shuāi"}, {"z": "ㄙㄨㄚ", "p": "suā"}], "note": "「刷牙」「刷子」的「刷」讀ㄕㄨㄚ（一聲）。", "deep": "1. 注音比較\n刷：ㄕㄨㄚ（一聲）＝刷牙、刷子、印刷、刷卡。誤讀ㄕㄨㄞ＝與「摔」「甩」相混；誤讀ㄙㄨㄚ＝ㄕ、ㄙ不分\n2. 國字拆解與造字原因\n刷：會意字，左邊是「屍」加「巾」（用布擦拭），右邊是「刂」（刀）。本義是用布或工具把東西刮乾淨。「印刷」也是這個意思——把墨刷在版上再印到紙上。記法：右邊有立刀旁的刷讀一聲ㄕㄨㄚ。"},
  {"id": "p719", "grade": 1, "word": "漱口", "target": "漱", "zhuyin": "ㄕㄨˋ", "pinyin": "shù", "wz": "ㄕㄨˋ ㄎㄡˇ", "wrong": [{"z": "ㄙㄡˋ", "p": "sòu"}, {"z": "ㄕㄨ", "p": "shū"}], "note": "「漱口」的「漱」讀ㄕㄨˋ（四聲）。", "deep": "1. 注音比較\n漱：ㄕㄨˋ（四聲）＝漱口、洗漱。誤讀ㄙㄡˋ＝與「嗽」（咳嗽）相混；誤讀ㄕㄨ＝少了聲調（跟「書」相混）\n2. 國字拆解與造字原因\n漱：形聲字，「水（氵）」＋「敕」（聲）。從水部表示用水。★「漱」（ㄕㄨˋ，三點水，漱口）和「嗽」（ㄙㄡˋ，口字旁，咳嗽）長得很像，一個用水、一個用嘴，讀音也不同。記法：三點水的漱讀ㄕㄨˋ。"},
  {"id": "p720", "grade": 1, "word": "肥皂", "target": "皂", "zhuyin": "ㄗㄠˋ", "pinyin": "zào", "wz": "ㄈㄟˊ ㄗㄠˋ", "wrong": [{"z": "ㄗㄠˇ", "p": "zǎo"}, {"z": "ㄅㄞˊ", "p": "bái"}], "note": "「肥皂」的「皂」讀ㄗㄠˋ（四聲）。", "deep": "1. 注音比較\n皂：ㄗㄠˋ（四聲）＝肥皂、香皂、皂白。誤讀ㄗㄠˇ＝與「早」「澡」相混；誤讀ㄅㄞˊ＝把上面的「白」直接讀出來\n2. 國字拆解與造字原因\n皂：上面是「白」，下面是「七」，但整個字的意思是黑色——古人用一種黑色的果實（皂莢）洗衣服去汙，所以洗滌用的東西就叫「皂」。★成語「不分青紅皂白」的「皂」就是黑色，整句是說是非黑白都分不清。記法：肥皂的皂讀四聲。"},
  {"id": "p721", "grade": 1, "word": "枕頭", "target": "枕", "zhuyin": "ㄓㄣˇ", "pinyin": "zhěn", "wz": "ㄓㄣˇ ˙ㄊㄡ", "wrong": [{"z": "ㄔㄣˊ", "p": "chén"}, {"z": "ㄗㄣˇ", "p": "zěn"}], "note": "「枕頭」的「枕」讀ㄓㄣˇ（三聲）。", "deep": "1. 注音比較\n枕：ㄓㄣˇ（三聲）＝枕頭、枕邊、高枕無憂；ㄓㄣˋ（四聲）＝文言裡當動詞用（枕戈待旦）。誤讀ㄔㄣˊ＝與「沉」相混；誤讀ㄗㄣˇ＝ㄗ、ㄓ不分\n2. 國字拆解與造字原因\n枕：形聲字，「木」＋「冘」（聲）。從木部，因為古代的枕頭是木頭或瓷做的硬枕，不是棉花做的。★成語「高枕無憂」是說把枕頭墊高好好睡，比喻沒有煩惱。記法：木字旁的枕讀三聲。"},
  {"id": "p722", "grade": 1, "word": "窗戶", "target": "窗", "zhuyin": "ㄔㄨㄤ", "pinyin": "chuāng", "wz": "ㄔㄨㄤ ㄏㄨˋ", "wrong": [{"z": "ㄔㄨㄤˊ", "p": "chuáng"}, {"z": "ㄘㄨㄤ", "p": "cuāng"}], "note": "「窗戶」「窗簾」的「窗」讀ㄔㄨㄤ（一聲）。", "deep": "1. 注音比較\n窗：ㄔㄨㄤ（一聲）＝窗戶、窗簾、同窗。誤讀ㄔㄨㄤˊ＝與「床」相混；誤讀ㄘㄨㄤ＝ㄘ、ㄔ不分\n2. 國字拆解與造字原因\n窗：上面是「穴」（洞），下面是「囪」（煙囪的形狀）。古人住的房子在牆上或屋頂開個洞讓光和空氣進來，那個洞就是窗。★「同窗」是指同班同學——古人一起在同一扇窗下讀書。記法：穴字頭的窗讀一聲，跟「床」（ㄔㄨㄤˊ）不一樣。"},
  {"id": "p723", "grade": 1, "word": "樓梯", "target": "梯", "zhuyin": "ㄊㄧ", "pinyin": "tī", "wz": "ㄌㄡˊ ㄊㄧ", "wrong": [{"z": "ㄉㄧˋ", "p": "dì"}, {"z": "ㄊㄧˊ", "p": "tí"}], "note": "「樓梯」「電梯」的「梯」讀ㄊㄧ（一聲）。", "deep": "1. 注音比較\n梯：ㄊㄧ（一聲）＝樓梯、電梯、梯子、階梯。誤讀ㄉㄧˋ＝把右邊的「弟」直接讀出來；誤讀ㄊㄧˊ＝與「提」「題」相混\n2. 國字拆解與造字原因\n梯：形聲字，「木」＋「弟」（聲）。從木部，因為最早的梯子是木頭做的。「弟」在這裡只表音，而且音已經變了（弟讀ㄉㄧˋ，梯讀ㄊㄧ）。★「階梯」比喻一步一步往上的過程。記法：木字旁的梯讀一聲ㄊㄧ。"},
  {"id": "p724", "grade": 1, "word": "冰箱", "target": "箱", "zhuyin": "ㄒㄧㄤ", "pinyin": "xiāng", "wz": "ㄅㄧㄥ ㄒㄧㄤ", "wrong": [{"z": "ㄒㄧㄤˋ", "p": "xiàng"}, {"z": "ㄕㄤ", "p": "shāng"}], "note": "「冰箱」「箱子」的「箱」讀ㄒㄧㄤ（一聲）。", "deep": "1. 注音比較\n箱：ㄒㄧㄤ（一聲）＝冰箱、箱子、行李箱。誤讀ㄒㄧㄤˋ＝與「像」「橡」相混；誤讀ㄕㄤ＝ㄒ、ㄕ不分\n2. 國字拆解與造字原因\n箱：形聲字，「竹」＋「相」（聲）。從竹部，因為古代的箱子是用竹片編的。★同樣讀ㄒㄧㄤ的還有「香」「鄉」；讀ㄒㄧㄤˋ的有「像」「橡」「向」——同音不同字，要看部首和意思。記法：竹字頭的箱讀一聲。"},
  {"id": "p725", "grade": 1, "word": "老師", "target": "師", "zhuyin": "ㄕ", "pinyin": "shī", "wz": "ㄌㄠˇ ㄕ", "wrong": [{"z": "ㄙ", "p": "sī"}, {"z": "ㄕˋ", "p": "shì"}], "note": "「老師」「師父」的「師」讀ㄕ（一聲），舌頭要翹。", "deep": "1. 注音比較\n師：ㄕ（一聲）＝老師、師父、軍師、出師。誤讀ㄙ＝ㄕ、ㄙ不分（跟「思」「私」相混）；誤讀ㄕˋ＝與「是」「事」相混\n2. 國字拆解與造字原因\n師：本義是古代的軍隊編制（二千五百人為一師），因為軍隊要有人帶領、教導，引申成傳授本領的人——「老師」。★ㄕ是翹舌音（舌尖上翹），ㄙ是平舌音（舌尖平放）。可以連著念「師」「思」比較看看。記法：老師的師讀一聲ㄕ，舌頭要翹。"},
  {"id": "p726", "grade": 1, "word": "謝謝", "target": "謝", "zhuyin": "ㄒㄧㄝˋ", "pinyin": "xiè", "wz": "ㄒㄧㄝˋ ˙ㄒㄧㄝ", "wrong": [{"z": "ㄒㄧㄝˊ", "p": "xié"}, {"z": "ㄕㄜˋ", "p": "shè"}], "note": "「謝謝」的第一個「謝」讀ㄒㄧㄝˋ（四聲），第二個讀輕聲。", "deep": "1. 注音比較\n謝：ㄒㄧㄝˋ（四聲）＝謝謝、感謝、凋謝、謝幕。誤讀ㄒㄧㄝˊ＝與「邪」「斜」相混；誤讀ㄕㄜˋ＝把右下的「射」直接讀出來\n2. 國字拆解與造字原因\n謝：形聲字，「言」＋「射」（聲）。從言部表示是用話說出來的——本義是道歉、推辭，後來變成感謝。花掉下來叫「凋謝」，也是「退下、辭去」的意思。★疊字詞的第二個字常讀輕聲：謝謝、爺爺、舅舅都是。記法：言字旁的謝讀四聲。"},
  {"id": "p727", "grade": 1, "word": "警察", "target": "察", "zhuyin": "ㄔㄚˊ", "pinyin": "chá", "wz": "ㄐㄧㄥˇ ㄔㄚˊ", "wrong": [{"z": "ㄔㄚˇ", "p": "chǎ"}, {"z": "ㄗㄚˊ", "p": "zá"}], "note": "「警察」「觀察」的「察」讀ㄔㄚˊ（二聲）。", "deep": "1. 注音比較\n察：ㄔㄚˊ（二聲）＝警察、觀察、察覺、視察。誤讀ㄔㄚˇ＝聲調錯（跟「叉」的變化相混）；誤讀ㄗㄚˊ＝ㄗ、ㄔ不分\n2. 國字拆解與造字原因\n察：形聲字，「宀」（房子）＋「祭」（聲）。古人在屋裡祭祀時要仔仔細細檢查供品，所以本義是「仔細看」——「觀察、察覺」。「警察」就是負責警戒、查看的人。記法：寶蓋頭的察讀二聲。"},
  {"id": "p728", "grade": 1, "word": "廚師", "target": "廚", "zhuyin": "ㄔㄨˊ", "pinyin": "chú", "wz": "ㄔㄨˊ ㄕ", "wrong": [{"z": "ㄕㄨˋ", "p": "shù"}, {"z": "ㄓㄨˊ", "p": "zhú"}], "note": "「廚師」「廚房」的「廚」讀ㄔㄨˊ（二聲）。", "deep": "1. 注音比較\n廚：ㄔㄨˊ（二聲）＝廚師、廚房、下廚。誤讀ㄕㄨˋ＝把裡面的「尌」看成「樹」；誤讀ㄓㄨˊ＝ㄓ、ㄔ不分\n2. 國字拆解與造字原因\n廚：形聲字，「广」（房子）＋「尌」（聲）。從广部表示是一個房間——煮飯的房間就是廚房。★「廚」（广字頭，煮飯的地方）和「櫥」（木字旁，櫥櫃）長得像，一個是房間、一個是家具。記法：广字頭的廚讀二聲。"},
  {"id": "p729", "grade": 1, "word": "阿姨", "target": "姨", "zhuyin": "ㄧˊ", "pinyin": "yí", "wz": "ㄚ ㄧˊ", "wrong": [{"z": "ㄧˇ", "p": "yǐ"}, {"z": "ㄒㄧˊ", "p": "xí"}], "note": "「阿姨」的「姨」讀ㄧˊ（二聲）；這裡的「阿」讀ㄚ（一聲）。", "deep": "1. 注音比較\n姨：ㄧˊ（二聲）＝阿姨、姨丈、姨媽。誤讀ㄧˇ＝與「以」「椅」相混；誤讀ㄒㄧˊ＝與「席」相混\n2. 國字拆解與造字原因\n姨：形聲字，「女」＋「夷」（聲）。從女部表示是女性親屬的稱呼。★「姨」是媽媽的姊妹；爸爸的姊妹叫「姑」（ㄍㄨ）。兩個都是女字旁，別記反了。★「阿姨」的「阿」在稱呼前面讀ㄚ（一聲），不讀ㄜ。記法：女字旁的姨讀二聲。"},
  {"id": "p730", "grade": 1, "word": "舅舅", "target": "舅", "zhuyin": "ㄐㄧㄡˋ", "pinyin": "jiù", "wz": "ㄐㄧㄡˋ ˙ㄐㄧㄡ", "wrong": [{"z": "ㄐㄧㄡˇ", "p": "jiǔ"}, {"z": "ㄑㄧㄡˊ", "p": "qiú"}], "note": "「舅舅」的第一個「舅」讀ㄐㄧㄡˋ（四聲），第二個讀輕聲。", "deep": "1. 注音比較\n舅：ㄐㄧㄡˋ（四聲）＝舅舅、舅媽、國舅。誤讀ㄐㄧㄡˇ＝與「九」「久」相混；誤讀ㄑㄧㄡˊ＝與「求」相混\n2. 國字拆解與造字原因\n舅：形聲字，上面是「臼」（ㄐㄧㄡˋ，舂米的石臼，聲符），下面是「男」。從「男」表示是男性親屬——媽媽的兄弟叫舅舅。★爸爸的兄弟叫「伯」（比爸爸大）或「叔」（比爸爸小）。記法：下面是「男」的舅讀四聲。"},
  {"id": "p731", "grade": 1, "word": "爺爺", "target": "爺", "zhuyin": "ㄧㄝˊ", "pinyin": "yé", "wz": "ㄧㄝˊ ˙ㄧㄝ", "wrong": [{"z": "ㄧㄝˇ", "p": "yě"}, {"z": "ㄦˊ", "p": "ér"}], "note": "「爺爺」的第一個「爺」讀ㄧㄝˊ（二聲），第二個讀輕聲。", "deep": "1. 注音比較\n爺：ㄧㄝˊ（二聲）＝爺爺、老爺、大爺。誤讀ㄧㄝˇ＝與「也」「野」相混；誤讀ㄦˊ＝把上面的「父」看錯\n2. 國字拆解與造字原因\n爺：形聲字，上面是「父」，下面是「耶」（聲）。從「父」表示是長輩男性。★〈木蘭詩〉「軍書十二卷，卷卷有爺名」的「爺」就是父親——古時候「爺」是稱爸爸，後來才變成稱祖父。記法：父字頭的爺讀二聲。"},
  {"id": "p732", "grade": 1, "word": "農夫", "target": "夫", "zhuyin": "ㄈㄨ", "pinyin": "fū", "wz": "ㄋㄨㄥˊ ㄈㄨ", "wrong": [{"z": "ㄈㄨˊ", "p": "fú"}, {"z": "ㄈㄨˋ", "p": "fù"}], "note": "「農夫」「丈夫」的「夫」讀ㄈㄨ（一聲）。", "deep": "1. 注音比較\n夫：ㄈㄨ（一聲）＝農夫、丈夫、夫妻、車夫；ㄈㄨˊ（二聲）＝文言的發語詞（「夫戰，勇氣也」）。誤讀ㄈㄨˋ＝與「父」「付」相混\n2. 國字拆解與造字原因\n夫：象形字，在「大」（張手站立的人）上面加一橫，那一橫是插在頭髮上的簪子——古代男子成年才束髮插簪，所以「夫」本義是成年男子。★注意「夫」和「父」不一樣：父（ㄈㄨˋ）是爸爸。記法：講成年男子的夫讀一聲。"},
  {"id": "p733", "grade": 1, "word": "書包", "target": "包", "zhuyin": "ㄅㄠ", "pinyin": "bāo", "wz": "ㄕㄨ ㄅㄠ", "wrong": [{"z": "ㄅㄠˇ", "p": "bǎo"}, {"z": "ㄆㄠˊ", "p": "páo"}], "note": "「書包」「包子」的「包」讀ㄅㄠ（一聲）。", "deep": "1. 注音比較\n包：ㄅㄠ（一聲）＝書包、包子、包裝、麵包。誤讀ㄅㄠˇ＝與「飽」「寶」相混；誤讀ㄆㄠˊ＝與「袍」「炮」相混\n2. 國字拆解與造字原因\n包：象形兼會意，外面是「勹」（彎起來把東西裹住的樣子），裡面是「巳」（還沒出生的胎兒），本義是母親懷著胎兒——把東西整個裹在裡面，所以引申成「包起來」。★從「勹」的字多半有「裹住」的意思，像「勺」「匀」。記法：包讀一聲ㄅㄠ，跟「飽」（三聲）不同。"},
  {"id": "p734", "grade": 1, "word": "棉被", "target": "被", "zhuyin": "ㄅㄟˋ", "pinyin": "bèi", "wz": "ㄇㄧㄢˊ ㄅㄟˋ", "wrong": [{"z": "ㄆㄧ", "p": "pī"}, {"z": "ㄅㄟ", "p": "bēi"}], "note": "「棉被」「被子」讀ㄅㄟˋ；文言裡當「披」用時才讀ㄆㄧ。", "deep": "1. 注音比較\n被：ㄅㄟˋ（四聲）＝棉被、被子、被人發現；ㄆㄧ（一聲）＝文言中同「披」（如「被髮」＝披頭散髮）。誤讀ㄅㄟ＝少了聲調（跟「杯」相混）\n2. 國字拆解與造字原因\n被：形聲字，「衣（衤）」＋「皮」（聲）。從衣部表示是蓋在身上的東西，本義就是被子。蓋在身上→引申為「加在身上」，所以「被人發現」的「被」表示承受、被動。★注意左邊是衣字旁（衤，五畫），不是示字旁（礻，四畫）。記法：衣字旁的被讀四聲。"},
  {"id": "p735", "grade": 2, "word": "縫衣服", "target": "縫", "zhuyin": "ㄈㄥˊ", "pinyin": "féng", "wz": "ㄈㄥˊ ㄧ ˙ㄈㄨ", "wrong": [{"z": "ㄈㄥˋ", "p": "fèng"}, {"z": "ㄈㄥ", "p": "fēng"}], "note": "動詞「縫衣服」讀ㄈㄥˊ（二聲）；名詞「縫隙」「裂縫」讀ㄈㄥˋ（四聲）。", "deep": "1. 注音比較\n縫：ㄈㄥˊ（二聲）＝縫衣服、縫補、縫紉（用針線把布接起來，動詞）；ㄈㄥˋ（四聲）＝縫隙、裂縫、門縫（接合處的細長空隙，名詞）\n2. 國字拆解與造字原因\n縫：形聲字，「糸」＋「逢」（聲）。「糸」是絲線，用線把兩塊布接在一起就是「縫」（動詞，二聲）；接起來的地方會留下一條細細的痕，那條痕就是「縫」（名詞，四聲）。記法：動作二聲、地方四聲。"},
  {"id": "p736", "grade": 2, "word": "盛大", "target": "盛", "zhuyin": "ㄕㄥˋ", "pinyin": "shèng", "wz": "ㄕㄥˋ ㄉㄚˋ", "wrong": [{"z": "ㄔㄥˊ", "p": "chéng"}, {"z": "ㄕㄥ", "p": "shēng"}], "note": "「盛大」「豐盛」讀ㄕㄥˋ；「盛飯」「盛湯」讀ㄔㄥˊ。", "deep": "1. 注音比較\n盛：ㄕㄥˋ（四聲）＝盛大、豐盛、茂盛、興盛（形容多、旺）；ㄔㄥˊ（二聲）＝盛飯、盛湯（把東西裝進容器，動詞）\n2. 國字拆解與造字原因\n盛：形聲字，「皿」＋「成」（聲）。「皿」是器皿，本義是把穀物裝滿在器皿裡祭祀——裝東西的動作讀ㄔㄥˊ；裝得滿滿的樣子，引申成「多、旺盛」，讀ㄕㄥˋ。記法：裝東西二聲，很旺盛四聲。"},
  {"id": "p737", "grade": 2, "word": "裝載", "target": "載", "zhuyin": "ㄗㄞˋ", "pinyin": "zài", "wz": "ㄓㄨㄤ ㄗㄞˋ", "wrong": [{"z": "ㄗㄞˇ", "p": "zǎi"}, {"z": "ㄗㄞ", "p": "zāi"}], "note": "「裝載」「載重」讀ㄗㄞˋ（四聲）；「記載」「刊載」讀ㄗㄞˇ（三聲）。", "deep": "1. 注音比較\n載：ㄗㄞˋ（四聲）＝裝載、載重、載客、滿載而歸（用車船裝東西）；ㄗㄞˇ（三聲）＝記載、刊載、轉載、一年半載（寫下來、年）\n2. 國字拆解與造字原因\n載：形聲字，「車」＋「𢦏」（聲）。從車部，本義是用車裝東西——這個意思讀四聲。把事情「裝」進書裡寫下來，就是「記載」，讀三聲。記法：用車裝東西四聲，寫在書上三聲。"},
  {"id": "p738", "grade": 2, "word": "電風扇", "target": "扇", "zhuyin": "ㄕㄢˋ", "pinyin": "shàn", "wz": "ㄉㄧㄢˋ ㄈㄥ ㄕㄢˋ", "wrong": [{"z": "ㄕㄢ", "p": "shān"}, {"z": "ㄕㄢˇ", "p": "shǎn"}], "note": "名詞「電風扇」「扇子」讀ㄕㄢˋ（四聲）；動詞「扇風」「扇涼」讀ㄕㄢ（一聲）。", "deep": "1. 注音比較\n扇：ㄕㄢˋ（四聲）＝電風扇、扇子、一扇門（名詞、量詞）；ㄕㄢ（一聲）＝扇風、扇涼、扇動（搧的動作，動詞）。誤讀ㄕㄢˇ＝與「閃」相混\n2. 國字拆解與造字原因\n扇：會意字，上面是「戶」（單扇的門），下面是「羽」（羽毛）。古代的門是一片一片開合的，扇子搖起來也是一開一合，所以借門來造字。★東西本身讀四聲，搧的動作讀一聲。記法：名詞四聲、動詞一聲。"},
  {"id": "p739", "grade": 2, "word": "卡片", "target": "卡", "zhuyin": "ㄎㄚˇ", "pinyin": "kǎ", "wz": "ㄎㄚˇ ㄆㄧㄢˋ", "wrong": [{"z": "ㄑㄧㄚˇ", "p": "qiǎ"}, {"z": "ㄎㄚ", "p": "kā"}], "note": "「卡片」「卡通」讀ㄎㄚˇ；「關卡」「卡住」讀ㄑㄧㄚˇ。", "deep": "1. 注音比較\n卡：ㄎㄚˇ（三聲）＝卡片、卡通、悠遊卡（外國話翻過來的詞）；ㄑㄧㄚˇ（三聲）＝關卡、卡住、卡在中間（夾住、檢查站）\n2. 國字拆解與造字原因\n卡：會意字，上面是「上」、下面是「下」，上不去也下不來，就是「夾在中間」——這個本義讀ㄑㄧㄚˇ（卡住、關卡）。後來英文的 card 翻成中文借用這個字，讀ㄎㄚˇ。記法：外來語讀ㄎㄚˇ，夾住讀ㄑㄧㄚˇ。"},
  {"id": "p740", "grade": 2, "word": "等待", "target": "待", "zhuyin": "ㄉㄞˋ", "pinyin": "dài", "wz": "ㄉㄥˇ ㄉㄞˋ", "wrong": [{"z": "ㄉㄞ", "p": "dāi"}, {"z": "ㄊㄞˋ", "p": "tài"}], "note": "「等待」「招待」讀ㄉㄞˋ（四聲）；口語「待會兒」「待在家裡」讀ㄉㄞ（一聲）。", "deep": "1. 注音比較\n待：ㄉㄞˋ（四聲）＝等待、招待、對待、待遇；ㄉㄞ（一聲）＝待會兒、待在家裡（口語，同「呆」）。誤讀ㄊㄞˋ＝ㄉ、ㄊ不分\n2. 國字拆解與造字原因\n待：形聲字，「彳」＋「寺」（聲）。「彳」（ㄔˋ）是走路的意思，凡是從彳部的字多半跟行走、行為有關（像「行」「往」「後」「德」）。本義是在路上停下來等人。記法：雙人旁的待，讀書音四聲、口語音一聲。"},
  {"id": "p741", "grade": 2, "word": "開會", "target": "會", "zhuyin": "ㄏㄨㄟˋ", "pinyin": "huì", "wz": "ㄎㄞ ㄏㄨㄟˋ", "wrong": [{"z": "ㄎㄨㄞˋ", "p": "kuài"}, {"z": "ㄏㄨㄟˇ", "p": "huǐ"}], "note": "「開會」「機會」讀ㄏㄨㄟˋ；「會計」（管帳的）讀ㄎㄨㄞˋ。", "deep": "1. 注音比較\n會：ㄏㄨㄟˋ（四聲）＝開會、機會、學會、社會；ㄎㄨㄞˋ（四聲）＝會計（管帳目的人或工作）；ㄏㄨㄟˇ（三聲）＝一會兒（口語的短時間）\n2. 國字拆解與造字原因\n會：會意字，古文字像一個有蓋子的容器，蓋子和身體剛好合起來，本義是「聚合、合在一起」——人聚在一起就是「開會、聚會」（ㄏㄨㄟˋ）。把一筆一筆帳目「合」起來算總數，就是「會計」，這個意思讀ㄎㄨㄞˋ。記法：只有「會計」讀ㄎㄨㄞˋ。"},
  {"id": "p742", "grade": 2, "word": "傳說", "target": "傳", "zhuyin": "ㄔㄨㄢˊ", "pinyin": "chuán", "wz": "ㄔㄨㄢˊ ㄕㄨㄛ", "wrong": [{"z": "ㄓㄨㄢˋ", "p": "zhuàn"}, {"z": "ㄔㄨㄢˋ", "p": "chuàn"}], "note": "「傳說」「傳話」讀ㄔㄨㄢˊ；「傳記」「自傳」讀ㄓㄨㄢˋ。", "deep": "1. 注音比較\n傳：ㄔㄨㄢˊ（二聲）＝傳說、傳話、傳達、流傳（一手交一手地遞過去）；ㄓㄨㄢˋ（四聲）＝傳記、自傳、水滸傳（記載一個人生平的書）\n2. 國字拆解與造字原因\n傳：形聲字，「人（亻）」＋「專」（聲）。從人部，本義是人接著人把東西或話遞下去（ㄔㄨㄢˊ）。把一個人的事情寫下來、傳給後人看的書，就叫「傳」（ㄓㄨㄢˋ）。記法：動作二聲，書名四聲。"},
  {"id": "p743", "grade": 2, "word": "划船", "target": "划", "zhuyin": "ㄏㄨㄚˊ", "pinyin": "huá", "wz": "ㄏㄨㄚˊ ㄔㄨㄢˊ", "wrong": [{"z": "ㄏㄨㄚˋ", "p": "huà"}, {"z": "ㄍㄜ", "p": "gē"}], "note": "「划船」「划算」的「划」讀ㄏㄨㄚˊ（二聲）。", "deep": "1. 注音比較\n划：ㄏㄨㄚˊ（二聲）＝划船、划水、划算。★「劃」（ㄏㄨㄚˋ，四聲）是計畫、劃分，跟「划」是兩個字。誤讀ㄍㄜ＝把左邊的「戈」直接讀出來\n2. 國字拆解與造字原因\n划：形聲字，「戈」＋「刂」（刀）。本義是用槳撥水前進。★分辨：划（用槳撥水、划算）／劃（用刀分開、計畫、筆劃）——一個講水上的動作，一個講切分和規畫。記法：划船的划讀二聲。"},
  {"id": "p744", "grade": 2, "word": "量體重", "target": "量", "zhuyin": "ㄌㄧㄤˊ", "pinyin": "liáng", "wz": "ㄌㄧㄤˊ ㄊㄧˇ ㄓㄨㄥˋ", "wrong": [{"z": "ㄌㄧㄤˋ", "p": "liàng"}, {"z": "ㄌㄧㄤˇ", "p": "liǎng"}], "note": "動詞「量體重」「量身高」讀ㄌㄧㄤˊ（二聲）；名詞「分量」「數量」讀ㄌㄧㄤˋ（四聲）。", "deep": "1. 注音比較\n量：ㄌㄧㄤˊ（二聲）＝量體重、量身高、量血壓、丈量（測量的動作）；ㄌㄧㄤˋ（四聲）＝分量、數量、力量、量力而為（多少、限度）\n2. 國字拆解與造字原因\n量：會意字，上面是漏斗形的量器，下面是「重」，本義是用器具測東西有多重多長——這個動作讀二聲；量出來的結果（多少）讀四聲。記法：正在量二聲，量出來的數目四聲。"},
  {"id": "p745", "grade": 2, "word": "散步", "target": "散", "zhuyin": "ㄙㄢˋ", "pinyin": "sàn", "wz": "ㄙㄢˋ ㄅㄨˋ", "wrong": [{"z": "ㄙㄢˇ", "p": "sǎn"}, {"z": "ㄕㄢˋ", "p": "shàn"}], "note": "「散步」「解散」讀ㄙㄢˋ（四聲）；「散文」「鬆散」讀ㄙㄢˇ（三聲）。", "deep": "1. 注音比較\n散：ㄙㄢˋ（四聲）＝散步、解散、散會、擴散（分開、走開的動作）；ㄙㄢˇ（三聲）＝散文、鬆散、散裝（不集中的樣子）。誤讀ㄕㄢˋ＝ㄙ、ㄕ不分\n2. 國字拆解與造字原因\n散：會意字，右邊是「攵」（手拿棍子），把麻的纖維敲開打散，本義就是「使分開」。做分開的動作讀四聲；形容東西本來就不成一團、鬆鬆的，讀三聲。記法：動詞四聲、形容詞三聲。"},
  {"id": "p746", "grade": 2, "word": "長頸鹿", "target": "頸", "zhuyin": "ㄐㄧㄥˇ", "pinyin": "jǐng", "wz": "ㄔㄤˊ ㄐㄧㄥˇ ㄌㄨˋ", "wrong": [{"z": "ㄐㄧㄥ", "p": "jīng"}, {"z": "ㄐㄧㄤˋ", "p": "jiàng"}], "note": "「長頸鹿」「頸部」的「頸」讀ㄐㄧㄥˇ（三聲）。", "deep": "1. 注音比較\n頸：ㄐㄧㄥˇ（三聲）＝長頸鹿、頸部、頸椎、刎頸之交；ㄍㄥˇ（三聲）＝脖頸兒（口語）。誤讀ㄐㄧㄥ＝少了聲調；誤讀ㄐㄧㄤˋ＝與「將」相混\n2. 國字拆解與造字原因\n頸：形聲字，「巠」（聲）＋「頁」。「頁」（ㄒㄧㄝˋ）本來就是「頭」，凡是從頁部的字多半跟頭、臉有關（像「頭」「額」「顏」「頰」）——脖子在頭下面，所以也從頁部。★「長頸鹿」的「長」在這裡讀ㄔㄤˊ（長短的長），不是ㄓㄤˇ。記法：頁字邊的頸讀三聲。"},
  {"id": "p747", "grade": 2, "word": "露水", "target": "露", "zhuyin": "ㄌㄨˋ", "pinyin": "lù", "wz": "ㄌㄨˋ ㄕㄨㄟˇ", "wrong": [{"z": "ㄌㄡˋ", "p": "lòu"}, {"z": "ㄌㄨˊ", "p": "lú"}], "note": "「露水」「露天」讀ㄌㄨˋ（讀書音）；口語「露臉」「露出來」讀ㄌㄡˋ。", "deep": "1. 注音比較\n露：ㄌㄨˋ（四聲）＝露水、露珠、露天、朝露、暴露（讀書音）；ㄌㄡˋ（四聲）＝露臉、露一手、露餡兒（口語音）\n2. 國字拆解與造字原因\n露：形聲字，「雨」＋「路」（聲）。從雨部表示是天上落下的水氣——夜裡水氣遇冷凝在草葉上，就是露水。露水在外面沒有遮蔽，所以引申出「顯出來、沒有遮蓋」的意思。記法：講水珠、講讀書音讀ㄌㄨˋ，口語「露出來」讀ㄌㄡˋ。"},
  {"id": "p748", "grade": 2, "word": "樹枝", "target": "枝", "zhuyin": "ㄓ", "pinyin": "zhī", "wz": "ㄕㄨˋ ㄓ", "wrong": [{"z": "ㄐㄧ", "p": "jī"}, {"z": "ㄓˇ", "p": "zhǐ"}], "note": "「樹枝」「枝葉」的「枝」讀ㄓ（一聲）。", "deep": "1. 注音比較\n枝：ㄓ（一聲）＝樹枝、枝葉、一枝筆、節外生枝。誤讀ㄐㄧ＝與「機」相混；誤讀ㄓˇ＝與「只」「紙」相混\n2. 國字拆解與造字原因\n枝：形聲字，「木」＋「支」（聲）。「支」本來就是手拿著一根分岔出來的枝條，所以「枝」既表音也表意——從樹幹分出來的就是枝。★成語「節外生枝」是說本來已經處理好的事，又多出新的麻煩。記法：木字旁的枝讀一聲ㄓ。"},
  {"id": "p749", "grade": 2, "word": "花瓣", "target": "瓣", "zhuyin": "ㄅㄢˋ", "pinyin": "bàn", "wz": "ㄏㄨㄚ ㄅㄢˋ", "wrong": [{"z": "ㄅㄧㄢˋ", "p": "biàn"}, {"z": "ㄅㄢˇ", "p": "bǎn"}], "note": "「花瓣」「蒜瓣」的「瓣」讀ㄅㄢˋ（四聲）。", "deep": "1. 注音比較\n瓣：ㄅㄢˋ（四聲）＝花瓣、蒜瓣、豆瓣醬。誤讀ㄅㄧㄢˋ＝與「辨」「辯」「辮」相混；誤讀ㄅㄢˇ＝與「板」相混\n2. 國字拆解與造字原因\n瓣：中間是「瓜」，兩邊是「辛」。瓜切開來一片一片的，所以「瓣」指的是可以一片片分開的東西——花瓣、蒜瓣。★同樣兩邊是「辛」的四個字要分清楚：辨（中間是點與撇，分辨）、辯（中間是言，辯論）、辮（中間是糸，辮子）、瓣（中間是瓜，花瓣）。記法：中間放什麼就跟什麼有關。"},
  {"id": "p750", "grade": 2, "word": "楓葉", "target": "楓", "zhuyin": "ㄈㄥ", "pinyin": "fēng", "wz": "ㄈㄥ ㄧㄝˋ", "wrong": [{"z": "ㄈㄥˊ", "p": "féng"}, {"z": "ㄈㄥˋ", "p": "fèng"}], "note": "「楓葉」「楓樹」的「楓」讀ㄈㄥ（一聲）。", "deep": "1. 注音比較\n楓：ㄈㄥ（一聲）＝楓葉、楓樹、楓林。誤讀ㄈㄥˊ＝與「逢」「縫」相混；誤讀ㄈㄥˋ＝與「鳳」相混\n2. 國字拆解與造字原因\n楓：形聲字，「木」＋「風」（聲）。從木部表示是樹。古人說楓樹的葉子薄，只要有一點風就整片搖動，所以用「風」當聲符。★楓葉秋天會變紅，是因為天冷之後綠色的葉綠素分解掉，本來就在葉子裡的紅色才顯出來。記法：木字旁的楓讀一聲，跟「風」同音。"},
  {"id": "p751", "grade": 2, "word": "彩虹", "target": "虹", "zhuyin": "ㄏㄨㄥˊ", "pinyin": "hóng", "wz": "ㄘㄞˇ ㄏㄨㄥˊ", "wrong": [{"z": "ㄍㄨㄥ", "p": "gōng"}, {"z": "ㄏㄨㄥˇ", "p": "hǒng"}], "note": "「彩虹」的「虹」讀ㄏㄨㄥˊ（二聲）。", "deep": "1. 注音比較\n虹：ㄏㄨㄥˊ（二聲）＝彩虹、虹橋。誤讀ㄍㄨㄥ＝把右邊的「工」直接讀出來；誤讀ㄏㄨㄥˇ＝與「哄」相混\n2. 國字拆解與造字原因\n虹：形聲字，「虫」＋「工」（聲）。古人以為彩虹是天上一條會喝水的大蟲（龍），所以造字時從虫部。★彩虹其實是陽光穿過空中的小水滴時被分開成七種顏色形成的，所以雨後太陽出來時最容易看到。記法：虫字旁的虹讀二聲。"},
  {"id": "p752", "grade": 2, "word": "冰雹", "target": "雹", "zhuyin": "ㄅㄠˊ", "pinyin": "báo", "wz": "ㄅㄧㄥ ㄅㄠˊ", "wrong": [{"z": "ㄅㄠ", "p": "bāo"}, {"z": "ㄅㄠˋ", "p": "bào"}], "note": "「冰雹」的「雹」讀ㄅㄠˊ（二聲）。", "deep": "1. 注音比較\n雹：ㄅㄠˊ（二聲）＝冰雹、雹災。誤讀ㄅㄠ＝與「包」相混；誤讀ㄅㄠˋ＝與「暴」「爆」相混\n2. 國字拆解與造字原因\n雹：形聲字，「雨」＋「包」（聲）。從雨部表示是天上落下來的東西。★冰雹是雲裡的小水滴被強烈上升氣流一次次帶上帶下，一層一層結成冰球，重到氣流托不住就掉下來，所以剖開常常有一圈一圈的紋路。記法：雨字頭的雹讀二聲。"},
  {"id": "p753", "grade": 2, "word": "瀑布", "target": "瀑", "zhuyin": "ㄆㄨˋ", "pinyin": "pù", "wz": "ㄆㄨˋ ㄅㄨˋ", "wrong": [{"z": "ㄅㄠˋ", "p": "bào"}, {"z": "ㄆㄨˊ", "p": "pú"}], "note": "「瀑布」的「瀑」讀ㄆㄨˋ（四聲），不讀「暴」的ㄅㄠˋ。", "deep": "1. 注音比較\n瀑：ㄆㄨˋ（四聲）＝瀑布、飛瀑。誤讀ㄅㄠˋ＝把右邊的「暴」直接讀出來；誤讀ㄆㄨˊ＝與「葡」「僕」相混\n2. 國字拆解與造字原因\n瀑：形聲字，「水（氵）」＋「暴」（聲）。從水部表示跟水有關。水從高處猛然衝下來，聲勢很「暴」（猛烈），因此得名；遠遠看像掛在山壁上的一匹白布，所以叫「瀑布」。★注意聲符是「暴」但字讀ㄆㄨˋ，不能照著念。記法：三點水的瀑讀ㄆㄨˋ。"},
  {"id": "p754", "grade": 2, "word": "山谷", "target": "谷", "zhuyin": "ㄍㄨˇ", "pinyin": "gǔ", "wz": "ㄕㄢ ㄍㄨˇ", "wrong": [{"z": "ㄩˋ", "p": "yù"}, {"z": "ㄍㄨˋ", "p": "gù"}], "note": "「山谷」「谷底」的「谷」讀ㄍㄨˇ（三聲）。", "deep": "1. 注音比較\n谷：ㄍㄨˇ（三聲）＝山谷、谷底、進退維谷；ㄩˋ（四聲）＝吐谷渾（古代的族名）。誤讀ㄍㄨˋ＝與「故」「顧」相混\n2. 國字拆解與造字原因\n谷：象形字，上面畫水從山間流下來的樣子，下面是「口」（谷口），本義就是兩山之間的低地。★成語「進退維谷」是說前進後退都像掉進山谷一樣走不出去，比喻左右為難。記法：山谷的谷讀三聲。"},
  {"id": "p755", "grade": 2, "word": "蜈蚣", "target": "蚣", "zhuyin": "ㄍㄨㄥ", "pinyin": "gōng", "wz": "ㄨˊ ㄍㄨㄥ", "wrong": [{"z": "ㄍㄨㄥˋ", "p": "gòng"}, {"z": "ㄙㄨㄥ", "p": "sōng"}], "note": "「蜈蚣」的「蚣」讀ㄍㄨㄥ（一聲）。", "deep": "1. 注音比較\n蚣：ㄍㄨㄥ（一聲）＝蜈蚣。誤讀ㄍㄨㄥˋ＝與「共」相混；誤讀ㄙㄨㄥ＝與「松」相混\n2. 國字拆解與造字原因\n蚣：形聲字，「虫」＋「公」（聲）。從虫部表示是蟲。★「蜈蚣」兩個字都是虫字旁，是連綿詞（要合在一起才有意思）。蜈蚣每一節長一對腳，並不是真的有一百隻腳。記法：虫字旁＋公，讀一聲。"},
  {"id": "p756", "grade": 2, "word": "蝌蚪", "target": "蚪", "zhuyin": "ㄉㄡˇ", "pinyin": "dǒu", "wz": "ㄎㄜ ㄉㄡˇ", "wrong": [{"z": "ㄉㄡˋ", "p": "dòu"}, {"z": "ㄉㄡ", "p": "dōu"}], "note": "「蝌蚪」的「蚪」讀ㄉㄡˇ（三聲）。", "deep": "1. 注音比較\n蚪：ㄉㄡˇ（三聲）＝蝌蚪。誤讀ㄉㄡˋ＝與「豆」「鬥」相混；誤讀ㄉㄡ＝少了聲調\n2. 國字拆解與造字原因\n蚪：形聲字，「虫」＋「斗」（聲）。「斗」是古代量米的杓子，圓圓的一個頭加一根柄——蝌蚪的樣子正好就是圓頭加尾巴，所以用「斗」既表音又像形。★蝌蚪長大會先長後腳、再長前腳，尾巴慢慢縮掉才變成青蛙。記法：虫字旁＋斗，讀三聲。"},
  {"id": "p757", "grade": 2, "word": "蝙蝠", "target": "蝠", "zhuyin": "ㄈㄨˊ", "pinyin": "fú", "wz": "ㄅㄧㄢ ㄈㄨˊ", "wrong": [{"z": "ㄈㄨˋ", "p": "fù"}, {"z": "ㄅㄧㄢˋ", "p": "biàn"}], "note": "「蝙蝠」的「蝠」讀ㄈㄨˊ（二聲），跟「福」同音。", "deep": "1. 注音比較\n蝠：ㄈㄨˊ（二聲）＝蝙蝠。誤讀ㄈㄨˋ＝與「富」「副」相混；誤讀ㄅㄧㄢˋ＝把前一個字的音套過來\n2. 國字拆解與造字原因\n蝠：形聲字，「虫」＋「畐」（聲）。因為「蝠」跟「福」同音，中國人把蝙蝠當成吉祥的象徵，畫五隻蝙蝠叫「五福臨門」。★蝙蝠是會飛的哺乳動物，不是鳥，牠靠發出超音波聽回音來認路。記法：虫字旁的蝠讀二聲，跟「福」同音。"},
  {"id": "p758", "grade": 2, "word": "駱駝", "target": "駝", "zhuyin": "ㄊㄨㄛˊ", "pinyin": "tuó", "wz": "ㄌㄨㄛˋ ㄊㄨㄛˊ", "wrong": [{"z": "ㄊㄨㄛˇ", "p": "tuǒ"}, {"z": "ㄊㄨㄛ", "p": "tuō"}], "note": "「駱駝」的「駝」讀ㄊㄨㄛˊ（二聲）。", "deep": "1. 注音比較\n駝：ㄊㄨㄛˊ（二聲）＝駱駝、駝背、駝鈴。誤讀ㄊㄨㄛˇ＝與「妥」相混；誤讀ㄊㄨㄛ＝與「拖」相混\n2. 國字拆解與造字原因\n駝：形聲字，「馬」＋「它」（聲）。從馬部表示是可以騎、可以載東西的牲口。駱駝背上的肉峰存的是脂肪，不是水；牠靠這些脂肪在沙漠裡撐很多天。★背彎彎的像駱駝的峰，就叫「駝背」。記法：馬字旁的駝讀二聲。"},
  {"id": "p759", "grade": 2, "word": "老鷹", "target": "鷹", "zhuyin": "ㄧㄥ", "pinyin": "yīng", "wz": "ㄌㄠˇ ㄧㄥ", "wrong": [{"z": "ㄧㄥˊ", "p": "yíng"}, {"z": "ㄧㄥˇ", "p": "yǐng"}], "note": "「老鷹」的「鷹」讀ㄧㄥ（一聲）。", "deep": "1. 注音比較\n鷹：ㄧㄥ（一聲）＝老鷹、鷹架、鷹爪。誤讀ㄧㄥˊ＝與「螢」「營」相混；誤讀ㄧㄥˇ＝與「影」相混\n2. 國字拆解與造字原因\n鷹：形聲字，下面是「鳥」，上面是聲符。從鳥部表示是一種猛禽。老鷹的眼力極好，可以在很高的空中看見地上的小動物，所以形容人看得準叫「鷹眼」。★「鷹架」是蓋房子時搭的架子，因為工人站在上面像鷹站在高處。記法：下面是鳥的鷹讀一聲。"},
  {"id": "p760", "grade": 2, "word": "獅子", "target": "獅", "zhuyin": "ㄕ", "pinyin": "shī", "wz": "ㄕ ˙ㄗ", "wrong": [{"z": "ㄙ", "p": "sī"}, {"z": "ㄕˊ", "p": "shí"}], "note": "「獅子」的「獅」讀ㄕ（一聲），舌頭要翹。", "deep": "1. 注音比較\n獅：ㄕ（一聲）＝獅子、雄獅、舞獅。誤讀ㄙ＝ㄕ、ㄙ不分（跟「思」相混）；誤讀ㄕˊ＝與「石」「時」相混\n2. 國字拆解與造字原因\n獅：形聲字，「犬（犭）」＋「師」（聲）。「犭」叫犬字旁，凡是從犬部的字多半是走獸（像「狗」「狼」「猴」「獅」）。★中國本來沒有獅子，是漢朝從西域傳進來的，名字也是從外國話翻過來的音。記法：犬字旁的獅讀一聲ㄕ。"},
  {"id": "p761", "grade": 2, "word": "斑馬", "target": "斑", "zhuyin": "ㄅㄢ", "pinyin": "bān", "wz": "ㄅㄢ ㄇㄚˇ", "wrong": [{"z": "ㄅㄢˇ", "p": "bǎn"}, {"z": "ㄅㄧㄢ", "p": "biān"}], "note": "「斑馬」「斑點」的「斑」讀ㄅㄢ（一聲）。", "deep": "1. 注音比較\n斑：ㄅㄢ（一聲）＝斑馬、斑點、雀斑、斑駁。誤讀ㄅㄢˇ＝與「板」相混；誤讀ㄅㄧㄢ＝與「編」相混\n2. 國字拆解與造字原因\n斑：中間是「文」（花紋），兩邊是「王」（其實是「玉」）。本義是玉上面雜色的花紋，引申成一切一塊一塊的花紋——斑馬身上黑白相間的條紋就是。★「斑」（花紋）和「班」（班級，中間是刀）長得很像，中間放什麼要看清楚。記法：中間是「文」的斑讀一聲。"},
  {"id": "p762", "grade": 2, "word": "犀牛", "target": "犀", "zhuyin": "ㄒㄧ", "pinyin": "xī", "wz": "ㄒㄧ ㄋㄧㄡˊ", "wrong": [{"z": "ㄒㄧˊ", "p": "xí"}, {"z": "ㄕ", "p": "shī"}], "note": "「犀牛」「犀利」的「犀」讀ㄒㄧ（一聲）。", "deep": "1. 注音比較\n犀：ㄒㄧ（一聲）＝犀牛、犀利、心有靈犀。誤讀ㄒㄧˊ＝與「席」「習」相混；誤讀ㄕ＝ㄒ、ㄕ不分\n2. 國字拆解與造字原因\n犀：下面是「牛」，表示是一種像牛的大獸。犀牛角很堅硬鋒利，所以「犀利」就是形容話說得或東西用起來又快又利。★成語「心有靈犀」是說兩個人心意相通，就像犀牛角中間那條白線一路通到底。記法：下面有牛的犀讀一聲。"},
  {"id": "p763", "grade": 2, "word": "鱷魚", "target": "鱷", "zhuyin": "ㄜˋ", "pinyin": "è", "wz": "ㄜˋ ㄩˊ", "wrong": [{"z": "ㄍㄜ", "p": "gē"}, {"z": "ㄩˋ", "p": "yù"}], "note": "「鱷魚」的「鱷」讀ㄜˋ（四聲），跟「餓」同音。", "deep": "1. 注音比較\n鱷：ㄜˋ（四聲）＝鱷魚、鱷梨。誤讀ㄍㄜ＝把右邊看成「哥」；誤讀ㄩˋ＝把後面的「魚」的音套過來\n2. 國字拆解與造字原因\n鱷：形聲字，「魚」＋「咢」（聲）。從魚部，因為古人把水裡的大型動物都歸在魚部（像「鯨」也是，其實鯨魚不是魚）。★「鱷魚的眼淚」是一句俗話，說鱷魚吃東西時眼睛會流水，看起來像在哭，用來比喻假慈悲。記法：魚字旁的鱷讀四聲，跟「餓」同音。"},
  {"id": "p764", "grade": 2, "word": "海豚", "target": "豚", "zhuyin": "ㄊㄨㄣˊ", "pinyin": "tún", "wz": "ㄏㄞˇ ㄊㄨㄣˊ", "wrong": [{"z": "ㄊㄨㄣ", "p": "tūn"}, {"z": "ㄉㄨㄣˋ", "p": "dùn"}], "note": "「海豚」的「豚」讀ㄊㄨㄣˊ（二聲）。", "deep": "1. 注音比較\n豚：ㄊㄨㄣˊ（二聲）＝海豚、河豚。誤讀ㄊㄨㄣ＝與「吞」相混；誤讀ㄉㄨㄣˋ＝與「頓」相混\n2. 國字拆解與造字原因\n豚：會意字，左邊是「肉（月）」，右邊是「豕」（ㄕˇ，豬）。本義是小豬。海豚圓圓胖胖的樣子像小豬，所以叫海豚。★海豚和鯨魚一樣是哺乳動物，用肺呼吸，要浮出水面換氣。記法：有「豕」（豬）的豚讀二聲。"},
  {"id": "p765", "grade": 2, "word": "鯨魚", "target": "鯨", "zhuyin": "ㄐㄧㄥ", "pinyin": "jīng", "wz": "ㄐㄧㄥ ㄩˊ", "wrong": [{"z": "ㄐㄧㄥˋ", "p": "jìng"}, {"z": "ㄌㄧㄤˊ", "p": "liáng"}], "note": "「鯨魚」的「鯨」讀ㄐㄧㄥ（一聲）。", "deep": "1. 注音比較\n鯨：ㄐㄧㄥ（一聲）＝鯨魚、鯨吞、藍鯨。誤讀ㄐㄧㄥˋ＝與「鏡」「敬」相混；誤讀ㄌㄧㄤˊ＝把右邊看成「涼」\n2. 國字拆解與造字原因\n鯨：形聲字，「魚」＋「京」（聲）。「京」有「大」的意思，鯨是海裡最大的動物，用「京」既表音又表意。★鯨其實不是魚，是哺乳動物：用肺呼吸、胎生、會餵奶。「蠶食鯨吞」是說像蠶慢慢啃、像鯨一口吞，比喻一點一點或一次全部占去。記法：魚字旁的鯨讀一聲。"},
  {"id": "p766", "grade": 2, "word": "螃蟹", "target": "蟹", "zhuyin": "ㄒㄧㄝˋ", "pinyin": "xiè", "wz": "ㄆㄤˊ ㄒㄧㄝˋ", "wrong": [{"z": "ㄐㄧㄝˇ", "p": "jiě"}, {"z": "ㄒㄧㄝˊ", "p": "xié"}], "note": "「螃蟹」的「蟹」讀ㄒㄧㄝˋ（四聲）。", "deep": "1. 注音比較\n蟹：ㄒㄧㄝˋ（四聲）＝螃蟹、蟹殼、蟹黃。誤讀ㄐㄧㄝˇ＝把上面的「解」直接讀出來；誤讀ㄒㄧㄝˊ＝與「邪」相混\n2. 國字拆解與造字原因\n蟹：形聲字，「虫」＋「解」（聲）。從虫部——古人把昆蟲以外的小動物也常歸在虫部。螃蟹橫著走，是因為牠的腳關節只能左右彎，不能前後伸。★注意聲符是「解」（ㄐㄧㄝˇ）但字讀ㄒㄧㄝˋ。記法：下面是虫的蟹讀四聲。"},
  {"id": "p767", "grade": 2, "word": "蝦子", "target": "蝦", "zhuyin": "ㄒㄧㄚ", "pinyin": "xiā", "wz": "ㄒㄧㄚ ˙ㄗ", "wrong": [{"z": "ㄏㄚˊ", "p": "há"}, {"z": "ㄐㄧㄚˇ", "p": "jiǎ"}], "note": "「蝦子」「龍蝦」讀ㄒㄧㄚ（一聲）；只有「蝦蟆」（青蛙、蟾蜍）讀ㄏㄚˊ。", "deep": "1. 注音比較\n蝦：ㄒㄧㄚ（一聲）＝蝦子、龍蝦、蝦米；ㄏㄚˊ（二聲）＝蝦蟆（同「蛤蟆」）。誤讀ㄐㄧㄚˇ＝把右邊的「叚」看成「假」\n2. 國字拆解與造字原因\n蝦：形聲字，「虫」＋「叚」（聲）。從虫部。★蝦子煮熟會變紅，是因為殼裡的紅色素本來被蛋白質包住，加熱後蛋白質變性，紅色就顯出來了。記法：吃的蝦讀一聲ㄒㄧㄚ，「蝦蟆」讀ㄏㄚˊ。"},
  {"id": "p768", "grade": 2, "word": "珊瑚", "target": "瑚", "zhuyin": "ㄏㄨˊ", "pinyin": "hú", "wz": "ㄕㄢ ㄏㄨˊ", "wrong": [{"z": "ㄏㄨˇ", "p": "hǔ"}, {"z": "ㄍㄨˇ", "p": "gǔ"}], "note": "「珊瑚」的「瑚」讀ㄏㄨˊ（二聲）。", "deep": "1. 注音比較\n瑚：ㄏㄨˊ（二聲）＝珊瑚、珊瑚礁。誤讀ㄏㄨˇ＝與「虎」相混；誤讀ㄍㄨˇ＝與「古」相混\n2. 國字拆解與造字原因\n瑚：形聲字，「玉（王）」＋「胡」（聲）。從玉部表示古人把珊瑚當成寶石。★珊瑚不是石頭也不是植物，是很多小小的珊瑚蟲一代一代把石灰質留下來堆成的，所以「珊瑚」兩個字都是王（玉）字旁。記法：王字旁的瑚讀二聲。"},
  {"id": "p769", "grade": 2, "word": "沙灘", "target": "灘", "zhuyin": "ㄊㄢ", "pinyin": "tān", "wz": "ㄕㄚ ㄊㄢ", "wrong": [{"z": "ㄊㄢˊ", "p": "tán"}, {"z": "ㄋㄢˊ", "p": "nán"}], "note": "「沙灘」「海灘」的「灘」讀ㄊㄢ（一聲）。", "deep": "1. 注音比較\n灘：ㄊㄢ（一聲）＝沙灘、海灘、灘頭。誤讀ㄊㄢˊ＝與「壇」「談」相混；誤讀ㄋㄢˊ＝把右邊的「難」直接讀出來\n2. 國字拆解與造字原因\n灘：形聲字，「水（氵）」＋「難」（聲）。從水部。本義是水邊沙石堆積、水又淺又急的地方——船走到這裡很「難」通過，所以用「難」當聲符，既表音也帶意思。記法：三點水的灘讀一聲ㄊㄢ。"},
  {"id": "p770", "grade": 2, "word": "稻田", "target": "稻", "zhuyin": "ㄉㄠˋ", "pinyin": "dào", "wz": "ㄉㄠˋ ㄊㄧㄢˊ", "wrong": [{"z": "ㄉㄠ", "p": "dāo"}, {"z": "ㄊㄠˊ", "p": "táo"}], "note": "「稻田」「稻米」的「稻」讀ㄉㄠˋ（四聲）。", "deep": "1. 注音比較\n稻：ㄉㄠˋ（四聲）＝稻田、稻米、稻穀、水稻。誤讀ㄉㄠ＝與「刀」相混；誤讀ㄊㄠˊ＝與「陶」「桃」相混\n2. 國字拆解與造字原因\n稻：形聲字，「禾」＋「舀」（聲）。「禾」是稻麥一類的穀物，穗子垂下來的樣子；「舀」是用手從臼裡取米。從禾部的字多半跟穀物、農事有關（像「稻」「秧」「穗」「稅」）。記法：禾字旁的稻讀四聲。"},
  {"id": "p771", "grade": 2, "word": "稻穗", "target": "穗", "zhuyin": "ㄙㄨㄟˋ", "pinyin": "suì", "wz": "ㄉㄠˋ ㄙㄨㄟˋ", "wrong": [{"z": "ㄏㄨㄟˋ", "p": "huì"}, {"z": "ㄙㄨㄟˇ", "p": "suǐ"}], "note": "「稻穗」「麥穗」的「穗」讀ㄙㄨㄟˋ（四聲）。", "deep": "1. 注音比較\n穗：ㄙㄨㄟˋ（四聲）＝稻穗、麥穗、抽穗。誤讀ㄏㄨㄟˋ＝把右邊的「惠」直接讀出來；誤讀ㄙㄨㄟˇ＝與「髓」相混\n2. 國字拆解與造字原因\n穗：形聲字，「禾」＋「惠」（聲）。從禾部表示是穀物的一部分——穀粒長在莖的頂端聚成一串，就是穗。★稻子長得越飽滿，穗就垂得越低，所以有一句話說「稻穗越飽滿，頭垂得越低」，用來勸人越有本事越要謙虛。記法：禾字旁的穗讀四聲。"},
  {"id": "p772", "grade": 2, "word": "芹菜", "target": "芹", "zhuyin": "ㄑㄧㄣˊ", "pinyin": "qín", "wz": "ㄑㄧㄣˊ ㄘㄞˋ", "wrong": [{"z": "ㄐㄧㄣ", "p": "jīn"}, {"z": "ㄑㄧㄥˊ", "p": "qíng"}], "note": "「芹菜」的「芹」讀ㄑㄧㄣˊ（二聲）。", "deep": "1. 注音比較\n芹：ㄑㄧㄣˊ（二聲）＝芹菜、獻芹。誤讀ㄐㄧㄣ＝與「斤」相混；誤讀ㄑㄧㄥˊ＝與「情」「晴」相混（ㄣ、ㄥ不分）\n2. 國字拆解與造字原因\n芹：形聲字，「艸（艹）」＋「斤」（聲）。從艸部表示是蔬菜。★ㄣ和ㄥ的分別：ㄣ的舌尖抵住上牙齦、嘴巴比較閉（芹ㄑㄧㄣˊ）；ㄥ的舌根抬起、聲音在鼻腔後面（情ㄑㄧㄥˊ）。記法：草字頭的芹讀ㄑㄧㄣˊ，是ㄣ不是ㄥ。"},
  {"id": "p773", "grade": 2, "word": "菠菜", "target": "菠", "zhuyin": "ㄅㄛ", "pinyin": "bō", "wz": "ㄅㄛ ㄘㄞˋ", "wrong": [{"z": "ㄅㄛˊ", "p": "bó"}, {"z": "ㄆㄛ", "p": "pō"}], "note": "「菠菜」的「菠」讀ㄅㄛ（一聲）。", "deep": "1. 注音比較\n菠：ㄅㄛ（一聲）＝菠菜、菠蘿。誤讀ㄅㄛˊ＝與「薄」「泊」相混；誤讀ㄆㄛ＝ㄅ、ㄆ不分\n2. 國字拆解與造字原因\n菠：形聲字，「艸（艹）」＋「波」（聲）。從艸部表示是蔬菜。★ㄅ和ㄆ的分別：ㄆ要送氣（把手放嘴前會有一股氣），ㄅ不送氣。可以先念「坡」再念「玻」比較看看。★菠菜是唐朝從尼泊爾一帶傳進來的，所以古時候也叫「菠薐菜」。記法：草字頭的菠讀一聲ㄅㄛ。"},
  {"id": "p774", "grade": 2, "word": "洋蔥", "target": "蔥", "zhuyin": "ㄘㄨㄥ", "pinyin": "cōng", "wz": "ㄧㄤˊ ㄘㄨㄥ", "wrong": [{"z": "ㄘㄨㄥˊ", "p": "cóng"}, {"z": "ㄗㄨㄥ", "p": "zōng"}], "note": "「洋蔥」「青蔥」的「蔥」讀ㄘㄨㄥ（一聲）。", "deep": "1. 注音比較\n蔥：ㄘㄨㄥ（一聲）＝洋蔥、青蔥、蔥花、蔥鬱。誤讀ㄘㄨㄥˊ＝與「從」相混；誤讀ㄗㄨㄥ＝ㄗ、ㄘ不分\n2. 國字拆解與造字原因\n蔥：形聲字，「艸（艹）」＋「悤」（聲）。從艸部表示是植物。「蔥」也可以形容青綠茂盛的樣子，例如「鬱鬱蔥蔥」。★切洋蔥會流眼淚，是因為切開時放出的含硫氣體碰到眼睛的水變成刺激的酸。記法：草字頭的蔥讀一聲。"},
  {"id": "p775", "grade": 2, "word": "大蒜", "target": "蒜", "zhuyin": "ㄙㄨㄢˋ", "pinyin": "suàn", "wz": "ㄉㄚˋ ㄙㄨㄢˋ", "wrong": [{"z": "ㄙㄨㄢ", "p": "suān"}, {"z": "ㄙㄨㄢˇ", "p": "suǎn"}], "note": "「大蒜」「蒜頭」的「蒜」讀ㄙㄨㄢˋ（四聲）。", "deep": "1. 注音比較\n蒜：ㄙㄨㄢˋ（四聲）＝大蒜、蒜頭、蒜泥。誤讀ㄙㄨㄢ＝與「酸」相混；誤讀ㄙㄨㄢˇ＝與「算」的變化相混（「算」也是ㄙㄨㄢˋ）\n2. 國字拆解與造字原因\n蒜：形聲字，「艸（艹）」＋「祘」（ㄙㄨㄢˋ，聲）。從艸部表示是植物。一整顆蒜頭是由好幾片「蒜瓣」合起來的，所以「瓣」這個字也用在這裡。★蒜切開會辣，是因為它含有蒜素，這也是它能殺菌的原因。記法：草字頭的蒜讀四聲。"},
  {"id": "p776", "grade": 2, "word": "蘑菇", "target": "菇", "zhuyin": "ㄍㄨ", "pinyin": "gū", "wz": "ㄇㄛˊ ㄍㄨ", "wrong": [{"z": "ㄍㄨˇ", "p": "gǔ"}, {"z": "ㄍㄨˋ", "p": "gù"}], "note": "「蘑菇」「香菇」的「菇」讀ㄍㄨ（一聲）。", "deep": "1. 注音比較\n菇：ㄍㄨ（一聲）＝蘑菇、香菇、金針菇。誤讀ㄍㄨˇ＝與「古」「鼓」相混；誤讀ㄍㄨˋ＝與「故」相混\n2. 國字拆解與造字原因\n菇：形聲字，「艸（艹）」＋「姑」（聲）。從艸部——古人把菇類也當成草木的一種。★其實菇不是植物，是真菌：它不會行光合作用，靠分解枯木、落葉取得養分，所以長在陰暗潮溼的地方。記法：草字頭的菇讀一聲。"},
  {"id": "p777", "grade": 2, "word": "竹筍", "target": "筍", "zhuyin": "ㄙㄨㄣˇ", "pinyin": "sǔn", "wz": "ㄓㄨˊ ㄙㄨㄣˇ", "wrong": [{"z": "ㄙㄨㄣ", "p": "sūn"}, {"z": "ㄒㄩㄣˊ", "p": "xún"}], "note": "「竹筍」的「筍」讀ㄙㄨㄣˇ（三聲）。", "deep": "1. 注音比較\n筍：ㄙㄨㄣˇ（三聲）＝竹筍、筍乾、雨後春筍。誤讀ㄙㄨㄣ＝與「孫」相混；誤讀ㄒㄩㄣˊ＝與「尋」相混\n2. 國字拆解與造字原因\n筍：形聲字，「竹」＋「旬」（聲）。從竹部表示是竹子的一部分——竹子剛從土裡冒出來的嫩芽就是筍。★成語「雨後春筍」是說春雨過後竹筍一根根冒出來，比喻同類的事物大量出現。記法：竹字頭的筍讀三聲。"},
  {"id": "p778", "grade": 2, "word": "蜘蛛", "target": "蛛", "zhuyin": "ㄓㄨ", "pinyin": "zhū", "wz": "ㄓ ㄓㄨ", "wrong": [{"z": "ㄓㄨˊ", "p": "zhú"}, {"z": "ㄓㄨˇ", "p": "zhǔ"}], "note": "「蜘蛛」的「蛛」讀ㄓㄨ（一聲）。", "deep": "1. 注音比較\n蛛：ㄓㄨ（一聲）＝蜘蛛、蛛絲馬跡、蜘蛛網。誤讀ㄓㄨˊ＝與「竹」「逐」相混；誤讀ㄓㄨˇ＝與「主」「煮」相混\n2. 國字拆解與造字原因\n蛛：形聲字，「虫」＋「朱」（聲）。★蜘蛛不是昆蟲：昆蟲六隻腳、身體分頭胸腹三段，蜘蛛八隻腳、身體只分兩段。★「蛛絲馬跡」是說像蜘蛛絲和馬蹄印那樣細微的線索。記法：虫字旁＋朱，讀一聲。"},
  {"id": "p779", "grade": 2, "word": "青蛙", "target": "蛙", "zhuyin": "ㄨㄚ", "pinyin": "wā", "wz": "ㄑㄧㄥ ㄨㄚ", "wrong": [{"z": "ㄨㄚˇ", "p": "wǎ"}, {"z": "ㄍㄨㄟ", "p": "guī"}], "note": "「青蛙」的「蛙」讀ㄨㄚ（一聲）。", "deep": "1. 注音比較\n蛙：ㄨㄚ（一聲）＝青蛙、牛蛙、井底之蛙。誤讀ㄨㄚˇ＝與「瓦」相混；誤讀ㄍㄨㄟ＝把右邊的「圭」看成別的字\n2. 國字拆解與造字原因\n蛙：形聲字，「虫」＋「圭」（聲）。★成語「井底之蛙」出自《莊子》，說住在井底的青蛙以為天空只有井口那麼大，比喻見識狹小。★青蛙小時候是蝌蚪，用鰓在水裡呼吸；長大後用肺，也能靠溼潤的皮膚換氣。記法：虫字旁的蛙讀一聲ㄨㄚ。"},
  {"id": "p780", "grade": 2, "word": "松鼠", "target": "鼠", "zhuyin": "ㄕㄨˇ", "pinyin": "shǔ", "wz": "ㄙㄨㄥ ㄕㄨˇ", "wrong": [{"z": "ㄙㄨˇ", "p": "sǔ"}, {"z": "ㄕㄨˋ", "p": "shù"}], "note": "「松鼠」「老鼠」的「鼠」讀ㄕㄨˇ（三聲）。", "deep": "1. 注音比較\n鼠：ㄕㄨˇ（三聲）＝松鼠、老鼠、鼠輩、鼠目寸光。誤讀ㄙㄨˇ＝ㄕ、ㄙ不分；誤讀ㄕㄨˋ＝與「樹」「數」相混\n2. 國字拆解與造字原因\n鼠：象形字，上面畫牠的頭和一口尖牙，下面畫腳和一條長尾巴。「鼠」自己就是一個部首。★老鼠的門牙一輩子都在長，所以牠必須不停啃硬東西把牙磨短。★「鼠目寸光」形容眼光短淺。記法：鼠讀三聲ㄕㄨˇ，舌頭要翹。"},
  {"id": "p781", "grade": 2, "word": "刺蝟", "target": "蝟", "zhuyin": "ㄨㄟˋ", "pinyin": "wèi", "wz": "ㄘˋ ㄨㄟˋ", "wrong": [{"z": "ㄨㄟˇ", "p": "wěi"}, {"z": "ㄨㄟˊ", "p": "wéi"}], "note": "「刺蝟」的「蝟」讀ㄨㄟˋ（四聲）。", "deep": "1. 注音比較\n蝟：ㄨㄟˋ（四聲）＝刺蝟、蝟集。誤讀ㄨㄟˇ＝與「尾」相混；誤讀ㄨㄟˊ＝與「圍」相混\n2. 國字拆解與造字原因\n蝟：形聲字，「虫」＋「胃」（聲）。★刺蝟身上的刺其實是變硬的毛，遇到危險時牠會縮成一顆球，把刺全部朝外。★「蝟集」是形容事情像刺蝟的刺一樣一根根密密麻麻地聚過來。記法：虫字旁＋胃，讀四聲。"},
  {"id": "p782", "grade": 2, "word": "麻煩", "target": "煩", "zhuyin": "ㄈㄢˊ", "pinyin": "fán", "wz": "ㄇㄚˊ ㄈㄢˊ", "wrong": [{"z": "ㄈㄢˇ", "p": "fǎn"}, {"z": "ㄒㄧㄚˋ", "p": "xià"}], "note": "「麻煩」「煩惱」的「煩」讀ㄈㄢˊ（二聲）。", "deep": "1. 注音比較\n煩：ㄈㄢˊ（二聲）＝麻煩、煩惱、煩躁、不厭其煩。誤讀ㄈㄢˇ＝與「反」相混；誤讀ㄒㄧㄚˋ＝把右邊的「頁」看成「夏」\n2. 國字拆解與造字原因\n煩：會意字，「火」＋「頁」（頭）。頭上像有一把火在燒，就是心裡煩躁、發熱的樣子，本義是頭痛發熱，引申為心煩。★「不厭其煩」是說一點也不嫌麻煩，很有耐心。記法：火加頭的煩讀二聲。"},
  {"id": "p783", "grade": 2, "word": "溫暖", "target": "暖", "zhuyin": "ㄋㄨㄢˇ", "pinyin": "nuǎn", "wz": "ㄨㄣ ㄋㄨㄢˇ", "wrong": [{"z": "ㄋㄨㄢˋ", "p": "nuàn"}, {"z": "ㄌㄨㄢˇ", "p": "luǎn"}], "note": "「溫暖」「暖和」的「暖」讀ㄋㄨㄢˇ（三聲）。", "deep": "1. 注音比較\n暖：ㄋㄨㄢˇ（三聲）＝溫暖、暖和、暖氣、春暖花開。誤讀ㄋㄨㄢˋ＝聲調錯；誤讀ㄌㄨㄢˇ＝ㄋ、ㄌ不分\n2. 國字拆解與造字原因\n暖：形聲字，「日」＋「爰」（聲）。從日部表示熱是太陽帶來的。★另一個寫法「煖」從火部，意思一樣。★ㄋ和ㄌ要分清楚：ㄋ的氣從鼻子出來，ㄌ的氣從舌頭兩邊出來——「暖」是ㄋ不是ㄌ。記法：日字旁的暖讀三聲ㄋㄨㄢˇ。"},
  {"id": "p784", "grade": 2, "word": "涼快", "target": "涼", "zhuyin": "ㄌㄧㄤˊ", "pinyin": "liáng", "wz": "ㄌㄧㄤˊ ㄎㄨㄞˋ", "wrong": [{"z": "ㄌㄧㄤˋ", "p": "liàng"}, {"z": "ㄋㄧㄤˊ", "p": "niáng"}], "note": "「涼快」「涼爽」讀ㄌㄧㄤˊ（二聲）；動詞「把湯涼一涼」讀ㄌㄧㄤˋ（四聲）。", "deep": "1. 注音比較\n涼：ㄌㄧㄤˊ（二聲）＝涼快、涼爽、乘涼、涼水（形容溫度低）；ㄌㄧㄤˋ（四聲）＝把湯涼一涼、涼一下（讓它變涼的動作）。誤讀ㄋㄧㄤˊ＝ㄋ、ㄌ不分\n2. 國字拆解與造字原因\n涼：形聲字，「水（氵）」＋「京」（聲）。從水部，因為水能帶走熱、讓人覺得涼。★形容詞讀二聲、當動詞讀四聲，跟「量」「散」是同一種變化規律。記法：形容涼二聲，讓它變涼四聲。"},
  {"id": "p785", "grade": 2, "word": "潮溼", "target": "溼", "zhuyin": "ㄕ", "pinyin": "shī", "wz": "ㄔㄠˊ ㄕ", "wrong": [{"z": "ㄙ", "p": "sī"}, {"z": "ㄕˊ", "p": "shí"}], "note": "「潮溼」的「溼」讀ㄕ（一聲）。", "deep": "1. 注音比較\n溼：ㄕ（一聲）＝潮溼、溼氣、溼透。誤讀ㄙ＝ㄕ、ㄙ不分；誤讀ㄕˊ＝與「十」「石」相混\n2. 國字拆解與造字原因\n溼：形聲字，從「水（氵）」，表示跟水有關。★「溼」和「濕」是同一個字的兩種寫法，教育部字表以「溼」為正體。★「潮」也從水部，本義是海水定時的漲落——空氣裡水氣多，感覺就像被海潮浸過一樣，所以叫「潮溼」。記法：三點水的溼讀一聲ㄕ。"},
  {"id": "p786", "grade": 2, "word": "乾燥", "target": "燥", "zhuyin": "ㄗㄠˋ", "pinyin": "zào", "wz": "ㄍㄢ ㄗㄠˋ", "wrong": [{"z": "ㄗㄠˇ", "p": "zǎo"}, {"z": "ㄘㄠˋ", "p": "cào"}], "note": "「乾燥」「燥熱」的「燥」讀ㄗㄠˋ（四聲）。", "deep": "1. 注音比較\n燥：ㄗㄠˋ（四聲）＝乾燥、燥熱、口乾舌燥。誤讀ㄗㄠˇ＝與「澡」「早」相混；誤讀ㄘㄠˋ＝ㄗ、ㄘ不分\n2. 國字拆解與造字原因\n燥：形聲字，「火」＋「喿」（聲）。從火部表示是被火烤乾的狀態。★同一組聲符要用部首分：燥（火，乾燥）／澡（水，洗澡）／躁（足，急躁）／噪（口，噪音）——火烤會乾、用水會洗、腳動不停是急、嘴巴吵是噪。記法：火字旁的燥讀四聲。"},
  {"id": "p787", "grade": 2, "word": "閃電", "target": "閃", "zhuyin": "ㄕㄢˇ", "pinyin": "shǎn", "wz": "ㄕㄢˇ ㄉㄧㄢˋ", "wrong": [{"z": "ㄕㄢ", "p": "shān"}, {"z": "ㄕㄢˋ", "p": "shàn"}], "note": "「閃電」「閃躲」的「閃」讀ㄕㄢˇ（三聲）。", "deep": "1. 注音比較\n閃：ㄕㄢˇ（三聲）＝閃電、閃躲、閃亮、一閃而過。誤讀ㄕㄢ＝與「扇風」的扇（一聲）相混；誤讀ㄕㄢˋ＝與「扇子」的扇（四聲）相混\n2. 國字拆解與造字原因\n閃：會意字，「門」裡面一個「人」——人從門後一下子探出頭又縮回去，本義就是「忽然出現一下」。閃電正是這樣忽然亮一下就不見了。★打雷時先看到閃電才聽到雷聲，是因為光比聲音快很多。記法：門裡有人的閃讀三聲。"},
  {"id": "p788", "grade": 2, "word": "霧氣", "target": "霧", "zhuyin": "ㄨˋ", "pinyin": "wù", "wz": "ㄨˋ ㄑㄧˋ", "wrong": [{"z": "ㄨˊ", "p": "wú"}, {"z": "ㄇㄡˋ", "p": "mòu"}], "note": "「霧氣」「濃霧」的「霧」讀ㄨˋ（四聲）。", "deep": "1. 注音比較\n霧：ㄨˋ（四聲）＝霧氣、濃霧、雲霧、騰雲駕霧。誤讀ㄨˊ＝與「無」相混；誤讀ㄇㄡˋ＝把下面的「務」看錯\n2. 國字拆解與造字原因\n霧：形聲字，「雨」＋「務」（聲）。從雨部表示跟水氣有關。★霧和雲其實是同一種東西——都是空氣中的水氣凝成的小水滴，貼著地面的叫霧，飄在高空的叫雲。記法：雨字頭的霧讀四聲。"},
  {"id": "p789", "grade": 2, "word": "池塘", "target": "塘", "zhuyin": "ㄊㄤˊ", "pinyin": "táng", "wz": "ㄔˊ ㄊㄤˊ", "wrong": [{"z": "ㄊㄤ", "p": "tāng"}, {"z": "ㄊㄤˇ", "p": "tǎng"}], "note": "「池塘」「魚塘」的「塘」讀ㄊㄤˊ（二聲）。", "deep": "1. 注音比較\n塘：ㄊㄤˊ（二聲）＝池塘、魚塘、堤塘。誤讀ㄊㄤ＝與「湯」相混；誤讀ㄊㄤˇ＝與「躺」相混\n2. 國字拆解與造字原因\n塘：形聲字，「土」＋「唐」（聲）。從土部，本義是用土堆起來擋水的堤——有堤才圍得出一池水，所以「塘」也用來指水池。★同樣讀ㄊㄤˊ的還有「糖」（米字旁，吃的）、「膛」（肉月旁，胸膛），部首不同意思就不同。記法：土字旁的塘讀二聲。"},
  {"id": "p790", "grade": 2, "word": "蘋果", "target": "蘋", "zhuyin": "ㄆㄧㄥˊ", "pinyin": "píng", "wz": "ㄆㄧㄥˊ ㄍㄨㄛˇ", "wrong": [{"z": "ㄆㄧㄣˊ", "p": "pín"}, {"z": "ㄅㄧㄥˋ", "p": "bìng"}], "note": "「蘋果」的「蘋」讀ㄆㄧㄥˊ（二聲）。", "deep": "1. 注音比較\n蘋：ㄆㄧㄥˊ（二聲）＝蘋果；ㄆㄧㄣˊ（二聲）＝蘋（一種水草，古書用）。誤讀ㄅㄧㄥˋ＝與「並」相混\n2. 國字拆解與造字原因\n蘋：形聲字，「艸（艹）」＋「頻」（聲）。從艸部表示是植物。★蘋果切開放久了會變褐色，是因為果肉裡的物質碰到空氣起了氧化反應；滴一點檸檬汁可以延緩。記法：草字頭的蘋，講水果讀ㄆㄧㄥˊ。"},
  {"id": "p791", "grade": 2, "word": "葫蘆", "target": "蘆", "zhuyin": "ㄌㄨˊ", "pinyin": "lú", "wz": "ㄏㄨˊ ㄌㄨˊ", "wrong": [{"z": "ㄌㄨˇ", "p": "lǔ"}, {"z": "ㄌㄨˋ", "p": "lù"}], "note": "「葫蘆」「蘆葦」的「蘆」讀ㄌㄨˊ（二聲）。", "deep": "1. 注音比較\n蘆：ㄌㄨˊ（二聲）＝葫蘆、蘆葦、蘆筍。誤讀ㄌㄨˇ＝與「魯」相混；誤讀ㄌㄨˋ＝與「路」「露」相混\n2. 國字拆解與造字原因\n蘆：形聲字，「艸（艹）」＋「盧」（聲）。從艸部表示是植物。★「葫蘆」兩個字都是草字頭。俗話「不知道他葫蘆裡賣什麼藥」是因為古代郎中把藥裝在葫蘆裡，外面看不見裡面裝什麼，用來比喻猜不透對方在打什麼主意。記法：草字頭的蘆讀二聲。"},
  {"id": "p792", "grade": 3, "word": "皇冠", "target": "冠", "zhuyin": "ㄍㄨㄢ", "pinyin": "guān", "wz": "ㄏㄨㄤˊ ㄍㄨㄢ", "wrong": [{"z": "ㄍㄨㄢˋ", "p": "guàn"}, {"z": "ㄎㄨㄢ", "p": "kuān"}], "note": "名詞「皇冠」「冠冕」讀ㄍㄨㄢ（一聲）；動詞或「冠軍」讀ㄍㄨㄢˋ（四聲）。", "deep": "1. 注音比較\n冠：ㄍㄨㄢ（一聲）＝皇冠、王冠、冠冕堂皇（帽子，名詞）；ㄍㄨㄢˋ（四聲）＝冠軍、冠上姓氏、冠絕群倫（戴上、居第一，動詞）。誤讀ㄎㄨㄢ＝ㄍ、ㄎ不分\n2. 國字拆解與造字原因\n冠：會意字，上面是「冖」（覆蓋），下面是「元」（人的頭）加「寸」（手），畫的是用手把帽子戴到頭上。帽子本身讀一聲；「戴上」這個動作、以及「排在最前面」讀四聲。記法：東西一聲、動作四聲，跟「扇」的規律一樣。"},
  {"id": "p793", "grade": 3, "word": "爪子", "target": "爪", "zhuyin": "ㄓㄨㄚˇ", "pinyin": "zhuǎ", "wz": "ㄓㄨㄚˇ ˙ㄗ", "wrong": [{"z": "ㄓㄠˇ", "p": "zhǎo"}, {"z": "ㄓㄨㄚ", "p": "zhuā"}], "note": "口語「爪子」「雞爪」讀ㄓㄨㄚˇ；讀書音「鷹爪」「爪牙」讀ㄓㄠˇ。", "deep": "1. 注音比較\n爪：ㄓㄨㄚˇ（三聲）＝爪子、雞爪、貓爪子（口語音）；ㄓㄠˇ（三聲）＝爪牙、鷹爪、張牙舞爪（讀書音）\n2. 國字拆解與造字原因\n爪：象形字，畫一隻手向下抓東西的樣子，本義是動物的腳趾和指甲。「爪」也是部首，從爪部的字多半跟「抓」有關（像「爬」「爭」「受」）。★「爪牙」原指猛獸的利爪與尖牙，後來比喻替壞人做事的手下。記法：口語ㄓㄨㄚˇ、讀書音ㄓㄠˇ。"},
  {"id": "p794", "grade": 3, "word": "大廈", "target": "廈", "zhuyin": "ㄒㄧㄚˋ", "pinyin": "xià", "wz": "ㄉㄚˋ ㄒㄧㄚˋ", "wrong": [{"z": "ㄕㄚˋ", "p": "shà"}, {"z": "ㄒㄧㄚˊ", "p": "xiá"}], "note": "教育部審訂音「大廈」讀ㄉㄚˋ ㄒㄧㄚˋ，跟「廈門」同音；念成ㄕㄚˋ不是審訂音。", "deep": "1. 注音比較\n廈：ㄒㄧㄚˋ（四聲）＝大廈、高樓大廈、廈門。★教育部《國語辭典簡編本》「廈」只收ㄒㄧㄚˋ一音，房子和地名都念ㄒㄧㄚˋ；坊間常把「大廈」念成ㄉㄚˋ ㄕㄚˋ，那是別的地方的讀法，不是我們的審訂音\n2. 國字拆解與造字原因\n廈：形聲字，「广」（房子）＋「夏」（聲）。「广」（ㄧㄢˇ）是靠著山崖蓋的房子，凡是從广部的字多半跟房屋有關（像「店」「府」「庭」「廁」）。「夏」有「大」的意思，所以「廈」本義就是高大的屋子。記法：跟聲符「夏」同音，讀ㄒㄧㄚˋ。"},
  {"id": "p795", "grade": 3, "word": "鑽洞", "target": "鑽", "zhuyin": "ㄗㄨㄢ", "pinyin": "zuān", "wz": "ㄗㄨㄢ ㄉㄨㄥˋ", "wrong": [{"z": "ㄗㄨㄢˋ", "p": "zuàn"}, {"z": "ㄘㄨㄢ", "p": "cuān"}], "note": "動詞「鑽洞」「鑽研」讀ㄗㄨㄢ（一聲）；名詞「鑽石」「電鑽」讀ㄗㄨㄢˋ（四聲）。", "deep": "1. 注音比較\n鑽：ㄗㄨㄢ（一聲）＝鑽洞、鑽研、鑽進去（動作）；ㄗㄨㄢˋ（四聲）＝鑽石、電鑽、鑽頭（東西，名詞）。誤讀ㄘㄨㄢ＝ㄗ、ㄘ不分\n2. 國字拆解與造字原因\n鑽：形聲字，「金」＋「贊」（聲）。從金部表示是金屬工具。鑽孔的動作讀一聲；用來鑽的工具、以及硬到可以鑽別的東西的寶石（鑽石）讀四聲。記法：動作一聲、東西四聲。"},
  {"id": "p796", "grade": 3, "word": "反應", "target": "應", "zhuyin": "ㄧㄥˋ", "pinyin": "yìng", "wz": "ㄈㄢˇ ㄧㄥˋ", "wrong": [{"z": "ㄧㄥ", "p": "yīng"}, {"z": "ㄧㄣˋ", "p": "yìn"}], "note": "「反應」「答應」讀ㄧㄥˋ（四聲）；「應該」「應當」讀ㄧㄥ（一聲）。", "deep": "1. 注音比較\n應：ㄧㄥˋ（四聲）＝反應、答應、應對、應付（回答、對付）；ㄧㄥ（一聲）＝應該、應當、理應如此（表示「該」）。誤讀ㄧㄣˋ＝ㄥ、ㄣ不分\n2. 國字拆解與造字原因\n應：形聲字，下面是「心」，本義是心裡答允。★分辨方法很簡單：句子裡換成「該」讀得通的，讀一聲（應該去＝該去）；換成「回答、回應」讀得通的，讀四聲（反應、答應）。記法：該＝一聲、答＝四聲。"},
  {"id": "p797", "grade": 3, "word": "討論", "target": "論", "zhuyin": "ㄌㄨㄣˋ", "pinyin": "lùn", "wz": "ㄊㄠˇ ㄌㄨㄣˋ", "wrong": [{"z": "ㄌㄨㄣˊ", "p": "lún"}, {"z": "ㄌㄨㄣˇ", "p": "lǔn"}], "note": "「討論」「議論」讀ㄌㄨㄣˋ（四聲）；書名《論語》讀ㄌㄨㄣˊ（二聲）。", "deep": "1. 注音比較\n論：ㄌㄨㄣˋ（四聲）＝討論、議論、理論、論文；ㄌㄨㄣˊ（二聲）＝《論語》（孔子和學生的對話集）\n2. 國字拆解與造字原因\n論：形聲字，「言」＋「侖」（聲）。「侖」有「按次序整理」的意思，所以「論」就是把話一條一條講清楚。★《論語》讀ㄌㄨㄣˊ，是因為那本書是把孔子的話「編排整理」起來的，取的是「侖」（條理）的意思。記法：只有《論語》讀二聲。"},
  {"id": "p798", "grade": 3, "word": "熟悉", "target": "熟", "zhuyin": "ㄕㄡˊ", "pinyin": "shóu", "wz": "ㄕㄡˊ ㄒㄧ", "wrong": [{"z": "ㄕㄨˊ", "p": "shú"}, {"z": "ㄕㄡˇ", "p": "shǒu"}], "note": "教育部審訂音「熟」只讀ㄕㄡˊ，「熟悉」「成熟」都念ㄕㄡˊ，不是ㄕㄨˊ。", "deep": "1. 注音比較\n熟：ㄕㄡˊ（二聲）＝熟悉、成熟、熟練、煮熟。★很多人念成ㄕㄨˊ，但教育部《國語辭典簡編本》只收ㄕㄡˊ一音，ㄕㄨˊ不是審訂音。誤讀ㄕㄡˇ＝與「手」「守」相混\n2. 國字拆解與造字原因\n熟：形聲字，下面是「灬」（火的變形，四點火），表示用火把東西煮到可以吃。煮到夠久＝熟；做一件事做到夠多次，也叫「熟」——熟練、熟悉。★從「灬」的字多半跟火有關（像「煮」「照」「熱」）。記法：熟讀ㄕㄡˊ。"},
  {"id": "p799", "grade": 3, "word": "模型", "target": "模", "zhuyin": "ㄇㄛˊ", "pinyin": "mó", "wz": "ㄇㄛˊ ㄒㄧㄥˊ", "wrong": [{"z": "ㄇㄨˊ", "p": "mú"}, {"z": "ㄇㄛˋ", "p": "mò"}], "note": "「模型」「模仿」讀ㄇㄛˊ（二聲）；「模樣」「模子」讀ㄇㄨˊ。", "deep": "1. 注音比較\n模：ㄇㄛˊ（二聲）＝模型、模仿、模範、規模；ㄇㄨˊ（二聲）＝模樣、模子、一個模子印出來的\n2. 國字拆解與造字原因\n模：形聲字，「木」＋「莫」（聲）。古人用木頭做出樣板，照著複製，所以本義是「樣板、標準」——「模範」就是可以照著學的榜樣。★講樣板、照著做讀ㄇㄛˊ；講「長相、外形」的口語詞讀ㄇㄨˊ。記法：模樣、模子讀ㄇㄨˊ，其他讀ㄇㄛˊ。"},
  {"id": "p800", "grade": 3, "word": "更加", "target": "更", "zhuyin": "ㄍㄥˋ", "pinyin": "gèng", "wz": "ㄍㄥˋ ㄐㄧㄚ", "wrong": [{"z": "ㄍㄥ", "p": "gēng"}, {"z": "ㄐㄧㄥˋ", "p": "jìng"}], "note": "「更加」「更好」讀ㄍㄥˋ（四聲）；「三更半夜」「更改」讀ㄍㄥ（一聲）。", "deep": "1. 注音比較\n更：ㄍㄥˋ（四聲）＝更加、更好、更上一層樓（表示「越、再」）；ㄍㄥ（一聲）＝三更半夜、更改、更衣（表示「改變」或古代夜裡的時段）\n2. 國字拆解與造字原因\n更：會意字，右邊是「攴」（手拿棍子），本義是「改變、替換」——古代夜裡由更夫敲梆子報時，一夜分成五更，也是輪流「替換」，所以讀一聲。改變之後比原來多一層，引申成「越發、更加」，讀四聲。記法：改變、報時一聲，「越發」四聲。"},
  {"id": "p801", "grade": 3, "word": "間隔", "target": "間", "zhuyin": "ㄐㄧㄢˋ", "pinyin": "jiàn", "wz": "ㄐㄧㄢˋ ㄍㄜˊ", "wrong": [{"z": "ㄐㄧㄢ", "p": "jiān"}, {"z": "ㄒㄧㄢˊ", "p": "xián"}], "note": "「間隔」「離間」「間諜」讀ㄐㄧㄢˋ（四聲）；「房間」「中間」讀ㄐㄧㄢ（一聲）。", "deep": "1. 注音比較\n間：ㄐㄧㄢ（一聲）＝房間、中間、時間、人間（空間、當中）；ㄐㄧㄢˋ（四聲）＝間隔、離間、間諜、間接（隔開、插在中間搞破壞）。誤讀ㄒㄧㄢˊ＝與「閒」相混\n2. 國字拆解與造字原因\n間：會意字，「門」中間一個「日」，本義是門縫裡透進來的光，也就是「縫隙」。當「當中的位置」講讀一聲；當「隔開」或「趁縫隙鑽進去」講讀四聲——「間諜」就是鑽進對方陣營的人。記法：位置一聲、隔開四聲。"},
  {"id": "p802", "grade": 3, "word": "參加", "target": "參", "zhuyin": "ㄘㄢ", "pinyin": "cān", "wz": "ㄘㄢ ㄐㄧㄚ", "wrong": [{"z": "ㄕㄣ", "p": "shēn"}, {"z": "ㄘㄣ", "p": "cēn"}], "note": "「參加」「參觀」讀ㄘㄢ；「人參」讀ㄕㄣ；「參差不齊」讀ㄘㄣ。", "deep": "1. 注音比較\n參：ㄘㄢ（一聲）＝參加、參觀、參考、參與；ㄕㄣ（一聲）＝人參、海參（藥材、食材）；ㄘㄣ（一聲）＝參差不齊（長短不一）；ㄙㄢ＝古代同「三」\n2. 國字拆解與造字原因\n參：本是星宿的名字（參宿），字形上面三點像三顆星。★一個字四個音，只能靠詞來分：加入讀ㄘㄢ、藥材讀ㄕㄣ、參差讀ㄘㄣ。記法：參加ㄘㄢ、人參ㄕㄣ、參差ㄘㄣ。"},
  {"id": "p803", "grade": 3, "word": "切菜", "target": "切", "zhuyin": "ㄑㄧㄝ", "pinyin": "qiē", "wz": "ㄑㄧㄝ ㄘㄞˋ", "wrong": [{"z": "ㄑㄧㄝˋ", "p": "qiè"}, {"z": "ㄑㄧㄝˇ", "p": "qiě"}], "note": "動詞「切菜」「切開」讀ㄑㄧㄝ（一聲）；「親切」「一切」讀ㄑㄧㄝˋ（四聲）。", "deep": "1. 注音比較\n切：ㄑㄧㄝ（一聲）＝切菜、切開、切斷（用刀分開的動作）；ㄑㄧㄝˋ（四聲）＝親切、一切、迫切、關切（貼近、全部）\n2. 國字拆解與造字原因\n切：形聲字，「刀」＋「七」（聲）。本義是用刀分開（一聲）。刀貼著東西才切得下去，引申出「貼近」的意思——「親切」就是貼近人心，「迫切」就是逼得很近，這一類讀四聲。記法：用刀的動作一聲，「貼近、全部」四聲。"},
  {"id": "p804", "grade": 3, "word": "節省", "target": "省", "zhuyin": "ㄕㄥˇ", "pinyin": "shěng", "wz": "ㄐㄧㄝˊ ㄕㄥˇ", "wrong": [{"z": "ㄒㄧㄥˇ", "p": "xǐng"}, {"z": "ㄕㄥ", "p": "shēng"}], "note": "「節省」「省錢」讀ㄕㄥˇ；「反省」「省親」讀ㄒㄧㄥˇ。", "deep": "1. 注音比較\n省：ㄕㄥˇ（三聲）＝節省、省錢、省略、臺灣省（減少、行政區）；ㄒㄧㄥˇ（三聲）＝反省、內省、省親、不省人事（檢查、看望、明白）\n2. 國字拆解與造字原因\n省：會意字，下面是「目」（眼睛），本義是仔細看、察看——「反省」就是回過頭來看自己，讀ㄒㄧㄥˇ。看清楚了就知道哪些是多餘的可以去掉，引申成「減少」，讀ㄕㄥˇ。記法：跟「看、想」有關讀ㄒㄧㄥˇ，跟「減少」有關讀ㄕㄥˇ。"},
  {"id": "p805", "grade": 3, "word": "尷尬", "target": "尷", "zhuyin": "ㄍㄢ", "pinyin": "gān", "wz": "ㄍㄢ ㄍㄚˋ", "wrong": [{"z": "ㄐㄧㄢ", "p": "jiān"}, {"z": "ㄍㄢˋ", "p": "gàn"}], "note": "「尷尬」讀ㄍㄢ ㄍㄚˋ，不要念成ㄐㄧㄢ ㄐㄧㄝˋ。", "deep": "1. 注音比較\n尷：ㄍㄢ（一聲）＝尷尬。誤讀ㄐㄧㄢ＝把右邊的「監」直接讀出來（這是最常見的錯）；誤讀ㄍㄢˋ＝與「幹」相混\n2. 國字拆解與造字原因\n尷：形聲字，「尢」（ㄨㄤ，腿彎曲不好走的樣子）＋「監」（聲）。「尷尬」本義是走路不方便、身體不自在，引申成處境為難、不好意思。★「尷尬」兩個字都是「尢」部，是連綿詞。記法：尷尬讀ㄍㄢ ㄍㄚˋ。"},
  {"id": "p806", "grade": 3, "word": "猶豫", "target": "豫", "zhuyin": "ㄩˋ", "pinyin": "yù", "wz": "ㄧㄡˊ ㄩˋ", "wrong": [{"z": "ㄩˊ", "p": "yú"}, {"z": "ㄒㄩˋ", "p": "xù"}], "note": "「猶豫」的「豫」讀ㄩˋ（四聲）。", "deep": "1. 注音比較\n豫：ㄩˋ（四聲）＝猶豫、豫劇、河南簡稱豫。誤讀ㄩˊ＝與「魚」「餘」相混；誤讀ㄒㄩˋ＝與「序」相混\n2. 國字拆解與造字原因\n豫：右邊是「象」。古書說「猶」和「豫」本來是兩種很多疑的動物，走幾步就停下來張望，所以合起來形容拿不定主意。★「猶豫」兩個字現在都不單獨用這個意思，是典型的連綿詞。記法：猶豫讀ㄧㄡˊ ㄩˋ。"},
  {"id": "p807", "grade": 3, "word": "慚愧", "target": "慚", "zhuyin": "ㄘㄢˊ", "pinyin": "cán", "wz": "ㄘㄢˊ ㄎㄨㄟˋ", "wrong": [{"z": "ㄓㄢˇ", "p": "zhǎn"}, {"z": "ㄘㄢ", "p": "cān"}], "note": "「慚愧」的「慚」讀ㄘㄢˊ（二聲）。", "deep": "1. 注音比較\n慚：ㄘㄢˊ（二聲）＝慚愧、羞慚、大言不慚。誤讀ㄓㄢˇ＝把左邊的「斬」直接讀出來；誤讀ㄘㄢ＝與「餐」「參加」的參相混\n2. 國字拆解與造字原因\n慚：形聲字，「心（忄）」＋「斬」（聲）。從心部表示是一種心裡的感受——覺得自己做得不好，心裡像被割了一刀。★「大言不慚」是說話說得很大，卻一點也不覺得不好意思。記法：豎心旁的慚讀二聲。"},
  {"id": "p808", "grade": 3, "word": "羨慕", "target": "羨", "zhuyin": "ㄒㄧㄢˋ", "pinyin": "xiàn", "wz": "ㄒㄧㄢˋ ㄇㄨˋ", "wrong": [{"z": "ㄒㄧㄢ", "p": "xiān"}, {"z": "ㄧㄤˊ", "p": "yáng"}], "note": "「羨慕」的「羨」讀ㄒㄧㄢˋ（四聲）。", "deep": "1. 注音比較\n羨：ㄒㄧㄢˋ（四聲）＝羨慕、欣羨、臨淵羨魚。誤讀ㄒㄧㄢ＝與「先」「鮮」相混；誤讀ㄧㄤˊ＝把上面的「羊」直接讀出來\n2. 國字拆解與造字原因\n羨：上面是「羊」（好東西），下面是「次」（口水），畫的是看到好吃的羊肉流口水的樣子，本義就是「因為喜歡而想要」。★成語「臨淵羨魚」是說站在水邊光羨慕魚，不如回家織網——比喻空想不如實做。記法：上面是羊的羨讀四聲。"},
  {"id": "p809", "grade": 3, "word": "憤怒", "target": "憤", "zhuyin": "ㄈㄣˋ", "pinyin": "fèn", "wz": "ㄈㄣˋ ㄋㄨˋ", "wrong": [{"z": "ㄈㄣˊ", "p": "fén"}, {"z": "ㄆㄣˋ", "p": "pèn"}], "note": "「憤怒」「氣憤」的「憤」讀ㄈㄣˋ（四聲）。", "deep": "1. 注音比較\n憤：ㄈㄣˋ（四聲）＝憤怒、氣憤、發憤圖強、義憤填膺。誤讀ㄈㄣˊ＝與「墳」相混；誤讀ㄆㄣˋ＝與「噴」相混\n2. 國字拆解與造字原因\n憤：形聲字，「心（忄）」＋「賁」（聲）。從心部表示是心裡的情緒——心裡像有東西鼓脹起來要爆開。★「發憤」（心裡不甘而奮起）和「發奮」（振作精神）意思相近但字不同：發憤是因為受了刺激，發奮是主動振作。記法：豎心旁的憤讀四聲。"},
  {"id": "p810", "grade": 3, "word": "恐懼", "target": "懼", "zhuyin": "ㄐㄩˋ", "pinyin": "jù", "wz": "ㄎㄨㄥˇ ㄐㄩˋ", "wrong": [{"z": "ㄑㄩˊ", "p": "qú"}, {"z": "ㄐㄩˇ", "p": "jǔ"}], "note": "「恐懼」「畏懼」的「懼」讀ㄐㄩˋ（四聲）。", "deep": "1. 注音比較\n懼：ㄐㄩˋ（四聲）＝恐懼、畏懼、懼怕、臨事而懼。誤讀ㄑㄩˊ＝把右邊的「瞿」讀錯；誤讀ㄐㄩˇ＝與「舉」相混\n2. 國字拆解與造字原因\n懼：形聲字，「心（忄）」＋「瞿」（聲）。「瞿」上面是兩個「目」，本來就是驚慌張望的樣子，加上「心」更強調心裡害怕。★孔子說做事要「臨事而懼」——遇到事情要存著戒慎的心，不是叫人膽小，是要謹慎。記法：豎心旁的懼讀四聲。"},
  {"id": "p811", "grade": 3, "word": "疲倦", "target": "倦", "zhuyin": "ㄐㄩㄢˋ", "pinyin": "juàn", "wz": "ㄆㄧˊ ㄐㄩㄢˋ", "wrong": [{"z": "ㄐㄩㄢˇ", "p": "juǎn"}, {"z": "ㄑㄩㄢˊ", "p": "quán"}], "note": "「疲倦」「厭倦」的「倦」讀ㄐㄩㄢˋ（四聲）。", "deep": "1. 注音比較\n倦：ㄐㄩㄢˋ（四聲）＝疲倦、厭倦、倦怠、誨人不倦。誤讀ㄐㄩㄢˇ＝與「捲」相混；誤讀ㄑㄩㄢˊ＝與「拳」「全」相混\n2. 國字拆解與造字原因\n倦：形聲字，「人（亻）」＋「卷」（聲）。人累了身體會蜷曲起來，所以用「卷」既表音又帶意思。★「誨人不倦」是說教導別人不覺得厭煩，出自《論語》，是孔子形容自己的話。記法：人字旁的倦讀四聲。"},
  {"id": "p812", "grade": 3, "word": "允許", "target": "允", "zhuyin": "ㄩㄣˇ", "pinyin": "yǔn", "wz": "ㄩㄣˇ ㄒㄩˇ", "wrong": [{"z": "ㄩㄥˇ", "p": "yǒng"}, {"z": "ㄊㄞˋ", "p": "tài"}], "note": "「允許」「應允」的「允」讀ㄩㄣˇ（三聲）。", "deep": "1. 注音比較\n允：ㄩㄣˇ（三聲）＝允許、應允、公允、允文允武。誤讀ㄩㄥˇ＝與「永」「勇」相混（ㄣ、ㄥ不分）；誤讀ㄊㄞˋ＝與長得像的「兌」相混\n2. 國字拆解與造字原因\n允：會意字，上面是「厶」，下面是「儿」（人），本義是誠信、答應。★「公允」是公平適當；「允文允武」是說又能文又能武。★注意「允」和「充」（ㄔㄨㄥ，充滿）上半不同，別看錯。記法：允讀ㄩㄣˇ，是ㄣ不是ㄥ。"},
  {"id": "p813", "grade": 3, "word": "拜訪", "target": "訪", "zhuyin": "ㄈㄤˇ", "pinyin": "fǎng", "wz": "ㄅㄞˋ ㄈㄤˇ", "wrong": [{"z": "ㄈㄤ", "p": "fāng"}, {"z": "ㄈㄤˋ", "p": "fàng"}], "note": "「拜訪」「訪問」的「訪」讀ㄈㄤˇ（三聲）。", "deep": "1. 注音比較\n訪：ㄈㄤˇ（三聲）＝拜訪、訪問、探訪、採訪。誤讀ㄈㄤ＝與「方」相混；誤讀ㄈㄤˋ＝與「放」相混\n2. 國字拆解與造字原因\n訪：形聲字，「言」＋「方」（聲）。從言部表示要開口問——本義是向人打聽、徵求意見。★所以「採訪」不只是去看看，是要問出東西來。記法：言字旁的訪讀三聲。"},
  {"id": "p814", "grade": 3, "word": "邀請", "target": "邀", "zhuyin": "ㄧㄠ", "pinyin": "yāo", "wz": "ㄧㄠ ㄑㄧㄥˇ", "wrong": [{"z": "ㄧㄠˊ", "p": "yáo"}, {"z": "ㄐㄧㄠˇ", "p": "jiǎo"}], "note": "「邀請」的「邀」讀ㄧㄠ（一聲）。", "deep": "1. 注音比較\n邀：ㄧㄠ（一聲）＝邀請、邀約、邀功。誤讀ㄧㄠˊ＝與「搖」「謠」相混；誤讀ㄐㄧㄠˇ＝與「繳」相混\n2. 國字拆解與造字原因\n邀：形聲字，「辵（辶）」＋「敫」（聲）。「辶」跟走路有關——本義是在半路上攔住對方、把人請來。★「邀功」是把別人的功勞攔下來算成自己的，是貶義詞，不要用錯。記法：走之旁的邀讀一聲。"},
  {"id": "p815", "grade": 3, "word": "拒絕", "target": "拒", "zhuyin": "ㄐㄩˋ", "pinyin": "jù", "wz": "ㄐㄩˋ ㄐㄩㄝˊ", "wrong": [{"z": "ㄐㄩˇ", "p": "jǔ"}, {"z": "ㄑㄩˊ", "p": "qú"}], "note": "「拒絕」「抗拒」的「拒」讀ㄐㄩˋ（四聲）。", "deep": "1. 注音比較\n拒：ㄐㄩˋ（四聲）＝拒絕、抗拒、拒之門外。誤讀ㄐㄩˇ＝與「舉」相混；誤讀ㄑㄩˊ＝與「渠」相混\n2. 國字拆解與造字原因\n拒：形聲字，「手（扌）」＋「巨」（聲）。從手部表示是用手擋開的動作。★「拒」和「距」（足字旁，距離）聲符一樣、部首不同：用手擋是拒，用腳量遠近是距。記法：提手旁的拒讀四聲。"},
  {"id": "p816", "grade": 3, "word": "解釋", "target": "釋", "zhuyin": "ㄕˋ", "pinyin": "shì", "wz": "ㄐㄧㄝˇ ㄕˋ", "wrong": [{"z": "ㄗㄜˊ", "p": "zé"}, {"z": "ㄕˊ", "p": "shí"}], "note": "「解釋」「釋放」的「釋」讀ㄕˋ（四聲）。", "deep": "1. 注音比較\n釋：ㄕˋ（四聲）＝解釋、釋放、釋懷、如釋重負。誤讀ㄗㄜˊ＝與「擇」「澤」相混；誤讀ㄕˊ＝與「石」「食」相混\n2. 國字拆解與造字原因\n釋：形聲字，左邊是「釆」（ㄅㄧㄢˋ，分辨），右邊是「睪」（聲）。本義是把纏在一起的東西分開、放開——把話講開了叫「解釋」，把人放了叫「釋放」。★「如釋重負」是說像放下重擔一樣輕鬆。記法：釋讀ㄕˋ。"},
  {"id": "p817", "grade": 3, "word": "複雜", "target": "複", "zhuyin": "ㄈㄨˋ", "pinyin": "fù", "wz": "ㄈㄨˋ ㄗㄚˊ", "wrong": [{"z": "ㄈㄨˊ", "p": "fú"}, {"z": "ㄈㄨˇ", "p": "fǔ"}], "note": "「複雜」「複習」的「複」讀ㄈㄨˋ（四聲）。", "deep": "1. 注音比較\n複：ㄈㄨˋ（四聲）＝複雜、複習、重複、複製。誤讀ㄈㄨˊ＝與「服」「福」相混；誤讀ㄈㄨˇ＝與「府」「腐」相混\n2. 國字拆解與造字原因\n複：形聲字，「衣（衤）」＋「复」（聲）。本義是夾層的衣服——有兩層，所以引申成「重疊、不只一個」。★三個容易混的字：複（衣字旁，重疊、複雜）／復（雙人旁，回來、恢復）／覆（西字頭，蓋住、翻過來）。記法：衣字旁的複讀四聲。"},
  {"id": "p818", "grade": 3, "word": "危險", "target": "危", "zhuyin": "ㄨㄟˊ", "pinyin": "wéi", "wz": "ㄨㄟˊ ㄒㄧㄢˇ", "wrong": [{"z": "ㄨㄟˋ", "p": "wèi"}, {"z": "ㄍㄨㄟˇ", "p": "guǐ"}], "note": "「危險」「危機」的「危」讀ㄨㄟˊ（二聲）。", "deep": "1. 注音比較\n危：ㄨㄟˊ（二聲）＝危險、危機、危害、正襟危坐。誤讀ㄨㄟˋ＝與「為」「衛」相混；誤讀ㄍㄨㄟˇ＝與「詭」相混\n2. 國字拆解與造字原因\n危：會意字，上面是人站在山崖邊，下面是「卩」（跪坐的人），畫的是高處讓人腿軟的樣子，本義是「高」，引申成「不安全」。★「正襟危坐」的「危」用的是本義「高、正直」——整整衣襟端端正正地坐好，不是危險地坐著。記法：危讀二聲ㄨㄟˊ。"},
  {"id": "p819", "grade": 3, "word": "保護", "target": "護", "zhuyin": "ㄏㄨˋ", "pinyin": "hù", "wz": "ㄅㄠˇ ㄏㄨˋ", "wrong": [{"z": "ㄏㄨˊ", "p": "hú"}, {"z": "ㄏㄨㄛˋ", "p": "huò"}], "note": "「保護」「護士」的「護」讀ㄏㄨˋ（四聲）。", "deep": "1. 注音比較\n護：ㄏㄨˋ（四聲）＝保護、護士、愛護、護送。誤讀ㄏㄨˊ＝與「湖」「胡」相混；誤讀ㄏㄨㄛˋ＝與「獲」相混\n2. 國字拆解與造字原因\n護：形聲字，「言」＋「蒦」（聲）。從言部——古代的「護」本義是替人說話、為人辯護，後來才擴大成一切保衛的意思。★「護」和「獲」（犬字旁，獲得）聲符相同，部首不同。記法：言字旁的護讀四聲。"},
  {"id": "p820", "grade": 3, "word": "環境", "target": "境", "zhuyin": "ㄐㄧㄥˋ", "pinyin": "jìng", "wz": "ㄏㄨㄢˊ ㄐㄧㄥˋ", "wrong": [{"z": "ㄐㄧㄥˇ", "p": "jǐng"}, {"z": "ㄐㄧㄤˋ", "p": "jiàng"}], "note": "「環境」「邊境」的「境」讀ㄐㄧㄥˋ（四聲）。", "deep": "1. 注音比較\n境：ㄐㄧㄥˋ（四聲）＝環境、邊境、境界、入境隨俗。誤讀ㄐㄧㄥˇ＝與「景」「警」相混；誤讀ㄐㄧㄤˋ＝與「醬」相混\n2. 國字拆解與造字原因\n境：形聲字，「土」＋「竟」（聲）。「竟」有「終了、盡頭」的意思，土地到了盡頭就是邊界——所以「境」本義是疆界，引申成「所處的地方、狀況」（環境、處境）。記法：土字旁的境讀四聲。"},
  {"id": "p821", "grade": 3, "word": "汙染", "target": "染", "zhuyin": "ㄖㄢˇ", "pinyin": "rǎn", "wz": "ㄨ ㄖㄢˇ", "wrong": [{"z": "ㄖㄢˋ", "p": "ràn"}, {"z": "ㄌㄢˇ", "p": "lǎn"}], "note": "「汙染」「染色」的「染」讀ㄖㄢˇ（三聲）。", "deep": "1. 注音比較\n染：ㄖㄢˇ（三聲）＝汙染、染色、傳染、耳濡目染。誤讀ㄖㄢˋ＝聲調錯；誤讀ㄌㄢˇ＝ㄖ、ㄌ不分\n2. 國字拆解與造字原因\n染：會意字，「水（氵）」＋「九」＋「木」。古人用草木煮出的汁泡布上色，而且要反覆泡很多次（「九」在古文裡表示次數多），所以字裡有水、有木、有九。★「耳濡目染」是說耳朵常聽、眼睛常看，不知不覺就受了影響。記法：染讀三聲ㄖㄢˇ。"},
  {"id": "p822", "grade": 3, "word": "咖啡", "target": "咖", "zhuyin": "ㄎㄚ", "pinyin": "kā", "wz": "ㄎㄚ ㄈㄟ", "wrong": [{"z": "ㄐㄧㄚ", "p": "jiā"}, {"z": "ㄎㄚˇ", "p": "kǎ"}], "note": "「咖啡」的「咖」讀ㄎㄚ（一聲）。", "deep": "1. 注音比較\n咖：ㄎㄚ（一聲）＝咖啡；ㄍㄚ（一聲）＝咖哩。誤讀ㄐㄧㄚ＝把右邊的「加」直接讀出來；誤讀ㄎㄚˇ＝與「卡」相混\n2. 國字拆解與造字原因\n咖：形聲字，「口」＋「加」（聲）。「咖啡」是英文 coffee 翻過來的音，翻譯外國詞時常挑口字旁的字，因為那表示「這只是聲音，不用管字義」——像「咖啡」「咖哩」「啤酒」「嗎啡」都是。記法：口字旁的咖，咖啡讀ㄎㄚ。"},
  {"id": "p823", "grade": 3, "word": "蛋糕", "target": "糕", "zhuyin": "ㄍㄠ", "pinyin": "gāo", "wz": "ㄉㄢˋ ㄍㄠ", "wrong": [{"z": "ㄍㄠˇ", "p": "gǎo"}, {"z": "ㄧㄤˊ", "p": "yáng"}], "note": "「蛋糕」「糕餅」的「糕」讀ㄍㄠ（一聲）。", "deep": "1. 注音比較\n糕：ㄍㄠ（一聲）＝蛋糕、糕餅、年糕、蘿蔔糕。誤讀ㄍㄠˇ＝與「稿」「搞」相混；誤讀ㄧㄤˊ＝把右上的「羊」直接讀出來\n2. 國字拆解與造字原因\n糕：形聲字，「米」＋「羔」（聲）。從米部表示是米（或麵粉）做的食品。★過年吃年糕，是取「糕」和「高」同音，希望一年比一年高。記法：米字旁的糕讀一聲。"},
  {"id": "p824", "grade": 3, "word": "豆漿", "target": "漿", "zhuyin": "ㄐㄧㄤ", "pinyin": "jiāng", "wz": "ㄉㄡˋ ㄐㄧㄤ", "wrong": [{"z": "ㄐㄧㄤˋ", "p": "jiàng"}, {"z": "ㄐㄧㄤˇ", "p": "jiǎng"}], "note": "「豆漿」「泥漿」讀ㄐㄧㄤ（一聲）；「漿糊」「漿洗」讀ㄐㄧㄤˋ。", "deep": "1. 注音比較\n漿：ㄐㄧㄤ（一聲）＝豆漿、泥漿、瓊漿玉液（濃稠的液體）；ㄐㄧㄤˋ（四聲）＝漿糊、漿衣服（用米湯讓布挺起來）。誤讀ㄐㄧㄤˇ＝與「講」「獎」相混\n2. 國字拆解與造字原因\n漿：形聲字，下面是「水」，表示是液體。★「漿」（下面是水，豆漿）和「醬」（下面是酉，醬油）長得很像：酉是酒罈子，跟發酵的東西有關。記法：下面是水的漿讀一聲。"},
  {"id": "p825", "grade": 3, "word": "冰淇淋", "target": "淇", "zhuyin": "ㄑㄧˊ", "pinyin": "qí", "wz": "ㄅㄧㄥ ㄑㄧˊ ㄌㄧㄣˊ", "wrong": [{"z": "ㄑㄧˋ", "p": "qì"}, {"z": "ㄐㄧ", "p": "jī"}], "note": "「冰淇淋」的「淇」讀ㄑㄧˊ（二聲）。", "deep": "1. 注音比較\n淇：ㄑㄧˊ（二聲）＝冰淇淋、淇水。誤讀ㄑㄧˋ＝與「氣」「汽」相混；誤讀ㄐㄧ＝與「基」「機」相混\n2. 國字拆解與造字原因\n淇：形聲字，「水（氵）」＋「其」（聲）。本來是一條河的名字（淇水，在河南）。「冰淇淋」是英文 ice cream 翻過來的音，只借字的聲音。★同樣以「其」為聲符的：淇（水，河名）／棋（木，下棋）／期（月，日期）／旗（方，旗子）。記法：三點水的淇讀二聲。"},
  {"id": "p826", "grade": 3, "word": "分泌", "target": "泌", "zhuyin": "ㄇㄧˋ", "pinyin": "mì", "wz": "ㄈㄣ ㄇㄧˋ", "wrong": [{"z": "ㄅㄧˋ", "p": "bì"}, {"z": "ㄆㄧˋ", "p": "pì"}], "note": "「分泌」的「泌」讀ㄇㄧˋ；地名「泌陽」讀ㄅㄧˋ。", "deep": "1. 注音比較\n泌：ㄇㄧˋ（四聲）＝分泌、泌尿；ㄅㄧˋ（四聲）＝泌陽（河南地名）。誤讀ㄆㄧˋ＝ㄅ、ㄆ不分\n2. 國字拆解與造字原因\n泌：形聲字，「水（氵）」＋「必」（聲）。從水部，本義是水一點一點滲出來——身體裡的腺體慢慢滲出汗、唾液，就叫「分泌」。★「泌」和「秘」（禾字旁，秘密）都讀ㄇㄧˋ，一個講滲出、一個講不讓人知道。記法：三點水的泌，講分泌讀ㄇㄧˋ。"},
  {"id": "p827", "grade": 3, "word": "遲到", "target": "遲", "zhuyin": "ㄔˊ", "pinyin": "chí", "wz": "ㄔˊ ㄉㄠˋ", "wrong": [{"z": "ㄕˊ", "p": "shí"}, {"z": "ㄔˇ", "p": "chǐ"}], "note": "「遲到」「遲早」的「遲」讀ㄔˊ（二聲）。", "deep": "1. 注音比較\n遲：ㄔˊ（二聲）＝遲到、遲早、延遲、事不宜遲。誤讀ㄕˊ＝ㄔ、ㄕ不分；誤讀ㄔˇ＝與「尺」「恥」相混\n2. 國字拆解與造字原因\n遲：形聲字，「辵（辶）」＋「犀」（聲）。從辶部跟走路有關，本義是走得慢。★「事不宜遲」是說事情不應該拖延，要趕快做。★注意裡面是「犀」（犀牛），不是「尾」。記法：走之旁的遲讀二聲。"},
  {"id": "p828", "grade": 3, "word": "鼓勵", "target": "勵", "zhuyin": "ㄌㄧˋ", "pinyin": "lì", "wz": "ㄍㄨˇ ㄌㄧˋ", "wrong": [{"z": "ㄌㄧˊ", "p": "lí"}, {"z": "ㄨㄢˋ", "p": "wàn"}], "note": "「鼓勵」「獎勵」的「勵」讀ㄌㄧˋ（四聲）。", "deep": "1. 注音比較\n勵：ㄌㄧˋ（四聲）＝鼓勵、獎勵、勉勵、勵志。誤讀ㄌㄧˊ＝與「離」「梨」相混；誤讀ㄨㄢˋ＝把右邊的「萬」直接讀出來\n2. 國字拆解與造字原因\n勵：形聲字，「力」＋「厲」（聲）。從力部表示要出力——用話語或行動給人力量，就是「鼓勵」。★「勵」（力字旁，鼓勵）和「厲」（嚴厲）、「勵」和「歷」（經歷）要分清楚。★「鼓」本來是打鼓，古代打仗擊鼓能讓士兵有精神，所以「鼓勵」就是敲鼓給人力量。記法：力字旁的勵讀四聲。"},
  {"id": "p829", "grade": 3, "word": "讚美", "target": "讚", "zhuyin": "ㄗㄢˋ", "pinyin": "zàn", "wz": "ㄗㄢˋ ㄇㄟˇ", "wrong": [{"z": "ㄗㄢ", "p": "zān"}, {"z": "ㄘㄢˋ", "p": "càn"}], "note": "「讚美」「稱讚」的「讚」讀ㄗㄢˋ（四聲）。", "deep": "1. 注音比較\n讚：ㄗㄢˋ（四聲）＝讚美、稱讚、讚嘆、讚不絕口。誤讀ㄗㄢ＝少了聲調；誤讀ㄘㄢˋ＝ㄗ、ㄘ不分\n2. 國字拆解與造字原因\n讚：形聲字，「言」＋「贊」（聲）。從言部表示是用話說出來的稱美。★「讚」（言字旁，稱讚）和「贊」（貝字旁，贊助、贊成）不同：一個用嘴、一個出錢出力。記法：言字旁的讚讀四聲。"},
  {"id": "p830", "grade": 3, "word": "興奮", "target": "奮", "zhuyin": "ㄈㄣˋ", "pinyin": "fèn", "wz": "ㄒㄧㄥ ㄈㄣˋ", "wrong": [{"z": "ㄈㄣˊ", "p": "fén"}, {"z": "ㄈㄣ", "p": "fēn"}], "note": "「興奮」「奮鬥」的「奮」讀ㄈㄣˋ（四聲）；這裡的「興」讀ㄒㄧㄥ（一聲）。", "deep": "1. 注音比較\n奮：ㄈㄣˋ（四聲）＝興奮、奮鬥、振奮、奮不顧身。誤讀ㄈㄣˊ＝與「墳」相混；誤讀ㄈㄣ＝與「分」相混\n2. 國字拆解與造字原因\n奮：會意字，上面是「大」（人張開手），中間是「隹」（鳥），下面是「田」，畫的是鳥在田野上用力振翅飛起，本義是「用力張開翅膀」，引申為振作、鼓起勁。★「興奮」的「興」讀一聲（興盛、興起），不是「興趣」的四聲。記法：奮讀四聲ㄈㄣˋ。"},
  {"id": "p831", "grade": 3, "word": "焦慮", "target": "慮", "zhuyin": "ㄌㄩˋ", "pinyin": "lǜ", "wz": "ㄐㄧㄠ ㄌㄩˋ", "wrong": [{"z": "ㄌㄨˋ", "p": "lù"}, {"z": "ㄏㄨˇ", "p": "hǔ"}], "note": "「焦慮」「考慮」的「慮」讀ㄌㄩˋ（四聲）。", "deep": "1. 注音比較\n慮：ㄌㄩˋ（四聲）＝焦慮、考慮、顧慮、深謀遠慮。誤讀ㄌㄨˋ＝把ㄩ念成ㄨ（跟「路」相混）；誤讀ㄏㄨˇ＝把上面的「虍」直接讀出來\n2. 國字拆解與造字原因\n慮：形聲字，下面是「心」，上面是「虍」（老虎頭）加「思」的省形。心裡反覆想，就是「思慮」。★「焦慮」的「焦」本義是火燒到發黑，心裡像被火燒著一樣著急，所以叫焦慮。記法：下面有心的慮讀ㄌㄩˋ，注意是ㄩ不是ㄨ。"},
  {"id": "p832", "grade": 3, "word": "建議", "target": "議", "zhuyin": "ㄧˋ", "pinyin": "yì", "wz": "ㄐㄧㄢˋ ㄧˋ", "wrong": [{"z": "ㄧˊ", "p": "yí"}, {"z": "ㄧㄤˋ", "p": "yàng"}], "note": "「建議」「會議」的「議」讀ㄧˋ（四聲）。", "deep": "1. 注音比較\n議：ㄧˋ（四聲）＝建議、會議、議論、抗議。誤讀ㄧˊ＝與「疑」「宜」相混；誤讀ㄧㄤˋ＝把右邊的「義」讀錯\n2. 國字拆解與造字原因\n議：形聲字，「言」＋「義」（聲）。從言部表示要說出來——大家把各自認為合宜（義）的想法說出來討論，就是「議」。★「議」（討論）和「義」（正義）不同：多了言字旁才是討論。記法：言字旁的議讀四聲。"},
  {"id": "p833", "grade": 3, "word": "描述", "target": "描", "zhuyin": "ㄇㄧㄠˊ", "pinyin": "miáo", "wz": "ㄇㄧㄠˊ ㄕㄨˋ", "wrong": [{"z": "ㄇㄧㄠ", "p": "miāo"}, {"z": "ㄇㄧㄠˇ", "p": "miǎo"}], "note": "「描述」「描寫」的「描」讀ㄇㄧㄠˊ（二聲）。", "deep": "1. 注音比較\n描：ㄇㄧㄠˊ（二聲）＝描述、描寫、描繪、素描。誤讀ㄇㄧㄠ＝與「喵」相混；誤讀ㄇㄧㄠˇ＝與「秒」「渺」相混\n2. 國字拆解與造字原因\n描：形聲字，「手（扌）」＋「苗」（聲）。從手部表示是用手做的——本義是照著樣子畫下來。用文字照著樣子寫出來，就是「描述、描寫」。★同樣以「苗」為聲符：描（手，畫）／貓（犬，動物）／瞄（目，瞄準）。記法：提手旁的描讀二聲。"},
  {"id": "p834", "grade": 3, "word": "蔬菜", "target": "蔬", "zhuyin": "ㄕㄨ", "pinyin": "shū", "wz": "ㄕㄨ ㄘㄞˋ", "wrong": [{"z": "ㄙㄨ", "p": "sū"}, {"z": "ㄕㄨˋ", "p": "shù"}], "note": "「蔬菜」的「蔬」讀ㄕㄨ（一聲）。", "deep": "1. 注音比較\n蔬：ㄕㄨ（一聲）＝蔬菜、蔬果、布衣蔬食。誤讀ㄙㄨ＝ㄕ、ㄙ不分（跟「蘇」相混）；誤讀ㄕㄨˋ＝與「樹」「數」相混\n2. 國字拆解與造字原因\n蔬：形聲字，「艸（艹）」＋「疏」（聲）。從艸部表示是可以吃的草本植物。★「布衣蔬食」是說穿粗布衣、吃簡單的菜，形容生活儉樸。★「蔬」和「疏」（疏遠）差一個草字頭。記法：草字頭的蔬讀一聲ㄕㄨ。"},
  {"id": "p835", "grade": 3, "word": "隧道", "target": "隧", "zhuyin": "ㄙㄨㄟˋ", "pinyin": "suì", "wz": "ㄙㄨㄟˋ ㄉㄠˋ", "wrong": [{"z": "ㄙㄨㄟˇ", "p": "suǐ"}, {"z": "ㄓㄨㄟˋ", "p": "zhuì"}], "note": "「隧道」的「隧」讀ㄙㄨㄟˋ（四聲）。", "deep": "1. 注音比較\n隧：ㄙㄨㄟˋ（四聲）＝隧道、地隧。誤讀ㄙㄨㄟˇ＝與「髓」相混；誤讀ㄓㄨㄟˋ＝與「墜」相混\n2. 國字拆解與造字原因\n隧：形聲字，「阜（阝）」＋「遂」（聲）。左邊的「阝」叫左耳旁，本來是「阜」，指土山、高地，凡是從阜部的字多半跟地形有關（像「陸」「陡」「險」「階」）。挖穿山的通道就是隧道。★注意：左耳旁（阜，地形）和右耳旁（邑，城邑，像「都」「郊」）意思不同。記法：左耳旁的隧讀四聲。"},
  {"id": "p836", "grade": 3, "word": "郵局", "target": "郵", "zhuyin": "ㄧㄡˊ", "pinyin": "yóu", "wz": "ㄧㄡˊ ㄐㄩˊ", "wrong": [{"z": "ㄧㄡˇ", "p": "yǒu"}, {"z": "ㄔㄨㄟˊ", "p": "chuí"}], "note": "「郵局」「郵票」的「郵」讀ㄧㄡˊ（二聲）。", "deep": "1. 注音比較\n郵：ㄧㄡˊ（二聲）＝郵局、郵票、郵寄、郵差。誤讀ㄧㄡˇ＝與「有」相混；誤讀ㄔㄨㄟˊ＝把左邊的「垂」直接讀出來\n2. 國字拆解與造字原因\n郵：會意字，「垂」（邊境）＋「邑（阝）」（城邑）。古代在邊境設驛站傳遞公文，那個站就叫「郵」。★右耳旁（阝在右）本來是「邑」，跟城市、地方有關（像「都」「郊」「部」）——跟左耳旁的「阜」（地形）不一樣。記法：右耳旁的郵讀二聲。"},
  {"id": "p837", "grade": 3, "word": "診所", "target": "診", "zhuyin": "ㄓㄣˇ", "pinyin": "zhěn", "wz": "ㄓㄣˇ ㄙㄨㄛˇ", "wrong": [{"z": "ㄓㄣ", "p": "zhēn"}, {"z": "ㄗㄣˇ", "p": "zěn"}], "note": "「診所」「看診」的「診」讀ㄓㄣˇ（三聲）。", "deep": "1. 注音比較\n診：ㄓㄣˇ（三聲）＝診所、看診、診斷、門診。誤讀ㄓㄣ＝與「針」「真」相混；誤讀ㄗㄣˇ＝ㄗ、ㄓ不分\n2. 國字拆解與造字原因\n診：形聲字，「言」＋「㐱」（聲）。從言部——醫生要先問病人哪裡不舒服，所以「診」本義是察看、問明病情。中醫講「望聞問切」，其中「問」就是這個意思。記法：言字旁的診讀三聲。"},
  {"id": "p838", "grade": 3, "word": "藥膏", "target": "膏", "zhuyin": "ㄍㄠ", "pinyin": "gāo", "wz": "ㄧㄠˋ ㄍㄠ", "wrong": [{"z": "ㄍㄠˋ", "p": "gào"}, {"z": "ㄍㄠˇ", "p": "gǎo"}], "note": "「藥膏」「牙膏」的「膏」讀ㄍㄠ（一聲）。", "deep": "1. 注音比較\n膏：ㄍㄠ（一聲）＝藥膏、牙膏、膏藥、民脂民膏；ㄍㄠˋ（四聲）＝把筆沾墨叫「膏筆」（少用）。誤讀ㄍㄠˇ＝與「稿」相混\n2. 國字拆解與造字原因\n膏：形聲字，下面是「肉（月）」，本義是動物身上很油的脂肪，引申成一切濃稠像油的東西——藥膏、牙膏。★「民脂民膏」是說人民辛苦得來的財物，就像身上的油脂一樣珍貴。記法：下面是肉月的膏讀一聲。"},
  {"id": "p839", "grade": 3, "word": "繃帶", "target": "繃", "zhuyin": "ㄅㄥ", "pinyin": "bēng", "wz": "ㄅㄥ ㄉㄞˋ", "wrong": [{"z": "ㄅㄥˇ", "p": "běng"}, {"z": "ㄆㄥˊ", "p": "péng"}], "note": "「繃帶」「繃緊」讀ㄅㄥ（一聲）；「繃著臉」讀ㄅㄥˇ。", "deep": "1. 注音比較\n繃：ㄅㄥ（一聲）＝繃帶、繃緊、緊繃；ㄅㄥˇ（三聲）＝繃著臉（板起臉）；ㄅㄥˋ（四聲）＝繃硬、繃亮（很、非常，口語）。誤讀ㄆㄥˊ＝ㄅ、ㄆ不分\n2. 國字拆解與造字原因\n繃：形聲字，「糸」＋「崩」（聲）。「糸」是絲線，本義是把布或線拉緊纏住——受傷時用布條纏起來，就是「繃帶」。記法：糸字旁的繃，講纏緊讀一聲。"},
  {"id": "p840", "grade": 3, "word": "疫苗", "target": "疫", "zhuyin": "ㄧˋ", "pinyin": "yì", "wz": "ㄧˋ ㄇㄧㄠˊ", "wrong": [{"z": "ㄧˊ", "p": "yí"}, {"z": "ㄕㄨˊ", "p": "shú"}], "note": "「疫苗」「防疫」的「疫」讀ㄧˋ（四聲）。", "deep": "1. 注音比較\n疫：ㄧˋ（四聲）＝疫苗、防疫、瘟疫、免疫。誤讀ㄧˊ＝與「宜」「移」相混；誤讀ㄕㄨˊ＝把右邊的「殳」讀錯\n2. 國字拆解與造字原因\n疫：形聲字，「疒」（ㄋㄨㄜˋ，病字頭）＋「役」省聲。凡是從「疒」的字多半跟疾病有關（像「病」「痛」「疼」「症」）。「疫」本義是會傳染很多人的流行病。★「疫苗」是把病原做成無害的樣子先讓身體認識它，之後真的遇到就能擋住。記法：病字頭的疫讀四聲。"},
  {"id": "p841", "grade": 3, "word": "感冒", "target": "冒", "zhuyin": "ㄇㄠˋ", "pinyin": "mào", "wz": "ㄍㄢˇ ㄇㄠˋ", "wrong": [{"z": "ㄇㄠ", "p": "māo"}, {"z": "ㄇㄨˋ", "p": "mù"}], "note": "「感冒」「冒險」的「冒」讀ㄇㄠˋ（四聲）。", "deep": "1. 注音比較\n冒：ㄇㄠˋ（四聲）＝感冒、冒險、冒煙、假冒；ㄇㄛˋ（四聲）＝冒頓（匈奴單于的名字，讀ㄇㄛˋ ㄉㄨˊ）。誤讀ㄇㄠ＝少了聲調；誤讀ㄇㄨˋ＝把上面看成「目」\n2. 國字拆解與造字原因\n冒：會意字，上面是「冃」（帽子），下面是「目」（眼睛），畫的是帽子蓋到眼睛上——本義是「蓋住、往上頂出來」。頂著危險往前是「冒險」；被風寒「頂」到就是「感冒」。★注意上面是「冃」不是「曰」，兩橫不碰到兩邊。記法：冒讀四聲ㄇㄠˋ。"},
  {"id": "p842", "grade": 3, "word": "咳嗽", "target": "嗽", "zhuyin": "ㄙㄡˋ", "pinyin": "sòu", "wz": "ㄎㄜˊ ㄙㄡˋ", "wrong": [{"z": "ㄕㄨˋ", "p": "shù"}, {"z": "ㄙㄡ", "p": "sōu"}], "note": "「咳嗽」的「嗽」讀ㄙㄡˋ；這裡的「咳」讀ㄎㄜˊ（二聲）。", "deep": "1. 注音比較\n嗽：ㄙㄡˋ（四聲）＝咳嗽。★「漱」（ㄕㄨˋ，三點水）是漱口，跟「嗽」是兩個字。誤讀ㄙㄡ＝少了聲調\n2. 國字拆解與造字原因\n嗽：形聲字，「口」＋「敕」（聲）。從口部表示是從嘴巴發出的動作。★「咳嗽」的「咳」在這個詞裡讀ㄎㄜˊ（二聲）；「咳聲嘆氣」的咳讀ㄏㄞ。★咳嗽其實是身體的保護動作，用強烈的氣流把喉嚨、氣管裡的髒東西沖出去。記法：口字旁的嗽讀ㄙㄡˋ，三點水的漱讀ㄕㄨˋ。"},
  {"id": "p843", "grade": 4, "word": "朝代", "target": "朝", "zhuyin": "ㄔㄠˊ", "pinyin": "cháo", "wz": "ㄔㄠˊ ㄉㄞˋ", "wrong": [{"z": "ㄓㄠ", "p": "zhāo"}, {"z": "ㄔㄠˇ", "p": "chǎo"}], "note": "「朝代」「朝廷」讀ㄔㄠˊ；「朝陽」「朝氣」讀ㄓㄠ。", "deep": "1. 注音比較\n朝：ㄔㄠˊ（二聲）＝朝代、朝廷、上朝、改朝換代（朝廷、時代）；ㄓㄠ（一聲）＝朝陽、朝氣、朝三暮四、一朝一夕（早晨）。誤讀ㄔㄠˇ＝與「吵」相混\n2. 國字拆解與造字原因\n朝：會意字，左邊畫草叢中太陽剛升起、月亮還沒落下，本義是「早晨」（ㄓㄠ）。古代臣子清早要進宮見君王，所以「上朝、朝廷」也用這個字，讀ㄔㄠˊ。★「朝三暮四」的朝是早上，「改朝換代」的朝是朝廷。記法：早晨一聲、朝廷二聲。"},
  {"id": "p844", "grade": 4, "word": "相似", "target": "似", "zhuyin": "ㄙˋ", "pinyin": "sì", "wz": "ㄒㄧㄤ ㄙˋ", "wrong": [{"z": "ㄕˋ", "p": "shì"}, {"z": "ㄙˇ", "p": "sǐ"}], "note": "「相似」「類似」讀ㄙˋ；只有「似的」讀ㄕˋ。", "deep": "1. 注音比較\n似：ㄙˋ（四聲）＝相似、類似、似乎、似曾相識；ㄕˋ（四聲）＝似的（像…一樣，如「雪似的白」）。誤讀ㄙˇ＝與「死」相混\n2. 國字拆解與造字原因\n似：形聲字，「人（亻）」＋「以」（聲）。本義是像、相類。★「似的」是口語裡固定的說法，只有這個詞讀ㄕˋ，其他一律讀ㄙˋ。★「似曾相識」是說好像從前見過。記法：只有「似的」讀ㄕˋ。"},
  {"id": "p845", "grade": 4, "word": "扒手", "target": "扒", "zhuyin": "ㄆㄚˊ", "pinyin": "pá", "wz": "ㄆㄚˊ ㄕㄡˇ", "wrong": [{"z": "ㄅㄚ", "p": "bā"}, {"z": "ㄆㄚ", "p": "pā"}], "note": "「扒手」「扒竊」讀ㄆㄚˊ（二聲）；「扒開」「扒皮」讀ㄅㄚ（一聲）。", "deep": "1. 注音比較\n扒：ㄆㄚˊ（二聲）＝扒手、扒竊、扒飯（偷、用手耙）；ㄅㄚ（一聲）＝扒開、扒下來、扒皮（用力撥開、剝掉）。誤讀ㄆㄚ＝少了聲調（跟「趴」相混）\n2. 國字拆解與造字原因\n扒：形聲字，「手（扌）」＋「八」（聲）。「八」本來就是分開的樣子——用手把東西撥開就是「扒開」（一聲）；手指像耙子一樣勾東西、順走別人的財物，就是「扒手」（二聲）。記法：撥開一聲、偷竊二聲。"},
  {"id": "p846", "grade": 4, "word": "挑剔", "target": "剔", "zhuyin": "ㄊㄧ", "pinyin": "tī", "wz": "ㄊㄧㄠ ㄊㄧ", "wrong": [{"z": "ㄊㄧˋ", "p": "tì"}, {"z": "ㄧˋ", "p": "yì"}], "note": "「挑剔」的「剔」讀ㄊㄧ（一聲）；這裡的「挑」讀ㄊㄧㄠ（一聲）。", "deep": "1. 注音比較\n剔：ㄊㄧ（一聲）＝挑剔、剔骨、剔除。誤讀ㄊㄧˋ＝與「替」「惕」相混；誤讀ㄧˋ＝把左邊的「易」直接讀出來\n2. 國字拆解與造字原因\n剔：形聲字，「刀（刂）」＋「易」（聲）。從刀部——本義是用刀把骨頭上的肉刮下來，引申成一項一項挑毛病。★「挑剔」的「挑」在這裡讀一聲ㄊㄧㄠ（挑選），不是三聲。記法：立刀旁的剔讀一聲ㄊㄧ。"},
  {"id": "p847", "grade": 4, "word": "沉澱", "target": "澱", "zhuyin": "ㄉㄧㄢˋ", "pinyin": "diàn", "wz": "ㄔㄣˊ ㄉㄧㄢˋ", "wrong": [{"z": "ㄉㄧㄢˇ", "p": "diǎn"}, {"z": "ㄉㄧㄥˋ", "p": "dìng"}], "note": "「沉澱」的「澱」讀ㄉㄧㄢˋ（四聲）。", "deep": "1. 注音比較\n澱：ㄉㄧㄢˋ（四聲）＝沉澱、澱粉。誤讀ㄉㄧㄢˇ＝與「點」相混；誤讀ㄉㄧㄥˋ＝與「定」相混（ㄢ、ㄥ不分）\n2. 國字拆解與造字原因\n澱：形聲字，「水（氵）」＋「殿」（聲）。從水部——本義是水裡的雜質慢慢沉到底下積成一層。★「沉澱」也用來比喻讓心情或想法安定下來（把思緒沉澱一下）。記法：三點水的澱讀四聲。"},
  {"id": "p848", "grade": 4, "word": "呼吸", "target": "吸", "zhuyin": "ㄒㄧ", "pinyin": "xī", "wz": "ㄏㄨ ㄒㄧ", "wrong": [{"z": "ㄒㄧˊ", "p": "xí"}, {"z": "ㄐㄧˊ", "p": "jí"}], "note": "「呼吸」「吸收」的「吸」讀ㄒㄧ（一聲）。", "deep": "1. 注音比較\n吸：ㄒㄧ（一聲）＝呼吸、吸收、吸引、吸管。誤讀ㄒㄧˊ＝與「習」「席」相混；誤讀ㄐㄧˊ＝與「及」「急」相混\n2. 國字拆解與造字原因\n吸：形聲字，「口」＋「及」（聲）。從口部表示是嘴巴的動作。★「呼」是把氣送出去、「吸」是把氣拉進來，兩個字都是口字旁，方向相反。★人吸進的空氣裡氧氣約占五分之一，呼出的氣則多了二氧化碳。記法：口字旁的吸讀一聲。"},
  {"id": "p849", "grade": 4, "word": "蒸發", "target": "蒸", "zhuyin": "ㄓㄥ", "pinyin": "zhēng", "wz": "ㄓㄥ ㄈㄚ", "wrong": [{"z": "ㄓㄣ", "p": "zhēn"}, {"z": "ㄔㄥˊ", "p": "chéng"}], "note": "「蒸發」「蒸氣」的「蒸」讀ㄓㄥ（一聲）。", "deep": "1. 注音比較\n蒸：ㄓㄥ（一聲）＝蒸發、蒸氣、蒸餃、蒸蒸日上。誤讀ㄓㄣ＝ㄥ、ㄣ不分（跟「真」相混）；誤讀ㄔㄥˊ＝與「成」相混\n2. 國字拆解與造字原因\n蒸：形聲字，「艸（艹）」＋「烝」（聲），下面有「灬」（火）。本義是用火加熱讓水氣往上升。★「蒸發」是液體表面的水分子跑到空氣中變成水蒸氣，不必燒開也會發生——晾衣服會乾就是蒸發。★「蒸蒸日上」形容一天比一天興旺。記法：草字頭下面有火的蒸讀一聲。"},
  {"id": "p850", "grade": 4, "word": "凝固", "target": "凝", "zhuyin": "ㄋㄧㄥˊ", "pinyin": "níng", "wz": "ㄋㄧㄥˊ ㄍㄨˋ", "wrong": [{"z": "ㄋㄧㄥˋ", "p": "nìng"}, {"z": "ㄧˊ", "p": "yí"}], "note": "「凝固」「凝視」的「凝」讀ㄋㄧㄥˊ（二聲）。", "deep": "1. 注音比較\n凝：ㄋㄧㄥˊ（二聲）＝凝固、凝結、凝視、凝聚。誤讀ㄋㄧㄥˋ＝與「寧可」的另一音相混；誤讀ㄧˊ＝把右邊的「疑」直接讀出來\n2. 國字拆解與造字原因\n凝：形聲字，「冫」（兩點水，是「冰」的省寫）＋「疑」（聲）。「冫」跟結冰、寒冷有關（像「冷」「凍」「冰」）——液體遇冷變成固體就是「凝固」。★眼神集中不動也叫「凝視」。★注意左邊是兩點水（冫），不是三點水（氵）。記法：兩點水的凝讀二聲。"},
  {"id": "p851", "grade": 4, "word": "溶解", "target": "溶", "zhuyin": "ㄖㄨㄥˊ", "pinyin": "róng", "wz": "ㄖㄨㄥˊ ㄐㄧㄝˇ", "wrong": [{"z": "ㄖㄨㄥˇ", "p": "rǒng"}, {"z": "ㄌㄨㄥˊ", "p": "lóng"}], "note": "「溶解」「溶化」的「溶」讀ㄖㄨㄥˊ（二聲）。", "deep": "1. 注音比較\n溶：ㄖㄨㄥˊ（二聲）＝溶解、溶化、溶液。誤讀ㄖㄨㄥˇ＝聲調錯；誤讀ㄌㄨㄥˊ＝ㄖ、ㄌ不分\n2. 國字拆解與造字原因\n溶：形聲字，「水（氵）」＋「容」（聲）。從水部——本義是東西化在水裡。★三個同音字要分清楚：溶（三點水，化在水裡，如糖溶解）／融（鬲字旁，冰雪化開、融合）／熔（火字旁，金屬被高溫化成液體，如熔岩）。記法：三點水的溶跟水有關，讀二聲。"},
  {"id": "p852", "grade": 4, "word": "濃度", "target": "濃", "zhuyin": "ㄋㄨㄥˊ", "pinyin": "nóng", "wz": "ㄋㄨㄥˊ ㄉㄨˋ", "wrong": [{"z": "ㄋㄨㄥˋ", "p": "nòng"}, {"z": "ㄌㄨㄥˊ", "p": "lóng"}], "note": "「濃度」「濃湯」的「濃」讀ㄋㄨㄥˊ（二聲）。", "deep": "1. 注音比較\n濃：ㄋㄨㄥˊ（二聲）＝濃度、濃湯、濃厚、濃眉大眼。誤讀ㄋㄨㄥˋ＝與「弄」相混；誤讀ㄌㄨㄥˊ＝ㄋ、ㄌ不分\n2. 國字拆解與造字原因\n濃：形聲字，「水（氵）」＋「農」（聲）。本義是露水多、味道厚。★同樣以「農」為聲符：濃（水，濃淡）／膿（肉，膿包）／儂（人，古語的「你、我」）。★「濃度」是指一定分量的液體裡溶了多少東西。記法：三點水的濃讀二聲。"},
  {"id": "p853", "grade": 4, "word": "磁鐵", "target": "磁", "zhuyin": "ㄘˊ", "pinyin": "cí", "wz": "ㄘˊ ㄊㄧㄝˇ", "wrong": [{"z": "ㄗˊ", "p": "zí"}, {"z": "ㄔˊ", "p": "chí"}], "note": "「磁鐵」「磁場」的「磁」讀ㄘˊ（二聲）。", "deep": "1. 注音比較\n磁：ㄘˊ（二聲）＝磁鐵、磁場、磁力、磁磚。誤讀ㄗˊ＝ㄗ、ㄘ不分；誤讀ㄔˊ＝平舌、翹舌不分\n2. 國字拆解與造字原因\n磁：形聲字，「石」＋「茲」（聲）。從石部——古人最早發現的磁石是一種天然的石頭，會吸鐵。★磁鐵有南北兩極，同極相斥、異極相吸；把磁鐵折成兩半，每一半仍然有南北兩極。記法：石字旁的磁讀二聲ㄘˊ，是平舌音。"},
  {"id": "p854", "grade": 4, "word": "摩擦", "target": "摩", "zhuyin": "ㄇㄛˊ", "pinyin": "mó", "wz": "ㄇㄛˊ ㄘㄚ", "wrong": [{"z": "ㄇㄛˋ", "p": "mò"}, {"z": "ㄇㄚˊ", "p": "má"}], "note": "「摩擦」「摩天大樓」的「摩」讀ㄇㄛˊ（二聲）。", "deep": "1. 注音比較\n摩：ㄇㄛˊ（二聲）＝摩擦、摩天大樓、按摩、摩拳擦掌。誤讀ㄇㄛˋ＝與「墨」「莫」相混；誤讀ㄇㄚˊ＝把上面的「麻」直接讀出來\n2. 國字拆解與造字原因\n摩：形聲字，「手」＋「麻」（聲）。下面是「手」，表示是用手來回擦動。★「摩」（下面是手，摩擦）和「磨」（下面是石，磨刀、石磨）不同：一個用手、一個用石頭。★「摩天大樓」是說高得好像擦到天。記法：下面是手的摩讀二聲。"},
  {"id": "p855", "grade": 4, "word": "齒輪", "target": "齒", "zhuyin": "ㄔˇ", "pinyin": "chǐ", "wz": "ㄔˇ ㄌㄨㄣˊ", "wrong": [{"z": "ㄘˇ", "p": "cǐ"}, {"z": "ㄔˋ", "p": "chì"}], "note": "「齒輪」「牙齒」的「齒」讀ㄔˇ（三聲）。", "deep": "1. 注音比較\n齒：ㄔˇ（三聲）＝齒輪、牙齒、齒縫、唇亡齒寒。誤讀ㄘˇ＝平舌、翹舌不分（跟「此」相混）；誤讀ㄔˋ＝與「翅」「斥」相混\n2. 國字拆解與造字原因\n齒：象形字，古文字畫的是嘴巴裡上下一排牙齒。「齒」本身也是部首。★古人把門牙叫「齒」、後面的臼齒叫「牙」，現在合稱牙齒。★「齒輪」邊上一個個凸起像牙齒，所以叫齒輪；兩個齒輪咬在一起就能把轉動傳過去。記法：齒讀三聲ㄔˇ，舌頭要翹。"},
  {"id": "p856", "grade": 4, "word": "槓桿", "target": "槓", "zhuyin": "ㄍㄤˋ", "pinyin": "gàng", "wz": "ㄍㄤˋ ㄍㄢˇ", "wrong": [{"z": "ㄍㄤ", "p": "gāng"}, {"z": "ㄍㄨㄥˋ", "p": "gòng"}], "note": "「槓桿」「單槓」的「槓」讀ㄍㄤˋ（四聲）。", "deep": "1. 注音比較\n槓：ㄍㄤˋ（四聲）＝槓桿、單槓、鐵槓。誤讀ㄍㄤ＝與「剛」「鋼」相混；誤讀ㄍㄨㄥˋ＝把右邊的「貢」直接讀出來\n2. 國字拆解與造字原因\n槓：形聲字，「木」＋「貢」（聲）。從木部，因為最早的槓是一根木棒。★槓桿有三個點：支點、施力點、抗力點；施力點離支點越遠越省力，這就是「給我一個支點，我可以撬起地球」的道理。★「桿」在這裡讀ㄍㄢˇ。記法：木字旁的槓讀四聲。"},
  {"id": "p857", "grade": 4, "word": "彈簧", "target": "簧", "zhuyin": "ㄏㄨㄤˊ", "pinyin": "huáng", "wz": "ㄊㄢˊ ㄏㄨㄤˊ", "wrong": [{"z": "ㄏㄨㄤ", "p": "huāng"}, {"z": "ㄏㄨㄤˇ", "p": "huǎng"}], "note": "「彈簧」的「簧」讀ㄏㄨㄤˊ（二聲）；這裡的「彈」讀ㄊㄢˊ（二聲）。", "deep": "1. 注音比較\n簧：ㄏㄨㄤˊ（二聲）＝彈簧、簧片、巧舌如簧。誤讀ㄏㄨㄤ＝與「荒」相混；誤讀ㄏㄨㄤˇ＝與「謊」相混\n2. 國字拆解與造字原因\n簧：形聲字，「竹」＋「黃」（聲）。從竹部——本義是笙、竽這類樂器裡會震動發聲的薄片，因為古代用竹片做。薄片能彈回來，所以會回彈的金屬圈也叫「彈簧」。★「彈簧」的「彈」讀ㄊㄢˊ（彈跳），不是「子彈」的ㄉㄢˋ。記法：竹字頭的簧讀二聲。"},
  {"id": "p858", "grade": 4, "word": "螺絲", "target": "螺", "zhuyin": "ㄌㄨㄛˊ", "pinyin": "luó", "wz": "ㄌㄨㄛˊ ㄙ", "wrong": [{"z": "ㄌㄟˇ", "p": "lěi"}, {"z": "ㄌㄨㄛˇ", "p": "luǒ"}], "note": "「螺絲」「螺旋」的「螺」讀ㄌㄨㄛˊ（二聲）。", "deep": "1. 注音比較\n螺：ㄌㄨㄛˊ（二聲）＝螺絲、螺旋、田螺、陀螺。誤讀ㄌㄟˇ＝把右上的「田」加「糸」看錯；誤讀ㄌㄨㄛˇ＝與「裸」相混\n2. 國字拆解與造字原因\n螺：形聲字，「虫」＋「累」（聲）。本義是有旋轉硬殼的軟體動物（田螺、海螺）。因為殼上是一圈一圈旋著上去的，所以那種形狀就叫「螺旋」，螺絲上的紋路也因此得名。記法：虫字旁的螺讀二聲。"},
  {"id": "p859", "grade": 4, "word": "插頭", "target": "插", "zhuyin": "ㄔㄚ", "pinyin": "chā", "wz": "ㄔㄚ ㄊㄡˊ", "wrong": [{"z": "ㄔㄚˋ", "p": "chà"}, {"z": "ㄗㄚ", "p": "zā"}], "note": "「插頭」「插花」的「插」讀ㄔㄚ（一聲）。", "deep": "1. 注音比較\n插：ㄔㄚ（一聲）＝插頭、插花、插隊、插曲。誤讀ㄔㄚˋ＝與「岔」「詫」相混；誤讀ㄗㄚ＝平舌、翹舌不分\n2. 國字拆解與造字原因\n插：形聲字，「手（扌）」＋「臿」（聲）。「臿」本來是把杵放進臼裡舂米的樣子，所以「插」的本義就是把東西直直放進去。★「插曲」原指戲中間插進去的樂曲，後來比喻事情進行中忽然發生的小事。記法：提手旁的插讀一聲。"},
  {"id": "p860", "grade": 4, "word": "導線", "target": "導", "zhuyin": "ㄉㄠˇ", "pinyin": "dǎo", "wz": "ㄉㄠˇ ㄒㄧㄢˋ", "wrong": [{"z": "ㄉㄠˋ", "p": "dào"}, {"z": "ㄉㄠ", "p": "dāo"}], "note": "「導線」「導電」的「導」讀ㄉㄠˇ（三聲）。", "deep": "1. 注音比較\n導：ㄉㄠˇ（三聲）＝導線、導電、指導、領導、導演。誤讀ㄉㄠˋ＝與「到」「道」相混；誤讀ㄉㄠ＝與「刀」相混\n2. 國字拆解與造字原因\n導：形聲字，「寸」（手）＋「道」（聲）。用手帶著人走上正路，本義是「引路、帶領」。★電流能通過的東西叫「導體」（金屬、石墨），不能通過的叫「絕緣體」（塑膠、橡膠、乾木頭）。記法：下面是寸的導讀三聲。"},
  {"id": "p861", "grade": 4, "word": "絕緣", "target": "緣", "zhuyin": "ㄩㄢˊ", "pinyin": "yuán", "wz": "ㄐㄩㄝˊ ㄩㄢˊ", "wrong": [{"z": "ㄩㄢˋ", "p": "yuàn"}, {"z": "ㄌㄩˋ", "p": "lǜ"}], "note": "「絕緣」「緣分」的「緣」讀ㄩㄢˊ（二聲）。", "deep": "1. 注音比較\n緣：ㄩㄢˊ（二聲）＝絕緣、緣分、邊緣、緣故、緣木求魚。誤讀ㄩㄢˋ＝與「願」「怨」相混；誤讀ㄌㄩˋ＝與「綠」相混\n2. 國字拆解與造字原因\n緣：形聲字，「糸」＋「彖」（聲）。本義是衣服的鑲邊，引申成「邊」（邊緣），也引申成「順著、依著」——「緣故」就是事情順著什麼原因來的。★「緣木求魚」是說爬到樹上找魚，比喻方向錯了絕對得不到。記法：糸字旁的緣讀二聲。"},
  {"id": "p862", "grade": 4, "word": "顯微鏡", "target": "顯", "zhuyin": "ㄒㄧㄢˇ", "pinyin": "xiǎn", "wz": "ㄒㄧㄢˇ ㄨㄟˊ ㄐㄧㄥˋ", "wrong": [{"z": "ㄒㄧㄢˋ", "p": "xiàn"}, {"z": "ㄒㄧㄢ", "p": "xiān"}], "note": "「顯微鏡」「明顯」的「顯」讀ㄒㄧㄢˇ（三聲）。", "deep": "1. 注音比較\n顯：ㄒㄧㄢˇ（三聲）＝顯微鏡、明顯、顯示、顯而易見。誤讀ㄒㄧㄢˋ＝與「現」「線」相混；誤讀ㄒㄧㄢ＝與「先」相混\n2. 國字拆解與造字原因\n顯：形聲字，右邊是「頁」（頭），本義是明白清楚地表現出來。★「顯微鏡」的意思就是「讓微小的東西顯出來的鏡子」——顯（讓它顯出來）＋微（很小的）＋鏡。★「顯微鏡」的「微」讀ㄨㄟˊ（二聲）。記法：顯讀三聲ㄒㄧㄢˇ。"},
  {"id": "p863", "grade": 4, "word": "標本", "target": "標", "zhuyin": "ㄅㄧㄠ", "pinyin": "biāo", "wz": "ㄅㄧㄠ ㄅㄣˇ", "wrong": [{"z": "ㄅㄧㄠˋ", "p": "biào"}, {"z": "ㄆㄧㄠ", "p": "piāo"}], "note": "「標本」「目標」的「標」讀ㄅㄧㄠ（一聲）。", "deep": "1. 注音比較\n標：ㄅㄧㄠ（一聲）＝標本、目標、標準、招標、治標不治本。誤讀ㄅㄧㄠˋ＝與「鰾」相混；誤讀ㄆㄧㄠ＝ㄅ、ㄆ不分（跟「飄」相混）\n2. 國字拆解與造字原因\n標：形聲字，「木」＋「票」（聲）。本義是樹的末梢——樹梢最顯眼，所以引申成「做記號、顯示出來的部分」。★「治標不治本」的「標」就是表面現象，「本」是樹根、根本原因。記法：木字旁的標讀一聲。"},
  {"id": "p864", "grade": 4, "word": "星座", "target": "座", "zhuyin": "ㄗㄨㄛˋ", "pinyin": "zuò", "wz": "ㄒㄧㄥ ㄗㄨㄛˋ", "wrong": [{"z": "ㄗㄨㄛˇ", "p": "zuǒ"}, {"z": "ㄘㄨㄛˋ", "p": "cuò"}], "note": "「星座」「座位」的「座」讀ㄗㄨㄛˋ（四聲）。", "deep": "1. 注音比較\n座：ㄗㄨㄛˋ（四聲）＝星座、座位、講座、一座山。誤讀ㄗㄨㄛˇ＝與「左」相混；誤讀ㄘㄨㄛˋ＝ㄗ、ㄘ不分\n2. 國字拆解與造字原因\n座：形聲字，「广」（房子）＋「坐」（聲）。★「座」（广字頭，名詞，座位、一座）和「坐」（動詞，坐下）不同：有房子頭的是東西或量詞。★星座是古人把天上位置相近的星連起來想像成圖案，其實那些星彼此距離非常遠。記法：广字頭的座是名詞，讀四聲。"},
  {"id": "p865", "grade": 4, "word": "彗星", "target": "彗", "zhuyin": "ㄏㄨㄟˋ", "pinyin": "huì", "wz": "ㄏㄨㄟˋ ㄒㄧㄥ", "wrong": [{"z": "ㄒㄩㄝˇ", "p": "xuě"}, {"z": "ㄏㄨㄟˊ", "p": "huí"}], "note": "「彗星」的「彗」讀ㄏㄨㄟˋ（四聲）。", "deep": "1. 注音比較\n彗：ㄏㄨㄟˋ（四聲）＝彗星、掃彗。誤讀ㄒㄩㄝˇ＝與長得像的「雪」相混；誤讀ㄏㄨㄟˊ＝與「回」相混\n2. 國字拆解與造字原因\n彗：會意字，上面是兩把細枝、下面是「彐」（手），畫的是手拿掃帚，本義就是掃帚。彗星拖著一條長長的尾巴，像天上的掃帚，所以古人叫它「彗星」，俗稱「掃把星」。★彗星的尾巴是被太陽風吹出來的，永遠背著太陽。記法：彗讀ㄏㄨㄟˋ，本義是掃帚。"},
  {"id": "p866", "grade": 4, "word": "衛星", "target": "衛", "zhuyin": "ㄨㄟˋ", "pinyin": "wèi", "wz": "ㄨㄟˋ ㄒㄧㄥ", "wrong": [{"z": "ㄨㄟˊ", "p": "wéi"}, {"z": "ㄏㄨㄟˋ", "p": "huì"}], "note": "「衛星」「保衛」的「衛」讀ㄨㄟˋ（四聲）。", "deep": "1. 注音比較\n衛：ㄨㄟˋ（四聲）＝衛星、保衛、防衛、衛生。誤讀ㄨㄟˊ＝與「為」「圍」相混；誤讀ㄏㄨㄟˋ＝聲母看錯\n2. 國字拆解與造字原因\n衛：會意字，外面是「行」（十字路口），中間是腳步繞著走，本義是「圍著守護」。★繞著行星轉的星體就叫「衛星」——月球是地球的天然衛星，我們發射上去的叫人造衛星。記法：中間有「韋」、外面是「行」的衛讀四聲。"},
  {"id": "p867", "grade": 4, "word": "軌道", "target": "軌", "zhuyin": "ㄍㄨㄟˇ", "pinyin": "guǐ", "wz": "ㄍㄨㄟˇ ㄉㄠˋ", "wrong": [{"z": "ㄍㄨㄟ", "p": "guī"}, {"z": "ㄐㄧㄡˇ", "p": "jiǔ"}], "note": "「軌道」「軌跡」的「軌」讀ㄍㄨㄟˇ（三聲）。", "deep": "1. 注音比較\n軌：ㄍㄨㄟˇ（三聲）＝軌道、軌跡、鐵軌、步入正軌。誤讀ㄍㄨㄟ＝與「歸」「規」相混；誤讀ㄐㄧㄡˇ＝把右邊的「九」直接讀出來\n2. 國字拆解與造字原因\n軌：形聲字，「車」＋「九」（聲）。從車部——本義是車輪輾出來的痕跡，引申成一定要走的路線。★「步入正軌」是說事情開始照著該有的方向進行。記法：車字旁的軌讀三聲。"},
  {"id": "p868", "grade": 4, "word": "潮汐", "target": "汐", "zhuyin": "ㄒㄧˋ", "pinyin": "xì", "wz": "ㄔㄠˊ ㄒㄧˋ", "wrong": [{"z": "ㄒㄧ", "p": "xī"}, {"z": "ㄕˋ", "p": "shì"}], "note": "「潮汐」的「汐」讀ㄒㄧˋ（四聲）。", "deep": "1. 注音比較\n汐：ㄒㄧˋ（四聲）＝潮汐、汐止（新北地名）。誤讀ㄒㄧ＝少了聲調（跟「西」相混）；誤讀ㄕˋ＝ㄒ、ㄕ不分\n2. 國字拆解與造字原因\n汐：形聲字，「水（氵）」＋「夕」（聲）。「夕」是傍晚——古人把早上的海水漲落叫「潮」、晚上的叫「汐」，合起來就是「潮汐」。★潮汐主要是月球的引力把海水拉起來造成的。記法：三點水的汐讀四聲。"},
  {"id": "p869", "grade": 4, "word": "颱風", "target": "颱", "zhuyin": "ㄊㄞˊ", "pinyin": "tái", "wz": "ㄊㄞˊ ㄈㄥ", "wrong": [{"z": "ㄊㄞ", "p": "tāi"}, {"z": "ㄊㄞˋ", "p": "tài"}], "note": "「颱風」的「颱」讀ㄊㄞˊ（二聲）。", "deep": "1. 注音比較\n颱：ㄊㄞˊ（二聲）＝颱風。誤讀ㄊㄞ＝與「胎」相混；誤讀ㄊㄞˋ＝與「太」「態」相混\n2. 國字拆解與造字原因\n颱：形聲字，「風」＋「台」（聲）。從風部表示是一種風。★注意「颱風」（有風字邊，指氣旋）和「台風」（指人在臺上的表現）是不同的詞。★颱風中心那個平靜無雲的區域叫「颱風眼」。記法：風字邊的颱讀二聲。"},
  {"id": "p870", "grade": 4, "word": "地震", "target": "震", "zhuyin": "ㄓㄣˋ", "pinyin": "zhèn", "wz": "ㄉㄧˋ ㄓㄣˋ", "wrong": [{"z": "ㄓㄣ", "p": "zhēn"}, {"z": "ㄔㄣˊ", "p": "chén"}], "note": "「地震」「震動」的「震」讀ㄓㄣˋ（四聲）。", "deep": "1. 注音比較\n震：ㄓㄣˋ（四聲）＝地震、震動、震驚、餘震。誤讀ㄓㄣ＝與「針」「真」相混；誤讀ㄔㄣˊ＝與「陳」「沉」相混\n2. 國字拆解與造字原因\n震：形聲字，「雨」＋「辰」（聲）。從雨部——本義是打雷，雷聲會讓東西發抖，引申成一切劇烈的搖動。★「震」（雨字頭，搖動）和「振」（提手旁，振作、揮動）不同：一個是被搖，一個是主動揮。記法：雨字頭的震讀四聲。"},
  {"id": "p871", "grade": 4, "word": "岩漿", "target": "岩", "zhuyin": "ㄧㄢˊ", "pinyin": "yán", "wz": "ㄧㄢˊ ㄐㄧㄤ", "wrong": [{"z": "ㄧㄢˇ", "p": "yǎn"}, {"z": "ㄕˊ", "p": "shí"}], "note": "「岩漿」「岩石」的「岩」讀ㄧㄢˊ（二聲）。", "deep": "1. 注音比較\n岩：ㄧㄢˊ（二聲）＝岩漿、岩石、火成岩、砂岩。誤讀ㄧㄢˇ＝與「眼」「演」相混；誤讀ㄕˊ＝把下面的「石」直接讀出來\n2. 國字拆解與造字原因\n岩：會意字，上面是「山」、下面是「石」，山上的大石頭就是岩。★地底下高溫熔化的岩石叫「岩漿」，噴出地面後叫「熔岩」，冷卻凝固就成了火成岩。記法：山加石的岩讀二聲。"},
  {"id": "p872", "grade": 4, "word": "侵蝕", "target": "蝕", "zhuyin": "ㄕˊ", "pinyin": "shí", "wz": "ㄑㄧㄣ ㄕˊ", "wrong": [{"z": "ㄕˋ", "p": "shì"}, {"z": "ㄙˊ", "p": "sí"}], "note": "「侵蝕」「腐蝕」的「蝕」讀ㄕˊ（二聲）。", "deep": "1. 注音比較\n蝕：ㄕˊ（二聲）＝侵蝕、腐蝕、日蝕、月蝕。誤讀ㄕˋ＝與「是」「事」相混；誤讀ㄙˊ＝平舌、翹舌不分\n2. 國字拆解與造字原因\n蝕：會意兼形聲，從「虫」、從「食」，本義是被蟲一點一點吃掉——引申成任何被慢慢消耗掉的情形。★河水沖刷岩石、海浪打掉海岸，都叫「侵蝕」。★太陽或月亮被遮住，古人以為是被天狗吃掉，所以叫「日蝕」「月蝕」。記法：有「食」的蝕讀二聲。"},
  {"id": "p873", "grade": 4, "word": "峽谷", "target": "峽", "zhuyin": "ㄒㄧㄚˊ", "pinyin": "xiá", "wz": "ㄒㄧㄚˊ ㄍㄨˇ", "wrong": [{"z": "ㄐㄧㄚˊ", "p": "jiá"}, {"z": "ㄒㄧㄚˋ", "p": "xià"}], "note": "「峽谷」「海峽」的「峽」讀ㄒㄧㄚˊ（二聲）。", "deep": "1. 注音比較\n峽：ㄒㄧㄚˊ（二聲）＝峽谷、海峽、三峽。誤讀ㄐㄧㄚˊ＝把右邊的「夾」直接讀出來；誤讀ㄒㄧㄚˋ＝與「下」「夏」相混\n2. 國字拆解與造字原因\n峽：形聲字，「山」＋「夾」（聲）。兩山夾著一條水道，就是「峽」——夾在中間的意思由聲符「夾」帶出來。★臺灣海峽就是臺灣和大陸之間夾著的那片海。★峽谷多半是河水長期向下侵蝕切出來的。記法：山字旁的峽讀二聲。"},
  {"id": "p874", "grade": 4, "word": "盆地", "target": "盆", "zhuyin": "ㄆㄣˊ", "pinyin": "pén", "wz": "ㄆㄣˊ ㄉㄧˋ", "wrong": [{"z": "ㄅㄣˊ", "p": "bén"}, {"z": "ㄆㄥˊ", "p": "péng"}], "note": "「盆地」「臉盆」的「盆」讀ㄆㄣˊ（二聲）。", "deep": "1. 注音比較\n盆：ㄆㄣˊ（二聲）＝盆地、臉盆、花盆、傾盆大雨。誤讀ㄅㄣˊ＝ㄅ、ㄆ不分；誤讀ㄆㄥˊ＝ㄣ、ㄥ不分（跟「朋」相混）\n2. 國字拆解與造字原因\n盆：形聲字，下面是「皿」（器皿），本義是口大底小的容器。★四周高、中間低的地形，形狀像一個盆子，所以叫「盆地」——臺北就是一個盆地。記法：下面是皿的盆讀二聲。"},
  {"id": "p875", "grade": 4, "word": "丘陵", "target": "陵", "zhuyin": "ㄌㄧㄥˊ", "pinyin": "líng", "wz": "ㄑㄧㄡ ㄌㄧㄥˊ", "wrong": [{"z": "ㄌㄧㄥˇ", "p": "lǐng"}, {"z": "ㄌㄧㄣˊ", "p": "lín"}], "note": "「丘陵」「陵墓」的「陵」讀ㄌㄧㄥˊ（二聲）。", "deep": "1. 注音比較\n陵：ㄌㄧㄥˊ（二聲）＝丘陵、陵墓、陵寢、盛氣凌人的「凌」另有其字。誤讀ㄌㄧㄥˇ＝與「領」相混；誤讀ㄌㄧㄣˊ＝ㄥ、ㄣ不分\n2. 國字拆解與造字原因\n陵：形聲字，左耳旁（阜，土山）＋「夌」（聲）。從阜部表示跟地形有關，本義是大土山。★帝王的墳墓築得像小山，所以叫「陵」（陵墓）。★「丘陵」是起伏不大、高度不高的小山地。記法：左耳旁的陵讀二聲。"},
  {"id": "p876", "grade": 4, "word": "沼澤", "target": "沼", "zhuyin": "ㄓㄠˇ", "pinyin": "zhǎo", "wz": "ㄓㄠˇ ㄗㄜˊ", "wrong": [{"z": "ㄓㄠ", "p": "zhāo"}, {"z": "ㄕㄠˋ", "p": "shào"}], "note": "「沼澤」「池沼」的「沼」讀ㄓㄠˇ（三聲）。", "deep": "1. 注音比較\n沼：ㄓㄠˇ（三聲）＝沼澤、池沼、沼氣。誤讀ㄓㄠ＝與「招」「朝陽」的朝相混；誤讀ㄕㄠˋ＝把右邊的「召」讀成ㄕㄠˋ\n2. 國字拆解與造字原因\n沼：形聲字，「水（氵）」＋「召」（聲）。本義是水淺的池子。★「沼澤」是地面長期積著淺水、長滿水生植物的地方，是很多動物的家，也能像海綿一樣吸水，減輕水災。記法：三點水的沼讀三聲。"},
  {"id": "p877", "grade": 4, "word": "沙漠", "target": "漠", "zhuyin": "ㄇㄛˋ", "pinyin": "mò", "wz": "ㄕㄚ ㄇㄛˋ", "wrong": [{"z": "ㄇㄨˋ", "p": "mù"}, {"z": "ㄇㄛˊ", "p": "mó"}], "note": "「沙漠」「冷漠」的「漠」讀ㄇㄛˋ（四聲）。", "deep": "1. 注音比較\n漠：ㄇㄛˋ（四聲）＝沙漠、冷漠、漠不關心、廣漠。誤讀ㄇㄨˋ＝與「幕」「慕」「墓」相混；誤讀ㄇㄛˊ＝與「摩」「模」相混\n2. 國字拆解與造字原因\n漠：形聲字，「水（氵）」＋「莫」（聲）。奇怪的是沙漠沒有水，卻用三點水——因為「漠」本義是「空曠得看不到邊」，古人先有這個意思，才用來指沒有水的大片荒地。心裡空空、對事情沒感覺，就是「冷漠」。★同聲符：漠（水）／幕（巾，布幕）／墓（土，墳墓）／慕（心，羨慕）／膜（肉，薄膜）。記法：三點水的漠讀四聲。"},
  {"id": "p878", "grade": 4, "word": "棲息", "target": "棲", "zhuyin": "ㄑㄧ", "pinyin": "qī", "wz": "ㄑㄧ ㄒㄧˊ", "wrong": [{"z": "ㄑㄧˊ", "p": "qí"}, {"z": "ㄒㄧ", "p": "xī"}], "note": "「棲息」「棲身」的「棲」讀ㄑㄧ（一聲）。", "deep": "1. 注音比較\n棲：ㄑㄧ（一聲）＝棲息、棲身、兩棲、棲地。誤讀ㄑㄧˊ＝與「奇」「其」相混；誤讀ㄒㄧ＝ㄑ、ㄒ不分\n2. 國字拆解與造字原因\n棲：形聲字，「木」＋「妻」（聲）。從木部——本義是鳥停在樹上休息，引申成一切生物居住的地方（棲地）。★「兩棲動物」像青蛙，小時候在水裡、長大能上陸地，兩邊都能待。記法：木字旁的棲讀一聲ㄑㄧ。"},
  {"id": "p879", "grade": 4, "word": "遷徙", "target": "徙", "zhuyin": "ㄒㄧˇ", "pinyin": "xǐ", "wz": "ㄑㄧㄢ ㄒㄧˇ", "wrong": [{"z": "ㄊㄨˊ", "p": "tú"}, {"z": "ㄒㄧ", "p": "xī"}], "note": "「遷徙」的「徙」讀ㄒㄧˇ（三聲）；不要跟「徒」（ㄊㄨˊ）看混。", "deep": "1. 注音比較\n徙：ㄒㄧˇ（三聲）＝遷徙、徙居。★「徒」（ㄊㄨˊ）是徒步、學徒，右邊是「走」；「徙」右邊是「止」加「少」，兩個字很像但不同。誤讀ㄒㄧ＝少了聲調\n2. 國字拆解與造字原因\n徙：從「彳」（走路），本義是搬移、遷居。★動物為了找食物或適合的氣候，季節性地長距離移動，就叫「遷徙」——像候鳥每年南北往返。記法：彳字旁、右邊有「止」的徙讀ㄒㄧˇ。"},
  {"id": "p880", "grade": 4, "word": "繁殖", "target": "殖", "zhuyin": "ㄓˊ", "pinyin": "zhí", "wz": "ㄈㄢˊ ㄓˊ", "wrong": [{"z": "ㄓˋ", "p": "zhì"}, {"z": "ㄓˇ", "p": "zhǐ"}], "note": "「繁殖」「養殖」的「殖」讀ㄓˊ（二聲）。", "deep": "1. 注音比較\n殖：ㄓˊ（二聲）＝繁殖、養殖、殖民。誤讀ㄓˋ＝與「值」的另一音或「志」相混；誤讀ㄓˇ＝與「只」「指」相混\n2. 國字拆解與造字原因\n殖：形聲字，「歹」＋「直」（聲）。「歹」（ㄉㄞˇ）本來是殘骨的樣子，但「殖」引申為生長、增多。★生物產生下一代叫「繁殖」；靠受精產生下一代叫有性生殖，直接由母體分出來的（像插枝、分株）叫無性生殖。記法：殖讀二聲ㄓˊ。"},
  {"id": "p881", "grade": 4, "word": "孵化", "target": "孵", "zhuyin": "ㄈㄨ", "pinyin": "fū", "wz": "ㄈㄨ ㄏㄨㄚˋ", "wrong": [{"z": "ㄈㄨˇ", "p": "fǔ"}, {"z": "ㄌㄨㄢˇ", "p": "luǎn"}], "note": "「孵化」「孵蛋」的「孵」讀ㄈㄨ（一聲）。", "deep": "1. 注音比較\n孵：ㄈㄨ（一聲）＝孵化、孵蛋、孵育。誤讀ㄈㄨˇ＝與「腐」「府」相混；誤讀ㄌㄨㄢˇ＝與「卵」相混\n2. 國字拆解與造字原因\n孵：會意字，左邊是「卵」（蛋），右邊是「孚」（用爪護著小孩），合起來就是親鳥用身體覆著蛋，讓小生命長出來。★不同動物孵化需要的時間差很多：雞約 21 天，鴨約 28 天。記法：有「卵」的孵讀一聲ㄈㄨ。"},
  {"id": "p882", "grade": 4, "word": "幼蟲", "target": "幼", "zhuyin": "ㄧㄡˋ", "pinyin": "yòu", "wz": "ㄧㄡˋ ㄔㄨㄥˊ", "wrong": [{"z": "ㄧㄡˇ", "p": "yǒu"}, {"z": "ㄩˋ", "p": "yù"}], "note": "「幼蟲」「幼稚」的「幼」讀ㄧㄡˋ（四聲）。", "deep": "1. 注音比較\n幼：ㄧㄡˋ（四聲）＝幼蟲、幼稚、年幼、扶老攜幼。誤讀ㄧㄡˇ＝與「有」「友」相混；誤讀ㄩˋ＝與「育」相混\n2. 國字拆解與造字原因\n幼：會意字，「幺」（細小的絲）＋「力」，力氣還很小，所以是年紀小。★昆蟲從卵孵出來後的樣子叫「幼蟲」；完全變態的昆蟲（如蝴蝶）要經過卵→幼蟲→蛹→成蟲四個階段。記法：幼讀四聲ㄧㄡˋ。"},
  {"id": "p883", "grade": 4, "word": "昆蟲", "target": "昆", "zhuyin": "ㄎㄨㄣ", "pinyin": "kūn", "wz": "ㄎㄨㄣ ㄔㄨㄥˊ", "wrong": [{"z": "ㄎㄨㄣˋ", "p": "kùn"}, {"z": "ㄏㄨㄣˊ", "p": "hún"}], "note": "「昆蟲」「昆布」的「昆」讀ㄎㄨㄣ（一聲）。", "deep": "1. 注音比較\n昆：ㄎㄨㄣ（一聲）＝昆蟲、昆布、昆仲。誤讀ㄎㄨㄣˋ＝與「困」相混；誤讀ㄏㄨㄣˊ＝與「魂」相混\n2. 國字拆解與造字原因\n昆：會意字，上面是「日」、下面是「比」（兩人並排），本義是「眾多」——蟲類數量最多，所以叫「昆蟲」。★昆蟲的共同特徵：身體分頭、胸、腹三段，胸部有六隻腳，多半有一或兩對翅膀。蜘蛛八隻腳，所以不是昆蟲。記法：昆讀一聲ㄎㄨㄣ。"},
  {"id": "p884", "grade": 4, "word": "觸角", "target": "觸", "zhuyin": "ㄔㄨˋ", "pinyin": "chù", "wz": "ㄔㄨˋ ㄐㄧㄠˇ", "wrong": [{"z": "ㄔㄨ", "p": "chū"}, {"z": "ㄗㄨˊ", "p": "zú"}], "note": "「觸角」「接觸」的「觸」讀ㄔㄨˋ（四聲）。", "deep": "1. 注音比較\n觸：ㄔㄨˋ（四聲）＝觸角、接觸、觸摸、觸類旁通。誤讀ㄔㄨ＝與「出」「初」相混；誤讀ㄗㄨˊ＝把右邊的「蜀」看錯\n2. 國字拆解與造字原因\n觸：形聲字，「角」＋「蜀」（聲）。從角部——本義是動物用角去頂，引申成「碰到」。★昆蟲的觸角是重要的感覺器官，可以聞氣味、感覺震動和風向，不只是拿來碰東西。★「觸類旁通」是說懂了一件事，同類的其他事情也跟著明白。記法：角字旁的觸讀四聲。"},
  {"id": "p885", "grade": 4, "word": "翅膀", "target": "翅", "zhuyin": "ㄔˋ", "pinyin": "chì", "wz": "ㄔˋ ㄅㄤˇ", "wrong": [{"z": "ㄔˇ", "p": "chǐ"}, {"z": "ㄓˋ", "p": "zhì"}], "note": "「翅膀」的「翅」讀ㄔˋ（四聲）。", "deep": "1. 注音比較\n翅：ㄔˋ（四聲）＝翅膀、魚翅、插翅難飛。誤讀ㄔˇ＝與「齒」「尺」相混；誤讀ㄓˋ＝把右上的「支」看錯\n2. 國字拆解與造字原因\n翅：形聲字，「羽」＋「支」（聲）。從羽部表示跟羽毛有關。★鳥的翅膀上面拱、下面平，飛的時候上面的空氣走得比較快、壓力比較小，就把鳥往上托——飛機的機翼也是照這個道理做的。★「插翅難飛」是說連翅膀都插上了也飛不掉，形容被困住。記法：羽字旁的翅讀四聲。"},
  {"id": "p886", "grade": 4, "word": "脊椎", "target": "脊", "zhuyin": "ㄐㄧˇ", "pinyin": "jǐ", "wz": "ㄐㄧˇ ㄓㄨㄟ", "wrong": [{"z": "ㄐㄧˊ", "p": "jí"}, {"z": "ㄗㄟˊ", "p": "zéi"}], "note": "「脊椎」「脊背」的「脊」讀ㄐㄧˇ（三聲）。", "deep": "1. 注音比較\n脊：ㄐㄧˇ（三聲）＝脊椎、脊背、山脊、脊梁。誤讀ㄐㄧˊ＝與「急」「集」相混；誤讀ㄗㄟˊ＝與「賊」相混\n2. 國字拆解與造字原因\n脊：會意字，上面畫背骨兩邊分出的肋骨，下面是「肉（月）」，本義就是背脊骨。★有脊椎骨的動物叫「脊椎動物」（魚、兩棲、爬蟲、鳥、哺乳五大類）；昆蟲、蝦蟹沒有脊椎，是「無脊椎動物」。★「山脊」是山最高處連成的一條線，形狀像背脊。記法：下面是肉月的脊讀三聲。"},
  {"id": "p887", "grade": 4, "word": "哺乳", "target": "哺", "zhuyin": "ㄅㄨˇ", "pinyin": "bǔ", "wz": "ㄅㄨˇ ㄖㄨˇ", "wrong": [{"z": "ㄅㄨˋ", "p": "bù"}, {"z": "ㄆㄨˇ", "p": "pǔ"}], "note": "「哺乳」「哺育」的「哺」讀ㄅㄨˇ（三聲）。", "deep": "1. 注音比較\n哺：ㄅㄨˇ（三聲）＝哺乳、哺育、嗷嗷待哺、反哺。誤讀ㄅㄨˋ＝與「不」「布」相混；誤讀ㄆㄨˇ＝ㄅ、ㄆ不分\n2. 國字拆解與造字原因\n哺：形聲字，「口」＋「甫」（聲）。從口部——本義是把食物餵進嘴裡。★「哺乳動物」的特徵是母親會分泌乳汁餵小孩，身上有毛、體溫恆定。鯨和蝙蝠雖然一個在海裡、一個會飛，都是哺乳動物。★「烏鴉反哺」是說小烏鴉長大後餵母親，比喻報答父母。記法：口字旁的哺讀三聲。"},
  {"id": "p888", "grade": 4, "word": "魚鰓", "target": "鰓", "zhuyin": "ㄙㄞ", "pinyin": "sāi", "wz": "ㄩˊ ㄙㄞ", "wrong": [{"z": "ㄙㄞˋ", "p": "sài"}, {"z": "ㄙˇ", "p": "sǐ"}], "note": "「魚鰓」的「鰓」讀ㄙㄞ（一聲）。", "deep": "1. 注音比較\n鰓：ㄙㄞ（一聲）＝魚鰓、鰓蓋。誤讀ㄙㄞˋ＝與「賽」相混；誤讀ㄙˇ＝把右邊的「思」看成別的字\n2. 國字拆解與造字原因\n鰓：形聲字，「魚」＋「思」（聲）。從魚部表示是魚身上的器官。★魚用鰓呼吸：水從嘴巴進來，通過鰓時，鰓上密密的血管把水裡的氧氣換進血液，再從鰓蓋後面流出去。所以魚離開水不是缺水，是鰓片黏在一起無法換氣。記法：魚字旁的鰓讀一聲ㄙㄞ。"},
  {"id": "p889", "grade": 5, "word": "汗流浹背", "target": "浹", "zhuyin": "ㄐㄧㄚˊ", "pinyin": "jiá", "wz": "ㄏㄢˋ ㄌㄧㄡˊ ㄐㄧㄚˊ ㄅㄟˋ", "wrong": [{"z": "ㄐㄧㄚ", "p": "jiā"}, {"z": "ㄑㄧㄝˋ", "p": "qiè"}], "note": "「汗流浹背」的「浹」讀ㄐㄧㄚˊ（二聲），是「溼透」的意思。", "deep": "1. 注音比較\n浹：ㄐㄧㄚˊ（二聲）＝汗流浹背、浹洽。誤讀ㄐㄧㄚ＝少了聲調（跟「加」「夾」相混）；誤讀ㄑㄧㄝˋ＝與「愜」相混\n2. 國字拆解與造字原因\n浹：形聲字，「水（氵）」＋「夾」（聲）。從水部——本義是溼透、浸遍。「汗流浹背」是汗流到把整個背都溼透了，形容非常辛苦或非常惶恐，不是單純「流很多汗」。記法：三點水的浹讀二聲。"},
  {"id": "p890", "grade": 5, "word": "強迫", "target": "迫", "zhuyin": "ㄆㄛˋ", "pinyin": "pò", "wz": "ㄑㄧㄤˇ ㄆㄛˋ", "wrong": [{"z": "ㄆㄞˇ", "p": "pǎi"}, {"z": "ㄅㄛˊ", "p": "bó"}], "note": "「強迫」「迫切」讀ㄆㄛˋ；只有「迫擊砲」讀ㄆㄞˇ。「強迫」的「強」讀ㄑㄧㄤˇ。", "deep": "1. 注音比較\n迫：ㄆㄛˋ（四聲）＝強迫、迫切、壓迫、迫不及待；ㄆㄞˇ（三聲）＝迫擊砲（一種火砲）。誤讀ㄅㄛˊ＝與「泊」相混\n2. 國字拆解與造字原因\n迫：形聲字，「辵（辶）」＋「白」（聲）。從辵部跟走動有關，本義是逼近——逼到很近就是「壓迫、強迫」。★「強迫」的「強」讀ㄑㄧㄤˇ（勉強的強），不是「強壯」的ㄑㄧㄤˊ。記法：只有「迫擊砲」讀ㄆㄞˇ。"},
  {"id": "p891", "grade": 5, "word": "好整以暇", "target": "暇", "zhuyin": "ㄒㄧㄚˊ", "pinyin": "xiá", "wz": "ㄏㄠˋ ㄓㄥˇ ㄧˇ ㄒㄧㄚˊ", "wrong": [{"z": "ㄒㄧㄚ", "p": "xiā"}, {"z": "ㄒㄧㄚˋ", "p": "xià"}], "note": "「好整以暇」「閒暇」的「暇」讀ㄒㄧㄚˊ（二聲）；這裡的「好」讀ㄏㄠˋ。", "deep": "1. 注音比較\n暇：ㄒㄧㄚˊ（二聲）＝閒暇、暇日、應接不暇、目不暇給。誤讀ㄒㄧㄚ＝少了聲調；誤讀ㄒㄧㄚˋ＝與「下」「夏」相混\n2. 國字拆解與造字原因\n暇：形聲字，「日」＋「叚」（聲）。從日部——本義是空閒的日子、空出來的時間。★三個同聲符的字要分：暇（日，空閒）／瑕（玉，玉上的斑點，瑕疵）／遐（辶，遠，遐想）。★「好整以暇」的「好」讀四聲（喜好），整句是說事情再忙也能整齊從容。記法：日字旁的暇讀二聲。"},
  {"id": "p892", "grade": 5, "word": "落實", "target": "落", "zhuyin": "ㄌㄨㄛˋ", "pinyin": "luò", "wz": "ㄌㄨㄛˋ ㄕˊ", "wrong": [{"z": "ㄌㄚˋ", "p": "là"}, {"z": "ㄌㄠˋ", "p": "lào"}], "note": "「落實」「落葉」讀ㄌㄨㄛˋ；「丟三落四」讀ㄌㄚˋ；「落枕」讀ㄌㄠˋ。", "deep": "1. 注音比較\n落：ㄌㄨㄛˋ（四聲）＝落實、落葉、降落、部落（最常用的讀書音）；ㄌㄚˋ（四聲）＝丟三落四、落下東西（遺漏，口語）；ㄌㄠˋ（四聲）＝落枕、落色（口語音）\n2. 國字拆解與造字原因\n落：形聲字，「艸（艹）」＋「洛」（聲）。本義是草木的葉子掉下來，引申成一切往下掉、安頓下來的意思——事情安頓妥當就是「落實」。★三個音只能靠詞分：讀書音ㄌㄨㄛˋ，遺漏ㄌㄚˋ，落枕ㄌㄠˋ。記法：一般用法讀ㄌㄨㄛˋ。"},
  {"id": "p893", "grade": 5, "word": "差遣", "target": "遣", "zhuyin": "ㄑㄧㄢˇ", "pinyin": "qiǎn", "wz": "ㄔㄞ ㄑㄧㄢˇ", "wrong": [{"z": "ㄑㄧㄢˋ", "p": "qiàn"}, {"z": "ㄒㄧㄢˇ", "p": "xiǎn"}], "note": "「差遣」「派遣」的「遣」讀ㄑㄧㄢˇ（三聲）；這裡的「差」讀ㄔㄞ。", "deep": "1. 注音比較\n遣：ㄑㄧㄢˇ（三聲）＝差遣、派遣、遣送、消遣。誤讀ㄑㄧㄢˋ＝與「欠」相混；誤讀ㄒㄧㄢˇ＝聲母看錯\n2. 國字拆解與造字原因\n遣：形聲字，從「辵（辶）」，跟走動有關，本義是把人打發出去做事。★「差遣」的「差」讀ㄔㄞ（出差的差）；「消遣」是把時間打發掉。★注意「遣」和「遺」（ㄧˊ，遺失）字形相近，中間不同。記法：走之旁的遣讀三聲。"},
  {"id": "p894", "grade": 5, "word": "蹊蹺", "target": "蹺", "zhuyin": "ㄑㄧㄠ", "pinyin": "qiāo", "wz": "ㄒㄧ ㄑㄧㄠ", "wrong": [{"z": "ㄑㄧㄠˊ", "p": "qiáo"}, {"z": "ㄧㄠˊ", "p": "yáo"}], "note": "「蹊蹺」讀ㄒㄧ ㄑㄧㄠ，是「奇怪、可疑」的意思。", "deep": "1. 注音比較\n蹺：ㄑㄧㄠ（一聲）＝蹊蹺、蹺課、蹺蹺板、蹺腳。誤讀ㄑㄧㄠˊ＝與「橋」「僑」相混；誤讀ㄧㄠˊ＝把右邊的「堯」直接讀出來\n2. 國字拆解與造字原因\n蹺：形聲字，「足（𧾷）」＋「堯」（聲）。從足部表示跟腳有關，本義是把腳抬高。★「蹊」在「蹊蹺」裡讀ㄒㄧ（一聲）；在「桃李不言，下自成蹊」裡也讀ㄒㄧ，指小路。★「事有蹊蹺」是說事情不太對勁。記法：足字旁的蹺讀一聲ㄑㄧㄠ。"},
  {"id": "p895", "grade": 5, "word": "鏗鏘", "target": "鏗", "zhuyin": "ㄎㄥ", "pinyin": "kēng", "wz": "ㄎㄥ ㄑㄧㄤ", "wrong": [{"z": "ㄐㄧㄢ", "p": "jiān"}, {"z": "ㄎㄣ", "p": "kēn"}], "note": "「鏗鏘有力」的「鏗」讀ㄎㄥ（一聲）。", "deep": "1. 注音比較\n鏗：ㄎㄥ（一聲）＝鏗鏘、鏗鏘有力、鏗然。誤讀ㄐㄧㄢ＝把右邊的「堅」直接讀出來；誤讀ㄎㄣ＝ㄥ、ㄣ不分\n2. 國字拆解與造字原因\n鏗：形聲字，「金」＋「堅」（聲）。從金部——本義是金屬互相撞擊發出的清脆響聲。「鏘」也是金字旁。★「鏗鏘有力」形容說話或文章節奏分明、很有力量，像敲金屬一樣清脆。記法：金字旁的鏗讀一聲ㄎㄥ。"},
  {"id": "p896", "grade": 5, "word": "恫嚇", "target": "恫", "zhuyin": "ㄉㄨㄥˋ", "pinyin": "dòng", "wz": "ㄉㄨㄥˋ ㄏㄜˋ", "wrong": [{"z": "ㄊㄨㄥˊ", "p": "tóng"}, {"z": "ㄉㄨㄥ", "p": "dōng"}], "note": "「恫嚇」讀ㄉㄨㄥˋ ㄏㄜˋ，是「用威嚇的手段使人害怕」。", "deep": "1. 注音比較\n恫：ㄉㄨㄥˋ（四聲）＝恫嚇；ㄊㄨㄥ（一聲）＝恫瘝在抱（把人民的疾苦放在心上）。誤讀ㄉㄨㄥ＝少了聲調\n2. 國字拆解與造字原因\n恫：形聲字，「心（忄）」＋「同」（聲）。★「嚇」是多音字：恫嚇、威嚇讀ㄏㄜˋ（四聲）；「嚇一跳」「嚇死人」讀ㄒㄧㄚˋ。這一題兩個字都容易念錯。記法：恫嚇讀ㄉㄨㄥˋ ㄏㄜˋ。"},
  {"id": "p897", "grade": 5, "word": "揮霍", "target": "霍", "zhuyin": "ㄏㄨㄛˋ", "pinyin": "huò", "wz": "ㄏㄨㄟ ㄏㄨㄛˋ", "wrong": [{"z": "ㄏㄨㄛ", "p": "huō"}, {"z": "ㄏㄨㄛˊ", "p": "huó"}], "note": "「揮霍」「霍亂」的「霍」讀ㄏㄨㄛˋ（四聲）。", "deep": "1. 注音比較\n霍：ㄏㄨㄛˋ（四聲）＝揮霍、霍亂、霍然而癒。誤讀ㄏㄨㄛ＝少了聲調；誤讀ㄏㄨㄛˊ＝與「活」相混\n2. 國字拆解與造字原因\n霍：會意字，上面是「雨」，下面是「隹」（鳥），畫的是鳥在雨中急急飛起，本義是「快、突然」——所以「霍然而癒」是病忽然就好了。花錢花得又快又多，就是「揮霍」。記法：雨字頭下面有鳥的霍讀四聲。"},
  {"id": "p898", "grade": 5, "word": "詼諧", "target": "詼", "zhuyin": "ㄏㄨㄟ", "pinyin": "huī", "wz": "ㄏㄨㄟ ㄒㄧㄝˊ", "wrong": [{"z": "ㄏㄨㄟˊ", "p": "huí"}, {"z": "ㄏㄨㄟˇ", "p": "huǐ"}], "note": "「詼諧」的「詼」讀ㄏㄨㄟ（一聲）。", "deep": "1. 注音比較\n詼：ㄏㄨㄟ（一聲）＝詼諧。誤讀ㄏㄨㄟˊ＝與「回」相混；誤讀ㄏㄨㄟˇ＝與「毀」相混\n2. 國字拆解與造字原因\n詼：形聲字，「言」＋「灰」（聲）。從言部表示跟說話有關。「諧」也是言字旁，本義是「和諧」，引申為風趣。「詼諧」就是說話幽默有趣，讓人覺得舒服。★「詼諧」和「滑稽」（ㄏㄨㄚˊ ㄐㄧ）意思相近，都是有趣好笑。記法：言字旁的詼讀一聲。"},
  {"id": "p899", "grade": 5, "word": "荒謬", "target": "謬", "zhuyin": "ㄇㄧㄡˋ", "pinyin": "miù", "wz": "ㄏㄨㄤ ㄇㄧㄡˋ", "wrong": [{"z": "ㄌㄧㄠˋ", "p": "liào"}, {"z": "ㄇㄧㄡˇ", "p": "miǔ"}], "note": "「荒謬」「謬論」的「謬」讀ㄇㄧㄡˋ（四聲）。", "deep": "1. 注音比較\n謬：ㄇㄧㄡˋ（四聲）＝荒謬、謬論、謬誤、失之毫釐，謬以千里。誤讀ㄌㄧㄠˋ＝把右邊的「翏」看成「廖」；誤讀ㄇㄧㄡˇ＝聲調錯\n2. 國字拆解與造字原因\n謬：形聲字，「言」＋「翏」（聲）。從言部——本義是說法錯得離譜。★「失之毫釐，謬以千里」是說開頭只差一點點，結果就差了一千里，提醒人小地方也不能錯。記法：言字旁的謬讀四聲。"},
  {"id": "p900", "grade": 5, "word": "蹂躪", "target": "躪", "zhuyin": "ㄌㄧㄣˋ", "pinyin": "lìn", "wz": "ㄖㄡˊ ㄌㄧㄣˋ", "wrong": [{"z": "ㄌㄧㄣˊ", "p": "lín"}, {"z": "ㄌㄢˋ", "p": "làn"}], "note": "「蹂躪」的「躪」讀ㄌㄧㄣˋ（四聲）。", "deep": "1. 注音比較\n躪：ㄌㄧㄣˋ（四聲）＝蹂躪。誤讀ㄌㄧㄣˊ＝與「鄰」「林」相混；誤讀ㄌㄢˋ＝與「爛」相混\n2. 國字拆解與造字原因\n躪：形聲字，「足（𧾷）」＋「藺」（聲）。「蹂」也是足字旁——兩個字都跟腳有關，本義是用腳踐踏，引申成用暴力摧殘。★「蹂躪」是很重的詞，用在受到嚴重破壞、傷害的場合。記法：足字旁的躪讀四聲。"},
  {"id": "p901", "grade": 5, "word": "鍥而不捨", "target": "鍥", "zhuyin": "ㄑㄧㄝˋ", "pinyin": "qiè", "wz": "ㄑㄧㄝˋ ㄦˊ ㄅㄨˋ ㄕㄜˇ", "wrong": [{"z": "ㄑㄧˋ", "p": "qì"}, {"z": "ㄐㄧㄝˊ", "p": "jié"}], "note": "「鍥而不捨」的「鍥」讀ㄑㄧㄝˋ（四聲）。", "deep": "1. 注音比較\n鍥：ㄑㄧㄝˋ（四聲）＝鍥而不捨。誤讀ㄑㄧˋ＝與「契」相混；誤讀ㄐㄧㄝˊ＝與「潔」相混\n2. 國字拆解與造字原因\n鍥：形聲字，「金」＋「契」（聲）。從金部——本義是用刀子刻。★「鍥而不捨」出自《荀子．勸學》：「鍥而舍之，朽木不折；鍥而不捨，金石可鏤。」意思是刻東西如果中途放棄，連朽木都刻不斷；一直刻下去不放棄，連金屬石頭都刻得穿。記法：金字旁的鍥讀四聲。"},
  {"id": "p902", "grade": 5, "word": "淋漓", "target": "漓", "zhuyin": "ㄌㄧˊ", "pinyin": "lí", "wz": "ㄌㄧㄣˊ ㄌㄧˊ", "wrong": [{"z": "ㄌㄧˇ", "p": "lǐ"}, {"z": "ㄌㄧˋ", "p": "lì"}], "note": "「淋漓盡致」的「漓」讀ㄌㄧˊ（二聲）。", "deep": "1. 注音比較\n漓：ㄌㄧˊ（二聲）＝淋漓、淋漓盡致、大汗淋漓。誤讀ㄌㄧˇ＝與「李」「裡」相混；誤讀ㄌㄧˋ＝與「利」相混\n2. 國字拆解與造字原因\n漓：形聲字，「水（氵）」＋「离」（聲）。「淋」「漓」兩個字都是三點水，本義是水一直往下滴、溼淋淋的樣子。★「淋漓盡致」是說表達得非常透澈、一點不留——本來是形容墨水流得暢快。記法：三點水的漓讀二聲。"},
  {"id": "p903", "grade": 5, "word": "徬徨", "target": "徬", "zhuyin": "ㄆㄤˊ", "pinyin": "páng", "wz": "ㄆㄤˊ ㄏㄨㄤˊ", "wrong": [{"z": "ㄅㄤˋ", "p": "bàng"}, {"z": "ㄆㄤ", "p": "pāng"}], "note": "「徬徨」的「徬」讀ㄆㄤˊ（二聲）。", "deep": "1. 注音比較\n徬：ㄆㄤˊ（二聲）＝徬徨。★「傍」（ㄅㄤˋ，人字旁）是傍晚、依傍，跟「徬」是兩個字。誤讀ㄆㄤ＝少了聲調（跟「乓」相混）\n2. 國字拆解與造字原因\n徬：形聲字，「彳」＋「旁」（聲）。「彳」跟走路有關——「徬徨」兩個字都是彳字旁，指走來走去拿不定主意，引申成心裡猶豫不安。★分辨：徬（彳，徬徨）／傍（亻，傍晚）／磅（石，磅秤）／膀（肉，肩膀）。記法：彳字旁的徬讀二聲。"},
  {"id": "p904", "grade": 5, "word": "蕭瑟", "target": "瑟", "zhuyin": "ㄙㄜˋ", "pinyin": "sè", "wz": "ㄒㄧㄠ ㄙㄜˋ", "wrong": [{"z": "ㄙㄜ", "p": "sē"}, {"z": "ㄅㄧˋ", "p": "bì"}], "note": "「蕭瑟」的「瑟」讀ㄙㄜˋ（四聲）。", "deep": "1. 注音比較\n瑟：ㄙㄜˋ（四聲）＝蕭瑟、琴瑟和鳴、瑟縮。誤讀ㄙㄜ＝少了聲調；誤讀ㄅㄧˋ＝把上面的兩個「王」看成別的字\n2. 國字拆解與造字原因\n瑟：象形兼形聲，上面兩個「王」其實是「玨」，畫的是弦樂器的弦。「瑟」本來是一種二十五弦的古樂器。★「琴瑟和鳴」比喻夫妻感情和睦，因為琴和瑟合奏起來聲音相配。★秋風吹得樹葉沙沙響、景色淒涼，就叫「蕭瑟」。記法：瑟讀四聲ㄙㄜˋ。"},
  {"id": "p905", "grade": 5, "word": "頹廢", "target": "頹", "zhuyin": "ㄊㄨㄟˊ", "pinyin": "tuí", "wz": "ㄊㄨㄟˊ ㄈㄟˋ", "wrong": [{"z": "ㄊㄨㄟ", "p": "tuī"}, {"z": "ㄊㄨㄟˋ", "p": "tuì"}], "note": "「頹廢」「頹喪」的「頹」讀ㄊㄨㄟˊ（二聲）。", "deep": "1. 注音比較\n頹：ㄊㄨㄟˊ（二聲）＝頹廢、頹喪、頹圮、斷垣頹壁。誤讀ㄊㄨㄟ＝少了聲調（跟「推」相混）；誤讀ㄊㄨㄟˋ＝與「退」「蛻」相混\n2. 國字拆解與造字原因\n頹：形聲字，右邊是「頁」（頭）。從頁部本來指頭禿，引申成「倒塌、衰敗」——房子倒了叫「頹圮」，精神垮了叫「頹廢」。記法：右邊是頁的頹讀二聲。"},
  {"id": "p906", "grade": 5, "word": "慷慨", "target": "慨", "zhuyin": "ㄎㄞˇ", "pinyin": "kǎi", "wz": "ㄎㄤ ㄎㄞˇ", "wrong": [{"z": "ㄎㄞˋ", "p": "kài"}, {"z": "ㄐㄧˋ", "p": "jì"}], "note": "「慷慨」「感慨」的「慨」讀ㄎㄞˇ（三聲）。", "deep": "1. 注音比較\n慨：ㄎㄞˇ（三聲）＝慷慨、感慨、慨嘆、慷慨激昂。誤讀ㄎㄞˋ＝聲調錯；誤讀ㄐㄧˋ＝把右邊的「既」直接讀出來\n2. 國字拆解與造字原因\n慨：形聲字，「心（忄）」＋「既」（聲）。「慷」也是豎心旁——兩個字都跟心情有關。本義是情緒激動、心裡不平，引申出兩個常用意思：情緒激昂（慷慨激昂）、出手大方（慷慨解囊）。記法：豎心旁的慨讀三聲。"},
  {"id": "p907", "grade": 5, "word": "譬如", "target": "譬", "zhuyin": "ㄆㄧˋ", "pinyin": "pì", "wz": "ㄆㄧˋ ㄖㄨˊ", "wrong": [{"z": "ㄅㄧˋ", "p": "bì"}, {"z": "ㄆㄧˊ", "p": "pí"}], "note": "「譬如」「譬喻」的「譬」讀ㄆㄧˋ（四聲）。", "deep": "1. 注音比較\n譬：ㄆㄧˋ（四聲）＝譬如、譬喻。誤讀ㄅㄧˋ＝把上面的「辟」讀成ㄅㄧˋ；誤讀ㄆㄧˊ＝與「皮」「疲」相混\n2. 國字拆解與造字原因\n譬：形聲字，下面是「言」，本義是「打比方說明」。★「譬喻」就是修辭法裡的比喻：用大家熟悉的東西來說明比較陌生的道理，例如「時間像流水」。★「辟」本身是多音字（復辟ㄅㄧˋ、闢ㄆㄧˋ），但「譬」固定讀ㄆㄧˋ。記法：下面是言的譬讀四聲ㄆㄧˋ。"},
  {"id": "p908", "grade": 5, "word": "詢問", "target": "詢", "zhuyin": "ㄒㄩㄣˊ", "pinyin": "xún", "wz": "ㄒㄩㄣˊ ㄨㄣˋ", "wrong": [{"z": "ㄒㄩㄣˇ", "p": "xǔn"}, {"z": "ㄒㄩㄥˊ", "p": "xióng"}], "note": "「詢問」「諮詢」的「詢」讀ㄒㄩㄣˊ（二聲）。", "deep": "1. 注音比較\n詢：ㄒㄩㄣˊ（二聲）＝詢問、諮詢、探詢。誤讀ㄒㄩㄣˇ＝與「選」的變化相混；誤讀ㄒㄩㄥˊ＝ㄣ、ㄥ不分\n2. 國字拆解與造字原因\n詢：形聲字，「言」＋「旬」（聲）。從言部表示要開口問。★三個同聲符的字：詢（言，詢問）／殉（歹，殉職）／恂（心）。★「諮詢」是向專業的人請教意見。記法：言字旁的詢讀二聲，注意是ㄣ不是ㄥ。"},
  {"id": "p909", "grade": 5, "word": "醞釀", "target": "醞", "zhuyin": "ㄩㄣˋ", "pinyin": "yùn", "wz": "ㄩㄣˋ ㄋㄧㄤˋ", "wrong": [{"z": "ㄨㄣ", "p": "wēn"}, {"z": "ㄩㄣˊ", "p": "yún"}], "note": "「醞釀」的「醞」讀ㄩㄣˋ（四聲）。", "deep": "1. 注音比較\n醞：ㄩㄣˋ（四聲）＝醞釀。誤讀ㄨㄣ＝與「溫」相混（少了ㄩ的圓唇）；誤讀ㄩㄣˊ＝與「雲」「勻」相混\n2. 國字拆解與造字原因\n醞：形聲字，「酉」＋「昷」（聲）。「酉」是酒罈子的樣子，凡是從酉部的字多半跟酒或發酵有關（像「酒」「酸」「醋」「醬」「酵」）。「醞釀」本義是釀酒——把材料放著慢慢發酵，引申成事情在暗中逐漸形成（醞釀已久）。記法：酉字旁的醞讀四聲。"},
  {"id": "p910", "grade": 5, "word": "斟酌", "target": "斟", "zhuyin": "ㄓㄣ", "pinyin": "zhēn", "wz": "ㄓㄣ ㄓㄨㄛˊ", "wrong": [{"z": "ㄕㄣˊ", "p": "shén"}, {"z": "ㄓㄣˋ", "p": "zhèn"}], "note": "「斟酌」的「斟」讀ㄓㄣ（一聲）。", "deep": "1. 注音比較\n斟：ㄓㄣ（一聲）＝斟酌、斟茶、字斟句酌。誤讀ㄕㄣˊ＝把左邊的「甚」直接讀出來；誤讀ㄓㄣˋ＝與「振」「震」相混\n2. 國字拆解與造字原因\n斟：形聲字，「斗」＋「甚」（聲）。「斗」是量東西的杓子——本義是拿杓子舀酒倒進杯裡，要倒得剛剛好，所以引申成「仔細衡量」。「酌」也是倒酒的意思（酉字旁）。★「字斟句酌」是說每個字每句話都仔細推敲。記法：斗字旁的斟讀一聲。"},
  {"id": "p911", "grade": 5, "word": "蘊含", "target": "蘊", "zhuyin": "ㄩㄣˋ", "pinyin": "yùn", "wz": "ㄩㄣˋ ㄏㄢˊ", "wrong": [{"z": "ㄨㄣ", "p": "wēn"}, {"z": "ㄩㄣ", "p": "yūn"}], "note": "「蘊含」「蘊藏」的「蘊」讀ㄩㄣˋ（四聲）。", "deep": "1. 注音比較\n蘊：ㄩㄣˋ（四聲）＝蘊含、蘊藏、意蘊、底蘊。誤讀ㄨㄣ＝與「溫」相混；誤讀ㄩㄣ＝少了聲調（跟「暈」的一聲相混）\n2. 國字拆解與造字原因\n蘊：形聲字，「艸（艹）」＋「縕」（聲）。本義是積聚、收藏在裡面。★「蘊含」是裡面含有；「底蘊」是內在的深厚基礎。★注意「蘊」（艹頭，蘊含）和「醞」（酉旁，醞釀）讀音一樣、意思不同。記法：草字頭的蘊讀四聲。"},
  {"id": "p912", "grade": 5, "word": "隱瞞", "target": "瞞", "zhuyin": "ㄇㄢˊ", "pinyin": "mán", "wz": "ㄧㄣˇ ㄇㄢˊ", "wrong": [{"z": "ㄇㄢˇ", "p": "mǎn"}, {"z": "ㄇㄢˋ", "p": "màn"}], "note": "「隱瞞」「欺瞞」的「瞞」讀ㄇㄢˊ（二聲）。", "deep": "1. 注音比較\n瞞：ㄇㄢˊ（二聲）＝隱瞞、欺瞞、瞞天過海。誤讀ㄇㄢˇ＝與「滿」相混；誤讀ㄇㄢˋ＝與「慢」「漫」相混\n2. 國字拆解與造字原因\n瞞：形聲字，「目」＋「㒼」（聲）。從目部——本義是把眼睛遮住，引申成不讓人知道真相。★「瞞天過海」是三十六計之一，比喻用假象掩人耳目，暗中行事。★同聲符：瞞（目）／滿（水）／饅（食）／蹣（足，蹣跚）。記法：目字旁的瞞讀二聲。"},
  {"id": "p913", "grade": 5, "word": "屏障", "target": "障", "zhuyin": "ㄓㄤˋ", "pinyin": "zhàng", "wz": "ㄆㄧㄥˊ ㄓㄤˋ", "wrong": [{"z": "ㄓㄤ", "p": "zhāng"}, {"z": "ㄓㄤˇ", "p": "zhǎng"}], "note": "「屏障」「障礙」的「障」讀ㄓㄤˋ（四聲）；這裡的「屏」讀ㄆㄧㄥˊ。", "deep": "1. 注音比較\n障：ㄓㄤˋ（四聲）＝屏障、障礙、故障、保障。誤讀ㄓㄤ＝與「張」「章」相混；誤讀ㄓㄤˇ＝與「掌」相混\n2. 國字拆解與造字原因\n障：形聲字，左耳旁（阜，土山）＋「章」（聲）。從阜部——本義是像土山一樣擋在前面的東西。★「屏」是多音字：屏障、屏風讀ㄆㄧㄥˊ；屏息、屏除讀ㄅㄧㄥˇ；地名屏東讀ㄆㄧㄥˊ。★中央山脈是臺灣東西之間的天然屏障。記法：左耳旁的障讀四聲。"},
  {"id": "p914", "grade": 5, "word": "締造", "target": "締", "zhuyin": "ㄉㄧˋ", "pinyin": "dì", "wz": "ㄉㄧˋ ㄗㄠˋ", "wrong": [{"z": "ㄉㄧˇ", "p": "dǐ"}, {"z": "ㄊㄧˋ", "p": "tì"}], "note": "「締造」「締結」的「締」讀ㄉㄧˋ（四聲）。", "deep": "1. 注音比較\n締：ㄉㄧˋ（四聲）＝締造、締結、取締、締約。誤讀ㄉㄧˇ＝與「底」「抵」相混；誤讀ㄊㄧˋ＝把右邊的「帝」讀錯聲母\n2. 國字拆解與造字原因\n締：形聲字，「糸」＋「帝」（聲）。「糸」是絲線——本義是把繩子打結繫緊，引申成「訂立（約定）、創立」。★「取締」是依法禁止並處理違規的事，也是從「結」的意思引申來的（把事情了結）。記法：糸字旁的締讀四聲。"},
  {"id": "p915", "grade": 5, "word": "遵循", "target": "循", "zhuyin": "ㄒㄩㄣˊ", "pinyin": "xún", "wz": "ㄗㄨㄣ ㄒㄩㄣˊ", "wrong": [{"z": "ㄉㄨㄣˋ", "p": "dùn"}, {"z": "ㄒㄩㄣˇ", "p": "xǔn"}], "note": "「遵循」「循環」的「循」讀ㄒㄩㄣˊ（二聲）。", "deep": "1. 注音比較\n循：ㄒㄩㄣˊ（二聲）＝遵循、循環、循序漸進、有例可循。誤讀ㄉㄨㄣˋ＝與「盾」相混（右邊是盾）；誤讀ㄒㄩㄣˇ＝聲調錯\n2. 國字拆解與造字原因\n循：形聲字，「彳」＋「盾」（聲）。「彳」跟走路有關——本義是順著一條路走，引申成「按照、依著」。★「循序漸進」是照著次序一步一步前進，不跳過任何一段。★注意聲符「盾」讀ㄉㄨㄣˋ，但「循」讀ㄒㄩㄣˊ。記法：彳字旁的循讀二聲。"},
  {"id": "p916", "grade": 5, "word": "崎嶇", "target": "崎", "zhuyin": "ㄑㄧˊ", "pinyin": "qí", "wz": "ㄑㄧˊ ㄑㄩ", "wrong": [{"z": "ㄑㄧˋ", "p": "qì"}, {"z": "ㄐㄧ", "p": "jī"}], "note": "「崎嶇」的「崎」讀ㄑㄧˊ（二聲）；「嶇」讀ㄑㄩ（一聲）。", "deep": "1. 注音比較\n崎：ㄑㄧˊ（二聲）＝崎嶇。誤讀ㄑㄧˋ＝與「氣」相混；誤讀ㄐㄧ＝與「奇數」的奇（ㄐㄧ）相混——那是「奇」的另一個音，加了山字旁的「崎」只讀ㄑㄧˊ\n2. 國字拆解與造字原因\n崎：形聲字，「山」＋「奇」（聲）。「嶇」也是山字旁——兩個字都跟山有關，形容山路高低不平、很難走。引申成人生道路艱難（前途崎嶇）。記法：山字旁的崎讀二聲ㄑㄧˊ。"},
  {"id": "p917", "grade": 5, "word": "峻嶺", "target": "峻", "zhuyin": "ㄐㄩㄣˋ", "pinyin": "jùn", "wz": "ㄐㄩㄣˋ ㄌㄧㄥˇ", "wrong": [{"z": "ㄐㄩㄣ", "p": "jūn"}, {"z": "ㄘㄨㄣ", "p": "cūn"}], "note": "「崇山峻嶺」的「峻」讀ㄐㄩㄣˋ（四聲）。", "deep": "1. 注音比較\n峻：ㄐㄩㄣˋ（四聲）＝峻嶺、崇山峻嶺、嚴峻、險峻。誤讀ㄐㄩㄣ＝與「軍」「君」相混；誤讀ㄘㄨㄣ＝把右邊的「夋」看錯\n2. 國字拆解與造字原因\n峻：形聲字，「山」＋「夋」（聲）。從山部，本義是山又高又陡，引申成「嚴厲」（嚴峻）。★同聲符要分：峻（山，高陡）／俊（人，才貌出眾）／竣（立，完工）／浚（水，疏浚）。記法：山字旁的峻讀四聲。"},
  {"id": "p918", "grade": 5, "word": "潺潺", "target": "潺", "zhuyin": "ㄔㄢˊ", "pinyin": "chán", "wz": "ㄔㄢˊ ㄔㄢˊ", "wrong": [{"z": "ㄔㄢˇ", "p": "chǎn"}, {"z": "ㄘㄢˊ", "p": "cán"}], "note": "「流水潺潺」的「潺」讀ㄔㄢˊ（二聲）。", "deep": "1. 注音比較\n潺：ㄔㄢˊ（二聲）＝潺潺、潺湲。誤讀ㄔㄢˇ＝與「產」「鏟」相混；誤讀ㄘㄢˊ＝平舌、翹舌不分（跟「殘」相混）\n2. 國字拆解與造字原因\n潺：形聲字，「水（氵）」＋「孱」（聲）。從水部——「潺潺」是形容溪水流動的聲音，屬於「狀聲詞」（用字模仿聲音）。★同類的狀聲詞還有：淅瀝（雨聲）、颯颯（風聲）、琅琅（讀書聲）、汪汪（狗叫）。記法：三點水的潺讀二聲。"},
  {"id": "p919", "grade": 5, "word": "澎湃", "target": "湃", "zhuyin": "ㄆㄞˋ", "pinyin": "pài", "wz": "ㄆㄥ ㄆㄞˋ", "wrong": [{"z": "ㄅㄞˋ", "p": "bài"}, {"z": "ㄆㄟˋ", "p": "pèi"}], "note": "「澎湃」的「湃」讀ㄆㄞˋ（四聲）；「澎」讀ㄆㄥ（一聲）。", "deep": "1. 注音比較\n湃：ㄆㄞˋ（四聲）＝澎湃、洶湧澎湃。誤讀ㄅㄞˋ＝與「拜」相混（ㄅ、ㄆ不分）；誤讀ㄆㄟˋ＝與「配」相混\n2. 國字拆解與造字原因\n湃：形聲字，「水（氵）」＋「拜」（聲）。「澎」也是三點水——兩個字都跟水有關，形容波浪互相撞擊的巨大聲勢。★「澎湃」除了寫海浪，也用來形容心情激動（心潮澎湃）。★澎湖的「澎」也是這個字。記法：三點水的湃讀四聲ㄆㄞˋ。"},
  {"id": "p920", "grade": 5, "word": "蔚藍", "target": "蔚", "zhuyin": "ㄨㄟˋ", "pinyin": "wèi", "wz": "ㄨㄟˋ ㄌㄢˊ", "wrong": [{"z": "ㄩˋ", "p": "yù"}, {"z": "ㄨㄟˇ", "p": "wěi"}], "note": "「蔚藍」「蔚為風氣」讀ㄨㄟˋ；姓氏「蔚」讀ㄩˋ。", "deep": "1. 注音比較\n蔚：ㄨㄟˋ（四聲）＝蔚藍、蔚為風氣、蔚然成風；ㄩˋ（四聲）＝用作姓氏時。誤讀ㄨㄟˇ＝與「偉」「委」相混\n2. 國字拆解與造字原因\n蔚：形聲字，「艸（艹）」＋「尉」（聲）。從艸部——本義是草木長得茂盛，引申成「盛大」（蔚為風氣＝發展成一股風氣）。「蔚藍」是形容像晴空那樣濃而亮的藍。記法：草字頭的蔚，一般用法讀ㄨㄟˋ。"},
  {"id": "p921", "grade": 5, "word": "遼闊", "target": "遼", "zhuyin": "ㄌㄧㄠˊ", "pinyin": "liáo", "wz": "ㄌㄧㄠˊ ㄎㄨㄛˋ", "wrong": [{"z": "ㄌㄧㄠˇ", "p": "liǎo"}, {"z": "ㄌㄧㄡˊ", "p": "liú"}], "note": "「遼闊」「遼遠」的「遼」讀ㄌㄧㄠˊ（二聲）。", "deep": "1. 注音比較\n遼：ㄌㄧㄠˊ（二聲）＝遼闊、遼遠、遼寧、遼朝。誤讀ㄌㄧㄠˇ＝與「了解」的了相混；誤讀ㄌㄧㄡˊ＝與「流」相混\n2. 國字拆解與造字原因\n遼：形聲字，「辵（辶）」＋「尞」（聲）。從辵部跟距離有關，本義是遠。★同聲符要分：遼（辶，遙遠）／療（疒，治療）／瞭（目，瞭望）／繚（糸，繚繞）／僚（人，同僚）。★「遼闊」是又遠又寬廣。記法：走之旁的遼讀二聲。"},
  {"id": "p922", "grade": 5, "word": "曙光", "target": "曙", "zhuyin": "ㄕㄨˋ", "pinyin": "shù", "wz": "ㄕㄨˋ ㄍㄨㄤ", "wrong": [{"z": "ㄕㄨˇ", "p": "shǔ"}, {"z": "ㄓㄨˋ", "p": "zhù"}], "note": "教育部審訂音「曙光」讀ㄕㄨˋ ㄍㄨㄤ（四聲），不是ㄕㄨˇ。", "deep": "1. 注音比較\n曙：ㄕㄨˋ（四聲）＝曙光、曙色。★很多人念成ㄕㄨˇ（三聲），但教育部《國語辭典簡編本》只收ㄕㄨˋ一音。誤讀ㄓㄨˋ＝聲母看錯\n2. 國字拆解與造字原因\n曙：形聲字，「日」＋「署」（聲）。從日部——本義是天剛亮、太陽將出未出的時候。★「曙光」引申為困境中出現的希望（看見一線曙光）。★注意聲符「署」讀ㄕㄨˇ（三聲），但「曙」讀ㄕㄨˋ（四聲），不能照聲符念。記法：日字旁的曙讀四聲。"},
  {"id": "p923", "grade": 5, "word": "皎潔", "target": "皎", "zhuyin": "ㄐㄧㄠˇ", "pinyin": "jiǎo", "wz": "ㄐㄧㄠˇ ㄐㄧㄝˊ", "wrong": [{"z": "ㄐㄧㄠ", "p": "jiāo"}, {"z": "ㄐㄧㄠˋ", "p": "jiào"}], "note": "「皎潔」的「皎」讀ㄐㄧㄠˇ（三聲）。", "deep": "1. 注音比較\n皎：ㄐㄧㄠˇ（三聲）＝皎潔、皎白、月色皎皎。誤讀ㄐㄧㄠ＝與「交」「郊」相混；誤讀ㄐㄧㄠˋ＝與「叫」「較」相混\n2. 國字拆解與造字原因\n皎：形聲字，「白」＋「交」（聲）。從白部——本義是月光明亮潔白，所以「皎潔」幾乎專門用來寫月亮。★同聲符要分：皎（白，明亮）／餃（食，水餃）／絞（糸，絞緊）／狡（犬，狡猾）／較（車，比較）。記法：白字旁的皎讀三聲。"},
  {"id": "p924", "grade": 5, "word": "璀璨", "target": "璀", "zhuyin": "ㄘㄨㄟˇ", "pinyin": "cuǐ", "wz": "ㄘㄨㄟˇ ㄘㄢˋ", "wrong": [{"z": "ㄘㄨㄟ", "p": "cuī"}, {"z": "ㄗㄨㄟˇ", "p": "zuǐ"}], "note": "「璀璨」的「璀」讀ㄘㄨㄟˇ（三聲）。", "deep": "1. 注音比較\n璀：ㄘㄨㄟˇ（三聲）＝璀璨。誤讀ㄘㄨㄟ＝少了聲調（跟「催」「摧」相混）；誤讀ㄗㄨㄟˇ＝ㄗ、ㄘ不分\n2. 國字拆解與造字原因\n璀：形聲字，「玉（王）」＋「崔」（聲）。「璨」也是王（玉）字旁——兩個字都跟美玉有關，本義是玉石光彩耀眼的樣子，引申成一切光亮奪目（璀璨的星空、璀璨的成就）。記法：王字旁的璀讀三聲ㄘㄨㄟˇ。"},
  {"id": "p925", "grade": 5, "word": "繚繞", "target": "繚", "zhuyin": "ㄌㄧㄠˊ", "pinyin": "liáo", "wz": "ㄌㄧㄠˊ ㄖㄠˋ", "wrong": [{"z": "ㄌㄧㄠˇ", "p": "liǎo"}, {"z": "ㄌㄧㄠˋ", "p": "liào"}], "note": "「繚繞」的「繚」讀ㄌㄧㄠˊ（二聲）。", "deep": "1. 注音比較\n繚：ㄌㄧㄠˊ（二聲）＝繚繞、眼花繚亂。誤讀ㄌㄧㄠˇ＝與「了」相混；誤讀ㄌㄧㄠˋ＝與「料」相混\n2. 國字拆解與造字原因\n繚：形聲字，「糸」＋「尞」（聲）。「糸」是絲線——本義是線纏繞在一起，引申成煙霧、聲音盤旋不散（雲霧繚繞、餘音繚繞）。★「眼花繚亂」是看到的東西太多太雜，眼睛跟不上。記法：糸字旁的繚讀二聲。"},
  {"id": "p926", "grade": 5, "word": "蓬勃", "target": "蓬", "zhuyin": "ㄆㄥˊ", "pinyin": "péng", "wz": "ㄆㄥˊ ㄅㄛˊ", "wrong": [{"z": "ㄆㄥ", "p": "pēng"}, {"z": "ㄈㄥˊ", "p": "féng"}], "note": "「蓬勃」「蓬鬆」的「蓬」讀ㄆㄥˊ（二聲）。", "deep": "1. 注音比較\n蓬：ㄆㄥˊ（二聲）＝蓬勃、蓬鬆、蓬頭垢面、篷車的「篷」另有其字。誤讀ㄆㄥ＝少了聲調（跟「澎」相混）；誤讀ㄈㄥˊ＝聲母看錯\n2. 國字拆解與造字原因\n蓬：形聲字，「艸（艹）」＋「逢」（聲）。從艸部——「蓬」本來是一種草，果實成熟後隨風亂滾，所以「蓬」引申出「散亂」（蓬頭垢面）和「旺盛」（蓬勃）兩個意思。★分辨：蓬（艹，草、旺盛）／篷（竹，帳篷、船篷）。記法：草字頭的蓬讀二聲。"},
  {"id": "p927", "grade": 5, "word": "巍峨", "target": "巍", "zhuyin": "ㄨㄟˊ", "pinyin": "wéi", "wz": "ㄨㄟˊ ㄜˊ", "wrong": [{"z": "ㄨㄟˋ", "p": "wèi"}, {"z": "ㄍㄨㄟˋ", "p": "guì"}], "note": "「巍峨」的「巍」讀ㄨㄟˊ（二聲）。", "deep": "1. 注音比較\n巍：ㄨㄟˊ（二聲）＝巍峨、巍然、巍巍。誤讀ㄨㄟˋ＝把下面的「魏」直接讀出來；誤讀ㄍㄨㄟˋ＝聲母看錯\n2. 國字拆解與造字原因\n巍：形聲字，「山」＋「魏」（聲）。從山部——本義是山又高又大。「峨」也是山字旁（四川峨嵋山）。「巍峨」形容山或建築高大雄偉。★注意聲符「魏」讀ㄨㄟˋ（四聲），「巍」讀ㄨㄟˊ（二聲）。記法：山字頭的巍讀二聲。"},
  {"id": "p928", "grade": 5, "word": "嶙峋", "target": "嶙", "zhuyin": "ㄌㄧㄣˊ", "pinyin": "lín", "wz": "ㄌㄧㄣˊ ㄒㄩㄣˊ", "wrong": [{"z": "ㄌㄧㄣˇ", "p": "lǐn"}, {"z": "ㄌㄧㄥˊ", "p": "líng"}], "note": "「嶙峋」的「嶙」讀ㄌㄧㄣˊ（二聲）。", "deep": "1. 注音比較\n嶙：ㄌㄧㄣˊ（二聲）＝嶙峋、瘦骨嶙峋。誤讀ㄌㄧㄣˇ＝與「凜」相混；誤讀ㄌㄧㄥˊ＝ㄣ、ㄥ不分\n2. 國字拆解與造字原因\n嶙：形聲字，「山」＋「粦」（聲）。「峋」也是山字旁——兩個字都跟山有關，本義是山石一稜一稜、凹凸不平。★「瘦骨嶙峋」是說人瘦到骨頭像山稜一樣一根根凸出來。記法：山字旁的嶙讀二聲，注意是ㄣ不是ㄥ。"},
  {"id": "p929", "grade": 5, "word": "浩瀚", "target": "瀚", "zhuyin": "ㄏㄢˋ", "pinyin": "hàn", "wz": "ㄏㄠˋ ㄏㄢˋ", "wrong": [{"z": "ㄏㄢˊ", "p": "hán"}, {"z": "ㄨㄟˋ", "p": "wèi"}], "note": "「浩瀚」的「瀚」讀ㄏㄢˋ（四聲）。", "deep": "1. 注音比較\n瀚：ㄏㄢˋ（四聲）＝浩瀚、瀚海。誤讀ㄏㄢˊ＝與「含」「寒」相混；誤讀ㄨㄟˋ＝把右邊的「翰」看錯\n2. 國字拆解與造字原因\n瀚：形聲字，「水（氵）」＋「翰」（聲）。「浩」也是三點水——本義都是水勢盛大，「浩瀚」形容水面廣闊無邊，引申成數量極大（浩瀚的宇宙、浩瀚的書海）。★「瀚海」在古書中指沙漠。記法：三點水的瀚讀四聲。"},
  {"id": "p930", "grade": 5, "word": "漩渦", "target": "漩", "zhuyin": "ㄒㄩㄢˊ", "pinyin": "xuán", "wz": "ㄒㄩㄢˊ ㄨㄛ", "wrong": [{"z": "ㄒㄩㄢˋ", "p": "xuàn"}, {"z": "ㄒㄩㄢˇ", "p": "xuǎn"}], "note": "「漩渦」的「漩」讀ㄒㄩㄢˊ（二聲）。", "deep": "1. 注音比較\n漩：ㄒㄩㄢˊ（二聲）＝漩渦。誤讀ㄒㄩㄢˋ＝與「炫」「絢」相混；誤讀ㄒㄩㄢˇ＝與「選」相混\n2. 國字拆解與造字原因\n漩：形聲字，「水（氵）」＋「旋」（聲）。「渦」也是三點水——水旋轉著往下捲，就是漩渦。★「捲入漩渦」常用來比喻被牽扯進複雜的事件裡。★注意「渦」讀ㄨㄛ（一聲），不是ㄍㄨㄛ。記法：三點水的漩讀二聲。"},
  {"id": "p931", "grade": 5, "word": "沸騰", "target": "沸", "zhuyin": "ㄈㄟˋ", "pinyin": "fèi", "wz": "ㄈㄟˋ ㄊㄥˊ", "wrong": [{"z": "ㄈㄨˊ", "p": "fú"}, {"z": "ㄈㄟ", "p": "fēi"}], "note": "「沸騰」「沸點」的「沸」讀ㄈㄟˋ（四聲）。", "deep": "1. 注音比較\n沸：ㄈㄟˋ（四聲）＝沸騰、沸點、人聲鼎沸。誤讀ㄈㄨˊ＝把右邊的「弗」直接讀出來；誤讀ㄈㄟ＝少了聲調（跟「飛」相混）\n2. 國字拆解與造字原因\n沸：形聲字，「水（氵）」＋「弗」（聲）。從水部——本義是水滾開、翻騰。★水的沸點在標準大氣壓下是攝氏 100 度，但氣壓越低沸點越低，所以在高山上煮水不到 100 度就滾了，飯反而不容易熟。★「人聲鼎沸」形容人聲吵雜得像鍋子滾開一樣。記法：三點水的沸讀四聲。"},
  {"id": "p932", "grade": 5, "word": "熄滅", "target": "熄", "zhuyin": "ㄒㄧˊ", "pinyin": "xí", "wz": "ㄒㄧˊ ㄇㄧㄝˋ", "wrong": [{"z": "ㄒㄧ", "p": "xī"}, {"z": "ㄒㄧˋ", "p": "xì"}], "note": "「熄滅」「熄燈」的「熄」讀ㄒㄧˊ（二聲）。", "deep": "1. 注音比較\n熄：ㄒㄧˊ（二聲）＝熄滅、熄燈、熄火。誤讀ㄒㄧ＝與「吸」「西」相混；誤讀ㄒㄧˋ＝與「戲」「係」相混\n2. 國字拆解與造字原因\n熄：形聲字，「火」＋「息」（聲）。從火部——「息」有停止的意思，火停下來就是熄滅。★同樣以「息」為聲符：熄（火，熄滅）／媳（女，媳婦）／瘜（疒）。★燃燒需要三個條件：可燃物、助燃的氧氣、達到燃點的溫度；滅火就是拿掉其中一個。記法：火字旁的熄讀二聲。"},
  {"id": "p933", "grade": 5, "word": "燦爛", "target": "燦", "zhuyin": "ㄘㄢˋ", "pinyin": "càn", "wz": "ㄘㄢˋ ㄌㄢˋ", "wrong": [{"z": "ㄘㄢ", "p": "cān"}, {"z": "ㄗㄢˋ", "p": "zàn"}], "note": "「燦爛」的「燦」讀ㄘㄢˋ（四聲）。", "deep": "1. 注音比較\n燦：ㄘㄢˋ（四聲）＝燦爛、燦然、金光燦燦。誤讀ㄘㄢ＝與「餐」相混；誤讀ㄗㄢˋ＝ㄗ、ㄘ不分（跟「讚」相混）\n2. 國字拆解與造字原因\n燦：形聲字，「火」＋「粲」（聲）。從火部——本義是像火光一樣明亮鮮明。「爛」也是火字旁，在「燦爛」裡取的是「光亮」的意思，不是「腐爛」。★「笑容燦爛」是說笑得像陽光一樣明亮。記法：火字旁的燦讀四聲。"},
  {"id": "p934", "grade": 5, "word": "綿延", "target": "延", "zhuyin": "ㄧㄢˊ", "pinyin": "yán", "wz": "ㄇㄧㄢˊ ㄧㄢˊ", "wrong": [{"z": "ㄧㄢˇ", "p": "yǎn"}, {"z": "ㄊㄧㄥˊ", "p": "tíng"}], "note": "「綿延」「延長」的「延」讀ㄧㄢˊ（二聲）。", "deep": "1. 注音比較\n延：ㄧㄢˊ（二聲）＝綿延、延長、延續、延期、延誤。誤讀ㄧㄢˇ＝與「演」「眼」相混；誤讀ㄊㄧㄥˊ＝與長得像的「廷」相混\n2. 國字拆解與造字原因\n延：會意字，從「廴」（ㄧㄣˇ，長行），本義是長長地伸展。「綿」是絲棉，連續不斷；「綿延」就是連續不斷地伸展（山脈綿延數百公里）。★注意「延」（廴部，六畫底）和「廷」（朝廷）字形相近。記法：延讀二聲ㄧㄢˊ。"},
  {"id": "p935", "grade": 6, "word": "大腹便便", "target": "便", "zhuyin": "ㄆㄧㄢˊ", "pinyin": "pián", "wz": "ㄉㄚˋ ㄈㄨˋ ㄆㄧㄢˊ ㄆㄧㄢˊ", "wrong": [{"z": "ㄅㄧㄢˋ", "p": "biàn"}, {"z": "ㄅㄧㄢ", "p": "biān"}], "note": "「大腹便便」的「便便」讀ㄆㄧㄢˊ ㄆㄧㄢˊ，不讀ㄅㄧㄢˋ。", "deep": "1. 注音比較\n便：ㄆㄧㄢˊ（二聲）＝便宜、大腹便便（肥胖的樣子）；ㄅㄧㄢˋ（四聲）＝方便、便當、便利、大便\n2. 國字拆解與造字原因\n便：會意字，「人」＋「更」（改變）。把不順手的事情改一改就順了，所以本義是方便（ㄅㄧㄢˋ）。★讀ㄆㄧㄢˊ的用法有兩個：「便宜」（價錢低）和「便便」（肚子肥大的樣子）。「大腹便便」形容人肚子很大，常帶調侃意味。記法：便宜、便便讀ㄆㄧㄢˊ，其餘讀ㄅㄧㄢˋ。"},
  {"id": "p936", "grade": 6, "word": "一模一樣", "target": "模", "zhuyin": "ㄇㄛˊ", "pinyin": "mó", "wz": "ㄧ ㄇㄛˊ ㄧ ㄧㄤˋ", "wrong": [{"z": "ㄇㄨˊ", "p": "mú"}, {"z": "ㄇㄛˋ", "p": "mò"}], "note": "教育部審訂音「一模一樣」讀ㄇㄛˊ；「模樣」「模子」才讀ㄇㄨˊ。", "deep": "1. 注音比較\n模：ㄇㄛˊ（二聲）＝一模一樣、模型、模仿、模範、規模；ㄇㄨˊ（二聲）＝模樣、模子、一個模子印出來的。★「一模一樣」常被念成ㄇㄨˊ，教育部《國語辭典簡編本》收的是ㄧ ㄇㄛˊ ㄧ ㄧㄤˋ\n2. 國字拆解與造字原因\n模：形聲字，「木」＋「莫」（聲）。古人用木頭做樣板照著複製，本義是樣板、標準。★讀ㄇㄨˊ的只有「模樣」「模子」這類口語詞，數量很少。記法：除了模樣、模子，一律讀ㄇㄛˊ。"},
  {"id": "p937", "grade": 6, "word": "濟弱扶傾", "target": "濟", "zhuyin": "ㄐㄧˋ", "pinyin": "jì", "wz": "ㄐㄧˋ ㄖㄨㄛˋ ㄈㄨˊ ㄑㄧㄥ", "wrong": [{"z": "ㄐㄧˇ", "p": "jǐ"}, {"z": "ㄑㄧˊ", "p": "qí"}], "note": "「濟弱扶傾」「救濟」讀ㄐㄧˋ；「濟濟一堂」讀ㄐㄧˇ。", "deep": "1. 注音比較\n濟：ㄐㄧˋ（四聲）＝濟弱扶傾、救濟、接濟、同舟共濟、無濟於事（幫助、渡過）；ㄐㄧˇ（三聲）＝濟濟一堂、人才濟濟（形容眾多）\n2. 國字拆解與造字原因\n濟：形聲字，「水（氵）」＋「齊」（聲）。本義是渡河——大家一起渡河要互相幫忙，所以引申成「救助」（ㄐㄧˋ）。★「濟弱扶傾」是幫助弱小、扶持將倒的；「無濟於事」是對事情沒有幫助。記法：幫助讀四聲、眾多讀三聲。"},
  {"id": "p938", "grade": 6, "word": "荷花", "target": "荷", "zhuyin": "ㄏㄜˊ", "pinyin": "hé", "wz": "ㄏㄜˊ ㄏㄨㄚ", "wrong": [{"z": "ㄏㄜˋ", "p": "hè"}, {"z": "ㄏㄨㄛˊ", "p": "huó"}], "note": "植物「荷花」「荷葉」讀ㄏㄜˊ；「負荷」「荷槍實彈」「薄荷」讀ㄏㄜˋ。", "deep": "1. 注音比較\n荷：ㄏㄜˊ（二聲）＝荷花、荷葉、荷塘（植物）；ㄏㄜˋ（四聲）＝負荷、荷槍實彈、電荷、薄荷（扛、擔負）\n2. 國字拆解與造字原因\n荷：形聲字，「艸（艹）」＋「何」（聲）。本義是蓮這種植物（ㄏㄜˊ）。荷葉像一片托著東西的圓盤，引申成「用肩扛著」，讀ㄏㄜˋ——「負荷」就是擔子。★「荷花」也叫蓮花，果實是蓮子、地下莖是蓮藕。記法：植物二聲、扛東西四聲。"},
  {"id": "p939", "grade": 6, "word": "沉著", "target": "著", "zhuyin": "ㄓㄨㄛˊ", "pinyin": "zhuó", "wz": "ㄔㄣˊ ㄓㄨㄛˊ", "wrong": [{"z": "ㄓㄠˊ", "p": "zháo"}, {"z": "ㄓㄨˋ", "p": "zhù"}], "note": "「沉著」「著陸」讀ㄓㄨㄛˊ；「著急」讀ㄓㄠ、「睡著」讀ㄓㄠˊ、「著作」讀ㄓㄨˋ。", "deep": "1. 注音比較\n著：ㄓㄨㄛˊ（二聲）＝沉著、著陸、著色、穿著、不著邊際（接觸、附上）；ㄓㄠ（一聲）＝著急、著涼；ㄓㄠˊ（二聲）＝睡著、找著；ㄓㄨˋ（四聲）＝著作、名著、顯著；˙ㄓㄜ＝隨著、慢著\n2. 國字拆解與造字原因\n著：從艸、者聲。本義是顯明、寫定（ㄓㄨˋ）；引申為接觸、附上（ㄓㄨㄛˊ）——心思穩穩地附著不浮動，就是「沉著」。★一字五音，只能靠詞分辨，是國語裡讀音最多的字之一。記法：接觸、附上讀ㄓㄨㄛˊ。"},
  {"id": "p940", "grade": 6, "word": "勁敵", "target": "勁", "zhuyin": "ㄐㄧㄥˋ", "pinyin": "jìng", "wz": "ㄐㄧㄥˋ ㄉㄧˊ", "wrong": [{"z": "ㄐㄧㄣˋ", "p": "jìn"}, {"z": "ㄐㄧㄥ", "p": "jīng"}], "note": "「勁敵」「強勁」讀ㄐㄧㄥˋ；口語「使勁」「有勁」也是同一個字，教育部只收ㄐㄧㄥˋ一音。", "deep": "1. 注音比較\n勁：ㄐㄧㄥˋ（四聲）＝勁敵、強勁、勁草、幹勁、使勁。★教育部《國語辭典簡編本》「勁」只收ㄐㄧㄥˋ；坊間念的ㄐㄧㄣˋ（有勁兒）不是審訂音。誤讀ㄐㄧㄥ＝少了聲調\n2. 國字拆解與造字原因\n勁：形聲字，「力」＋「巠」（聲）。從力部——本義是力量強大。★「疾風知勁草」是說風大了才看得出哪些草夠強韌，比喻在危難中才看得出誰真堅強。記法：勁讀ㄐㄧㄥˋ，是ㄥ不是ㄣ。"},
  {"id": "p941", "grade": 6, "word": "剝奪", "target": "剝", "zhuyin": "ㄅㄛ", "pinyin": "bō", "wz": "ㄅㄛ ㄉㄨㄛˊ", "wrong": [{"z": "ㄅㄠ", "p": "bāo"}, {"z": "ㄅㄛˊ", "p": "bó"}], "note": "教育部審訂音「剝」只讀ㄅㄛ（一聲），「剝奪」「剝皮」都念ㄅㄛ。", "deep": "1. 注音比較\n剝：ㄅㄛ（一聲）＝剝奪、剝皮、剝削、生吞活剝。★很多人把「剝皮」念成ㄅㄠ，但教育部《國語辭典簡編本》只收ㄅㄛ一音。誤讀ㄅㄛˊ＝與「薄」「泊」相混\n2. 國字拆解與造字原因\n剝：會意兼形聲，右邊是「刂」（刀），本義是用刀把外皮去掉。引申成強行奪走——「剝奪」就是硬把別人的權利拿掉。★「剝削」（ㄅㄛ ㄒㄩㄝˋ）是用不正當手段占別人的勞力或財物。記法：剝一律讀ㄅㄛ。"},
  {"id": "p942", "grade": 6, "word": "脈搏", "target": "脈", "zhuyin": "ㄇㄞˋ", "pinyin": "mài", "wz": "ㄇㄞˋ ㄅㄛˊ", "wrong": [{"z": "ㄇㄛˋ", "p": "mò"}, {"z": "ㄇㄞˇ", "p": "mǎi"}], "note": "「脈搏」「山脈」讀ㄇㄞˋ；「脈脈含情」讀ㄇㄛˋ。", "deep": "1. 注音比較\n脈：ㄇㄞˋ（四聲）＝脈搏、山脈、血脈、一脈相承；ㄇㄛˋ（四聲）＝脈脈（默默用眼神表達的樣子，如「脈脈含情」）。誤讀ㄇㄞˇ＝與「買」相混\n2. 國字拆解與造字原因\n脈：會意字，「肉（月）」＋「𠂢」（水分流的樣子），本義是血管——血在身體裡像水分流一樣走。所以山勢連綿也叫「山脈」。★「搏」讀ㄅㄛˊ，是跳動；「脈搏」就是血管的跳動。★注意「搏」（提手旁，搏鬥）和「博」（十字旁，博學）不同。記法：脈一般讀ㄇㄞˋ。"},
  {"id": "p943", "grade": 6, "word": "綽號", "target": "綽", "zhuyin": "ㄔㄨㄛˋ", "pinyin": "chuò", "wz": "ㄔㄨㄛˋ ㄏㄠˋ", "wrong": [{"z": "ㄓㄨㄛˊ", "p": "zhuó"}, {"z": "ㄔㄠˋ", "p": "chào"}], "note": "「綽號」「綽綽有餘」的「綽」讀ㄔㄨㄛˋ（四聲）。", "deep": "1. 注音比較\n綽：ㄔㄨㄛˋ（四聲）＝綽號、綽綽有餘、綽約多姿。誤讀ㄓㄨㄛˊ＝與「琢」「拙」相混；誤讀ㄔㄠˋ＝韻母看錯\n2. 國字拆解與造字原因\n綽：形聲字，「糸」＋「卓」（聲）。本義是寬綽有餘。★「綽綽有餘」是說很寬裕、還多出不少。★「綽號」是別人依照一個人的特徵取的稱呼，也叫外號、渾號。記法：糸字旁的綽讀四聲ㄔㄨㄛˋ。"},
  {"id": "p944", "grade": 6, "word": "忌憚", "target": "憚", "zhuyin": "ㄉㄢˋ", "pinyin": "dàn", "wz": "ㄐㄧˋ ㄉㄢˋ", "wrong": [{"z": "ㄉㄢ", "p": "dān"}, {"z": "ㄔㄢˊ", "p": "chán"}], "note": "「肆無忌憚」的「憚」讀ㄉㄢˋ（四聲）。", "deep": "1. 注音比較\n憚：ㄉㄢˋ（四聲）＝忌憚、肆無忌憚、不憚其煩。誤讀ㄉㄢ＝與「擔心」的擔相混；誤讀ㄔㄢˊ＝把右邊的「單」看成「禪」\n2. 國字拆解與造字原因\n憚：形聲字，「心（忄）」＋「單」（聲）。從心部——本義是心裡害怕、有顧忌。★「肆無忌憚」是說放肆到毫無顧忌；「不憚其煩」是不怕麻煩，跟「不厭其煩」意思相近。記法：豎心旁的憚讀四聲。"},
  {"id": "p945", "grade": 6, "word": "悼念", "target": "悼", "zhuyin": "ㄉㄠˋ", "pinyin": "dào", "wz": "ㄉㄠˋ ㄋㄧㄢˋ", "wrong": [{"z": "ㄉㄠˇ", "p": "dǎo"}, {"z": "ㄓㄨㄛˊ", "p": "zhuó"}], "note": "「悼念」「追悼」的「悼」讀ㄉㄠˋ（四聲）。", "deep": "1. 注音比較\n悼：ㄉㄠˋ（四聲）＝悼念、追悼、哀悼。誤讀ㄉㄠˇ＝與「導」「島」相混；誤讀ㄓㄨㄛˊ＝把右邊的「卓」直接讀出來\n2. 國字拆解與造字原因\n悼：形聲字，「心（忄）」＋「卓」（聲）。從心部——本義是因為傷心而懷念，專門用在對過世的人。★「悼」（豎心旁，哀悼）和「掉」（提手旁，掉落）、「卓」（卓越）要分清楚。記法：豎心旁的悼讀四聲。"},
  {"id": "p946", "grade": 6, "word": "緬懷", "target": "緬", "zhuyin": "ㄇㄧㄢˇ", "pinyin": "miǎn", "wz": "ㄇㄧㄢˇ ㄏㄨㄞˊ", "wrong": [{"z": "ㄇㄧㄢˋ", "p": "miàn"}, {"z": "ㄇㄧㄢˊ", "p": "mián"}], "note": "「緬懷」「緬甸」的「緬」讀ㄇㄧㄢˇ（三聲）。", "deep": "1. 注音比較\n緬：ㄇㄧㄢˇ（三聲）＝緬懷、緬甸、緬想。誤讀ㄇㄧㄢˋ＝與「面」相混；誤讀ㄇㄧㄢˊ＝與「棉」「綿」相混\n2. 國字拆解與造字原因\n緬：形聲字，「糸」＋「面」（聲）。本義是細絲，引申成「遙遠」——回想遙遠的往事就是「緬懷」。★分辨：緬（糸，緬懷）／棉（木，棉花）／綿（糸，絲綿、綿延）／勉（力，勉強）。記法：糸字旁的緬讀三聲。"},
  {"id": "p947", "grade": 6, "word": "淪陷", "target": "淪", "zhuyin": "ㄌㄨㄣˊ", "pinyin": "lún", "wz": "ㄌㄨㄣˊ ㄒㄧㄢˋ", "wrong": [{"z": "ㄌㄨㄣˋ", "p": "lùn"}, {"z": "ㄌㄨㄣˇ", "p": "lǔn"}], "note": "「淪陷」「沉淪」的「淪」讀ㄌㄨㄣˊ（二聲）。", "deep": "1. 注音比較\n淪：ㄌㄨㄣˊ（二聲）＝淪陷、沉淪、淪落、淪為。誤讀ㄌㄨㄣˋ＝與「論」的四聲相混；誤讀ㄌㄨㄣˇ＝聲調錯\n2. 國字拆解與造字原因\n淪：形聲字，「水（氵）」＋「侖」（聲）。從水部——本義是水面的小波紋，引申成「沉沒、陷落」。★「淪陷」是土地被敵人占領；「淪落」是流落到不好的境地。★同聲符：淪（水）／論（言）／倫（人，倫理）／輪（車，輪子）。記法：三點水的淪讀二聲。"},
  {"id": "p948", "grade": 6, "word": "抨擊", "target": "抨", "zhuyin": "ㄆㄥ", "pinyin": "pēng", "wz": "ㄆㄥ ㄐㄧˊ", "wrong": [{"z": "ㄆㄧㄥˊ", "p": "píng"}, {"z": "ㄅㄥ", "p": "bēng"}], "note": "「抨擊」的「抨」讀ㄆㄥ（一聲）。", "deep": "1. 注音比較\n抨：ㄆㄥ（一聲）＝抨擊。誤讀ㄆㄧㄥˊ＝把右邊的「平」直接讀出來；誤讀ㄅㄥ＝ㄅ、ㄆ不分（跟「繃」相混）\n2. 國字拆解與造字原因\n抨：形聲字，「手（扌）」＋「平」（聲）。從手部——本義是彈、擊，引申成用言論攻擊、批評。★「抨擊」和「批評」的差別：批評可以是中性的評論，「抨擊」則明顯帶有嚴厲攻擊的意味。記法：提手旁的抨讀一聲ㄆㄥ。"},
  {"id": "p949", "grade": 6, "word": "撫慰", "target": "撫", "zhuyin": "ㄈㄨˇ", "pinyin": "fǔ", "wz": "ㄈㄨˇ ㄨㄟˋ", "wrong": [{"z": "ㄨˊ", "p": "wú"}, {"z": "ㄈㄨˊ", "p": "fú"}], "note": "「撫慰」「安撫」的「撫」讀ㄈㄨˇ（三聲）。", "deep": "1. 注音比較\n撫：ㄈㄨˇ（三聲）＝撫慰、安撫、撫養、撫摸。誤讀ㄨˊ＝把右邊的「無」直接讀出來；誤讀ㄈㄨˊ＝與「扶」相混\n2. 國字拆解與造字原因\n撫：形聲字，「手（扌）」＋「無」（聲）。從手部——本義是用手輕輕拍、摸，引申成安慰、照顧（撫養）。★注意聲符「無」讀ㄨˊ，「撫」讀ㄈㄨˇ。★「撫」（安慰、輕拍）和「扶」（用手支持）都是提手旁，但意思不同。記法：提手旁的撫讀三聲。"},
  {"id": "p950", "grade": 6, "word": "憐憫", "target": "憫", "zhuyin": "ㄇㄧㄣˇ", "pinyin": "mǐn", "wz": "ㄌㄧㄢˊ ㄇㄧㄣˇ", "wrong": [{"z": "ㄇㄧㄣˊ", "p": "mín"}, {"z": "ㄇㄣˋ", "p": "mèn"}], "note": "「憐憫」的「憫」讀ㄇㄧㄣˇ（三聲）。", "deep": "1. 注音比較\n憫：ㄇㄧㄣˇ（三聲）＝憐憫、悲天憫人。誤讀ㄇㄧㄣˊ＝與「民」相混；誤讀ㄇㄣˋ＝與「悶」相混（都是豎心旁，要看清楚裡面）\n2. 國字拆解與造字原因\n憫：形聲字，「心（忄）」＋「閔」（聲）。從心部——本義是同情、哀憐。★「悲天憫人」是為時代的不幸而悲傷、為百姓的苦難而同情，形容胸懷寬大有愛心。★注意「憫」（忄＋閔）和「悶」（門裡有心）字形不同。記法：豎心旁的憫讀三聲。"},
  {"id": "p951", "grade": 6, "word": "惻隱", "target": "惻", "zhuyin": "ㄘㄜˋ", "pinyin": "cè", "wz": "ㄘㄜˋ ㄧㄣˇ", "wrong": [{"z": "ㄗㄜˊ", "p": "zé"}, {"z": "ㄔㄜˋ", "p": "chè"}], "note": "「惻隱之心」的「惻」讀ㄘㄜˋ（四聲）。", "deep": "1. 注音比較\n惻：ㄘㄜˋ（四聲）＝惻隱之心、悽惻。誤讀ㄗㄜˊ＝把右邊的「則」直接讀出來；誤讀ㄔㄜˋ＝ㄘ、ㄔ不分\n2. 國字拆解與造字原因\n惻：形聲字，「心（忄）」＋「則」（聲）。從心部——本義是悲傷、不忍。★「惻隱之心」出自《孟子》：「惻隱之心，人皆有之。」孟子舉例說，看到小孩快掉進井裡，任何人都會立刻心驚而想去救——那份不忍就是惻隱之心。★同聲符：惻（心）／側（人，旁邊）／測（水，測量）／廁（广，廁所）。記法：豎心旁的惻讀四聲。"},
  {"id": "p952", "grade": 6, "word": "悽慘", "target": "悽", "zhuyin": "ㄑㄧ", "pinyin": "qī", "wz": "ㄑㄧ ㄘㄢˇ", "wrong": [{"z": "ㄑㄧˊ", "p": "qí"}, {"z": "ㄒㄧ", "p": "xī"}], "note": "「悽慘」的「悽」讀ㄑㄧ（一聲）。", "deep": "1. 注音比較\n悽：ㄑㄧ（一聲）＝悽慘、悽涼、悽厲。誤讀ㄑㄧˊ＝與「其」「奇」相混；誤讀ㄒㄧ＝ㄑ、ㄒ不分\n2. 國字拆解與造字原因\n悽：形聲字，「心（忄）」＋「妻」（聲）。從心部表示是心裡的感受——悲傷難過。★「悽」（豎心旁，心裡悲傷）和「淒」（三點水，本指風雨寒冷，如淒風苦雨）、「棲」（木字旁，棲息）三個字聲符相同，部首不同。記法：豎心旁的悽讀一聲ㄑㄧ。"},
  {"id": "p953", "grade": 6, "word": "懊悔", "target": "懊", "zhuyin": "ㄠˋ", "pinyin": "ào", "wz": "ㄠˋ ㄏㄨㄟˇ", "wrong": [{"z": "ㄠ", "p": "āo"}, {"z": "ㄩˋ", "p": "yù"}], "note": "「懊悔」「懊惱」的「懊」讀ㄠˋ（四聲）。", "deep": "1. 注音比較\n懊：ㄠˋ（四聲）＝懊悔、懊惱、懊喪。誤讀ㄠ＝少了聲調；誤讀ㄩˋ＝把右邊的「奧」讀成「澳」以外的音\n2. 國字拆解與造字原因\n懊：形聲字，「心（忄）」＋「奧」（聲）。從心部——本義是心裡煩悶後悔。★「懊悔」和「懺悔」不同：懊悔只是自己心裡難過，懺悔則含有承認錯誤、決心改過的意思。記法：豎心旁的懊讀四聲。"},
  {"id": "p954", "grade": 6, "word": "懺悔", "target": "懺", "zhuyin": "ㄔㄢˋ", "pinyin": "chàn", "wz": "ㄔㄢˋ ㄏㄨㄟˇ", "wrong": [{"z": "ㄑㄧㄢ", "p": "qiān"}, {"z": "ㄓㄢˋ", "p": "zhàn"}], "note": "「懺悔」的「懺」讀ㄔㄢˋ（四聲）。", "deep": "1. 注音比較\n懺：ㄔㄢˋ（四聲）＝懺悔、拜懺。誤讀ㄑㄧㄢ＝把右邊的「韱」看成「纖」；誤讀ㄓㄢˋ＝ㄓ、ㄔ不分\n2. 國字拆解與造字原因\n懺：形聲字，「心（忄）」＋「韱」（聲）。★「懺」原是佛經音譯「懺摩」的簡稱（梵語 kṣama，請求原諒），後來和漢語的「悔」合成「懺悔」，是外來語和本土詞合起來的例子。記法：豎心旁的懺讀四聲ㄔㄢˋ。"},
  {"id": "p955", "grade": 6, "word": "醒悟", "target": "悟", "zhuyin": "ㄨˋ", "pinyin": "wù", "wz": "ㄒㄧㄥˇ ㄨˋ", "wrong": [{"z": "ㄨˊ", "p": "wú"}, {"z": "ㄩˋ", "p": "yù"}], "note": "「醒悟」「覺悟」的「悟」讀ㄨˋ（四聲）。", "deep": "1. 注音比較\n悟：ㄨˋ（四聲）＝醒悟、覺悟、領悟、恍然大悟、執迷不悟。誤讀ㄨˊ＝把右邊的「吾」直接讀出來；誤讀ㄩˋ＝與「遇」相混\n2. 國字拆解與造字原因\n悟：形聲字，「心（忄）」＋「吾」（聲）。從心部——本義是心裡明白過來。★「恍然大悟」是忽然一下子完全明白；「執迷不悟」是固執地錯下去不肯醒悟。★注意聲符「吾」讀ㄨˊ（二聲），「悟」讀ㄨˋ（四聲）。記法：豎心旁的悟讀四聲。"},
  {"id": "p956", "grade": 6, "word": "徹底", "target": "徹", "zhuyin": "ㄔㄜˋ", "pinyin": "chè", "wz": "ㄔㄜˋ ㄉㄧˇ", "wrong": [{"z": "ㄔㄜ", "p": "chē"}, {"z": "ㄩˋ", "p": "yù"}], "note": "「徹底」「貫徹」的「徹」讀ㄔㄜˋ（四聲）。", "deep": "1. 注音比較\n徹：ㄔㄜˋ（四聲）＝徹底、貫徹、透徹、響徹雲霄。誤讀ㄔㄜ＝與「車」相混；誤讀ㄩˋ＝把右邊的「攵」看錯\n2. 國字拆解與造字原因\n徹：會意字，從「彳」（行走），本義是通、貫穿到底。★三個形近字要分清楚：徹（彳，通到底）／撤（扌，撤退、撤除）／澈（氵，清澈）。★「響徹雲霄」是聲音大到穿透雲層。記法：彳字旁的徹讀四聲。"},
  {"id": "p957", "grade": 6, "word": "嚴謹", "target": "謹", "zhuyin": "ㄐㄧㄣˇ", "pinyin": "jǐn", "wz": "ㄧㄢˊ ㄐㄧㄣˇ", "wrong": [{"z": "ㄐㄧㄣ", "p": "jīn"}, {"z": "ㄑㄧㄣˊ", "p": "qín"}], "note": "「嚴謹」「謹慎」的「謹」讀ㄐㄧㄣˇ（三聲）。", "deep": "1. 注音比較\n謹：ㄐㄧㄣˇ（三聲）＝嚴謹、謹慎、謹記、謹言慎行。誤讀ㄐㄧㄣ＝與「今」「斤」相混；誤讀ㄑㄧㄣˊ＝與「勤」相混（兩個字右半相同）\n2. 國字拆解與造字原因\n謹：形聲字，「言」＋「堇」（聲）。從言部——本義是說話小心，引申成做事嚴密不隨便。★同聲符要分：謹（言，謹慎）／勤（力，勤勞）／僅（人，僅僅）／饉（食，饑饉）／瑾（玉，美玉）。記法：言字旁的謹讀三聲。"},
  {"id": "p958", "grade": 6, "word": "周詳", "target": "詳", "zhuyin": "ㄒㄧㄤˊ", "pinyin": "xiáng", "wz": "ㄓㄡ ㄒㄧㄤˊ", "wrong": [{"z": "ㄧㄤˊ", "p": "yáng"}, {"z": "ㄒㄧㄤˇ", "p": "xiǎng"}], "note": "「周詳」「詳細」的「詳」讀ㄒㄧㄤˊ（二聲）。", "deep": "1. 注音比較\n詳：ㄒㄧㄤˊ（二聲）＝周詳、詳細、詳情、不厭其詳。誤讀ㄧㄤˊ＝把右邊的「羊」直接讀出來；誤讀ㄒㄧㄤˇ＝與「想」「響」相混\n2. 國字拆解與造字原因\n詳：形聲字，「言」＋「羊」（聲）。從言部——本義是把話說得完整周全。★同樣以「羊」為聲符：詳（言，詳細）／祥（示，吉祥）／洋（水，海洋）／養（食，養育）——聲符相同，部首決定意思。記法：言字旁的詳讀二聲ㄒㄧㄤˊ。"},
  {"id": "p959", "grade": 6, "word": "琢磨", "target": "琢", "zhuyin": "ㄓㄨㄛˊ", "pinyin": "zhuó", "wz": "ㄓㄨㄛˊ ㄇㄛˊ", "wrong": [{"z": "ㄓㄨˊ", "p": "zhú"}, {"z": "ㄉㄨㄛˋ", "p": "duò"}], "note": "「琢磨」「雕琢」的「琢」讀ㄓㄨㄛˊ（二聲）。", "deep": "1. 注音比較\n琢：ㄓㄨㄛˊ（二聲）＝琢磨、雕琢、玉不琢不成器。誤讀ㄓㄨˊ＝與「逐」「竹」相混；誤讀ㄉㄨㄛˋ＝把右邊的「豖」看成「豕」\n2. 國字拆解與造字原因\n琢：形聲字，「玉（王）」＋「豖」（聲）。從玉部——本義是雕刻玉石。★《禮記》說「玉不琢，不成器；人不學，不知道」——玉不經過雕琢就成不了器物，人不學習就不懂道理。★「琢磨」在這裡讀ㄓㄨㄛˊ ㄇㄛˊ，指反覆思考推敲。記法：王字旁的琢讀二聲。"},
  {"id": "p960", "grade": 6, "word": "鑑賞", "target": "鑑", "zhuyin": "ㄐㄧㄢˋ", "pinyin": "jiàn", "wz": "ㄐㄧㄢˋ ㄕㄤˇ", "wrong": [{"z": "ㄐㄧㄢ", "p": "jiān"}, {"z": "ㄑㄧㄢ", "p": "qiān"}], "note": "「鑑賞」「借鑑」的「鑑」讀ㄐㄧㄢˋ（四聲）。", "deep": "1. 注音比較\n鑑：ㄐㄧㄢˋ（四聲）＝鑑賞、借鑑、鑑定、前車之鑑。誤讀ㄐㄧㄢ＝與「監」「間」的一聲相混；誤讀ㄑㄧㄢ＝聲母看錯\n2. 國字拆解與造字原因\n鑑：形聲字，「金」＋「監」（聲）。古代還沒有玻璃鏡子，是用磨亮的銅盤照人，所以「鑑」本義是鏡子——照鏡子可以看清自己，引申成「審察、可作為警惕的事」。★「前車之鑑」是前面的車翻了，後面的車該引以為戒。記法：金字旁的鑑讀四聲。"},
  {"id": "p961", "grade": 6, "word": "蒐集", "target": "蒐", "zhuyin": "ㄙㄡ", "pinyin": "sōu", "wz": "ㄙㄡ ㄐㄧˊ", "wrong": [{"z": "ㄙㄡˇ", "p": "sǒu"}, {"z": "ㄍㄨㄟˇ", "p": "guǐ"}], "note": "「蒐集」的「蒐」讀ㄙㄡ（一聲）。", "deep": "1. 注音比較\n蒐：ㄙㄡ（一聲）＝蒐集、蒐羅、蒐證。誤讀ㄙㄡˇ＝與「叟」「嫂」相混；誤讀ㄍㄨㄟˇ＝把下面的「鬼」直接讀出來\n2. 國字拆解與造字原因\n蒐：形聲字，「艸（艹）」＋「鬼」（聲）。本來是一種草的名字，後來借用為「聚集、尋找」。★「蒐集」和「搜集」都通用，但「蒐」偏重把材料聚攏起來，「搜」（提手旁）偏重四處尋找。記法：草字頭的蒐讀一聲ㄙㄡ。"},
  {"id": "p962", "grade": 6, "word": "彙整", "target": "彙", "zhuyin": "ㄏㄨㄟˋ", "pinyin": "huì", "wz": "ㄏㄨㄟˋ ㄓㄥˇ", "wrong": [{"z": "ㄏㄨㄟˊ", "p": "huí"}, {"z": "ㄨㄟˋ", "p": "wèi"}], "note": "「彙整」「詞彙」的「彙」讀ㄏㄨㄟˋ（四聲）。", "deep": "1. 注音比較\n彙：ㄏㄨㄟˋ（四聲）＝彙整、詞彙、彙報、彙編。誤讀ㄏㄨㄟˊ＝與「回」相混；誤讀ㄨㄟˋ＝聲母漏掉\n2. 國字拆解與造字原因\n彙：本義是一種刺蝟類的動物，因為牠的刺又多又密，引申成「聚集在一起的同類事物」——「詞彙」就是一種語言裡所有詞的總集合。★「彙整」是把資料歸類整理起來。記法：彙讀四聲ㄏㄨㄟˋ。"},
  {"id": "p963", "grade": 6, "word": "篩選", "target": "篩", "zhuyin": "ㄕㄞ", "pinyin": "shāi", "wz": "ㄕㄞ ㄒㄩㄢˇ", "wrong": [{"z": "ㄕ", "p": "shī"}, {"z": "ㄙㄞ", "p": "sāi"}], "note": "「篩選」「篩子」的「篩」讀ㄕㄞ（一聲）。", "deep": "1. 注音比較\n篩：ㄕㄞ（一聲）＝篩選、篩子、篩檢。誤讀ㄕ＝與「師」「溼」相混；誤讀ㄙㄞ＝ㄕ、ㄙ不分（跟「塞」「腮」相混）\n2. 國字拆解與造字原因\n篩：形聲字，「竹」＋「師」（聲）。從竹部——古代的篩子用竹片編成，網眼大小固定，把細的漏下去、粗的留下來。★引申成「經過條件挑選」（篩選人才）。記法：竹字頭的篩讀一聲ㄕㄞ。"},
  {"id": "p964", "grade": 6, "word": "詮釋", "target": "詮", "zhuyin": "ㄑㄩㄢˊ", "pinyin": "quán", "wz": "ㄑㄩㄢˊ ㄕˋ", "wrong": [{"z": "ㄑㄩㄢˇ", "p": "quǎn"}, {"z": "ㄕㄨㄢˋ", "p": "shuàn"}], "note": "「詮釋」的「詮」讀ㄑㄩㄢˊ（二聲）。", "deep": "1. 注音比較\n詮：ㄑㄩㄢˊ（二聲）＝詮釋、詮解、真詮。誤讀ㄑㄩㄢˇ＝與「犬」相混；誤讀ㄕㄨㄢˋ＝聲母看錯\n2. 國字拆解與造字原因\n詮：形聲字，「言」＋「全」（聲）。從言部——本義是把道理完整地說明白（「全」帶出「完整」的意思）。★「詮釋」比「解釋」更強調把深層意義完整說出來，也用在表演上（他把這個角色詮釋得很好）。記法：言字旁的詮讀二聲。"},
  {"id": "p965", "grade": 6, "word": "闡述", "target": "闡", "zhuyin": "ㄔㄢˇ", "pinyin": "chǎn", "wz": "ㄔㄢˇ ㄕㄨˋ", "wrong": [{"z": "ㄉㄢ", "p": "dān"}, {"z": "ㄕㄢˋ", "p": "shàn"}], "note": "「闡述」「闡明」的「闡」讀ㄔㄢˇ（三聲）。", "deep": "1. 注音比較\n闡：ㄔㄢˇ（三聲）＝闡述、闡明、闡揚、闡釋。誤讀ㄉㄢ＝把裡面的「單」直接讀出來；誤讀ㄕㄢˋ＝與「善」相混\n2. 國字拆解與造字原因\n闡：形聲字，「門」＋「單」（聲）。從門部——本義是把門打開，引申成「把道理講開、說明白」。★同樣從門部的字多半跟門或開合有關（像「開」「閉」「閒」「間」「關」）。記法：門字框的闡讀三聲。"},
  {"id": "p966", "grade": 6, "word": "涵蓋", "target": "涵", "zhuyin": "ㄏㄢˊ", "pinyin": "hán", "wz": "ㄏㄢˊ ㄍㄞˋ", "wrong": [{"z": "ㄏㄢˋ", "p": "hàn"}, {"z": "ㄒㄧㄢˊ", "p": "xián"}], "note": "「涵蓋」「內涵」的「涵」讀ㄏㄢˊ（二聲）。", "deep": "1. 注音比較\n涵：ㄏㄢˊ（二聲）＝涵蓋、內涵、涵養、涵洞。誤讀ㄏㄢˋ＝與「漢」「汗」相混；誤讀ㄒㄧㄢˊ＝聲母看錯\n2. 國字拆解與造字原因\n涵：形聲字，「水（氵）」＋「函」（聲）。從水部——本義是水包容、浸潤，引申成「包含」。★「涵養」是修養功夫，也指土地保住水分的能力（森林能涵養水源）。★注意「涵」（三點水，包含）和「函」（函件、信）不同。記法：三點水的涵讀二聲。"},
  {"id": "p967", "grade": 6, "word": "臆測", "target": "臆", "zhuyin": "ㄧˋ", "pinyin": "yì", "wz": "ㄧˋ ㄘㄜˋ", "wrong": [{"z": "ㄧˊ", "p": "yí"}, {"z": "ㄧㄡˋ", "p": "yòu"}], "note": "「臆測」「胸臆」的「臆」讀ㄧˋ（四聲）。", "deep": "1. 注音比較\n臆：ㄧˋ（四聲）＝臆測、臆想、胸臆、直抒胸臆。誤讀ㄧˊ＝與「宜」相混；誤讀ㄧㄡˋ＝把左邊的「月」看成別的\n2. 國字拆解與造字原因\n臆：形聲字，「肉（月）」＋「意」（聲）。從肉部——本義是胸口，引申成「心中的想法」。★「臆測」是只憑自己心裡猜想，沒有根據；寫作或研究時要避免。★「直抒胸臆」是直接把心裡的話說出來。記法：肉月旁的臆讀四聲。"},
  {"id": "p968", "grade": 6, "word": "揭露", "target": "揭", "zhuyin": "ㄐㄧㄝ", "pinyin": "jiē", "wz": "ㄐㄧㄝ ㄌㄨˋ", "wrong": [{"z": "ㄐㄧㄝˊ", "p": "jié"}, {"z": "ㄑㄧˋ", "p": "qì"}], "note": "「揭露」「揭曉」的「揭」讀ㄐㄧㄝ（一聲）。", "deep": "1. 注音比較\n揭：ㄐㄧㄝ（一聲）＝揭露、揭曉、揭發、揭竿而起。誤讀ㄐㄧㄝˊ＝與「結」「潔」相混；誤讀ㄑㄧˋ＝把右邊的「曷」看成「氣」\n2. 國字拆解與造字原因\n揭：形聲字，「手（扌）」＋「曷」（聲）。從手部——本義是用手把蓋著的東西掀起來，引申成「使隱藏的顯出來」（揭露真相）。★「揭竿而起」是砍下竹竿當旗子起義，比喻民眾起來反抗。記法：提手旁的揭讀一聲ㄐㄧㄝ。"},
  {"id": "p969", "grade": 6, "word": "昭示", "target": "昭", "zhuyin": "ㄓㄠ", "pinyin": "zhāo", "wz": "ㄓㄠ ㄕˋ", "wrong": [{"z": "ㄓㄠˋ", "p": "zhào"}, {"z": "ㄕㄠˋ", "p": "shào"}], "note": "「昭示」「昭告」的「昭」讀ㄓㄠ（一聲）。", "deep": "1. 注音比較\n昭：ㄓㄠ（一聲）＝昭示、昭告、昭雪、天理昭彰。誤讀ㄓㄠˋ＝與「照」「兆」相混；誤讀ㄕㄠˋ＝把右邊的「召」讀成ㄕㄠˋ\n2. 國字拆解與造字原因\n昭：形聲字，「日」＋「召」（聲）。從日部——本義是光明、清楚，引申成「明白地表示出來」。★「天理昭彰」是說天理清清楚楚，善惡終有報。★注意「昭」（日字旁，明白）和「照」（下面有火，照射）不同。記法：日字旁的昭讀一聲ㄓㄠ。"},
  {"id": "p970", "grade": 6, "word": "彰顯", "target": "彰", "zhuyin": "ㄓㄤ", "pinyin": "zhāng", "wz": "ㄓㄤ ㄒㄧㄢˇ", "wrong": [{"z": "ㄓㄤˇ", "p": "zhǎng"}, {"z": "ㄔㄤˊ", "p": "cháng"}], "note": "「彰顯」「表彰」的「彰」讀ㄓㄤ（一聲）。", "deep": "1. 注音比較\n彰：ㄓㄤ（一聲）＝彰顯、表彰、彰化、欲蓋彌彰。誤讀ㄓㄤˇ＝與「掌」「長大」的長相混；誤讀ㄔㄤˊ＝聲母看錯\n2. 國字拆解與造字原因\n彰：形聲字，「章」＋「彡」。「彡」（ㄕㄢ）是花紋、光影的樣子，凡是從彡部的字多半跟紋飾、外顯有關（像「形」「影」「彩」）——所以「彰」是明顯地表現出來。★「欲蓋彌彰」是越想遮掩反而越明顯。記法：右邊有「彡」的彰讀一聲。"},
  {"id": "p971", "grade": 6, "word": "標榜", "target": "榜", "zhuyin": "ㄅㄤˇ", "pinyin": "bǎng", "wz": "ㄅㄧㄠ ㄅㄤˇ", "wrong": [{"z": "ㄅㄤˋ", "p": "bàng"}, {"z": "ㄆㄤˊ", "p": "páng"}], "note": "「標榜」「榜樣」的「榜」讀ㄅㄤˇ（三聲）。", "deep": "1. 注音比較\n榜：ㄅㄤˇ（三聲）＝標榜、榜樣、放榜、金榜題名；ㄅㄥˋ（四聲）＝榜人（划船的人，罕用）。誤讀ㄅㄤˋ＝與「棒」相混；誤讀ㄆㄤˊ＝與「旁」相混\n2. 國字拆解與造字原因\n榜：形聲字，「木」＋「旁」（聲）。從木部——古代把考試錄取名單寫在木板上公布，那塊木板就叫「榜」，所以有「放榜、金榜題名」。★「標榜」原是把好事寫出來公布表揚，現在多帶貶義，指自吹自擂（標榜自己）。記法：木字旁的榜讀三聲。"},
  {"id": "p972", "grade": 6, "word": "佇立", "target": "佇", "zhuyin": "ㄓㄨˋ", "pinyin": "zhù", "wz": "ㄓㄨˋ ㄌㄧˋ", "wrong": [{"z": "ㄋㄧㄥˊ", "p": "níng"}, {"z": "ㄓㄨˇ", "p": "zhǔ"}], "note": "「佇立」的「佇」讀ㄓㄨˋ（四聲）。", "deep": "1. 注音比較\n佇：ㄓㄨˋ（四聲）＝佇立、佇候。誤讀ㄋㄧㄥˊ＝把右邊的「宁」看成「寧」；誤讀ㄓㄨˇ＝與「主」「煮」相混\n2. 國字拆解與造字原因\n佇：形聲字，「人（亻）」＋「宁」（ㄓㄨˋ，聲）。從人部——本義是站著不動、久立等待。★「佇立」比「站著」更有情味，多用來寫人靜靜站著出神或等待。★注意右邊是「宁」（沒有心），不是「寧」。記法：人字旁的佇讀四聲。"},
  {"id": "p973", "grade": 6, "word": "瞻仰", "target": "瞻", "zhuyin": "ㄓㄢ", "pinyin": "zhān", "wz": "ㄓㄢ ㄧㄤˇ", "wrong": [{"z": "ㄓㄢˇ", "p": "zhǎn"}, {"z": "ㄔㄢˊ", "p": "chán"}], "note": "「瞻仰」「瞻前顧後」的「瞻」讀ㄓㄢ（一聲）。", "deep": "1. 注音比較\n瞻：ㄓㄢ（一聲）＝瞻仰、瞻望、瞻前顧後、高瞻遠矚。誤讀ㄓㄢˇ＝與「展」相混；誤讀ㄔㄢˊ＝與「蟾」「詹」的變化相混\n2. 國字拆解與造字原因\n瞻：形聲字，「目」＋「詹」（聲）。從目部——本義是抬頭往遠處看。★「瞻前顧後」原指做事仔細考慮前後，後來多用來說顧慮太多不敢行動。★「高瞻遠矚」是眼光遠大。記法：目字旁的瞻讀一聲ㄓㄢ。"},
  {"id": "p974", "grade": 6, "word": "俯瞰", "target": "瞰", "zhuyin": "ㄎㄢˋ", "pinyin": "kàn", "wz": "ㄈㄨˇ ㄎㄢˋ", "wrong": [{"z": "ㄍㄢˇ", "p": "gǎn"}, {"z": "ㄎㄢ", "p": "kān"}], "note": "「俯瞰」的「瞰」讀ㄎㄢˋ（四聲）；「俯」讀ㄈㄨˇ。", "deep": "1. 注音比較\n瞰：ㄎㄢˋ（四聲）＝俯瞰、鳥瞰。誤讀ㄍㄢˇ＝把右邊的「敢」直接讀出來；誤讀ㄎㄢ＝少了聲調\n2. 國字拆解與造字原因\n瞰：形聲字，「目」＋「敢」（聲）。從目部——本義是從高處往下看。★「俯」是低頭（俯首），「仰」是抬頭；「俯瞰」就是低頭往下看，「鳥瞰」是像鳥在空中往下看。記法：目字旁的瞰讀四聲。"},
  {"id": "p975", "grade": 6, "word": "翱翔", "target": "翱", "zhuyin": "ㄠˊ", "pinyin": "áo", "wz": "ㄠˊ ㄒㄧㄤˊ", "wrong": [{"z": "ㄍㄠ", "p": "gāo"}, {"z": "ㄠˋ", "p": "ào"}], "note": "「翱翔」的「翱」讀ㄠˊ（二聲）。", "deep": "1. 注音比較\n翱：ㄠˊ（二聲）＝翱翔。誤讀ㄍㄠ＝把左邊的「皋」看成「高」；誤讀ㄠˋ＝與「奧」「傲」相混\n2. 國字拆解與造字原因\n翱：形聲字，「羽」＋「皋」（聲）。「翔」也是羽字旁——兩個字都跟飛有關。★「翱」是展翅盤旋而上，「翔」是張開翅膀不動地滑行，合起來形容自在地飛。★引申用來說人自由發揮（在知識的天空翱翔）。記法：羽字旁的翱讀二聲ㄠˊ。"},
  {"id": "p976", "grade": 6, "word": "馳騁", "target": "騁", "zhuyin": "ㄔㄥˇ", "pinyin": "chěng", "wz": "ㄔˊ ㄔㄥˇ", "wrong": [{"z": "ㄆㄧㄣˋ", "p": "pìn"}, {"z": "ㄔㄥ", "p": "chēng"}], "note": "「馳騁」的「騁」讀ㄔㄥˇ（三聲）。", "deep": "1. 注音比較\n騁：ㄔㄥˇ（三聲）＝馳騁、騁懷。誤讀ㄆㄧㄣˋ＝把右邊的「甹」看成「聘」；誤讀ㄔㄥ＝少了聲調（跟「稱」相混）\n2. 國字拆解與造字原因\n騁：形聲字，「馬」＋「甹」（聲）。「馳」也是馬字旁——兩個字都指馬跑得快。★「馳騁」引申成盡情施展（在球場上馳騁、思緒馳騁）。★注意「騁」（馬字旁，奔馳）和「聘」（耳字旁，聘請）字形相近。記法：馬字旁的騁讀三聲ㄔㄥˇ。"},
  {"id": "p977", "grade": 6, "word": "蹉跎", "target": "蹉", "zhuyin": "ㄘㄨㄛ", "pinyin": "cuō", "wz": "ㄘㄨㄛ ㄊㄨㄛˊ", "wrong": [{"z": "ㄘㄨㄛˋ", "p": "cuò"}, {"z": "ㄔㄚ", "p": "chā"}], "note": "「蹉跎歲月」的「蹉」讀ㄘㄨㄛ（一聲）。", "deep": "1. 注音比較\n蹉：ㄘㄨㄛ（一聲）＝蹉跎、蹉跌。誤讀ㄘㄨㄛˋ＝與「錯」「措」相混；誤讀ㄔㄚ＝把右邊的「差」直接讀出來\n2. 國字拆解與造字原因\n蹉：形聲字，「足（𧾷）」＋「差」（聲）。「跎」也是足字旁——本義是走路失足跌倒，引申成「時間白白過去、事情耽誤了」。★「蹉跎歲月」是說時光白白虛度，什麼也沒做成。記法：足字旁的蹉讀一聲ㄘㄨㄛ。"},
  {"id": "p978", "grade": 6, "word": "迄今", "target": "迄", "zhuyin": "ㄑㄧˋ", "pinyin": "qì", "wz": "ㄑㄧˋ ㄐㄧㄣ", "wrong": [{"z": "ㄑㄧˇ", "p": "qǐ"}, {"z": "ㄏㄨㄚˊ", "p": "huá"}], "note": "「迄今」的「迄」讀ㄑㄧˋ（四聲）。", "deep": "1. 注音比較\n迄：ㄑㄧˋ（四聲）＝迄今、迄未成功。誤讀ㄑㄧˇ＝與「乞」「起」相混；誤讀ㄏㄨㄚˊ＝與「訖」以外的字看混\n2. 國字拆解與造字原因\n迄：形聲字，「辵（辶）」＋「乞」（聲）。從辵部跟走到某處有關——本義是「到、至」。「迄今」就是到現在為止。★注意「迄」（走之旁，到）和「訖」（言字旁，完畢，如「驗訖」）不同，兩個都讀ㄑㄧˋ。記法：走之旁的迄讀四聲。"},
];
